// Dynamic array of LTE_Uplink_Sched_Req_T structures
struct ScheduledRequest {
    uint16_t UE_INDEX;
    uint32_t RNTI;
    struct SCHED_REQUEST_REL15_TAG request;
};

// Function to allocate and populate a new scheduled request
uint8_t addScheduledRequest(struct ScheduledRequest **requests, uint16_t UE_INDEX, uint32_t RNTI, struct SCHED_REQUEST_REL15_TAG *request) {
    // Check if the request is already in the array
    for (int i = 0; i < requests->size; i++) {
        if (requests[i]->UE_INDEX == UE_INDEX && requests[i]->RNTI == RNTI) {
            return 1;
        }
    }

    // Allocate a new request structure and populate it with the given data
    struct ScheduledRequest *new_request = (struct ScheduledRequest *) malloc(sizeof(struct ScheduledRequest));
    new_request->UE_INDEX = UE_INDEX;
    new_request->RNTI = RNTI;
    memcpy(&new_request->request, request, sizeof(struct SCHED_REQUEST_REL15_TAG));

    // Add the new request to the array
    requests->push_back(new_request);

    return 0;
}

// Function to lookup a scheduled request by UE_INDEX and RNTI
struct ScheduledRequest *getScheduledRequest(struct ScheduledRequest **requests, uint16_t UE_INDEX, uint32_t RNTI) {
    // Check if the request is in the array
    for (int i = 0; i < requests->size; i++) {
        if (requests[i]->UE_INDEX == UE_INDEX && requests[i]->RNTI == RNTI) {
            return requests[i];
        }
    }

    // Return NULL if the request is not found
    return NULL;
}

// Function to deallocate a scheduled request by its index in the array
void deleteScheduledRequest(struct ScheduledRequest **requests, uint16_t index) {
    // Remove the request from the array and free its memory
    struct ScheduledRequest *request = requests[index];
    free(request);

    // Shift all subsequent requests down in the array
    for (int i = index + 1; i < requests->size; i++) {
        requests[i - 1] = requests[i];
    }
}

// Function to handle external RNTI information and populate a scheduled request
uint8_t addScheduledRequestFromExternalSource(struct ScheduledRequest **requests, uint16_t UE_INDEX, uint32_t *RNTI) {
    // Check if the RNTI is valid
    if (*RNTI != 0) {
        struct SCHED_REQUEST_REL15_TAG request;

        // Populate the request structure with the external data
        memcpy(&request, *RNTI, sizeof(struct SCHED_REQUEST_REL15_TAG));

        // Add the new request to the array
        addScheduledRequest(requests, UE_INDEX, *RNTI, &request);
    } else {
        return 1;
    }

    return 0;
}

// Function to handle internal RNTI information and populate a scheduled request
uint8_t addScheduledRequestFromInternalSource(struct ScheduledRequest **requests, uint16_t UE_INDEX, uint32_t *RNTI) {
    // Check if the RNTI is valid
    if (*RNTI != 0) {
        struct SCHED_REQUEST_REL15_TAG request;

