    } else {
        return 1;
    }

    return 0;
}

// Function to handle RNTI information from both external and internal sources
uint8_t addScheduledRequestFromSources(struct ScheduledRequest **requests, uint16_t UE_INDEX, uint32_t *RNTI) {
    // Check if the RNTI is valid
    if (*RNTI != 0) {
        struct SCHED_REQUEST_REL15_TAG request;

        // Populate the request structure with the internal data
        memcpy(&request, *RNTI, sizeof(struct SCHED_REQUEST_REL15_TAG));

