// Function to handle RNTI information from both external and internal sources with error handling
uint8_t addScheduledRequestFromSourcesWithErrorHandling(struct ScheduledRequest **requests, uint16_t UE_INDEX, uint32_t *RNTI) {
    // Check if the RNTI is valid
    if (*RNTI != 0) {
