#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef struct {
    int key;
    double timestamp;
} record_t;

int initializeDataStructure(long* offsets, int* keys, record_t* records, size_t num_records) {
    if (num_records == 0) {
        // Invalid input parameter
        return -1;
    }

    // Allocate memory for the arrays
    long* offset_array = malloc(sizeof(long) * num_records);
    int* key_array = malloc(sizeof(int) * num_records);
    record_t* record_array = malloc(sizeof(record_t) * num_records);

    if (offset_array == NULL || key_array == NULL || record_array == NULL) {
        // Memory allocation failed
        free(offset_array);
        free(key_array);
        free(record_array);
        return -2;
    }

    // Initialize the arrays with random values within the specified range
    srand(time(NULL));
    for (size_t i = 0; i < num_records; ++i) {
        offset_array[i] = rand() % 1000 + 1;
        key_array[i] = rand() % 1000 + 1;
        record_array[i].key = key_array[i];
        record_array[i].timestamp = offset_array[i] / 1000.0;
    }

    // Copy the arrays to the output parameters
    memcpy(offsets, offset_array, sizeof(long) * num_records);
    memcpy(keys, key_array, sizeof(int) * num_records);
    memcpy(records, record_array, sizeof(record_t) * num_records);

    // Free the allocated memory
    free(offset_array);
    free(key_array);
    free(record_array);

    return 0;
}
