using namespace std;

// Define the structure to store the input file information
struct InputFile {
    string filename; // The name of the input file
    ifstream stream; // The file stream for reading
};

// Define the structure to store the word count information
struct WordCount {
    string word; // The word being counted
    int count; // The number of occurrences of the word
};

// Define the vector to store the input files
vector<InputFile> inputFiles;

// Define the vector to store the unique words
vector<WordCount> uniqueWords;

// Define the function to process a single file
void processFile(const string& filename) {
    // Open the file and create a new ifstream object
    ifstream fileStream(filename);

    // Check if the file is open successfully
    if (!fileStream.is_open()) {
        cout << "Error: Failed to open input file " << filename << endl;
        return;
    }

    // Read the contents of the file line by line
    string line;
    while (getline(fileStream, line)) {
        // Tokenize the line and store each word in a vector
        vector<string> words = split(line);

        // Iterate through the vector of words and count the occurrences of each word
        for (string word : words) {
            bool found = false;

            // Check if the word is already in the uniqueWords vector
            for (WordCount& wc : uniqueWords) {
                if (wc.word == word) {
                    wc.count++;
                    found = true;
                    break;
                }
            }

            // If the word is not in the uniqueWords vector, add it to the end of the vector
            if (!found) {
                WordCount newWord = {word, 1};
                uniqueWords.push_back(newWord);
            }
        }
    }
}

// Define the function to process multiple files concurrently
void processFilesConcurrently() {
    // Create a vector of threads to process each file
    vector<thread> threads;

    // Iterate through the input files and create a new thread for each file
    for (InputFile& ifile : inputFiles) {
        thread t = thread(processFile, ifile.filename);
        threads.push_back(t);
    }

    // Join all the threads to wait for their completion
    for (thread& t : threads) {
        t.join();
    }
}

// Define the function to process multiple files sequentially
void processFilesSequentially() {
    // Iterate through the input files and process each file in sequence
    for (InputFile& ifile : inputFiles) {
        processFile(ifile.filename);
    }
}

