// Define the logging levels
typedef enum {
    LOG_DEBUG,
    LOG_INFO,
    LOG_WARN,
    LOG_ERROR
} log_level_t;

// Define the logging message format
typedef struct {
    log_level_t level;
    const char* message;
} log_message_t;

// Define the logging configuration options
typedef struct {
    bool enabled; // Whether logging is enabled or not
    int rate_limit; // The maximum number of messages per second to be logged
    int burst_size; // The maximum number of messages that can be buffered before being sent to the log service
    const char* format; // The message format string (e.g. "%s %d")
} log_config_t;

// Define a thread-safe queue for storing logging messages
typedef struct {
    pthread_mutex_t mutex;
    size_t capacity;
    size_t count;
    log_message_t* buffer;
} log_queue_t;

// Initialize the logging queue
void init_log_queue(log_queue_t* queue, size_t capacity) {
    queue->mutex = PTHREAD_MUTEX_INITIALIZER;
    queue->capacity = capacity;
    queue->count = 0;
    queue->buffer = malloc(sizeof(log_message_t) * capacity);
}

// Add a logging message to the queue
void add_log_message(log_queue_t* queue, log_level_t level, const char* format, va_list args) {
    pthread_mutex_lock(&queue->mutex);
    if (queue->count < queue->capacity) {
        log_message_t* message = &(queue->buffer[queue->count]);
        message->level = level;
        vsprintf(message->message, format, args);
        queue->count++;
    }
    pthread_mutex_unlock(&queue->mutex);
}

// Log a dynamic message to the centralized log system
void log_dynamic(log_config_t* config, log_level_t level, const char* format, va_list args) {
    if (config->enabled && level >= config->min_level && level <= config->max_level) {
        // Check if the logging rate is exceeded
        int current_time = time(NULL);
        if (current_time - config->last_log_time < config->rate_limit) {
            // Buffer the message and send it to the log service when the limit is reached
            add_log_message(&config->buffer, level, format, args);
            return;
        }
        config->last_log_time = current_time;

        // Log the message immediately
        char* buffer = malloc(strlen(format) + 1024);
        vsprintf(buffer, format, args);
        log_to_service(config, level, buffer);
        free(buffer);
    }
}

