#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <openssl/aes.h>
#include <openssl/chacha.h>
#include <openssl/xchacha.h>
#include <openssl/hmac.h>

// Enumeration for different encryption algorithms
enum Algorithm {AES, ChaCha20, XChaCha20};

// Structure to represent the encryption context
typedef struct EncryptionContext {
    int algorithm; // The selected encryption algorithm
    bool stream; // Whether the encryption is in streaming mode or not
    size_t key_size; // The size of the encryption key (in bits)
    unsigned char* key; // The encryption key
    EVP_CIPHER_CTX* ctx; // The OpenSSL cipher context
} EncryptionContext;

// Function to initialize the encryption context
void init_encryption_context(EncryptionContext* ctx, int algorithm, size_t key_size, unsigned char* key) {
    if (ctx == NULL || key == NULL) {
        printf("Error: Invalid parameters for initialization\n");
        return;
    }

    // Set the encryption algorithm and key size
    ctx->algorithm = algorithm;
    ctx->key_size = key_size;

    // Allocate memory for the encryption key
    ctx->key = malloc(key_size / 8);
    if (ctx->key == NULL) {
        printf("Error: Failed to allocate memory for encryption key\n");
        return;
    }

    // Copy the encryption key into the context
    memcpy(ctx->key, key, key_size / 8);

    // Set up the OpenSSL cipher context
    ctx->ctx = EVP_CIPHER_CTX_new();
    if (ctx->ctx == NULL) {
        printf("Error: Failed to initialize OpenSSL cipher context\n");
        return;
    }
}

// Function to encrypt data using the encryption context
int encrypt(EncryptionContext* ctx, unsigned char* plaintext, size_t plaintext_len, unsigned char* ciphertext) {
    if (ctx == NULL || plaintext == NULL || ciphertext == NULL) {
        printf("Error: Invalid parameters for encryption\n");
        return -1;
    }

    // Set up the OpenSSL cipher context for encryption
    int ret = EVP_EncryptInit(ctx->ctx, ctx->algorithm, ctx->key, NULL);
    if (ret == 0) {
        printf("Error: Failed to initialize OpenSSL cipher context for encryption\n");
        return -1;
    }

    // Set the IV for encryption
    unsigned char iv[EVP_MAX_IV_LENGTH];
    ret = EVP_EncryptInit(ctx->ctx, NULL, NULL, iv);
    if (ret == 0) {
        printf("Error: Failed to set the IV for encryption\n");
        return -1;
    }

    // Encrypt the plaintext
    ret = EVP_EncryptUpdate(ctx->ctx, ciphertext, &plaintext_len, plaintext, plaintext_len);
    if (ret == 0) {
        printf("Error: Failed to encrypt the plaintext\n");
        return -1;
    }

    // Add any padding to the ciphertext
    ret = EVP_EncryptFinal(ctx->ctx, ciphertext + plaintext_len, &plaintext_len);
    if (ret == 0) {
        printf("Error: Failed to add padding to the ciphertext\n");
        return -1;
    }

    // Return the length of the encrypted data
    return plaintext_len;
}

// Function to decrypt data using the encryption context
int decrypt(EncryptionContext* ctx, unsigned char* ciphertext, size_t ciphertext_len, unsigned char* plaintext) {
    if (ctx == NULL || ciphertext == NULL || plaintext == NULL) {
        printf("Error: Invalid parameters for decryption\n");
        return -1;
    }

    // Set up the OpenSSL cipher context for decryption
    int ret = EVP_DecryptInit(ctx->ctx, ctx->algorithm, ctx->key, NULL);
    if (ret == 0) {
        printf("Error: Failed to initialize OpenSSL cipher context for decryption\n");
        return -1;
    }

    // Set the IV for decryption
    unsigned char iv[EVP_MAX_IV_LENGTH];
    ret = EVP_DecryptInit(ctx->ctx, NULL, NULL, iv);
    if (ret == 0) {
        printf("Error: Failed to set the IV for decryption\n");
        return -1;
    }

    // Decrypt the ciphertext
    ret = EVP_DecryptUpdate(ctx->ctx, plaintext, &ciphertext_len, ciphertext, ciphertext_len);
    if (ret == 0) {
        printf("Error: Failed to decrypt the ciphertext\n");
        return -1;
    }

    // Add any padding to the plaintext
    ret = EVP_DecryptFinal(ctx->ctx, plaintext + ciphertext_len, &plaintext_len);
    if (ret == 0) {
        printf("Error: Failed to add padding to the plaintext\n");
        return -1;
    }

    // Return the length of the decrypted data
    return ciphertext_len;
}

// Function to switch between different encryption algorithms and modes
int switch_algorithm(EncryptionContext* ctx, int algorithm, bool stream) {
    if (ctx == NULL || algorithm < AES || algorithm > XChaCha20) {
        printf("Error: Invalid parameters for algorithm switching\n");
        return -1;
    }

    // Check whether the new algorithm and mode are different from the current ones
    if (algorithm != ctx->algorithm || stream != ctx->stream) {
        // If so, release the current cipher context and initialize a new one
        EVP_CIPHER_CTX_free(ctx->ctx);
        ctx->ctx = NULL;
        init_encryption_context(ctx, algorithm, ctx->key_size, ctx->key);
    }

    // Update the encryption context with the new parameters
    ctx->algorithm = algorithm;
    ctx->stream = stream;

    // Return success
    return 0;
}

// Function to add HMAC-SHA256 integrity checking to the encryption context
int hmac_sha256(EncryptionContext* ctx, unsigned char* plaintext, size_t plaintext_len, unsigned char* hash) {
    if (ctx == NULL || plaintext == NULL || hash == NULL) {
        printf("Error: Invalid parameters for HMAC-SHA256\n");
        return -1;
    }

    // Set up the OpenSSL cipher context for encryption
    int ret = EVP_EncryptInit(ctx->ctx, ctx->algorithm, ctx->key, NULL);
    if (ret == 0) {
        printf("Error: Failed to initialize the HMAC-SHA256 cipher context\n");
        return -1;
    }

    // Set the IV for encryption
    unsigned char iv[EVP_MAX_IV_LENGTH];
    ret = EVP_EncryptInit(ctx->ctx, NULL, NULL, iv);
    if (ret == 0) {
        printf("Error: Failed to set the IV for HMAC-SHA256\n");
        return -1;
    }

    // Encrypt the plaintext to get the hash value
    ret = EVP_EncryptUpdate(ctx->ctx, hash, &plaintext_len, plaintext, plaintext_len);
    if (ret == 0) {
        printf("Error: Failed to encrypt the plaintext for HMAC-SHA256\n");
        return -1;
    }

    // Add any padding to the hash value
    ret = EVP_EncryptFinal(ctx->ctx, hash + plaintext_len, &plaintext_len);
    if (ret == 0) {
        printf("Error: Failed to add padding to the HMAC-SHA256 hash value\n");
        return -1;
    }

    // Return the length of the hash value
    return plaintext_len;
}
