// Define the command-line options for the encryption/decryption operation
#define OPTION_ENCRYPT 0x1
#define OPTION_DECRYPT 0x2
#define OPTION_SIGN 0x3
#define OPTION_VERIFY 0x4

// Define the cryptographic algorithm to use for encryption/decryption and signing/verification
#define ALGORITHM_AES_128_CBC 0x1
#define ALGORITHM_RSA_SHA256 0x2

// Define the key length in bytes for RSA signing/verifying
#define KEY_LEN_RSA 256

// Define the maximum input string size in bytes
#define MAX_INPUT_SIZE 1024

// Function to initialize the OpenSSL library and create a new cryptographic object
EVP_CIPHER_CTX* init_crypto(int option, int algorithm, const unsigned char* key, int keylen) {
    // Initialize the OpenSSL library if not already initialized
    OPENSSL_init_crypto(OPENSSL_INIT_LOAD_CONFIG | OPENSSL_INIT_ADD_ALL_CIPHERS | OPENSSL_INIT_ADD_ALL_DIGESTS, NULL);

    // Create a new cryptographic object based on the specified option and algorithm
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        ERR_print_errors_fp(stderr);
        return NULL;
    }

    // Set the encryption/decryption mode and padding scheme based on the option
    int mode, padding;
    switch (option) {
        case OPTION_ENCRYPT:
            mode = EVP_CIPH_CBC_MODE;
            padding = RSA_PKCS1_PADDING;
            break;
        case OPTION_DECRYPT:
            mode = EVP_CIPH_CBC_MODE;
            padding = RSA_NO_PADDING;
            break;
        case OPTION_SIGN:
            mode = EVP_CIPH_CBC_MODE;
            padding = RSA_PKCS1_PSS_PADDING;
            break;
        case OPTION_VERIFY:
            mode = EVP_CIPH_CBC_MODE;
            padding = RSA_PKCS1_OAEP_PADDING;
            break;
    }

    // Set the cipher and key length based on the algorithm
    int cipher, key_len;
    switch (algorithm) {
        case ALGORITHM_AES_128_CBC:
            cipher = EVP_aes_128_cbc();
            key_len = 16;
            break;
        case ALGORITHM_RSA_SHA256:
            cipher = EVP_sha256();
            key_len = KEY_LEN_RSA;
    }

    // Set the key and IV for encryption/decryption
    unsigned char* iv = (unsigned char*) malloc(sizeof(unsigned char) * 16);
    if (!iv) {
        ERR_print_errors_fp(stderr);
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }
    memset(iv, 0x00, 16);
    if (EVP_CipherInit_ex(ctx, cipher, NULL, key, iv, mode) != 1) {
        ERR_print_errors_fp(stderr);
        EVP_CIPHER_CTX_free(ctx);
        free(iv);
        return NULL;
    }

    // Set the padding scheme for signing/verifying
    if (EVP_CipherInit_ex(ctx, NULL, NULL, NULL, NULL, mode) != 1) {
        ERR_print_errors_fp(stderr);
        EVP_CIPHER_CTX_free(ctx);
        free(iv);
        return NULL;
    }

    // Set the key length for RSA signing/verifying
    if (EVP_CipherInit_ex(ctx, NULL, NULL, NULL, NULL, mode) != 1) {
        ERR_print_errors_fp(stderr);
        EVP_CIPHER_CTX_free(ctx);
        free(iv);
        return NULL;
    }

    // Return the initialized cryptographic object
    return ctx;
}

// Function to process a variable-length input string and perform a specified cryptographic operation using the OpenSSL library
void* process_input(const char* input, int option, int algorithm, const unsigned char* key, int keylen) {
    // Initialize the cryptographic object based on the specified option and algorithm
    EVP_CIPHER_CTX* ctx = init_crypto(option, algorithm, key, keylen);

    // Return NULL if the initialization failed
    if (!ctx) {
        return NULL;
    }

    // Set the input length and allocate memory for the output string
    int input_len = strlen(input);
    unsigned char* output = (unsigned char*) malloc(sizeof(unsigned char) * input_len + 1);
    if (!output) {
        ERR_print_errors_fp(stderr);
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Set the output length and perform the cryptographic operation
    int output_len = 0;
    if (EVP_CipherUpdate(ctx, output, &output_len, (unsigned char*) input, input_len) != 1) {
        ERR_print_errors_fp(stderr);
        EVP_CIPHER_CTX_free(ctx);
        free(output);
        return NULL;
    }

    // Return the output string
    output[output_len] = '\0';
    EVP_CIPHER_CTX_free(ctx);
    return output;
}

// Function to handle errors and print them to stderr
void handle_error() {
    ERR_print_errors_fp(stderr);
}

// Main function
int main() {
    // Initialize the OpenSSL library
    SSL_library_init();

    // Create a variable for the input string
    char* input = "Hello, World!";

    // Create variables for the option and algorithm
    int option = OPTION_ENCRYPT;
    int algorithm = ALGORITHM_AES_128_CBC;

    // Create a variable for the key and set it to all zeros
    unsigned char* key = (unsigned char*) malloc(sizeof(unsigned char) * 16);
    memset(key, 0x00, 16);

    // Call the process_input function with the input string and the option, algorithm, and key
    void* output = process_input(input, option, algorithm, key);

    // Print the output to stdout
    if (output) {
        printf("Output: %s\n", (const char*) output);
    } else {
        handle_error();
    }

    return 0;
}']

