void insertValue(std::forward_list<int>& list, int target, int value) {
    // Handle edge case where the list is empty
    if (list.empty()) {
        return;
    }

    // Find the first occurrence of the target integer in the list
    auto iter = std::find(list.begin(), list.end(), target);

    // If the target integer was not found, append the value to the end of the list
    if (iter == list.end()) {
        list.push_back(value);
        return;
    }

    // Insert the value immediately after the first occurrence of the target integer
    iter = list.insert_after(iter, value);

    // Handle edge case where the target integer appears multiple times consecutively
    if (std::distance(iter, list.end()) > 1) {
        list.erase(++iter, list.end());
    }
}
