class LoggingFramework {
private:
    // In-memory buffer for temporary storage
    std::vector<std::string> logBuffer;
    // Mutex for thread safety
    std::mutex mtx;
    // Threadsafe way to write to file
    void writeToFile(const std::string& message) {
        std::lock_guard<std::mutex> lock(mtx);
        std::ofstream ofs("log.txt", std::ios::app);
        if (ofs.is_open()) {
            ofs << message;
        } else {
            std::cerr << "Error writing to file" << std::endl;
        }
    }
public:
    // Add log entry to in-memory buffer
    void addLogEntry(const std::string& message) {
        mtx.lock();
        logBuffer.push_back(message);
        mtx.unlock();
    }
    // Flush log entries to file
    void flush() {
        for (auto it = logBuffer.begin(); it != logBuffer.end(); ++it) {
            writeToFile(*it);
        }
        logBuffer.clear();
    }
};

int main() {
    // Create a logging framework instance
    LoggingFramework logger;
    // Add some log entries to the buffer
    logger.addLogEntry("DEBUG: This is a DEBUG message");
    logger.addLogEntry("INFO: This is an INFO message");
    logger.addLogEntry("WARNING: This is a WARNING message");
    logger.addLogEntry("ERROR: This is an ERROR message");
    // Flush log entries to file
    logger.flush();
    return 0;
}
```
