using System;
using System.Collections.Generic;
using System.Data;
using System.Linq;
using System.Threading.Tasks;
using System.Transactions;
using Microsoft.EntityFrameworkCore;
using MongoDB.Driver;
using Newtonsoft.Json;

namespace InventorySync
{
    public class InventoryManager
    {
        private readonly string _connectionStringPrimaryDB;
        private readonly string _connectionStringSecondaryDB;
        private readonly List<string> _apiEndpoints;
        private readonly int _batchSize;

        public InventoryManager(string connectionStringPrimaryDB, string connectionStringSecondaryDB, List<string> apiEndpoints, int batchSize)
        {
            _connectionStringPrimaryDB = connectionStringPrimaryDB;
            _connectionStringSecondaryDB = connectionStringSecondaryDB;
            _apiEndpoints = apiEndpoints;
            _batchSize = batchSize;
        }

        public async Task<IEnumerable<string>> ProcessTransactionsAsync(List<Transaction> transactions)
        {
            var errors = new List<string>();

            using (var scope = new TransactionScope())
            {
                // Update inventory in primary SQL database
                try
                {
                    await using var dbContext = new InventoryContext(_connectionStringPrimaryDB);
                    foreach (var transaction in transactions.Take(_batchSize))
                    {
                        var inventoryItem = await dbContext.InventoryItems.FirstOrDefaultAsync(i => i.Id == transaction.ProductId);
                        if (inventoryItem != null)
                        {
                            inventoryItem.Quantity -= transaction.Quantity;
                            await dbContext.SaveChangesAsync();
                        }
                    }
                }
                catch (Exception ex)
                {
                    errors.Add($"Error updating inventory in primary database: {ex.Message}");
                }

                // Update customer balances in secondary NoSQL database
                try
                {
                    await using var mongoContext = new MongoDBContext(_connectionStringSecondaryDB);
                    foreach (var transaction in transactions.Take(_batchSize))
                    {
                        var customer = await mongoContext.Customers.Find(c => c.Id == transaction.CustomerId).FirstOrDefaultAsync();
                        if (customer != null)
                        {
                            customer.Balance += transaction.Amount;
                            await mongoContext.SaveChangesAsync();
                        }
                    }
                }
                catch (Exception ex)
                {
                    errors.Add($"Error updating customer balances in secondary database: {ex.Message}");
                }

                // Integrate with external APIs for fraud detection and payment processing
                foreach (var transaction in transactions.Take(_batchSize))
                {
                    try
                    {
                        var response = await PostTransactionToAPIAsync(transaction);
                        if (!response.Success)
                        {
                            errors.Add($"Error integrating with external API for fraud detection: {response.Message}");
                        }
                    }
                    catch (Exception ex)
                    {
                        errors.Add($"Error integrating with external API for payment processing: {ex.Message}");
                    }
                }

                // Update transaction logs in both relational and non-relational databases
                try
                {
                    await using var dbContext = new InventoryContext(_connectionStringPrimaryDB);
                    foreach (var transaction in transactions)
                    {
                        dbContext.TransactionLogs.Add(new TransactionLog { TransactionId = transaction.Id, Amount = transaction.Amount });
                        await dbContext.SaveChangesAsync();
                    }
                }
                catch (Exception ex)
                {
                    errors.Add($"Error updating transaction logs: {ex.Message}");
                }

                if (errors.Any())
                {
                    scope.Complete();
                }

                return errors;
            }
        }

        private async Task<HttpResponse> PostTransactionToAPIAsync(Transaction transaction)
        {
            var request = new HttpRequestMessage(HttpMethod.Post, _apiEndpoints[0])
            {
                Content = new StringContent(JsonConvert.SerializeObject(transaction), Encoding.UTF8, "application/json")
            };

            var response = await _httpClient.SendAsync(request);
            response.EnsureSuccessStatusCode();

            return await response.Content.ReadAsStringAsync();
        }
    }
}
```
