public MoSTState loadStateFromFile(String filePath) throws IOException {
    // Initialize the theme cache if not already initialized
    if (themeCache == null) {
        initThemeCache();
    }

    // Check if the file is still in use by any other part of the app
    if (isBitmapInUse(filePath)) {
        recycleBitmap(filePath);
    }

    // Open the file stream and read the state object from it
    try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(filePath))) {
        MoSTState state = (MoSTState) ois.readObject();

        // Check if the state is an instance of MoSTState class
        if (!(state instanceof MoSTState)) {
            return null;
        }

        // Store the state in the theme cache
        themeCache.put(filePath, state);

        // Return the state object
        return state;
    } catch (IOException | ClassNotFoundException e) {
        // Handle potential IOExceptions and ClassNotFoundExceptions by returning null
        return null;
    } finally {
        // Close the file stream to prevent resource leaks
        if (ois != null) {
            ois.close();
        }
    }
}
```
