const Module = {
  _dataStream: [],
  _fetchUrl: null,
  _fetchInterval: null,
  _processInterval: null,
  _paused: false,
  _stopped: true,

  // Initialize the module with the fetch URL and processing interval
  initialize(fetchUrl, processInterval) {
    this._fetchUrl = fetchUrl;
    this._processInterval = processInterval;
  },

  // Start the background service to fetch and validate data
  startService() {
    if (this._stopped) {
      clearTimeout(this._fetchInterval);
      clearTimeout(this._processInterval);
      this._dataStream = [];
    }
    this._stopped = false;
    this._paused = false;
    this._fetchInterval = setInterval(() => this.fetchData(), 1000);
    this._processInterval = setInterval(() => this.processData(), 2000);
  },

  // Stop the background service and send a message to the messaging system
  stopService() {
    clearTimeout(this._fetchInterval);
    clearTimeout(this._processInterval);
    this._stopped = true;
    this._paused = true;
    const data = JSON.stringify(this._dataStream, null, 2);
    // Send message to messaging system with data payload
