// Modules and dependencies
const fs = require('fs');
const path = require('path');
const util = require('util');
const { fork } = require('child_process');

// Function to modify file extensions based on filename length
function modifyFileExtensions(filename, extension) {
  // Check if the filename already has the correct extension
  if (path.extname(filename) === extension) {
    return filename;
  }

  // Get the file name without the extension
  const baseName = path.basename(filename, path.extname(filename));

  // Add the new extension to the file name
  const modifiedFilename = `${baseName}${extension}`;

  return modifiedFilename;
}

// Function to load and execute JavaScript files in sequence
function loadAndExecuteFiles(files) {
  // Create a queue of files to be loaded and executed
  const fileQueue = [];

  for (const file of files) {
    fileQueue.push(file);
  }

  // Load and execute each file in the queue
  while (fileQueue.length > 0) {
    const currentFile = fileQueue[0];

    // Check if the file exists and is compatible with the current environment
    if (!fs.existsSync(currentFile) || !isCompatible(currentFile)) {
      console.error(`${currentFile} does not exist or is not compatible with the current environment`);
      continue;
    }

    // Load the file and add it to the module cache
    const module = require(currentFile);

    // Check if the file has dependencies that need to be loaded first
    const dependencyQueue = [];

    for (const dependency of module.dependencies) {
      dependencyQueue.push(dependency);
    }

    // Load and execute each dependency in the queue
    while (dependencyQueue.length > 0) {
      const currentDependency = dependencyQueue[0];

      if (!fs.existsSync(currentDependency) || !isCompatible(currentDependency)) {
        console.error(`${currentDependency} does not exist or is not compatible with the current environment`);
        continue;
      }

      // Load the dependency and add it to the module cache
      const dependencyModule = require(currentDependency);

      // Check if there are any circular dependencies between files
      if (dependencyQueue.includes(currentFile)) {
        console.error(`Circular dependency detected: ${currentFile} depends on ${currentDependency}, which depends on ${currentFile}`);
        continue;
      }

      // Add the dependency to the module cache and execute it
      Object.defineProperty(module, currentDependency, { value: dependencyModule });
      dependencyModule.execute();

      // Remove the dependency from the queue and continue loading dependencies
      dependencyQueue.shift();
    }

    // Execute the current file
    module.execute();

    // Remove the current file from the queue and continue loading files
    fileQueue.shift();
  }
}

