use std::time;
use std::process;
use std::sync::SyncLazy;
use rustc_driver::catch_with_exit_code;
use crate::logging;

fn custom_build(config_path: &str) -> i32 {
    let start = time::Instant::now();
    let mut initial_rss = 0;
    let mut final_rss = 0;
    let mut exit_code = 0;

    // Initialize ice hook
    SyncLazy::new(|| {
        initial_rss = process::current_pid().unwrap().resident_set_size();
    });

    // Run build process
    match catch_with_exit_code(config_path, |mut driver| {
        let build_result = driver.build();
        exit_code = build_result.status;
        final_rss = process::current_pid().unwrap().resident_set_size();
    }) {
        Ok(_) => {},
        Err(err) => {
            log::error!("Error during build: {}", err);
            exit_code = 1;
        }
    }

    // Log build statistics
    let duration = start.elapsed();
    logging::log(format!("Build took {:?} seconds, initial resident set size: {}, final resident set size: {}. Exit code: {}",
                         duration, initial_rss, final_rss, exit_code));

    // Clean up ice hook
    SyncLazy::new(|| {});

    return exit_code;
}
