int custom_build(char* config_path) {
    struct timespec start;
    clock_gettime(CLOCK_MONOTONIC, &start);

    long initial_rss = 0;
    long final_rss = 0;
    int exit_code = 0;

    // Run build process
    char command[LOGGING_BUFFER_SIZE];
    snprintf(command, LOGGING_BUFFER_SIZE, "./build.sh %s", config_path);
    FILE* fp = popen(command, "r");
    if (!fp) {
        log("Error running build: %s\n", strerror(errno));
        return 1;
    }
    char buffer[LOGGING_BUFFER_SIZE];
    while (fgets(buffer, LOGGING_BUFFER_SIZE, fp)) {
        // Handle build output here
    }
    exit_code = pclose(fp);

    // Log build statistics
    struct timespec end;
    clock_gettime(CLOCK_MONOTONIC, &end);
    double duration = (double)(end.tv_sec - start.tv_sec) + (end.tv_nsec - start.tv_nsec) / 1000000000;
    initial_rss = getrusage(RUSAGE_SELF, &rusage).ru_maxrss * 1024;
    final_rss = getrusage(RUSAGE_SELF, &rusage).ru_maxrss * 1024;
    log("Build took %f seconds, initial resident set size: %ld, final resident set size: %ld. Exit code: %d\n", duration, initial_rss, final_rss, exit_code);

    return exit_code;
}
