const fetchPrivateKey = async (url) => {
  try {
    const response = await fetch(url);
    if (!response.ok) {
      throw new Error(`Network error: ${response.statusText}`);
    }
    return response.json();
  } catch (error) {
    console.error(error);
    throw error;
  }
};

const fetchCertificate = async (url) => {
  try {
    const response = await fetch(url);
    if (!response.ok) {
      throw new Error(`Network error: ${response.statusText}`);
    }
    return response.json();
  } catch (error) {
    console.error(error);
    throw error;
  }
};

const buildCertificate = async ({ privateKey, certificate }) => {
  try {
    const pem = `-----BEGIN PRIVATE KEY-----\n${privateKey}\n-----END PRIVATE KEY-----\n`;
    const cert = `-----BEGIN CERTIFICATE-----\n${certificate}\n-----END CERTIFICATE-----\n`;
    return `${pem}${cert}`;
  } catch (error) {
    console.error(error);
    throw error;
  }
};

const buildPEM = async (oauthRequest) => {
  const privateKeyUrl = oauthRequest.privateKeyUrl;
  const certificateUrl = oauthRequest.certificateUrl;

  try {
    const privateKey = await fetchPrivateKey(privateKeyUrl);
    const certificate = await fetchCertificate(certificateUrl);
    return buildCertificate({ privateKey, certificate });
  } catch (error) {
    console.error(error);
    throw error;
  }
};

const handleNetworkError = async (error) => {
  console.error(error);
  await new Promise((resolve) => setTimeout(resolve, 1000));
  return buildPEM(oauthRequest);
};

const buildPEMWithRetry = async () => {
  try {
    return buildPEM(oauthRequest);
  } catch (error) {
    return handleNetworkError(error);
  }
};

const pauseAndResumeBuffer = [];

const pauseBuffer = async (buffer, index) => {
  const bufferSize = buffer.length;
  for (let i = index; i < bufferSize; i++) {
    await new Promise((resolve) => setTimeout(resolve, 10));
    const data = buffer[i];
    if (data !== null && typeof data === "object") {
      pauseAndResumeBuffer.push(data);
    }
  }
};

const resumeBuffer = async () => {
  const bufferSize = pauseAndResumeBuffer.length;
  for (let i = 0; i < bufferSize; i++) {
    await new Promise((resolve) => setTimeout(resolve, 10));
    const data = pauseAndResumeBuffer[i];
    if (data !== null && typeof data === "object") {
      return data;
    }
  }
};

const streamData = async () => {
  try {
    const buffer = [];
    const stream = fetch(streamUrl, { mode: "cors" });
    for await (const data of stream) {
      buffer.push(data);
      if (buffer.length > 100) {
        await pauseBuffer(buffer, 50);
      }
    }
    return buffer;
  } catch (error) {
    console.error(error);
  }
};

const cache = {};

const fetchData = async () => {
  try {
    const data = await streamData();
    for (let i = 0; i < data.length; i++) {
      const element = data[i];
      if (element !== null && typeof element === "object") {
        cache[element.key] = element.value;
      }
    }
    return cache;
  } catch (error) {
    console.error(error);
  }
};

const fetchCachedData = async () => {
  try {
    const data = await streamData();
    for (let i = 0; i < data.length; i++) {
      const element = data[i];
      if (element !== null && typeof element === "object") {
        cache[element.key] = element.value;
        return cache;
      }
    }
  } catch (error) {
    console.error(error);
  }
};

const buildPEMWithCaching = async () => {
  try {
    const cachedData = await fetchCachedData();
    if (!cachedData || cachedData.length === 0) {
      return buildPEMWithRetry();
    }
    const privateKeyUrl = cachedData["privateKeyUrl"];
    const certificateUrl = cachedData["certificateUrl"];
    const privateKey = await fetchPrivateKey(privateKeyUrl);
    const certificate = await fetchCertificate(certificateUrl);
    return buildCertificate({ privateKey, certificate });
