// Structure to represent a state in the FSA
typedef struct {
    int id;
    char* name;
} State;

// Function to create a new state list from an array of states
State** create_state_list(int num_states, State* states[], State* last_state) {
    // Check if the input array is empty
    if (num_states == 0) {
        return NULL;
    }

    // Create a new state list with enough capacity to hold all states
    State** state_list = malloc(sizeof(State*) * num_states);
    if (state_list == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for state list\n");
        return NULL;
    }

    // Add the first state to the list
    state_list[0] = states[0];
    int num_unique_states = 1;

    // Iterate over the remaining states and add unique ones to the list
    for (int i = 1; i < num_states; i++) {
        State* current_state = states[i];
        bool is_duplicate = false;

        // Check if the current state is a duplicate of an existing state in the list
        for (int j = 0; j < num_unique_states && !is_duplicate; j++) {
            if (state_list[j]->id == current_state->id) {
                is_duplicate = true;
            }
        }

        // Add the current state to the list if it's not a duplicate
        if (!is_duplicate) {
            state_list[num_unique_states++] = current_state;
        }
    }

    // If the last state is not in the list, add it
    if (last_state != NULL && !is_duplicate(last_state->id)) {
        state_list[num_unique_states++] = last_state;
    }

    return state_list;
}
