using System;
using UnityEngine;

public class DynamicRangeManager
{
    // Private fields for the minimum and maximum values of the ranges, along with metadata for tracking the source of each range (e.g., application module, version)
    private Dictionary<int, Range> _ranges = new Dictionary<int, Range>();

    // Public properties to get and set these values, with validation ensuring the minimum value is less than the maximum value
    public int MinValue { get; private set; }
    public int MaxValue { get; private set; }
    public string SourceModule { get; private set; }
    public int Version { get; private set; }

    // Methods for generating random integer and float values within each range, supporting both inclusive and exclusive boundaries
    public int GetRandomIntInRange(int index) => UnityEngine.Random.Range(_ranges[index].MinValue, _ranges[index].MaxValue);
    public int GetRandomIntOutOfRange(int index) => UnityEngine.Random.Range(_ranges[index].MinValue + 1, _ranges[index].MaxValue - 1);
    public float GetRandomFloatInRange(int index) => UnityEngine.Random.Range(_ranges[index].MinValue, _ranges[index].MaxValue);
    public float GetRandomFloatOutOfRange(int index) => UnityEngine.Random.Range(_ranges[index].MinValue + 1, _ranges[index].MaxValue - 1);

    // Method to add a new range with specified boundaries, ensuring no overlap with existing ranges
    public void AddRange(int minValue, int maxValue, string sourceModule = "", int version = 0)
    {
        if (minValue > maxValue)
            throw new ArgumentException("Minimum value cannot be greater than maximum value");

        // Handle potential race conditions in a multi-threaded environment to prevent concurrent modifications from causing conflicts
        lock (_ranges)
        {
            foreach (var range in _ranges.Values)
            {
                if (range.MinValue == minValue || range.MaxValue == maxValue)
                    throw new ArgumentException("Range overlaps with existing ranges");
            }

            _ranges[minValue] = new Range(minValue, maxValue, sourceModule, version);
        }
    }

    // Method to remove a specific range by index or identifier, ensuring that removal does not disrupt ongoing operations or lead to undefined behavior
    public void RemoveRange(int index)
    {
        if (index < 0 || index >= _ranges.Count)
            throw new ArgumentOutOfRangeException("Index is out of range");

        // Handle potential race conditions in a multi-threaded environment to prevent concurrent modifications from causing conflicts
        lock (_ranges)
        {
            var range = _ranges[index];
            foreach (var otherRange in _ranges.Values)
            {
                if (otherRange != range && otherRange.MinValue >= range.MinValue && otherRange.MaxValue <= range.MaxValue)
                    throw new InvalidOperationException("Removing this range would disrupt ongoing operations");
            }

            _ranges.RemoveAt(index);
        }
    }

    // Implement a mechanism to automatically clean up unused or redundant ranges periodically, balancing memory usage and computational overhead
    public void CleanupRanges()
    {
        lock (_ranges)
        {
            _ranges.RemoveAll(range => range.Value.IsEmpty);
        }
    }

    // Override the ToString method to display all defined ranges, including metadata, in a human-readable format
    public override string ToString()
    {
        return "DynamicRangeManager: " + _ranges.Values.Select(range => range.ToString()).Join(", ");
    }
}
```
