#define MAX_EXTENSION_LENGTH 3

// Function to validate the existence of a file
int validateFile(const char* filename) {
    struct stat buf;
    if (stat(filename, &buf) == -1) {
        return -errno;
    }
    return 0;
}

// Function to generate a dynamically generated extension for a filename
char* generateExtension(const char* filename) {
    // Calculate the length of the extension
    int ext_length = strlen(filename) - 3;
    if (ext_length > MAX_EXTENSION_LENGTH) {
        ext_length = MAX_EXTENSION_LENGTH;
    }

    // Derive the file type from the first letter of the filename
    char file_type[2] = "txt";
    if (filename[0] >= 'a' && filename[0] <= 'z') {
        file_type[0] = tolower(filename[0]);
    }

    // Generate a new filename with the updated extension
    char* new_filename = (char*)malloc((strlen(filename) + strlen(file_type) + 1) * sizeof(char));
    sprintf(new_filename, "%s.%s", filename, file_type);

    // Return the new filename with the updated extension
    return new_filename;
}

// Function to rename a file with a dynamically generated extension
int renameFileWithDynamicExtension(const char* filename) {
    if (validateFile(filename)) {
        fprintf(stderr, "Error: File does not exist\n");
        return -1;
    }

    // Generate a new filename with the updated extension
    char* new_filename = generateExtension(filename);
    if (!new_filename) {
        fprintf(stderr, "Error: Invalid input filename\n");
        return -1;
    }

    // Rename the file
    int result = rename(filename, new_filename);
    if (result == -1) {
        perror("rename");
        free(new_filename);
        return -1;
    }

    // Free memory allocated for the new filename
    free(new_filename);

    // Return 0 on success
    return 0;
}
