#include <openssl/aes.h>
#include <openssl/evp.h>
#include <stdlib.h>
#include <string.h>

void init_AES_CBC(char* password, int password_len) {
    // Allocate memory for the cipher context and key
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    unsigned char *key = (unsigned char *) malloc(AES_KEY_LEN);

    // Set the cipher type to AES-256-CBC
    EVP_CipherInit_ex(ctx, EVP_aes_256_cbc(), NULL, NULL, NULL, 1);

    // Generate a random key for the cipher using OpenSSL's RAND function
    RAND_bytes(key, AES_KEY_LEN);

    // Set the password as the initialization vector (IV) for the cipher
    EVP_CipherInit_ex(ctx, NULL, NULL, key, NULL, 1);

    // Initialize the cipher context with the given password and key
    EVP_EncryptInit_ex(ctx, NULL, NULL, key, NULL);

    // Free the memory allocated for the key and return the cipher context
    free(key);
    return ctx;
}
```
This function initializes an AES-256-CBC cipher with a given password using OpenSSL's EVP API. It dynamically allocates memory for the cipher context and key, generates a random key using OpenSSL's RAND function, sets the password as the initialization vector (IV) for the cipher, initializes the cipher context with the given password and key, and frees the memory allocated for the key. The function returns the initialized cipher context.

The function takes two parameters:

* `password`: a string representing the password to be used as the IV for the AES-256-CBC cipher.
* `password_len`: an integer representing the length of the password in bytes.

