    int port_number;
    int max_connections;
    char *server_name;
    char log_level[10];
} Config;

int parse_config(Config *config) {
    // Read the JSON configuration file
    json_object *root = json_object_from_file(CONFIG_FILE);
    if (!root) {
        fprintf(stderr, "Failed to read configuration file: %s\n", strerror(errno));
        return 0;
    }

    // Validate the presence of essential parameters
    json_object *port_number_obj = json_object_object_get(root, "port_number");
    if (!json_object_is_type(port_number_obj, json_type_int)) {
        fprintf(stderr, "Invalid 'port_number' type: expected integer\n");
        return 0;
    }
    config->port_number = json_object_get_int(port_number_obj);

    json_object *max_connections_obj = json_object_object_get(root, "max_connections");
    if (!json_object_is_type(max_connections_obj, json_type_int)) {
        fprintf(stderr, "Invalid 'max_connections' type: expected integer\n");
        return 0;
    }
    config->max_connections = json_object_get_int(max_connections_obj);

    json_object *server_name_obj = json_object_object_get(root, "server_name");
    if (!json_object_is_type(server_name_obj, json_type_string)) {
        fprintf(stderr, "Invalid 'server_name' type: expected string\n");
        return 0;
    }
    config->server_name = strdup(json_object_get_string(server_name_obj));

    json_object *log_level_obj = json_object_object_get(root, "log_level");
    if (!json_object_is_type(log_level_obj, json_type_string)) {
        fprintf(stderr, "Invalid 'log_level' type: expected string\n");
        return 0;
    }
    const char *log_level = json_object_get_string(log_level_obj);
    if (!strcmp(log_level, LOG_LEVELS)) {
        fprintf(stderr, "Invalid 'log_level' value: expected one of '%s'\n", LOG_LEVELS);
        return 0;
    }
    strcpy(config->log_level, log_level);

    // Validate the port number range (1-65535)
    if (config->port_number < 1 || config->port_number > MAX_PORT_NUMBER) {
        fprintf(stderr, "Invalid 'port_number' value: expected integer between 1 and %d\n", MAX_PORT_NUMBER);
        return 0;
    }

    // Validate the max connections value
    if (config->max_connections < 0) {
        fprintf(stderr, "Invalid 'max_connections' value: expected positive integer\n");
        return 0;
    }

    // Validate the server name is a non-empty string
    if (!*config->server_name) {
        fprintf(stderr, "Invalid 'server_name' value: expected non-empty string\n");
        return 0;
    }

    json_object_put(root);

    return 1;
}

int main() {
    Config config;

    // Parse the JSON configuration file
    if (!parse_config(&config)) {
        fprintf(stderr, "Failed to parse configuration file\n");
        return 1;
    }

    // Print the parsed configuration parameters
    printf("Server name: %s\n", config.server_name);
    printf("Port number: %d\n", config.port_number);
    printf("Max connections: %d\n", config.max_connections);
    printf("Log level: %s\n", config.log_level);

    return 0;
}
