```javascript
function traverseDOM(rootNode, selector) {
  // Create a stack to store nodes to be processed
  const nodeStack = [rootNode];

  // Create a list to store matching elements
  const elementList = [];

  // Recursively traverse the DOM tree starting from the root node
  while (nodeStack.length > 0) {
    // Pop the top node from the stack and process it
    const currentNode = nodeStack.pop();

    // Test the current node against the selector
    if (currentNode.matches(selector)) {
      elementList.push(currentNode);
    }

    // Push the child nodes of the current node onto the stack for processing
    const childrenNodes = currentNode.childNodes;
    for (let i = 0; i < childrenNodes.length; i++) {
      nodeStack.push(childrenNodes[i]);
    }
  }

  // Return the list of matching elements
  return elementList;
}
