public static string DecipherMessage(string encodedMessage, string key, string iv)
{
    // Validate inputs
    if (string.IsNullOrEmpty(encodedMessage))
        return "";
    if (!key.Length == 24 || !iv.Length == 24)
        return "";

    try
    {
        // Decode the Base64-encoded message
        byte[] encodedBytes = Convert.FromBase64String(encodedMessage);

        // Create a new instance of the Triple DES algorithm
        using (TripleDESCryptoServiceProvider des = new TripleDESCryptoServiceProvider())
        {
            // Set the key and IV for the algorithm
            des.Key = Encoding.UTF8.GetBytes(key);
            des.IV = Encoding.UTF8.GetBytes(iv);

            // Create a decryptor to perform the actual decryption
            using (ICryptoTransform decryptor = des.CreateDecryptor())
            {
                // Decrypt the encoded message
                byte[] decryptedBytes = decryptor.TransformFinalBlock(encodedBytes, 0, encodedBytes.Length);

                // Verify that the resulting message is a valid UTF-8 string
                if (Encoding.UTF8.GetString(decryptedBytes) == "")
                    return "";

                // Return the decrypted message as a string
                return Encoding.UTF8.GetString(decryptedBytes);
            }
        }
    }
    catch (Exception e)
    {
        Console.WriteLine("Error deciphering message: " + e.Message);
        return "";
    }
}
