    public static class AES_CBC
    {
        private const int KeySize = 256; // 256-bit key size
        private const int IVSize = 16; // 16-byte initialization vector
        private const PaddingMode PaddingScheme = PaddingMode.PKCS7; // Default padding scheme

        private static readonly Encoding TextEncoding = Encoding.UTF8;

        public static byte[] Decrypt(string ciphertext, string encryptionKey, string iv)
        {
            try
            {
                // Validate input parameters
                if (ciphertext == null || encryptionKey == null || iv == null)
                    throw new ArgumentException("Invalid input parameter");

                // Convert input strings to byte arrays
                byte[] cipherBytes = Convert.FromBase64String(ciphertext);
                byte[] keyBytes = TextEncoding.GetBytes(encryptionKey);
                byte[] ivBytes = TextEncoding.GetBytes(iv);

                // Validate key and IV lengths
                if (keyBytes.Length != KeySize || ivBytes.Length != IVSize)
                    throw new ArgumentException("Invalid key or IV length");

                // Create AES-CBC decryption object
                using var aes = new AesCbcDecryptor(KeySize, PaddingScheme);

                // Set key and IV for the decryption object
                aes.Key = keyBytes;
                aes.IV = ivBytes;

                // Decrypt ciphertext using AES-CBC algorithm
                byte[] plainBytes = aes.Decrypt(cipherBytes);

                // Return decrypted plaintext as byte array
                return plainBytes;
            }
            catch (Exception e)
            {
                Console.WriteLine("Decryption failed: " + e.Message);
                return null;
            }
        }
    }
}
