    public class FileLoader
    {
        private const int DEFAULT_BUFFER_SIZE = 4096;
        private const int MAX_CACHE_SIZE = 1024;
        private static readonly ConcurrentDictionary<string, byte[]> Cache = new ConcurrentDictionary<string, byte[]>();

        public async Task<object> LoadFile(string filePath, string checksum)
        {
            // Validate the file path and checksum
            if (string.IsNullOrEmpty(filePath))
                throw new ArgumentException("Invalid file path", nameof(filePath));
            if (string.IsNullOrEmpty(checksum))
                throw new ArgumentException("Invalid checksum", nameof(checksum));

            // Check the cache for a matching file
            var cachedFile = Cache.Get(filePath);
            if (cachedFile != null)
            {
                // Verify the checksum of the cached file
                var cachedChecksum = CalculateChecksum(cachedFile);
                if (cachedChecksum == checksum)
                    return Deserialize(cachedFile);
            }

            // Load the file from disk
            using (var stream = File.OpenRead(filePath))
            {
                // Determine the compression format and load the file accordingly
                var compressionFormat = GetCompressionFormat(stream);
                if (compressionFormat == CompressionFormat.GZip)
                    return await LoadGZipFileAsync(stream, checksum).ConfigureAwait(false);
                else if (compressionFormat == CompressionFormat.Deflate)
                    return await LoadDeflateFileAsync(stream, checksum).ConfigureAwait(false);
                else
                    throw new NotSupportedException($"Compression format {compressionFormat} is not supported");
            }
        }

        private async Task<object> LoadGZipFileAsync(Stream stream, string checksum)
        {
            using (var gzipStream = new GZipStream(stream, CompressionMode.Decompress))
            {
                // Read the file contents from the decompressed stream
                var buffer = new byte[DEFAULT_BUFFER_SIZE];
                int read;
                using (var memoryStream = new MemoryStream())
                {
                    while ((read = await gzipStream.ReadAsync(buffer, 0, buffer.Length).ConfigureAwait(false)) > 0)
                        memoryStream.Write(buffer, 0, read);

                    // Verify the checksum of the decompressed file contents
                    var checksum = CalculateChecksum(memoryStream.ToArray());
                    if (checksum != this.checksum)
                        throw new InvalidDataException($"Checksum mismatch for {filePath}");

                    // Deserialize the file contents
                    return Deserialize(memoryStream.ToArray());
                }
            }
        }

        private async Task<object> LoadDeflateFileAsync(Stream stream, string checksum)
        {
            using (var inflateStream = new DeflateStream(stream, CompressionMode.Decompress))
            {
                // Read the file contents from the decompressed stream
                var buffer = new byte[DEFAULT_BUFFER_SIZE];
                int read;
                using (var memoryStream = new MemoryStream())
                {
                    while ((read = await inflateStream.ReadAsync(buffer, 0, buffer.Length).ConfigureAwait(false)) > 0)
                        memoryStream.Write(buffer, 0, read);

                    // Verify the checksum of the decompressed file contents
                    var checksum = CalculateChecksum(memoryStream.ToArray());
                    if (checksum != this.checksum)
                        throw new InvalidDataException($"Checksum mismatch for {filePath}");

                    // Deserialize the file contents
                    return Deserialize(memoryStream.ToArray());
                }
            }
        }

        private object Deserialize(byte[] data)
        {
            // Implement deserialization logic here, using a third-party library if necessary
        }

        private string CalculateChecksum(byte[] data)
        {
            // Implement checksum calculation logic here
        }

        private static CompressionFormat GetCompressionFormat(Stream stream)
        {
            // Determine the compression format of the file based on its header
            var buffer = new byte[4];
            stream.Read(buffer, 0, 4);
            return (CompressionFormat)buffer[0];
        }
    }
}
