using namespace std;

struct Record {
    int key;
    double timestamp;
};

string uploadAndInitializeDataStructure(const string& url) {
    // Upload the file from the given URL using libcurl
    CURL* curl = curl_easy_init();
    if (curl) {
        CURLcode res = curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
        if (res != CURLE_OK) {
            cerr << "Failed to set URL: " << curl_easy_strerror(res) << endl;
            return "";
        }

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            cerr << "Failed to upload file: " << curl_easy_strerror(res) << endl;
            return "";
        }
    } else {
        cerr << "Failed to initialize libcurl" << endl;
        return "";
    }

    // Initialize the complex data structure using the uploaded file
    vector<size_t> offset_array;
    vector<int> key_array;
    vector<Record> record_array;

    // Read the uploaded file line by line and populate the data structures
    FILE* file = fopen(url.c_str(), "r");
    if (file == NULL) {
        cerr << "Failed to open file: " << url << endl;
        return "";
    }

    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        // Parse the current line and populate the data structures
        int key = rand() % 100; // Replace with a real random number generator
        double timestamp = (double)time(NULL); // Replace with a real time function

        offset_array.push_back(line - line[0]);
        key_array.push_back(key);
        record_array.emplace_back(key, timestamp);
    }

    fclose(file);

    // Clean up memory and return the uploaded URL
    curl_easy_cleanup(curl);
    return url;
}
```
