```c++
#include <iostream>
#include <string>
#include <boost/graph/adjacency_list.hpp>
#include <boost/graph/random_generator.hpp>
#include <boost/property_map/property_map.hpp>
#include <boost/algorithm/string.hpp>
#include <sstream>

using namespace std;
using namespace boost::graph;

struct vertex_t {
    int id;
    string label;
};

struct edge_t {
    int id;
    string label;
};

// Command-line arguments for configuring graph generation
int NUM_VERTICES = 0;
int NUM_EDGES = 0;
bool USE_RANDOM = false;
double PROBABILITY_OF_EDGES = 0.0;
string FILENAME = "";

// Graph structure
adjacency_list<vecS, vecS, bidirectionalS> graph(NUM_VERTICES);

// Function to generate random properties for vertices and edges
void generateRandomProperties() {
    // Generate a random number of vertices and edges
    if (USE_RANDOM) {
        int numVertices = rand() % NUM_VERTICES;
        int numEdges = rand() % NUM_EDGES;
        for (int i = 0; i < numVertices; i++) {
            vertex_t v(i, "");
            add_vertex(v, graph);
        }
        for (int i = 0; i < numEdges; i++) {
            edge_t e(i, "");
            add_edge(e, graph);
        }
    } else {
        // Generate a fixed number of vertices and edges
        for (int i = 0; i < NUM_VERTICES; i++) {
            vertex_t v(i, "");
            add_vertex(v, graph);
        }
        for (int i = 0; i < NUM_EDGES; i++) {
            edge_t e(i, "");
            add_edge(e, graph);
        }
    }
}

// Function to generate properties for vertices and edges based on command-line arguments
void generateProperties() {
    // Generate random properties if using random mode
    if (USE_RANDOM) {
        generateRandomProperties();
    } else {
        // Generate fixed properties if not using random mode
        for (int i = 0; i < NUM_VERTICES; i++) {
            vertex_t v(i, "");
            add_vertex(v, graph);
        }
        for (int i = 0; i < NUM_EDGES; i++) {
            edge_t e(i, "");
            add_edge(e, graph);
        }
    }
}

// Function to interact with an external service for metadata retrieval
void fetchMetadata() {
    // Implement a robust mechanism to handle potential failures in metadata fetching
    try {
        // Fetch metadata from the external service
        string response = "";
        if (FILENAME.empty()) {
            response = get_metadata_from_external_service();
        } else {
            response = read_metadata_from_file(FILENAME);
        }
        // Parse the response and set properties for vertices and edges
        parseMetadata(response);
    } catch (const exception& e) {
        // Handle any exceptions that may occur during metadata fetching
        cerr << "Error: " << e.what() << endl;
    }
}

// Function to parse the response from an external service for metadata retrieval
void parseMetadata(string response) {
    // Implement a caching strategy to minimize redundant metadata requests and improve performance
    if (response != "") {
        // Parse the response and set properties for vertices and edges
        istringstream iss(response);
        string line;
        while (getline(iss, line)) {
            vector<string> tokens = boost::split(line, " ");
            vertex_t v(tokens[0], tokens[1]);
            add_vertex(v, graph);
            for (int i = 2; i < tokens.size(); i++) {
                edge_t e(i - 2, tokens[i]);
                add_edge(e, graph);
            }
        }
    }
}

// Function to send periodic status updates to a monitoring server using Sandesh client
void sendStatusUpdates() {
    // Implement a configurable mechanism for sending periodic status updates to a monitoring server
    while (true) {
        // Send a status update to the monitoring server
        string status = "";
        if (FILENAME.empty()) {
            status = generate_status_update(graph);
        } else {
            status = read_status_from_file(FILENAME);
        }
        send_status_update(status);
        // Sleep for a configurable amount of time before sending the next update
        boost::this_thread::sleep(boost::posix_time::seconds(10));
    }
}

// Function to log detailed metrics, including the number of successful and failed operations, to assist in performance tuning and debugging
void logMetrics() {
    // Implement a mechanism for logging detailed metrics
    while (true) {
        // Log a metric for the number of successful and failed operations
        string metric = "";
        if (FILENAME.empty()) {
            metric = generate_metric(graph);
        } else {
            metric = read_metric_from_file(FILENAME);
        }
        log_metric(metric);
        // Sleep for a configurable amount of time before logging the next metric
        boost::this_thread::sleep(boost::posix_time::seconds(10));
    }
}

int main(int argc, char** argv) {
    // Parse command-line arguments to configure graph generation
    for (int i = 1; i < argc; ++i) {
        if (!strcmp(argv[i], "-v")) {
            NUM_VERTICES = atoi(argv[++i]);
        } else if (!strcmp(argv[i], "-e")) {
            NUM_EDGES = atoi(argv[++i]);
        } else if (!strcmp(argv[i], "-r")) {
            USE_RANDOM = true;
        } else if (!strcmp(argv[i], "-p")) {
            PROBABILITY_OF_EDGES = atof(argv[++i]);
        } else if (!strcmp(argv[i], "-f")) {
            FILENAME = argv[++i];
        }
    }

    // Generate properties for vertices and edges based on command-line arguments
    generateProperties();

    // Fetch metadata from an external service for setting properties
    fetchMetadata();

    // Send periodic status updates to a monitoring server using Sandesh client
    boost::thread thread1(sendStatusUpdates);
    thread1.join();

    // Log detailed metrics, including the number of successful and failed operations, to assist in performance tuning and debugging
    boost::thread thread2(logMetrics);
    thread2.join();

    return 0;
}
```

This code uses several Boost libraries for multithreading, file I/O, string manipulation, and time management. The `main` function parses command-line arguments to configure graph generation and metadata retrieval. It then generates properties for vertices and edges based on the command-line arguments and fetches metadata from an external service using a robust mechanism to handle potential failures. It also sends periodic status updates to a monitoring server using Sandesh client and logs detailed metrics to assist in performance tuning and debugging.']

