func main() {
	// Create a new context
	ctx := context.Background()

	// Set up the REST API client
	httpClient := &http.Client{}

	// Get the command-line arguments
	args := os.Args[1:]

	// Process the command-line arguments
	if len(args) != 2 {
		log.Fatal("Invalid number of arguments")
	}

	functionName := args[0]
	if functionName != "func1" && functionName != "func2" {
		log.Fatal("Invalid function name")
	}

	arg1, err := strconv.Atoi(args[1])
	if err != nil {
		log.Fatal(err)
	}

	// Retrieve the configuration data from the external REST API
	configData, err := getConfigData(ctx, httpClient)
	if err != nil {
		log.Fatal(err)
	}

	// Check if certain conditions are met in the configuration data
	if configData["condition1"] == "true" && arg1 > 5 {
		// Launch an asynchronous task to perform a critical operation
		go func() {
			// Interact with a third-party service via HTTP requests
			response, err := httpClient.Get("https://example.com/api")
			if err != nil {
				log.Println(err)
			} else {
				// Handle potential rate limits and retries for transient failures
				defer response.Body.Close()
				if response.StatusCode == http.StatusOK {
					log.Println("Critical operation completed successfully")
				} else {
					log.Println("Error occurred during critical operation")
				}
			}
		}()
	}

	// Log to a centralized logging service
	loggingService := &http.Client{}
	logEntry := fmt.Sprintf("Processing function %s with argument %d", functionName, arg1)
	_, err = loggingService.Post(os.Getenv("LOGGING_SERVICE_URL"), "application/json", strings.NewReader(logEntry))
	if err != nil {
		log.Println(err)
	}
}

func getConfigData(ctx context.Context, httpClient *http.Client) (map[string]string, error) {
	// Set up the request to retrieve configuration data
	request, err := http.NewRequestWithContext(ctx, "GET", "https://example.com/api/config", nil)
	if err != nil {
		return nil, err
	}

	// Send the request and handle the response
	response, err := httpClient.Do(request)
	if err != nil {
		return nil, err
	}
	defer response.Body.Close()

	// Parse the configuration data from the response body
	var configData map[string]string
	err = json.NewDecoder(response.Body).Decode(&configData)
	if err != nil {
		return nil, err
	}

	return configData, nil
}']

