                Ok(_) => (),
                Err(e) => return Err(format!("Failed to create config directory: {}", e)),
            }
        }

        // Update the configuration path in the global store
        let mut guard = CONFIG_STORE.lock().unwrap();
        *guard = Some(config);

        Ok(())
    }
}

lazy_static! {
    static ref CONFIG_STORE: Mutex<Option<HashMap<String, String>>> = Mutex::new(None);
}

