        rec_count++;
        if (rec_count > buf_size) {
            printf("Input buffer overflow\n");
            break;
        }
    }

    // Find the largest integer in the input buffer
    for (int i = 0; i < rec_count; i++) {
        if (records[i].key > max_key) {
            max_key = records[i].key;
        }
    }

