#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

// Define the structure for a record
typedef struct {
    int value;
} Record;

// Define the hash table for mapping keys to record indices
typedef struct {
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
    int* keys;
    Record** records;
} HashTable;

// Initialize a new hash table with the given initial capacity and load factor
HashTable* init_hash_table(size_t capacity, float load_factor) {
    // Allocate memory for the hash table structure and its arrays
    HashTable* table = malloc(sizeof(HashTable));
    table->capacity = capacity;
    table->count = 0;
    table->mutex = PTHREAD_MUTEX_INITIALIZER;
    table->keys = calloc(table->capacity, sizeof(int));
    table->records = calloc(table->capacity, sizeof(Record*));

    // Set the load factor and calculate the initial capacity
    table->load_factor = load_factor;
    table->initial_capacity = (size_t)(table->capacity / table->load_factor);

    return table;
}

// Insert a new record into the hash table with the given key and value
void insert(HashTable* table, int key, int value) {
    // Lock the mutex to prevent concurrent updates
    pthread_mutex_lock(&table->mutex);

    // Check if the hash table needs to be resized
    if (table->count >= table->initial_capacity) {
        resize(table);
    }

    // Calculate the index for the new record
    size_t index = key % table->capacity;

    // Check if there is already a record with the same key
    if (table->keys[index] == key) {
        // Update the existing record
        table->records[index]->value = value;
    } else {
        // Insert a new record
        Record* record = malloc(sizeof(Record));
        record->value = value;
        table->keys[index] = key;
        table->records[index] = record;
        table->count++;
    }

    // Unlock the mutex
    pthread_mutex_unlock(&table->mutex);
}

// Update a record in the hash table with the given key and value
void update(HashTable* table, int key, int value) {
    // Lock the mutex to prevent concurrent updates
    pthread_mutex_lock(&table->mutex);

    // Calculate the index for the record
    size_t index = key % table->capacity;

    // Check if there is a record with the same key
    if (table->keys[index] == key) {
        // Update the existing record
        table->records[index]->value = value;
    } else {
        // Insert a new record
        Record* record = malloc(sizeof(Record));
        record->value = value;
        table->keys[index] = key;
        table->records[index] = record;
        table->count++;
    }

    // Unlock the mutex
    pthread_mutex_unlock(&table->mutex);
}

// Lookup a record in the hash table with the given key and return its value
int lookup(HashTable* table, int key) {
    // Lock the mutex to prevent concurrent updates
    pthread_mutex_lock(&table->mutex);

    // Calculate the index for the record
    size_t index = key % table->capacity;

    // Check if there is a record with the same key
    if (table->keys[index] == key) {
        // Return the value of the existing record
        int value = table->records[index]->value;
        pthread_mutex_unlock(&table->mutex);
        return value;
    } else {
        // Unlock the mutex and return a special value indicating that the key is not found
        pthread_mutex_unlock(&table->mutex);
        return -1;
    }
}

// Resize the hash table when it reaches its initial capacity
void resize(HashTable* table) {
    // Calculate the new capacity based on the current load factor
    size_t new_capacity = (size_t)(table->count * table->load_factor);

    // Allocate memory for the new arrays
    int* new_keys = calloc(new_capacity, sizeof(int));
    Record** new_records = calloc(new_capacity, sizeof(Record*));

    // Copy the existing keys and records to the new arrays
    for (size_t i = 0; i < table->count; i++) {
        size_t index = table->keys[i] % new_capacity;
        new_keys[index] = table->keys[i];
        new_records[index] = table->records[i];
    }

    // Free the old arrays and assign the new ones to the hash table structure
    free(table->keys);
    free(table->records);
    table->keys = new_keys;
    table->records = new_records;
}

// Clean up the hash table when it is no longer needed
void cleanup(HashTable* table) {
    // Lock the mutex to prevent concurrent updates
    pthread_mutex_lock(&table->mutex);

    // Free the keys and records arrays
    free(table->keys);
    for (size_t i = 0; i < table->count; i++) {
        free(table->records[i]);
    }
    free(table->records);

    // Unlock the mutex and free the hash table structure
    pthread_mutex_unlock(&table->mutex);
}
```
This implementation uses a hash table to map keys to record indices, with each key associated with a single record containing an integer value. The hash table is initialized with an initial capacity and load factor, which determines when the table needs to be resized. The insert and update functions use a mutex to prevent concurrent updates, and the lookup function uses the same mutex to ensure consistency in retrieving values. When the hash table reaches its initial capacity, it is resized to accommodate more records with a new load factor that takes into account the current number of records. The cleanup function frees the memory used by the hash table and its arrays when they are no longer needed.

This implementation also supports dynamic resizing of the key and record arrays based on user-provided thresholds, which helps to optimize performance and minimize the frequency of memory reallocations. Additionally, it provides a mechanism for safely updating the value of any given record based on its key, ensuring atomicity in the updates.']

