import java.io.*;
import java.net.*;
import java.nio.*;
import java.nio.channels.*;

public class SocketConnection {
    private SocketChannel socketChannel;
    private ByteBuffer readBuffer, writeBuffer;

    public SocketConnection(String hostname, int port) throws IOException {
        // Create a new SocketChannel and set it to non-blocking mode
        socketChannel = SocketChannel.open();
        socketChannel.configureBlocking(false);

        // Connect the channel to the specified address
        InetSocketAddress addr = new InetSocketAddress(hostname, port);
        if (!socketChannel.connect(addr)) {
            throw new IOException("Failed to connect to " + hostname + ":" + port);
        }

        // Initialize the buffers for reading and writing data
        readBuffer = ByteBuffer.allocateDirect(1024);
        writeBuffer = ByteBuffer.allocateDirect(1024);
    }

    public boolean isConnected() {
        return socketChannel.isConnected();
    }

    public void disconnect() throws IOException {
        // Close the SocketChannel and free resources
        socketChannel.close();
    }

    public int write(byte[] data) throws IOException {
        // Write data to the channel and return the number of bytes written
        int bytesWritten = 0;
        while (bytesWritten < data.length) {
            int numBytes = socketChannel.write(ByteBuffer.wrap(data, bytesWritten, data.length - bytesWritten));
            if (numBytes == -1) break;
            bytesWritten += numBytes;
        }
        return bytesWritten;
    }

    public byte[] read() throws IOException {
        // Read data from the channel and return it as a byte array
        int bytesRead = 0;
        byte[] buffer = new byte[1024];
        while (bytesRead < buffer.length) {
            int numBytes = socketChannel.read(ByteBuffer.wrap(buffer, bytesRead, buffer.length - bytesRead));
            if (numBytes == -1) break;
            bytesRead += numBytes;
        }
        return Arrays.copyOfRange(buffer, 0, bytesRead);
    }
}
