namespace fsa {
    struct StateList {
        vector<int> states;
        StateList* next;
    };

    int createStateList(const int* states, int numStates, FSA& fsa, int lastState) {
        mutex mtx;
        unique_lock<mutex> lock(mtx);

        // Create a new state list and add the given states to it
        auto newStateList = make_unique<StateList>();
        for (int i = 0; i < numStates; ++i) {
            newStateList->states.push_back(states[i]);
        }

        // Update the 'next' pointer of the last state to point to the newly created list
        fsa.states[lastState].next = newStateList.get();

        // Store the newly created state list in the FSA object
        fsa.stateLists.push_back(move(newStateList));

        return 0;
    }
}
