fn createHttpClient(url: &str) -> Result<RequestBuilder, Box<dyn Error>> {
    let mut client_config = ClientConfig::new();
    let url = Url::parse(url)?;
    let hostname = url.host_str().ok_or("Invalid URL")?;
    let port = url.port().unwrap_or(443);
    let request_timeout = Duration::from_secs(env::var("REQUEST_TIMEOUT").ok());
    let retry_attempts = env::var("RETRY_ATTEMPTS").parse::<usize>().unwrap();
    let retry_delay = Duration::from_millis(env::var("RETRY_DELAY").parse::<u64>().unwrap());

    if client_config.has_root_store() {
        client_config.root_store.add_server_trust_anchors(&webpki_roots::TLS_SERVER_ROOTS);
    } else {
        client_config.set_persistence(ClientConfig:: persistence_type());
        let mut roots = rustls::RootCertStore::empty();
        if !root_certs.is_empty() {
            for cert in root_certs {
                match roots.add(&rustls::Certificate(cert)) {
                    Ok(_) => (),
                    Err(e) => return Err(Box::<dyn Error>::from(e)),
                }
            }
        }
    }

    let connector = HttpsConnector::new((client_config, hostname).ok_or("Invalid URL")?);

    Ok(RequestBuilder {
        url,
        method: Method::GET,
        headers: HashMap::new(),
        body: None,
        connector,
        request_timeout,
        retry_attempts,
        retry_delay,
    })
