// Function to process and generate report from multiple sources
void processAndGenerateReport(const Logs* logs, const Content* content, const LineNumbers* lineNumbers) {
    // Preallocate memory for log entries and content
    LogEntry* entry = malloc(sizeof(LogEntry) * (logs->numEntries + 1));
    char* contentPtr = malloc(content->length + 1);

    // Iterate over log entries and copy to the preallocated memory
