        return -1;
    }

    // Resize the nodes array to accommodate the new node
    graph->nodes = realloc(graph->nodes, (graph->num_nodes + 1) * sizeof(Node*));
    if (!graph->nodes) {
        printf("Error: insufficient memory to resize nodes array.\n");
        free(node);
        return -1;
    }

    // Initialize the new node's fields
    graph->nodes[graph->num_nodes] = node;
    graph->num_nodes++;

    return graph->num_nodes - 1;
}

// Function to add a dependency between two nodes, returns true if successful or false otherwise
bool add_dependency(Graph* graph, int from, int to) {
    // Check if the nodes exist in the graph and are connected
    if (from >= graph->num_nodes || to >= graph->num_nodes) {
        printf("Error: invalid node indices.\n");
        return false;
    }

    Node* from_node = graph->nodes[from];
    Node* to_node = graph->nodes[to];

    // Check if the dependency already exists
    for (int i = 0; i < from_node->num_dependencies; i++) {
        if (from_node->dependencies[i] == to_node) {
            printf("Error: duplicate dependency.\n");
            return false;
        }
    }

    // Resize the dependencies array to accommodate the new dependency
    from_node->dependencies = realloc(from_node->dependencies, (from_node->num_dependencies + 1) * sizeof(Node*));
    if (!from_node->dependencies) {
        printf("Error: insufficient memory to resize dependencies array.\n");
        return false;
    }

    // Initialize the new dependency's fields
    from_node->dependencies[from_node->num_dependencies] = to_node;
    from_node->num_dependencies++;

    // Add the edge ID to the edge IDs array
    graph->edge_ids = realloc(graph->edge_ids, (graph->num_edges + 1) * sizeof(int));
    if (!graph->edge_ids) {
        printf("Error: insufficient memory to resize edge IDs array.\n");
        return false;
    }

    graph->edge_ids[graph->num_edges] = from_node->id + " -> " + to_node->id;
    graph->num_edges++;

    return true;
}

// Function to remove a node and its dependencies from the graph, returns true if successful or false otherwise
bool remove_node(Graph* graph, int id) {
    // Check if the node exists in the graph
    if (id >= graph->num_nodes) {
        printf("Error: invalid node index.\n");
        return false;
    }

    Node* node = graph->nodes[id];

    // Remove all edges connected to this node
    for (int i = 0; i < node->num_dependencies; i++) {
        int from = id;
        int to = node->dependencies[i]->id;
        remove_dependency(graph, from, to);
    }

    // Remove the node from the nodes array
    for (int i = 0; i < graph->num_nodes - 1; i++) {
        if (graph->nodes[i] == node) {
            int j = i + 1;
            while (j < graph->num_nodes) {
                graph->nodes[i] = graph->nodes[j];
                i++;
                j++;
            }
            break;
        }
    }

    // Reduce the number of nodes in the graph
    graph->num_nodes--;

    return true;
}

// Function to remove a dependency between two nodes, returns true if successful or false otherwise
bool remove_dependency(Graph* graph, int from, int to) {
