            return calculate_weight(graph, from, to);
        }
    }

    // Check if the nodes are connected by a direct edge
    for (int i = 0; i < graph->num_edges; i++) {
        string edge_id = graph->edge_ids[i];
        int pos = edge_id.find(" -> ");
        int from_id = stoi(edge_id.substr(0, pos));
        int to_id = stoi(edge_id.substr(pos + 4));
        if (from_id == from && to_id == to) {
            return 1;
        }
    }

    // The nodes are not connected
    return -1;
}

