  vector<string> ips;

  // Populate vector with server IP addresses using configuration service interface
  for (auto i = 0; i < 3; ++i) {
    const string& ip = config_.getServerNodeMetadata("192.168.1." + to_string(i + 1)).first;
    ips.push_back(ip);
  }

  // Send GET requests to remote servers and validate responses
  sandesh_client.sendGetRequests(ips, "path");

  // Free memory for arrays and records
  delete[] offsets;
  delete[] keys;
  delete[] records;

  return 0;
}
