```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pthread.h>

// Define the structure for a record
typedef struct {
    int key;
    long offset;
} Record;

// Define the linked list node
typedef struct LinkedListNode {
    Record *record;
    struct LinkedListNode *next;
} LinkedListNode;

// Define the function to handle batch updates to multiple records based on their key values
int batchUpdateRecords(Record **records, int num_records, int *keys, long *offsets) {
    // Check if the input arrays are valid
    if (!records || !num_records || !keys || !offsets) {
        return -1;
    }

    // Initialize a cache for frequently accessed records
    struct CacheNode {
        Record *record;
        bool used;
    };
    size_t cache_size = 10000; // Dynamically adjust the cache size based on system load and memory availability
    struct CacheNode *cache = malloc(sizeof(struct CacheNode) * cache_size);
    if (!cache) {
        return -2;
    }

    // Initialize the linked list for managing the records
    LinkedListNode *head = NULL;
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    // Iterate over the input arrays and update the corresponding records in the linked list
    for (int i = 0; i < num_records; ++i) {
        // Check if the record is in the cache, and return it if found
        struct CacheNode *cache_node = findInCache(keys[i], cache, cache_size);
        if (cache_node) {
            records[i] = cache_node->record;
            continue;
        }

        // Allocate a new record and initialize it with a random value within the specified range
        Record *new_record = malloc(sizeof(Record));
        new_record->key = keys[i];
        new_record->offset = offsets[i] + rand() % 100; // Generate a random offset within the specified range
        records[i] = new_record;

        // Add the record to the linked list and update the cache
        pthread_mutex_lock(&lock);
        LinkedListNode *node = malloc(sizeof(LinkedListNode));
        node->record = new_record;
        node->next = head;
        head = node;
        addToCache(keys[i], new_record, cache, cache_size);
        pthread_mutex_unlock(&lock);
    }

    // Free the memory used by the cache and linked list
    free(cache);
    while (head) {
        LinkedListNode *node = head;
        head = node->next;
        free(node->record);
        free(node);
    }

    return 0;
}

// Find the record in the cache with the given key
struct CacheNode *findInCache(int key, struct CacheNode *cache, size_t cache_size) {
    for (size_t i = 0; i < cache_size; ++i) {
        if (cache[i].used && cache[i].record->key == key) {
            return &cache[i];
        }
    }
    return NULL;
}

// Add the record to the cache and update its status as used
void addToCache(int key, Record *record, struct CacheNode *cache, size_t cache_size) {
    for (size_t i = 0; i < cache_size; ++i) {
        if (!cache[i].used) {
            cache[i].used = true;
            cache[i].record = record;
            break;
        }
    }
}
```
The function takes in three arrays of integers as input: `records`, `keys`, and `offsets`. The `records` array is used to store the actual records, while the `keys` and `offsets` arrays are used for batch updates.

The function first checks if the input arrays are valid and initializes a cache for frequently accessed records using a linked list structure. The cache size is dynamically adjusted based on system load and memory availability.

Next, the function iterates over the input arrays and updates the corresponding records in the linked list. If the record is already in the cache, it returns the cached record without modifying it. Otherwise, it allocates a new record with a random offset within the specified range and adds it to the linked list and the cache.

Finally, the function frees the memory used by the cache and linked list.

