        arr->count++;
        KeyValuePair* pair = malloc(sizeof(KeyValuePair));
        if (!pair) {
            printf("Error allocating memory for integer list\n");
            return -1;
        }
        pair->offset = arr->count - 1;
        pair->key = num;
        arr->pairs = realloc(arr->pairs, sizeof(KeyValuePair) * (arr->count));
        if (!arr->pairs) {
            printf("Error allocating memory for integer list\n");
            return -1;
        }
        arr->pairs[pair->offset] = *pair;
        if (largest < num) {
            largest = num;
        }
    }

    // Print the largest integer in the list
    printf("Largest integer in list: %d\n", largest);

    return 0;
}

// Function to update a record in the array based on its key value
int updateRecord(IntArray* arr, int key, int newValue) {
    // Find the index of the record with the given key
    size_t i = 0;
    while (i < arr->count && arr->pairs[i].key != key) {
        i++;
    }

    if (i == arr->count) {
        // Record not found
        return -1;
    } else {
        // Update the record with the new value
        arr->pairs[i].value = newValue;
        return 0;
    }
}

// Function to retrieve a record from the array based on its key value
int getRecord(IntArray* arr, int key, int* value) {
    // Find the index of the record with the given key
    size_t i = 0;
    while (i < arr->count && arr->pairs[i].key != key) {
        i++;
    }

    if (i == arr->count) {
        // Record not found
        return -1;
    } else {
        // Return the value of the record
        *value = arr->pairs[i].value;
        return 0;
    }
}

// Function to free the memory allocated for the array
void freeIntArray(IntArray* arr) {
    if (arr->pairs != NULL) {
        free(arr->pairs);
        arr->pairs = NULL;
    }
}
