public class DynamicRangeManager
{
    private readonly List<Range> ranges = new List<Range>();

    public DynamicRangeManager() { }

    public void AddNewRange(int minValue, int maxValue)
    {
        if (minValue >= maxValue)
        {
            throw new ArgumentException("Minimum value must be less than maximum value");
        }

        // Ensure that the new range does not overlap with existing ranges
        foreach (var range in ranges)
        {
            if (range.Overlaps(minValue, maxValue))
            {
                throw new ArgumentException("Range overlaps with an existing range");
            }
        }

        // Ensure that the new range fits within predefined limits
        if (minValue < int.MinValue || minValue > int.MaxValue)
        {
            throw new ArgumentOutOfRangeException(nameof(minValue), "Minimum value must be between " + int.MinValue + " and " + int.MaxValue);
        }
        if (maxValue < int.MinValue || maxValue > int.MaxValue)
        {
            throw new ArgumentOutOfRangeException(nameof(minValue), "Maximum value must be between " + int.MinValue + " and " + int.MaxValue);
        }

        ranges.Add(new Range(minValue, maxValue));
    }

    public void RemoveRange(int index)
    {
        if (index < 0 || index >= ranges.Count)
        {
            throw new ArgumentOutOfRangeException(nameof(index), "Index must be between 0 and " + (ranges.Count - 1));
        }

        ranges.RemoveAt(index);
    }

    public void UpdateRange(int index, int minValue, int maxValue)
    {
        if (index < 0 || index >= ranges.Count)
        {
            throw new ArgumentOutOfRangeException(nameof(index), "Index must be between 0 and " + (ranges.Count - 1));
        }

        // Ensure that the new range does not overlap with existing ranges
        foreach (var range in ranges)
        {
            if (range != this && range.Overlaps(minValue, maxValue))
            {
                throw new ArgumentException("Range overlaps with an existing range");
            }
        }

        // Ensure that the new range fits within predefined limits
        if (minValue < int.MinValue || minValue > int.MaxValue)
        {
            throw new ArgumentOutOfRangeException(nameof(minValue), "Minimum value must be between " + int.MinValue + " and " + int.MaxValue);
        }
        if (maxValue < int.MinValue || maxValue > int.MaxValue)
        {
            throw new ArgumentOutOfRangeException(nameof(minValue), "Maximum value must be between " + int.MinValue + " and " + int.MaxValue);
        }

        ranges[index] = new Range(minValue, maxValue);
    }

    public int GetRandomInteger()
    {
        // Pseudo-random number generator to ensure consistent results across different runs
        Random random = new Random();

        // Loop until a valid integer value is found within one of the ranges
        while (true)
        {
            var rangeIndex = random.Next(ranges.Count);
            var range = ranges[rangeIndex];

            if (range.MinValue == range.MaxValue)
            {
                // Inclusive boundary case
                return range.MinValue;
            }
            else
            {
                // Exclusive boundary case
                var randomValue = random.Next(range.MinValue, range.MaxValue + 1);
                if (randomValue >= range.MinValue && randomValue < range.MaxValue)
                {
                    return randomValue;
                }
            }
        }
    }

    public float GetRandomFloat()
    {
        // Pseudo-random number generator to ensure consistent results across different runs
        Random random = new Random();

        // Loop until a valid float value is found within one of the ranges
        while (true)
        {
            var rangeIndex = random.Next(ranges.Count);
            var range = ranges[rangeIndex];

            if (range.MinValue == range.MaxValue)
            {
                // Inclusive boundary case
                return range.MinValue;
            }
            else
            {
                // Exclusive boundary case
                var randomValue = (float)random.NextDouble() * (range.MaxValue - range.MinValue) + range.MinValue;
                if (randomValue >= range.MinValue && randomValue < range.MaxValue)
                {
                    return randomValue;
                }
            }
        }
    }

    public override string ToString()
    {
        var output = "Ranges:";
        foreach (var range in ranges)
        {
            output += $"\n\t{range.MinValue}-{range.MaxValue}";
        }
        return output;
    }

    private class Range
    {
        public int MinValue { get; set; }
        public int MaxValue { get; set; }

        public Range(int minValue, int maxValue)
        {
            this.MinValue = minValue;
            this.MaxValue = maxValue;
        }

        public bool Overlaps(int minValue, int maxValue)
        {
            return !(maxValue < MinValue || MinValue > maxValue);
        }
    }
}
```
