    }
    // Add the new record to the caching mechanism
    if (cache->size == 0) {
        cache->records[0] = new_record;
    } else {
        for (int i = 0; i < cache->size; ++i) {
            if (cache->records[i] == NULL) {
                cache->records[i] = new_record;
                break;
            }
        }
    }
}

// Define a function to retrieve a record from the linked list and caching mechanism
record_t* get_record(cache_t* cache, int value) {
    // Search for the record in the linked list
    record_t* current = cache->records[0];
    while (current != NULL && current->value != value) {
        current = current->next;
    }
    // If the record is found, move it to the front of the linked list
    if (current != NULL) {
        record_t* temp = current->next;
        current->next = temp->next;
        temp->next = cache->records[0];
        cache->records[0] = temp;
        return temp;
    } else {
        // If the record is not found, allocate memory for a new one and add it to the linked list
        record_t* new_record = (record_t*)malloc(sizeof(record_t));
        new_record->value = value;
        new_record->next = cache->records[0];
        cache->records[0] = new_record;
        return new_record;
    }
}

// Define a function to release all allocated memory when the function completes execution
void cleanup(cache_t* cache) {
    // Release memory for the linked list and caching mechanism
    record_t* current = cache->records[0];
    while (current != NULL) {
        record_t* temp = current;
        current = current->next;
        free(temp);
    }
    free(cache->records);
}

int main() {
