    cache_t cache;
    init(&cache, 10);
    // Set the value of each record's int field to a random value within a specified range
    srand(time(NULL));
    for (int i = 0; i < 20; ++i) {
        add_record(&cache, rand() % 10);
    }
    // Retrieve and print the values of each record in the linked list
    current = cache.records[0];
    while (current != NULL) {
        printf("%d\n", current->value);
        current = current->next;
    }
    cleanup(&cache);
    return 0;
}
