// encrypt the input string using AES in CBC mode with PKCS#7 padding
void encrypt(char *plaintext, char *ciphertext, int len) {
    // generate a random IV and encrypt the plaintext
    unsigned char iv[AES_BLOCK_SIZE];
    getrandom(iv, AES_BLOCK_SIZE, 0);
    memcpy(ciphertext, iv, AES_BLOCK_SIZE);
