    // pad the ciphertext with PKCS#7 padding
    int blocksize = AES_BLOCK_SIZE;
    int padding = blocksize - (cipherlen % blocksize);
    memset(ciphertext + cipherlen, padding, padding);
}

// decrypt the input string using AES in CBC mode with PKCS#7 padding
void decrypt(char *ciphertext, char *plaintext, int len) {
    // extract the IV from the beginning of the ciphertext
    unsigned char iv[AES_BLOCK_SIZE];
    memcpy(iv, ciphertext, AES_BLOCK_SIZE);

    // decrypt the ciphertext using AES in CBC mode with PKCS#7 padding
    int blocksize = AES_BLOCK_SIZE;
    int plainlen = len - blocksize;
    aes_cbc_decrypt(ciphertext + AES_BLOCK_SIZE, plaintext, plainlen, key, iv);
