    int len = BN_num_bytes(bnx);
    BN_bn2bin(bnx, x);
    unsigned char y[ECDSA_PUBKEY_SIZE];
    len = BN_num_bytes(bny);
    BN_bn2bin(bny, y);
    ECDSA_PUBKEY_SIZE;
    EC_KEY_free(pubkey);

    // hash the input string and verify the signature
    unsigned char digest[SHA256_DIGEST_LENGTH];
    SHA256((unsigned char *)input, len, digest);
    int result = ecdsa_verify(x, y, len, signature, len);
}
