    if (packets != NULL) {
        free(packets);
    }
}

// Define a function to resize an array of data packets
void resize_data_packets(struct data_packet** packets, size_t new_size) {
    // Check if the new size is greater than the current size
    if (new_size > (*packets)->size) {
        // Reallocate memory for the array of data packets
        struct data_packet* new_packets = (struct data_packet*) realloc(*packets, sizeof(struct data_packet) * new_size);
