        size_t i;
        for (i = (*packets)->size; i < new_size; i++) {
            new_packets[i].timestamp = 0;
            strcpy(new_packets[i].message, "");
            new_packets[i].measurement = 0.0;
        }

        // Update the size of the array and free the old memory
        (*packets)->size = new_size;
        free((*packets));
