	EVP_EncryptInit_ex(&ctx, EVP_aes_256_cbc(), NULL, key, iv);
	int len;
	while ((len = RSA_size(rsa)) > 0) {
		if (RAND_bytes(input_buffer, input_buffer_size) <= 0) {
			fprintf(stderr, "Error generating random number\n");
		}
		EVP_EncryptUpdate(&ctx, output_buffer + written, &len, input_buffer, RSA_size(rsa));
		written += len;
	}

	// 4. Generate a MAC using HMAC-SHA256 and the encryption result
	EVP_HMAC_CTX *ctx = NULL;
	unsigned char mac[EVP_MAX_MD_SIZE];
	int mac_len = 0;
	if (!HMAC_Init_ex(ctx, key, key_length, EVP_sha256(), NULL)) {
		fprintf(stderr, "Error initializing HMAC context\n");
	}

	if (!HMAC_Update(ctx, output_buffer, written)) {
		fprintf(stderr, "Error updating HMAC with encryption result\n");
	}

	if (!HMAC_Final(ctx, mac, &mac_len)) {
		fprintf(stderr, "Error finalizing HMAC calculation\n");
	}

	// 5. Serialize the data for transmission and deserialization on the other end
	unsigned char* serialized = malloc((written + mac_len) * sizeof(unsigned char));
	if (serialized == NULL) {
		fprintf(stderr, "Error allocating memory for serialized data\n");
	}

	memcpy(serialized, output_buffer, written);
	memcpy(serialized + written, mac, mac_len);

	// 6. Deserialize the data on the other end and verify the MAC
	unsigned char* deserialized = malloc((written + mac_len) * sizeof(unsigned char));
	if (deserialized == NULL) {
		fprintf(stderr, "Error allocating memory for deserialized data\n");
	}

	memcpy(deserialized, serialized, written + mac_len);

	// 7. Decrypt the data using AES-256-CBC with the generated IV
	EVP_DecryptInit_ex(&ctx, EVP_aes_256_cbc(), NULL, key, iv);
	int len;
	while ((len = RSA_size(rsa)) > 0) {
		if (RAND_bytes(input_buffer, input_buffer_size) <= 0) {
			fprintf(stderr, "Error generating random number\n");
		}
		EVP_DecryptUpdate(&ctx, output_buffer + written, &len, deserialized, RSA_size(rsa));
		written += len;
	}

	// 8. Verify the MAC using HMAC-SHA256 and the decryption result
	EVP_HMAC_CTX *ctx = NULL;
	unsigned char mac[EVP_MAX_MD_SIZE];
	int mac_len = 0;
	if (!HMAC_Init_ex(ctx, key, key_length, EVP_sha256(), NULL)) {
		fprintf(stderr, "Error initializing HMAC context\n");
	}

	if (!HMAC_Update(ctx, output_buffer, written)) {
		fprintf(stderr, "Error updating HMAC with decryption result\n");
	}

	if (!HMAC_Final(ctx, mac, &mac_len)) {
		fprintf(stderr, "Error finalizing HMAC calculation\n");
	}

	// 9. Compare the MACs and verify that they match
	int mac_match = 0;
	for (int i = 0; i < mac_len; ++i) {
		if (mac[i] != deserialized[written + i]) {
			break;
		} else {
			mac_match = 1;
		}
	}

	// 10. If the MACs match, decrypt the data and return it to the caller, otherwise return an error
	if (mac_match == 1) {
		return output_buffer;
	} else {
		fprintf(stderr, "Error: MACs do not match\n");
		return NULL;
	}
}']

