// Define data structures
struct record {
    int value;
};

struct long_int_record {
    long offset;
    int key;
    struct record rec;
};

// Function to dynamically allocate memory for data structures based on input parameters
void dynamic_allocation(int num_records, int num_keys, int max_value) {
    // Allocate memory for the array of records
    struct record *records = malloc(num_records * sizeof(struct record));
    if (records == NULL) {
        printf("Error: Failed to allocate memory for records\n");
        return;
    }

    // Allocate memory for the array of long integers
    long *long_ints = malloc(num_keys * sizeof(long));
    if (long_ints == NULL) {
        printf("Error: Failed to allocate memory for long integers\n");
        free(records);
        return;
    }

    // Allocate memory for the array of integer keys
    int *keys = malloc(num_keys * sizeof(int));
    if (keys == NULL) {
        printf("Error: Failed to allocate memory for integer keys\n");
        free(records);
        free(long_ints);
        return;
    }

    // Allocate memory for the array of long integer offsets
    long *offsets = malloc(num_keys * sizeof(long));
    if (offsets == NULL) {
        printf("Error: Failed to allocate memory for long integer offsets\n");
        free(records);
        free(long_ints);
        free(keys);
        return;
    }

    // Initialize the arrays with default values
    memset(records, 0, num_records * sizeof(struct record));
    memset(long_ints, 0, num_keys * sizeof(long));
    memset(keys, 0, num_keys * sizeof(int));
    memset(offsets, 0, num_keys * sizeof(long));
}

// Function to dynamically allocate memory for a single record structure
struct record* dynamic_allocate_record(int max_value) {
    // Allocate memory for the record structure
    struct record *rec = malloc(sizeof(struct record));
    if (rec == NULL) {
        printf("Error: Failed to allocate memory for a single record\n");
        return NULL;
    }

    // Initialize the record structure with default values
    rec->value = 0;

    return rec;
}

// Function to handle memory allocation failures gracefully
void memory_allocation_failure(struct long_int_record *rec, int num_keys) {
    // Free all allocated memory
    free(rec);
    for (int i = 0; i < num_keys; i++) {
        free(long_ints[i]);
        free(keys[i]);
        free(offsets[i]);
    }
}

// Function to read input from standard input and fill the data structures
void read_input(struct long_int_record *rec, int num_keys) {
    // Read the input values from standard input
    for (int i = 0; i < num_keys; i++) {
        scanf("%d", &(rec[i].key));
        rec[i].rec.value = rec[i].key;
        rec[i].long_ints = malloc(sizeof(long));
        if (rec[i].long_ints == NULL) {
            printf("Error: Failed to allocate memory for long integer\n");
            return;
        }
        *(rec[i].long_ints) = rec[i].key;
    }
}

// Function to identify and print the largest integer in the array
void identify_largest(struct record *records, int num_records) {
    // Initialize variables to keep track of the largest value and its index
    int largest = -1;
    int largest_index = 0;

    // Iterate over the array and find the largest value
    for (int i = 0; i < num_records; i++) {
        if (largest == -1 || records[i].value > largest) {
            largest = records[i].value;
            largest_index = i;
        }
    }

    // Print the largest integer and its index
    printf("Largest integer: %d at index %d\n", largest, largest_index);
}

// Function to maintain a separate count of non-positive integers (zero and negative numbers)
void count_non_positive(struct record *records, int num_records) {
    // Initialize variables to keep track of the number of non-positive values
    int count = 0;

    // Iterate over the array and count the number of non-positive values
    for (int i = 0; i < num_records; i++) {
        if (records[i].value <= 0) {
            count++;
        }
    }

    // Print the number of non-positive integers
    printf("Number of non-positive integers: %d\n", count);
}

// Function to ignore duplicate integers and count only unique values
void count_unique(struct record *records, int num_records) {
    // Create a hash table to keep track of the unique values
    struct hash_table *ht = create_hash_table();

    // Iterate over the array and add each value to the hash table
    for (int i = 0; i < num_records; i++) {
        if (!add_key_to_hash_table(ht, records[i].value)) {
            printf("Error: Failed to add key to hash table\n");
            return;
        }
    }

    // Print the number of unique integers
    printf("Number of unique integers: %d\n", get_hash_table_size(ht));

    // Free the hash table
    free_hash_table(ht);
}

// Function to sort the array and print it
void print_sorted_array(struct record *records, int num_records) {
    // Sort the array using the quicksort algorithm
    quicksort(records, 0, num_records - 1);

    // Print the sorted array
    for (int i = 0; i < num_records; i++) {
        printf("%d ", records[i].value);
    }
}

// Function to free all allocated memory
void free_memory(struct long_int_record *rec, int num_keys) {
    // Free all allocated memory for the data structures
    for (int i = 0; i < num_keys; i++) {
        free(rec[i].long_ints);
        free(rec[i].key);
        free(rec[i].offsets);
    }
}

int main() {
    // Declare variables to hold the number of keys and records
    int num_keys = 0;
    int num_records = 0;

    // Read the number of keys from standard input
    scanf("%d", &num_keys);

    // Allocate memory for the data structures
    struct long_int_record *rec = dynamic_allocate_record(num_keys, num_records);

    // Read the input values from standard input and fill the data structures
    read_input(rec, num_keys);

    // Identify and print the largest integer in the array
    identify_largest(rec, num_records);

    // Maintain a separate count of non-positive integers (zero and negative numbers)
    count_non_positive(rec, num_records);

    // Ignore duplicate integers and count only unique values
    count_unique(rec, num_records);

    // Sort the array and print it
    print_sorted_array(rec, num_records);

    // Free all allocated memory
    free_memory(rec, num_keys);

    return 0;
}
