#include <stdlib.h>
#include <stdio.h>
#include <string.h>

// Structure to represent each record
struct Record {
    long offset;
    int key;
};

// Function to generate a variable number of records with unique keys
void generate_records(int min, int max, int callback) {
    // Allocate memory for the records
    struct Record* records = malloc(sizeof(struct Record) * (max - min + 1));

    // Initialize each record with a unique key
    for (int i = 0; i < (max - min + 1); i++) {
        records[i].key = min + i;
        records[i].offset = 0;
    }

    // Call the callback function on each record
    for (int i = 0; i < (max - min + 1); i++) {
        callback(&records[i]);
    }

    // Free the memory allocated for the records
    free(records);
}

// Function to initialize each record with a unique key and offset value
void init_record(struct Record* record) {
    record->key = rand() % (max - min + 1) + min;
    record->offset = 0;
}
