    // Initialize the starting index and end index of the range to search
    size_t start = 0;
    size_t end = offsets[offsets.length - 1];

    // Loop until a match is found or the end of the range is reached
    while (start < end) {
        // Calculate the midpoint of the current range
        size_t mid = start + (end - start) / 2;

        // Compare the key with the record at the midpoint
        if (records[mid].key == key) {
            return mid;
        } else if (records[mid].key < key) {
            start = mid + 1;
        } else {
            end = mid - 1;
        }
    }

    // If no match is found, return -1
    return -1;
}
