    int temp_files = 0;
    while (temp_files < MAX_TEMP_FILES) {
        char* file_name = generate_temp_file(input);
        if (file_name == NULL) break;
        temp_files++;
        free(file_name);
    }
    for (int i = 0; i < temp_files; i++) {
        delete_temp_file();
    }

    // Clean up and return
    pthread_mutex_destroy(&lock);
    fclose(input);
    fclose(output);
    free(offsets);
    free(keys);
    free(threads);
    return 0;
}
