using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace ConfigService
{
    public class ConfigurationManager : IConfigurationManager
    {
        private readonly string _configFilePath;
        private readonly Dictionary<string, string> _environmentVariables;

        public ConfigurationManager(string configFilePath = "appsettings.json", Dictionary<string, string> environmentVariables = null)
        {
            _configFilePath = configFilePath;
            _environmentVariables = environmentVariables ?? new Dictionary<string, string>();
        }

        public async Task<bool> UpdateConfigurationAsync(string key, string value)
        {
            var config = await GetConfigurationAsync();
            if (!config.ContainsKey(key)) return false;

            config[key] = value;
            return await SaveConfigurationAsync(config);
        }

        public async Task<bool> RemoveConfigurationAsync(string key)
        {
            var config = await GetConfigurationAsync();
            if (!config.ContainsKey(key)) return false;

            config.Remove(key);
            return await SaveConfigurationAsync(config);
        }

        public async Task<bool> AddConfigurationAsync(string key, string value)
        {
            var config = await GetConfigurationAsync();
            if (config.ContainsKey(key)) return false;

            config.Add(key, value);
            return await SaveConfigurationAsync(config);
        }

        public async Task<Dictionary<string, string>> GetConfigurationAsync()
        {
            using var stream = new FileStream(_configFilePath, FileMode.OpenOrCreate, FileAccess.ReadWrite);
            using var reader = new StreamReader(stream);
            return await DeserializeJsonAsync(reader.ReadToEnd());
        }

        public async Task<bool> SaveConfigurationAsync(Dictionary<string, string> config)
        {
            using var stream = new FileStream(_configFilePath, FileMode.Create, FileAccess.Write);
            using var writer = new StreamWriter(stream);
            return await SerializeJsonAsync(config, writer);
        }

        public async Task<bool> ReloadConfigurationAsync()
        {
            using var stream = new FileStream(_configFilePath, FileMode.OpenOrCreate, FileAccess.ReadWrite);
            using var reader = new StreamReader(stream);
            await DeserializeJsonAsync(reader.ReadToEnd());
            return true;
        }

        public async Task<bool> SaveChangesAsync()
        {
            var config = GetConfiguration();
            using var stream = new FileStream(_configFilePath, FileMode.Create, FileAccess.Write);
            using var writer = new StreamWriter(stream);
            return await SerializeJsonAsync(config, writer);
        }

        public async Task<bool> SaveRollbackAsync()
        {
            throw new NotImplementedException();
        }

        private async Task<Dictionary<string, string>> DeserializeJsonAsync(string json)
        {
            var config = await JsonSerializer.DeserializeAsync<Dictionary<string, string>>(json);
            return config;
        }

        private async Task<bool> SerializeJsonAsync(Dictionary<string, string> config, TextWriter writer)
        {
            var json = await JsonSerializer.SerializeAsync(config);
            writer.Write(json);
            return true;
        }
    }
}
