char* construct_pem_certificate(const char* input, size_t limit, int timeout) {
    // Check if the input string exceeds the size limit
    if (strlen(input) > limit) {
        return NULL;
    }

    // Append a slash to the end of the input string
    char* output = malloc(sizeof(char) * (limit + 1));
    strcpy(output, input);
    output[strlen(input)] = '/';

    // Construct the certificate in PEM format
    char* pem_certificate = malloc(sizeof(char) * (limit + 256));
    sprintf(pem_certificate, "-----BEGIN CERTIFICATE-----\n%s\n-----END CERTIFICATE-----", output);

    // Free the memory allocated for the output string
    free(output);

    return pem_certificate;
}
