    data->offsets = (long *)malloc(sizeof(long) * size);
    data->keys = (int *)malloc(sizeof(int) * size);
    if (!data->offsets || !data->keys) {
        printf("Memory allocation failed. Terminating gracefully...\n");
        free(data);
        return NULL;
    }

    // Initialize the arrays with sequential values starting from 0, optimized for minimizing cache misses during iteration
    int i;
    for (i = 0; i < size; i++) {
        data->offsets[i] = i * sizeof(int);
        data->keys[i] = i;
