    // Create an array of `record` structures, where each `record` contains a pointer to an integer (`value`) and a reference to a `key` from the `keys` array
    data->records = (record *)malloc(sizeof(record) * size);
    if (!data->records) {
        printf("Memory allocation failed. Terminating gracefully...\n");
        free(data->offsets);
        free(data->keys);
        free(data);
        return NULL;
    }

    // Initialize each `record` structure with a random integer within the user-specified range, ensuring it avoids overflow and minimizes memory fragmentation
    srand(time(NULL));
    for (i = 0; i < size; i++) {
        data->records[i].value = rand() % 100 + 1;
        data->records[i].key = &data->keys[i];
