struct session_info {
    unsigned long session_id;
    char* user_agent;
    time_t start_timestamp;
    time_t last_activity;
};

// Function to initialize a new session
int init_session(unsigned long session_id, struct session_info** session) {
    // Allocate memory for the session info structure
    *session = (struct session_info*)malloc(sizeof(struct session_info));
    if (*session == NULL) {
        return -1; // Memory allocation failed
    }

    // Initialize the session ID and user agent string
    (*session)->session_id = session_id;
    (*session)->user_agent = (char*)malloc(sizeof(char) * 256);
    if ((*session)->user_agent == NULL) {
        free(*session);
        return -1; // Memory allocation failed
    }
    strcpy((*session)->user_agent, "User Agent String");

    // Set the start and last activity timestamps to the current time
    (*session)->start_timestamp = time(NULL);
    (*session)->last_activity = time(NULL);

    return 0; // Success
}

