// Thread-safe logging interface for debugging and monitoring
void log(const char* message, int level) {
    if (level == 1) {
        // Level 1 logs are critical errors that should be immediately logged and reported
        printf("CRITICAL: %s\n", message);
    } else if (level == 2) {
        // Level 2 logs are error conditions that may not impact performance, but still need to be logged for monitoring purposes
        printf("ERROR: %s\n", message);
    } else if (level == 3) {
        // Level 3 logs are informational messages that provide context and insights into system behavior
        printf("INFO: %s\n", message);
    } else if (level == 4) {
        // Level 4 logs are detailed information about system performance and resource utilization
        printf("DEBUG: %s\n", message);
    } else {
        // Unknown logging level, log as an error
