#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

#define MAX_LINE_LENGTH 1024 // maximum length of a line in the input file
#define MAX_FIELDS 100 // maximum number of fields per line

// structure to store information about each line
typedef struct {
    char *line; // pointer to the actual line data
    int num_fields; // number of numerical fields in the line
    double avg; // average of the last two numerical values
} LineInfo;

// function to parse a line and compute the average
void parseLine(char *line, LineInfo *info) {
    // split the line into individual fields using strtok()
    char *token = strtok(line, " ");
    int i = 0;
    while (token != NULL && i < MAX_FIELDS) {
        if (isdigit(token[0])) {
            info->num_fields++;
            if (info->num_fields == 2) {
                info->avg = atof(token);
            } else if (info->num_fields > 2) {
                info->avg += atof(token);
            }
        }
        token = strtok(NULL, " ");
    }
}

// function to process a single line and append the average to the end
void processLine(char *line, LineInfo *info) {
    parseLine(line, info);
    if (info->num_fields >= 2) {
        char avg[100];
        sprintf(avg, "%.3f", info->avg / (info->num_fields - 1));
        strcat(line, ",");
        strcat(line, avg);
    } else {
        strcat(line, ",N/A");
    }
}

// function to process multiple lines concurrently and handle edge cases
void processLines(char **lines, int num_lines) {
    // initialize the LineInfo structure for each line
    LineInfo *infos = malloc(num_lines * sizeof(LineInfo));
    for (int i = 0; i < num_lines; i++) {
        infos[i].line = lines[i];
        infos[i].num_fields = 0;
        infos[i].avg = 0.0;
    }

    // process each line and append the average to the end
    #pragma omp parallel for num_threads(4)
    for (int i = 0; i < num_lines; i++) {
        processLine(infos[i].line, &infos[i]);
    }

    // free the memory allocated for the LineInfo structure
    free(infos);
}

// function to read lines from a file and process them concurrently
void processFile(char *filename) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error: unable to open file %s\n", filename);
        return;
    }

    // read the lines from the file into a buffer
    char **lines = malloc(MAX_LINE_LENGTH * sizeof(char));
    int num_lines = 0;
    while (fgets(lines[num_lines], MAX_LINE_LENGTH, file) != NULL && num_lines < MAX_LINES) {
        num_lines++;
    }

    // process the lines concurrently using a thread pool
    processLines(lines, num_lines);

    // free the memory allocated for the lines buffer
    free(lines);
}

// main function to demonstrate the usage of the functions above
int main() {
    char *filenames[] = {"file1.txt", "file2.txt", "file3.txt"};

    // process each file concurrently using a thread pool
    for (int i = 0; i < 3; i++) {
        processFile(filenames[i]);
    }

    return 0;
}
