#include <string.h>

typedef struct {
    int value;
} record_t;

int init_arrays(long offset_size, int key_size, int record_size) {
    // Dynamically allocate memory for the arrays
    long *offsets = malloc(offset_size * sizeof(long));
    int *keys = malloc(key_size * sizeof(int));
    record_t *records = malloc(record_size * sizeof(record_t));

    if (!offsets || !keys || !records) {
        // Memory allocation failed, log an error message and return a failure status code
        printf("Failed to allocate memory for arrays\n");
        return -1;
    }

    // Initialize the offsets array with random values
    srand(time(NULL));
    for (int i = 0; i < offset_size; ++i) {
        offsets[i] = rand() % 1000;
    }

    // Initialize the keys array with random values
    for (int i = 0; i < key_size; ++i) {
        keys[i] = rand() % 1000;
    }

    // Initialize the records array with random values
    for (int i = 0; i < record_size; ++i) {
        records[i].value = rand() % 1000;
    }

    return 0;
}
