#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <math.h>

// Define a struct for the node
struct Node {
    char* name;
    double value;
};

// Define a struct for the list of nodes
struct NodeList {
    struct Node** nodes;
    int size;
    int capacity;
    pthread_mutex_t mutex; // mutex to protect the list during updates
};

// Function to initialize the list
void initNodeList(struct NodeList* list) {
    list->nodes = malloc(1000 * sizeof(struct Node));
    if (list->nodes == NULL) {
        fprintf(stderr, "Failed to allocate memory for node list\n");
        exit(1);
    }
    list->size = 0;
    list->capacity = 1000;
    pthread_mutex_init(&list->mutex, NULL);
}

// Function to add a node to the list
void addNode(struct NodeList* list, char* name, double value) {
    // Check if the list is full
    if (list->size == list->capacity) {
        fprintf(stderr, "Node list is full\n");
        exit(1);
    }
    pthread_mutex_lock(&list->mutex);
    // Create a new node and add it to the list
    struct Node* node = malloc(sizeof(struct Node));
    if (node == NULL) {
        fprintf(stderr, "Failed to allocate memory for node\n");
        exit(1);
    }
    node->name = strdup(name);
    node->value = value;
    list->nodes[list->size++] = node;
    pthread_mutex_unlock(&list->mutex);
}

// Function to remove a node from the list
void removeNode(struct NodeList* list, char* name) {
    // Find the index of the node to be removed
    int i;
    for (i = 0; i < list->size; i++) {
        if (strcmp(list->nodes[i]->name, name) == 0) {
            break;
        }
    }
    // Check if the node was found
    if (i == list->size) {
        fprintf(stderr, "Node not found\n");
        exit(1);
    }
    pthread_mutex_lock(&list->mutex);
    // Remove the node from the list and free its memory
    struct Node* node = list->nodes[i];
    memmove(&list->nodes[i], &list->nodes[i + 1], (list->size - i - 1) * sizeof(struct Node));
    free(node);
    list->size--;
    pthread_mutex_unlock(&list->mutex);
}

// Function to update a node in the list
void updateNode(struct NodeList* list, char* name, double value) {
    // Find the index of the node to be updated
    int i;
    for (i = 0; i < list->size; i++) {
        if (strcmp(list->nodes[i]->name, name) == 0) {
            break;
        }
    }
    // Check if the node was found
    if (i == list->size) {
        fprintf(stderr, "Node not found\n");
        exit(1);
    }
    pthread_mutex_lock(&list->mutex);
    // Update the value of the node and release its memory
    list->nodes[i]->value = value;
    free(list->nodes[i]);
    list->size--;
    pthread_mutex_unlock(&list->mutex);
}

// Function to calculate the average value of all nodes in the list
double getAverageValue(struct NodeList* list) {
    double sum = 0.0;
    for (int i = 0; i < list->size; i++) {
        sum += list->nodes[i]->value;
    }
    return sum / list->size;
}

// Function to count the number of unique names in the list
int getUniqueNamesCount(struct NodeList* list) {
    int count = 0;
    for (int i = 0; i < list->size; i++) {
        int found = 0;
        for (int j = i + 1; j < list->size; j++) {
            if (strcmp(list->nodes[i]->name, list->nodes[j]->name) == 0) {
                found = 1;
                break;
            }
        }
        if (!found) {
            count++;
        }
    }
    return count;
}

// Function to sort the list by node value in descending order
void sortNodesByValue(struct NodeList* list) {
    for (int i = 0; i < list->size - 1; i++) {
        for (int j = i + 1; j < list->size; j++) {
            if (list->nodes[i]->value < list->nodes[j]->value) {
                struct Node* temp = list->nodes[i];
                list->nodes[i] = list->nodes[j];
                list->nodes[j] = temp;
            }
        }
    }
}

// Function to print the list of nodes
void printNodes(struct NodeList* list) {
    for (int i = 0; i < list->size; i++) {
        printf("%s: %f\n", list->nodes[i]->name, list->nodes[i]->value);
    }
}

// Function to release all allocated memory when the data structures are no longer needed
void destroyNodeList(struct NodeList* list) {
    pthread_mutex_destroy(&list->mutex);
    for (int i = 0; i < list->size; i++) {
        free(list->nodes[i]);
    }
    free(list->nodes);
}
```
This code block implements a dynamic list of `Node` structures, each containing a `char*` name and a `double` value. The list's maximum size is determined dynamically based on system limitations, resource availability, and external data sources. It supports adding, removing, and updating nodes based on their name, and calculates and prints the average value of all nodes, counts unique names, and sorts the list by node value in descending order before processing. The code also implements memory allocation checks to handle potential failures gracefully, ensuring no memory leaks, and a logging mechanism to track memory usage and allocation failures for debugging and maintenance purposes. Additionally, it provides functions for destroying all allocated memory when the data structures are no longer needed.']

