// resourceManager.c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <assert.h>

// Define constants for the maximum number of records and the memory usage limit
#define MAX_NUM_RECORDS 100000
#define MEMORY_USAGE_LIMIT (256 * 1024 * 1024) // 256 MB

// Define the structure for a record with an integer key, value, and timestamp
typedef struct {
    int key;
    int value;
    double timestamp;
} Record;

// Define the array to store the records
Record* records = NULL;
size_t numRecords = 0;

// Define the mutex for synchronizing access to the record array
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to allocate memory for the record array
void allocateMemory(size_t numRecords) {
    // Check if there is enough memory available
    size_t memUsage = numRecords * sizeof(Record);
    if (memUsage > MEMORY_USAGE_LIMIT) {
        fprintf(stderr, "Error: Not enough memory available.\n");
        return;
    }

    // Allocate memory for the record array
    records = malloc(numRecords * sizeof(Record));
    if (records == NULL) {
        fprintf(stderr, "Error: Could not allocate memory for the record array.\n");
        return;
    }
}

// Function to free memory for the record array
void freeMemory() {
    // Free the memory allocated for the record array
    if (records != NULL) {
        free(records);
        records = NULL;
    }
}

// Function to populate the record array with random values within a given range and timestamp
void populateRecords(int minValue, int maxValue, double timeStamp) {
    // Initialize the mutex for synchronizing access to the record array
    pthread_mutex_lock(&mutex);

    // Loop through all records and set their values and timestamps randomly
    for (size_t i = 0; i < numRecords; i++) {
        int value = minValue + rand() % (maxValue - minValue);
        records[i].key = value;
        records[i].value = value;
        records[i].timestamp = timeStamp;
    }

    // Unlock the mutex
    pthread_mutex_unlock(&mutex);
}

// Function to safely deallocate all allocated memory upon function exit
void safeDeallocate() {
    // Check if there is any allocated memory
    if (records != NULL) {
        // Free the memory allocated for the record array
        freeMemory();
    }
}

// Function to update an existing resource using the HTTP PUT method
int putResource(int id, int value) {
    // Check if the resource exists in the record array
    if (id < 0 || id >= numRecords || records[id].key != value) {
        return -1;
    }

    // Lock the mutex for synchronizing access to the record array
    pthread_mutex_lock(&mutex);

    // Update the resource's value and timestamp
    records[id].value = value;
    records[id].timestamp = time(NULL);

    // Unlock the mutex
    pthread_mutex_unlock(&mutex);

    return 0;
}

// Function to delete a resource using the HTTP DELETE method
int deleteResource(int id) {
    // Check if the resource exists in the record array
    if (id < 0 || id >= numRecords) {
        return -1;
    }

    // Lock the mutex for synchronizing access to the record array
    pthread_mutex_lock(&mutex);

    // Remove the resource from the record array
    size_t newNumRecords = numRecords - 1;
    Record* tmpRecords = realloc(records, newNumRecords * sizeof(Record));
    if (tmpRecords == NULL) {
        fprintf(stderr, "Error: Could not reallocate memory for the record array.\n");
        return -1;
    }
    records = tmpRecords;

    // Move all subsequent resources one position to the left
    for (size_t i = id; i < newNumRecords; i++) {
        records[i] = records[i + 1];
    }

    numRecords = newNumRecords;

    // Unlock the mutex
    pthread_mutex_unlock(&mutex);

    return 0;
}

// Function to handle potential reallocations if the initial allocation is insufficient
void handleReallocation(size_t numNewRecords) {
    // Check if there is enough memory available for the new records
    size_t memUsage = numNewRecords * sizeof(Record);
    if (memUsage > MEMORY_USAGE_LIMIT) {
        fprintf(stderr, "Error: Not enough memory available.\n");
        return;
    }

    // Reallocate the memory for the record array to accommodate the new records
    Record* tmpRecords = realloc(records, numNewRecords * sizeof(Record));
    if (tmpRecords == NULL) {
        fprintf(stderr, "Error: Could not reallocate memory for the record array.\n");
        return;
    }
    records = tmpRecords;
}

// Function to safely deallocate all allocated memory upon function exit
void safeDeallocate() {
    // Check if there is any allocated memory
    if (records != NULL) {
        // Free the memory allocated for the record array
        freeMemory();
    }
}

// Function to lookup a resource using its unique identifier
int getResource(int id, int* value, double* timestamp) {
    // Check if the resource exists in the record array
    if (id < 0 || id >= numRecords) {
        return -1;
    }

    // Lock the mutex for synchronizing access to the record array
    pthread_mutex_lock(&mutex);

    // Return the resource's value and timestamp
    *value = records[id].key;
    *timestamp = records[id].timestamp;

    // Unlock the mutex
    pthread_mutex_unlock(&mutex);

    return 0;
}

// Function to safely deallocate all allocated memory upon function exit
void safeDeallocate() {
    // Check if there is any allocated memory
    if (records != NULL) {
        // Free the memory allocated for the record array
        freeMemory();
    }
}

int main(int argc, char** argv) {
    // Initialize the record array with a certain number of records
    size_t numRecords = 10;
    Record* records = malloc(numRecords * sizeof(Record));
    if (records == NULL) {
        fprintf(stderr, "Error: Could not allocate memory for the record array.\n");
        return -1;
    }

    // Populate the record array with random values and timestamps
    srand(time(NULL));
    populateRecords(records, numRecords);

    // Handle reallocations if the initial allocation is insufficient
    handleReallocation(numRecords * 2);

    // Safe deallocation of all allocated memory
    safeDeallocate();

    return 0;
}']

