#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <netinet/in.h>

// Define client connection struct
typedef struct {
    char *ip_addr;
    uint16_t port;
    int socket_desc;
} client_conn_t;

// Define message queue node struct
typedef struct {
    char *payload;
    time_t timestamp;
} msg_node_t;

// Define message queue struct
typedef struct {
    size_t capacity;
    size_t size;
    msg_node_t *head;
    msg_node_t *tail;
} msg_queue_t;

// Define memory pool for client connections and message queues
typedef struct {
    size_t max_mem_usage; // Maximum allowed memory usage (in bytes)
    size_t reallocs; // Number of times memory has been reallocated
    size_t avg_msg_proc_time; // Average time spent processing messages (in milliseconds)
    client_conn_t *clients; // Array of client connections
    msg_queue_t *queues; // Array of message queues
} mem_pool_t;

// Initialize memory pool and allocate space for clients and message queues
void init_mem_pool(mem_pool_t *mp, size_t num_clients, size_t msg_queue_capacity) {
    mp->max_mem_usage = 0;
    mp->reallocs = 0;
    mp->avg_msg_proc_time = 0;
    mp->clients = malloc(sizeof(client_conn_t) * num_clients);
    memset(mp->clients, 0, sizeof(client_conn_t) * num_clients);
    mp->queues = malloc(sizeof(msg_queue_t) * num_clients);
    memset(mp->queues, 0, sizeof(msg_queue_t) * num_clients);
}

// Destroy memory pool and deallocate all allocated memory
void destroy_mem_pool(mem_pool_t *mp) {
    free(mp->clients);
    mp->clients = NULL;
    for (size_t i = 0; i < mp->num_clients; i++) {
        if (mp->queues[i].head != NULL) {
            msg_node_t *tmp = mp->queues[i].head;
            while (tmp != NULL) {
                free(tmp->payload);
                tmp = tmp->next;
            }
            free(mp->queues[i].head);
        }
    }
    free(mp->queues);
    mp->queues = NULL;
}

// Add a new client connection to the memory pool and allocate space for its message queue
void add_client(mem_pool_t *mp, const char *ip_addr, uint16_t port) {
    // Check if there is enough space in the memory pool for another client connection
    if (mp->max_mem_usage + sizeof(client_conn_t) > mp->max_mem_limit) {
        printf("ERROR: Memory limit exceeded\n");
        return;
    }

    // Allocate space for the new client connection and message queue
    size_t i = 0;
    while (mp->clients[i].socket_desc != -1) {
        i++;
    }
    mp->clients[i].ip_addr = strdup(ip_addr);
    mp->clients[i].port = port;
    mp->queues[i].capacity = msg_queue_capacity;
    mp->queues[i].size = 0;
    mp->queues[i].head = NULL;
    mp->queues[i].tail = NULL;
}

// Remove a client connection from the memory pool and deallocate its message queue
void remove_client(mem_pool_t *mp, const char *ip_addr, uint16_t port) {
    size_t i = 0;
    while (i < mp->num_clients && !(strcmp(mp->clients[i].ip_addr, ip_addr) == 0 && mp->clients[i].port == port)) {
        i++;
    }
    if (i >= mp->num_clients) {
        printf("ERROR: Could not find client connection to remove\n");
        return;
    }
    free(mp->clients[i].ip_addr);
    mp->clients[i].socket_desc = -1;
    for (size_t j = 0; j < mp->queues[i].size; j++) {
        msg_node_t *tmp = mp->queues[i].head;
        if (j == 0) {
            free(mp->queues[i].head);
            mp->queues[i].head = NULL;
        } else {
            while (tmp->next != NULL && j != 0) {
                tmp = tmp->next;
                j--;
            }
            if (j == 0) {
                free(tmp->next);
                tmp->next = NULL;
            }
        }
    }
    mp->queues[i].size = 0;
}

// Add a new message to the memory pool for a client connection and allocate space for its payload
void add_message(mem_pool_t *mp, const char *ip_addr, uint16_t port, size_t msg_len) {
    // Find the client connection with the specified IP address and port
    size_t i = 0;
    while (i < mp->num_clients && !(strcmp(mp->clients[i].ip_addr, ip_addr) == 0 && mp->clients[i].port == port)) {
        i++;
    }
    if (i >= mp->num_clients) {
        printf("ERROR: Could not find client connection to add message\n");
        return;
    }

    // Check if there is enough space in the memory pool for another message
    size_t new_size = mp->queues[i].size + 1;
    if (mp->max_mem_usage + msg_len > mp->max_mem_limit) {
        printf("ERROR: Memory limit exceeded\n");
        return;
    } else if (new_size * sizeof(msg_node_t) > mp->queues[i].capacity) {
        // Reallocate the message queue to increase its capacity
        msg_queue_t *tmp = realloc(mp->queues[i], new_size * sizeof(msg_queue_t));
        if (tmp == NULL) {
            printf("ERROR: Could not allocate memory for message\n");
            return;
        } else {
            mp->queues[i] = tmp;
            mp->max_mem_usage += msg_len;
        }
    }

    // Allocate space for the new message's payload and add it to the queue
    size_t j = 0;
    while (j < mp->queues[i].size && !(mp->queues[i].head != NULL && mp->queues[i].tail != NULL)) {
        j++;
    }
    if (j >= mp->queues[i].size) {
        printf("ERROR: Could not find message queue to add message\n");
        return;
    }
    msg_node_t *new_node = malloc(sizeof(msg_node_t));
    if (new_node == NULL) {
        printf("ERROR: Could not allocate memory for message\n");
        return;
    } else {
        new_node->payload = malloc(msg_len);
        if (new_node->payload == NULL) {
            free(new_node);
            printf("ERROR: Could not allocate memory for message payload\n");
            return;
        } else {
            mp->queues[i].size++;
            mp->max_mem_usage += msg_len;
        }
    }
}

// Remove a message from the memory pool for a client connection and deallocate its payload
void remove_message(mem_pool_t *mp, const char *ip_addr, uint16_t port, size_t index) {
    // Find the client connection with the specified IP address and port
    size_t i = 0;
    while (i < mp->num_clients && !(strcmp(mp->clients[i].ip_addr, ip_addr) == 0 && mp->clients[i].port == port)) {
        i++;
    }
    if (i >= mp->num_clients) {
        printf("ERROR: Could not find client connection to remove message\n");
        return;
    }

    // Check if the index is out of range for the message queue
    size_t j = 0;
    while (j < mp->queues[i].size && !(mp->queues[i].head != NULL && mp->queues[i].tail != NULL)) {
        j++;
    }
    if (j > index) {
        printf("ERROR: Index out of range\n");
        return;
    }

    // Remove the message from the queue and deallocate its payload
    msg_node_t *tmp = mp->queues[i].head;
    if (index == 0) {
        free(mp->queues[i].head);
        tmp = tmp->next;
        mp->queues[i].head = tmp;
        mp->max_mem_usage -= sizeof(msg_node_t);
    } else {
        while (tmp != NULL && j != 0) {
            tmp = tmp->next;
            j--;
        }
        if (j == 0) {
            free(mp->queues[i].head);
            mp->queues[i].head = tmp;
            mp->max_mem_usage -= sizeof(msg_node_t);
        }
    }
}

// Print the memory usage of the memory pool
void print_memory_usage(mem_pool_t *mp) {
    printf("Memory usage: %lu\n", mp->max_mem_usage);
}
```

This code implements a memory pool for storing client connections and messages. The `add_client` function adds a new client connection to the memory pool, allocating space for its message queue. The `remove_client` function removes a client connection from the memory pool and deallocates its message queue. The `add_message` function adds a new message to the memory pool for a client connection, allocating space for its payload. The `remove_message` function removes a message from the memory pool for a client connection and deallocates its payload. The `print_memory_usage` function prints the memory usage of the memory pool.

The memory pool uses a linked list to store the messages for each client connection, with each node in the list representing a single message. The `msg_node_t` struct is used to represent an individual message, with the `payload` field containing the actual message data and the `next` field pointing to the next message in the queue.

The memory pool uses a fixed-size array to store the client connections, with each element in the array representing a single client connection. The `client_t` struct is used to represent an individual client connection, with the `msg_queue` field containing a pointer to the linked list of messages for that client and the `next` field pointing to the next client in the array.

The memory pool uses the `max_mem_usage` variable to keep track of the maximum amount of memory it has allocated so far, and the `num_clients` variable to keep track of the number of client connections currently stored in the memory pool. The `add_client` and `remove_client` functions update these variables as necessary.

The `print_memory_usage` function is a utility function that can be used to print the current memory usage of the memory pool, which can be useful for debugging purposes.']

