// Define a buffer for incoming data from the network socket
char buffer[BUFSIZ];

int processAndFindMax(int sockfd) {
    // Initialize variables for memory management
    int *offsets = (int *)malloc(sizeof(int) * MAX_OFFSET_ARRAY);
    int *keys = (int *)malloc(sizeof(int) * MAX_KEYS_ARRAY);
    Record *records = (Record *)malloc(sizeof(Record) * MAX_RECORDS_ARRAY);

    // Initialize variables for duplicate key detection and offset updates
    int maxKey = 0;
    int minOffset = INT_MAX;
    int maxOffset = INT_MIN;

    // Loop until the connection is closed
    while (1) {
        // Read a record from the network socket
        ssize_t bytesRead = read(sockfd, buffer, BUFSIZ);
        if (bytesRead <= 0) break;

        // Parse the record and update variables for duplicate key detection and offset updates
        Record *record = (Record *)buffer;
        int key = record->value;
        if (key > maxKey) {
            maxKey = key;
        }
        offsets[numOffsets++] = (int)(record->timestamp - currentTime);
        minOffset = MIN(minOffset, offsets[numOffsets-1]);
        maxOffset = MAX(maxOffset, offsets[numOffsets-1]);

        // Check for duplicate keys and update the offset values accordingly
        if (keyExists(keys, key)) {
            int index = getKeyIndex(keys, key);
            records[index].offset += offsets[numOffsets-1];
        } else {
            insertKey(keys, key);
            insertRecord(records, record->value, record->timestamp);
        }
    }

    // Clean up memory and return the maximum offset value
    free(offsets);
    free(keys);
    free(records);
    return maxOffset;
}

int getKeyIndex(int *keys, int key) {
    for (int i = 0; i < numKeys; i++) {
        if (keys[i] == key) {
            return i;
        }
    }
    return -1;
}

bool keyExists(int *keys, int key) {
    for (int i = 0; i < numKeys; i++) {
        if (keys[i] == key) {
            return true;
        }
    }
    return false;
}

void insertKey(int *keys, int key) {
    keys[numKeys++] = key;
}

void insertRecord(Record *records, int value, double timestamp) {
    records[numRecords++].value = value;
}
