        return -1;
    }

    // Initialize the records with random values and unique strings
    for (size_t i = 0; i < num_records; i++) {
        (*records)[i].value = rand() % (max_value - min_value + 1) + min_value;
        (*records)[i].timestamp = millis;
        snprintf((*records)[i].string, sizeof((*records)[i].string), "Record %zu", i);
    }

    // Apply the filtering mechanism to retain only records within the specified range
    size_t filtered_count = 0;
    for (size_t i = 0; i < num_records; i++) {
        if ((*records)[i].value >= min_value && (*records)[i].value <= max_value) {
            filtered_count++;
        } else {
            free((*records)[i]);
        }
    }

    // Update the number of records to reflect the filtered count
    *num_records = filtered_count;

    return 0;
}

