// Define the person data structure
typedef struct {
    int ID;
    char name[256];
    int age;
} Person;

// Define the activity record structure
typedef struct {
    long timestamp;
    char activity_type[256];
    int duration;
} Activity;

// Define the array of person objects
Person *people = NULL;

// Define the hash table for quick lookups by ID
void *person_id_hash_table = NULL;

// Define the array of activity records
Activity *activities = NULL;

// Function to initialize the data structures
void init() {
    // Allocate memory for the person array and initialize it with 10 elements
    people = (Person *)malloc(sizeof(Person) * 10);
    memset(people, 0, sizeof(Person) * 10);

    // Allocate memory for the hash table and initialize it with 10 buckets
    person_id_hash_table = (void *)calloc(10, sizeof(void *));

    // Allocate memory for the activity array and initialize it with 10 elements
    activities = (Activity *)malloc(sizeof(Activity) * 10);
    memset(activities, 0, sizeof(Activity) * 10);
}

// Function to populate the data structures with predefined activity types and durations
void populate() {
    // Populate the person array with 5 elements
    for (int i = 0; i < 5; i++) {
        people[i].ID = i + 1;
        sprintf(people[i].name, "Person %d", i + 1);
        people[i].age = 25 + i;
    }

    // Populate the hash table with 5 buckets and assign each bucket to a person ID
    for (int i = 0; i < 5; i++) {
        int id = people[i].ID;
        void **bucket = &person_id_hash_table[id];
        *bucket = (void *)malloc(sizeof(void *));
        memcpy(*bucket, &people[i], sizeof(Person));
    }

    // Populate the activity array with 10 elements
    for (int i = 0; i < 10; i++) {
        activities[i].timestamp = time(NULL) * 1000 + i;
        sprintf(activities[i].activity_type, "Activity %d", i);
        activities[i].duration = 30 + i * 5;
    }
}

// Function to update the total duration of an activity record based on a person's age
void update_duration(int id) {
    // Get the person object from the hash table using the ID
    Person *person = (Person *)person_id_hash_table[id];

    // Update the duration of each activity record based on the person's age
    for (int i = 0; i < 10; i++) {
        int duration = activities[i].duration + ((person->age - 25) * 5);
        if (duration > 360) {
            duration = 360;
        } else if (duration < 30) {
            duration = 30;
        }
        activities[i].duration = duration;
    }
}

// Main function to demonstrate the use of the data structures
int main() {
    init();
    populate();
    update_duration(1);
    for (int i = 0; i < 10; i++) {
        printf("Activity %d: %ld - %s - %d\n", i + 1, activities[i].timestamp, activities[i].activity_type, activities[i].duration);
    }
    free(people);
    free(activities);
    free(person_id_hash_table);
    return 0;
}
```
