#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <time.h>

// Define the record structure to hold data for each record
struct Record {
    int value;
    double timestamp;
    char* string_value;
    short status_code;
};

// Define an array of pointers to store offsets, keys, and records
long* offsets = NULL;
int* keys = NULL;
struct Record** records = NULL;

// Define a memory pool for reusing memory blocks
#define MEMORY_POOL_SIZE 1024 * 1024 * 32 // 32 MB
char memory_pool[MEMORY_POOL_SIZE];
int memory_pool_used = 0;

// Define a function to allocate memory from the pool
void* memory_alloc(size_t size) {
    if (memory_pool_used + size > MEMORY_POOL_SIZE) {
        // Handle memory allocation failure by returning NULL
        return NULL;
    }
    void* ptr = &memory_pool[memory_pool_used];
    memory_pool_used += size;
    return ptr;
}

// Define a function to free memory from the pool
void memory_free(void* ptr) {
    // Handle null pointers by returning early
    if (ptr == NULL) {
        return;
    }
    // Calculate the memory block size and adjust the used memory counter
    size_t size = *((size_t*)ptr - 1);
    memory_pool_used -= size;
}

// Define a function to initialize the data structures
void init(int num_records) {
    // Allocate memory for the offsets and keys arrays
    offsets = (long*)memory_alloc(num_records * sizeof(long));
    if (offsets == NULL) {
        return;
    }
    keys = (int*)memory_alloc(num_records * sizeof(int));
    if (keys == NULL) {
        memory_free(offsets);
        offsets = NULL;
        return;
    }
    // Allocate memory for the records array
    records = (struct Record**)memory_alloc(num_records * sizeof(struct Record*));
    if (records == NULL) {
        memory_free(offsets);
        offsets = NULL;
        memory_free(keys);
        keys = NULL;
        return;
    }
}

// Define a function to add a new record to the data structures
void add_record(int key, long offset, struct Record* record) {
    // Check if there is enough memory available for the record
    size_t record_size = sizeof(struct Record);
    if (memory_pool_used + record_size > MEMORY_POOL_SIZE) {
        return;
    }
    // Allocate a new record from the pool
    struct Record* new_record = (struct Record*)memory_alloc(record_size);
    if (new_record == NULL) {
        return;
    }
    // Copy the contents of the input record to the new record
    memcpy(new_record, record, record_size);
    // Update the offsets and keys arrays
    offsets[key] = offset;
    keys[offset] = key;
    // Store the pointer to the new record in the records array
