    int result = mkdir(dirname, S_IRWXU | S_IRWXG | S_IROTH | S_IXOTH);

    // Unlock the mutex
    pthread_mutex_unlock(&lock);

    return result;
}

// Function to configure environment variables and directories for a multi-threaded application
void configureEnvironmentForMultiThreadedApp(Config* config) {
    // Iterate over each directory in the configuration structure
    for (int i = 0; i < config->numDirs; i++) {
        // Create the directory if it does not exist
        if (!access(config->dirNames[i], F_OK)) {
            continue;
        } else {
            mkdir(config->dirNames[i]);
        }
    }

    // Iterate over each environment variable in the configuration structure
    for (int i = 0; i < config->numEnvVars; i++) {
        // Update the environment variable if it exists
        if (!access(config->envVarNames[i], F_OK)) {
            setenv(config->envVarNames[i], config->envVarValues[i]);
        } else {
            // Create a new environment variable if it does not exist
            setenv(config->envVarNames[i], config->envVarValues[i], 1);
        }
    }
}
```
