            int attackID;
            for (int i = 0; i < bytesRead; i++) {
                if (buffer[i] == '\n') {
                    ss << buffer[i];
                    if (ss >> attackID) {
                        // add attack ID to the list of predefined attacks
                        attackIDs[attackID - 100] = attackID;
                        logEntries[i].status = 'A';
                        logEntries[i].timestamp = time(NULL);
                    } else {
                        // add string to the list of predefined strings
                        logEntries[i].status = 'S';
                        logEntries[i].timestamp = time(NULL);
                    }
                }
            }

            // select one of two predefined attacks for a game character
            int selectedAttackID = -1;
            for (int i = 0; i < 2; i++) {
                if (attackIDs[i] != -1) {
                    selectedAttackID = attackIDs[i];
                    break;
                }
            }

            // print the selected attack number
            cout << "Selected attack ID: " << selectedAttackID << endl;

            // release resources
