// Define the record structure
typedef struct {
    int key;
    long offset;
    double timestamp;
    char* metadata;
} Record;

// Define the function to dynamically manage memory for an array of records
void manage_memory(Record** records, size_t num_records, size_t metadata_length) {
    // Initialize a mutex for thread-safe access
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Allocate memory for the records array
    *records = (Record*) malloc(num_records * sizeof(Record));
    if (*records == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for records\n");
        return;
    }

    // Initialize each record with a random integer within the specified range and set the timestamp
    srand(time(NULL));
    for (size_t i = 0; i < num_records; ++i) {
        int key = rand() % 100 + 1;
        long offset = i * sizeof(Record);
        double timestamp = get_timestamp();
        (*records)[i].key = key;
        (*records)[i].offset = offset;
        (*records)[i].timestamp = timestamp;

        // Generate a random alphanumeric sequence for the metadata string
        char* metadata = (char*) malloc(metadata_length * sizeof(char));
        if (metadata == NULL) {
            fprintf(stderr, "Error: Failed to allocate memory for metadata\n");
            return;
        }
        generate_metadata(metadata, metadata_length);
        (*records)[i].metadata = metadata;
    }

    // Periodically flush the records array to a persistent storage system
    pthread_mutex_lock(&mutex);
    for (size_t i = 0; i < num_records; ++i) {
        fwrite(*records, sizeof(Record), 1, stdout);
        free((*records)[i].metadata);
    }
    pthread_mutex_unlock(&mutex);

    // Free all allocated resources upon successful completion or early exit due to an error
    pthread_mutex_destroy(&mutex);
    free(*records);
}

// Generate a random alphanumeric sequence for the metadata string
void generate_metadata(char* metadata, size_t length) {
    srand(time(NULL));
    for (size_t i = 0; i < length; ++i) {
        char c = rand() % 128 + 'a';
        if (c >= 'A' && c <= 'Z') {
            metadata[i] = c;
        } else if (c >= 'a' && c <= 'z') {
            metadata[i] = c;
        } else if (c >= '0' && c <= '9') {
            metadata[i] = c;
        } else {
            i--;
        }
    }
}

// Get the current time in milliseconds since the epoch
double get_timestamp() {
