// Define a hash table data structure for the secondary index
typedef struct {
    size_t capacity;
    size_t size;
    struct record** buckets;
} hash_table;

int create_record(struct record* record, int key, double timestamp) {
    // Initialize the record fields with the given values
    record->key = key;
    record->timestamp = timestamp;
    return 0;
}

int create_hash_table(hash_table* table, size_t capacity) {
    // Allocate memory for the hash table buckets
    table->buckets = (struct record**)malloc(sizeof(struct record*) * capacity);
    if (!table->buckets) {
        return -1; // Memory allocation failed
    }
    table->capacity = capacity;
    table->size = 0;
    return 0;
}

int insert_record(hash_table* table, struct record* record) {
    // Generate a hash value for the record key
    unsigned long hash = record->key % table->capacity;

    // Check if the bucket is already occupied
    if (table->buckets[hash]) {
        // Collision resolution: rehash the key and try again
        hash = (hash + 1) % table->capacity;
    }

    // Insert the record into the bucket
    table->buckets[hash] = record;
    table->size++;
    return 0;
}

int find_record(hash_table* table, int key) {
    // Generate a hash value for the search key
    unsigned long hash = key % table->capacity;

    // Search for the record in the bucket
    while (table->buckets[hash]) {
        if (table->buckets[hash]->key == key) {
            return 0; // Record found
        }
        // Collision resolution: rehash the key and try again
        hash = (hash + 1) % table->capacity;
    }
    return -1; // Record not found
}

int delete_record(hash_table* table, int key) {
    // Generate a hash value for the search key
    unsigned long hash = key % table->capacity;

    // Search for the record in the bucket
    while (table->buckets[hash]) {
        if (table->buckets[hash]->key == key) {
            free(table->buckets[hash]);
            table->buckets[hash] = NULL;
            table->size--;
            return 0; // Record deleted
        }
        // Collision resolution: rehash the key and try again
        hash = (hash + 1) % table->capacity;
    }
    return -1; // Record not found
}

