                max_key = current_key;
                max_timestamp = new_record->timestamp;
            }
        }
    }

    // Free the allocated memory for the offset values and key values arrays
    free(offset_values_allocated);
    free(key_values_allocated);

    // Print the maximum value and its corresponding timestamp
