    size_t memoryPoolSize = 1024 * 1024; // 1MB
    void* memoryPool = malloc(memoryPoolSize);
    if (memoryPool == NULL) {
        perror("Failed to allocate memory pool");
        fclose(fp);
        return;
    }

    // Initialize variables for tracking weather records and memory allocation
    size_t recordCount = 0;
    size_t allocatedMemory = 0;

    // Read the CSV file line by line and parse each line as a weather record
    char* line = NULL;
    size_t lineSize = 0;
    ssize_t readBytes;
    while ((readBytes = getline(&line, &lineSize, fp)) != -1) {
        // Ignore empty lines and comments
        if (strlen(line) == 0 || strchr(line, '#')) {
            continue;
        }

        // Parse the line as a weather record using strtok
        char* token = strtok(line, ",");
        if (token == NULL) {
            fprintf(stderr, "Failed to parse weather record: %s\n", line);
            continue;
        }

        // Allocate memory for the current weather record
        size_t recordSize = sizeof(weatherRecord) + strlen(token) + 1;
        void* recordMemory = memoryPool + allocatedMemory;
        if (recordCount >= memoryPoolSize / recordSize) {
            // Reached the end of the memory pool, reallocate more memory
            size_t newMemoryPoolSize = memoryPoolSize * 2;
            void* newMemoryPool = realloc(memoryPool, newMemoryPoolSize);
            if (newMemoryPool == NULL) {
                perror("Failed to reallocate memory pool");
                fclose(fp);
                return;
            }
            memoryPool = newMemoryPool;
            allocatedMemory += newMemoryPoolSize - memoryPoolSize;
        }

        // Copy the token as the city name and timestamp
        weatherRecord* record = (weatherRecord*)recordMemory;
        record->cityName = (char*)recordMemory + sizeof(weatherRecord);
        strcpy(record->cityName, token);
        record->timestamp = time(NULL);

        // Parse the remaining tokens as temperatures and store them in the array
        int i = 0;
        while ((token = strtok(NULL, ",")) != NULL) {
            if (i >= MAX_TEMPERATURES) {
                fprintf(stderr, "Maximum number of temperatures exceeded: %s\n", token);
                break;
            }
            record->temperature[i] = atof(token);
            i++;
        }

        // Increment the record count and update the allocated memory size
        recordCount++;
        allocatedMemory += sizeof(weatherRecord) + strlen(record->cityName) + 1;
    }

    // Clean up resources
    fclose(fp);
    free(line);
    if (memoryPool != NULL) {
        free(memoryPool);
    }
}
