    size_t size;
    void* memory;
};

struct ThreadArgs {
    pthread_mutex_t* mutex;
    struct MemoryPool* pool;
    int streamId;
    struct StreamData** data;
};

void* processAndAggregateData(void* args) {
    struct ThreadArgs* threadArgs = (struct ThreadArgs*)args;
    pthread_mutex_lock(threadArgs->mutex);

    // Allocate memory for the stream data
    size_t dataSize = sizeof(struct StreamData) * 1000;
    void* dataMemory = malloc(dataSize);
    if (!dataMemory) {
        pthread_mutex_unlock(threadArgs->mutex);
        return NULL;
    }

    // Initialize the memory pool for this stream
    struct MemoryPool* pool = (struct MemoryPool*)malloc(sizeof(struct MemoryPool));
    if (!pool) {
        free(dataMemory);
        pthread_mutex_unlock(threadArgs->mutex);
        return NULL;
    }

    pool->size = dataSize;
    pool->memory = dataMemory;

    // Initialize the offset for this stream
    threadArgs->offset = 0;

    // Set up the data structures for this stream
    struct StreamData** data = (struct StreamData**)malloc(sizeof(struct StreamData*) * 1000);
    if (!data) {
        free(pool);
        free(dataMemory);
        pthread_mutex_unlock(threadArgs->mutex);
        return NULL;
    }

    for (int i = 0; i < 1000; i++) {
        data[i] = (struct StreamData*)((char*)dataMemory + i * sizeof(struct StreamData));
    }

    threadArgs->data = data;
    threadArgs->pool = pool;

    // Process the stream data
    while (1) {
        pthread_mutex_lock(threadArgs->mutex);
        struct StreamData* dataPtr = *threadArgs->data[threadArgs->offset];
        if (!dataPtr) {
            break;
        }

        // Process the record
        int value = dataPtr->value;
        double timestamp = dataPtr->timestamp;

        // Update the offset for this stream
        threadArgs->offset++;

        pthread_mutex_unlock(threadArgs->mutex);
    }

    free(data);
    free(pool);
    free(dataMemory);
    pthread_mutex_unlock(threadArgs->mutex);
    return NULL;
}

int main() {
    // Initialize the mutex for thread synchronization
    pthread_mutex_t* mutex = (pthread_mutex_t*)malloc(sizeof(pthread_mutex_t));
    if (!mutex) {
        return 1;
    }

    pthread_mutex_init(mutex, NULL);

    // Initialize the stream data structures
    struct StreamData** data = (struct StreamData**)malloc(sizeof(struct StreamData*) * 200);
    if (!data) {
        free(mutex);
        return 1;
    }

    for (int i = 0; i < 200; i++) {
        data[i] = NULL;
    }

    // Create a thread for each stream
    pthread_t threads[200];
    for (int i = 0; i < 200; i++) {
        struct ThreadArgs* threadArgs = (struct ThreadArgs*)malloc(sizeof(struct ThreadArgs));
        if (!threadArgs) {
            free(data);
            free(mutex);
            return 1;
        }

        threadArgs->mutex = mutex;
        threadArgs->pool = NULL;
        threadArgs->streamId = i;
        threadArgs->data = data;

        pthread_create(&threads[i], NULL, processAndAggregateData, (void*)threadArgs);
    }

    // Join the threads
    for (int i = 0; i < 200; i++) {
        pthread_join(threads[i], NULL);
    }

    free(data);
    free(mutex);
    return 0;
}
