        for (int j = 0; j < n; j++) {
            if (i == j) continue; // Skip self-comparisons
            int parent1 = find(uf, i);
            int parent2 = find(uf, j);
            if (parent1 != parent2) {
                is_disjoint = false;
                break;
            }
        }
        count += is_disjoint ? 1 : 0;
    }

    // Clean up the Union-Find data structure
    destroy_uf(uf);

    return count;
}

// Function to measure and print the execution time for each disjoint pair check in milliseconds
void test_disjoint_pairs(int* array, int n) {
    clock_t start = clock();
    int count = count_disjoint_pairs(array, n);
    clock_t end = clock();
    double time = (double)(end - start) / CLOCKS_PER_SEC;
    printf("Number of disjoint pairs: %d\n", count);
    printf("Execution time in milliseconds: %.2f\n", time * 1000);
}

int main() {
    // Define the size of the input array
    int n = 10;

    // Dynamically allocate memory for and initialize three arrays: one for 'long' offsets, one for 'int' keys, and one for 'record' structures
    long* offsets;
    int* keys;
    record** records;
    initialize_arrays(n, &offsets, &keys, &records);

    // Print the arrays to demonstrate that they are correctly initialized
    printf("Offset array:\n");
    for (int i = 0; i < n; i++) {
        printf("%ld ", offsets[i]);
    }
    printf("\n");
    printf("Key array:\n");
    for (int i = 0; i < n; i++) {
        printf("%d ", keys[i]);
    }
    printf("\n");
    printf("Record array:\n");
    for (int i = 0; i < n; i++) {
        printf("(%d, %ld, %d) ", records[i]->value, *(records[i]->offset), *(records[i]->key));
    }
    printf("\n");

    // Test the function to count the number of disjoint pairs in an integer array
    test_disjoint_pairs(array, n);

    // Clean up memory allocated for the arrays
    free(offsets);
    free(keys);
    free(records);

    return 0;
}
