// ProjectTask structure definition
typedef struct projectTask {
    int projectId;
    enum status { planned, active, completed } status;
    char* description;
    int priority;
} ProjectTask;

// Memory allocator for custom memory management
void* malloc_wrapper(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        printf("Error: Failed to allocate %zu bytes of memory\n", size);
        return NULL;
    }
    return ptr;
}

// Function to manage dynamic memory allocation for a list of ProjectTask structures
ProjectTask* manageTasks(ProjectTask* tasks, int num_tasks) {
    if (tasks == NULL || num_tasks < 0) {
        printf("Error: Invalid input parameters\n");
        return NULL;
    }

    // Initialize linked list of ProjectTask structures
    ProjectTask* head = NULL;
    for (int i = 0; i < num_tasks; i++) {
        ProjectTask* task = malloc_wrapper(sizeof(ProjectTask));
        if (task == NULL) {
            printf("Error: Failed to allocate memory for task %d\n", i);
            return NULL;
        }
        task->projectId = tasks[i].projectId;
        task->status = tasks[i].status;
        task->description = strdup(tasks[i].description);
        task->priority = tasks[i].priority;
        head = insertTask(head, task);
    }

    return head;
}

// Function to initialize a linked list of ProjectTask structures
ProjectTask* insertTask(ProjectTask* head, ProjectTask* task) {
    if (task == NULL || head == NULL) {
        printf("Error: Invalid input parameters\n");
        return NULL;
    }

    // Add new task to linked list
    task->next = head;
    return task;
}

// Function to query a ProjectTask structure based on its status or priority
ProjectTask* queryTasks(ProjectTask* head, int status, int priority) {
    if (head == NULL) {
        printf("Error: No tasks available\n");
        return NULL;
    }

    // Traverse linked list and find matching task based on status or priority
    ProjectTask* curr = head;
    while (curr != NULL) {
        if ((status == -1 || curr->status == status) &&
                (priority == -1 || curr->priority == priority)) {
            return curr;
        }
        curr = curr->next;
    }
    printf("Error: No matching tasks found\n");
    return NULL;
}

// Function to free memory allocated for a linked list of ProjectTask structures
void freeTasks(ProjectTask* head) {
    if (head == NULL) {
        printf("Error: No tasks available\n");
        return;
    }

    // Free all nodes in linked list
    ProjectTask* curr = head;
    while (curr != NULL) {
        ProjectTask* next = curr->next;
        free(curr);
        curr = next;
    }
}
