#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/time.h>

// Third-party library for task persistence
#ifdef USE_PERSISTENCE
    #include "persistence.h"
#endif

// Macro definitions
#define MAX_TASKS 1000 // Maximum number of tasks allowed in the collection
#define MIN_PRIORITY 0 // Minimum priority level for a task
#define MAX_PRIORITY 10 // Maximum priority level for a task
#define DEFAULT_PERSISTENCE_FREQUENCY 60 // Default persistence frequency in seconds
#define MIN_MEMORY_ALLOCATION 8 // Minimum memory allocation size (in bytes)

// Data structure definitions
typedef struct {
    char* name; // Task name
    int priority; // Priority level
    struct timeval startTime; // Start time of the task
    struct timeval endTime; // End time of the task
} Task;

typedef struct {
    int size; // Size of the collection
    int count; // Number of tasks in the collection
    Task* tasks[MAX_TASKS]; // Array of tasks
} TaskCollection;

// Function prototypes
TaskCollection* createTaskCollection();
void destroyTaskCollection(TaskCollection* collection);
int addTask(TaskCollection* collection, const char* name, int priority, struct timeval startTime, struct timeval endTime);
void removeTask(TaskCollection* collection, int index);
void updateTask(TaskCollection* collection, int index, const char* name, int priority, struct timeval startTime, struct timeval endTime);
void printTasks(TaskCollection* collection);
int getTaskCount(TaskCollection* collection);
Task* getTask(TaskCollection* collection, int index);
void setPersistenceFrequency(TaskCollection* collection, unsigned long frequency);
unsigned long getPersistenceFrequency(TaskCollection* collection);
void persistTasks(TaskCollection* collection);
int fetchTasks(TaskCollection* collection);

// Implementation

/**
 * Creates a new task collection.
 */
TaskCollection* createTaskCollection() {
    TaskCollection* collection = malloc(sizeof(TaskCollection));
    if (collection == NULL) {
        fprintf(stderr, "Failed to allocate memory for the task collection\n");
        return NULL;
    }
    collection->size = 0;
    collection->count = 0;
    memset(collection->tasks, 0, MAX_TASKS * sizeof(Task*));
    return collection;
}

/**
 * Destroys a task collection.
 */
void destroyTaskCollection(TaskCollection* collection) {
    if (collection == NULL) {
        return;
    }
    for (int i = 0; i < MAX_TASKS && i < collection->size; i++) {
        free(collection->tasks[i]);
    }
    free(collection);
}

/**
 * Adds a new task to the collection.
 */
int addTask(TaskCollection* collection, const char* name, int priority, struct timeval startTime, struct timeval endTime) {
    if (collection == NULL || name == NULL || priority < MIN_PRIORITY || priority > MAX_PRIORITY) {
        return -1;
    }
    // Check if the task already exists
    for (int i = 0; i < collection->count; i++) {
        Task* task = collection->tasks[i];
        if (strcmp(task->name, name) == 0) {
            fprintf(stderr, "A task with the same name already exists\n");
            return -1;
        }
    }
    // Check if the collection is full
    if (collection->size >= MAX_TASKS) {
        fprintf(stderr, "The task collection is full\n");
        return -1;
    }
    // Create a new task
    Task* task = malloc(sizeof(Task));
    if (task == NULL) {
        fprintf(stderr, "Failed to allocate memory for the new task\n");
        return -1;
    }
    strcpy(task->name, name);
    task->priority = priority;
    task->startTime = startTime;
    task->endTime = endTime;
    collection->tasks[collection->size] = task;
    collection->count++;
    collection->size++;
    return 0;
}

/**
 * Removes a task from the collection.
 */
void removeTask(TaskCollection* collection, int index) {
    if (collection == NULL || index < 0 || index >= collection->count) {
        fprintf(stderr, "Invalid task index\n");
        return;
    }
    Task* task = collection->tasks[index];
    free(task);
    for (int i = index + 1; i < collection->size; i++) {
        collection->tasks[i - 1] = collection->tasks[i];
    }
    collection->count--;
    collection->size--;
}

/**
 * Updates a task in the collection.
 */
void updateTask(TaskCollection* collection, int index, const char* name, int priority, struct timeval startTime, struct timeval endTime) {
    if (collection == NULL || index < 0 || index >= collection->count) {
        fprintf(stderr, "Invalid task index\n");
        return;
    }
    Task* task = collection->tasks[index];
    strcpy(task->name, name);
    task->priority = priority;
    task->startTime = startTime;
    task->endTime = endTime;
}

/**
 * Prints all tasks in the collection.
 */
void printTasks(TaskCollection* collection) {
    if (collection == NULL || collection->count <= 0) {
        fprintf(stderr, "No tasks found\n");
        return;
    }
    printf("Task Collection:\n");
    for (int i = 0; i < collection->count; i++) {
        Task* task = collection->tasks[i];
        printf("%d. %s: priority=%d, startTime=%ld, endTime=%ld\n", i + 1, task->name, task->priority, task->startTime, task->endTime);
    }
}

/**
 * Sets the persistence frequency for the collection.
 */
void setPersistenceFrequency(TaskCollection* collection, unsigned long frequency) {
    if (collection == NULL) {
        return;
    }
    collection->persistenceFrequency = frequency;
}

/**
 * Gets the persistence frequency for the collection.
 */
unsigned long getPersistenceFrequency(TaskCollection* collection) {
    if (collection == NULL) {
        return 0;
    }
    return collection->persistenceFrequency;
}

/**
 * Persists tasks to a file.
 */
void persistTasks(TaskCollection* collection) {
    if (collection == NULL) {
        return;
    }
    FILE* file = fopen("tasks.txt", "w");
    for (int i = 0; i < collection->count; i++) {
        Task* task = collection->tasks[i];
        fprintf(file, "%s %d %ld %ld\n", task->name, task->priority, task->startTime, task->endTime);
    }
    fclose(file);
}

/**
 * Fetches tasks from a file.
 */
int fetchTasks(TaskCollection* collection) {
    if (collection == NULL) {
        return -1;
    }
    FILE* file = fopen("tasks.txt", "r");
    if (file == NULL) {
        return -1;
    }
    while (!feof(file)) {
        char name[256];
        int priority;
        long startTime, endTime;
        fscanf(file, "%s %d %ld %ld\n", name, &priority, &startTime, &endTime);
        addTask(collection, name, priority, startTime, endTime);
    }
    fclose(file);
    return 0;
}']

