#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define the maximum number of concurrent threads to prevent overwhelming system resources
#define MAX_CONCURRENT_THREADS 10

// Define the structure for a weather record, including temperature, city name, and timestamp
typedef struct {
    double temperature;
    char* city_name;
    time_t timestamp;
} weatherRecord;

// Function to process weather data from a CSV file and calculate the average temperature
int processWeatherData(const char* filename) {
    // Open the CSV file for reading
    FILE* fp = fopen(filename, "r");
    if (fp == NULL) {
        printf("Error opening file: %s\n", filename);
        return -1;
    }

    // Define arrays to store temperature values, city names, and timestamps
    double* temperatures = NULL;
    char** city_names = NULL;
    time_t* timestamps = NULL;

    // Initialize the array of weather records
    int record_count = 0;
    weatherRecord* records = NULL;

    // Read each line from the CSV file and process it
    char line[1024];
    while (fgets(line, sizeof(line), fp) != NULL) {
        // Ignore empty lines or comments
        if (strlen(line) == 0 || line[0] == '#') {
            continue;
        }

        // Split the line into fields and extract the temperature, city name, and timestamp
        char* temp = strtok(line, ",");
        char* city = strtok(NULL, ",");
        char* time = strtok(NULL, "\n");

        // Convert the temperature from string to double
        double temperature = atof(temp);

        // Allocate memory for a new weather record and initialize it with the extracted values
        weatherRecord* record = malloc(sizeof(weatherRecord));
        record->temperature = temperature;
        record->city_name = strdup(city);
        record->timestamp = atol(time);

        // Add the new record to the array of records
        record_count++;
        if (records == NULL) {
            records = malloc(record_count * sizeof(weatherRecord));
        } else {
            records = realloc(records, record_count * sizeof(weatherRecord));
        }
        records[record_count - 1] = *record;

        // Free the memory allocated for the new record
        free(record);
    }

    // Close the CSV file
    fclose(fp);

    // Allocate memory for the arrays of temperature values, city names, and timestamps
    int temp_count = record_count;
    temperatures = malloc(temp_count * sizeof(double));
    city_names = malloc(temp_count * sizeof(char*));
    timestamps = malloc(temp_count * sizeof(time_t));

    // Initialize the arrays with the values from the weather records
    for (int i = 0; i < record_count; i++) {
        temperatures[i] = records[i].temperature;
        city_names[i] = strdup(records[i].city_name);
        timestamps[i] = records[i].timestamp;
    }

    // Calculate the average temperature across all records
    double avg_temp = 0.0;
    for (int i = 0; i < record_count; i++) {
        avg_temp += temperatures[i];
    }
    avg_temp /= temp_count;

    // Print the average temperature
    printf("Average temperature: %.2f\n", avg_temp);

    // Free the memory allocated for the arrays and the weather records
    free(temperatures);
    free(city_names);
    free(timestamps);
    free(records);

    return 0;
}

int main() {
    processWeatherData("weather.csv");
    return 0;
}

