    float metric_value = 0.0;

    // Iterate over events and process them
    for (size_t i = 0; i < num_events; i++) {
        event_record* current_event = &events[i];
        current_key++;
        current_timestamp = time(NULL);
        generate_label(label, sizeof(label));
        metric_value = rand() % 10.0;

        // Handle memory allocation and deallocation
        if (current_event->label != NULL) {
            free(current_event->label);
            current_event->label = NULL;
        }
        current_event->label = malloc(strlen(label) + 1);
        strcpy(current_event->label, label);
        current_event->key = current_key;
        current_event->timestamp = current_timestamp;
        current_event->value = metric_value;

        // Log operations to eventLog.txt file
        FILE* logFile = fopen("eventLog.txt", "a");
        if (logFile == NULL) {
            perror("fopen failed");
            return 1;
        }
        char* timestamp_str = ctime(&current_timestamp);
        fprintf(logFile, "%s - %d: %s (%f)\n", timestamp_str, current_key, label, metric_value);
        fclose(logFile);

        // Check for highest metric value and update if necessary
        if (metric_value > highest_metric) {
            highest_metric = metric_value;
        }
    }

    // Export final list of records to metrics.csv file
    FILE* csvFile = fopen("metrics.csv", "w");
    if (csvFile == NULL) {
        perror("fopen failed");
        return 1;
    }
    for (size_t i = 0; i < num_events; i++) {
        event_record* current_event = &events[i];
        fprintf(csvFile, "%d,%s,%f\n", current_event->key, current_event->label, current_event->value);
    }
    fclose(csvFile);

    // Print highest metric value and return successfully
    printf("Highest metric value: %f\n", highest_metric);
    return 0;
}
