//processAndFindMax.c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <unistd.h>
#include <fcntl.h>
#include <pthread.h>

// Structures for storing records
struct record {
    long offset;
    int key;
    double timestamp;
    unsigned char flag;
};

// Constants for memory management
#define MAX_RECORDS 10000
#define BLOCK_SIZE 1024

// Global variables for logging and synchronization
FILE *logFile = NULL;
int logFd = -1;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function prototypes
void logMessage(const char* message);
struct record* allocateRecord();
void freeRecord(struct record* r);
void processRecord(struct record* r, int index);
int exportRecords(struct record** records, int numRecords);

/**
 * Main function for the program
 */
int main(int argc, char* argv[]) {
    // Initialize logging file and mutex
    logFile = fopen("processLog.txt", "a+");
    if (logFile == NULL) {
        perror("fopen");
        return 1;
    }
    logFd = fileno(logFile);
    pthread_mutex_lock(&mutex);

    // Process records from standard input
    struct record** records = (struct record**)malloc(sizeof(struct record*) * MAX_RECORDS);
    for (int i = 0; i < MAX_RECORDS; ++i) {
        records[i] = allocateRecord();
    }

    // Loop until end of input is reached
    while (1) {
        struct record* r = allocateRecord();
        if (!processRecord(r, i)) {
            freeRecord(r);
            break;
        }

        // Export records to CSV file periodically
        if (exportRecords(records, i)) {
            logMessage("Exporting records to CSV file");
        }
    }

    // Clean up and exit
    free(records);
    pthread_mutex_unlock(&mutex);
    fclose(logFile);
    return 0;
}

/**
 * Allocates a new record structure
 */
struct record* allocateRecord() {
    struct record* r = (struct record*)malloc(sizeof(struct record));
    if (r == NULL) {
        logMessage("Memory allocation failed");
        return NULL;
    }

    // Initialize record fields
    r->offset = rand();
    r->key = rand() % 100;
    r->timestamp = time(NULL);
    r->flag = 'U';

    return r;
}

/**
 * Frees a record structure and its contents
 */
void freeRecord(struct record* r) {
    if (r != NULL) {
        free(r->buffer);
        free(r);
    }
}

/**
 * Processes a single record from standard input
 */
int processRecord(struct record* r, int index) {
    // Read from standard input and check for errors
    if (fscanf(stdin, "%ld %d %lf %c", &r->offset, &r->key, &r->timestamp, &r->flag) != 4) {
        logMessage("Error reading record");
        return 0;
    }

    // Validate input and update record fields if necessary
    if (r->offset < 0 || r->key < 0 || r->timestamp < 0 || !(r->flag == 'V' || r->flag == 'U')) {
        logMessage("Invalid input");
        return 0;
    }

    // Update record status and timestamp
    if (r->flag == 'V') {
        r->flag = 'P';
    } else {
        r->timestamp = time(NULL);
    }

    // Add the record to the records array
    records[index] = r;
    return 1;
}

/**
 * Exports the final list of records to a CSV file
 */
int exportRecords(struct record** records, int numRecords) {
    // Open CSV file for writing and check for errors
    FILE* csvFile = fopen("output.csv", "w");
    if (csvFile == NULL) {
        perror("fopen");
        return 1;
    }

    // Write header row to CSV file
    fprintf(csvFile, "Offset,Key,Timestamp,Flag\n");

    // Write records to CSV file
    for (int i = 0; i < numRecords; ++i) {
        struct record* r = records[i];
        fprintf(csvFile, "%ld,%d,%lf,%c\n", r->offset, r->key, r->timestamp, r->flag);
    }

    // Close CSV file and return success
    fclose(csvFile);
    return 0;
}

/**
 * Logs a message to the log file
 */
void logMessage(const char* message) {
    pthread_mutex_lock(&mutex);
    char timeBuf[32];
    time_t rawtime = time(NULL);
    struct tm* timeinfo = localtime(&rawtime);
    strftime(timeBuf, sizeof(timeBuf), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(logFile, "%s - %s\n", timeBuf, message);
    pthread_mutex_unlock(&mutex);
}']

