    // Clean up resources
    cleanup_resources(game_state, env_width, env_height);
}

// Initialize logging system
void init_logging() {
    log_fd = open(log_filename, O_WRONLY | O_CREAT | O_APPEND, S_IRUSR | S_IWUSR);
    if (log_fd == -1) {
        printf("Error opening file %s\n", log_filename);
    }
}

// Load XML configuration file
int load_xml_config(const char* config_path, xmlDoc** doc, xmlNode** root) {
    int ret = 0;
    *doc = xmlParseFile(config_path);
    if (*doc == NULL) {
        printf("Error parsing XML configuration file\n");
        ret = -1;
    } else {
        *root = xmlDocGetRootElement(*doc);
        if (*root == NULL) {
            printf("Error retrieving root node from XML configuration file\n");
            ret = -2;
        }
    }
    return ret;
}

// Parse game-like environment parameters from XML config
rectangle parse_environment_parameters(xmlNode* root) {
    rectangle env_rectangle;
    xmlChar* value = NULL;

    // Parse tile size parameter
    xmlNodePtr node = xmlFirstElementChild(root);
    while (node != NULL && value == NULL) {
        if (xmlStrcmp(node->name, BAD_CAST "tile_size") == 0) {
            value = xmlNodeGetContent(node);
        }
        node = xmlNextElementSibling(node);
    }
    if (value != NULL) {
        int tile_size = atoi((const char*)value);
        env_rectangle.top_left.x = 0;
        env_rectangle.top_left.y = 0;
        env_rectangle.bottom_right.x = tile_size - 1;
        env_rectangle.bottom_right.y = tile_size - 1;
    } else {
        env_rectangle.top_left.x = 0;
        env_rectangle.top_left.y = 0;
        env_rectangle.bottom_right.x = WORLD_DIMENSIONS_X - 1;
        env_rectangle.bottom_right.y = WORLD_DIMENSIONS_Y - 1;
    }
    xmlFree(value);

    return env_rectangle;
}

