// Define the maximum number of connections allowed in the pool
#define MAX_CONNECTIONS 10000

// Define the maximum number of transactions that can be processed concurrently
#define MAX_TRANSACTIONS 50

// Define the connection metadata structure
struct dbMetadata {
    int status;      // Connection status (e.g., available, busy, closed)
    time_t lastAccess;     // Last access time for the connection
    int errorCode;   // Error code associated with the connection
};

// Define the database connection structure
struct dbConnection {
    int transactionID;  // Unique transaction ID for this connection
    struct dbMetadata metadata;  // Connection metadata (e.g., status, last access time, error code)
};

// Define the connection pool array
struct dbConnection connections[MAX_CONNECTIONS];

// Define the transaction ID counter
int transactionID = 0;

// Define the function to allocate a new connection in the pool
struct dbConnection* allocConnection() {
    // Check if there are any available connections in the pool
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        if (connections[i].metadata.status == AVAILABLE) {
            // Mark the connection as busy and update its metadata
            connections[i].metadata.status = BUSY;
            connections[i].metadata.lastAccess = time(NULL);
            return &connections[i];
        }
    }
    // If no available connections are found, allocate a new one
    struct dbConnection* conn = malloc(sizeof(struct dbConnection));
    if (conn != NULL) {
        conn->transactionID = transactionID++;
        conn->metadata.status = BUSY;
        conn->metadata.lastAccess = time(NULL);
        conn->metadata.errorCode = 0;
    } else {
        fprintf(stderr, "Failed to allocate new connection\n");
    }
    return conn;
}

// Define the function to free a connection in the pool
void freeConnection(struct dbConnection* conn) {
    // Mark the connection as available and update its metadata
    connections[conn->transactionID].metadata.status = AVAILABLE;
    connections[conn->transactionID].metadata.lastAccess = time(NULL);
}

