    struct dbMetadata metadata;  // Metadata for the connection
    char* queryString;  // Query string for the connection
    pthread_mutex_t mutex;  // Mutex for protecting the connection
};

// Define the structure for a connection pool
struct dbConnectionPool {
    int size;  // Number of connections in the pool
    struct dbConnection* connections;  // Array of connections
};

// Define the function to manage database connections
void manageDatabaseConnections(int numThreads, int numConnectionsPerThread) {
    // Initialize the connection pool with the specified number of connections per thread
    struct dbConnectionPool* pool = (struct dbConnectionPool*)malloc(sizeof(struct dbConnectionPool));
    pool->size = numThreads * numConnectionsPerThread;
    pool->connections = (struct dbConnection*)calloc(pool->size, sizeof(struct dbConnection));

    // Initialize each connection's status to a random state within the specified range
    for (int i = 0; i < pool->size; ++i) {
        int randState = rand() % 2;
        pool->connections[i].metadata.status = randState ? OPEN : CLOSED;
        pool->connections[i].metadata.errorCode = 0;
    }

    // Initialize the mutex for each connection in the pool
    for (int i = 0; i < pool->size; ++i) {
        pthread_mutex_init(&pool->connections[i].mutex, NULL);
    }

    // Create a thread for each connection in the pool
    std::vector<std::thread> threads(pool->size);
    for (int i = 0; i < pool->size; ++i) {
        threads[i] = std::thread([&](int id) {
            struct dbConnection* conn = &pool->connections[id];
            while (true) {
                // Acquire the mutex for the connection
                pthread_mutex_lock(&conn->mutex);

                // Check if the connection is open and valid
                if (conn->metadata.status != OPEN || conn->errorCode != 0) {
                    // If not, close the connection and release the mutex
                    pthread_mutex_unlock(&conn->mutex);
                    break;
                }

                // Execute the query on the connection
                int result = executeQuery(conn->queryString);
                if (result != 0) {
                    conn->metadata.status = CLOSED;
                    conn->errorCode = result;
                }

                // Commit or roll back the transaction, depending on the status of the connection
                if (conn->metadata.status == OPEN) {
                    int commitResult = commitTransaction(conn);
                    if (commitResult != 0) {
                        conn->metadata.status = CLOSED;
                        conn->errorCode = commitResult;
                    }
                } else {
                    int rollbackResult = rollbackTransaction(conn);
                    if (rollbackResult != 0) {
                        conn->metadata.status = CLOSED;
                        conn->errorCode = rollbackResult;
                    }
                }

                // Release the mutex for the connection
                pthread_mutex_unlock(&conn->mutex);
            }
        }, i);
    }

    // Wait for all threads to finish before cleaning up resources
    for (auto& thread : threads) {
        thread.join();
    }

    // Clean up the connection pool and free memory
    pthread_mutex_destroy(&pool->connections[0].mutex);
    free(pool->connections);
    free(pool);
}
