#include <time.h>

// Structure to hold an offset and a pointer to a record
struct offset {
    int offset;
    struct record *record;
};

// Structure to hold a key and its frequency count
struct key_count {
    int key;
    int frequency;
};

// Function to generate a random integer within the specified range
int generateRandomInt(int min, int max) {
    return (rand() % (max - min + 1)) + min;
}

// Function to initialize a linked list of offsets and an array of keys
void initListAndArray(struct offset **list, int **keys) {
    // Initialize the linked list of offsets
    *list = malloc(sizeof(struct offset));
    (*list)->offset = 0;
    (*list)->record = NULL;

    // Initialize the array of keys
    *keys = malloc(sizeof(int));
    (*keys)[0] = generateRandomInt(min, max);
}

// Function to update a hash table with frequency counts for each unique key
void updateHashTable(struct offset **list) {
    // Declare variables for the current offset and record
    struct offset *current_offset = *list;
    struct record *current_record = (*list)->record;

    // Iterate through the linked list of offsets
    while (current_offset != NULL) {
        // Get the key from the current record
        int key = current_record->key;

        // Check if the key already exists in the hash table
        struct key_count *key_count = findKey(key);
        if (key_count == NULL) {
            // If the key does not exist, create a new entry and set its frequency to 1
            key_count = malloc(sizeof(struct key_count));
            key_count->key = key;
            key_count->frequency = 1;

            // Add the new key to the hash table
            addKey(key_count);
        } else {
            // If the key already exists, increment its frequency count
            key_count->frequency++;
        }

        // Move to the next offset in the linked list
        current_offset = current_offset->next;
    }
}

// Function to find a key in the hash table and return its frequency count
int findKey(int key) {
    // Iterate through the linked list of keys in the hash table
    struct key_count *current_key_count = head;
    while (current_key_count != NULL) {
        if (current_key_count->key == key) {
            return current_key_count->frequency;
        }
        current_key_count = current_key_count->next;
    }

    // If the key is not found, return 0
    return 0;
}

// Function to add a new key to the hash table and set its frequency count to 1
void addKey(struct key_count *new_key) {
    // Add the new key to the linked list of keys in the hash table
    struct key_count *current_key_count = head;
    while (current_key_count->next != NULL) {
        current_key_count = current_key_count->next;
    }
    current_key_count->next = new_key;
}

// Function to process a stream of integers and find the largest integer and most frequently occurring key
void processAndFindMax(struct offset **list, int *max_int, int *most_frequent_key) {
    // Declare variables for the current offset and record
    struct offset *current_offset = *list;
    struct record *current_record = (*list)->record;

    // Initialize the maximum integer and most frequently occurring key to the first value in the stream
    *max_int = current_record->value;
    *most_frequent_key = current_record->key;

    // Iterate through the linked list of offsets
    while (current_offset != NULL) {
        // Get the key and value from the current record
        int key = current_record->key;
        int value = current_record->value;

        // Update the maximum integer if necessary
        if (value > *max_int) {
            *max_int = value;
        }

        // Update the most frequently occurring key and its frequency count if necessary
        struct key_count *key_count = findKey(key);
        if (key_count != NULL && key_count->frequency > (*most_frequent_key)->frequency) {
            *most_frequent_key = key;
        }

        // Move to the next offset in the linked list
        current_offset = current_offset->next;
    }
}

// Function to clean up resources and exit gracefully
void cleanup(struct offset **list, int *max_int, int *most_frequent_key) {
    // Release the memory allocated for the linked list of offsets
    free(*list);

    // Release the memory allocated for the array of keys
    free(*keys);

    // Release the memory allocated for the hash table
    struct key_count *current_key_count = head;
    while (current_key_count != NULL) {
        struct key_count *next_key_count = current_key_count->next;
        free(current_key_count);
        current_key_count = next_key_count;
    }
}
