};

// function to manage database connections
int manageDatabaseConnections(char *configFilePath) {
    FILE *configFile = fopen(configFilePath, "r");
    if (!configFile) {
        printf("Error: failed to open configuration file\n");
        return -1;
    }

    // read configuration parameters from the file
    int numConnections;
    int connectionTimeout;
    int maxIdleConnections;
    fscanf(configFile, "%d %d %d", &numConnections, &connectionTimeout, &maxIdleConnections);
    if (ferror(configFile)) {
        printf("Error: failed to read configuration parameters\n");
        fclose(configFile);
        return -1;
    }
    fclose(configFile);

    // allocate memory for connection pools and metadata records
    long *lastAccessTimes = (long *)malloc(sizeof(long) * numConnections);
    int *transactionIds = (int *)malloc(sizeof(int) * numConnections);
    struct dbMetadata *connectionMetadata = (struct dbMetadata *)malloc(sizeof(struct dbMetadata) * numConnections);
    if (!lastAccessTimes || !transactionIds || !connectionMetadata) {
        printf("Error: failed to allocate memory for connection pools and metadata records\n");
        return -1;
    }

    // initialize each connection's status and error code
    for (int i = 0; i < numConnections; i++) {
        lastAccessTimes[i] = time(NULL);
        transactionIds[i] = -1;
        connectionMetadata[i].state = rand() % MAX_CONNECTION_STATE; // random connection state within the specified range
        connectionMetadata[i].errorCode = 0; // no error
    }

    // create a thread pool for managing database connections
    pthread_t *connectionThreads = (pthread_t *)malloc(sizeof(pthread_t) * numConnections);
    if (!connectionThreads) {
        printf("Error: failed to allocate memory for connection threads\n");
        free(lastAccessTimes);
        free(transactionIds);
        free(connectionMetadata);
        return -1;
    }

    // create a semaphore for managing access to the connection pools
    sem_t *connectionSemaphore = sem_open("connSem", O_CREAT, 0644, numConnections);
    if (sem_open == SEM_FAILED) {
        printf("Error: failed to create semaphore for managing connections\n");
        free(lastAccessTimes);
        free(transactionIds);
        free(connectionMetadata);
        return -1;
    }

    // initialize each connection thread with a unique id
    for (int i = 0; i < numConnections; i++) {
        pthread_create(&connectionThreads[i], NULL, manageConnection, (void *)(long long)i);
    }

    // wait for all connections to be closed before returning from the function
    for (int i = 0; i < numConnections; i++) {
        pthread_join(connectionThreads[i], NULL);
    }

    // clean up resources
    sem_close(connectionSemaphore);
    free(lastAccessTimes);
    free(transactionIds);
    free(connectionMetadata);
    free(connectionThreads);

    return 0;
}

// function to manage a single database connection
void *manageConnection(void *threadId) {
    long threadIdLong = (long)threadId; // convert void * to long for casting
    int id = (int)threadIdLong; // cast long to int for indexing the connection pools
    struct dbMetadata *connectionMetadata = &connectionMetadata[id];

    // loop indefinitely until a shutdown signal is received
    while (1) {
        sem_wait(connectionSemaphore); // wait for access to the connection pool

        // check if the connection is disconnected or if the maximum idle time has been exceeded
        if (connectionMetadata->state == DISCONNECTED || differenceInSeconds(time(NULL), connectionMetadata->lastAccessTime) > maxIdleConnections) {
            reconnectToDatabase(); // attempt to reconnect to the database
            connectionMetadata->state = CONNECTED; // update the connection state to connected
        }

        // check if there are any pending queries in the queue
        if (queueIsEmpty()) {
            sem_post(connectionSemaphore); // release access to the connection pool
            break; // exit the thread since there is nothing left to do
        } else {
            executeQuery(); // execute a query from the queue
            connectionMetadata->lastAccessTime = time(NULL); // update the last access time for this connection
            sem_post(connectionSemaphore); // release access to the connection pool
        }
    }
}
