    // Initialize variables
    int i = 0;
    long t = 0;
    int id = 0;
    double temp = 0.0;
    Record records[RECORD_COUNT];

    // Parse command-line options and configuration file path
    if (argc > MAX_COMMAND_LINE_OPTIONS) {
        printf("Error: too many command-line options\n");
        return;
    }
    char *configFilePath = DEFAULT_CONFIGURATION_FILE;
    if (argc == 2) {
        configFilePath = argv[1];
    } else if (argc > 2) {
        printf("Error: invalid command-line options\n");
        return;
    }

    // Load configuration file
    FILE *configFile = fopen(configFilePath, "r");
    if (!configFile) {
        perror("Error opening configuration file");
        return;
    }
