    while (fgets(line, sizeof(line), configFile)) {
        // Check for comments and empty lines
        if (line[0] == '#' || line[0] == '\n') {
            continue;
        }
        // Parse configuration file options
        char *option = strtok(line, "=");
        if (!option) {
            printf("Error: invalid configuration option\n");
            fclose(configFile);
            return;
        }
        char *value = strtok(NULL, "\n");
        if (!value) {
            printf("Error: missing value for option '%s'\n", option);
            fclose(configFile);
            return;
        }
