        if (strcmp(option, "identifier_range") == 0) {
            sscanf(value, "%d", &id);
        } else if (strcmp(option, "temperature_range") == 0) {
            sscanf(value, "%lf %lf", &temp, &temp + 1);
        } else {
            printf("Error: unsupported configuration option '%s'\n", option);
            fclose(configFile);
            return;
        }
