        // If not, double the size of the map
        struct hashMap *newMap = realloc(map, sizeof(struct hashMap) * 2);
        map = newMap;
    }

    // Insert log entry into map
    node->next = map->head;
    map->head = node;
    map->size++;
}

// Generate report
void generateReport(struct hashMap *map) {
    // Print unique status indicators and their frequencies
    for (int i = 0; i < map->size; i++) {
        struct listNode *node = map->head;
        while (node != NULL) {
            printf("%c: %d\n", node->entry.status, node->entry.timestamp);
            node = node->next;
        }
    }
}

// Clean up memory allocated to hash map
void destroyHashMap(struct hashMap *map) {
    free(map);
}
