// Define a structure to represent a record
typedef struct {
    int key;
    long offset;
    struct {
        int value;
    } record;
    char *label;
} Record;

// Define a function to initialize the records collection
void init_records(Record **records, size_t capacity) {
    // Allocate memory for the records array and set its initial size
    *records = malloc(capacity * sizeof(**records));
    memset(*records, 0, capacity * sizeof(**records));
}

// Define a function to insert a new record into the collection
void insert_record(Record **records, size_t *size, int key, long offset, struct { int value; } record, char *label) {
    // Check if the records array needs to be resized
    if (*size == capacity) {
        // Resize the array by doubling its current size
        *records = realloc(*records, 2 * capacity * sizeof(**records));
        memset(*records + capacity, 0, capacity * sizeof(**records));
        capacity *= 2;
    }

    // Insert the new record into the array
    (*records)[*size].key = key;
    (*records)[*size].offset = offset;
    (*records)[*size].record.value = record.value;
    (*records)[*size].label = strdup(label);

    // Increment the size of the array
    *size += 1;
}

// Define a function to retrieve a record from the collection by its key
Record *get_record(Record **records, size_t size, int key) {
    // Loop through the records array and find the matching record
    for (int i = 0; i < size; i++) {
        if ((*records)[i].key == key) {
            return &(*records)[i];
        }
    }

    // If no matching record is found, return NULL
    return NULL;
}

// Define a function to update a record in the collection by its key
void update_record(Record **records, size_t *size, int key, struct { int value; } new_record) {
    // Retrieve the record to be updated
    Record *record = get_record(records, *size, key);

    if (record != NULL) {
        // Update the record's value and return
        record->value.value = new_record.value;
    } else {
        // If no matching record is found, insert a new one
        insert_record(records, size, key, 0, new_record);
    }
}
```
The `init_records` function initializes an empty collection of records with the given capacity. The `insert_record` function inserts a new record into the collection by allocating memory for it and copying the provided values. The `get_record` function retrieves a record from the collection by its key. The `update_record` function updates a record in the collection by its key by either updating the existing record or inserting a new one if no matching record is found.

