    // Create data transformer objects
    for (int i = 0; i < num_threads; i++) {
        threads[i] = pthread_create(&threads[i], NULL, data_transformer, NULL);
    }
}

void setup_signal_handling() {
    // Set up signal handling
    struct sigaction sa;
    memset(&sa, 0, sizeof(struct sigaction));
    sa.sa_handler = handle_sigint;
    sigfillset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
}

void start_threads() {
    // Start threads to process data
    for (int i = 0; i < num_threads; i++) {
        pthread_create(&threads[i], NULL, data_processor, NULL);
    }
}

void wait_for_all_threads() {
    // Wait for all threads to finish
    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }
}

void handle_sigint(int signum) {
    // Handle SIGINT signal
    if (signum == SIGINT) {
        // Clean up resources and exit
        cleanup();
        exit(0);
    }
}

void cleanup() {
    // Clean up resources
    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }
    semaphore_destroy(data_lock);
    semaphore_destroy(thread_count_lock);
}
