static const char *MEM_ERROR = "Insufficient memory allocation";

// Struct to store weather data
typedef struct {
    double temperature;
    char *city;
    time_t timestamp;
} weatherRecord;

/**
 * Function to parse and aggregate weather data from a CSV file.
 * Dynamically manages memory allocation for arrays of double values,
 * char* pointers for city names, and time_t values for timestamps, storing
 * each record in a weatherRecord structure containing a temperature, city name,
 * and timestamp. Memory pool is used for better memory management, ensuring
 * that any allocated resources are properly released in case of errors.
 *
 * @param filename Path to the CSV file
 * @return Pointer to an array of weatherRecord structures
 */
weatherRecord* parseAndAggregateWeatherData(char *filename) {
    // Initialize variables
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error: Unable to open file %s\n", filename);
        return NULL;
    }

    long numRecords = 0;
    size_t bufSize = 1024 * 8; // Initial buffer size in bytes
    char *buffer = malloc(bufSize);
    if (buffer == NULL) {
        printf("Error: %s\n", MEM_ERROR);
        fclose(file);
        return NULL;
    }

    int i, j;
    weatherRecord *records = NULL;
    weatherRecord *record;
    char *token;
    double temp;
    char *cityName;
    time_t timestamp;

    // Read CSV file and parse data into memory pool
    while (fgets(buffer, bufSize, file) != NULL) {
        numRecords++;

        // Reallocate memory for records if necessary
        if (numRecords % 10 == 0) {
            records = realloc(records, sizeof(weatherRecord) * (numRecords + 10));
            if (records == NULL) {
                printf("Error: %s\n", MEM_ERROR);
                fclose(file);
                free(buffer);
                return NULL;
            }
        }

        record = &records[numRecords - 1];

        // Parse temperature and city name from buffer
        token = strtok(buffer, ",");
        if (token == NULL) {
            printf("Error: Unable to parse temperature\n");
            fclose(file);
            free(buffer);
            return NULL;
        }
        temp = atof(token);
        record->temperature = temp;

        token = strtok(NULL, ",");
        if (token == NULL) {
            printf("Error: Unable to parse city name\n");
            fclose(file);
            free(buffer);
            return NULL;
        }
        cityName = malloc(strlen(token) + 1);
        if (cityName == NULL) {
            printf("Error: %s\n", MEM_ERROR);
            fclose(file);
            free(buffer);
            return NULL;
        }
        strcpy(cityName, token);
        record->city = cityName;

        // Parse timestamp from buffer
        token = strtok(NULL, ",");
        if (token == NULL) {
            printf("Error: Unable to parse timestamp\n");
            fclose(file);
            free(buffer);
            return NULL;
        }
        timestamp = atol(token);
        record->timestamp = timestamp;
    }

    // Close file and release buffer
    fclose(file);
    free(buffer);

    // Initialize key array with random values within specified range
    srand(time(NULL));
    int *keyArray = malloc(sizeof(int) * numRecords);
    if (keyArray == NULL) {
        printf("Error: %s\n", MEM_ERROR);
        return NULL;
    }
    for (i = 0; i < numRecords; i++) {
        keyArray[i] = rand() % 1000000 + 1; // Random value within specified range
    }

    // Initialize offset array with unique indices that do not exceed bounds of key array
    int *offsetArray = malloc(sizeof(int) * numRecords);
    if (offsetArray == NULL) {
        printf("Error: %s\n", MEM_ERROR);
        free(keyArray);
        return NULL;
    }
    for (i = 0, j = 0; i < numRecords; i++) {
        while (keyArray[j] == keyArray[i]) {
            j++;
            if (j >= numRecords) {
                break;
            }
        }
        offsetArray[i] = j;
    }

    // Initialize record with random value within specified range and unique indices that do not exceed bounds of key array
    for (i = 0; i < numRecords; i++) {
        record = &records[i];
        record->key = rand() % 1000000 + 1; // Random value within specified range
        record->offset = offsetArray[i];
    }

    // Free key and offset arrays to avoid memory leaks
    free(keyArray);
    free(offsetArray);

    return records;
}']

