#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <errno.h>

// Define structure for storing record data
typedef struct {
    char status; // 'char' status indicator
    time_t timestamp; // 'time_t' timestamp
    double value; // 'double' numeric value
} record_t;

// Define function to parse and aggregate data from a file descriptor
int parseAndAggregateData(FILE *fd) {
    int error = 0; // Error code for handling errors gracefully
    char line[1024]; // Buffer for reading lines from the file
    size_t len; // Length of each line in bytes
    record_t *records = NULL; // Array of 'record' structures
    time_t max_timestamp = 0; // Maximum timestamp found among records
    double sum = 0.0; // Sum of all numeric values
    size_t count = 0; // Count of unique status indicators
    char prev_status = '\0'; // Previous status indicator

    // Read each line from the file descriptor and process it
    while (fgets(line, sizeof(line), fd)) {
        len = strlen(line);

        if (len < 2) { // Skip empty lines or malformed records
            continue;
        }

        char status = line[0]; // Get status indicator from the line
        time_t timestamp = atol(line + 1); // Parse timestamp from the line
        double value = strtod(line + 2, NULL); // Parse numeric value from the line

        if (status != prev_status) { // If status is different from previous record
            count++; // Increment unique status indicator count
        }

        sum += value; // Add numeric value to the sum

        if (timestamp > max_timestamp) { // Update maximum timestamp found among records
            max_timestamp = timestamp;
        }

        // Allocate memory for 'record' structure and assign data to it
        record_t *new_record = malloc(sizeof(record_t));
        if (new_record == NULL) { // Check for memory allocation failure
            error = errno;
            break;
        }
        new_record->status = status;
        new_record->timestamp = timestamp;
        new_record->value = value;

        // Add 'record' structure to the array of records
        records = realloc(records, (count + 1) * sizeof(record_t));
        if (records == NULL) { // Check for memory allocation failure
            error = errno;
            break;
        }
        records[count - 1] = new_record;
    }

    if (error != 0) { // Handle memory allocation or external dependency errors
        printf("Error %d: %s\n", error, strerror(error));
        return error;
    }

    // Print summary report containing count of unique status indicators, average numeric value, and maximum timestamp found among records
    printf("Unique status indicators: %zu\n", count);
    printf("Average numeric value: %.2lf\n", sum / (count > 0 ? count : 1));
    printf("Maximum timestamp: %ld\n", max_timestamp);

    // Clean up allocated resources
    if (records != NULL) {
        for (size_t i = 0; i < count; i++) {
            free(records[i]);
        }
        free(records);
    }

    return 0;
}
