// Custom memory allocator for efficient memory management
void* my_malloc(size_t size) {
    // Memory pooling technique using a fixed-size buffer
    static char mempool[1024 * 1024]; // 1 MB memory pool
    static int next_free = 0;
    if (next_free + size <= sizeof(mempool)) {
        void* ptr = mempool + next_free;
        next_free += size;
        return ptr;
    } else {
        // Slab allocation technique using a linked list of fixed-size blocks
        static struct Block {
            struct Block* next;
            char data[1024]; // 1 KB per block
        }* first = NULL;
        struct Block* current = first;
        while (current != NULL && current->next == NULL) {
            current = current->next;
        }
        if (current == NULL) {
            // No more memory available, return NULL
            return NULL;
        } else {
            void* ptr = current->data + next_free;
            next_free += size;
            return ptr;
        }
    }
}

// Custom free function for efficient memory management
void my_free(void* ptr) {
    // Memory pooling technique
    if (ptr < mempool || ptr >= mempool + sizeof(mempool)) {
        // Slab allocation technique using a linked list of fixed-size blocks
        struct Block* current = first;
        while (current != NULL && current->data <= ptr) {
            current = current->next;
        }
        if (current == NULL || current->data + sizeof(current->data) <= ptr) {
            // Invalid pointer, do nothing
            return;
        } else {
            current->next = (struct Block*)ptr;
        }
    }
}

// Custom realloc function for efficient memory management
void* my_realloc(void* ptr, size_t size) {
    // Memory pooling technique
    if (ptr < mempool || ptr >= mempool + sizeof(mempool)) {
        // Slab allocation technique using a linked list of fixed-size blocks
        struct Block* current = first;
        while (current != NULL && current->data <= ptr) {
            current = current->next;
        }
        if (current == NULL || current->data + sizeof(current->data) <= ptr) {
            // Invalid pointer, do nothing
            return NULL;
        } else {
            current->next = (struct Block*)ptr;
            void* new_ptr = my_malloc(size);
            if (new_ptr != NULL) {
                memcpy(new_ptr, ptr, size);
                return new_ptr;
            } else {
                return NULL;
            }
        }
    } else {
        void* new_ptr = my_malloc(size);
        if (new_ptr != NULL) {
            memcpy(new_ptr, ptr, size);
            return new_ptr;
        } else {
            return NULL;
        }
    }
}

