typedef struct eventRecord {
    unsigned long eventID;
    time_t timestamp;
    float priority;
} EventRecord;

int processEvents(const char* filePath) {
    int fd = open(filePath, O_RDONLY);
    if (fd == -1) {
        perror("open");
        return 1;
    }

    size_t bufferSize = BUFFER_SIZE;
    char* buffer = malloc(bufferSize * sizeof(char));
    if (!buffer) {
        fprintf(stderr, "Memory allocation failed\n");
        close(fd);
        return 1;
    }

    unsigned long* eventIDs = malloc(MAX_EVENTS * sizeof(unsigned long));
    time_t* timestamps = malloc(MAX_EVENTS * sizeof(time_t));
    float* priorities = malloc(MAX_EVENTS * sizeof(float));
    EventRecord* events = malloc(MAX_EVENTS * sizeof(EventRecord));
    if (!eventIDs || !timestamps || !priorities || !events) {
        fprintf(stderr, "Memory allocation failed\n");
        close(fd);
        free(buffer);
        return 1;
    }

    ssize_t readBytes = 0;
    size_t eventCount = 0;
    while ((readBytes = read(fd, buffer, bufferSize)) > 0) {
        for (size_t i = 0; i < readBytes; i++) {
            if (buffer[i] == '\n') {
                EventRecord* event = &events[eventCount];
                char* token = strtok(buffer, ",");
                event->eventID = atol(token);
                token = strtok(NULL, ",");
                event->timestamp = atol(token);
                token = strtok(NULL, ",");
                event->priority = atof(token);
                if (eventCount < MAX_EVENTS) {
                    eventIDs[eventCount] = event->eventID;
                    timestamps[eventCount] = event->timestamp;
                    priorities[eventCount] = event->priority;
                    eventCount++;
                } else {
                    fprintf(stderr, "Buffer overflow\n");
                    close(fd);
                    free(buffer);
                    return 1;
                }
            }
        }
    }

    if (readBytes == -1) {
        perror("read");
        close(fd);
        free(buffer);
        return 1;
    }

    size_t highestPriorityEventIndex = 0;
    float highestPriority = priorities[highestPriorityEventIndex];
    for (size_t i = 1; i < eventCount; i++) {
        if (priorities[i] > highestPriority) {
            highestPriorityEventIndex = i;
            highestPriority = priorities[i];
        }
    }

    printf("Highest priority event: %lu, timestamp: %ld, priority: %.2f\n",
            events[highestPriorityEventIndex].eventID,
            events[highestPriorityEventIndex].timestamp,
            events[highestPriorityEventIndex].priority);

    close(fd);
    free(buffer);
    return 0;
}

int main() {
    processEvents("events.txt");
    return 0;
}']

