```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>
#include <time.h>

// Struct for storing connection metadata
struct dbMetadata {
  int status;        // Connection status (e.g., open or closed)
  time_t lastAccess; // Last access time
  int errorCode;     // Error code (if any)
};

// Struct for storing database connections in the pool
struct dbConnection {
  struct dbMetadata *metadata; // Pointer to connection metadata
  char *queryString;           // Query string (if any)
  int transactionID;          // Transaction ID (if any)
};

// Global variables
int numConnections = 0;                         // Number of connections in the pool
int maxConnections = 100;                       // Maximum number of connections in the pool
struct dbConnection *connections[maxConnections]; // Array of database connections
sem_t semaphore;                                // Semaphore for synchronizing access to the connections array

// Initialize the database manager
void initializeDatabaseManager() {
  int i;
  struct dbMetadata *metadata;

  // Allocate memory for the connections array
  connections = (struct dbConnection **)malloc(maxConnections * sizeof(struct dbConnection *));
  if (!connections) {
    fprintf(stderr, "Error: Failed to allocate memory for the connections array.\n");
    exit(1);
  }

  // Initialize each connection's status and error code to a random state within a specified range
  srand((unsigned int)time(NULL));
  for (i = 0; i < maxConnections; i++) {
    metadata = &connections[i]->metadata;
    metadata->status = rand() % 2 == 1 ? OPEN : CLOSED;
    metadata->errorCode = 0;
  }

  // Initialize the semaphore
  if (sem_init(&semaphore, 0, maxConnections) < 0) {
    fprintf(stderr, "Error: Failed to initialize the semaphore.\n");
    exit(1);
  }
}

// Shut down the database manager
void shutdownDatabaseManager() {
  int i;

  // Free memory for the connections array
  free(connections);

  // Destroy the semaphore
  if (sem_destroy(&semaphore) < 0) {
    fprintf(stderr, "Error: Failed to destroy the semaphore.\n");
    exit(1);
  }
}

// Acquire a connection from the pool
struct dbConnection *acquireConnection() {
  int i;

  // Search for an available connection in the pool
  for (i = 0; i < maxConnections; i++) {
    if (connections[i]->metadata.status == OPEN) {
      return connections[i];
    }
  }

  // No available connections found, add a new one to the pool
  if (numConnections < maxConnections) {
    struct dbConnection *newConnection = malloc(sizeof(struct dbConnection));
    if (!newConnection) {
      fprintf(stderr, "Error: Failed to allocate memory for a new connection.\n");
      exit(1);
    }
    connections[numConnections++] = newConnection;
    return newConnection;
  } else {
    // No more available connections, block until one is released
    sem_wait(&semaphore);
    return acquireConnection();
  }
}

// Release a connection to the pool
void releaseConnection(struct dbConnection *connection) {
  int i;

  // Find the connection in the pool and mark it as available
  for (i = 0; i < maxConnections; i++) {
    if (connections[i] == connection) {
      connections[i]->metadata.status = OPEN;
      sem_post(&semaphore); // Release the semaphore to unblock any waiting threads
      return;
    }
  }
}

// Execute a query on a database connection
int executeQuery(struct dbConnection *connection, char *queryString) {
  int status = -1;

  // Check input parameters
  if (!connection || !queryString) {
    fprintf(stderr, "Error: Invalid input parameters.\n");
    return status;
  }

  // Acquire the connection from the pool
  struct dbConnection *acquiredConnection = acquireConnection();
  if (!acquiredConnection) {
    fprintf(stderr, "Error: Failed to acquire a connection from the pool.\n");
    return status;
  }

  // Execute the query on the acquired connection
  status = executeQueryOnConnection(acquiredConnection, queryString);
  if (status < 0) {
    fprintf(stderr, "Error: Failed to execute the query.\n");
  }

  // Release the acquired connection back to the pool
  releaseConnection(acquiredConnection);

  return status;
}

// Commit a transaction on a database connection
int commitTransaction(struct dbConnection *connection) {
  int status = -1;

  // Check input parameters
  if (!connection) {
    fprintf(stderr, "Error: Invalid input parameters.\n");
    return status;
  }

  // Acquire the connection from the pool
  struct dbConnection *acquiredConnection = acquireConnection();
  if (!acquiredConnection) {
    fprintf(stderr, "Error: Failed to acquire a connection from the pool.\n");
    return status;
  }

  // Commit the transaction on the acquired connection
  status = commitTransactionOnConnection(acquiredConnection);
  if (status < 0) {
    fprintf(stderr, "Error: Failed to commit the transaction.\n");
  }

  // Release the acquired connection back to the pool
  releaseConnection(acquiredConnection);

  return status;
}

// Rollback a transaction on a database connection
int rollbackTransaction(struct dbConnection *connection) {
  int status = -1;

  // Check input parameters
  if (!connection) {
    fprintf(stderr, "Error: Invalid input parameters.\n");
    return status;
  }

  // Acquire the connection from the pool
  struct dbConnection *acquiredConnection = acquireConnection();
  if (!acquiredConnection) {
    fprintf(stderr, "Error: Failed to acquire a connection from the pool.\n");
    return status;
  }

  // Rollback the transaction on the acquired connection
  status = rollbackTransactionOnConnection(acquiredConnection);
  if (status < 0) {
    fprintf(stderr, "Error: Failed to rollback the transaction.\n");
  }

  // Release the acquired connection back to the pool
  releaseConnection(acquiredConnection);

  return status;
}
```

This implementation uses a semaphore to control access to the database connections. When a thread needs to execute a query, it acquires a connection from the pool by calling `acquireConnection()`. If no available connections are found in the pool, the thread blocks until one is released or a new connection is added to the pool. The thread then executes the query on the acquired connection and releases the connection back to the pool by calling `releaseConnection()`.

The implementation also provides functions for committing and rolling back transactions. When a transaction needs to be committed, the thread acquires a connection from the pool, commits the transaction on the acquired connection, and releases the connection back to the pool. Similarly, when a transaction needs to be rolled back, the thread acquires a connection from the pool, rolls back the transaction on the acquired connection, and releases the connection back to the pool.

This implementation allows multiple threads to execute queries concurrently without blocking each other. However, it may still lead to deadlocks or liveness issues if there are conflicting updates among different threads. To address these issues, we can use a transaction manager that keeps track of all active transactions and ensures that they are executed in an order that prevents conflicts.']

