// Function to process and analyze records read from standard input
void processAndAnalyzeRecords(int minKey, int maxKey) {
    // Initialize variables for tracking the record count and memory usage
    size_t recordCount = 0;
    size_t totalMemoryUsage = 0;

    // Create arrays to store the offset values, keys, and records
    long *offsets = malloc(sizeof(long) * WINDOW_SIZE);
    int *keys = malloc(sizeof(int) * WINDOW_SIZE);
    Record *records = malloc(sizeof(Record) * WINDOW_SIZE);

    // Initialize the sliding window of last 10 records
    for (size_t i = 0; i < WINDOW_SIZE; i++) {
        offsets[i] = -1;
        keys[i] = -1;
        records[i].key = -1;
        records[i].timestamp = -1;
    }

    // Read records from standard input and process them
    while (true) {
        // Read the next record from standard input
        Record r;
        if (!readRecord(r)) {
            break;
        }

        // Check if the record is valid
        if (r.key < minKey || r.key > maxKey) {
            continue;
        }

        // Allocate memory for the new record and copy it to the sliding window
        Record *newRecord = malloc(sizeof(Record));
        memcpy(newRecord, &r, sizeof(Record));
        offsets[recordCount % WINDOW_SIZE] = totalMemoryUsage;
        keys[recordCount % WINDOW_SIZE] = r.key;
        records[recordCount % WINDOW_SIZE] = *newRecord;
        recordCount++;
        totalMemoryUsage += sizeof(Record);

        // Update the sliding window by removing the oldest record and adding the newest one
        offsets[(recordCount - 1) % WINDOW_SIZE] = -1;
        keys[(recordCount - 1) % WINDOW_SIZE] = -1;
        records[(recordCount - 1) % WINDOW_SIZE].key = -1;
        records[(recordCount - 1) % WINDOW_SIZE].timestamp = -1;
    }

    // Calculate the rolling average of the 'int' values in the sliding window
    int rollingAverage = 0;
    for (size_t i = 0; i < recordCount && i < WINDOW_SIZE; i++) {
        rollingAverage += keys[i];
    }
    if (recordCount > 0) {
        rollingAverage /= recordCount;
    }

    // Calculate the weighted average of the 'double' timestamp values in the sliding window
    double weightedAverage = 0;
    for (size_t i = 0; i < recordCount && i < WINDOW_SIZE; i++) {
        weightedAverage += records[i].timestamp * keys[i];
    }
    if (recordCount > 0) {
        weightedAverage /= recordCount;
    }

    // Free the memory allocated for the arrays
    free(offsets);
    free(keys);
    free(records);
}

// Read a single record from standard input
bool readRecord(Record &r) {
    // Check if there is still data in the buffer
    int c = getchar();
    while (c == ' ') {
        c = getchar();
    }

    // If there is no more data, return false
