        return false;
    }

    // Read the key and timestamp from standard input
    int key;
    double timestamp;
    scanf("%d %lf", &key, &timestamp);

    // Check if the record is valid
    if (key < minKey || key > maxKey) {
        return false;
    }

    // Fill in the record structure with the read data
    r.key = key;
    r.timestamp = timestamp;
    return true;
}
```
