        pthread_mutex_unlock(&lock);
        if (connToRemove != NULL) {
            connList->connections[connList->size - 1].metadata.inUse = false;
        }

        // If a new connection needs to be added, add it to the pool and increase the used count
        if (config.pool.used < config.maxConnections) {
            config.pool.connections[config.pool.used].metadata.inUse = true;
            config.pool.connections[config.pool.used].metadata.lastAccessed = time(NULL);
            config.pool.used++;
        }
    }
