void processAndFindMax(int min, int max) {
    // Allocate memory for the arrays of offsets, keys, and records
    size_t num_records = 0;
    int *offsets = NULL;
    int *keys = NULL;
    Record *records = NULL;

    // Create a linked list to track the records
    struct Node {
        Record record;
        struct Node *next;
    };
    struct Node *head = NULL;

    // Initialize the current time in milliseconds since the epoch
    long current_time = 0L;
    time(&current_time);

    while (1) {
        int key;
        Record record;

        // Read an integer from standard input, or exit if no more inputs are available
        if (!fscanf(stdin, "%d", &key)) break;

        // Generate a random number within the specified range for the current record's key and timestamp
        srand((unsigned int)current_time);
        key = min + (int)(rand() % ((max - min) + 1));
        record.timestamp = (double)current_time / 1000.0;

        // Allocate memory for the current record and add it to the linked list
        struct Node *node = malloc(sizeof(struct Node));
        if (!node) {
            fprintf(stderr, "Error: failed to allocate memory for record (%s)\n", strerror(errno));
            break;
        }
        node->record = record;
        node->next = head;
        head = node;

        // Update the current time and continue reading inputs
        current_time++;
    }

    // Free any allocated memory if there were errors
    if (!head) {
        free(offsets);
        free(keys);
        free(records);
    }
}
