// Data structure for storing the data entries
struct Entry {
    int key;
    float value;
    long *offset;
};

// Linked list to store the data entries
struct ListNode {
    struct Entry entry;
    struct ListNode *next;
};

// Global variable to store the head of the linked list
static struct ListNode *head = NULL;

// Global variable to store the number of elements in the linked list
static int num_elements = 0;

// Function to allocate memory for a new entry and add it to the linked list
struct Entry* addEntry(int key, float value, long offset) {
    // Allocate memory for the new entry
    struct Entry *entry = (struct Entry*)malloc(sizeof(struct Entry));
    if (!entry) {
        perror("Failed to allocate memory for the new entry");
        return NULL;
    }

    // Set the values for the new entry
    entry->key = key;
    entry->value = value;
    entry->offset = (long*)malloc(sizeof(long));
    if (!entry->offset) {
        perror("Failed to allocate memory for the offset");
        free(entry);
        return NULL;
    }
    *(entry->offset) = offset;

    // Create a new node in the linked list and add it
    struct ListNode *new_node = (struct ListNode*)malloc(sizeof(struct ListNode));
    if (!new_node) {
        perror("Failed to allocate memory for the new node");
        free(entry->offset);
        free(entry);
        return NULL;
    }
    new_node->entry = *entry;
    new_node->next = head;
    head = new_node;

    // Increment the number of elements in the linked list
    num_elements++;

    return entry;
}

// Function to search for an entry with a given key and return its value
float getValue(int key) {
    // Traverse the linked list until we find the node with the specified key
    struct ListNode *current = head;
    while (current != NULL && current->entry.key != key) {
        current = current->next;
    }

    if (current == NULL) {
        // Key not found
        return 0.0f;
    } else {
        // Return the value of the entry with the specified key
        return current->entry.value;
    }
}

// Function to update a random float value for an entry with a given key
void updateEntry(int key, float new_value) {
    // Traverse the linked list until we find the node with the specified key
    struct ListNode *current = head;
    while (current != NULL && current->entry.key != key) {
        current = current->next;
    }

    if (current == NULL) {
        // Key not found
        return;
    } else {
        // Update the value of the entry with the specified key to a new random value within the specified range
        float min_value = 0.0f;
        float max_value = 100.0f;
        current->entry.value = min_value + (float)rand() / RAND_MAX * (max_value - min_value);
    }
}

// Function to retrieve the long offset value for an entry with a given key
long getOffset(int key) {
    // Traverse the linked list until we find the node with the specified key
    struct ListNode *current = head;
    while (current != NULL && current->entry.key != key) {
        current = current->next;
    }

    if (current == NULL) {
        // Key not found
        return 0L;
    } else {
        // Return the long offset value of the entry with the specified key
        return *(current->entry.offset);
    }
}

// Function to free all memory allocated by the linked list and reset the number of elements to zero
void freeList() {
    struct ListNode *current = head;
    while (current != NULL) {
        // Free the entry and its offset value
        free(current->entry.offset);
        free(current->entry.value);
        current = current->next;
    }
}
