  void* entry = allocate_entry(key, data_point, offset);
  if (!entry) {
    return -1;
  }

  // Add the new entry to the collection
  ((struct collection*)collection)->entries[((struct collection*)collection)->num_entries++] = entry;

  return 0;
}

// Function to iterate over the entries in the collection
void* iterate_entries(struct collection* collection, void (*callback)(void*)) {
  for (int i = 0; i < ((struct collection*)collection)->num_entries; i++) {
    callback(((struct collection*)collection)->entries[i]);
  }
}

// Function to update the float data points in the collection using a user-defined function
void update_data_points(struct collection* collection, void (*user_func)(int key, float *data_point)) {
  for (int i = 0; i < ((struct collection*)collection)->num_entries; i++) {
    user_func(((struct entry*)((struct collection*)collection)->entries[i])->key, &((struct entry*)((struct collection*)collection)->entries[i])->data_point);
  }
}

// Function to remove an entry from the collection by key
int remove_entry(struct collection* collection, int key) {
  // Find the index of the entry with the specified key
  int i = -1;
  for (int j = 0; j < ((struct collection*)collection)->num_entries; j++) {
    if (((struct entry*)((struct collection*)collection)->entries[j])->key == key) {
      i = j;
      break;
    }
  }

  // If the entry was found, remove it from the collection
  if (i != -1) {
    ((struct collection*)collection)->num_entries--;
    for (int j = i; j < ((struct collection*)collection)->num_entries; j++) {
      ((struct collection*)collection)->entries[j] = ((struct collection*)collection)->entries[j + 1];
    }
  } else {
