int processAndFindMax(const char* file_name, const int range_min, const int range_max) {
    // Allocate memory for the offset values, keys, and values arrays
    int* offsets = malloc(sizeof(int) * 3);
    int* keys = malloc(sizeof(int) * 3);
    float* values = malloc(sizeof(float) * 3);
    if (offsets == NULL || keys == NULL || values == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for arrays\n");
        return -1;
    }

    // Initialize the offset values to zero
    offsets[0] = 0;
    offsets[1] = 0;
    offsets[2] = 0;

