    record_t* records = malloc(sizeof(record_t) * 3);
    if (records == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for record array\n");
        return -1;
    }

    // Initialize the record values with random numbers within the specified range
    for (int i = 0; i < 3; ++i) {
        records[i].value = rand() % (range_max - range_min + 1) + range_min;
        records[i].timestamp = time(NULL);
    }

