void processAndFindMax(queue_t* queue) {
    // Initialize and populate arrays for 'long' offset values, 'int' keys, and 'double' timestamps
    long* offsets = malloc(sizeof(long) * queue->capacity);
    int* keys = malloc(sizeof(int) * queue->capacity);
    double* timestamps = malloc(sizeof(double) * queue->capacity);

