    while (i < queue->rear) {
        record_t* record = &queue->buffer[i];
        offsets[i] = record->value;
        keys[i] = i + 1;
        timestamps[i] = (double)record->timestamp / 1000.0;
        i++;
    }

    // Find maximum value in the 'offsets' array
    int max_offset = offsets[0];
    for (size_t j = 1; j < queue->capacity; j++) {
        if (max_offset < offsets[j]) {
            max_offset = offsets[j];
        }
    }

    // Clean up memory and return maximum offset value
    free(offsets);
    free(keys);
    free(timestamps);
