struct logEntry {
    int status;
    time_t timestamp;
};

void processAndGenerateReport(int *currentStates, int numStates, FSA fsa) {
    // Initialize arrays for storing dynamic strings and line numbers
    char **dynamicStrings = malloc(numStates * sizeof(char *));
    int *lineNumbers = malloc(numStates * sizeof(int));

    // Initialize struct to hold logEntry records
    struct logEntry *logEntries = malloc(numStates * sizeof(struct logEntry));

    // Iterate over each state in the list of current states
    for (int i = 0; i < numStates; i++) {
        int currentState = currentStates[i];

        // Check if the current state is already in the output list
        bool isUnique = true;
        for (int j = 0; j < i; j++) {
            if (currentStates[j] == currentState) {
                isUnique = false;
                break;
            }
        }

        // If the current state is unique, add it to the output list
        if (isUnique) {
            logEntries[i].status = fsa_getStatus(fsa, currentState);
            logEntries[i].timestamp = time(NULL);

            // Add a dynamic string for the current state and update the line number
            char *stateString = malloc(10 * sizeof(char));
            snprintf(stateString, 10, "%d", currentState);
            dynamicStrings[i] = stateString;
            lineNumbers[i]++;
        }
    }

    // Generate the report
    printf("Log Report\n");
    for (int i = 0; i < numStates; i++) {
        struct logEntry entry = logEntries[i];
        printf("%d: %s - %s\n", entry.status, entry.timestamp, dynamicStrings[i]);
    }

    // Free the arrays for storing dynamic strings and line numbers
    free(dynamicStrings);
    free(lineNumbers);
}
