#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

// A structure to store record information
struct Record {
  int key;
  double measurement;
  time_t timestamp;
  int version; // Version history to track changes over time
};

// A data structure to store records in a dynamic array
struct Records {
  struct Record **records;
  size_t num_records;
  size_t capacity;
  pthread_mutex_t mutex;
};

// Function to add a new record to the database
int addRecord(struct Records *db, int key, double measurement) {
  // Acquire lock on the database
  pthread_mutex_lock(&db->mutex);

  // Check if the key is already in the database
  for (size_t i = 0; i < db->num_records; i++) {
    if (db->records[i]->key == key) {
      // Key already exists, return -1
      pthread_mutex_unlock(&db->mutex);
      return -1;
    }
  }

  // If the key is not in the database, add a new record
  if (db->num_records == db->capacity) {
    // Increase capacity of the dynamic array if necessary
    db->capacity *= 2;
    struct Record **new_records = realloc(db->records, sizeof(struct Record *) * db->capacity);
    if (new_records == NULL) {
      // Handle out-of-memory condition gracefully
      pthread_mutex_unlock(&db->mutex);
      return -1;
    }
    db->records = new_records;
  }

  // Create a new record and add it to the database
  struct Record *new_record = malloc(sizeof(struct Record));
  if (new_record == NULL) {
    // Handle out-of-memory condition gracefully
    pthread_mutex_unlock(&db->mutex);
    return -1;
  }
  new_record->key = key;
  new_record->measurement = measurement;
  new_record->timestamp = time(NULL);
  new_record->version = 0;
  db->records[db->num_records++] = new_record;

  // Release lock on the database
  pthread_mutex_unlock(&db->mutex);

  return 0;
}

// Function to update an existing record in the database
int updateRecord(struct Records *db, int key, double measurement) {
  // Acquire lock on the database
  pthread_mutex_lock(&db->mutex);

  // Check if the key is in the database
  for (size_t i = 0; i < db->num_records; i++) {
    if (db->records[i]->key == key) {
      // Increment version of the record
      db->records[i]->version++;
      // Update measurement and timestamp of the record
      db->records[i]->measurement = measurement;
      db->records[i]->timestamp = time(NULL);
      break;
    }
  }

  // Release lock on the database
  pthread_mutex_unlock(&db->mutex);

  return 0;
}

// Function to retrieve a record from the database
struct Record *getRecord(struct Records *db, int key) {
  struct Record *record = NULL;

  // Acquire lock on the database
  pthread_mutex_lock(&db->mutex);

  // Check if the key is in the database
  for (size_t i = 0; i < db->num_records; i++) {
    if (db->records[i]->key == key) {
      record = db->records[i];
      break;
    }
  }

  // Release lock on the database
  pthread_mutex_unlock(&db->mutex);

  return record;
}

// Function to calculate average, minimum and maximum of precision measurements in the database
void calculateSummary(struct Records *db) {
  double sum = 0.0;
  double min = DBL_MAX;
  double max = -DBL_MAX;

  // Acquire lock on the database
  pthread_mutex_lock(&db->mutex);

  for (size_t i = 0; i < db->num_records; i++) {
    sum += db->records[i]->measurement;
    if (min > db->records[i]->measurement) {
      min = db->records[i]->measurement;
    }
    if (max < db->records[i]->measurement) {
      max = db->records[i]->measurement;
    }
  }

  // Release lock on the database
  pthread_mutex_unlock(&db->mutex);

  printf("Average: %f\n", sum / (double)db->num_records);
  printf("Minimum: %f\n", min);
  printf("Maximum: %f\n", max);
}
