#include <stdbool.h>
#include <pthread.h>
#include <errno.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <stdint.h>

struct record {
    int key;
    long offset;
};

struct record_array {
    struct record *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
};

void record_array_init(struct record_array *arr, size_t initial_capacity) {
    arr->capacity = initial_capacity;
    arr->count = 0;
    arr->records = (struct record *)malloc(initial_capacity * sizeof(struct record));
    pthread_mutex_init(&arr->mutex, NULL);
}

void record_array_destroy(struct record_array *arr) {
    free(arr->records);
    arr->count = 0;
    arr->capacity = 0;
    pthread_mutex_destroy(&arr->mutex);
}

bool record_array_add(struct record_array *arr, int key, long offset) {
    struct record new_record = {key, offset};
    pthread_mutex_lock(&arr->mutex);
    if (arr->count == arr->capacity) {
        // Resize the array if it's full
        size_t new_capacity = arr->capacity * 2;
        struct record *new_records = realloc(arr->records, new_capacity * sizeof(struct record));
        if (!new_records) {
            pthread_mutex_unlock(&arr->mutex);
            return false;
        }
        arr->records = new_records;
        arr->capacity = new_capacity;
    }
    arr->records[arr->count] = new_record;
    arr->count++;
    pthread_mutex_unlock(&arr->mutex);
    return true;
}

struct record *record_array_get(struct record_array *arr, int key) {
    pthread_mutex_lock(&arr->mutex);
    for (size_t i = 0; i < arr->count; i++) {
        if (arr->records[i].key == key) {
            struct record *record = &arr->records[i];
            pthread_mutex_unlock(&arr->mutex);
            return record;
        }
    }
    pthread_mutex_unlock(&arr->mutex);
    return NULL;
}

void record_array_update(struct record_array *arr, int key, long offset) {
    pthread_mutex_lock(&arr->mutex);
    struct record *record = record_array_get(arr, key);
    if (record != NULL) {
        record->offset = offset;
    }
    pthread_mutex_unlock(&arr->mutex);
}

void record_array_clear(struct record_array *arr) {
    pthread_mutex_lock(&arr->mutex);
    arr->count = 0;
    pthread_mutex_unlock(&arr->mutex);
}

int main() {
    // Initialize the array with an initial capacity of 10
    struct record_array *arr = (struct record_array *)malloc(sizeof(struct record_array));
    record_array_init(arr, 10);

    // Add records to the array using record_array_add()
    for (int i = 0; i < 10; i++) {
        struct record new_record = {i, 0};
        record_array_add(arr, new_record.key, new_record.offset);
    }

    // Update a record in the array using record_array_update()
    record_array_update(arr, 5, 100);

    // Retrieve a record from the array using record_array_get()
    struct record *record = record_array_get(arr, 5);
    if (record != NULL) {
        printf("Record with key %d has offset %ld\n", record->key, record->offset);
    } else {
        printf("No record found for key 5\n");
    }

    // Clear the array using record_array_clear()
    record_array_clear(arr);

    // Destroy the array using record_array_destroy()
    record_array_destroy(arr);
    free(arr);
    return 0;
}']

