    *keys = (int *)malloc(sizeof(int) * (*num_keys));
    if (*keys == NULL) {
        fprintf(stderr, "Failed to allocate memory for keys\n");
        exit(1);
    }

    // Allocate memory for the record array
    *records = (Record *)malloc(sizeof(Record) * (*num_records));
    if (*records == NULL) {
        fprintf(stderr, "Failed to allocate memory for records\n");
        exit(1);
    }
}

// Function to populate the graph database with vertices and edges
void populate_graph(size_t num_records, Record *records, GraphDatabase *db) {
    // Loop through each record and add a vertex for the offset and key
    for (int i = 0; i < num_records; i++) {
        Record *record = &records[i];
        long offset = record->offset;
        int key = record->key;

        // Add a vertex for the offset
        GraphVertex *offset_vertex = graph_database_add_vertex(db, offset);
        if (offset_vertex == NULL) {
            fprintf(stderr, "Failed to add vertex for offset\n");
            exit(1);
        }

        // Add a vertex for the key
        GraphVertex *key_vertex = graph_database_add_vertex(db, key);
        if (key_vertex == NULL) {
            fprintf(stderr, "Failed to add vertex for key\n");
            exit(1);
        }

        // Add an edge between the offset and key vertices
        GraphEdge *edge = graph_database_add_edge(db, offset_vertex, key_vertex);
        if (edge == NULL) {
            fprintf(stderr, "Failed to add edge between offset and key\n");
            exit(1);
        }
    }
}

// Function to safely retrieve a random record based on an index
Record *get_random_record(size_t num_records, Record *records) {
    // Generate a random index within the range of the records
    int random_index = (int)(num_records * ((double)rand() / RAND_MAX));

    // Ensure the index is valid and return the corresponding record
    if (random_index >= num_records || random_index < 0) {
        fprintf(stderr, "Invalid random index: %d\n", random_index);
        exit(1);
    }
    Record *record = &records[random_index];
    return record;
}

// Function to handle potential network latency and transient failures
void handle_failure(size_t num_records, Record **records) {
    // Retry logic for network latency and transient failures
    int retry_count = 0;
    while (retry_count < 3) {
        try {
            return get_random_record(num_records, records);
        } catch (NetworkLatencyException e) {
            fprintf(stderr, "Network latency exception: %s\n", e.what());
            retry_count++;
        } catch (TransientFailureException e) {
            fprintf(stderr, "Transient failure exception: %s\n", e.what());
            retry_count++;
        }
    }

    // Fallback strategy for network latency and transient failures
    fprintf(stderr, "Falling back to alternative retrieval method\n");
    return get_random_record(num_records, records);
}

// Function to log memory usage and allocation failures
void log_memory_usage(size_t num_records, Record *records) {
    // Log the total size of all arrays
    long total_size = sizeof(long) * num_records + sizeof(int) * num_records + sizeof(Record) * num_records;
    fprintf(stderr, "Total memory usage: %lu bytes\n", total_size);

    // Log any allocation failures
    if (num_records > 0 && records == NULL) {
        fprintf(stderr, "Failed to allocate memory for records\n");
    }
}

// Function to manage dynamic allocation and manipulation of complex data structures in a resource-constrained environment
void manage_complex_data_structures(size_t num_records, size_t *num_offsets, size_t *num_keys, Record **records) {
    // Allocate memory for the arrays
    allocate_memory(num_records, num_offsets, num_keys, records);

    // Populate the graph database with vertices and edges
    GraphDatabase db = populate_graph(num_records, *records, db);

    // Safely retrieve a random record based on an index
    Record *random_record = get_random_record(num_records, *records);

    // Handle potential network latency and transient failures
    handle_failure(num_records, records);

    // Log memory usage and allocation failures
    log_memory_usage(num_records, *records);

    // Free the allocated memory to prevent memory leaks
    free(*offsets);
    free(*keys);
    free(*records);
}
