void processAndGenerateReport(int socket) {
    int bufferSize = BUFFER_SIZE; // Adjust this value to balance between memory usage and performance
    int maxEntries = MAX_ENTRIES; // Adjust this value to limit the maximum number of entries in the log file
    logEntry* logData = (logEntry*) malloc(maxEntries * sizeof(logEntry));
    time_t* timestamps = (time_t*) malloc(maxEntries * sizeof(time_t));
    int* occurrenceCounts = (int*) malloc(256 * sizeof(int));
    if (!logData || !timestamps || !occurrenceCounts) {
        perror("Failed to allocate memory for log data");
        return;
    }

    // Initialize the occurrence counts to zero
    memset(occurrenceCounts, 0, 256 * sizeof(int));

    // Create a thread pool to handle concurrent access and avoid deadlocks
    int numThreads = sysconf(_SC_NPROCESSORS_ONLN);
    pthread_t* threads = (pthread_t*) malloc(numThreads * sizeof(pthread_t));
    if (!threads) {
        perror("Failed to allocate memory for thread pool");
        return;
    }

    // Initialize the thread pool and create a thread for each CPU core
    pthread_attr_t attr;
    pthread_attr_init(&attr);
    pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_JOINABLE);
    int i;
    for (i = 0; i < numThreads; ++i) {
        if (pthread_create(&threads[i], &attr, processLogEntry, NULL)) {
            perror("Failed to create thread");
            return;
        }
    }

    // Initialize the network socket connection and read log entries in real-time
    while (1) {
        char* buffer = (char*) malloc(bufferSize * sizeof(char));
        if (!buffer) {
            perror("Failed to allocate memory for network buffer");
            return;
        }
        ssize_t bytesRead = read(socket, buffer, bufferSize);
        if (bytesRead < 0) {
            perror("Error reading from network socket");
            break;
        } else if (bytesRead == 0) {
            // If the connection is closed by the server, exit the loop
            break;
        }

        // Parse the log entries and update the occurrence counts
        char* token = strtok(buffer, "\n");
        while (token != NULL) {
            logEntry entry;
            memset(&entry, 0, sizeof(logEntry));
            entry.status = token[0];
            entry.timestamp = time(NULL);
            entry.count = 1;
            occurrenceCounts[entry.status]++;
            pthread_mutex_lock(&mutex);
            logData[index++] = entry;
            timestamps[index++] = entry.timestamp;
            pthread_mutex_unlock(&mutex);
            token = strtok(NULL, "\n");
        }
    }

    // Wait for all threads to finish before generating the report
    int i;
    for (i = 0; i < numThreads; ++i) {
        if (pthread_join(threads[i], NULL)) {
            perror("Failed to join thread");
            return;
        }
    }

    // Generate the report based on the log data and occurrence counts
