int processAndFindMax(record_t *records, int num_records) {
  // Initialize variables for memory management and logging
  int i, max = -1;
  time_t start_time = time(NULL);
  FILE *log_file = fopen("process.log", "w");

  // Loop through the records and find the maximum value
  for (i = 0; i < num_records; i++) {
    if (max < records[i].value) {
      max = records[i].value;
    }

    // Log processing steps for monitoring and debugging purposes
    fprintf(log_file, "%d/%d: Processed record %d with value %d\n", i + 1, num_records, i, records[i].value);
  }

  // Close the log file and return the maximum value
  fclose(log_file);
  return max;
}

// Define a signal handler to gracefully recover from unexpected interruptions
void signalHandler(int sig) {
  printf("Caught signal %d\n", sig);
  // Clean up resources and exit the function
  exit(EXIT_FAILURE);
}

// Implement concurrency by creating a thread for each record
pthread_t threads[10000];
int i, status;
for (i = 0; i < num_records; i++) {
  if (pthread_create(&threads[i], NULL, processAndFindMax, &records[i])) {
    perror("Error creating thread");
    exit(EXIT_FAILURE);
  }
}

// Join all threads and return the maximum value
int max = -1;
for (i = 0; i < num_records; i++) {
  if (pthread_join(threads[i], &status)) {
    perror("Error joining thread");
    exit(EXIT_FAILURE);
  }
  max = status > max ? status : max;
}

return max;
