// Struct for sensor readings
typedef struct SensorReading {
    double temperature;
    double location[2]; // latitude, longitude
    char log_message[100];
    uint64_t timestamp;
} SensorReading;

// Circular buffer for log messages
#define LOG_BUFFER_SIZE 100
static SensorReading log_buffer[LOG_BUFFER_SIZE];
static int log_index = 0; // index of next free slot in log buffer

bool insert_sensor_reading(SensorReading reading) {
    // Check if temperature is within range and timestamp is sequential
    if (reading.temperature < MIN_TEMPERATURE || reading.temperature > MAX_TEMPERATURE ||
        log_buffer[log_index].timestamp != reading.timestamp - 1) {
        return false; // invalid data, do not insert
    }

    // Insert reading into circular buffer
    memcpy(&log_buffer[log_index], &reading, sizeof(SensorReading));
    log_index = (log_index + 1) % LOG_BUFFER_SIZE;

    return true; // data inserted successfully
}

void manage_sensor_readings() {
    static int num_readings = 0; // number of valid readings received since last call to manage_sensor_readings
    SensorReading *current_reading = NULL; // pointer to current reading being processed

    while (num_readings < MAX_NUM_READINGS) {
        // Acquire mutex for shared resource
        acquire_mutex();

        // Check if there are any available readings in the circular buffer
        if (log_index == 0) {
            // No more readings available, release mutex and return
            release_mutex();
            break;
        }

        current_reading = &log_buffer[log_index - 1]; // get pointer to last reading in circular buffer

        // Check if reading is valid
        if (current_reading->temperature < MIN_TEMPERATURE || current_reading->temperature > MAX_TEMPERATURE ||
            current_reading->timestamp != num_readings) {
            // Invalidate the reading and release mutex
            log_buffer[log_index - 1].timestamp = 0; // invalidate reading
            release_mutex();
        } else {
            // Valid reading, process it
            process_sensor_reading(current_reading);

            // Release mutex and increment number of valid readings received since last call to manage_sensor_readings
            num_readings++;
            release_mutex();
        }
    }
}

