int compareWeatherRecords(const void* a, const void* b) {
    struct weatherRecord* recordA = (struct weatherRecord*)a;
    struct weatherRecord* recordB = (struct weatherRecord*)b;

    // Compare the timestamps of the two records
    if (recordA->timestamp < recordB->timestamp) {
        return -1;
    } else if (recordA->timestamp > recordB->timestamp) {
        return 1;
    }

    // If the timestamps are equal, compare the temperatures
    if (recordA->temperature < recordB->temperature) {
        return -1;
    } else if (recordA->temperature > recordB->temperature) {
