// Define the record structure
typedef struct {
  int key;
  int value;
} Record;

// Define the hash function
unsigned long hash(int key) {
  return key % (UINT_MAX / 2);
}

// Define the dynamic resizable array of records
Record *records = NULL;
size_t record_capacity = 0;
size_t record_count = 0;

// Initialize the records with a specified capacity and load factor
void init_records(size_t capacity, float load_factor) {
  // Allocate memory for the records
  records = malloc(sizeof(Record) * capacity);
  if (records == NULL) {
    printf("Error: Failed to allocate memory for records\n");
    return;
  }
  record_capacity = capacity;
  record_count = 0;
}

// Add a new record with a specified key and value
void add_record(int key, int value) {
  // Check if the array needs to be resized
  if (record_count >= record_capacity * load_factor) {
    // Resize the array by a factor of 2
    size_t new_size = record_capacity * 2;
    Record *new_records = realloc(records, sizeof(Record) * new_size);
    if (new_records == NULL) {
      printf("Error: Failed to resize records\n");
      return;
    }
    records = new_records;
    record_capacity = new_size;
  }

  // Insert the new record at the end of the array
  Record *record = &records[record_count];
  record->key = key;
  record->value = value;
  ++record_count;
}

// Get the value associated with a specified key
int get_value(int key) {
  // Compute the index of the hash table slot for the given key
  size_t index = hash(key) % (record_capacity);

  // Search for the record in the array starting from the computed slot
  Record *record;
  for (size_t i = 0; i < record_count; ++i) {
    record = &records[index];
    if (record->key == key) {
      return record->value;
    }
    index = (index + 1) % record_capacity;
  }

  // If no matching record is found, return -1
  return -1;
}

// Free the memory allocated for the records
void free_records() {
  if (records != NULL) {
    free(records);
  }
  record_capacity = 0;
  record_count = 0;
}
