#include <stdlib.h>
#include <string.h>
#include <math.h>

// Define the record structure
typedef struct {
    int key;
    int value;
} record;

// Define the hash table data structure
typedef struct {
    int size; // current size of the table
    int capacity; // maximum number of elements in the table
    record** buckets; // array of pointers to records
} hash_table;

// Custom hash function that takes a key and returns an index in the table
int hash(int key) {
    return key % (capacity - 1);
}

// Initialize a new empty hash table with the specified capacity
hash_table* create_hash_table(int capacity) {
    hash_table* table = malloc(sizeof(hash_table));
    if (!table) {
        return NULL;
    }
    table->size = 0;
    table->capacity = capacity;
    table->buckets = malloc(sizeof(record*) * capacity);
    if (!table->buckets) {
        free(table);
        return NULL;
    }
    memset(table->buckets, 0, sizeof(record*) * capacity);
    return table;
}

// Insert a new record into the hash table with the specified key and value
void insert_record(hash_table* table, int key, int value) {
    // Calculate the index of the slot in which to store the record
    int index = hash(key);
    while (table->buckets[index] != NULL) {
        if (table->buckets[index]->key == key) {
            table->buckets[index]->value = value;
            return;
        }
        // Increase the index by 1 and continue searching for an empty slot
        index = (index + 1) % table->capacity;
    }
    // Create a new record with the specified key and value, and store it in the hash table
    record* new_record = malloc(sizeof(record));
    if (!new_record) {
        return;
    }
    new_record->key = key;
    new_record->value = value;
    table->buckets[index] = new_record;
    table->size++;
}

// Look up a record in the hash table by its key and return its value
int lookup(hash_table* table, int key) {
    // Calculate the index of the slot that contains the record with the specified key
    int index = hash(key);
    while (table->buckets[index] != NULL) {
        if (table->buckets[index]->key == key) {
            return table->buckets[index]->value;
        }
        // Increase the index by 1 and continue searching for a matching record
        index = (index + 1) % table->capacity;
    }
    // If no matching record is found, return -1 to indicate that the key does not exist in the table
    return -1;
}

// Delete a record from the hash table by its key and return its value
int delete(hash_table* table, int key) {
    // Calculate the index of the slot that contains the record with the specified key
    int index = hash(key);
    while (table->buckets[index] != NULL) {
        if (table->buckets[index]->key == key) {
            int value = table->buckets[index]->value;
            free(table->buckets[index]);
            table->buckets[index] = NULL;
            table->size--;
            return value;
        }
        // Increase the index by 1 and continue searching for a matching record
        index = (index + 1) % table->capacity;
    }
    // If no matching record is found, return -1 to indicate that the key does not exist in the table
    return -1;
}

// Free all memory allocated by the hash table
void destroy_hash_table(hash_table* table) {
    for (int i = 0; i < table->capacity; i++) {
        if (table->buckets[i] != NULL) {
            free(table->buckets[i]);
            table->buckets[i] = NULL;
        }
    }
    free(table->buckets);
    free(table);
}
```
This function implements a hash table that can be used to store and retrieve records with integer keys. The hash function `hash` takes a key and returns an index in the table, which is used to calculate the slot where the record should be stored or retrieved. The function `create_hash_table` creates a new empty hash table with the specified capacity, while `insert_record`, `lookup`, and `delete` insert, look up, and delete records from the table respectively. Finally, `destroy_hash_table` frees all memory allocated by the hash table.

The function `create_hash_table` uses a dynamic array to store the buckets of the hash table. Each bucket is an array of pointers to records, where each pointer points to a record in the table. The size of the hash table is stored separately from the buckets, so that it can be easily accessed and updated.

The function `insert_record` uses a simple loop to find the first empty slot in the bucket corresponding to the key, and then stores the new record there. If no empty slot is found, the function increases the capacity of the table by 1 and rehashes all the records to their new positions. The `lookup` function works similarly, using a simple loop to find the matching record in the bucket corresponding to the key. If no match is found, -1 is returned to indicate that the key does not exist in the table.

