    if (!root) {
        fprintf(stderr, "Failed to open configuration file: %s\n", file);
        return;
    }

    config->algorithm = json_object_get_string(json_object_object_get(root, "algorithm"));
    config->key_size = json_object_get_int(json_object_object_get(root, "key_size"));

    // Parse encryption/decryption keys
