        json_object *encryption_key = json_object_object_get(root, "encryption_key");
        config->encryption_key = json_object_get_string(encryption_key);

        json_object *decryption_key = json_object_object_get(root, "decryption_key");
        config->decryption_key = json_object_get_string(decryption_key);
