// Define encryption/decryption function
void encrypt_decrypt(const unsigned char *input, const unsigned char *key, int key_size, enum OPERATIONS op) {
    EVP_CIPHER_CTX *ctx;

    // Initialize encryption context
    if ((ctx = EVP_CIPHER_CTX_new()) == NULL) {
