        return;
    }

    // Set cipher and key length
    if (EVP_EncryptInit_ex(ctx, EVP_get_cipherbyname(config->algorithm), NULL, NULL, NULL) <= 0) {
        fprintf(stderr, "Failed to set encryption algorithm\n");
        EVP_CIPHER_CTX_free(ctx);
        return;
