    if (op == ENCRYPT || op == DECRYPT) {
        if (EVP_CIPHER_CTX_set_key_length(ctx, key_size) <= 0) {
            fprintf(stderr, "Failed to set encryption key length\n");
            EVP_CIPHER_CTX_free(ctx);
            return;
        }
    }

