    if (EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, 16, NULL) <= 0) {
        fprintf(stderr, "Failed to set IV length\n");
        EVP_CIPHER_CTX_free(ctx);
        return;
    }

    // Set key and IV for encryption/decryption
    if (EVP_EncryptInit_ex(ctx, NULL, NULL, key, iv) <= 0) {
        fprintf(stderr, "Failed to set encryption key or IV\n");
        EVP_CIPHER_CTX_free(ctx);
        return;
    }

