    int outlen = 0;
    while (inlen > 0) {
        // Encrypt/decrypt input chunk and get output length
        if (EVP_EncryptUpdate(ctx, NULL, &outlen, input, inlen) <= 0) {
            fprintf(stderr, "Failed to encrypt/decrypt input data\n");
            EVP_CIPHER_CTX_free(ctx);
            return;
        }

        // Reallocate output buffer for next chunk
        out = realloc(out, outlen);
        if (!out) {
            fprintf(stderr, "Failed to allocate memory for output data\n");
            EVP_CIPHER_CTX_free(ctx);
            return;
        }

        // Encrypt/decrypt input chunk and get output data
        if (EVP_EncryptUpdate(ctx, out, &outlen, input, inlen) <= 0) {
            fprintf(stderr, "Failed to encrypt/decrypt input data\n");
            EVP_CIPHER_CTX_free(ctx);
            return;
        }

        // Update input and output lengths
        inlen -= CHUNK_SIZE;
    }

    // Finalize encryption/decryption and get tag
    if (EVP_EncryptFinal_ex(ctx, NULL, &taglen) <= 0) {
        fprintf(stderr, "Failed to finalize encryption\n");
        EVP_CIPHER_CTX_free(ctx);
        return;
    }

