        fprintf(stderr, "Failed to finalize encryption\n");
        EVP_CIPHER_CTX_free(ctx);
        return;
    }

    // Free encryption context
    EVP_CIPHER_CTX_free(ctx);
}

// Define signature/verification function
void sign_verify(const unsigned char *input, const unsigned char *key, int key_size, enum OPERATIONS op) {
    RSA *rsa;

    // Initialize RSA context
    if ((rsa = RSA_new()) == NULL) {
        fprintf(stderr, "Failed to initialize RSA context\n");
        return;
    }

    // Set key length and modulus
    if (RSA_set_key_size(rsa, key_size) <= 0 ||
            RSA_set0_key(rsa, NULL, key, NULL) <= 0) {
        fprintf(stderr, "Failed to set RSA key length or modulus\n");
        RSA_free(rsa);
        return;
    }

    // Sign/verify input data
    if (op == SIGN) {
        // Sign input data using RSA private key
        if ((sig = RSA_sign(NID_sha256, input, inlen, sig, &siglen, rsa)) <= 0) {
            fprintf(stderr, "Failed to sign input data\n");
            RSA_free(rsa);
            return;
        }

        // Reallocate signature buffer for next chunk
        sig = realloc(sig, siglen);
        if (!sig) {
            fprintf(stderr, "Failed to allocate memory for output data\n");
            RSA_free(rsa);
            return;
        }

        // Get signature length
        if (RSA_sign(NID_sha256, input, inlen, sig, &siglen, rsa) <= 0) {
            fprintf(stderr, "Failed to get signature length\n");
            RSA_free(rsa);
            return;
        }
    } else {
        // Verify input data using RSA public key
        if (RSA_verify(NID_sha256, input, inlen, sig, siglen, rsa) <= 0) {
            fprintf(stderr, "Failed to verify input data\n");
            RSA_free(rsa);
            return;
        }
    }

    // Free RSA context
    RSA_free(rsa);
}

