    if (read != size) {
        fprintf(stderr, "Failed to read from input file\n");
        return EXIT_FAILURE;
    }

    // Close input file
    fclose(infile);

    // Get public/private key from environment variables
    const char *pubkey = getenv("PUBKEY");
    if (!pubkey) {
        fprintf(stderr, "Failed to read public key from environment variable\n");
        return EXIT_FAILURE;
    }

    const char *privkey = getenv("PRIVKEY");
    if (!privkey) {
        fprintf(stderr, "Failed to read private key from environment variable\n");
        return EXIT_FAILURE;
    }

    // Initialize OpenSSL library
    SSL_library_init();

    // Create new RSA object
    RSA *rsa = RSA_new();
    if (!rsa) {
        fprintf(stderr, "Failed to create RSA object\n");
        return EXIT_FAILURE;
    }

    // Set public/private key for RSA object
