        size = RSA_public_encrypt(size, input, output, rsa, RSA_PKCS1_PADDING);
        if (size < 0) {
            fprintf(stderr, "Failed to encrypt data\n");
            return EXIT_FAILURE;
        }
    } else {
        size = RSA_private_decrypt(size, input, output, rsa, RSA_PKCS1_PADDING);
        if (size < 0) {
            fprintf(stderr, "Failed to decrypt data\n");
            return EXIT_FAILURE;
        }
    }

    // Write output data to file
    FILE *outfile = fopen("output", "wb");
    if (!outfile) {
        fprintf(stderr, "Failed to open output file\n");
        return EXIT_FAILURE;
    }

    size_t written = fwrite(output, 1, size, outfile);
    if (written != size) {
        fprintf(stderr, "Failed to write to output file\n");
        return EXIT_FAILURE;
    }

    // Close output file
    fclose(outfile);

    // Free memory for input and output data
    free(input);
    free(output);

    // Free RSA object
    RSA_free(rsa);

    return EXIT_SUCCESS;
}
