['Here is an example implementation of the C function to dynamically allocate memory for a complex event logging system:
```c
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <assert.h>

// Define log stream structure
struct log_stream {
    int id;
    char* name;
    struct log_stream* next;
};

// Define context element structure
struct context_element {
    // Store values of different types in a flexible way
    void* value;
    enum type { INT, STRING, BOOL } type;
};

// Define event structure
struct event {
    long timestamp;
    char* message;
    int priority;
    struct context_element* context;
    struct event* next;
};

// Define log configuration structure
struct log_configuration {
    int depth;
    int num_log_streams;
    struct log_stream* log_streams[1000]; // Maximum 1000 nesting levels
    struct event* events[1000]; // Maximum 1000 events per log stream
};

// Initialize log configuration
void init_log_configuration(struct log_configuration* config) {
    for (int i = 0; i < config->num_log_streams; ++i) {
        struct log_stream* stream = &config->log_streams[i];
        stream->id = i + 1;
        stream->name = NULL;
        stream->next = NULL;
    }
}

// Load log configuration from file
void load_log_configuration(const char* filename, struct log_configuration* config) {
    // Open file and check for errors
    FILE* fp = fopen(filename, "r");
    if (fp == NULL) {
        printf("Error: unable to open configuration file\n");
        return;
    }

    // Initialize log streams and events
    init_log_configuration(config);

    // Parse file line by line
    char* line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, fp)) != -1) {
        // Check for comments and empty lines
        if (line[0] == '#' || line[0] == '\n') continue;

        // Parse stream name and id
        char* token = strtok(line, " ");
        int stream_id = atoi(token);

        // Create new log stream if needed
        if (stream_id > config->depth) {
            printf("Error: invalid nesting level\n");
            return;
        }
        struct log_stream* stream = &config->log_streams[stream_id - 1];
        if (stream->name == NULL) {
            stream->name = strdup(token);
        } else {
            printf("Error: duplicate stream name\n");
            return;
        }

        // Parse event data
        token = strtok(NULL, " ");
        long timestamp = atol(token);
        token = strtok(NULL, " ");
        char* message = strdup(token);
        token = strtok(NULL, " ");
        int priority = atoi(token);
        struct context_element* context = NULL;
        for (int i = 0; i < config->depth; ++i) {
            token = strtok(NULL, " ");
            if (token == NULL) break;
            int value_type = -1;
            void* value = NULL;
            switch (value_type) {
                case INT:
                    value = malloc(sizeof(int));
                    *(int*)value = atoi(token);
                    break;
                case STRING:
                    value = strdup(token);
                    break;
                case BOOL:
                    value = malloc(sizeof(bool));
                    *(bool*)value = token[0] == 't' || token[0] == 'T';
                    break;
            }
            struct context_element* element = malloc(sizeof(struct context_element));
            element->type = value_type;
            element->value = value;
            if (context == NULL) {
                context = element;
            } else {
                // Add element to linked list of context elements
                struct context_element* current = context;
                while (current->next != NULL) {
                    current = current->next;
                }
                current->next = element;
            }
        }

        // Create new event if needed
        if (stream->events == NULL) {
            stream->events = malloc(sizeof(struct event));
            struct event* event = &config->events[stream_id - 1];
            event->timestamp = timestamp;
            event->message = message;
            event->priority = priority;
            event->context = context;
        } else {
            // Add event to linked list of events
            struct event* current = &config->events[stream_id - 1];
            while (current->next != NULL) {
                current = current->next;
            }
            current->next = malloc(sizeof(struct event));
            struct event* new_event = current->next;
            new_event->timestamp = timestamp;
            new_event->message = message;
            new_event->priority = priority;
            new_event->context = context;
        }
    }

    // Close file and check for errors
    if (ferror(fp)) {
        printf("Error: unable to read from configuration file\n");
        return;
    }

    fclose(fp);
}

// Free log configuration resources
void free_log_configuration(struct log_configuration* config) {
    for (int i = 0; i < config->num_log_streams; ++i) {
        struct log_stream* stream = &config->log_streams[i];
        if (stream->name != NULL) free(stream->name);
        if (stream->events != NULL) free(stream->events);
    }
    for (int i = 0; i < config->num_log_streams * config->depth; ++i) {
        struct event* event = &config->events[i];
        if (event->context != NULL) {
            // Free linked list of context elements
            struct context_element* current = event->context;
            while (current != NULL) {
                void* value = current->value;
                free(value);
                struct context_element* next = current->next;
                free(current);
                current = next;
            }
        }
    }
}

// Main function
int main() {
    // Load log configuration from file
    char* config_file = "log_config.txt";
    struct log_configuration config;
    load_log_configuration(config_file, &config);

    // Free log configuration resources
    free_log_configuration(&config);
    return 0;
}
```

This code reads the contents of a file `log_config.txt` and loads the log configuration into the `struct log_configuration`. The file should have the following format:
```
[stream_id] [timestamp] [message] [priority] [context1] [context2] ...
```
Where `[stream_id]` is the ID of the stream, `[timestamp]` is a timestamp in milliseconds since the epoch, `[message]` is a string representing the log message, `[priority]` is an integer representing the priority level (0-3), and `[context1]` to `[contextN]` are context elements in the format described above.

The `load_log_configuration` function parses the contents of the file and creates a new `struct log_configuration`. It allocates memory for the stream names, events, and context elements. If there is an error while parsing the file, it returns `-1`. Otherwise, it returns `0`.

The `free_log_configuration` function frees the memory allocated by the `load_log_configuration` function. It should be called after the log configuration has been used to ensure that all resources are properly released.

In this example, we assume that the `struct log_configuration` contains a field for the number of streams and events, as well as arrays of stream names and event data. We also assume that the `load_log_configuration` function is responsible for loading the configuration from the file into these fields.

The `free_log_configuration` function frees the memory allocated by the `load_log_configuration` function by iterating over all streams, events, and context elements and calling `free` on each one. This ensures that all resources are properly released when the log configuration is no longer needed.']

