// Custom memory allocator with aligned and unaligned support
#define ALIGNMENT 16

void* my_malloc(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) return NULL;
    // Align the pointer to a multiple of 16 bytes
    ptrdiff_t diff = (ptrdiff_t)ptr % ALIGNMENT;
    if (diff != 0) {
        diff = ALIGNMENT - diff;
        char *tmp = (char*)ptr + diff;
        tmp -= ((size_t)tmp % ALIGNMENT);
        ptr = tmp;
    }
    return ptr;
}

void my_free(void* ptr) {
    free(ptr);
}

