// Current capacity of the arrays
static size_t capacity = 0;

// Growth factor for the arrays
#define GROWTH_FACTOR 2.0

// Function to add a new record and grow the arrays if necessary
void processAndFindMax(int key, int value) {
    // Check if the arrays need to be grown
    if (num_elements == capacity) {
        capacity *= GROWTH_FACTOR;
        offsets = realloc(offsets, capacity * sizeof(long));
        keys = realloc(keys, capacity * sizeof(int));
        records = realloc(records, capacity * sizeof(Record));
    }

    // Generate a random number within the specified range and initialize timestamp and identifier
