    records[num_elements].value = value;
    records[num_elements].timestamp = timestamp;
    strcpy(records[num_elements].identifier, identifier);

    // Increment the number of elements and adjust the capacity if necessary
    num_elements++;
}

// Function to find the maximum value in the array
