    for (size_t i = 0; i < num_elements; i++) {
        if (records[i].value > max) {
            max = records[i].value;
        }
    }
    return max;
}

// Function to clean up the arrays and any allocated resources
void cleanup() {
    free(offsets);
    free(keys);
    free(records);
}
