    sem_init(&pool->lock, 0, 1);

    // Monitor the configuration file for changes and apply updates to the connection pool
    // ...

    while (1) {
        // Handle incoming requests from clients
        int clientSocket = accept(socketFd, NULL, NULL);
        if (clientSocket < 0) {
            perror("Failed to accept client socket");
            continue;
        }

        // Allocate a new connection in the pool if necessary
        pthread_mutex_lock(&pool->lock);
        if (pool->nextFreeConnection == pool->poolSize) {
            // Pool is full, expand it by 10%
            int newPoolSize = pool->poolSize + (pool->poolSize / 10);
            dbMetadata *newPool = realloc(pool->pool, newPoolSize * sizeof(dbMetadata));
            if (newPool == NULL) {
                perror("Failed to expand connection pool");
                pthread_mutex_unlock(&pool->lock);
                close(clientSocket);
                continue;
            }
            memset(newPool + pool->poolSize, 0, (newPoolSize - pool->poolSize) * sizeof(dbMetadata));
            pool->pool = newPool;
            pool->poolSize = newPoolSize;
        }
        int connectionIndex = pool->nextFreeConnection++;
        pthread_mutex_unlock(&pool->lock);

        // Initialize the connection metadata for this client
        dbMetadata *connectionMetadata = &pool->pool[connectionIndex];
        connectionMetadata->transaction_id = pool->nextTransactionId++;
        connectionMetadata->lastAccessTime = time(NULL);
        connectionMetadata->errorCode = 0;

        // Handle the request from the client
        // ...

        // Clean up after the request is complete
        pthread_mutex_lock(&pool->lock);
        pool->pool[connectionIndex].lastAccessTime = time(NULL);
        if (pool->nextFreeConnection > pool->poolSize / 2) {
            // Pool is more than half full, shrink it by 10%
            int newPoolSize = pool->poolSize - (pool->poolSize / 10);
            dbMetadata *newPool = realloc(pool->pool, newPoolSize * sizeof(dbMetadata));
            if (newPool == NULL) {
                perror("Failed to shrink connection pool");
                pthread_mutex_unlock(&pool->lock);
                continue;
            }
            memset(newPool + pool->poolSize, 0, (pool->poolSize - newPoolSize) * sizeof(dbMetadata));
            pool->pool = newPool;
            pool->poolSize = newPoolSize;
        }
        pthread_mutex_unlock(&pool->lock);
    }
}

void closeConnection(connectionPool *pool, int connectionIndex) {
    // Close the client socket and free any resources associated with it
    // ...

    // Update the connection metadata to indicate that the connection is closed
    pool->pool[connectionIndex].errorCode = -1;
}

