int processAndFindMax(const char *input_file) {
    // Initialize variables
    FILE *fp = fopen(input_file, "r");
    if (fp == NULL) {
        printf("Failed to open file %s for reading\n", input_file);
        return 1;
    }

    int record_count = 0;
    size_t buffer_size = 4096; // initial buffer size in bytes
    char *buffer = malloc(buffer_size);
    if (buffer == NULL) {
        printf("Failed to allocate memory for buffer\n");
        fclose(fp);
        return 1;
    }

    double max_value = -INT_MAX; // initialize maximum value to lowest possible integer
    struct record *records = malloc(sizeof(struct record) * record_count);
    if (records == NULL) {
        printf("Failed to allocate memory for records\n");
        free(buffer);
        fclose(fp);
        return 1;
    }

    // Read input file and process records
    while (!feof(fp)) {
        int key = -1;
        double timestamp = -1.0;

        if (fscanf(fp, "%d %lf", &key, &timestamp) != 2) {
            printf("Failed to read record from file\n");
            free(buffer);
            fclose(fp);
            return 1;
        }

        // Add record to array of records and update maximum value
        if (record_count >= MAX_RECORDS) {
            printf("Maximum number of records exceeded\n");
            free(buffer);
            fclose(fp);
            return 1;
        }

        records[record_count].key = key;
        records[record_count].timestamp = timestamp;

        if (key > max_value) {
            max_value = key;
        }

        record_count++;
    }

    // Clean up and return
    free(buffer);
    fclose(fp);
    return 0;
}
