#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <assert.h>

// Custom structure for additional metadata
typedef struct {
    int some_data;
} meta_t;

// Record structure containing key, offset, and meta data
typedef struct {
    int key;
    long offset;
    meta_t meta;
} record_t;

// Dynamic collection of records
typedef struct {
    size_t capacity; // current capacity in records
    size_t count; // number of elements stored in the collection
    record_t *records; // array of records
} collection_t;

/**
 * Initializes a new collection with a given capacity.
 */
void collection_init(collection_t *col, size_t capacity) {
    col->capacity = capacity;
    col->count = 0;
    col->records = malloc(sizeof(record_t) * capacity);
}

/**
 * Adds a new record to the collection with a given key and offset.
 */
void collection_add(collection_t *col, int key, long offset) {
    // check if we need to resize the array
    if (col->count == col->capacity) {
        col->capacity = col->capacity * 2;
        col->records = realloc(col->records, sizeof(record_t) * col->capacity);
    }

    // add the new record to the collection
    col->records[col->count].key = key;
    col->records[col->count].offset = offset;
    memset(&col->records[col->count].meta, 0, sizeof(meta_t));
    col->count++;
}

/**
 * Returns the record at a given index.
 */
record_t collection_get(collection_t *col, size_t index) {
    assert(index < col->count);
    return col->records[index];
}

/**
 * Updates the value of a record in the collection.
 */
void collection_update(collection_t *col, int key, long offset) {
    for (size_t i = 0; i < col->count; i++) {
        if (col->records[i].key == key) {
            col->records[i].offset = offset;
            break;
        }
    }
}

/**
 * Frees the memory allocated for the collection.
 */
void collection_free(collection_t *col) {
    free(col->records);
}

// Randomly populates the collection with integer values within a specified range, ensuring uniform distribution without introducing predictable patterns.
void populate_collection(collection_t *col, int min_key, int max_key) {
    // generate random keys and offsets within the given range
    srand(time(NULL));
    for (size_t i = 0; i < col->capacity; i++) {
        int key = rand() % (max_key - min_key + 1) + min_key;
        long offset = rand() % 1000; // random offset within a range of 0 to 999
        collection_add(col, key, offset);
    }
}

// Accesses and modifies individual record values post-initialization.
void access_and_modify_records(collection_t *col) {
    // print the initial records
    printf("Initial Records:\n");
    for (size_t i = 0; i < col->count; i++) {
        printf("%d: key=%d, offset=%ld\n", i, col->records[i].key, col->records[i].offset);
    }

    // update the record with key=5's offset to 2000
    collection_update(col, 5, 2000);

    // print the updated records
    printf("Updated Records:\n");
    for (size_t i = 0; i < col->count; i++) {
        printf("%d: key=%d, offset=%ld\n", i, col->records[i].key, col->records[i].offset);
    }
}
