        config = config.replace("${offset}", str(offset)).replace("${key}", str(key))

    # Write the modified configuration file back to disk
    with open(config_file, "w") as f:
        f.write(config)

# Use subprocess module to execute shell commands
def execute_command(command):
    print("Executing command:", command)
    try:
        output = subprocess.check_output(command, shell=True).decode("utf-8")
        return 0
    except subprocess.CalledProcessError as e:
        print("Error executing command:", e)
        return 1

# Main function to handle file I/O and command execution
