#include <stdlib.h>
#include <time.h>

// Define structure for vertex records
typedef struct {
    long offset;
    int key;
} Vertex;

// Define structure for edge records
typedef struct {
    int record[1]; // single int value
} Edge;

// Define graph structure
typedef struct {
    Vertex **vertices; // array of vertex pointers
    Edge **edges; // array of edge pointers
    size_t numVertices; // number of vertices
    size_t numEdges; // number of edges
} Graph;

// Function to initialize a graph with predefined minimum number of vertices and edges
Graph *initGraph(size_t minNumVertices, size_t minNumEdges) {
    // Allocate memory for the graph structure
    Graph *graph = malloc(sizeof(Graph));
    if (graph == NULL) {
        // Handle out-of-memory condition
        return NULL;
    }

    // Initialize graph parameters
    graph->numVertices = minNumVertices;
    graph->numEdges = minNumEdges;

    // Allocate memory for vertex and edge arrays
    graph->vertices = malloc(sizeof(Vertex) * graph->numVertices);
    if (graph->vertices == NULL) {
        // Handle out-of-memory condition
        return NULL;
    }
    graph->edges = malloc(sizeof(Edge) * graph->numEdges);
    if (graph->edges == NULL) {
        // Handle out-of-memory condition
        return NULL;
    }

    // Initialize vertex and edge arrays
    for (size_t i = 0; i < graph->numVertices; i++) {
        graph->vertices[i] = malloc(sizeof(Vertex));
        if (graph->vertices[i] == NULL) {
            // Handle out-of-memory condition
            return NULL;
        }
        graph->vertices[i]->offset = 0;
        graph->vertices[i]->key = 0;
    }
    for (size_t i = 0; i < graph->numEdges; i++) {
        graph->edges[i] = malloc(sizeof(Edge));
        if (graph->edges[i] == NULL) {
            // Handle out-of-memory condition
            return NULL;
        }
        graph->edges[i]->record[0] = 0;
    }

    return graph;
}

// Function to add a vertex to the graph
void addVertex(Graph *graph, long offset, int key) {
    // Check if graph is null or if number of vertices exceeds capacity
    if (graph == NULL || graph->numVertices >= SIZE_MAX / sizeof(Vertex)) {
        return;
    }

    // Allocate memory for new vertex record
    Vertex *newVertex = malloc(sizeof(Vertex));
    if (newVertex == NULL) {
        // Handle out-of-memory condition
        return;
    }
    newVertex->offset = offset;
    newVertex->key = key;

    // Add vertex to adjacency list of existing vertices
    for (size_t i = 0; i < graph->numVertices; i++) {
        if (graph->vertices[i]->offset == offset) {
            break;
        } else if (i == graph->numVertices - 1) {
            // Add new vertex to end of adjacency list
            graph->vertices = realloc(graph->vertices, sizeof(Vertex) * (graph->numVertices + 1));
            if (graph->vertices == NULL) {
                // Handle out-of-memory condition
                return;
            }
            graph->vertices[graph->numVertices] = newVertex;
            graph->numVertices++;
        }
    }
}

// Function to add an edge between two vertices
void addEdge(Graph *graph, size_t vertex1, size_t vertex2) {
    // Check if graph is null or if number of edges exceeds capacity
    if (graph == NULL || graph->numEdges >= SIZE_MAX / sizeof(Edge)) {
        return;
    }

    // Allocate memory for new edge record
    Edge *newEdge = malloc(sizeof(Edge));
    if (newEdge == NULL) {
        // Handle out-of-memory condition
        return;
    }
    newEdge->record[0] = 1;

    // Add edge to adjacency list of both vertices
    for (size_t i = 0; i < graph->numVertices; i++) {
        if (graph->vertices[i]->offset == vertex1) {
            break;
        } else if (i == graph->numVertices - 1) {
            // Add new edge to end of adjacency list
            graph->edges = realloc(graph->edges, sizeof(Edge) * (graph->numEdges + 1));
            if (graph->edges == NULL) {
                // Handle out-of-memory condition
                return;
            }
            graph->edges[graph->numEdges] = newEdge;
            graph->numEdges++;
        }
    }
}

// Function to remove a vertex from the graph
void removeVertex(Graph *graph, size_t index) {
    // Check if graph is null or if vertex index exceeds capacity
    if (graph == NULL || index >= graph->numVertices) {
        return;
    }

    // Remove vertex from adjacency list of existing vertices
    for (size_t i = 0; i < graph->numVertices; i++) {
        if (i == index) {
            break;
        } else if (i == graph->numVertices - 1) {
                // Remove vertex from adjacency list
                graph->vertices[i]->offset = 0;
                graph->vertices[i]->key = 0;
            }
    }
}

// Function to remove an edge between two vertices
void removeEdge(Graph *graph, size_t vertex1, size_t vertex2) {
    // Check if graph is null or if edge index exceeds capacity
    if (graph == NULL || vertex1 >= graph->numVertices || vertex2 >= graph->numEdges) {
        return;
    }

    // Remove edge from adjacency list of both vertices
    for (size_t i = 0; i < graph->numEdges; i++) {
        if (graph->edges[i]->record[0] == vertex1 && graph->edges[i]->record[1] == vertex2) {
            break;
        } else if (i == graph->numEdges - 1) {
                // Remove edge from adjacency list
                graph->edges[i]->record[0] = 0;
                graph->edges[i]->record[1] = 0;
            }
    }
}

// Function to set a random value in an array of integers
void setRandomValue(int *arr, size_t n) {
    // Check if array is null or if number of elements exceeds capacity
    if (arr == NULL || n >= SIZE_MAX / sizeof(int)) {
        return;
    }

    // Set random value in each element of the array
    for (size_t i = 0; i < n; i++) {
        arr[i] = rand() % 10 + 1;
    }
}

// Function to print an array of integers
void printArray(int *arr, size_t n) {
    // Check if array is null or if number of elements exceeds capacity
    if (arr == NULL || n >= SIZE_MAX / sizeof(int)) {
        return;
    }

    // Print each element of the array on a new line
    for (size_t i = 0; i < n; i++) {
        printf("%d\n", arr[i]);
    }
}

// Function to sort an array of integers using insertion sort
void insertionSort(int *arr, size_t n) {
    // Check if array is null or if number of elements exceeds capacity
    if (arr == NULL || n >= SIZE_MAX / sizeof(int)) {
        return;
    }

    // Sort the array using insertion sort
    for (size_t i = 1; i < n; i++) {
        int key = arr[i];
        size_t j = i - 1;
        while (j >= 0 && arr[j] > key) {
            arr[j + 1] = arr[j];
            j--;
        }
        arr[j + 1] = key;
    }
}

// Function to calculate the sum of two integers
int add(int a, int b) {
    return a + b;
}
