  if (!records) {
    fprintf(stderr, "Failed to allocate memory for records\n");
    free(offsets);
    free(keys);
    return;
  }

  // Initialize the offset and key arrays
  for (int i = 0; i < num_records; ++i) {
    offsets[i] = rand() % (max_value - min_value + 1) + min_value;
    keys[i] = offsets[i];
  }

  // Initialize the records
  for (int i = 0; i < num_records; ++i) {
    records[i].key = keys[i];
    records[i].offset = offsets[i];
    records[i].value = rand() % (max_value - min_value + 1) + min_value;
  }

  // Print the initialized arrays and records
  printf("Offsets:\n");
  for (int i = 0; i < num_records; ++i) {
    printf("%ld\n", offsets[i]);
  }
  printf("Keys:\n");
  for (int i = 0; i < num_keys; ++i) {
    printf("%d\n", keys[i]);
  }
  printf("Records:\n");
  for (int i = 0; i < num_records; ++i) {
    printf("Key: %d, Offset: %ld, Value: %d\n", records[i].key, records[i].offset, records[i].value);
  }

  // Free the allocated memory
  free(offsets);
  free(keys);
  free(records);
}

// Function to insert a record into the database
void insert_record(int key, int value) {
  // Prepare the SQL statement
  char *sql = "INSERT INTO records (key, offset, value) VALUES (?, ?, ?)";

  // Create a prepared statement
  sqlite3_stmt *stmt;
  if (sqlite3_prepare_v2(db, sql, -1, &stmt, NULL) != SQLITE_OK) {
    fprintf(stderr, "Failed to prepare statement: %s\n", sqlite3_errmsg(db));
    return;
  }

  // Bind the key and value parameters
  if (sqlite3_bind_int(stmt, 1, key) != SQLITE_OK ||
      sqlite3_bind_int(stmt, 2, value) != SQLITE_OK) {
    fprintf(stderr, "Failed to bind parameters: %s\n", sqlite3_errmsg(db));
    sqlite3_finalize(stmt);
    return;
  }

  // Execute the statement
  if (sqlite3_step(stmt) != SQLITE_DONE) {
    fprintf(stderr, "Failed to execute statement: %s\n", sqlite3_errmsg(db));
    sqlite3_finalize(stmt);
    return;
  }

  // Finalize the statement
  sqlite3_finalize(stmt);
}

// Function to handle callbacks for each record after initialization
void callback(Record *record) {
  // Perform custom operations on the record, such as updating internal state or performing additional computations
  printf("Callback: Key %d, Offset %ld, Value %d\n", record->key, record->offset, record->value);
}

// Main function to demonstrate usage of the C function
