  // Initialize the arrays and records
  initialize(5, 10, 1, 10);

  // Insert each record into the database using a Data Access Object (DAO) class
  for (int i = 0; i < 10; ++i) {
    insert_record(i, i * 2 + 1);
  }

  // Free the allocated memory
  free();

  return 0;
}
