  $stmt->bindValue(':key', $record->key, PDO::PARAM_INT);
  $stmt->bindValue(':offset', $record->offset, PDO::PARAM_INT);
  $stmt->bindValue(':value', $record->value, PDO::PARAM_INT);
  $stmt->execute();

  // Close the database connection
  $db = null;
}

