        file_cache_entry_t *file = (file_cache_entry_t *) ((char *) file_cache + i * sizeof(file_cache_entry_t));
        if (!strcmp(name, file->name)) {
            // Remove the file from the cache
            free(file);
            file_cache_size--;

            // Close the file descriptor
            close(file->fd);

            return 0;
        }
    }

    // File not found in the cache, check if it exists on disk
    int fd = open(name, O_RDONLY);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to delete file %s: %s", name, strerror(errno));
        return -1;
    }

    // Remove the file from the disk
    unlink(name);

    return 0;
}

// Function to rename a file
int renameFile(const char *old_name, const char *new_name) {
    // Check if the old file exists in the cache
    int i = 0;
    for (i = 0; i < file_cache_size; i++) {
        file_cache_entry_t *file = (file_cache_entry_t *) ((char *) file_cache + i * sizeof(file_cache_entry_t));
        if (!strcmp(old_name, file->name)) {
            // Remove the file from the cache
            free(file);
            file_cache_size--;

            // Close the file descriptor
            close(file->fd);

            break;
        }
    }

    // Check if the new file already exists on disk
    int fd = open(new_name, O_CREAT | O_WRONLY, 0644);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to rename file %s: %s", new_name, strerror(errno));
        return -1;
    }

    // Remove the file from the disk
    unlink(old_name);

    return 0;
}

// Function to traverse a directory
int traverseDirectory(const char *dir) {
    // Check if the directory exists in the cache
    int i = 0;
    for (i = 0; i < file_cache_size; i++) {
        file_cache_entry_t *file = (file_cache_entry_t *) ((char *) file_cache + i * sizeof(file_cache_entry_t));
        if (!strcmp(dir, file->name)) {
            // Remove the directory from the cache
            free(file);
            file_cache_size--;

            return 0;
        }
    }

    // Check if the directory exists on disk
    DIR *dp = opendir(dir);
    if (dp == NULL) {
        syslog(LOG_ERR, "Failed to traverse directory %s: %s", dir, strerror(errno));
        return -1;
    }

    // Read the directory entries
    struct dirent *ep = readdir(dp);
    while (ep != NULL) {
        // Check if the entry is a file
        if (!strcmp(ep->d_name, "..") || !strcmp(ep->d_name, ".") || !strcmp(ep->d_name, dir)) {
            ep = readdir(dp);
            continue;
        }

        // Check if the entry is a directory
        struct stat sb;
        if (stat(ep->d_name, &sb) == 0 && S_ISDIR(sb.st_mode)) {
            traverseDirectory(ep->d_name);
        } else {
            // Remove the file from the cache
            int fd = open(ep->d_name, O_RDONLY);
            if (fd < 0) {
                syslog(LOG_ERR, "Failed to traverse directory %s: %s", dir, strerror(errno));
                return -1;
            }

            // Remove the file from the disk
            unlink(ep->d_name);
        }
    }

    closedir(dp);

    return 0;
}

// Function to check if a file exists
bool fileExists(const char *name) {
    // Check if the file exists in the cache
    int i = 0;
    for (i = 0; i < file_cache_size; i++) {
        file_cache_entry_t *file = (file_cache_entry_t *) ((char *) file_cache + i * sizeof(file_cache_entry_t));
        if (!strcmp(name, file->name)) {
            return true;
        }
    }

    // Check if the file exists on disk
    int fd = open(name, O_RDONLY);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to check if file %s exists: %s", name, strerror(errno));
        return false;
    }

    close(fd);

    return true;
}

// Function to get the size of a file
off_t getFileSize(const char *name) {
    // Check if the file exists in the cache
    int i = 0;
    for (i = 0; i < file_cache_size; i++) {
        file_cache_entry_t *file = (file_cache_entry_t *) ((char *) file_cache + i * sizeof(file_cache_entry_t));
        if (!strcmp(name, file->name)) {
            return file->size;
        }
    }

    // Check if the file exists on disk
    int fd = open(name, O_RDONLY);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to get size of file %s: %s", name, strerror(errno));
        return -1;
    }

    struct stat sb;
    if (fstat(fd, &sb) == 0 && S_ISREG(sb.st_mode)) {
        close(fd);
        return sb.st_size;
    }

    close(fd);

    return -1;
}
