    sensorRecord *sensorRecords = (sensorRecord *)malloc(sizeof(sensorRecord) * numCommandLineOptions);
    for (int i = 0; i < numCommandLineOptions; i++) {
        sensorRecords[i].timestamp = timestampArray[i];
        sensorRecords[i].identifier = identifierArray[i];
        sensorRecords[i].temperature = temperatureArray[i];
