    }

    // Initialize array of temperature thresholds and populate with values from configuration file
    double *temperatureThresholdsArray = (double *)malloc(sizeof(double) * 3);
    for (int i = 0; i < 3; i++) {
        temperatureThresholdsArray[i] = coefficients->temperature1 + coefficients->temperature2 + coefficients->temperature3;
    }

    // Implement thread-safe operations to process sensor data and perform calibration
    pthread_t threads[numCommandLineOptions];
    for (int i = 0; i < numCommandLineOptions; i++) {
        pthread_create(&threads[i], NULL, &processSensorDataAndCalibrate, &sensorRecords[i]);
    }

    // Wait for all threads to complete
    for (int i = 0; i < numCommandLineOptions; i++) {
        pthread_join(threads[i], NULL);
