    // Free memory allocated for timestamp, identifier, and temperature arrays
    free(timestampArray);
    free(identifierArray);
    free(temperatureArray);

    // Free memory allocated for sensor records array
    free(sensorRecords);

    // Free memory allocated for calibration coefficients array
    free(calibrationCoefficientsArray);

    // Free memory allocated for temperature thresholds array
    free(temperatureThresholdsArray);
