// Function to read and process network packet headers from a file descriptor
void processNetworkTraffic(int fd) {
    // Allocate memory for the arrays
    packetHeaders = (packetHeader*)malloc(sizeof(packetHeader) * 1024);
    byteCounts = (uint64_t*)malloc(sizeof(uint64_t) * 1024);
    timeIntervals = (double*)malloc(sizeof(double) * 1024);
    protocolTypes = (int*)malloc(sizeof(int) * 1024);
    sourceIPs = (uint32_t*)malloc(sizeof(uint32_t) * 1024);
    destIPs = (uint32_t*)malloc(sizeof(uint32_t) * 1024);

    // Initialize the arrays
