    memset(byteCounts, 0, sizeof(uint64_t) * 1024);
    memset(timeIntervals, 0, sizeof(double) * 1024);
    memset(protocolTypes, 0, sizeof(int) * 1024);
    memset(sourceIPs, 0, sizeof(uint32_t) * 1024);
    memset(destIPs, 0, sizeof(uint32_t) * 1024);

    // Read and process network packet headers from the file descriptor
    while (true) {
        struct packetHeader* header = malloc(sizeof(struct packetHeader));
        if (header == NULL) {
            break;
        }
        // Read the packet header into the buffer
        ssize_t bytesRead = read(fd, header, sizeof(struct packetHeader));
        if (bytesRead <= 0) {
            free(header);
            break;
        }

        // Lock the mutex before accessing shared resources
        pthread_mutex_lock(&mutex);

        // Store the packet header in the arrays
        packetHeaders[numPackets] = *header;
        byteCounts[numPackets] = header->byteCount;
        timeIntervals[numPackets] = (double)(header->timestamp - previousTimestamp) / 1000.0;
        protocolTypes[numPackets] = header->protocolType;
        sourceIPs[numPackets] = header->sourceIP;
        destIPs[numPackets] = header->destIP;

        // Update the previous timestamp and number of packets processed
        previousTimestamp = header->timestamp;
        numPackets++;

        // Unlock the mutex after accessing shared resources
        pthread_mutex_unlock(&mutex);

        // Free the buffer for the packet header
        free(header);
    }
}
