void handleFileSystemOperations(const char* path, const config* cfg) {
    // Initialize the file descriptor pool
    struct fd_pool fd_pool;
    int max_fds = MAX_FDS;
    int num_fds = 0;
    struct file_descriptor* fds[MAX_FDS];

