Record* allocateRecord(float value, double timestamp) {
  Record* record = (Record*) malloc(sizeof(Record));
  if (record == NULL) {
    fprintf(stderr, "Error: Failed to allocate memory for record\n");
    return NULL;
  }
  record->value = value;
  record->timestamp = timestamp;
  return record;
}

// Function prototype for filtering records based on weight threshold
void filterRecordsByWeight(Record* records, int num_records, float weight_threshold) {
  // Iterate through the records and filter out any below the weight threshold
  for (int i = 0; i < num_records; i++) {
    if (records[i].weight < weight_threshold) {
      // If a record is below the threshold, remove it from the array
      memmove(records + i, records + i + 1, sizeof(Record) * (num_records - i));
      num_records--;
      i--;
    }
  }
}

// Function prototype for processing and analyzing data
void processAndAnalyzeData(float* values, int num_values, double* weights, int num_weights) {
  // Allocate memory for the record array
  Record* records = (Record*) malloc(sizeof(Record) * num_values);
  if (records == NULL) {
    fprintf(stderr, "Error: Failed to allocate memory for record array\n");
    return;
  }

  // Initialize the timestamp for each record
  for (int i = 0; i < num_values; i++) {
    records[i].timestamp = getCurrentTimestamp();
  }

  // Filter out any records below the weight threshold
  filterRecordsByWeight(records, num_values, WEIGHT_THRESHOLD);

  // Process and analyze the remaining records
  for (int i = 0; i < num_values; i++) {
    // Perform analysis on each record
    printf("Record %d: value=%f, weight=%f, timestamp=%lld\n", i, records[i].value, records[i].weight, records[i].timestamp);
  }

  // Free the memory for the record array
  free(records);
}

// Function to get the current timestamp in microseconds since the epoch
long long getCurrentTimestamp() {
  time_t rawtime;
  struct tm* timeinfo;
  time(&rawtime);
  timeinfo = localtime(&rawtime);
  return ((long long) timeinfo->tm_year + 1900) * 10000000000LL + (timeinfo->tm_mon + 1) * 100000000LL + timeinfo->tm_mday * 1000000LL + timeinfo->tm_hour * 10000LL + timeinfo->tm_min * 100LL + timeinfo->tm_sec);
}
```
