// Define the node structure
typedef struct Node {
    int key;
    struct Node* next;
} Node;

// Define the linked list data structure
struct LinkedList {
    Node* head;
};

// Define the function to manage memory for multiple arrays and structures
void memManage(LinkedList* ll, int key) {
    // Allocate memory for a new node
    Node* newNode = malloc(sizeof(Node));
    if (newNode == NULL) {
        printf("Error: Failed to allocate memory for new node\n");
        return;
    }

    // Initialize the new node
    newNode->key = key;
    newNode->next = NULL;

    // Insert the new node into the linked list
    Node* currentNode = ll->head;
    while (currentNode != NULL && currentNode->key < key) {
        currentNode = currentNode->next;
    }
    if (currentNode == NULL) {
        ll->head = newNode;
    } else {
        newNode->next = currentNode->next;
        currentNode->next = newNode;
    }
}

// Define the function to free all allocated memory when the function exits
void memFree(LinkedList* ll) {
    Node* currentNode = ll->head;
    while (currentNode != NULL) {
        Node* nextNode = currentNode->next;
        free(currentNode);
        currentNode = nextNode;
    }
}
```
