// Custom memory pool for efficient allocation and deallocation of memory
struct MemoryPool {
    void* mem;
    size_t size;
    pthread_mutex_t lock;
};

void* allocate(size_t size) {
    struct MemoryPool* pool = (struct MemoryPool*)malloc(sizeof(struct MemoryPool));
    if (!pool) return NULL;

    pool->mem = malloc(size);
    if (!pool->mem) {
        free(pool);
        return NULL;
    }

    pthread_mutex_init(&pool->lock, NULL);

    return pool;
}

void deallocate(void* mem) {
    struct MemoryPool* pool = (struct MemoryPool*)mem;
    if (!pool) return;

    pthread_mutex_destroy(&pool->lock);
    free(pool->mem);
    free(pool);
}

