  Record *record = list->head;
  while (record != NULL && record->key != key) {
    record = record->next;
  }
  if (record == NULL) {
    return;
  }
  linked_list_remove(list, record);
  free(record);
}

// Function to update the offset value of a record in the database
void update_offset(const int key, const long offset) {
  LinkedList *list = hash_table_lookup(hash_table, key);
  if (list == NULL) {
    return;
  }
  Record *record = list->head;
  while (record != NULL && record->key != key) {
    record = record->next;
  }
  if (record == NULL) {
    return;
  }
  record->offset = offset;
}

// Function to retrieve all records from the database
void get_all_records(Record **records, size_t *num_records) {
  LinkedList *list = hash_table_lookup(hash_table, key);
  if (list == NULL) {
    return;
  }
  Record *record = list->head;
  while (record != NULL) {
    records[*num_records] = record;
    (*num_records)++;
    record = record->next;
  }
