// Define the hash table structure
typedef struct {
    record** records;  // Array of pointers to records
    size_t capacity;  // Current capacity of the hash table
    size_t count;     // Number of records in the hash table
} hash_table;

// Initialize a new hash table with a given capacity
hash_table* init_hash_table(size_t capacity) {
    hash_table* ht = (hash_table*)malloc(sizeof(hash_table));
    ht->records = (record**)malloc(capacity * sizeof(record*));
    ht->count = 0;
    ht->capacity = capacity;
    return ht;
}

// Insert a new record into the hash table
void insert_record(hash_table* ht, int key, long offset, nested_struct* data) {
    // Check if the hash table is full and needs to be resized
    if (ht->count == ht->capacity) {
        resize_hash_table(ht);
    }

    // Find an empty slot in the hash table
    size_t index = key % ht->capacity;
    while (ht->records[index] != NULL && ht->records[index]->key != 0) {
        index = (index + 1) % ht->capacity;
    }

    // Allocate a new record and assign its values
    record* r = malloc(sizeof(record));
    r->key = key;
    r->offset = offset;
    r->data = data;

    // Add the record to the hash table
    ht->records[index] = r;
    ht->count++;
}

// Delete a record from the hash table
void delete_record(hash_table* ht, int key) {
    // Find the index of the record to delete
    size_t index = key % ht->capacity;
    while (ht->records[index] != NULL && ht->records[index]->key != key) {
        index = (index + 1) % ht->capacity;
    }

    // If the record is found, delete it from the hash table
    if (ht->records[index] != NULL) {
        free(ht->records[index]);
        ht->records[index] = NULL;
        ht->count--;
    }
}

// Look up a record in the hash table by its key
record* lookup_record(hash_table* ht, int key) {
    // Find the index of the record to look up
    size_t index = key % ht->capacity;
    while (ht->records[index] != NULL && ht->records[index]->key != key) {
        index = (index + 1) % ht->capacity;
    }

    // If the record is found, return it
    if (ht->records[index] != NULL) {
        return ht->records[index];
    } else {
        return NULL;
    }
}

// Resize the hash table to a new capacity
void resize_hash_table(hash_table* ht, size_t new_capacity) {
    // Allocate a new array of pointers to records
    record** new_records = (record**)malloc(new_capacity * sizeof(record*));

    // Copy the old records into the new array
    for (size_t i = 0; i < ht->count; i++) {
        size_t index = ht->records[i]->key % new_capacity;
        while (new_records[index] != NULL) {
            index = (index + 1) % new_capacity;
        }
        new_records[index] = ht->records[i];
    }

    // Free the old array of pointers to records
    free(ht->records);

    // Update the hash table with the new array
    ht->records = new_records;
    ht->capacity = new_capacity;
}
