#include <stdlib.h>
#include <time.h>

struct record {
    int value;
    double timestamp;
    unsigned long ref_count;
    struct record *next;
};

int init_record(struct record **head, struct record **tail) {
    // Allocate memory for the linked list
    *head = malloc(sizeof(struct record));
    if (*head == NULL) {
        return -1;  // Memory allocation failed
    }

    // Initialize the reference count to 1
    (*head)->ref_count = 1;

    // Set the head and tail pointers to the same location
    *tail = *head;

    return 0;  // Success
}

int add_record(struct record **head, struct record **tail, int value, double timestamp) {
    // Allocate memory for a new 'record' structure
    struct record *new_rec = malloc(sizeof(struct record));
    if (new_rec == NULL) {
        return -1;  // Memory allocation failed
    }

    // Initialize the fields of the new 'record' structure
    new_rec->value = value;
    new_rec->timestamp = timestamp;

    // Increment the reference count of the new record
    new_rec->ref_count = 1;

    // Insert the new 'record' at the end of the linked list
    (*tail)->next = new_rec;
    *tail = new_rec;

    return 0;  // Success
}

int del_record(struct record **head, struct record **tail, int value) {
    // Find the 'record' with the given value in the linked list
    struct record *cur_rec = *head;
    while (cur_rec != NULL && cur_rec->value != value) {
        cur_rec = cur_rec->next;
    }

    if (cur_rec == NULL) {
        return -1;  // Record not found
    }

    // Decrement the reference count of the deleted record
    cur_rec->ref_count--;

    // Remove the deleted 'record' from the linked list
    if (cur_rec == *head) {
        *head = cur_rec->next;
    } else {
        (*tail)->next = cur_rec->next;
    }

    return 0;  // Success
}

int get_record(struct record **head, struct record **tail, int value) {
    // Find the 'record' with the given value in the linked list
    struct record *cur_rec = *head;
    while (cur_rec != NULL && cur_rec->value != value) {
        cur_rec = cur_rec->next;
    }

    if (cur_rec == NULL) {
        return -1;  // Record not found
    }

    // Increment the reference count of the returned record
    cur_rec->ref_count++;

    return 0;  // Success
}

int release_record(struct record **head, struct record **tail, int value) {
    // Find the 'record' with the given value in the linked list
    struct record *cur_rec = *head;
    while (cur_rec != NULL && cur_rec->value != value) {
        cur_rec = cur_rec->next;
    }

    if (cur_rec == NULL) {
        return -1;  // Record not found
    }

    // Decrement the reference count of the released record
    cur_rec->ref_count--;

    // Remove the released 'record' from the linked list
    if (cur_rec == *head) {
        *head = cur_rec->next;
    } else {
        (*tail)->next = cur_rec->next;
    }

    return 0;  // Success
}

int main() {
    struct record *head = NULL, *tail = NULL;
    init_record(&head, &tail);

    // Insert some records into the linked list
    add_record(&head, &tail, 10, 1.0);
    add_record(&head, &tail, 20, 2.0);
    add_record(&head, &tail, 30, 3.0);

    // Get the first record from the linked list
    struct record *first = get_record(&head, &tail, 10);

    // Release the first record from the linked list
    release_record(&head, &tail, 10);

    // Delete the second record from the linked list
    del_record(&head, &tail, 20);

    return 0;
}
