// Data structures for tracking frequency of keys
struct FrequencyTracker {
    int *keys;
    size_t num_keys;
    size_t capacity;
};

void initFrequencyTracker(struct FrequencyTracker *tracker, size_t initial_capacity) {
    tracker->keys = malloc(initial_capacity * sizeof(*tracker->keys));
    if (!tracker->keys) {
        fprintf(stderr, "Error: Could not allocate memory for frequency tracker\n");
        return;
    }
    tracker->num_keys = 0;
    tracker->capacity = initial_capacity;
}

void addKeyToFrequencyTracker(struct FrequencyTracker *tracker, int key) {
    if (tracker->num_keys >= tracker->capacity) {
        // Resize the array to accommodate new key
        size_t new_capacity = tracker->capacity * 2;
        int *new_keys = realloc(tracker->keys, new_capacity * sizeof(*tracker->keys));
        if (!new_keys) {
            fprintf(stderr, "Error: Could not resize frequency tracker\n");
            return;
        }
        tracker->keys = new_keys;
        tracker->capacity = new_capacity;
    }
    tracker->keys[tracker->num_keys++] = key;
}

void freeFrequencyTracker(struct FrequencyTracker *tracker) {
    if (tracker->keys) {
        free(tracker->keys);
    }
    tracker->num_keys = 0;
    tracker->capacity = 0;
}

