        print_usage(argv[0]);
        return 0;
    } else if (argc > 2) {
        fprintf(stderr, "Error: too many arguments\n");
        print_usage(argv[0]);
        return 1; // Return an error code
    }

    // Initialize arrays for records and offsets/keys
    size_t num_records = 1000; // Initially set to a small value
    Record* records = NULL;
    int* offsets = NULL;
    int* keys = NULL;

    // Check if input file is specified
    if (argc == 2) {
        FILE* input_file = fopen(argv[1], "r");
        if (input_file == NULL) {
            fprintf(stderr, "Error: failed to open input file\n");
            return 1; // Return an error code
        }

        // Read data from the input file and update the records
        while ((fgets(input_file)) != NULL) {
            // Skip empty lines or lines containing only whitespace
            if (strlen(input_file) == 0 || strspn(input_file, " \t\r\n") == strlen(input_file)) {
                continue;
            }

            // Parse the data from the input line and update the records
            int id = atoi(input_file);
            int random_int = rand() % 100;
            double timestamp = time(NULL) * 1000; // Convert to milliseconds since epoch
            int count = 0;

            // Update the record with the appropriate fields
            records[id].id = id;
            records[id].random_int = random_int;
            records[id].timestamp = timestamp;
            records[id].count = count;
        }
    } else {
        fprintf(stderr, "Error: no input file specified\n");
        return 1; // Return an error code
    }

    // Free the memory allocated for the arrays and close the input file
    free(records);
    free(offsets);
    free(keys);
    fclose(input_file);

    return 0;
}
