        if (sensorData == NULL) {
            sensorData = malloc(sizeof(SensorData));
            if (sensorData == NULL) {
                printf("Error: unable to allocate memory for sensor data\n");
                return -1;
            }
        }

        // Add the current reading to the array of structures
        SensorData* newReading = malloc(sizeof(SensorData));
        if (newReading == NULL) {
            printf("Error: unable to allocate memory for new sensor reading\n");
            return -1;
