        newReading->temperature = temperature;
        newReading->humidity = humidity;
        newReading->timestamp = timestamp;
        sensorData[currentIndex] = *newReading;
        currentIndex++;
    }

    // Compute aggregate statistics on the collected data
    double averageTemperature = 0.0;
    for (int i = 0; i < currentIndex; i++) {
        averageTemperature += sensorData[i].temperature;
    }
    averageTemperature /= currentIndex;

    SensorData* highestTemperatureSensor = NULL;
    for (int i = 0; i < currentIndex; i++) {
        if (sensorData[i].temperature > highestTemperatureSensor->temperature) {
            highestTemperatureSensor = &sensorData[i];
        }
    }

    time_t lowestHumidityTimestamp = 0;
    for (int i = 0; i < currentIndex; i++) {
        if (sensorData[i].humidity < lowestHumidityTimestamp) {
            lowestHumidityTimestamp = sensorData[i].timestamp;
        }
    }

    // Print the computed statistics and relevant information
    printf("Average temperature: %.2f\n", averageTemperature);
    printf("Sensor with highest temperature: %s\n", highestTemperatureSensor->identifier);
    printf("Time range with lowest humidity: [%ld, %ld]\n", lowestHumidityTimestamp - 10000, lowestHumidityTimestamp + 10000);

    // Clean up any allocated resources before exiting
    if (sensorData != NULL) {
        free(sensorData);
    }
    fclose(fp);

    return 0;
}
