    int index;
    size_t length;
} Metadata;

// Function to dynamically allocate memory for an array of entries
Entry* createEntries(int numEntries, double minValue, double maxValue, int stringLength) {
    // Allocate memory for the entry array and initialize it with random values
    Entry* entries = (Entry*)malloc(numEntries * sizeof(Entry));
    if (!entries) {
        return NULL;
    }
    for (int i = 0; i < numEntries; i++) {
        // Generate a random double value within the specified range
        entries[i].value = minValue + ((double)rand() / RAND_MAX) * (maxValue - minValue);
        // Allocate memory for the string and initialize it with a randomly generated string
        entries[i].string = (char*)malloc(stringLength + 1);
        if (!entries[i].string) {
            freeEntries(entries, numEntries);
            return NULL;
        }
        for (int j = 0; j < stringLength; j++) {
            entries[i].string[j] = 'a' + ((rand() % 26));
        }
        entries[i].string[stringLength] = '\0';
    }
    return entries;
}

// Function to dynamically allocate memory for an array of metadata
Metadata* createMetadata(int numEntries) {
    // Allocate memory for the metadata array and initialize it with the index and length fields
    Metadata* metadata = (Metadata*)malloc(numEntries * sizeof(Metadata));
    if (!metadata) {
        return NULL;
    }
    for (int i = 0; i < numEntries; i++) {
        metadata[i].index = i;
        metadata[i].length = strlen(entries[i].string);
    }
    return metadata;
}

// Function to free memory allocated for an array of entries
void freeEntries(Entry* entries, int numEntries) {
    if (!entries) {
        return;
    }
    for (int i = 0; i < numEntries; i++) {
        free(entries[i].string);
    }
    free(entries);
}

// Function to free memory allocated for an array of metadata
void freeMetadata(Metadata* metadata, int numEntries) {
    if (!metadata) {
        return;
    }
    free(metadata);
}

int main() {
    // Initialize variables and allocate memory for the entry and metadata arrays
    srand(time(NULL));
    int numEntries = 10;
    double minValue = 1.0;
    double maxValue = 100.0;
    int stringLength = 5;
    Entry* entries = createEntries(numEntries, minValue, maxValue, stringLength);
    Metadata* metadata = createMetadata(numEntries);
    if (!entries || !metadata) {
        printf("Failed to allocate memory for the arrays\n");
        return 1;
    }
    // Print the contents of the entry and metadata arrays
    for (int i = 0; i < numEntries; i++) {
        printf("Entry %d: %lf, String: %s\n", i, entries[i].value, entries[i].string);
        printf("Metadata %d: Index: %d, Length: %zu\n", i, metadata[i].index, metadata[i].length);
    }
    // Free the memory allocated for the entry and metadata arrays
    freeEntries(entries, numEntries);
    freeMetadata(metadata, numEntries);
    return 0;
}

