    size_t session_length;
};

int generate_records(size_t num_records, float min_value, float max_value, int str_len) {
    srand((unsigned)time(NULL));

    // Allocate memory for the records and initialize values
    struct record *records = (struct record *)malloc(num_records * sizeof(struct record));
    if (!records) {
        fprintf(stderr, "Failed to allocate memory for records\n");
        return -1;
    }

    for (size_t i = 0; i < num_records; i++) {
        records[i].value = min_value + ((double)rand() / RAND_MAX) * (max_value - min_value);

        // Allocate memory for the string pointer and initialize it with a random string
        records[i].str_ptr = (char *)malloc(str_len * sizeof(char));
        if (!records[i].str_ptr) {
            fprintf(stderr, "Failed to allocate memory for string pointer\n");
            return -1;
        }
        memset(records[i].str_ptr, 0, str_len);
        srand((unsigned)time(NULL));
        for (int j = 0; j < str_len; j++) {
            records[i].str_ptr[j] = rand() % 26 + 'a';
        }
    }

    // Allocate memory for the context array and initialize values
    struct context *contexts = (struct context *)malloc(num_records * sizeof(struct context));
    if (!contexts) {
        fprintf(stderr, "Failed to allocate memory for contexts\n");
        return -1;
    }

    for (size_t i = 0; i < num_records; i++) {
        contexts[i].session_id = records[i].value;
        contexts[i].timestamp = time(NULL);
        contexts[i].session_length = rand() % 100 + 1;
    }

    return 0;
}
```
