// Define the function to process the network metrics
void processNetworkMetrics(struct NetworkMetrics* metrics) {
    // Allocate memory for the metric values and labels
    metrics->values = malloc(sizeof(double) * metrics->num_metrics);
    metrics->labels = malloc(sizeof(char*) * metrics->num_metrics);

    // Initialize the metric values and labels to zero
    memset(metrics->values, 0, sizeof(double) * metrics->num_metrics);
    memset(metrics->labels, 0, sizeof(char*) * metrics->num_metrics);

    // Parse the incoming data streams and store the metric values and labels
    for (size_t i = 0; i < metrics->num_metrics; ++i) {
        char* line = getLine(); // Get a line from the input stream
        double value = parseDouble(line); // Parse the metric value
        if (value != DBL_MAX) {
            metrics->values[i] = value;
            metrics->labels[i] = strdup(line);
        } else {
            // Handle parsing errors gracefully by returning an appropriate error code and cleaning up any allocated resources before exiting.
            printf("Error: Failed to parse metric value.\n");
            free(metrics->values);
            free(metrics->labels);
