        if (strlen(metrics->labels[i]) > max_label_len) {
            max_label_len = strlen(metrics->labels[i]);
            most_frequent_label = metrics->labels[i];
        }
    }
    printf("Most Frequent Label: %s\n", most_frequent_label);

    // Free the allocated memory for the metric values and labels
    free(metrics->values);
    for (size_t i = 0; i < metrics->num_metrics; ++i) {
        free(metrics->labels[i]);
    }
    free(metrics->labels);
}
```
