import java.util.Random;

public class BackgroundServiceManager {
    private static final int MAX_DELAY = 30 * 1000; // 30 seconds
    private static final int MIN_DELAY = 5 * 1000; // 5 seconds

    private static final Random RANDOM = new Random();

    private static BackgroundService service;

    public static void main(String[] args) {
        service = new BackgroundService();
        startService();
    }

    private static void startService() {
        int delay = getRandomDelay();
        System.out.println("Starting background service with delay: " + delay);
        service.start(delay);
    }

    private static void stopService() {
        System.out.println("Stopping background service");
        service.stop();
    }

    private static int getRandomDelay() {
        return MIN_DELAY + RANDOM.nextInt((MAX_DELAY - MIN_DELAY) + 1);
    }
}
```
