int processAndAggregateData(Data *data, int numRecords) {
    if (numRecords <= 0) {
        return -1;
    }

    // Allocate memory for the arrays
    data->values = malloc(sizeof(float) * numRecords);
    data->timestamps = malloc(sizeof(time_t) * numRecords);

    if (data->values == NULL || data->timestamps == NULL) {
        // Clean up allocated memory and return error code
        free(data->values);
        free(data->timestamps);
        return -2;
