        data->values[i] = (float)rand() / RAND_MAX * 2.0 - 1.0;
        data->timestamps[i] = time(NULL);
    }

    // Calculate average and standard deviation of the float values
    float sum = 0.0, sqrSum = 0.0;
    for (int i = 0; i < numRecords; ++i) {
        sum += data->values[i];
        sqrSum += data->values[i] * data->values[i];
    }
    float avg = sum / numRecords;
    float stdDev = sqrt((sqrSum - (sum * sum / numRecords)) / (numRecords - 1));

    // Find the most frequent timestamp and print the average and standard deviation of the float values
    time_t maxCount = 0, maxTimestamp = data->timestamps[0];
    for (int i = 1; i < numRecords; ++i) {
        if (data->timestamps[i] > maxTimestamp) {
            maxCount = 1;
            maxTimestamp = data->timestamps[i];
        } else if (data->timestamps[i] == maxTimestamp) {
            maxCount++;
        }
    }
    printf("Average: %f\nStandard Deviation: %f\nMost frequent timestamp: %s\n", avg, stdDev, ctime(&maxTimestamp));

    // Clean up allocated memory
    free(data->values);
    free(data->timestamps);

    return 0;
}
