// Define a data structure to store environmental monitoring data
struct Data {
    double temperature;
    unsigned long sensor_id;
    struct timespec timestamp;
    float additional_data;
    char* description;
    int sequence_number;
};

// Define a linked list node to store the data entries
typedef struct DataNode {
    struct Data data;
    struct DataNode* next;
} DataNode;

// Define a function to initialize a new data entry
void initDataEntry(struct Data* data) {
    data->temperature = 0.0;
    data->sensor_id = 0;
    memset(&data->timestamp, 0, sizeof(struct timespec));
    data->additional_data = 0.0f;
    data->description = NULL;
    data->sequence_number = 0;
}

// Define a function to allocate memory for a new data entry
DataNode* createNewDataEntry() {
    DataNode* node = malloc(sizeof(DataNode));
    if (node) {
        initDataEntry(&node->data);
        node->next = NULL;
    }
    return node;
}

// Define a function to insert a new data entry into the linked list
void insertNewDataEntry(DataNode** head_ref, struct Data* data) {
    DataNode* current = *head_ref;
    if (current == NULL) {
        // Insert as head of linked list
        current = createNewDataEntry();
        *head_ref = current;
    } else {
        // Insert at the end of the linked list
        while (current->next != NULL) {
            current = current->next;
        }
        DataNode* new_node = createNewDataEntry();
        if (new_node == NULL) {
            printf("Memory allocation failed!");
        } else {
            current->next = new_node;
        }
    }
}

// Define a function to retrieve the last data entry in the linked list
struct Data* getLastDataEntry(DataNode* head) {
    DataNode* current = head;
    if (current == NULL) {
        return NULL;
    } else {
        while (current->next != NULL) {
            current = current->next;
        }
        return &current->data;
    }
}

// Define a function to apply a moving average filter to the temperature readings in the linked list
void applyMovingAverageFilter(DataNode** head_ref, int window_size) {
    DataNode* current = *head_ref;
    if (current == NULL || window_size <= 0) {
        return;
    }
    // Calculate the moving average for each data entry in the linked list
    while (current != NULL) {
        double sum = 0.0;
        int count = 0;
        DataNode* temp = current;
        while (count < window_size && temp != NULL) {
            sum += temp->data.temperature;
            count++;
            temp = temp->next;
        }
        if (count == window_size) {
            // Update the temperature reading with the moving average
            current->data.temperature = sum / window_size;
        } else {
            printf("Not enough data to apply the moving average filter!");
        }
        current = current->next;
    }
}

// Define a function to free the memory allocated for the linked list
void freeLinkedList(DataNode** head) {
    DataNode* current = *head;
    while (current != NULL) {
        DataNode* temp = current;
        current = current->next;
        free(temp);
    }
}
