// Define a class to manage memory allocation for arrays of long offset values, int keys, and an array of Record structures
class MemoryManager {
public:
    MemoryManager() : max_size_(0), current_size_(0), total_allocated_(0) {}

    // Allocate memory for the specified size of records
    void allocate(const size_t size) {
        if (max_size_ >= size) return;

        // Release any existing allocated memory
        deallocate();

        // Allocate new memory for the specified size
        max_size_ = size;
        current_size_ = 0;
        total_allocated_ = 0;
    }

    // Deallocate all allocated memory
    void deallocate() {
        if (max_size_ > 0) {
            for (size_t i = 0; i < max_size_; ++i) {
                delete[] records_[i].value;
            }
            records_.clear();

            max_size_ = 0;
            current_size_ = 0;
            total_allocated_ = 0;
        }
    }

    // Add a new record to the memory pool
    void addRecord(const Record& record) {
        if (current_size_ >= max_size_) {
            allocate(max_size_ * 2);
        }

        records_.push_back(record);
        ++current_size_;
        total_allocated_ += sizeof(Record);
    }

    // Get the number of allocated records
    size_t getNumRecords() const { return current_size_; }

    // Get the total memory usage in bytes
    size_t getTotalMemoryUsage() const { return total_allocated_; }

private:
    size_t max_size_;
    size_t current_size_;
    size_t total_allocated_;
    vector<Record> records_;
};

// Define a class to track memory usage and resource allocation events
class MemoryTracker {
public:
    MemoryTracker() : mem_used_(0), num_allocations_(0) {}

    // Increment the number of allocations and update the memory usage
    void incrementNumAllocations(const size_t size) {
        ++num_allocations_;
        mem_used_ += size;
    }

    // Decrement the number of allocations and update the memory usage
    void decrementNumAllocations(const size_t size) {
        --num_allocations_;
        mem_used_ -= size;
    }

    // Get the total memory usage in bytes
    size_t getMemUsed() const { return mem_used_; }

    // Get the number of allocations
    size_t getNumAllocations() const { return num_allocations_; }

private:
    size_t mem_used_;
    size_t num_allocations_;
};

