// Define the data structure for each entry in the collection
typedef struct Entry {
  size_t size;
  unsigned long session_id;
  struct Data {
    double d;
    char *c;
    int i;
  } data;
} Entry;

// Define a linked list data structure to hold the collection of entries
typedef struct LinkedList {
  struct Node {
    Entry entry;
    struct Node *next;
  } *head, *tail;
} LinkedList;

// Function to allocate memory for a new entry in the collection
Entry* allocate_entry(size_t size, unsigned long session_id) {
  Entry *new_entry = (Entry*)malloc(sizeof(Entry));
  if (new_entry == NULL) {
    return NULL;
  }
  new_entry->size = size;
  new_entry->session_id = session_id;
  return new_entry;
}

// Function to insert a new entry into the linked list
void insert_into_list(LinkedList *list, Entry *new_entry) {
  struct Node *node = (struct Node*)malloc(sizeof(struct Node));
  node->entry = *new_entry;
  node->next = NULL;
  if (list->head == NULL) {
    list->head = node;
  } else {
    list->tail->next = node;
  }
  list->tail = node;
}

// Function to retrieve an entry from the linked list
Entry* get_entry(LinkedList *list, unsigned long session_id) {
  struct Node *node = list->head;
  while (node != NULL) {
    if (node->entry.session_id == session_id) {
      return &node->entry;
    }
    node = node->next;
  }
  return NULL;
}

// Function to rate-limit a single session based on the bandwidth threshold
void rate_limit(LinkedList *list, unsigned long session_id, size_t max_size) {
  struct Node *node = list->head;
  while (node != NULL) {
    if (node->entry.session_id == session_id && node->entry.size > max_size) {
      Entry *updated_entry = allocate_entry(max_size, session_id);
      memcpy(updated_entry, &node->entry, sizeof(Entry));
      free(node);
      insert_into_list(list, updated_entry);
      break;
    }
    node = node->next;
  }
}

// Function to iterate over the linked list and apply the rate-limiting algorithm
void iterate_over_list(LinkedList *list, size_t max_size) {
  struct Node *node = list->head;
  while (node != NULL) {
    if (node->entry.size > max_size) {
      rate_limit(list, node->entry.session_id, max_size);
    }
    node = node->next;
  }
}

// Function to remove an entry from the linked list
void remove_from_list(LinkedList *list, unsigned long session_id) {
  struct Node *node = list->head;
  while (node != NULL) {
    if (node->entry.session_id == session_id) {
      free(node);
      break;
    }
    node = node->next;
  }
}
