    // Initialize the array of records
    records = malloc(sizeof(struct record));
    if (records == NULL) {
        perror("malloc");
        return -1;
    }
    num_records++;

    // Read input from standard input and process each record
    while (fscanf(stdin, "%d", &records[num_records].value) == 1) {
        records[num_records].timestamp = timestamp;
        records[num_records].identifier = strdup(identifier);
        num_records++;

        // Reallocate the array of records if necessary
        if (num_records % 10 == 0) {
            struct record *tmp = realloc(records, num_records + 10);
            if (tmp == NULL) {
                perror("realloc");
                return -1;
            }
            records = tmp;
        }
    }

    // Track the maximum value found across all records
    for (int i = 0; i < num_records; i++) {
        if (records[i].value > max_value) {
            max_value = records[i].value;
        }
    }

