struct record {
    int id;
    double timestamp;
    int value;
    double weighted_sum;
};

int processAndFindMax(int min, int max) {
    // Initialize variables for managing memory
    long *offset_values = NULL;
    int *key_values = NULL;
    struct record *records = NULL;
    size_t num_records = 0;
    size_t capacity = 0;

    // Read input from standard input and populate records
    while (1) {
        // Read next integer value
        int value;
        scanf("%d", &value);

        if (!(value >= min && value <= max)) {
            // Ignore values that are outside the specified range
            continue;
        }

        // Check if we need to allocate more memory for records
        if (num_records == capacity) {
            // Double the size of the record array
            capacity *= 2;
            struct record *new_records = realloc(records, capacity * sizeof(struct record));
            if (new_records == NULL) {
                // Memory allocation failed, release all allocated resources and return -1
                free(offset_values);
                free(key_values);
                free(records);
                printf("Error: Memory allocation failed\n");
                return -1;
            } else {
                records = new_records;
            }
        }

        // Populate the record with a random value within the specified range
        srand((unsigned int)time(NULL));
        int rand_value = min + (rand() % (max - min + 1));
        records[num_records].id = num_records;
        records[num_records].timestamp = time(NULL);
        records[num_records].value = rand_value;
        records[num_records].weighted_sum = rand_value * (1.0 / (min + max));
        num_records++;
    }

    // Filter the records based on age, number in past 3 seconds, and weighted sum
    long current_time = time(NULL);
    long cutoff_time = current_time - 3000;
    size_t filtered_num_records = 0;
    for (size_t i = 0; i < num_records; i++) {
        struct record *record = &records[i];
        if (record->timestamp > cutoff_time) {
            // Record is still valid, skip it
            continue;
        }

        if (current_time - record->timestamp > 3000) {
            // Record is too old, ignore it
            continue;
        }

        filtered_num_records++;
    }

    // Update the metrics and return the maximum weighted sum along with its corresponding ID
    long max_weighted_sum = 0;
    int max_id = -1;
    for (size_t i = 0; i < filtered_num_records; i++) {
        struct record *record = &records[i];
        if (record->weighted_sum > max_weighted_sum) {
            max_weighted_sum = record->weighted_sum;
            max_id = record->id;
        }
    }

    // Release all allocated memory
    free(offset_values);
    free(key_values);
    free(records);

    return max_id;
}
