typedef struct record {
    float value;
    char label;
    time_t timestamp;
} Record;

void processAndAggregateData(int numStreams, int* streamSizes, float** dataArrays, char** labelsArrays) {
    // Initialize the arrays to store the processed data and labels
    float* processedData = malloc(numStreams * sizeof(float));
    char* processedLabels = malloc(numStreams * sizeof(char));

    // Create a mutex for each stream to synchronize access to the data arrays
    pthread_mutex_t* streamsMutexes = malloc(numStreams * sizeof(pthread_mutex_t));
    for (int i = 0; i < numStreams; ++i) {
        pthread_mutex_init(&streamsMutexes[i], NULL);
    }

    // Create a condition variable to signal when all streams have processed their data
    pthread_cond_t* streamsReadyCond = malloc(sizeof(pthread_cond_t));
    pthread_cond_init(streamsReadyCond, NULL);

    // Create threads for each stream and pass them the necessary data
    pthread_t* threads = malloc(numStreams * sizeof(pthread_t));
    for (int i = 0; i < numStreams; ++i) {
        int threadIndex = i;
        pthread_create(&threads[i], NULL, processDataThread, &threadIndex);
    }

    // Wait for all threads to finish and clean up
    for (int i = 0; i < numStreams; ++i) {
        pthread_join(threads[i], NULL);
        pthread_cond_destroy(&streamsReadyCond[i]);
        pthread_mutex_destroy(&streamsMutexes[i]);
    }

    free(processedData);
    free(processedLabels);
    free(threads);
    free(streamsMutexes);
    free(streamsReadyCond);
}

void* processDataThread(void* threadIndex) {
    int index = *((int*)threadIndex);
    float* dataArray = dataArrays[index];
    char* labelsArray = labelsArrays[index];

    // Acquire the mutex for this stream to synchronize access to the data arrays
    pthread_mutex_lock(&streamsMutexes[index]);

    // Process the data and update the processed data array
    float* processedData = malloc(sizeof(float) * numStreams);
    char* processedLabels = malloc(sizeof(char) * numStreams);
    for (int i = 0; i < streamSizes[index]; ++i) {
        processedData[i] = dataArray[i] + 1; // Add 1 to the value
        processedLabels[i] = labelsArray[i]; // Copy the label
    }

    // Release the mutex for this stream
    pthread_mutex_unlock(&streamsMutexes[index]);

    // Wait for all streams to process their data before aggregating it
    pthread_cond_wait(streamsReadyCond, NULL);

    // Aggregate the processed data and labels
    float sum = 0;
    int count = 0;
    for (int i = 0; i < numStreams; ++i) {
        sum += processedData[i];
        count++;
    }

    float average = sum / count;
    printf("Average value from all streams: %f\n", average);

    free(processedData);
    free(processedLabels);

    return NULL;
}
```
