    std::cout << "Error: Source file does not exist or cannot be read." << std::endl;
    return 1;
  }

  // Open the source file for reading
  std::ifstream inFile(sourceFile);
  if (!inFile) {
    std::cout << "Error: Could not open source file." << std::endl;
    return 1;
  }

  // Create a unique hash seed value based on the current time and the size of the source file
  uint64_t hashSeed = (uint64_t)time(NULL) ^ (uint64_t)stat(sourceFile, &inFile).st_size;

  // Initialize the random number generator with the seed value
  std::random_device rd;
  std::mt19937 gen(rd());
  gen.seed(hashSeed);

  // Generate a specified number of records based on the source file's content and the specified range
  int recordIndex = 0;
  Record* records = new Record[recordCount];
  while (inFile >> value) {
    if (recordIndex >= recordCount) {
      break;
    }

    // Generate a random value within the specified range
    int randomValue = std::uniform_int_distribution<int>(minRandomValue, maxRandomValue)(gen);
    records[recordIndex].value = randomValue;
    recordIndex++;
  }

  // Close the source file
  inFile.close();

  // Create a ZIP archive of the generated records
  zip_file* outFile = zip_open(outputFile, 0, 'w');
  if (!outFile) {
    std::cout << "Error: Could not open output file." << std::endl;
    return 1;
  }

  // Write the generated records to the ZIP archive
  for (int i = 0; i < recordCount; i++) {
    Record* record = &records[i];
    zip_write(outFile, "record", sizeof(Record), 1);
  }

  // Close the ZIP archive
  zip_close(outFile);

  // Clean up temporary files and memory allocations
  delete[] records;

  return 0;
}

