typedef struct connectionPool {
  int size;
  struct dbMetadata* metadata;
  pthread_mutex_t lock;
} ConnectionPool;

void databaseManager(ConnectionPool* pool, char* queryString, int transactionID) {
  if (!pool || !queryString || !transactionID) return;

  // Acquire lock to protect shared resource
  pthread_mutex_lock(&pool->lock);

  // Check if connection is available in the pool
  for (int i = 0; i < pool->size; ++i) {
    if (pool->metadata[i].status == FREE) {
      // Allocate memory for query string and transaction ID
      char* queryBuffer = malloc(sizeof(char) * strlen(queryString));
      int* transactionIDBuffer = malloc(sizeof(int));

      // Copy query string and transaction ID to allocated memory
      strcpy(queryBuffer, queryString);
      *transactionIDBuffer = transactionID;

      // Update metadata for the connection
      pool->metadata[i].status = USED;
      pool->metadata[i].lastAccessTime = time(NULL);
      pool->metadata[i].errorCode = NO_ERROR;

      // Release lock to allow other threads to access shared resource
      pthread_mutex_unlock(&pool->lock);

      // Execute query and commit/rollback transaction as needed
      executeQuery(queryBuffer, *transactionIDBuffer);
      if (pool->metadata[i].errorCode != NO_ERROR) {
        rollbackTransaction(*transactionIDBuffer);
      } else {
        commitTransaction(*transactionIDBuffer);
      }

      // Free allocated memory
      free(queryBuffer);
      free(transactionIDBuffer);

      return;
    }
  }

  // Release lock to allow other threads to access shared resource
  pthread_mutex_unlock(&pool->lock);

  // If no connection is available, create a new one and add it to the pool
  struct dbMetadata metadata = {FREE, time(NULL), NO_ERROR};
  int* transactionIDBuffer = malloc(sizeof(int));
  *transactionIDBuffer = createNewTransaction();
  ConnectionPool* newPool = realloc(pool, sizeof(ConnectionPool) + (++pool->size) * sizeof(struct dbMetadata));
  if (!newPool) {
    // Handle memory allocation failure
    return;
  }

  pool = newPool;
  pool->metadata[pool->size - 1] = metadata;
  pool->lock = pthread_mutex_init();

  executeQuery(queryString, *transactionIDBuffer);
  if (pool->metadata[pool->size - 1].errorCode != NO_ERROR) {
    rollbackTransaction(*transactionIDBuffer);
  } else {
    commitTransaction(*transactionIDBuffer);
  }

  free(transactionIDBuffer);
}

void executeQuery(char* queryString, int transactionID) {
