    record->timestamp = (double)clock() / CLOCKS_PER_SEC * 1000.0;
    record->log_message = DEFAULT_LOG_MESSAGE;
    record->success = true;
}

void init_manager(LogManager* manager) {
    // Initialize the log manager with an array of strings to store log entries
    manager->operation_count = 0;
    manager->error_count = 0;
    manager->log_entries = calloc(MAX_RECORDS, sizeof(char*));
}

void free_manager(LogManager* manager) {
    // Free the log entries array and reset the log manager
    for (int i = 0; i < MAX_RECORDS; i++) {
        free(manager->log_entries[i]);
    }
    free(manager->log_entries);
    manager->operation_count = 0;
    manager->error_count = 0;
}

void add_record(Record* record, long offset) {
    // Add a new record to the log manager and update the operation count
    Record new_record = *record;
    init_record(&new_record, offset);
    LogManager* manager = get_manager();
    manager->log_entries[manager->operation_count] = malloc(sizeof(Record));
    memcpy(manager->log_entries[manager->operation_count], &new_record, sizeof(Record));
    manager->operation_count++;
}

void add_error(long offset) {
    // Add an error log entry to the log manager and update the error count
    LogManager* manager = get_manager();
    manager->log_entries[manager->operation_count] = malloc(sizeof(char*));
    sprintf(manager->log_entries[manager->operation_count], "Error encountered at offset %d", offset);
    manager->error_count++;
}

void log_record(Record* record) {
    // Log the record to the log manager and update the operation count
    Record new_record = *record;
    init_record(&new_record, 0);
    LogManager* manager = get_manager();
    manager->log_entries[manager->operation_count] = malloc(sizeof(Record));
    memcpy(manager->log_entries[manager->operation_count], &new_record, sizeof(Record));
    manager->operation_count++;
}

void log_error(long offset) {
    // Log an error to the log manager and update the error count
    LogManager* manager = get_manager();
    manager->log_entries[manager->operation_count] = malloc(sizeof(char*));
    sprintf(manager->log_entries[manager->operation_count], "Error encountered at offset %d", offset);
    manager->error_count++;
}

void print_log() {
    // Print the log entries to the console
    LogManager* manager = get_manager();
    for (int i = 0; i < manager->operation_count; i++) {
        printf("%s\n", manager->log_entries[i]);
    }
}
