    if (keys[num_records - 1] > largest_key) {
      largest_key = keys[num_records - 1];
    }
  }

  // Free memory for arrays of offsets, keys, and records
  free(offset_values);
  free(keys);
  free(records);

  // Return the largest integer found among the provided inputs
  return largest_key;
}

