}

// Read the configuration file and update the configuration settings
int readFileConfig(const char* filename, struct file_config* cfg) {
    // Check input parameters
    if (filename == NULL || cfg == NULL) {
        return -1;
    }

    // Open the configuration file in read-only mode
    int fd = open(filename, O_RDONLY);
    if (fd == -1) {
        return -2;
    }

    // Read the contents of the configuration file
    char* buffer = (char*)malloc(sizeof(char) * 1024);
    if (buffer == NULL) {
        close(fd);
        return -3;
    }
    ssize_t bytes_read = read(fd, buffer, 1024);
    if (bytes_read == -1) {
        free(buffer);
        close(fd);
        return -4;
    }

    // Parse the configuration file and update the settings
    char* token = strtok(buffer, " ");
    while (token != NULL) {
        if (strcmp(token, "--buffer-size") == 0) {
            token = strtok(NULL, "\n");
            if (token == NULL) {
                break;
            }
            cfg->buffer_size = atoi(token);
        }
        token = strtok(NULL, " ");
    }

    // Close the configuration file and free memory
    close(fd);
    free(buffer);

    return 0;
}']

