struct logEntry* pool = NULL; // Pointer to the start of the memory pool

// Function to allocate a new log entry and initialize it with random data
struct logEntry* allocLogEntry() {
    struct logEntry* entry = (struct logEntry*) malloc(sizeof(struct logEntry));
    if (entry == NULL) {
        printf("Error: Out of memory!\n");
        return NULL;
    }
    entry->id = rand() % 1000; // Randomly generate an id between 0 and 1000
    entry->metric = (double)rand() / RAND_MAX * 100; // Generate a random metric value between 0 and 100
    entry->timestamp = time(NULL); // Get the current timestamp
    return entry;
}

// Function to add a log entry to the memory pool
void addLogEntry(struct logEntry* entry) {
    if (pool == NULL) {
        // Initialize the memory pool with the first log entry
        pool = (struct logEntry*) malloc(sizeof(struct logEntry) * POOL_SIZE);
        if (pool == NULL) {
            printf("Error: Out of memory!\n");
            return;
        }
    } else {
        // Check if the memory pool is full and allocate more memory if needed
        if ((pool - (struct logEntry*) malloc(sizeof(struct logEntry) * POOL_SIZE)) >= POOL_SIZE) {
