// Define the data structure to store environmental sensor readings
typedef struct {
  double temperature;
  int humidity;
  char status;
} SensorReading;

// Initialize a new sensor reading with randomly generated values within specified ranges
SensorReading *init_sensor_reading() {
  // Generate random temperatures between -20°C and 50°C
  double temperature = (double)rand() / RAND_MAX * (50 - (-20)) + (-20);
  // Generate random humidity levels between 0% and 100%
  int humidity = (int)rand() % 101;
  // Set the status based on predefined conditions
  char status = 'normal';
  if (temperature > 35 || humidity > 60) {
    status = 'critical';
  }

  SensorReading *reading = malloc(sizeof(SensorReading));
  reading->temperature = temperature;
  reading->humidity = humidity;
  reading->status = status;
  return reading;
}

// Update a sensor reading with data from an external weather API
void update_sensor_reading(SensorReading *reading, double new_temperature, int new_humidity) {
  // Set the new temperature and humidity values
  reading->temperature = new_temperature;
  reading->humidity = new_humidity;
  // Update the status based on predefined conditions
  if (reading->temperature > 35 || reading->humidity > 60) {
    reading->status = 'critical';
  } else {
    reading->status = 'normal';
  }
}

// Manage a collection of environmental sensor readings in a flexible and efficient manner
void manage_sensor_readings(int num_threads, int num_records) {
  // Initialize the sensor readings array with randomly generated values
  SensorReading *readings = malloc(sizeof(SensorReading) * num_records);
  for (int i = 0; i < num_records; i++) {
    readings[i] = init_sensor_reading();
  }

  // Update the sensor readings periodically with data from an external weather API
  while (1) {
    // Wait for a random amount of time before updating the sensor readings
    int update_interval = rand() % 3600;
    sleep(update_interval);
    // Fetch new climate data from the external API
    double new_temperature, new_humidity;
    fetch_climate_data(&new_temperature, &new_humidity);
    // Update each sensor reading with the new climate data
    for (int i = 0; i < num_records; i++) {
      update_sensor_reading(&readings[i], new_temperature, new_humidity);
    }
  }
}

// Fetch new climate data from an external weather API and return it in the specified variables
void fetch_climate_data(double *new_temperature, int *new_humidity) {
  // Simulate a random delay before returning the climate data
  sleep(rand() % 30);
  // Set the new temperature and humidity values randomly generated within specified ranges
  double temperature = (double)rand() / RAND_MAX * (50 - (-20)) + (-20);
  int humidity = (int)rand() % 101;
  // Return the climate data
  *new_temperature = temperature;
  *new_humidity = humidity;
}

// Clean up memory resources used by the sensor readings
void free_sensor_readings(SensorReading *readings) {
  // Free each sensor reading and its associated data structures
  for (int i = 0; i < num_records; i++) {
    free(readings[i]);
  }
}

// Main function to manage the environmental sensor readings in a concurrent manner
int main() {
  // Initialize the number of threads and records
  int num_threads = 4;
  int num_records = 10000;

  // Create a thread pool to manage the concurrent access to the sensor readings
  pthread_t *threads = malloc(sizeof(pthread_t) * num_threads);
  for (int i = 0; i < num_threads; i++) {
    pthread_create(&threads[i], NULL, manage_sensor_readings, (void *)num_records);
  }

  // Wait for all threads to finish before cleaning up memory resources
  for (int i = 0; i < num_threads; i++) {
    pthread_join(threads[i], NULL);
  }

  // Clean up the memory resources used by the sensor readings
  free_sensor_readings(readings);
  free(threads);

  return 0;
}
