void initSensorData(int numStations, struct SensorData **data) {
  // Allocate memory for the array of structures
  *data = (struct SensorData *)malloc(sizeof(struct SensorData) * numStations);

  // Initialize each structure in the array with a timestamp and default values for temperature, humidity, and status
  for (int i = 0; i < numStations; i++) {
