void processSensorData(struct SensorData *data, int numStations) {
  // Loop through each station and process its readings independently
  for (int i = 0; i < numStations; i++) {
    struct SensorData currentReading = data[i];

    // Handle missing or invalid sensor data gracefully
    if (!currentReading.valid) {
      continue;
    }

    // Update the rolling average temperature over the past 24 hours
    int numHours = 24;
    struct SensorData *rollingAverageTemp = (struct SensorData *)malloc(sizeof(struct SensorData) * numHours);

    for (int j = 0; j < numHours; j++) {
      rollingAverageTemp[j].temperature += currentReading.temperature;
    }

    // Store the historical readings in memory
    data[i].historicalTemperature = rollingAverageTemp / numHours;
  }
}

