// Define a struct to represent a Node in the collection
typedef struct Node {
    char key;
    long timestamp;
    double value;
} Node;

// Define a hash table to keep track of unique keys
typedef struct HashTable {
    int size;
    Node** nodes;
} HashTable;

// Function to initialize the collection and verify uniqueness
void init_collection(HashTable* ht) {
    // Initialize the hash table with a default size
    ht->size = 1024;
    ht->nodes = (Node**)malloc(ht->size * sizeof(Node*));
    if (!ht->nodes) {
        printf("Error: Memory allocation failed\n");
        return;
    }

    // Initialize all nodes in the hash table to NULL
    for (int i = 0; i < ht->size; i++) {
        ht->nodes[i] = NULL;
    }
}

// Function to insert a new node into the collection
void insert_node(HashTable* ht, char key, long timestamp, double value) {
    // Check if the key is already in the hash table
    bool exists = false;
    for (int i = 0; i < ht->size && !exists; i++) {
        if (ht->nodes[i] && ht->nodes[i]->key == key) {
            exists = true;
        }
    }

    // If the key is not in the hash table, insert a new node
    if (!exists) {
        Node* n = malloc(sizeof(Node));
        if (!n) {
            printf("Error: Memory allocation failed\n");
            return;
        }
        n->key = key;
        n->timestamp = timestamp;
        n->value = value;
        ht->nodes[hash_key(key)] = n;
    }
}

// Function to retrieve a node from the collection by key
Node* get_node(HashTable* ht, char key) {
    int index = hash_key(key);
    return ht->nodes[index];
}

// Function to update a node in the collection
void update_node(HashTable* ht, char key, long timestamp, double value) {
    Node* n = get_node(ht, key);
    if (n) {
        n->timestamp = timestamp;
        n->value = value;
    } else {
        printf("Error: Key not found\n");
    }
}

// Function to delete a node from the collection
void delete_node(HashTable* ht, char key) {
    int index = hash_key(key);
    free(ht->nodes[index]);
    ht->nodes[index] = NULL;
}

// Function to check if a node is in the collection by key
bool contains_node(HashTable* ht, char key) {
    Node* n = get_node(ht, key);
    return n != NULL;
}

// Function to iterate over all nodes in the collection
void for_each_node(HashTable* ht, void (*func)(Node*)) {
    for (int i = 0; i < ht->size; i++) {
        if (ht->nodes[i]) {
            func(ht->nodes[i]);
        }
    }
}

// Function to free all memory allocated by the collection
void destroy_collection(HashTable* ht) {
    for (int i = 0; i < ht->size; i++) {
        if (ht->nodes[i]) {
            free(ht->nodes[i]);
        }
    }
    free(ht->nodes);
}
