Node* insertAtHead(LinkedList* list, Node* node) {
    // Handle edge case of empty linked list
    if (list->head == NULL) {
        list->head = node;
        list->tail = node;
        return node;
    }

    // Insert at head of linked list
    node->next = list->head;
    list->head = node;

    return node;
}

void removeNode(LinkedList* list, Node* node) {
    // Handle edge case of empty linked list
    if (list->head == NULL) {
        printf("Cannot remove from an empty linked list!\n");
        return;
    }

    // Remove specified node
    if (node == list->head) {
        list->head = node->next;
    } else {
        Node* current = list->head;
        while (current != NULL && current->next != node) {
            current = current->next;
        }
        if (current == NULL) {
            printf("Node not found in linked list!\n");
        } else {
            current->next = node->next;
        }
    }
}

void freeList(LinkedList* list) {
    // Handle edge case of empty linked list
    if (list->head == NULL) {
        return;
    }

    // Free all nodes in the linked list
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
}

struct LinkedList {
    Node* head;
    Node* tail;
};

struct Node {
    char* key;
    long timestamp;
    double value;
    Node* next;
};

struct HashTable {
    int size;
    int count;
    struct Node** table;
};

HashTable<char, Node> hashTable(int size) {
    // Allocate memory for the hash table
    HashTable<char, Node> table = malloc(sizeof(HashTable));
    if (table == NULL) {
        printf("Memory allocation failed!\n");
        return NULL;
    }

    // Initialize the hash table with the given size
    table->size = size;
    table->count = 0;
    table->table = malloc(sizeof(struct Node*) * size);
    if (table->table == NULL) {
        free(table);
        printf("Memory allocation failed!\n");
        return NULL;
    }

    // Initialize all elements of the hash table to NULL
    for (int i = 0; i < size; i++) {
        table->table[i] = NULL;
    }

    return table;
}

void put(HashTable<char, Node>* table, char* key, Node* value) {
    // Handle edge case of empty hash table
    if (table == NULL || table->size == 0) {
        printf("Cannot add to an empty hash table!\n");
        return;
    }

    // Calculate the index for the given key in the hash table
    int index = hashCode(key, table->size);

    // Check if there is already a node with this key in the hash table
    Node* existingNode = table->table[index];
    if (existingNode != NULL) {
        // If there is, update the value of the existing node
        existingNode->value = value;
    } else {
        // Otherwise, create a new node with this key and add it to the hash table
        Node* newNode = malloc(sizeof(Node));
        if (newNode == NULL) {
            printf("Memory allocation failed!\n");
            return;
        }
        newNode->key = key;
        newNode->value = value;
        table->table[index] = newNode;
        table->count++;
    }
}

void remove(HashTable<char, Node>* table, char* key) {
    // Handle edge case of empty hash table
    if (table == NULL || table->size == 0) {
        printf("Cannot remove from an empty hash table!\n");
        return;
    }

    // Calculate the index for the given key in the hash table
    int index = hashCode(key, table->size);

    // Check if there is a node with this key in the hash table
    Node* existingNode = table->table[index];
    if (existingNode != NULL) {
        // If there is, remove it from the hash table
        table->table[index] = NULL;
        table->count--;
    } else {
        printf("Key not found in hash table!\n");
    }
}

int hashCode(char* key, int size) {
    // Calculate the hash code for the given key and size
    int hash = 0;
    for (int i = 0; i < strlen(key); i++) {
        hash = (hash + key[i]) % size;
    }

    return hash;
}
