            newNode->value = update->value;
            addNode(newNode);
        }
    }
}

// Function to query the dynamic collection of nodes for a specific key
double getValue(const char *key) {
    // Get the node corresponding to the input key from the hash table
    Node *node = getNode(key);
    if (node != NULL) {
        return node->value;
    } else {
        return NAN;
    }
}

// Function to add a new node to the dynamic collection of nodes
void addNode(const char *key, long timestamp, double value) {
    // Check if there is enough memory to allocate a new node
    if (nodes == NULL) {
        return;
    }

    // Find the first available slot in the hash table for the new node
    int i = 0;
    while (nodes[i] != NULL && strcmp(key, nodes[i]->key) != 0) {
        i++;
    }

    // If a matching key is already in the hash table, update it with the new timestamp and value
    if (nodes[i] != NULL) {
        nodes[i]->timestamp = timestamp;
        nodes[i]->value = value;
    } else {
        // Otherwise, allocate a new node and add it to the hash table
        Node *newNode = malloc(sizeof(Node));
        assert(newNode != NULL);
        strcpy(newNode->key, key);
        newNode->timestamp = timestamp;
        newNode->value = value;
        nodes[i] = newNode;
    }
}

// Function to delete a node from the dynamic collection of nodes
void deleteNode(const char *key) {
    // Find the node corresponding to the input key in the hash table
    int i = 0;
    while (nodes[i] != NULL && strcmp(key, nodes[i]->key) != 0) {
        i++;
    }

    // If a matching key is found, free the node and update the hash table
    if (nodes[i] != NULL) {
        free(nodes[i]);
        nodes[i] = NULL;
    }
}
```

