#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>
#include <unistd.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <iostream>

using namespace std;

// Define constants for the database connection pool
#define CONNECTION_POOL_SIZE 10
#define MAX_CONCURRENT_QUERIES 256
#define QUERY_TIMEOUT 60 // seconds

// Struct to represent a database connection
struct DatabaseConnection {
    int fd;
    struct sockaddr_in addr;
};

// Array of available database connections
DatabaseConnection* connections = new DatabaseConnection[CONNECTION_POOL_SIZE];

// Semaphore for controlling access to the connection pool
sem_t* connectionPoolSemaphore;

// Function to initialize the database connection pool
void initConnectionPool() {
    int i;
    for (i = 0; i < CONNECTION_POOL_SIZE; i++) {
        connections[i].fd = -1;
    }
    connectionPoolSemaphore = sem_open("connectionPool", O_CREAT, 0644, CONNECTION_POOL_SIZE);
}

// Function to acquire a database connection from the pool
int getConnection() {
    int i;
    for (i = 0; i < CONNECTION_POOL_SIZE; i++) {
        if (connections[i].fd == -1) {
            break;
        }
    }
    if (i == CONNECTION_POOL_SIZE) {
        return -1;
    }
    sem_wait(connectionPoolSemaphore);
    connections[i].fd = socket(AF_INET, SOCK_STREAM, 0);
    if (connections[i].fd == -1) {
        sem_post(connectionPoolSemaphore);
        return -1;
    }
    return i;
}

// Function to release a database connection back to the pool
void releaseConnection(int index) {
    if (connections[index].fd == -1) {
        return;
    }
    close(connections[index].fd);
    connections[index].fd = -1;
    sem_post(connectionPoolSemaphore);
}

// Function to manage database connections in a highly concurrent multi-threaded application
void* manageDatabaseConnections(void* args) {
    int index;
    struct DatabaseConnection* connection;
    struct sockaddr_in addr;
    fd_set readfds;
    timeval timeout;
    int nfds;
    char buffer[1024];

    // Acquire a database connection from the pool
    index = getConnection();
    if (index == -1) {
        return NULL;
    }
    connection = &connections[index];

    // Set up the socket address for the distributed database system
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(5432);
    inet_pton(AF_INET, "192.168.1.1", &addr.sin_addr);

    // Connect to the distributed database system
    if (connect(connection->fd, (struct sockaddr*)&addr, sizeof(addr)) == -1) {
        perror("connect");
        releaseConnection(index);
        return NULL;
    }

    // Set up the read file descriptor set
    FD_ZERO(&readfds);
    FD_SET(connection->fd, &readfds);
    nfds = connection->fd + 1;

    while (1) {
        // Wait for incoming data or a timeout
        timeout.tv_sec = QUERY_TIMEOUT;
        timeout.tv_usec = 0;
        if (select(nfds, &readfds, NULL, NULL, &timeout) == -1) {
            perror("select");
            break;
        }

        // Handle incoming data
        if (FD_ISSET(connection->fd, &readfds)) {
            // Read the query from the socket
            int n = recv(connection->fd, buffer, sizeof(buffer), 0);
            if (n == -1) {
                perror("recv");
                break;
            }

            // Handle the query
            if (!strncmp(buffer, "COMMIT", n)) {
                // Commit the transaction
                send(connection->fd, "COMMIT\n", 6, 0);
            } else if (!strncmp(buffer, "ROLLBACK", n)) {
                // Roll back the transaction
                send(connection->fd, "ROLLBACK\n", 8, 0);
            } else if (strlen(buffer) > 6 && !strncmp(buffer, "QUERY ", 6)) {
                // Execute the query
                send(connection->fd, buffer + 6, strlen(buffer) - 6, 0);
            } else {
                // Unsupported operation or configuration error
                send(connection->fd, "ERROR\n", 6, 0);
            }
        }
    }

    // Close the connection and release it back to the pool
    close(connection->fd);
    connection->fd = -1;
    releaseConnection(index);

    return NULL;
}

int main() {
    initConnectionPool();
    pthread_t thread;
    int i;
    for (i = 0; i < CONNECTION_POOL_SIZE; i++) {
        if (pthread_create(&thread, NULL, manageDatabaseConnections, NULL) != 0) {
            perror("pthread_create");
            return 1;
        }
    }
    pthread_exit(NULL);
}
```
This is a simple example of how to manage database connections in a highly concurrent multi-threaded application using a connection pool. In this example, we use a fixed number of threads to handle incoming requests, and each thread manages its own set of database connections. The `manageDatabaseConnections` function is called once for each thread, and it handles incoming requests from the socket by reading them and executing the appropriate database operations.

This code uses the Berkeley sockets API to implement the connection pool and handle incoming requests. It also uses pthreads to create multiple threads that can handle incoming requests simultaneously. The `select` function is used to wait for incoming data on the socket, and the `recv` function is used to read the query from the socket once it has been received.

The code also includes some error handling to make sure that any errors are handled gracefully and that the application does not crash in case of an unexpected situation.']

