#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define struct to store data for each record
typedef struct {
  int value;
  long timestamp;
  float weight;
} Record;

// Define array of pointers to store records
Record* records = NULL;

// Function to process and analyze data
void processAndAnalyzeData(FILE *input) {
  // Check if input is not null
  if (input == NULL) {
    printf("Error: Input file is null\n");
    return;
  }

  // Initialize variables for memory management
  long num_records = 0;
  int record_size = sizeof(Record);

  // Loop through each line of input and process data
  char* line = NULL;
  size_t len = 0;
  ssize_t read;
  while ((read = getline(&line, &len, input)) != -1) {
    // Allocate memory for record
    Record* new_record = (Record*) malloc(record_size);
    if (new_record == NULL) {
      printf("Error: Failed to allocate memory for record\n");
      return;
    }

    // Parse line and store data in record
    char* token = strtok(line, " ");
    new_record->value = atoi(token);
    token = strtok(NULL, " ");
    new_record->timestamp = atol(token);
    token = strtok(NULL, " ");
    new_record->weight = atof(token);

    // Add record to array of pointers
    records = (Record**) realloc(records, sizeof(Record*) * (num_records + 1));
    if (records == NULL) {
      printf("Error: Failed to reallocate memory for records\n");
      return;
    }
    records[num_records] = new_record;
    num_records++;

    // Free line buffer and reset length
    free(line);
    len = 0;
  }

  // Check if any errors occurred during processing
  if (ferror(input) || records == NULL) {
    printf("Error: Failed to process input data\n");
    return;
  }

  // Sort records by value in ascending order
  qsort(records, num_records, record_size, compareValues);

  // Find and print highest-value record and its weight
  Record* highest = &records[0];
  for (int i = 1; i < num_records; i++) {
    if (highest->value < records[i]->value) {
      highest = records[i];
    }
  }
  printf("Highest value: %d\n", highest->value);
  printf("Weight of highest value: %.2f\n", highest->weight);

  // Free memory for records
  free(records);
}

// Compare function to sort records by value in ascending order
int compareValues(const void* a, const void* b) {
  Record* record_a = (Record*) a;
  Record* record_b = (Record*) b;
  return record_a->value - record_b->value;
}
