#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netdb.h>
#include <arpa/inet.h>
#include <pthread.h>

#define LOG_LEVEL_INFO 0
#define LOG_LEVEL_WARN 1
#define LOG_LEVEL_ERROR 2

#define BUFFER_SIZE 4096
#define MAX_ENTRIES 1000000
#define MEMORY_ALLOCATION_FAILURE "Failed to allocate memory for log entry"
#define DATA_PARSING_ERROR "Failed to parse log data"
#define COMMUNICATION_FAILURE "Communication failure with external service"

struct LogEntry {
    time_t timestamp;
    int severity;
    char* message;
};

struct LogManager {
    struct LogEntry* entries;
    size_t capacity;
    size_t num_entries;
    pthread_mutex_t lock;
};

void processAndStoreLogs(const char* input, struct LogManager* manager) {
    // Initialize log manager if necessary
    if (!manager->entries) {
        manager->capacity = MAX_ENTRIES;
        manager->num_entries = 0;
        manager->entries = malloc(sizeof(struct LogEntry) * manager->capacity);
        pthread_mutex_init(&manager->lock, NULL);
    }

    // Parse log data and add to log manager
    const char* delimiter = " ";
    struct LogEntry entry;
    while (fgets(input, BUFFER_SIZE, stdin)) {
        char* token = strtok(input, delimiter);
        if (!token) {
            break;
        }
        entry.timestamp = atoll(token);
        token = strtok(NULL, delimiter);
        if (!token) {
            break;
        }
        entry.severity = atoi(token);
        token = strtok(NULL, delimiter);
        if (!token) {
            break;
        }
        char* message = strdup(token);
        if (!message) {
            fprintf(stderr, MEMORY_ALLOCATION_FAILURE);
            return;
        }
        entry.message = message;
        pthread_mutex_lock(&manager->lock);
        if (manager->num_entries >= manager->capacity) {
            // Reallocate memory for log entries
            size_t new_capacity = manager->capacity * 2;
            struct LogEntry* new_entries = realloc(manager->entries, sizeof(struct LogEntry) * new_capacity);
            if (!new_entries) {
                fprintf(stderr, MEMORY_ALLOCATION_FAILURE);
                pthread_mutex_unlock(&manager->lock);
                return;
            }
            manager->entries = new_entries;
            manager->capacity = new_capacity;
        }
        manager->entries[manager->num_entries++] = entry;
        pthread_mutex_unlock(&manager->lock);
    }
}

void logToFile(const char* file, struct LogManager* manager) {
    // Open log file for writing
    FILE* fp = fopen(file, "w");
    if (!fp) {
        perror("Failed to open log file for writing");
        return;
    }

    // Write log entries to file
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->num_entries; i++) {
        fprintf(fp, "%lu %d %s\n", manager->entries[i].timestamp, manager->entries[i].severity, manager->entries[i].message);
    }
    pthread_mutex_unlock(&manager->lock);

    // Close log file
    fclose(fp);
}

void logToExternalService(const char* url, struct LogManager* manager) {
    // Open socket to external service
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        perror("Failed to open socket");
        return;
    }

    // Connect to external service
    struct sockaddr_in serv_addr;
    memset(&serv_addr, 0, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(80);
    if (inet_pton(AF_INET, url, &serv_addr.sin_addr) <= 0) {
        fprintf(stderr, "Failed to resolve hostname");
        close(sock);
        return;
    }
    if (connect(sock, (struct sockaddr*)&serv_addr, sizeof(serv_addr)) < 0) {
        perror("Failed to connect to external service");
        close(sock);
        return;
    }

    // Send log entries to external service
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->num_entries; i++) {
        char* buffer = malloc(BUFFER_SIZE);
        if (!buffer) {
            fprintf(stderr, MEMORY_ALLOCATION_FAILURE);
            pthread_mutex_unlock(&manager->lock);
            close(sock);
            return;
        }
        int num_bytes = snprintf(buffer, BUFFER_SIZE, "%lu %d %s\n", manager->entries[i].timestamp, manager->entries[i].severity, manager->entries[i].message);
        if (num_bytes < 0 || write(sock, buffer, num_bytes) != num_bytes) {
            perror("Failed to send log entry");
            free(buffer);
            pthread_mutex_unlock(&manager->lock);
            close(sock);
            return;
        }
        free(buffer);
    }
    pthread_mutex_unlock(&manager->lock);

    // Close socket to external service
    close(sock);
}

void logRotate(struct LogManager* manager) {
    // Implement log rotation here
}

int main() {
    struct LogManager manager;
    manager.num_entries = 0;
    manager.capacity = 10;
    manager.entries = malloc(sizeof(struct LogEntry) * manager.capacity);
    if (!manager.entries) {
        fprintf(stderr, MEMORY_ALLOCATION_FAILURE);
        return 1;
    }

    // Process log entries here
    processLogEntries(&manager);

    // Log rotate here
    logRotate(&manager);

    // Close log file and free memory
    fclose(fp);
    free(manager.entries);

    return 0;
}']

