typedef struct {
    int key;
    double timestamp;
} Record;

void processAndFindMax(int max_key, int min_key) {
    // Initialize arrays for offset values, keys, and records
    long *offset_values = NULL;
    int *keys = NULL;
    Record *records = NULL;

    // Allocate memory for the arrays
    offset_values = malloc(sizeof(long) * 10);
    if (offset_values == NULL) {
        fprintf(stderr, "Failed to allocate memory for offset values\n");
        return;
    }
    keys = malloc(sizeof(int) * 10);
    if (keys == NULL) {
        fprintf(stderr, "Failed to allocate memory for key values\n");
        free(offset_values);
        return;
    }
    records = malloc(sizeof(Record) * 10);
    if (records == NULL) {
        fprintf(stderr, "Failed to allocate memory for record structures\n");
        free(offset_values);
        free(keys);
        return;
    }

    // Initialize the arrays with random values within the specified range
    srand((unsigned int)time(NULL));
    for (int i = 0; i < 10; i++) {
        offset_values[i] = rand() % 10 + min_key;
        keys[i] = offset_values[i];
        records[i].key = offset_values[i];
        records[i].timestamp = time(NULL);
    }

    // Find the maximum value in the array of keys
    int max_value = INT_MIN;
    for (int i = 0; i < 10; i++) {
        if (keys[i] > max_value) {
            max_value = keys[i];
        }
    }

    // Print the maximum value and corresponding record
    printf("Maximum value: %d\n", max_value);
    printf("Corresponding record: {%d, %f}\n", records[max_value].key, records[max_value].timestamp);

    // Free memory for the arrays
    free(offset_values);
    free(keys);
    free(records);
}
