// Memory pool for allocating memory
static void* mempool = NULL;
static size_t mempool_size = 0;

// Function to dynamically allocate memory from the pool
void* dynamic_alloc(size_t size) {
  if (mempool == NULL || size > mempool_size) {
    // Allocate a new block of memory from the system
    void* ptr = malloc(size);
    if (ptr == NULL) {
      return NULL;
    }
    // Add the block to the pool
    mempool_size += size;
    return ptr;
  } else {
