// Function to initialize the configuration system and records system
int init_system(const char* config_file) {
    // Initialize variables to store configuration settings and records
    int* config_keys = NULL;
    char** config_values = NULL;
    Section* sections = NULL;

    // Read configuration settings from JSON file
    FILE* fp = fopen(config_file, "r");
    if (fp == NULL) {
        printf("Error: unable to open configuration file\n");
        return 1;
    }

    // Dynamically allocate memory for arrays of 'int' and 'char*' based on number of entries in JSON file
    int num_entries = 0;
    while (fscanf(fp, "%s", buffer) != EOF) {
        if (strcmp(buffer, "{" || strcmp(buffer, "}") == 0) {
            continue;
        } else {
            num_entries++;
        }
    }

    // Close file pointer and allocate memory for arrays of 'int' and 'char*' based on number of entries in JSON file
    fclose(fp);
    config_keys = (int*) malloc((num_entries + 1) * sizeof(int));
    if (config_keys == NULL) {
        printf("Error: unable to allocate memory for configuration keys\n");
        return 1;
    }
    config_values = (char**) malloc((num_entries + 1) * sizeof(char*));
    if (config_values == NULL) {
        printf("Error: unable to allocate memory for configuration values\n");
        free(config_keys);
        return 1;
    }

    // Initialize arrays of 'int' and 'char*' with configuration settings from JSON file
    int index = 0;
    while (fscanf(fp, "%s", buffer) != EOF) {
        if (strcmp(buffer, "{" || strcmp(buffer, "}") == 0) {
            continue;
        } else {
            config_keys[index] = atoi(buffer);
            config_values[index] = strdup(buffer);
            index++;
        }
    }

    // Close file pointer and allocate memory for array of 'Section' structures based on number of sections in JSON file
    fclose(fp);
    int num_sections = 0;
    while (fscanf(fp, "%s", buffer) != EOF) {
        if (strcmp(buffer, "{" || strcmp(buffer, "}") == 0) {
            continue;
        } else {
            num_sections++;
        }
    }
    sections = (Section*) malloc((num_sections + 1) * sizeof(Section));
    if (sections == NULL) {
        printf("Error: unable to allocate memory for section structures\n");
        free(config_keys);
        free(config_values);
        return 1;
    }

    // Initialize array of 'Section' structures with configuration settings from JSON file
    index = 0;
    while (fscanf(fp, "%s", buffer) != EOF) {
        if (strcmp(buffer, "{" || strcmp(buffer, "}") == 0) {
            continue;
        } else {
            sections[index].index = atoi(buffer);
            sections[index].name = strdup(buffer);
            index++;
        }
    }

    // Close file pointer and initialize rolling average of last 10 timestamps
    fclose(fp);
    int* timestamps = (int*) malloc(10 * sizeof(int));
    if (timestamps == NULL) {
        printf("Error: unable to allocate memory for timestamps\n");
        free(config_keys);
        free(config_values);
        free(sections);
        return 1;
    }
    int curr_index = 0;
    int prev_timestamps[10];
    for (int i = 0; i < 10; i++) {
        prev_timestamps[i] = 0;
    }
    while (fscanf(fp, "%s", buffer) != EOF) {
        if (strcmp(buffer, "{" || strcmp(buffer, "}") == 0) {
            continue;
        } else {
            int timestamp = atoi(buffer);
            timestamps[curr_index] = timestamp;
            curr_index++;
            if (curr_index >= 10) {
                for (int i = 0; i < 9; i++) {
                    prev_timestamps[i] = prev_timestamps[i + 1];
                }
                prev_timestamps[9] = timestamp;
            }
        }
    }

    // Free memory allocated for configuration settings and records
    free(config_keys);
    free(config_values);
    free(sections);
    free(timestamps);

    return 0;
}
