        if ((*batch)->records[i] == NULL) {
            free(*batch);
            return -3;
        }
        memset((*batch)->records[i], 0, sizeof(record_t));
        (*batch)->records[i]->key = key;
        (*batch)->records[i]->offset = offset;
        (*batch)->records[i]->value = value;
        (*batch)->records[i]->timestamp = timestamp;
    }

    // set the creation and completion timestamps for the batch
    (*batch)->creation_timestamp = get_timestamp();
    (*batch)->completion_timestamp = 0.0;

    return 0;
}

int deallocate_batch(batch_t* batch) {
    // check input parameter for validity
    if (batch == NULL) {
        return -1;
    }

    // release memory for the batch structure and its records
    int total_size = sizeof(batch_t) + batch->num_records * sizeof(record_t);
    free(batch);

    return 0;
}

int add_record_to_batch(batch_t* batch, record_t* record) {
    // check input parameters for validity and consistency
    if (batch == NULL || record == NULL || batch->num_records >= MAX_RECORDS_PER_BATCH) {
        return -1;
    }

    // allocate memory for the new record
    int total_size = sizeof(record_t);
    record = (record_t*)malloc(total_size);
    if (record == NULL) {
        return -2;
    }
    memset(record, 0, total_size);

    // add the new record to the batch and update its metadata
    batch->records[batch->num_records++] = record;
    batch->total_size += sizeof(record_t);

    return 0;
}

int remove_record_from_batch(batch_t* batch, int index) {
    // check input parameters for validity and consistency
    if (batch == NULL || index < 0 || index >= batch->num_records) {
        return -1;
    }

    // remove the record from the batch and update its metadata
    free(batch->records[index]);
    batch->total_size -= sizeof(record_t);
    batch->num_records--;

    return 0;
}

double get_timestamp() {
    // return the current time in milliseconds since the epoch
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (double)ts.tv_sec * 1000 + (double)ts.tv_nsec / 1000000;
