Record* allocate_records(int numRecords) {
    Record *records = (Record*) malloc(numRecords * sizeof(Record));
    if (records == NULL) {
        perror("Error allocating memory for records");
        return NULL;
    }
    // Initialize the values to zero
    memset(records, 0, numRecords * sizeof(Record));
    return records;
}

