    }
    // Generate a random value between the minimum and maximum values
    record->value = rand() % (maxValue - minValue + 1) + minValue;
}

// Function to free all allocated memory once the operation is complete
void free_memory(long *offsets, int *keys, Record *records) {
    if (offsets != NULL) {
        free(offsets);
    }
    if (keys != NULL) {
        free(keys);
    }
    if (records != NULL) {
        free(records);
    }
}

