void resize_records(Record **records, int numRecords) {
    Record *newRecords = realloc(*records, numRecords * sizeof(Record));
    if (newRecords == NULL) {
        perror("Error resizing records");
        return;
    }
    // Update the pointer to the new array
    *records = newRecords;
}

// Function to check for memory leaks and handle errors gracefully
void error_check(long *offsets, int *keys, Record *records) {
    if (offsets == NULL || keys == NULL || records == NULL) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        free_memory(offsets, keys, records);
        return;
    }
}

// Function to allocate memory for multiple arrays and structures under various constraints
void manage_memory(int numOffsets, int numKeys, int numRecords, int minValue, int maxValue) {
    // Allocate memory for the offsets array
    long *offsets = allocate_offsets(numOffsets);
    if (offsets == NULL) {
        error_check(offsets, NULL, NULL);
        return;
    }

    // Initialize the offsets to zero
    memset(offsets, 0, numOffsets * sizeof(long));

    // Allocate memory for the keys array
    int *keys = allocate_keys(numKeys);
    if (keys == NULL) {
        error_check(offsets, keys, NULL);
        return;
    }

    // Initialize the keys to zero
    memset(keys, 0, numKeys * sizeof(int));

    // Allocate memory for the records array
    Record *records = allocate_records(numRecords);
    if (records == NULL) {
        error_check(offsets, keys, records);
        return;
    }

    // Initialize the values of each record to a random integer within the specified range
    for (int i = 0; i < numRecords; i++) {
        init_record(&records[i], minValue, maxValue);
    }

    // Free all allocated memory once the operation is complete
    free_memory(offsets, keys, records);
}
