["```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/time.h>
#include <unistd.h>
#include <sys/resource.h>
#include <assert.h>

// Custom memory pool implementation
struct MemoryPool {
    size_t capacity;
    void* base_address;
    void** free_list;
};

void initMemoryPool(struct MemoryPool* pool, size_t capacity) {
    pool->capacity = capacity;
    pool->base_address = malloc(pool->capacity);
    pool->free_list = (void**)pool->base_address;
}

void destroyMemoryPool(struct MemoryPool* pool) {
    free(pool->base_address);
}

void* allocFromMemoryPool(struct MemoryPool* pool, size_t size) {
    // Allocate memory from the free list or allocate a new block if necessary
    void** p = pool->free_list;
    if (p != NULL) {
        pool->free_list = *p;
        return p;
    } else {
        size_t offset = (size_t)(pool->base_address - (char*)NULL);
        void* new_block = malloc(size + offset);
        if (new_block == NULL) {
            // Memory allocation failed, return NULL
            return NULL;
        } else {
            size_t new_offset = (size_t)(new_block - (char*)NULL);
            void** new_p = (void**)((char*)new_block + new_offset);
            *new_p = pool->free_list;
            return new_p;
        }
    }
}

// Custom memory allocation function
void* myMalloc(size_t size, struct MemoryPool* pool) {
    // Check if the size is within the maximum allowed limit
    size_t max_size = pool->capacity - sizeof(struct MemoryPool);
    if (size > max_size) {
        return NULL;
    }

    // Allocate memory from the memory pool
    void* p = allocFromMemoryPool(pool, size);
    if (p == NULL) {
        return NULL;
    }

    // Initialize the allocated memory
    memset(p, 0, size);
    return p;
}

// Custom memory deallocation function
void myFree(void* p, struct MemoryPool* pool) {
    // Check if the pointer is within the memory pool's base address range
    size_t offset = (size_t)(pool->base_address - (char*)NULL);
    void** p_internal = (void**)((char*)p + offset);
    if (*p_internal >= pool->free_list && *p_internal <= (void**)pool->base_address) {
        // Free the memory back to the memory pool
        *p_internal = pool->free_list;
        pool->free_list = p_internal;
    } else {
        // Memory is outside of the pool's range, free it normally
        free(p);
    }
}

// Function to allocate memory for an array of offset values
void* allocOffsets(size_t numOffsets, size_t offsetSize) {
    // Check if the requested number of offsets is within the maximum allowed limit
