    // Implement optimistic locking to manage concurrent updates and handle conflicts gracefully
    if ($statement->rowCount() === 0) {
        sleep(1); // Backoff for a short period to allow other requests to complete
        $statement = $pdo->prepare($sql);
        $statement->execute([$contactDetails, $preferences, $subscriptionStatus, $sessionId]);
    }

    // Support rollback mechanisms for partial updates due to database constraints or failures
    if ($statement->rowCount() === 0) {
        $rollbackState = [];
