        sleep(1); // Backoff for a short period to allow other requests to complete
        $statement = $pdo->prepare($sql);
        $statement->execute([$sessionId]);
        if ($statement->rowCount() === 0) {
            return "Rollback failed";
        }
        $statement->bindParam(':contact_details', $rollbackState['contactDetails'], PDO::PARAM_STR);
        $statement->bindParam(':preferences', $rollbackState['preferences'], PDO::PARAM_STR);
        $statement->bindParam(':subscription_status', $rollbackState['subscriptionStatus'], PDO::PARAM_INT);
        $statement->execute();
    }

    // Handle transient issues gracefully by retrying operations up to three times before failing permanently
    if ($statement->rowCount() === 0) {
        for ($i = 1; $i <= 3; $i++) {
            sleep(pow($i, 2)); // Backoff with increasing delays between retries
            $statement = $pdo->prepare($sql);
            $statement->execute([$contactDetails, $preferences, $subscriptionStatus, $sessionId]);
            if ($statement->rowCount() !== 0) {
                break;
            }
        }
    }

    // Ensure that all updates are atomic to maintain data consistency across a distributed system
    if ($statement->rowCount() === 0) {
