    *(metadata + metadata_length) = '\0';

    // Flush the metadata string periodically to a persistent storage system to prevent data loss during frequent updates
    size_t flush_interval = 500; // in milliseconds
    long last_flush = timestamp - (timestamp % flush_interval);
    while (1) {
        if (timestamp - last_flush >= flush_interval) {
            // Write the metadata string to a file
            FILE* fp = fopen("metadata.txt", "w");
            if (fp == NULL) {
                perror("fopen");
                exit(1);
            }
            fprintf(fp, "%s\n", metadata);
            fclose(fp);

            // Update the last_flush timestamp
            last_flush += flush_interval;
        }

        // Sleep for a short time to reduce CPU overhead
        struct timespec sleeptime = {0, 100000};
        nanosleep(&sleeptime, NULL);
    }
}

int main() {
    size_t num_records = 10;
    int min_key = 0;
    int max_key = 100;
    size_t metadata_length = 20;

    record_t* records;
    init_records(&records, num_records, min_key, max_key, metadata_length);

    // Use the records as needed...

    free(records);
    return 0;
}
