    for (int i = 0; i < num_records; i++) {
        records[i].identifier = rand() % num_keys;
        records[i].temperature.value = ((float)rand() / RAND_MAX) * 25 + 10;
    }

    // Return a pointer to the first element of the records array
    return records;
}

// Define a function to validate that all keys in the records array are valid indices in the keys array
bool validateRecords(Record *records, int num_records, int *keys) {
    // Loop through each record and check that its identifier is a valid index in the keys array
    for (int i = 0; i < num_records; i++) {
        if (!keys[records[i].identifier]) {
            printf("Invalid key at index %d: %d\n", i, records[i].identifier);
            return false;
        }
    }

    // If all keys are valid, return true
    return true;
}

