#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <limits.h>
#include <errno.h>

#define MAX_OFFSETS 1000
#define MAX_KEYS 1000
#define MAX_RECORDS 1000
#define RANDOM_NUMBER_MAX 1000

// Structs for data storage
typedef struct {
    long offset;
} offset_t;

typedef struct {
    int key;
} key_t;

typedef struct {
    int record;
} record_t;

// Function to read file and initialize structures
int init_structs(const char* filename, offset_t** offsets, key_t** keys, record_t** records) {
    // Variables to store file data
    long* offsets_data = NULL;
    int* keys_data = NULL;
    int* records_data = NULL;

    // Initialize pointers to NULL
    *offsets = NULL;
    *keys = NULL;
    *records = NULL;

    // Open file and check for errors
    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        perror("Error opening file");
        return -1;
    }

    // Read data from file into arrays
    size_t offset_count = 0;
    size_t key_count = 0;
    size_t record_count = 0;

    while (fscanf(file, "%ld", &offsets_data[offset_count]) != EOF) {
        offset_count++;
    }

    for (size_t i = 0; i < offset_count; i++) {
        keys_data[key_count++] = offsets_data[i];
    }

    for (size_t i = 0; i < key_count; i++) {
        records_data[record_count++] = keys_data[i];
    }

    // Check for malformed data and handle errors gracefully
    if (offset_count > MAX_OFFSETS || key_count > MAX_KEYS || record_count > MAX_RECORDS) {
        fprintf(stderr, "Error: file contains too many entries\n");
        return -1;
    }

    // Dynamically allocate memory for structures
    *offsets = (offset_t*)malloc(sizeof(offset_t) * offset_count);
    if (*offsets == NULL) {
        perror("Error allocating memory for offsets");
        return -1;
    }

    *keys = (key_t*)malloc(sizeof(key_t) * key_count);
    if (*keys == NULL) {
        perror("Error allocating memory for keys");
        free(*offsets);
        *offsets = NULL;
        return -1;
    }

    *records = (record_t*)malloc(sizeof(record_t) * record_count);
    if (*records == NULL) {
        perror("Error allocating memory for records");
        free(*offsets);
        free(*keys);
        *keys = NULL;
        return -1;
    }

    // Initialize structures with data from arrays
    for (size_t i = 0; i < offset_count; i++) {
        (*offsets)[i].offset = offsets_data[i];
    }

    for (size_t i = 0; i < key_count; i++) {
        (*keys)[i].key = keys_data[i];
    }

    for (size_t i = 0; i < record_count; i++) {
        (*records)[i].record = records_data[i];
    }

    // Clean up temporary data structures
    free(offsets_data);
    offsets_data = NULL;

    free(keys_data);
    keys_data = NULL;

    free(records_data);
    records_data = NULL;

    return 0;
}

// Function to generate random numbers within a specified range
int generate_random_numbers(int min, int max) {
    // Use linear congruential generator for repeatability
    srand((unsigned int)time(NULL));

    int rand_num = (min + rand() % (max - min + 1));

    return rand_num;
}

// Function to initialize a single record structure with random data
record_t* init_record(int min, int max) {
    // Allocate memory for the structure
    record_t* record = (record_t*)malloc(sizeof(record_t));

    if (record == NULL) {
        perror("Error allocating memory for record");
        return NULL;
    }

    // Initialize structure with random data within specified range
    record->record = generate_random_numbers(min, max);

    return record;
}
