// Define the graph data structure using Boost library
using namespace boost;
typedef adjacency_list<vecS, vecS, undirectedS, no_property, property<edge_weight_t, int>> Graph;

// Define the dynamic range manager class
class DynamicRangeManager {
private:
    // Minimum and maximum values for integers and floats
    int minInt, maxInt;
    float minFloat, maxFloat;

    // Set of ranges for integers and floats
    std::set<std::pair<int, int>> intRanges;
    std::set<std::pair<float, float>> floatRanges;

public:
    DynamicRangeManager(int minInt = INT_MIN, int maxInt = INT_MAX, float minFloat = -FLT_MAX, float maxFloat = FLT_MAX) {
        // Set the minimum and maximum values for integers and floats
        this->minInt = minInt;
        this->maxInt = maxInt;
        this->minFloat = minFloat;
        this->maxFloat = maxFloat;
    }

    // Add a new range with specified boundaries, checking for overlaps
    void addRange(int min, int max) {
        if (min >= max || min < minInt || max > maxInt) {
            throw std::invalid_argument("Invalid range");
        }
        intRanges.insert({min, max});
    }

    // Remove a specific range by index or identifier
    void removeRange(int index) {
        if (index >= 0 && index < intRanges.size()) {
            auto it = intRanges.begin();
            std::advance(it, index);
            intRanges.erase(it);
        } else {
            throw std::invalid_argument("Invalid range index");
        }
    }

    // Update existing range boundaries while maintaining non-overlapping constraints
    void updateRange(int min, int max) {
        if (min >= max || min < minInt || max > maxInt) {
            throw std::invalid_argument("Invalid range");
        }
        for (auto it = intRanges.begin(); it != intRanges.end(); ++it) {
            if (it->first == min && it->second == max) {
                return;
            }
        }
        intRanges.erase({min, max});
        intRanges.insert({min, max});
    }

    // Generate random integer values within each range
    int generateRandomInt() {
        boost::random::uniform_int<std::set<std::pair<int, int>>::iterator> dist(intRanges.begin(), intRanges.end());
        return dist(*engine);
    }

    // Generate random float values within each range
    float generateRandomFloat() {
        boost::random::uniform_real<std::set<std::pair<float, float>>::iterator> dist(floatRanges.begin(), floatRanges.end());
        return dist(*engine);
    }

    // Display all defined ranges in a human-readable format
    std::string toString() {
        std::string str;
        for (auto it = intRanges.begin(); it != intRanges.end(); ++it) {
            str += "[" + std::to_string(it->first) + "," + std::to_string(it->second) + "] ";
        }
        return str;
    }
};
```

