ConnectionPool* connectionPools[MAX_CONNECTIONS];
Task tasks[MAX_TASKS];
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
semaphore_t semaphore;

int taskAndConnectionManager(char* configFile) {
    // Load configuration file and validate inputs
    if (validateConfigFile(configFile) == -1) {
        return -1;
    }

    // Initialize connection pools and task lists
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        connectionPools[i] = malloc(sizeof(ConnectionPool));
        memset(connectionPools[i], 0, sizeof(ConnectionPool));
    }
    for (int i = 0; i < MAX_TASKS; i++) {
        tasks[i].name = NULL;
        tasks[i].priority = -1;
    }

    // Start connection pooling and task processing threads
    pthread_t threadPool[MAX_CONNECTIONS];
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        if (pthread_create(&threadPool[i], NULL, connectionPoolThread, (void*)i) != 0) {
            fprintf(stderr, "Error creating connection pool thread\n");
            return -1;
        }
    }
    for (int i = 0; i < MAX_TASKS; i++) {
        if (pthread_create(&threadPool[i + MAX_CONNECTIONS], NULL, taskThread, (void*)i) != 0) {
            fprintf(stderr, "Error creating task thread\n");
            return -1;
        }
    }

    // Wait for threads to finish and clean up resources
    for (int i = 0; i < MAX_CONNECTIONS + MAX_TASKS; i++) {
        if (pthread_join(threadPool[i], NULL) != 0) {
            fprintf(stderr, "Error joining thread %d\n", i);
            return -1;
        }
    }
    free(connectionPools);
    free(tasks);
    return 0;
}

void* connectionPoolThread(void* threadId) {
    int poolIndex = (int)threadId;
    ConnectionPool* pool = connectionPools[poolIndex];
    while (1) {
        // Wait for a semaphore signal
        if (sem_wait(&semaphore) == -1) {
            fprintf(stderr, "Error waiting for semaphore\n");
            return NULL;
        }

        // Process tasks in the task list
        pthread_mutex_lock(&mutex);
        for (int i = 0; i < MAX_TASKS; i++) {
            Task* task = &tasks[i];
            if (task->name != NULL && strcmp(task->name, pool->queryString) == 0) {
                // Execute query and commit transaction
                if (executeQuery(poolIndex, task->priority) == -1) {
                    fprintf(stderr, "Error executing query\n");
                    return NULL;
                }
                if (commitTransaction(poolIndex) == -1) {
                    fprintf(stderr, "Error committing transaction\n");
                    return NULL;
                }
            }
        }
        pthread_mutex_unlock(&mutex);
    }
}

void* taskThread(void* threadId) {
    int taskIndex = (int)threadId;
    Task* task = &tasks[taskIndex];
    while (1) {
        // Wait for a semaphore signal
        if (sem_wait(&semaphore) == -1) {
            fprintf(stderr, "Error waiting for semaphore\n");
            return NULL;
        }

        // Add task to the task list and update connection pool metadata
        pthread_mutex_lock(&mutex);
        if (task->name == NULL) {
            // Allocate memory for task name, priority, and start/end times
            task->name = malloc(sizeof(char) * QUERY_STRING_LENGTH);
            task->priority = 0;
            gettimeofday(&task->start, NULL);
        } else {
            // Increment transaction ID in connection pool metadata
            connectionPools[poolIndex].metadata.transactionId++;
        }
        pthread_mutex_unlock(&mutex);
    }
}

