// Define the record structure
typedef struct {
    long value;
    int *key;
} record_t;

// Define the maximum memory allocation size in bytes
#define MAX_MEMORY_SIZE (1024*1024*10) // 10 MB

// Function to dynamically allocate memory for three arrays: offsets, keys, and records
void *allocate_memory(int num_records, int num_keys, long max_offset) {
    // Calculate the total size of memory required
    long total_size = sizeof(long) * num_records + sizeof(int) * num_keys + sizeof(record_t) * num_records;

    // Check if the total size exceeds the maximum allowed
    if (total_size > MAX_MEMORY_SIZE) {
        fprintf(stderr, "Error: Memory allocation exceeded maximum size\n");
        return NULL;
    }

    // Allocate memory for the arrays
    long *offsets = malloc(sizeof(long) * num_records);
    int *keys = malloc(sizeof(int) * num_keys);
    record_t *records = malloc(sizeof(record_t) * num_records);

    // Initialize the memory allocation pointers
    long offset_ptr = (long)offsets;
    int key_ptr = (int)keys;
    record_t *record_ptr = records;

    // Load data from the external CSV file
    FILE *file = fopen("input.csv", "r");
    if (!file) {
        fprintf(stderr, "Error: Unable to open input file\n");
        return NULL;
    }

    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        // Parse the line and extract the key and offset values
        int key = atoi(strtok(line, ","));
        long offset = atol(strtok(NULL, ",\n"));

        // Check if the key is valid
        if (key < 0 || key >= num_keys) {
            fprintf(stderr, "Error: Key %d is out of range\n", key);
            return NULL;
        }

        // Update the offset and key pointers
        offsets[offset_ptr++] = offset;
        keys[key_ptr++] = key;

        // Initialize the record pointer
        record_t *record = &records[record_ptr++];
        record->value = 0;
        record->key = &keys[key];
    }

    fclose(file);

    return records;
}

// Function to release memory allocated by allocate_memory()
void free_memory(void *records) {
    // Calculate the number of records
    int num_records = sizeof(record_t) / sizeof(long);

    // Release memory for the arrays
    long *offsets = (long *)records;
    int *keys = (int *)(offsets + num_records);
    record_t *records = (record_t *)(keys + num_records);

    free(offsets);
    free(keys);
    free(records);
}
