char *truncateString(const char *str, size_t limit) {
    if (str == NULL || limit <= 0) {
        return NULL;
    }

    // Calculate the length of the input string
    size_t len = strlen(str);

    // Check if the input string exceeds the limit
    if (len > limit) {
        char *new_str = malloc((limit + 1) * sizeof(char));
        if (new_str == NULL) {
            fprintf(stderr, "Failed to allocate memory for truncated string\n");
            exit(EXIT_FAILURE);
        }

        // Copy the first `limit` characters of the input string to the new string
        strncpy(new_str, str, limit);

        // Append a slash to the end of the new string if necessary
        if (len > limit) {
            new_str[limit] = '/';
        } else {
            new_str[limit] = '\0';
        }

        return new_str;
    } else {
        // Return the input string if it does not exceed the limit
        char *new_str = malloc((len + 1) * sizeof(char));
        if (new_str == NULL) {
            fprintf(stderr, "Failed to allocate memory for truncated string\n");
            exit(EXIT_FAILURE);
        }

        strcpy(new_str, str);
        return new_str;
    }
}
