// Function to add a new node to the list
void addNode(Node** head, const char* str, int weight) {
    // Allocate memory for the new node
    Node* new_node = malloc(sizeof(Node));
    if (new_node == NULL) {
        printf("Error: Out of memory\n");
        return;
