  double metricValue;
};

// Function to process and aggregate batch data
int batchProcessAndAggregateData(char* filePath, char* networkStreamUrl, char* distributedMessageQueueUrl) {
  // Initialize variables for buffer size and number of records processed
  int bufferSize = 1024;
  int numRecordsProcessed = 0;

  // Allocate memory for the internal buffer
  struct batchRecord* buffer = (struct batchRecord*) malloc(bufferSize * sizeof(struct batchRecord));
  if (buffer == NULL) {
    printf("Error: Failed to allocate memory for internal buffer.\n");
    return -1;
  }

  // Initialize variables for file, network stream, and distributed message queue connections
  FILE* file = fopen(filePath, "r");
  if (file == NULL) {
    printf("Error: Failed to open file %s.\n", filePath);
    return -1;
  }
  int netStreamFd = networkStreamUrl ? open(networkStreamUrl, O_RDONLY) : -1;
  if (netStreamFd == -1) {
    printf("Error: Failed to connect to network stream %s.\n", networkStreamUrl);
    return -1;
  }
  int dmqFd = distributedMessageQueueUrl ? open(distributedMessageQueueUrl, O_RDONLY) : -1;
  if (dmqFd == -1) {
    printf("Error: Failed to connect to distributed message queue %s.\n", distributedMessageQueueUrl);
    return -1;
  }

  // Loop until all data has been processed and the buffer is empty
  while (1) {
    // Check if any data is available on the file, network stream, or distributed message queue
    int dataAvailable = (file && feof(file)) || netStreamFd != -1 || dmqFd != -1;

    // If no data is available, break from the loop
    if (!dataAvailable) {
      break;
    }

    // Read data from the file or network stream into the buffer
    for (int i = 0; i < bufferSize && !feof(file); i++) {
      buffer[i].batchId = fgetc(file);
      buffer[i].timestamp = time(NULL);
      fscanf(file, "%lf", &buffer[i].metricValue);
    }
    if (netStreamFd != -1) {
      read(netStreamFd, buffer + i, sizeof(struct batchRecord));
    }
    if (dmqFd != -1) {
      // Read data from the distributed message queue into the buffer
      char* msg = dmq_receive();
      if (msg) {
        struct batchRecord* record = (struct batchRecord*) malloc(sizeof(struct batchRecord));
        memcpy(record, msg, sizeof(struct batchRecord));
        free(msg);
        buffer[i] = *record;
      }
    }

    // Process and aggregate the data in the buffer
    for (int i = 0; i < bufferSize; i++) {
      struct batchRecord* record = &buffer[i];
      numRecordsProcessed++;

      // Handle memory allocation failures gracefully by returning an appropriate error code and cleaning up any allocated resources
      if (!record) {
        printf("Error: Failed to allocate memory for record.\n");
        return -1;
      }

      // Handle external data sources, ensure seamless integration by implementing robust error handling and retry logic for failed connections
      if (file && feof(file)) {
        fclose(file);
        file = NULL;
      } else if (netStreamFd == -1) {
        close(netStreamFd);
        netStreamFd = open(networkStreamUrl, O_RDONLY);
      } else if (dmqFd == -1) {
        dmq_disconnect();
        dmqFd = open(distributedMessageQueueUrl, O_RDONLY);
      }
    }
  }

  // Generate an aggregated report containing the average, maximum, and minimum metric values per batch, along with the total number of records processed
  printf("Aggregated Report: \n");
  for (int i = 0; i < numRecordsProcessed; i++) {
    struct batchRecord* record = &buffer[i];
    double average = record->metricValue / numRecordsProcessed;
    printf("Batch %d: Average=%.2f, Maximum=%.2f, Minimum=%.2f\n", record->batchId, average, record->metricValue, record->metricValue);
  }
  return 0;
}
