pthread_cond_t fileCond = PTHREAD_COND_INITIALIZER;

// Function to read a file and store its contents in a buffer
int readFile(char* filePath, size_t bufferSize, char** buffer) {
  // Open the file for reading
  FILE* fp = fopen(filePath, "r");
  if (fp == NULL) {
    perror("Error opening file for reading");
    return -1;
  }

  // Allocate memory for the buffer
  *buffer = malloc(bufferSize);
  if (*buffer == NULL) {
    fclose(fp);
    perror("Error allocating memory for buffer");
    return -1;
  }

  // Read the file contents into the buffer
  size_t bytesRead = fread(*buffer, sizeof(char), bufferSize, fp);
  if (bytesRead == 0) {
    free(*buffer);
    *buffer = NULL;
    fclose(fp);
    perror("Error reading file contents");
    return -1;
  }

  // Close the file
  fclose(fp);

  return bytesRead;
}

// Function to write a buffer to a file
int writeFile(char* filePath, size_t bufferSize, char* buffer) {
  // Open the file for writing
  FILE* fp = fopen(filePath, "w");
  if (fp == NULL) {
    perror("Error opening file for writing");
    return -1;
  }

  // Write the buffer to the file
  size_t bytesWritten = fwrite(buffer, sizeof(char), bufferSize, fp);
  if (bytesWritten == 0) {
    fclose(fp);
    perror("Error writing buffer to file");
    return -1;
  }

  // Close the file
  fclose(fp);

  return bytesWritten;
}

// Function to append a buffer to a file
int appendFile(char* filePath, size_t bufferSize, char* buffer) {
  // Open the file for appending
  FILE* fp = fopen(filePath, "a");
  if (fp == NULL) {
    perror("Error opening file for appending");
    return -1;
  }

  // Write the buffer to the file
  size_t bytesWritten = fwrite(buffer, sizeof(char), bufferSize, fp);
  if (bytesWritten == 0) {
    fclose(fp);
    perror("Error appending buffer to file");
    return -1;
  }

  // Close the file
  fclose(fp);

  return bytesWritten;
}

// Function to truncate a file to a specified length
int truncateFile(char* filePath, size_t length) {
  // Open the file for truncating
  FILE* fp = fopen(filePath, "w");
  if (fp == NULL) {
    perror("Error opening file for truncating");
    return -1;
  }

  // Truncate the file to the specified length
  int status = ftruncate(fileno(fp), length);
  if (status != 0) {
    fclose(fp);
    perror("Error truncating file");
    return -1;
  }

  // Close the file
  fclose(fp);

  return status;
}

// Function to handle a single file operation
int handleFileOperation(struct Options* options, char* filePath) {
  pthread_mutex_lock(&fileMutex);

  // Read the file contents into a buffer
  size_t readBufferSize = options->readBufferSize;
  char* readBuffer = NULL;
  int bytesRead = readFile(filePath, readBufferSize, &readBuffer);
  if (bytesRead < 0) {
    pthread_mutex_unlock(&fileMutex);
    return -1;
  }

  // Write the buffer to a file
  size_t writeBufferSize = options->writeBufferSize;
  char* writeBuffer = NULL;
  int bytesWritten = writeFile(filePath, writeBufferSize, readBuffer);
  if (bytesWritten < 0) {
    free(readBuffer);
    pthread_mutex_unlock(&fileMutex);
    return -1;
  }

  // Append the buffer to a file
  size_t appendBufferSize = options->appendBufferSize;
  char* appendBuffer = NULL;
  int bytesAppended = appendFile(filePath, appendBufferSize, readBuffer);
  if (bytesAppended < 0) {
    free(readBuffer);
    free(writeBuffer);
    pthread_mutex_unlock(&fileMutex);
    return -1;
  }

  // Truncate the file to a specified length
  size_t truncateLength = options->truncateLength;
  int status = truncateFile(filePath, truncateLength);
  if (status < 0) {
    free(readBuffer);
    free(writeBuffer);
    free(appendBuffer);
    pthread_mutex_unlock(&fileMutex);
    return -1;
  }

  // Log the operation result and release resources
  LogEntry logEntry = {status, time(NULL)};
  printf("Operation on file %s completed with status %d\n", filePath, status);
  free(readBuffer);
  free(writeBuffer);
  free(appendBuffer);
  pthread_mutex_unlock(&fileMutex);

  return status;
}

// Function to handle multiple file operations in parallel
void* handleFileOperations(void* arg) {
  struct Options* options = (struct Options*)arg;

  // Iterate over the list of files and perform the operation on each one
  int i;
  for (i = 0; i < options->fileCount; i++) {
    char* filePath = options->files[i];
    handleFileOperation(options, filePath);
  }

  return NULL;
}

int main(int argc, char** argv) {
  struct Options options;
  parseOptions(&options, argc, argv);

  // Perform the operation on all files in parallel
  pthread_t thread[options.fileCount];
  int i;
  for (i = 0; i < options.fileCount; i++) {
    char* filePath = options.files[i];
    pthread_create(&thread[i], NULL, handleFileOperations, &options);
  }

  // Wait for all threads to finish
  for (i = 0; i < options.fileCount; i++) {
    pthread_join(thread[i], NULL);
  }

  return 0;
}

// Parse command line options and populate the Options struct with their values
void parseOptions(struct Options* options, int argc, char** argv) {
  // Initialize all options to their default values
  options->readBufferSize = 4096;
  options->writeBufferSize = 4096;
  options->appendBufferSize = 4096;
  options->truncateLength = -1;
  options->fileCount = 0;

  int i;
  for (i = 0; i < argc; i++) {
    if (strcmp(argv[i], "-read") == 0) {
      options->readBufferSize = atoi(argv[++i]);
    } else if (strcmp(argv[i], "-write") == 0) {
      options->writeBufferSize = atoi(argv[++i]);
    } else if (strcmp(argv[i], "-append") == 0) {
      options->appendBufferSize = atoi(argv[++i]);
    } else if (strcmp(argv[i], "-truncate") == 0) {
      options->truncateLength = atoi(argv[++i]);
    } else if (argv[i][0] != '-') {
      // Not a flag, must be a file path
      options->files[options->fileCount++] = argv[i];
    }
  }
}
