// Custom memory allocator with support for both aligned and unaligned memory allocation
void* my_malloc(size_t size) {
    void* ptr = NULL;
    if (posix_memalign(&ptr, 16, size) != 0) {
        return NULL;
    }
    return ptr;
}

void my_free(void* ptr) {
    free(ptr);
}

// Custom logging system for recording all operations and errors
#define LOG(msg) printf("[%s:%d] %s\n", __FILE__, __LINE__, msg)

typedef struct {
    int key;
    double timestamp;
    char identifier[1024];
} Record;

int processAndFindMax(const int offset_count, const int* offsets, const int key_count, const int* keys) {
    // Allocate memory for the arrays of long and int values
    long* offset_values = (long*)my_malloc(offset_count * sizeof(long));
    if (!offset_values) {
        LOG("Failed to allocate memory for offset values");
        return -1;
    }

    int* key_values = (int*)my_malloc(key_count * sizeof(int));
    if (!key_values) {
        my_free(offset_values);
        LOG("Failed to allocate memory for key values");
        return -1;
    }

    // Initialize the arrays of long and int values
    for (int i = 0; i < offset_count; i++) {
        offset_values[i] = offsets[i];
    }
    for (int i = 0; i < key_count; i++) {
        key_values[i] = keys[i];
    }

    // Allocate memory for the array of Record structures
    int max_record_count = offset_count + key_count;
    Record* records = (Record*)my_malloc(max_record_count * sizeof(Record));
    if (!records) {
        my_free(offset_values);
        my_free(key_values);
        LOG("Failed to allocate memory for record structures");
        return -1;
    }

    // Populate the Record structures with random values, timestamps, and identifiers
    srand((unsigned int)time(NULL));
    for (int i = 0; i < max_record_count; i++) {
        records[i].key = rand() % offset_values[i] + key_values[i];
        records[i].timestamp = (double)time(NULL);
        strcpy(records[i].identifier, "Unique Identifier");
    }

    // Find the maximum value in the Record structures
    int max_value = -1;
    for (int i = 0; i < max_record_count; i++) {
        if (records[i].key > max_value) {
            max_value = records[i].key;
        }
    }

    // Clean up allocated resources and return the maximum value
    my_free(offset_values);
    my_free(key_values);
    my_free(records);
    return max_value;
}

int main() {
    const int offset_count = 5;
    const int key_count = 10;
    const int* offsets = (const int[]){1, 2, 3, 4, 5};
