    // Call the processAndFindMax function and print the result
    int max_value = processAndFindMax(offset_count, offsets, key_count, keys);
    if (max_value < 0) {
        LOG("Error processing data");
    } else {
        printf("The maximum value is %d\n", max_value);
    }

