  // Initialize the arrays for 'long' offsets, 'int' keys, and 'Record' structures
  long *offsets = (long *)aligned_alloc(sizeof(long), sizeof(long) * 10);
  int *keys = (int *)aligned_alloc(sizeof(int), sizeof(int) * 10);
