int processAndAggregateData(char *filename, int num_files) {
    // Declare variables for memory allocation
    struct data_record *data = NULL;
    size_t capacity = 0;
    size_t count = 0;

    // Open the files and check for errors
    int fd[num_files];
    for (int i = 0; i < num_files; i++) {
        if ((fd[i] = open(filename[i], O_RDONLY)) == -1) {
            perror("open");
            return errno;
        }
    }

    // Read from the files and process the data
    for (int i = 0; i < num_files; i++) {
        struct data_record record;
        if (read(fd[i], &record, sizeof(struct data_record)) != -1) {
            // Check for out-of-range values and malformed records
            if (record.sensor_reading < 0 || record.sensor_reading > 100) {
                continue;
            }

            // Allocate memory for the data array, if needed
            if (count >= capacity) {
                capacity += 100;
                data = realloc(data, sizeof(struct data_record) * capacity);
                if (data == NULL) {
                    perror("realloc");
                    return errno;
                }
            }

            // Add the record to the array
            data[count] = record;
            count++;
        } else {
            // Handle errors gracefully
            perror("read");
            return errno;
        }
    }

    // Close the files and free memory
    for (int i = 0; i < num_files; i++) {
        if (close(fd[i]) == -1) {
            perror("close");
            return errno;
        }
    }
    free(data);

    // Calculate the average and maximum timestamp
    float sum = 0;
    unsigned long max_timestamp = 0;
    for (int i = 0; i < count; i++) {
        sum += data[i].sensor_reading;
        if (data[i].timestamp > max_timestamp) {
            max_timestamp = data[i].timestamp;
        }
    }
    float average = sum / count;

    // Print the results and return success
    printf("Average: %.2f\n", average);
    printf("Maximum timestamp: %lu\n", max_timestamp);
    return 0;
}
