#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <limits.h>

// Structure to store records
typedef struct {
    int key;
} Record;

// Function to allocate memory for arrays and initialize with values
int allocateMemory(int n) {
    // Check if input is within range
    if (n < 1 || n > 10000) {
        return -1;
    }

    // Allocate memory for two separate arrays: one for long offsets and another for int keys
    Record* records = malloc(sizeof(Record) * n);
    if (records == NULL) {
        return -1;
    }

    // Initialize both arrays with the specified size
    memset(records, 0, sizeof(Record) * n);

    // Return success
    return 0;
}

// Function to fill each record in the array with a unique value derived from its index using a hash function
int fillRecords(Record* records, int n) {
    // Check if input is within range
    if (n < 1 || n > 10000) {
        return -1;
    }

    // Initialize a hash function to generate unique values
    unsigned long hash(unsigned long i) {
        return i * 37 % 1000000;
    }

    // Fill each record with a unique value derived from its index
    for (int i = 0; i < n; i++) {
        records[i].key = hash(i);
    }

    // Return success
    return 0;
}

// Function to sort the array of records based on the hashed values using a stable sorting algorithm
int sortRecords(Record* records, int n) {
    // Check if input is within range
    if (n < 1 || n > 10000) {
        return -1;
    }

    // Use quicksort as the sorting algorithm to avoid performance issues with large datasets
    void quickSort(Record* records, int left, int right) {
        if (left >= right) {
            return;
        }

        int pivot = partition(records, left, right);
        quickSort(records, left, pivot - 1);
        quickSort(records, pivot + 1, right);
    }

    // Partition the array around a random pivot element
    int partition(Record* records, int left, int right) {
        srand(time(NULL));
        int pivotIndex = rand() % (right - left + 1) + left;
        Record pivot = records[pivotIndex];
        swap(&records[left], &records[pivotIndex]);

        int i = left + 1, j = right;
        while (i <= j) {
            while (i <= j && hash(records[i].key) <= hash(pivot.key)) {
                i++;
            }
            while (j >= left && hash(records[j].key) > hash(pivot.key)) {
                j--;
            }
            if (i < j) {
                swap(&records[i], &records[j]);
            }
        }
        swap(&records[left], &records[j]);
        return j;
    }

    // Swap two elements of the array
    void swap(Record* a, Record* b) {
        Record temp = *a;
        *a = *b;
        *b = temp;
    }

    // Sort the array using quicksort
    quickSort(records, 0, n - 1);

    // Return success
    return 0;
}

// Function to return the sorted array of records and track the total memory usage in bytes
int getSortedRecords(Record* records, int n) {
    // Check if input is within range
    if (n < 1 || n > 10000) {
        return -1;
    }

    // Calculate the total memory usage in bytes
    size_t totalMemUsage = sizeof(Record) * n + sizeof(int) * n;

    // Return the sorted array and the total memory usage
    return records;
}

// Function to handle error conditions gracefully
void handleError(const char* message) {
    perror(message);
    exit(EXIT_FAILURE);
}']

