#include <stdlib.h>
#include <string.h>
#include <stdio.h>

// Define the record structure
typedef struct {
    int id;
    double val1, val2;
    enum {
        ENUM_A,
        ENUM_B,
        ENUM_C,
        NUM_ENUMS
    } enum_val;
    char *string;
} record_t;

// Define the function to initialize the records
int init_records(int num_records, char **strings) {
    // Check that the number of records is within bounds
    if (num_records > 10000 || num_records < 0) {
        fprintf(stderr, "Invalid number of records: %d\n", num_records);
        return -1;
    }

    // Allocate memory for the records and their associated components
    record_t *records = malloc(num_records * sizeof(record_t));
    if (!records) {
        fprintf(stderr, "Failed to allocate memory for records\n");
        return -1;
    }

    // Initialize the records
    int num_initialized = 0;
    for (int i = 0; i < num_records; i++) {
        record_t *record = &records[i];
        char *string = strings[i];

        // Check that the string is within bounds
        if (strlen(string) > 100 || strlen(string) == 0) {
            fprintf(stderr, "Invalid string length: %zu\n", strlen(string));
            continue;
        }

        // Allocate memory for the string and copy it
        record->string = malloc(strlen(string) + 1);
        if (!record->string) {
            fprintf(stderr, "Failed to allocate memory for string\n");
            continue;
        }
        strcpy(record->string, string);

        // Validate the enum value
        int enum_val = atoi(strings[i + 1]);
        if (enum_val < ENUM_A || enum_val > NUM_ENUMS) {
            fprintf(stderr, "Invalid enum value: %d\n", enum_val);
            continue;
        }
        record->enum_val = enum_val;

        // Initialize the other components of the record
        record->id = i + 1;
        record->val1 = atof(strings[i + 2]);
        record->val2 = atof(strings[i + 3]);

        // Increment the number of initialized records
        num_initialized++;
    }

    // Check if any records were successfully initialized
    if (num_initialized == 0) {
        fprintf(stderr, "No records were successfully initialized\n");
        free(records);
        return -1;
    }

    // Return the number of successfully initialized records
    return num_initialized;
}
