void handleFileProcessing(char *file_path, int access_mode) {
    // Allocate memory for file metadata structures
    struct file_metadata_list *file_list = (struct file_metadata_list *)malloc(sizeof(struct file_metadata_list));
    if (!file_list) {
        perror("handleFileProcessing: failed to allocate memory for file list");
        return;
