    file_meta->fd = fd;
    file_meta->sb.st_size = 0;
    pthread_rwlock_init(&file_meta->lock, NULL);
    file_list->files[file_list->count++] = file_meta;

    // Read the file contents and process them
    char buffer[BUFFER_SIZE];
    while (1) {
        int bytes_read = read(fd, buffer, BUFFER_SIZE);
        if (bytes_read == 0) {
            break;
        } else if (bytes_read < 0) {
            perror("handleFileProcessing: failed to read file");
            return;
