    // Close the file descriptor and free resources
    close(fd);
    for (size_t i = 0; i < file_list->count; i++) {
        struct file_metadata *file_meta = file_list->files[i];
        pthread_rwlock_destroy(&file_meta->lock);
        free(file_meta->path);
        free(file_meta);
    }
    free(file_list);
}

