// Define a function to generate a summary report
int generateLogSummary(const char* filePath, logSummary* summary) {
    // Open the log file for reading
    FILE* logFile = fopen(filePath, "r");
    if (!logFile) {
        return -1; // Error opening file
    }

    // Allocate memory for the array of log entries
    size_t numEntries = 0;
    logEntry* entries = NULL;
    while (fgets(line, MAX_LINE_LENGTH, logFile) != NULL) {
        // Skip blank lines and comments
        if (strlen(line) == 0 || line[0] == '#') {
            continue;
        }

        // Add a new entry to the array
        entries = realloc(entries, (numEntries + 1) * sizeof(*entries));
        if (!entries) {
            fclose(logFile);
            return -2; // Error allocating memory for entries
        }

        // Parse the log entry and store its information
        char* content = strdup(line);
        if (!content) {
            fclose(logFile);
            free(entries);
            return -3; // Error allocating memory for content
        }
        entries[numEntries].status = content[0];
        entries[numEntries].timestamp = strtoull(content + 1, NULL, 10);
        entries[numEntries].lineNumber = numLines + 1;
        numEntries++;
    }

    // Close the log file
    fclose(logFile);

    // Allocate memory for the summary information
    summary->content = (char*)malloc(sizeof(char) * (numEntries + 1));
    if (!summary->content) {
        free(entries);
        return -4; // Error allocating memory for content
    }
    summary->numLines = numEntries;
    summary->earliestTimestamp = entries[0].timestamp;
    summary->totalSize = 0;
    for (size_t i = 0; i < numEntries; i++) {
        summary->content[i] = entries[i].status;
        summary->totalSize += strlen(entries[i].content);
    }
    summary->content[numEntries] = '\0';

    // Free the memory for the log entries array
    free(entries);

    return 0; // Success
}
