// Structures for file metadata and buffers
typedef struct {
    time_t last_modified;
    size_t file_size;
    int error_code;
} fileMetadata;

typedef struct {
    char *buffer;
    size_t buffer_size;
    time_t last_accessed;
    int error_code;
} fileBuffer;

// Function to handle file operations
int handleFileOperations(const char *file_name, const char *operation) {
    // Initialize variables
    int file_ptr = 0;
    size_t buffer_size = 0;
    time_t last_modified = 0;
    int error_code = 0;

    // Open the file in a thread-safe manner
    if ((file_ptr = open(file_name, O_RDONLY)) == -1) {
        perror("Error opening file");
        return -1;
    }

    // Get the size of the file and allocate memory for it
    if (fstat(file_ptr, &buffer_size) == -1) {
        perror("Error getting file size");
        close(file_ptr);
        return -1;
    }
    char *buffer = malloc(buffer_size);
    if (!buffer) {
        perror("Error allocating memory for buffer");
        close(file_ptr);
        return -1;
    }

    // Read the file into the buffer in a thread-safe manner
    size_t bytes_read = read(file_ptr, buffer, buffer_size);
    if (bytes_read == -1) {
        perror("Error reading from file");
        free(buffer);
        close(file_ptr);
        return -1;
    }

    // Close the file and release resources
    close(file_ptr);

    // Handle the operation based on its type
    if (strcmp(operation, "read") == 0) {
        // Print the contents of the buffer
        printf("Reading from file...\n");
        for (size_t i = 0; i < bytes_read; i++) {
            putchar(buffer[i]);
        }
    } else if (strcmp(operation, "write") == 0) {
        // Write the contents of the buffer to a new file
        printf("Writing to file...\n");
        int new_file_ptr = open("new_file.txt", O_CREAT | O_WRONLY);
        if (new_file_ptr == -1) {
            perror("Error opening new file");
            free(buffer);
            return -1;
        }
        size_t bytes_written = write(new_file_ptr, buffer, bytes_read);
        if (bytes_written == -1) {
            perror("Error writing to file");
            close(new_file_ptr);
            free(buffer);
            return -1;
        }
        // Close the new file and release resources
        close(new_file_ptr);
    } else if (strcmp(operation, "append") == 0) {
        // Append the contents of the buffer to an existing file
        printf("Appending to file...\n");
        int append_file_ptr = open("existing_file.txt", O_CREAT | O_WRONLY);
        if (append_file_ptr == -1) {
            perror("Error opening append file");
            free(buffer);
            return -1;
        }
        size_t bytes_written = write(append_file_ptr, buffer, bytes_read);
        if (bytes_written == -1) {
            perror("Error appending to file");
            close(append_file_ptr);
            free(buffer);
            return -1;
        }
        // Close the append file and release resources
        close(append_file_ptr);
    } else {
        printf("Unsupported operation. Supported operations: read, write, append\n");
        free(buffer);
        return -1;
    }

    // Free the memory allocated for the buffer
    free(buffer);

    // Return success
    return 0;
}
```
