// Define a union-find data structure to manage disjoint pairs
typedef struct {
    int parent;
    int rank;
} node;

// Function to process strings read from standard input and generate a report
void processAndGenerateReport(char **content, int *lineNumbers, logEntry *logEntries, int *indices) {
    // Initialize variables for memory allocation and concurrency control
    int numLines = 0;
    char **lines = NULL;
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Allocate memory for the arrays
    lines = (char **)malloc(sizeof(char *) * numLines);
    lineNumbers = (int *)calloc(numLines, sizeof(int));
    logEntries = (logEntry *)calloc(numLines, sizeof(logEntry));
    indices = (int *)malloc(sizeof(int) * numLines * 2);

    // Initialize the union-find data structure
    node **nodes = (node **)malloc(sizeof(node *) * numLines);
    for (int i = 0; i < numLines; i++) {
        nodes[i] = (node *)malloc(sizeof(node));
        nodes[i]->parent = i;
        nodes[i]->rank = 0;
    }

    // Read lines from standard input and process them
    while ((lines[numLines] = fgets(stdin)) != NULL) {
        // Increment the number of lines
        numLines++;

        // Reallocate memory for the arrays
        lines = (char **)realloc(lines, sizeof(char *) * numLines);
        lineNumbers = (int *)realloc(lineNumbers, sizeof(int) * numLines);
        logEntries = (logEntry *)realloc(logEntries, sizeof(logEntry) * numLines);
        indices = (int *)realloc(indices, sizeof(int) * numLines * 2);

        // Parse the line and populate the corresponding arrays
        char *line = lines[numLines - 1];
        int len = strlen(line);
        if (len > 0 && line[len - 1] == '\n') {
            line[len - 1] = '\0';
        }
        lineNumbers[numLines - 1] = numLines;
        logEntries[numLines - 1].status = parseStatus(line);
        logEntries[numLines - 1].timestamp = parseTimestamp(line);

        // Determine the disjoint pairs of elements in the 'char' content array
        int startIndex = numLines * 2;
        for (int i = 0; i < len; i++) {
            int index = findNode(nodes, startIndex + i);
            if (index != -1) {
                indices[startIndex + i] = index;
            } else {
                int newIndex = makeNode(nodes, startIndex + i);
                indices[startIndex + i] = newIndex;
            }
        }
    }

    // Clean up memory and print the report
    free(lines);
    free(lineNumbers);
    free(logEntries);
    free(indices);
    for (int i = 0; i < numLines; i++) {
        free(nodes[i]);
    }
    free(nodes);
    printf("Time taken: %lf milliseconds\n", time_elapsed());
}

// Parse the status indicator from a line
