    // TODO: Implement parsing logic for timestamp
    return 0;
}

// Find the parent node of an index in the union-find data structure
int findNode(node **nodes, int index) {
    pthread_mutex_lock(&mutex);
    if (index < 0 || index >= numLines) {
        return -1;
    }
    while (nodes[index]->parent != index) {
        nodes[index] = nodes[nodes[index]->parent];
        index = nodes[index]->parent;
    }
    pthread_mutex_unlock(&mutex);
    return index;
}

// Make a new node in the union-find data structure and return its index
int makeNode(node **nodes, int index) {
    pthread_mutex_lock(&mutex);
    if (index < 0 || index >= numLines) {
        return -1;
    }
    nodes[index] = (node *)malloc(sizeof(node));
    nodes[index]->parent = index;
    nodes[index]->rank = 0;
    pthread_mutex_unlock(&mutex);
    return index;
}

// Calculate the time elapsed in milliseconds since the program started
