    int num_metrics;
    double* sums;
    double* averages;
    double* minimums;
    double* maximums;
} AggregateMetrics;

// Function to process and aggregate JSON-formatted input strings
AggregateMetrics processAndAggregateMetrics(char** inputs, int num_inputs) {
    // Initialize aggregated metrics structure
    AggregateMetrics agg_metrics = {0};
    agg_metrics.num_metrics = num_inputs;
    agg_metrics.sums = calloc(num_inputs, sizeof(double));
    agg_metrics.averages = calloc(num_inputs, sizeof(double));
    agg_metrics.minimums = calloc(num_inputs, sizeof(double));
    agg_metrics.maximums = calloc(num_inputs, sizeof(double));

    // Initialize JSON parser library
    json_init();

    // Process each input string concurrently using a thread pool
    pthread_t* threads = malloc(sizeof(pthread_t) * num_inputs);
    for (int i = 0; i < num_inputs; i++) {
        pthread_create(&threads[i], NULL, processInput, inputs[i]);
    }

    // Wait for all threads to finish and aggregate metrics
    for (int i = 0; i < num_inputs; i++) {
        pthread_join(threads[i], NULL);
        AggregateMetrics thread_metrics = processInput(inputs[i]);
        agg_metrics.sums[i] += thread_metrics.sums[i];
        agg_metrics.averages[i] += thread_metrics.averages[i];
        agg_metrics.minimums[i] = fmin(agg_metrics.minimums[i], thread_metrics.minimums[i]);
        agg_metrics.maximums[i] = fmax(agg_metrics.maximums[i], thread_metrics.maximums[i]);
    }

    // Free memory allocated for JSON parser library and threads
    json_free();
    free(threads);

    return agg_metrics;
}

// Process input string concurrently using a thread pool
void* processInput(char* input) {
    // Initialize JSON parser library
    json_init();

    // Parse input string to extract numerical values and categorize them into different metrics
    AggregateMetrics metrics = {0};
    metrics.num_metrics = 1;
    metrics.sums = calloc(1, sizeof(double));
    metrics.averages = calloc(1, sizeof(double));
    metrics.minimums = calloc(1, sizeof(double));
    metrics.maximums = calloc(1, sizeof(double));

    // Extract numerical values from input JSON object and update aggregated metrics structure
    json_t* root = json_parse(input);
    if (root) {
        json_object_foreach(root, key, value) {
            if (json_is_number(value)) {
                double num_val = json_number_value(value);
                metrics.sums[0] += num_val;
                metrics.averages[0] += num_val / 1.0;
                metrics.minimums[0] = fmin(metrics.minimums[0], num_val);
                metrics.maximums[0] = fmax(metrics.maximums[0], num_val);
            }
        }
    } else {
        // Handle malformed JSON structures gracefully and provide informative error messages
        fprintf(stderr, "Error: Malformed JSON structure in input string\n");
    }

    // Free memory allocated for JSON parser library
    json_free();

    return metrics;
}
