// Define the structure for connection metadata
struct dbMetadata {
    int status; // Status indicator (e.g., available, busy, closed)
    time_t lastAccessTime; // Timestamp of last access
    int errorCode; // Error code (e.g., 0 = no error, non-zero = error)
};

// Define the structure for database connections
struct dbConnection {
    struct dbMetadata *metadata; // Pointer to connection metadata
    char queryString[128]; // Query string buffer
    int transactionID; // Transaction ID
};

// Define the pool of database connections
struct dbConnectionPool {
    int size; // Size of the pool
    struct dbConnection *connections; // Array of connection structures
};

// Initialize a new connection pool with the given size
void initializeConnectionPool(int size) {
    struct dbConnectionPool *pool = (struct dbConnectionPool *) malloc(sizeof(struct dbConnectionPool));
    if (!pool) {
        fprintf(stderr, "Failed to allocate memory for connection pool\n");
        return;
    }
    pool->size = size;
    pool->connections = (struct dbConnection *) malloc(size * sizeof(struct dbConnection));
    if (!pool->connections) {
        fprintf(stderr, "Failed to allocate memory for connection array\n");
        free(pool);
        return;
    }
    int i;
    for (i = 0; i < size; i++) {
        pool->connections[i].metadata = (struct dbMetadata *) malloc(sizeof(struct dbMetadata));
        if (!pool->connections[i].metadata) {
            fprintf(stderr, "Failed to allocate memory for connection metadata\n");
            free(pool->connections);
            free(pool);
            return;
        }
        pool->connections[i].queryString = (char *) malloc(128 * sizeof(char));
        if (!pool->connections[i].queryString) {
            fprintf(stderr, "Failed to allocate memory for query string buffer\n");
            free(pool->connections[i].metadata);
            free(pool->connections);
            free(pool);
            return;
        }
        pool->connections[i].transactionID = 0;
        pool->connections[i].metadata->status = RANDOM_STATUS(); // Set random status for each connection
    }
}

// Deinitialize a connection pool
void deinitializeConnectionPool(struct dbConnectionPool *pool) {
    int i;
    for (i = 0; i < pool->size; i++) {
        free(pool->connections[i].queryString);
        free(pool->connections[i].metadata);
    }
    free(pool->connections);
    free(pool);
}

// Get a connection from the pool
struct dbConnection *getConnection(struct dbConnectionPool *pool) {
    int i;
    for (i = 0; i < pool->size; i++) {
        if (pool->connections[i].metadata->status == AVAILABLE) {
            return &pool->connections[i];
        }
    }
    // If no available connections, create a new one and return it
    struct dbConnection *conn = malloc(sizeof(struct dbConnection));
    if (!conn) {
        fprintf(stderr, "Failed to allocate memory for connection\n");
        return NULL;
    }
    conn->metadata = (struct dbMetadata *) malloc(sizeof(struct dbMetadata));
    if (!conn->metadata) {
        fprintf(stderr, "Failed to allocate memory for connection metadata\n");
        free(conn);
        return NULL;
    }
    conn->queryString = (char *) malloc(128 * sizeof(char));
    if (!conn->queryString) {
        fprintf(stderr, "Failed to allocate memory for query string buffer\n");
        free(conn->metadata);
        free(conn);
        return NULL;
    }
    conn->transactionID = 0;
    conn->metadata->status = AVAILABLE;
    pool->connections[pool->size++] = *conn; // Add new connection to the end of the array
    return conn;
}

// Return a connection to the pool
void returnConnection(struct dbConnectionPool *pool, struct dbConnection *conn) {
    int i;
    for (i = 0; i < pool->size; i++) {
        if (&pool->connections[i] == conn) { // Find the connection in the array
            pool->connections[i].metadata->status = AVAILABLE; // Set status to available
            break;
        }
    }
}

// Execute a query on a database connection
int executeQuery(struct dbConnection *conn, char *query) {
    if (conn == NULL || query == NULL) {
        return -1;
    }
    // Lock the connection before modifying it
    pthread_mutex_lock(&conn->metadata->lock);
    strcpy(conn->queryString, query); // Copy the query string into the buffer
    conn->metadata->status = BUSY; // Set status to busy
    // Unlock the connection after using it
    pthread_mutex_unlock(&conn->metadata->lock);
    return 0;
}

// Commit a transaction on a database connection
int commitTransaction(struct dbConnection *conn) {
    if (conn == NULL) {
        return -1;
    }
    // Lock the connection before modifying it
    pthread_mutex_lock(&conn->metadata->lock);
    conn->transactionID++; // Increment the transaction ID
    conn->metadata->status = AVAILABLE; // Set status to available
    // Unlock the connection after using it
    pthread_mutex_unlock(&conn->metadata->lock);
    return 0;
}

// Roll back a transaction on a database connection
int rollbackTransaction(struct dbConnection *conn) {
    if (conn == NULL) {
        return -1;
    }
    // Lock the connection before modifying it
    pthread_mutex_lock(&conn->metadata->lock);
    conn->transactionID--; // Decrement the transaction ID
    conn->metadata->status = AVAILABLE; // Set status to available
    // Unlock the connection after using it
    pthread_mutex_unlock(&conn->metadata->lock);
    return 0;
}

// Get the next available connection from the pool
struct dbConnection *getNextAvailableConnection(struct dbConnectionPool *pool) {
    int i;
    for (i = 0; i < pool->size; i++) {
        if (pool->connections[i].metadata->status == AVAILABLE) {
            return &pool->connections[i];
