    if (!conn->metadata) {
        fprintf(stderr, "Failed to allocate memory for connection metadata\n");
        free(conn);
        return NULL;
    }
    conn->queryString = (char *) malloc(128 * sizeof(char));
    if (!conn->queryString) {
        fprintf(stderr, "Failed to allocate memory for query string buffer\n");
        free(conn->metadata);
        free(conn);
        return NULL;
    }
    conn->transactionID = 0;
    conn->metadata->status = AVAILABLE;
    pool->connections[pool->size++] = *conn; // Add new connection to the end of the array
    return conn;
}

// Get the next available transaction ID from the pool
int getNextAvailableTransactionID(struct dbConnectionPool *pool) {
    int i;
    for (i = 0; i < pool->size; i++) {
        if (pool->connections[i].metadata->status == AVAILABLE) {
            return pool->connections[i].transactionID + 1; // Return the next available transaction ID
        }
    }
    // If no available connections, create a new one and return it
    struct dbConnection *conn = malloc(sizeof(struct dbConnection));
    if (!conn) {
        fprintf(stderr, "Failed to allocate memory for connection\n");
