        return -1;
    }
    conn->transactionID = 0;
    conn->metadata->status = AVAILABLE;
    pool->connections[pool->size++] = *conn; // Add new connection to the end of the array
    return conn->transactionID + 1; // Return the next available transaction ID
}

// Get the number of connections in the pool
int getConnectionCount(struct dbConnectionPool *pool) {
    return pool->size;
}

// Deinitialize and free all connections in the pool
void deinitializeAllConnections(struct dbConnectionPool *pool) {
    int i;
    for (i = 0; i < pool->size; i++) {
        free(pool->connections[i].queryString);
        free(pool->connections[i].metadata);
    }
    free(pool->connections);
}

// Initialize the connection pool with a given number of connections
struct dbConnectionPool *initializeConnectionPool(int numConnections) {
