#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <math.h>
#include <time.h>

// Struct for storing record data
struct Record {
    long timestamp;
    int identifier;
    double temperature;
};

// Function to read configuration settings from JSON file
void readConfig(const char* configFilePath, struct Record** records, int* numRecords) {
    // Open the JSON file and check for errors
    FILE* fp = fopen(configFilePath, "r");
    if (fp == NULL) {
        printf("Error: could not open configuration file '%s'\n", configFilePath);
        return;
    }

    // Allocate memory for the records array and initialize it to NULL
    *records = malloc(sizeof(struct Record*) * (*numRecords));
    if (*records == NULL) {
        printf("Error: could not allocate memory for records\n");
        fclose(fp);
        return;
    }

    // Parse the JSON file and fill in the record data
    char* line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, fp)) != -1) {
        // Skip empty lines and comments
        if (strlen(line) == 0 || line[0] == '#') continue;

        // Parse the timestamp and identifier from the line
        long timestamp = strtol(line, NULL, 10);
        int identifier = rand() % 100;

        // Allocate memory for the record structure and fill in the data
        struct Record* record = malloc(sizeof(struct Record));
        if (record == NULL) {
            printf("Error: could not allocate memory for record\n");
            fclose(fp);
            return;
        }
        record->timestamp = timestamp;
        record->identifier = identifier;
        record->temperature = ((double)rand() / RAND_MAX) * 120 - 50;

        // Add the record to the records array
        (*records)[*numRecords] = record;
        (*numRecords)++;
    }

    // Close the JSON file and free the line buffer
    fclose(fp);
    free(line);
}

// Function to configure and process web app data
void configureAndProcessWebApp(const char* configFilePath, struct Record** records, int* numRecords) {
    // Read configuration settings from JSON file
    readConfig(configFilePath, records, numRecords);

    // Allocate memory for the long and double arrays
    long* timestamps = malloc(sizeof(long) * (*numRecords));
    if (timestamps == NULL) {
        printf("Error: could not allocate memory for timestamps\n");
        return;
    }
    double* temperatures = malloc(sizeof(double) * (*numRecords));
    if (temperatures == NULL) {
        printf("Error: could not allocate memory for temperatures\n");
        free(timestamps);
        return;
    }

    // Initialize the arrays with the record data
    for (int i = 0; i < *numRecords; i++) {
        timestamps[i] = (*records)[i]->timestamp;
        temperatures[i] = (*records)[i]->temperature;
    }

    // Free the record data structures
    for (int i = 0; i < *numRecords; i++) {
        free((*records)[i]);
    }
    free(*records);

    // Process the web app data
    printf("Processing %d records...\n", *numRecords);
    for (int i = 0; i < *numRecords; i++) {
        printf("%ld: Temperature is %.2f\n", timestamps[i], temperatures[i]);
    }

    // Free the memory allocated for the arrays
    free(timestamps);
    free(temperatures);
}
