        // Truncate oldest entries in the log file to make space for new logs
        fseek(log_file, -MAX_LOG_FILE_SIZE, SEEK_END);

        // Save current log file position
        int old_pos = ftell(log_file);

        // Write a log message indicating the truncation of older logs
        char log_message[1024];
        snprintf(log_message, sizeof(log_message), "Log file flushed: %d records truncated.", *record_count);
        fwrite(log_message, strlen(log_message), 1, log_file);

        // Restore log file position to the end of the file
        fseek(log_file, old_pos, SEEK_SET);
    }
}

// Define a function to limit the total number of records stored in memory
void evict_least_recently_used_records(Record **records, int *record_count) {
    // Check if record count exceeds the threshold
    if (*record_count > MEMORY_USAGE_THRESHOLD) {
        // Find the least recently used record and evict it from memory
        Record *least_recently_used = records[0];
        for (int i = 1; i < *record_count; i++) {
            if (records[i]->timestamp < least_recently_used->timestamp) {
                least_recently_used = records[i];
            }
        }
        // Free the evicted record from memory
        free(least_recently_used);

        // Update the record count and position of the evicted record
        *record_count -= 1;
    }
}

