        key_array[i] = rand() % threshold + 1;
        record_array[i].value = rand() % threshold + 1;
        record_array[i].timestamp = (double)clock() / CLOCKS_PER_SEC * 1000;
    }

    // Filter records based on the threshold and find the largest integer
