// Structure definitions
typedef struct {
    int id;
    unsigned int duration;
    char phase[10]; // Phase string with a maximum length of 10 characters
} project_t;

typedef struct {
    char type[10]; // Type string with a maximum length of 10 characters
    unsigned int availability;
    char status[10]; // Status string with a maximum length of 10 characters
} resource_t;

// Function declarations
project_t* allocate_projects(unsigned int num_projects);
void initialize_projects(project_t *projects, unsigned int num_projects, unsigned int duration, char phase[]);
resource_t* allocate_resources(unsigned int num_resources);
void initialize_resources(resource_t *resources, unsigned int num_resources, char status[]);
int assign_resources_to_projects(project_t *projects, resource_t *resources, unsigned int num_projects, unsigned int num_resources);
void print_assignment_summary(project_t *projects, resource_t *resources, unsigned int num_projects, unsigned int num_resources);
void free_memory(project_t *projects, resource_t *resources);

int main() {
    // Define variables and allocate memory for projects and resources
    unsigned int num_projects = 5;
    project_t* projects = allocate_projects(num_projects);
    if (!projects) {
        printf("Failed to allocate memory for projects\n");
        return EXIT_FAILURE;
    }

    resource_t* resources = allocate_resources(10); // Assume a maximum of 10 resources
    if (!resources) {
        printf("Failed to allocate memory for resources\n");
        free_memory(projects, NULL);
        return EXIT_FAILURE;
    }

    // Initialize projects and resources with user-provided values
    unsigned int duration = 10; // Duration of each project
    char phase[] = "Phase 1"; // Phase string for each project
    initialize_projects(projects, num_projects, duration, phase);

    char status[] = "Available"; // Status of each resource
    initialize_resources(resources, 10, status);

    // Assign resources to projects based on urgency and availability
    int result = assign_resources_to_projects(projects, resources, num_projects, 10);
    if (result != EXIT_SUCCESS) {
        printf("Failed to assign resources to projects\n");
        free_memory(projects, resources);
        return EXIT_FAILURE;
    }

    // Print summary of assigned resources
    print_assignment_summary(projects, resources, num_projects, 10);

    // Free allocated memory
    free_memory(projects, resources);

    return EXIT_SUCCESS;
}

// Function definitions
project_t* allocate_projects(unsigned int num_projects) {
    project_t *projects = (project_t *)malloc(num_projects * sizeof(project_t));
    if (!projects) {
        printf("Failed to allocate memory for %d projects\n", num_projects);
        return NULL;
    }
    return projects;
}

void initialize_projects(project_t *projects, unsigned int num_projects, unsigned int duration, char phase[]) {
    for (int i = 0; i < num_projects; ++i) {
        projects[i].id = i + 1; // Sequential project IDs starting from 1
        projects[i].duration = duration;
        strncpy(projects[i].phase, phase, sizeof(projects[i].phase) - 1);
    }
}

resource_t* allocate_resources(unsigned int num_resources) {
    resource_t *resources = (resource_t *)malloc(num_resources * sizeof(resource_t));
    if (!resources) {
        printf("Failed to allocate memory for %d resources\n", num_resources);
        return NULL;
    }
    return resources;
}

void initialize_resources(resource_t *resources, unsigned int num_resources, char status[]) {
    for (int i = 0; i < num_resources; ++i) {
        strncpy(resources[i].type, "Resource", sizeof(resources[i].type) - 1); // Type string for each resource
        resources[i].availability = 5; // Availability of each resource
        strncpy(resources[i].status, status, sizeof(resources[i].status) - 1);
    }
}

int assign_resources_to_projects(project_t *projects, resource_t *resources, unsigned int num_projects, unsigned int num_resources) {
    // Prioritize resource allocation based on project urgency and availability
    for (int i = 0; i < num_projects; ++i) {
        for (int j = 0; j < num_resources; ++j) {
            if (resources[j].availability >= projects[i].duration && strcmp(resources[j].status, "Available") == 0) {
                projects[i].id = j + 1; // Resource ID for each project
                resources[j].status = "Assigned";
                break;
            }
        }
    }

    // Log assignment process and provide summary of allocated resources
    printf("Resource Assignment Summary:\n");
    for (int i = 0; i < num_projects; ++i) {
        printf("Project %d: Resource ID %d\n", projects[i].id, projects[i].id);
    }

    return EXIT_SUCCESS;
}

void print_assignment_summary(project_t *projects, resource_t *resources, unsigned int num_projects, unsigned int num_resources) {
    // Print summary of assigned resources
    printf("Resource Assignment Summary:\n");
    for (int i = 0; i < num_projects; ++i) {
        printf("Project %d: Resource ID %d\n", projects[i].id, projects[i].id);
    }
}

void free_memory(project_t *projects, resource_t *resources) {
    if (projects != NULL) {
        free(projects);
    }
    if (resources != NULL) {
        free(resources);
    }
}
