    struct timeval deadline;
    void *data;
};

void cleanup_task(struct task *task) {
    free(task->name);
    free(task->data);
}

int init_task_array(struct task **tasks, size_t num_tasks, char *task_names[], int priority, struct timeval deadline, void (*data_init)(void *)) {
    if (num_tasks == 0 || tasks == NULL) {
        return -1;
    }

    for (size_t i = 0; i < num_tasks; i++) {
        struct task *task = malloc(sizeof(struct task));
        if (task == NULL) {
            return -2;
        }

        task->name = strdup(task_names[i]);
        task->priority = priority;
        task->deadline = deadline;

        // Initialize data based on task type
        void *data = malloc(sizeof(void));
        if (data == NULL) {
            cleanup_task(task);
            return -3;
        }
        data_init(data);
        task->data = data;

        tasks[i] = task;
    }

    return 0;
}
