            if (!streamData[numStreams]) {
                printf("Memory allocation failed. Exiting...\n");
                return -1;
            }
        } else {
            // Reallocate memory for the stream's data structure to avoid fragmentation
            streamDataPtr = (struct logEntry *)realloc(streamData[numStreams], sizeof(struct logEntry));
            if (!streamDataPtr) {
