    for (int i = 0; i < num_events; i++) {
        events[i].timestamp = curr_time + i;
    }

    // Generate unique identifiers for each event message
    char prefix[] = "Event: ";
    int suffix_len = 8;
    for (int i = 0; i < num_events; i++) {
        char* message = (char*)malloc(strlen(prefix) + suffix_len + 1);
        if (!message) {
