            return NULL;
        }

        // Generate a random suffix using a cryptographically secure PRNG
        char suffix[suffix_len];
        int rc = getrandom(&suffix, suffix_len, GRND_RANDOM);
        if (rc < 0) {
            fprintf(stderr, "Failed to generate random suffix\n");
            return NULL;
