        // Concatenate the prefix and suffix to form the event message
        strcpy(message, prefix);
        for (int j = 0; j < suffix_len; j++) {
            message[strlen(prefix) + j] = suffix[j];
        }
        events[i].message = message;
    }

    // Generate random values within the specified range for each event metric
