struct record_node {
    struct record *record;
    struct record_node *next;
    struct record_node *prev;
};

// Define a linked list of records
struct record_list {
    struct record_node *head;
    struct record_node *tail;
    int count;
};

// Function to allocate memory for a new record
struct record* alloc_record() {
    struct record *record = (struct record*)malloc(sizeof(struct record));
    if (!record) {
        return NULL;
    }
    memset(record, 0, sizeof(struct record));
    return record;
}

// Function to free memory for a record
