    if (record) {
        free(record);
    }
}

// Function to allocate memory for a new event
struct event* alloc_event() {
    struct event *event = (struct event*)malloc(sizeof(struct event));
    if (!event) {
        return NULL;
    }
    memset(event, 0, sizeof(struct event));
    return event;
}

// Function to free memory for an event
void free_event(struct event *event) {
    if (event) {
        // Free the linked list of records
        struct record_node *record = event->records;
        while (record) {
            struct record_node *next = record->next;
            free_record(record->record);
            free(record);
            record = next;
        }

        // Free the event structure itself
        free(event);
    }
}

// Function to allocate memory for a new record list
struct record_list* alloc_record_list() {
    struct record_list *list = (struct record_list*)malloc(sizeof(struct record_list));
    if (!list) {
        return NULL;
    }
    memset(list, 0, sizeof(struct record_list));
    return list;
}

// Function to free memory for a record list
void free_record_list(struct record_list *list) {
    if (list) {
        // Free the linked list of records
        struct record_node *record = list->head;
        while (record) {
            struct record_node *next = record->next;
            free_record(record->record);
            free(record);
            record = next;
        }

        // Free the list structure itself
        free(list);
    }
}

// Function to add a new record to the list
void add_record(struct record_list *list, struct record *record) {
    if (list && record) {
        // Create a new node for the record
        struct record_node *node = (struct record_node*)malloc(sizeof(struct record_node));
        node->record = record;
        node->next = NULL;
        node->prev = list->tail;
        if (list->tail) {
            list->tail->next = node;
        } else {
            list->head = node;
        }
        list->tail = node;
        ++list->count;
    }
}

// Function to remove a record from the list
void remove_record(struct record_list *list, struct record *record) {
    if (list && record) {
        // Find the node for the record
        struct record_node *node = list->head;
        while (node) {
            if (node->record == record) {
                break;
            }
            node = node->next;
        }

        // Remove the node from the list
        if (node) {
            struct record_node *prev = node->prev;
            struct record_node *next = node->next;
            free(node);
            if (prev) {
                prev->next = next;
            } else {
                list->head = next;
            }
            if (next) {
                next->prev = prev;
            } else {
                list->tail = prev;
            }
            --list->count;
        }
    }
}

// Function to handle memory allocation failures gracefully
int alloc_failure(void *ptr, size_t size) {
