public class DataProcessor
{
    private readonly long[] offsets;
    private readonly int[] transactionIds;
    private readonly double[] errorCodes;
    private readonly List<Record> records;

    public DataProcessor(int capacity, int transactionIdCapacity)
    {
        if (capacity < 10 || transactionIdCapacity < capacity / 2)
        {
            throw new ArgumentException("Invalid capacity or transaction ID capacity specified.");
        }

        offsets = new long[capacity];
        transactionIds = new int[transactionIdCapacity];
        errorCodes = new double[transactionIdCapacity];
        records = new List<Record>(capacity);
    }

    public Record RetrieveRandomRecord()
    {
        var randomIndex = Random.Next(records.Count);
        return records[randomIndex];
    }

    public void UpdateTransactionId(int index, int newValue)
    {
        if (index < 0 || index >= transactionIds.Length)
        {
            throw new ArgumentOutOfRangeException("Invalid index specified.");
        }

        lock (this)
        {
            var currentTransactionId = transactionIds[index];
            var updatedTransactionId = Math.Max(currentTransactionId, newValue);

            if (updatedTransactionId > currentTransactionId)
            {
                transactionIds[index] = updatedTransactionId;
            }
        }
    }

    public void AddRecord()
    {
        var record = new Record();
        records.Add(record);

        lock (this)
        {
            offsets[records.Count - 1] = random.NextLong();
            transactionIds[records.Count - 1] = random.NextInt(int.MaxValue / 2);
            errorCodes[records.Count - 1] = random.NextDouble();
        }
    }

    public void PersistChanges()
    {
        // Integrate with external data source to persist changes.
    }
}

public class Record
{
    public long Offset { get; set; }
