// Define the frequency tracker structure
typedef struct {
    unsigned long key;
    int count;
} FrequencyTracker;

// Define the hash table for tracking key frequencies
typedef struct {
    FrequencyTracker* buckets;
    size_t capacity;
} HashTable;

// Function to initialize the frequency tracker
void initFrequencyTracker(HashTable* ht) {
    // Initialize the hash table with a default capacity
    ht->capacity = 1024;
    // Allocate memory for the buckets
    ht->buckets = malloc(ht->capacity * sizeof(FrequencyTracker));
    // Check for memory allocation failures
    if (ht->buckets == NULL) {
        fprintf(stderr, "Failed to allocate memory for frequency tracker\n");
        exit(1);
    }
}

// Function to insert a key into the hash table
void insertKey(HashTable* ht, unsigned long key) {
    // Check if the key already exists in the hash table
    int index = findKeyIndex(ht, key);
    // If the key does not exist, create a new entry
    if (index == -1) {
        // Expand the hash table if it is too full
        if (ht->capacity == ht->count) {
            expandHashTable(ht);
        }
        // Insert the key into the hash table
        ht->buckets[ht->count].key = key;
        ht->buckets[ht->count].count = 1;
        ht->count++;
    } else {
        // Increment the count for the existing key
        ht->buckets[index].count++;
    }
}

// Function to find the index of a key in the hash table
int findKeyIndex(HashTable* ht, unsigned long key) {
    for (size_t i = 0; i < ht->capacity; i++) {
        if (ht->buckets[i].key == key) {
            return i;
        }
    }
    return -1;
}

// Function to expand the hash table
void expandHashTable(HashTable* ht) {
    // Double the capacity of the hash table
    ht->capacity *= 2;
    // Allocate memory for the new buckets
    FrequencyTracker* new_buckets = malloc(ht->capacity * sizeof(FrequencyTracker));
    if (new_buckets == NULL) {
        fprintf(stderr, "Failed to allocate memory for expanded hash table\n");
        exit(1);
    }
    // Copy the existing buckets into the new array
    memcpy(new_buckets, ht->buckets, ht->count * sizeof(FrequencyTracker));
    // Free the old bucket array
    free(ht->buckets);
    // Set the new bucket array and capacity
    ht->buckets = new_buckets;
}

// Function to clean up the hash table
void destroyHashTable(HashTable* ht) {
    // Free the memory for the buckets
    free(ht->buckets);
    // Set the capacity and count to zero
    ht->capacity = 0;
    ht->count = 0;
}

// Function to process a record
void processRecord(Record* r) {
    // Insert the key into the frequency tracker
    insertKey(&frequency_tracker, r->key);
    // Update the offset for the record
    r->offset = offset++;
}

// Main function
int main() {
    // Initialize the frequency tracker
    initFrequencyTracker(&frequency_tracker);

    // Open the input file and allocate memory for the records
    FILE* fp = fopen("input.txt", "r");
    if (fp == NULL) {
        perror("Failed to open input file");
        return 1;
    }
    Record* records = malloc(sizeof(Record) * record_count);
    if (records == NULL) {
        fprintf(stderr, "Failed to allocate memory for records\n");
        return 1;
    }

    // Process the records in parallel using multiple threads
    size_t thread_count = 4;
    pthread_t* threads = malloc(sizeof(pthread_t) * thread_count);
    if (threads == NULL) {
        fprintf(stderr, "Failed to allocate memory for threads\n");
        return 1;
    }
    for (size_t i = 0; i < thread_count; i++) {
        int rc = pthread_create(&threads[i], NULL, processRecords, &records);
        if (rc != 0) {
            fprintf(stderr, "Failed to create thread %lu\n", i);
            return 1;
        }
    }

    // Join the threads and clean up the hash table
    for (size_t i = 0; i < thread_count; i++) {
        int rc = pthread_join(threads[i], NULL);
        if (rc != 0) {
            fprintf(stderr, "Failed to join thread %lu\n", i);
            return 1;
        }
    }
    destroyHashTable(&frequency_tracker);

    // Print the frequency tracker and records
    printf("Frequency tracker: \n");
    for (size_t i = 0; i < ht->count; i++) {
        printf("%lu: %d\n", ht->buckets[i].key, ht->buckets[i].count);
    }
    printf("Records: \n");
    for (size_t i = 0; i < record_count; i++) {
        printf("%d %ld\n", records[i].value, records[i].offset);
    }

    // Free the memory for the threads and the records
    free(threads);
    free(records);

    return 0;
}
```
