// Get the name of a metric type enum value
const char* getMetricTypeName(enum MetricType type) {
    switch (type) {
        case METRIC_TYPE_DOUBLE: return "double";
        case METRIC_TYPE_UINT32: return "uint32";
        default: return "unknown";
    }
}
