// Define the struct for holding metric records
struct metricRecord {
    double value;
    char label[256];
};

// Function to parse and aggregate metrics
void* parseAndAggregateMetrics(void *data) {
    // Get the file path from the data argument
    const char *filePath = (const char*) data;

    // Open the file for reading
    FILE *fp = fopen(filePath, "r");
    if (fp == NULL) {
        printf("Error: unable to open file %s\n", filePath);
        return NULL;
    }

    // Allocate memory for the metric records array
    struct metricRecord **metrics = malloc(sizeof(struct metricRecord*) * 100);
    if (metrics == NULL) {
        printf("Error: unable to allocate memory for metrics\n");
        fclose(fp);
        return NULL;
    }

    // Initialize the array of pointers with null values
    for (int i = 0; i < 100; i++) {
        metrics[i] = NULL;
    }

    // Allocate memory for the metric records themselves
    int currentMetricCount = 0;
    while (!feof(fp)) {
        struct metricRecord *metric = malloc(sizeof(struct metricRecord));
        if (metric == NULL) {
            printf("Error: unable to allocate memory for metric record\n");
            fclose(fp);
            return NULL;
        }

        // Read the value and label from the file
        double value = 0.0;
        char *label = malloc(sizeof(char) * 256);
        if (label == NULL) {
            printf("Error: unable to allocate memory for label\n");
            fclose(fp);
            return NULL;
        }
        fscanf(fp, "%lf %s", &value, label);

        // Add the metric record to the array of pointers
        metrics[currentMetricCount] = metric;
        currentMetricCount++;

        // Check if the array is full and reallocate memory if necessary
        if (currentMetricCount == 100) {
            int newSize = currentMetricCount * 2;
            struct metricRecord **newMetrics = realloc(metrics, sizeof(struct metricRecord*) * newSize);
            if (newMetrics == NULL) {
                printf("Error: unable to reallocate memory for metrics\n");
                fclose(fp);
                return NULL;
            }
            metrics = newMetrics;
        }
    }

    // Close the file
    fclose(fp);

    // Compute the aggregates
    double average = 0.0;
    double minimum = INFINITY;
    double maximum = -INFINITY;
    for (int i = 0; i < currentMetricCount; i++) {
        struct metricRecord *metric = metrics[i];
        average += metric->value;
        if (metric->value < minimum) {
            minimum = metric->value;
        }
        if (metric->value > maximum) {
            maximum = metric->value;
        }
    }
    average /= currentMetricCount;

    // Print the summary report
    printf("Average: %.2f\n", average);
    printf("Minimum: %.2f\n", minimum);
    printf("Maximum: %.2f\n", maximum);

    // Clean up memory
    for (int i = 0; i < currentMetricCount; i++) {
        struct metricRecord *metric = metrics[i];
        free(metric->label);
        free(metric);
    }
    free(metrics);
}
```
