import java.util.*;

public class DependencyManager {
    private final List<Dependency> dependencies;
    private final Map<String, Dependency> dependencyMap;

    public DependencyManager(List<Dependency> dependencies) {
        this.dependencies = new ArrayList<>();
        this.dependencyMap = new HashMap<>();
        for (Dependency dependency : dependencies) {
            addDependency(dependency);
        }
    }

    public void addDependency(Dependency dependency) {
        dependencies.add(dependency);
        dependencyMap.put(dependency.getName(), dependency);
    }

    public Dependency getDependency(String name) {
        return dependencyMap.get(name);
    }

    public void removeDependency(String name) {
        for (int i = 0; i < dependencies.size(); i++) {
            if (dependencies.get(i).getName().equals(name)) {
                dependencies.remove(i);
                break;
            }
        }
        dependencyMap.remove(name);
    }

    public void updateDependency(Dependency dependency) {
        for (int i = 0; i < dependencies.size(); i++) {
            if (dependencies.get(i).getName().equals(dependency.getName())) {
                dependencies.set(i, dependency);
                break;
            }
        }
        dependencyMap.put(dependency.getName(), dependency);
    }

    public List<Dependency> getDependencies() {
        return dependencies;
    }
}
