class DependencyManager
{
    private $dependencies;
    private $dependencyMap;

    public function __construct(array $dependencies)
    {
        $this->dependencies = [];
        $this->dependencyMap = new \SplObjectStorage();
        foreach ($dependencies as $dependency) {
            $this->addDependency($dependency);
        }
    }

    public function addDependency(object $dependency): void
    {
        $this->dependencies[] = $dependency;
        $this->dependencyMap[$dependency] = $dependency;
    }

    public function getDependency(string $name): ?object
    {
        foreach ($this->dependencies as $dependency) {
            if ($dependency->getName() === $name) {
                return $dependency;
            }
        }

        return null;
    }

    public function removeDependency(string $name): void
    {
        foreach ($this->dependencies as $i => $dependency) {
            if ($dependency->getName() === $name) {
                unset($this->dependencies[$i]);
                break;
            }
        }

        $this->dependencyMap->detach(new \SplObjectStorage($name));
    }

    public function updateDependency(object $dependency): void
    {
        foreach ($this->dependencies as $i => $existingDependency) {
            if ($existingDependency->getName() === $dependency->getName()) {
                $this->dependencies[$i] = $dependency;
                break;
            }
        }

        $this->dependencyMap[$dependency] = $dependency;
    }

    public function getDependencies(): array
    {
        return $this->dependencies;
    }
}
