using namespace std;

class DependencyManager {
public:
    explicit DependencyManager(const vector<pair<string, string>>& dependencies) : dependencies_(dependencies) {}

    void addDependency(const pair<string, string>& dependency) {
        dependencies_.push_back(dependency);
        dependencyMap_[dependency.first] = dependency;
    }

    const pair<string, string>* getDependency(const string& name) {
        for (auto it = dependencies_.begin(); it != dependencies_.end(); ++it) {
            if (it->first == name) {
                return &(*it);
            }
        }

        return nullptr;
    }

    void removeDependency(const string& name) {
        for (auto it = dependencies_.begin(); it != dependencies_.end(); ++it) {
            if (it->first == name) {
                dependencies_.erase(it);
                break;
            }
        }

        dependencyMap_.erase(name);
    }

    void updateDependency(const pair<string, string>& dependency) {
        for (auto it = dependencies_.begin(); it != dependencies_.end(); ++it) {
            if (it->first == dependency.first) {
                *it = dependency;
                break;
            }
        }

        dependencyMap_[dependency.first] = dependency;
    }

    const vector<pair<string, string>>& getDependencies() const {
        return dependencies_;
    }

private:
    vector<pair<string, string>> dependencies_;
    unordered_map<string, pair<string, string>> dependencyMap_;
};
