int processAndAggregateData(size_t batchSize) {
    // Get the current time in seconds since the epoch
    time_t t = time(NULL);

    // Allocate memory for the three arrays
    float *values = (float *)malloc(batchSize * sizeof(float));
    double *timestamps = (double *)malloc(batchSize * sizeof(double));
    Record *records = (Record *)malloc(batchSize * sizeof(Record));

    // Check for memory allocation failure
    if (values == NULL || timestamps == NULL || records == NULL) {
        fprintf(stderr, "Error: failed to allocate memory\n");
        return 1;
