    // Initialize the arrays with random floating-point numbers and unique character identifiers
    for (size_t i = 0; i < batchSize; ++i) {
        values[i] = (float)(rand() % 1000);
        timestamps[i] = (double)t + (double)i * 1.0;
        records[i].value = values[i];
        records[i].identifier = 'A' + i % 26;
    }

    // Compute the average value of all the floating-point numbers processed
    float sum = 0.0f;
    for (size_t i = 0; i < batchSize; ++i) {
        sum += values[i];
    }
    float average = sum / (float)batchSize;

    // Print the result
