// Configuration options
#define MAX_MEMORY_ALLOCATION (1024 * 1024 * 1024) // 1 GB
#define RANDOM_NUMBER_RANGE 100000

typedef struct Record {
    int value;
    double timestamp;
} Record;

int processAndFindMax(const char* filename, const char* logfile) {
    // Open the input file and check for errors
    FILE* fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("fopen");
        return errno;
    }

    // Initialize random number generator with current time in milliseconds
    srand((unsigned int)time(NULL));

    // Initialize memory allocation variables
    size_t offset = 0;
    size_t num_records = 0;
    Record* records = NULL;

    // Read input file and process datasets sequentially
    while (fscanf(fp, "%d", &num_records) == 1) {
        if (num_records <= 0) {
            break;
        }

        // Allocate memory for records
        size_t allocation_size = num_records * sizeof(Record);
        if (allocation_size > MAX_MEMORY_ALLOCATION) {
            printf("Error: allocation size exceeds maximum limit\n");
            break;
        }
        records = realloc(records, offset + allocation_size);
        if (records == NULL) {
            perror("realloc");
            return errno;
        }

        // Generate random numbers and initialize timestamps
        for (int i = 0; i < num_records; ++i) {
            int value = rand() % RANDOM_NUMBER_RANGE + 1;
            records[offset + i].value = value;
            records[offset + i].timestamp = (double)time(NULL);
        }

        // Find maximum integer in current dataset
        int max_value = INT_MIN;
        for (int i = 0; i < num_records; ++i) {
            if (records[offset + i].value > max_value) {
                max_value = records[offset + i].value;
            }
        }

        // Log maximum integer and processing timestamps
        log_max_integer(logfile, max_value);
        log_processing_timestamps(logfile, offset, num_records);

        // Increment offset and reset internal state for next dataset
        offset += allocation_size;
        memset(records + offset, 0, allocation_size);
    }

    // Clean up allocated memory
    free(records);
    fclose(fp);

