// Define the record structure
typedef struct record {
  int value;
  double timestamp;
  char data[128];
} record_t;

// Define the linked list node structure
typedef struct node {
  record_t* record;
  struct node* next;
} node_t;

// Function to generate a random integer within a specified range
int rand_int(int min, int max) {
  return (rand() % (max - min + 1)) + min;
}

// Function to generate a random string of alphanumeric characters
char* rand_string(size_t length) {
  char* str = malloc(length);
  if (!str) {
    fprintf(stderr, "Error: failed to allocate memory for string\n");
    return NULL;
  }

  for (int i = 0; i < length; i++) {
    str[i] = 'a' + (rand() % ('z' - 'a' + 1));
  }

  str[length - 1] = '\0';
  return str;
}

// Function to initialize the record structure with random values
record_t* init_record(int value, double timestamp) {
  // Allocate memory for the record structure
  record_t* record = malloc(sizeof(record_t));
  if (!record) {
    fprintf(stderr, "Error: failed to allocate memory for record\n");
    return NULL;
  }

  // Initialize the record fields with random values
  record->value = value;
  record->timestamp = timestamp;
  record->data = rand_string(128);

  return record;
}

// Function to insert a new record into the linked list
void insert_record(node_t** head, int value, double timestamp) {
  // Allocate memory for the new node
  node_t* new_node = malloc(sizeof(node_t));
  if (!new_node) {
    fprintf(stderr, "Error: failed to allocate memory for new node\n");
    return;
  }

  // Initialize the new node with the given value and timestamp
  record_t* new_record = init_record(value, timestamp);
  if (!new_record) {
    fprintf(stderr, "Error: failed to initialize new record\n");
    free(new_node);
    return;
  }

  // Set the new node's record and next pointers
  new_node->record = new_record;
  new_node->next = *head;

  // Update the head pointer to point to the new node
  *head = new_node;
}

// Function to delete a record from the linked list
void delete_record(node_t** head, int value) {
  // Search for the record with the given value in the linked list
  node_t* current = *head;
  while (current != NULL && current->record->value != value) {
    current = current->next;
  }

  // If the record is found, delete it from the linked list
  if (current != NULL) {
    node_t* previous = current->previous;
    free(current);
    if (previous == NULL) {
      *head = current->next;
    } else {
      previous->next = current->next;
    }
  }
}

// Function to process an external data source update and insert or delete records as necessary
void process_update(node_t** head, int value, double timestamp) {
  // Insert a new record if the given value is not already in the linked list
  node_t* current = *head;
  while (current != NULL && current->record->value != value) {
    current = current->next;
  }

  // If the record is not found, insert it into the linked list
  if (current == NULL) {
    insert_record(head, value, timestamp);
  } else {
    // Update the existing record with the given value and timestamp
    current->record->value = value;
    current->record->timestamp = timestamp;
  }
}

// Function to handle memory allocation failures gracefully
int handle_allocation_failure(void) {
  fprintf(stderr, "Error: failed to allocate memory\n");
  return -1;
}

// Function to free all allocated memory upon successful completion or early exit due to an error
void free_memory(node_t* head) {
  while (head != NULL) {
    node_t* next = head->next;
    free(head);
    head = next;
  }
}
