    for (size_t i = 0; i < num_timestamps; ++i) {
        timestamp[i] = timestamps[i];
    }
    for (size_t i = 0; i < num_labels; ++i) {
        label[i] = labels[i];
    }

    // Initialize the array of records and set the transaction IDs
    struct record* records = safe_malloc_array(num_transaction_ids, MAX_TRANSACTION_IDS);
    for (size_t i = 0; i < num_transaction_ids; ++i) {
        records[i].offset = offset + i;
        records[i].transaction_id = transaction_id + i;
        records[i].timestamp = timestamp + i;
        records[i].label = label + i;
        records[i].transaction_id = rand() % MAX_TRANSACTION_IDS;
    }

    // Clean up memory
    free(offset);
    free(transaction_id);
    free(timestamp);
    free(label);

    return 0;
}
```
