    return timestamp + (3600 * 1000);
}

// Process metadata for a metric
char* processMetricMetadata(char* metadata) {
    // Trim whitespace characters from the beginning and end of the metadata
    char* trimmedMetadata = trim(metadata);
    return trimmedMetadata;
}

// Trim whitespace characters from the beginning and end of a string
char* trim(char* str) {
    size_t len = strlen(str);
    size_t start = 0;
    while (isspace(str[start])) start++;
    if (start == 0) return str;
    size_t end = len - 1;
    while (isspace(str[end]) && end > start) end--;
    size_t new_len = end - start + 1;
    char* buf = malloc(new_len * sizeof(char));
    if (!buf) {
        printf("Error: Out of memory\n");
        return str;
    }
    memcpy(buf, &str[start], new_len);
    buf[new_len] = '\0';
    free(str);
    return buf;
}
