Here is a possible implementation of the C function for initializing a dynamic memory allocation pipeline:
```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdio.h>

// Define record structure
struct record {
    long value;
    char* buffer;
    int length;
};

// Define pipeline data structures
struct offset_array {
    long* offsets;
    size_t capacity;
    size_t count;
};

struct key_array {
    int* keys;
    size_t capacity;
    size_t count;
};

struct record_array {
    struct record* records;
    size_t capacity;
    size_t count;
};

// Define logging mechanism
#define LOGGING_ENABLED 1

void log(const char* format, ...) {
    #if LOGGING_ENABLED
        va_list args;
        va_start(args, format);
        vprintf(format, args);
        va_end(args);
    #endif
}

// Initialize pipeline with given capacity and number of keys
void initialize_pipeline(struct offset_array* offsets, struct key_array* keys, size_t num_keys, size_t capacity) {
    // Allocate memory for the offset array
    offsets->offsets = malloc(capacity * sizeof(*offsets));
    if (offsets == NULL) {
        log("ERROR: Failed to allocate memory for offset array\n");
        return;
    }
    offsets->capacity = capacity;
    offsets->count = 0;

    // Allocate memory for the key array
    keys->keys = malloc(num_keys * sizeof(*keys));
    if (keys == NULL) {
        log("ERROR: Failed to allocate memory for key array\n");
        free(offsets->offsets);
        return;
    }
    keys->capacity = num_keys;
    keys->count = 0;

    // Allocate memory for the record array
    struct record_array* records = malloc(capacity * sizeof(*records));
    if (records == NULL) {
        log("ERROR: Failed to allocate memory for record array\n");
        free(offsets->offsets);
        free(keys->keys);
        return;
    }
    records->capacity = capacity;
    records->count = 0;

    // Initialize the offset array
    for (size_t i = 0; i < offsets->capacity; i++) {
        offsets->offsets[i] = -1;
    }

    // Initialize the key array
    for (size_t i = 0; i < keys->capacity; i++) {
        keys->keys[i] = -1;
    }

    // Initialize the record array
    for (size_t i = 0; i < records->capacity; i++) {
        records->records[i].value = -1;
        records->records[i].buffer = NULL;
        records->records[i].length = 0;
    }
}

// Add a new record to the pipeline with given key and value
void add_record(struct offset_array* offsets, struct key_array* keys, struct record_array* records, size_t key, long value) {
    // Find an available slot in the record array
    size_t i;
    for (i = 0; i < records->capacity; i++) {
        if (records->records[i].value == -1) {
            break;
        }
    }
    if (i >= records->capacity) {
        log("ERROR: Record array is full\n");
        return;
    }

    // Add the record to the pipeline
    records->records[i].value = value;
    offsets->offsets[key] = i;
    keys->keys[key] = key;
}

// Remove a record from the pipeline with given key
void remove_record(struct offset_array* offsets, struct key_array* keys, struct record_array* records, size_t key) {
    // Find the slot of the record to be removed
    size_t i;
    for (i = 0; i < records->capacity; i++) {
        if (records->records[i].value == -1) {
            break;
        }
    }
    if (i >= records->capacity) {
        log("ERROR: Record array is full\n");
        return;
    }

    // Remove the record from the pipeline
    offsets->offsets[key] = -1;
    keys->keys[key] = -1;
    records->records[i].value = -1;
}

// Get a reference to a record in the pipeline with given key
struct record* get_record(struct offset_array* offsets, struct key_array* keys, struct record_array* records, size_t key) {
    // Find the slot of the record to be accessed
    size_t i = offsets->offsets[key];
    if (i >= records->capacity || records->records[i].value == -1) {
        return NULL;
    }

    // Return a reference to the record
    return &records->records[i];
}

// Update the value of a record in the pipeline with given key
void update_record(struct offset_array* offsets, struct key_array* keys, struct record_array* records, size_t key, long value) {
    // Find the slot of the record to be updated
    size_t i = offsets->offsets[key];
    if (i >= records->capacity || records->records[i].value == -1) {
        log("ERROR: Record array is full\n");
        return;
    }

    // Update the value of the record
    records->records[i].value = value;
}
```
