void batchProcessAndAggregateData(char** inputs, int numInputs, int batchSize, int numThreads) {
    // Initialize variables
    Transaction* transactions = (Transaction*)malloc(sizeof(Transaction) * numInputs);
    double totalAmount[numInputs];
    memset(totalAmount, 0, sizeof(double) * numInputs);
    pthread_t threads[numThreads];
    int threadArgs[numThreads][2];
    int i;

    // Create and start threads for processing
    for (i = 0; i < numThreads; ++i) {
        threadArgs[i][0] = i;
        threadArgs[i][1] = batchSize / numThreads;
        pthread_create(&threads[i], NULL, processBatch, &threadArgs[i]);
    }

    // Join threads and aggregate data
    for (i = 0; i < numThreads; ++i) {
        pthread_join(threads[i], NULL);
        int j;
        for (j = 0; j < threadArgs[i][1]; ++j) {
            totalAmount[threadArgs[i][0]] += transactions[j].amount;
        }
    }

    // Print results and free memory
    printf("Total amount: %lf\n", totalAmount[numInputs - 1]);
    free(transactions);
}

