```c
#include <stdlib.h>
#include <stdio.h>

struct memory_pool {
    // ...
};

void *memory_pool_alloc(struct memory_pool *pool, size_t size) {
    void *ptr = NULL;
    if (size <= pool->free_size) {
        ptr = pool->free_list + pool->free_offset;
        pool->free_offset += size;
        pool->free_size -= size;
    } else {
        // allocate new block and add it to the free list
        void *new_block = malloc(size);
        if (new_block != NULL) {
            struct memory_pool_node *new_node = (struct memory_pool_node *)new_block;
            new_node->next = pool->free_list;
            pool->free_list = new_node;
        } else {
            // handle allocation failure
        }
    }
    return ptr;
}

void memory_pool_evict(struct memory_pool *pool) {
    struct memory_pool_node *head = pool->free_list;
    size_t total_size = 0;
    while (head != NULL && head->next != NULL) {
        if (total_size >= pool->max_size / 2) {
            // evict least recently used record
            struct memory_pool_node *to_evict = head;
            total_size -= to_evict->size;
            head = head->next;
            free(to_evict);
        } else {
            head = head->next;
            total_size += head->size;
        }
    }
}
