    mgr->num_records = 0;
    mgr->records = NULL;
    pthread_mutex_init(&mgr->mutex, NULL);
}

void record_manager_insert(struct record_manager *mgr, int key, long offset) {
    pthread_mutex_lock(&mgr->mutex);
    // allocate new block and add it to the records array
    size_t new_size = mgr->num_records + 1;
    struct record *new_records = (struct record *)realloc(mgr->records, sizeof(struct record) * new_size);
    if (new_records == NULL) {
        perror("Failed to allocate memory for records");
        exit(EXIT_FAILURE);
    }
    mgr->records = new_records;
    mgr->records[mgr->num_records].key = key;
    mgr->records[mgr->num_records++].offset = offset;
    pthread_mutex_unlock(&mgr->mutex);
}

bool record_manager_contains(struct record_manager *mgr, int key) {
    bool found = false;
    pthread_mutex_lock(&mgr->mutex);
    for (size_t i = 0; i < mgr->num_records; i++) {
        if (mgr->records[i].key == key) {
            found = true;
            break;
        }
    }
    pthread_mutex_unlock(&mgr->mutex);
    return found;
}
