            metricTypes[index].refCount++;
        } else {
            // Unknown metric type encountered
            printf("Unknown metric type: %s\n", records[i].label);
        }
    }

    // Print metrics to output file
    fprintf(outputFileDesc, "CPU|Memory|IO|...\n");
    for (int i = 0; i < numRecords; i++) {
        fprintf(outputFileDesc, "%f|%d|%d|\n", values[i], records[i].value, metricTypes[records[i].index].refCount);
    }
