#include <stdlib.h>
#include <string.h>
#include <stdio.h>

// Structure to store a pointer to a string, its length, and an int value
typedef struct {
    char* str;
    size_t len;
    int val;
} StringIntPair;

// Hash table node data structure
typedef struct {
    StringIntPair* pair;
    struct hash_node* next;
} HashNode;

// Custom hash function to minimize collisions
unsigned long custom_hash(char* str) {
    unsigned long hash = 5381;
    int c;

    while ((c = *str++) != '\0') {
        hash = ((hash << 5) + hash) + c;
    }

    return hash % TABLE_SIZE;
}

// Simple collision resolution strategy to handle potential hash conflicts
void resolve_collision(HashNode* node, HashNode* prev_node) {
    // If the previous node is not null and its next pointer is not equal to the current node,
    // then there has been a collision. In this case, we link the previous node's next pointer
    // to the current node.
    if (prev_node != NULL && prev_node->next != node) {
        prev_node->next = node;
    }
}

// Function to dynamically allocate memory for an array of structures, each containing a pointer to a string, a size_t length field, and an int value
StringIntPair* alloc_string_int_pair(size_t num_pairs) {
    StringIntPair* pairs = malloc(sizeof(StringIntPair) * num_pairs);
    if (pairs == NULL) {
        printf("Memory allocation failed!\n");
        exit(1);
    }

    return pairs;
}

// Function to allocate memory for a hash table and initialize it with a custom hash function
HashTable* alloc_hash_table() {
    HashTable* table = malloc(sizeof(HashTable));
    if (table == NULL) {
        printf("Memory allocation failed!\n");
        exit(1);
    }

    // Initialize the table's nodes array to a size that can hold num_pairs elements
    table->nodes = malloc(sizeof(HashNode*) * TABLE_SIZE);
    if (table->nodes == NULL) {
        printf("Memory allocation failed!\n");
        exit(1);
    }

    // Initialize each node in the nodes array to null
    for (size_t i = 0; i < TABLE_SIZE; i++) {
        table->nodes[i] = NULL;
    }

    // Set the custom hash function and collision resolution strategy
    table->hash_func = &custom_hash;
    table->col_res_strategy = &resolve_collision;

    return table;
}

// Function to add a string-int pair to the hash table
void add_string_int_pair(HashTable* table, char* str, size_t len, int val) {
    // Calculate the hash value for the given string
    unsigned long hash = table->hash_func(str);

    // Get a pointer to the node in the nodes array that corresponds to the calculated hash value
    HashNode* node = &table->nodes[hash];

    // If the current node is not null, then there has been a collision. In this case, we recursively call
    // the add_string_int_pair function with the next node in the chain until we find an empty node.
    if (node != NULL) {
        table->col_res_strategy(node, NULL);
    }

    // Allocate memory for a new string-int pair structure and initialize it
    StringIntPair* new_pair = malloc(sizeof(StringIntPair));
    if (new_pair == NULL) {
        printf("Memory allocation failed!\n");
        exit(1);
    }

    // Set the values of the string-int pair structure
    new_pair->str = str;
    new_pair->len = len;
    new_pair->val = val;

    // Link the new node to the previous node in the chain and update the next pointer of the previous node
    if (node != NULL) {
        resolve_collision(new_pair, node);
    }

    // Set the current node to the new node
    node = new_pair;

    // Update the nodes array with the new node
    table->nodes[hash] = new_pair;
}

// Function to iterate over the string-int pairs in the hash table and update their int values
void update_string_int_pairs(HashTable* table) {
    // Iterate over all the nodes in the nodes array
    for (size_t i = 0; i < TABLE_SIZE; i++) {
        HashNode* node = &table->nodes[i];

        // If the current node is not null, then there is a string-int pair to update. In this case, we call
        // the update_string_int_pair function with the current node as its argument.
        if (node != NULL) {
            update_string_int_pair(node);
        }
    }
}

// Function to update a string-int pair's int value based on the length of its associated string
void update_string_int_pair(StringIntPair* pair) {
    // Calculate the length of the string and set it in the pair structure
    size_t len = strlen(pair->str);
    pair->len = len;

    // Update the int value based on the length of the string
    pair->val = (int)len;
}

// Function to free all allocated memory when the function is no longer needed
void free_string_int_pairs(HashTable* table) {
    for (size_t i = 0; i < TABLE_SIZE; i++) {
        HashNode* node = &table->nodes[i];
        if (node != NULL) {
            free(node);
        }
    }
}
