#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <jpeglib.h>
#include <sys/types.h>
#include <unistd.h>
#include <pthread.h>

// Define a struct to store the extracted metadata
struct jpeg_metadata {
  int width;
  int height;
  int orientation;
};

// Function to extract metadata from a JPEG image file
struct jpeg_metadata *extract_metadata(const char *filename) {
  // Open the file and create a struct to store the extracted metadata
  FILE *file = fopen(filename, "rb");
  struct jpeg_metadata *metadata = (struct jpeg_metadata *)malloc(sizeof(struct jpeg_metadata));

  // Initialize the JPEG decompression object
  jpeg_decompress_struct cinfo;
  jpeg_error_mgr jerr;
  cinfo.err = jpeg_std_error(&jerr);
  jpeg_create_decompress(&cinfo);

  // Read the file header and check for errors
  if (jpeg_read_header(&cinfo, TRUE) != JPEG_HEADER_OK) {
    // Handle error by logging a message and returning NULL
    printf("Error reading JPEG header: %s\n", jerr.msg);
    free(metadata);
    fclose(file);
    return NULL;
  }

  // Check the image orientation (landscape or portrait)
  if (cinfo.image_width > cinfo.image_height) {
    metadata->orientation = LANDSCAPE;
  } else {
    metadata->orientation = PORTRAIT;
  }

  // Extract the image width and height from the JPEG header
  metadata->width = cinfo.image_width;
  metadata->height = cinfo.image_height;

  // Release resources and close the file
  jpeg_destroy_decompress(&cinfo);
  fclose(file);

  return metadata;
}

// Function to handle concurrent requests from multiple clients
void *process_image(void *filename) {
  char *path = (char *)filename;
  struct jpeg_metadata *metadata = extract_metadata(path);

  // Handle any errors during extraction
  if (metadata == NULL) {
    printf("Error extracting metadata: %s\n", strerror(errno));
    return NULL;
  }

  // Print the extracted metadata to stdout for debugging purposes
  printf("Metadata for %s:\n", path);
  printf("Width: %d\nHeight: %d\nOrientation: %s\n", metadata->width, metadata->height, (metadata->orientation == LANDSCAPE) ? "Landscape" : "Portrait");

  // Clean up memory
  free(metadata);

  return NULL;
}

// Function to integrate with an existing image processing pipeline
void process_images(char **filenames, int num_files) {
  // Create a pool of threads to handle the requests concurrently
  pthread_t *threads = (pthread_t *)malloc(sizeof(pthread_t) * num_files);

  // Loop over the files and create a thread for each one
  int i;
  for (i = 0; i < num_files; i++) {
    pthread_create(&threads[i], NULL, process_image, filenames[i]);
  }

  // Wait for all threads to complete before returning
  int j;
  for (j = 0; j < num_files; j++) {
    pthread_join(threads[j], NULL);
  }
}
