// File processing utility using fs.promises API in JavaScript

const fs = require('fs').promises;
const path = require('path');
const { Logger } = require('logging-library'); // Optional logging framework

async function processFiles(filePaths, concurrencyLimit = 10) {
  const logger = new Logger('File Processing Utility'); // Optional logging instance
  const processedFiles = [];

  try {
    for (let i = 0; i < filePaths.length; i++) {
      // Limit concurrency to prevent memory exhaustion and improve performance
      if (processedFiles.length >= concurrencyLimit) await sleep(10);

      const filePath = filePaths[i];
      try {
        logger.info(`Processing file: ${filePath}`);
        const fileContents = await fs.readFile(filePath, 'utf8');
        processedFiles.push({ filePath, contents: fileContents });
      } catch (error) {
        if (error instanceof Error) {
          logger.error(`Error processing file ${filePath}: ${error.message}`);
          // Handle transient network failures or file access permissions issues gracefully
          await sleep(5000);
        } else {
          logger.error(`Unknown error processing file ${filePath}`, error);
          throw error;
        }
      }
    }
  } catch (error) {
    // Handle errors in the entire process gracefully
    logger.error('Error processing files', error);
  } finally {
    // Clean up any resources used by the function
  }

  return processedFiles;
}

async function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

// Testing with various file sizes and configurations
