// C code for managing dynamic memory allocation and initialization of an array of records with a custom hash function
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>
#include <assert.h>

typedef struct {
    long offset;
    int key;
    void* record_data; // Pointer to custom record structure
} Record;

// Custom hash function for the string field of the record
int hash(const char* str) {
    int hash = 0;
    while (*str != '\0') {
        hash = (hash << 5) - hash + *str++;
    }
    return hash;
}

// Function to initialize and allocate memory for an array of records
int init_records(Record* records, size_t num_records, size_t record_size) {
    // Allocate memory for the records
    records = (Record*)malloc(num_records * record_size);
    if (!records) {
        return -1;
    }

    // Initialize each record with random values
    for (int i = 0; i < num_records; i++) {
        records[i].offset = rand();
        records[i].key = rand();
        records[i].record_data = malloc(sizeof(CustomRecord));
        if (!records[i].record_data) {
            return -1;
        }
    }

    // Initialize the custom record structure with current time in milliseconds since epoch and random values for the 'int' field and 'size_t' length field
    CustomRecord* record = (CustomRecord*)records[0].record_data;
    record->timestamp = time(NULL) * 1000 + rand();
    record->int_value = rand();
    record->length = rand() % 100;
    record->string = malloc(record->length);
    if (!record->string) {
        return -1;
    }

    // Update the 'int' field of each structure based on the length of its associated string
    for (int i = 0; i < num_records; i++) {
        record = (CustomRecord*)records[i].record_data;
        records[i].int_value = strlen(record->string);
    }

    return 0;
}

// Function to free the memory allocated for an array of records
void free_records(Record* records, size_t num_records) {
    // Free the memory for each record
    for (int i = 0; i < num_records; i++) {
        free(records[i].record_data);
    }
    // Free the memory allocated for the records array
    free(records);
}

// Function to handle allocation failures gracefully and return appropriate error codes
void* safe_malloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Error: Out of memory.\n");
        exit(1);
    }
    return ptr;
}

// Function to handle freeing allocated memory and prevent leaks
void safe_free(void* ptr) {
    if (ptr) {
        free(ptr);
    }
}

