public static void ProcessFilesConcurrently(List<string> files)
{
    // Initialize variables
    int parallelismLevel = 4; // Adjust this value based on available system resources
    List<Task<string>> tasks = new List<Task<string>>();

    try
    {
        // Create a list of tasks to process the files concurrently
        foreach (string file in files)
        {
            tasks.Add(new Task<string>(() => CalculateSHA256Hash(file)));
        }

        // Start all tasks and wait for them to complete
        Task.WaitAll(tasks.ToArray());

        // Process the results from each task
        foreach (Task<string> task in tasks)
        {
            string file = task.Result;
            Console.WriteLine("File: " + file);
            Console.WriteLine("SHA-256 Hash: " + CalculateSHA256Hash(file));
        }
    }
    catch (Exception e)
    {
        Console.WriteLine("Error processing files: " + e.Message);
    }
}

public static string CalculateSHA256Hash(string filePath)
{
    // Use a stream to read the file and calculate the hash
    using (var stream = new FileStream(filePath, FileMode.Open))
    {
        SHA256 sha256 = new SHA256Managed();
        byte[] hash = sha256.ComputeHash(stream);
        return BitConverter.ToString(hash).Replace("-", "");
    }
}
