// Define the memory pool size and alignment
#define MEM_POOL_SIZE 1024*1024 // 1 MB
#define MEM_ALIGNMENT 32

// Define the data structures used to store sequence numbers, identifiers, and event records
typedef struct {
    uint64_t seq_num;
    uint16_t id;
} SequenceNumStruct;

typedef struct {
    uint16_t id;
    uint32_t value;
    float latency;
} EventRecordStruct;

// Define the data structures used to store the processed data
typedef struct {
    uint64_t seq_num;
    uint16_t id;
    uint32_t value;
    float latency;
} ProcessedDataStruct;

// Define the memory pool and alignment macros
#define MEM_POOL_BEGIN() \
    uint8_t mem_pool[MEM_POOL_SIZE] __attribute__((aligned(MEM_ALIGNMENT)));

#define MEM_POOL_END() \
    uint8_t *mem_pool_end = &mem_pool[0] + sizeof(mem_pool);

// Define the function to process and aggregate data
void processAndAggregateData(SequenceNumStruct *seq_nums, uint16_t num_seq_nums, EventRecordStruct *event_records, uint16_t num_event_records) {
    // Declare the processed data structure
    ProcessedDataStruct *processed_data = NULL;

    // Initialize the memory pool
    MEM_POOL_BEGIN();

    // Allocate memory for the processed data structure
    processed_data = (ProcessedDataStruct *)malloc(sizeof(ProcessedDataStruct) * num_seq_nums);
    if (!processed_data) {
        printf("Memory allocation failed\n");
        return;
    }

    // Allocate memory for the sequence numbers and identifiers
    uint64_t *seq_nums_mem = (uint64_t *)malloc(sizeof(uint64_t) * num_seq_nums);
    if (!seq_nums_mem) {
        printf("Memory allocation failed\n");
        return;
    }

    uint16_t *ids_mem = (uint16_t *)malloc(sizeof(uint16_t) * num_event_records);
    if (!ids_mem) {
        printf("Memory allocation failed\n");
        return;
    }

    // Initialize the sequence numbers and identifiers
    for (int i = 0; i < num_seq_nums; i++) {
        seq_nums_mem[i] = seq_nums[i].seq_num;
    }

    for (int i = 0; i < num_event_records; i++) {
        ids_mem[i] = event_records[i].id;
    }

    // Initialize the latency metrics
    float *latencies = (float *)malloc(sizeof(float) * num_seq_nums);
    if (!latencies) {
        printf("Memory allocation failed\n");
        return;
    }

    for (int i = 0; i < num_seq_nums; i++) {
        latencies[i] = -1.0f;
    }

    // Process the data and aggregate the results
    for (int i = 0; i < num_event_records; i++) {
        int seq_idx = findSeqNumIdx(seq_nums_mem, num_seq_nums, event_records[i].seq_num);
        if (seq_idx == -1) {
            printf("Sequence number not found\n");
            return;
        }

        int id_idx = findIdx(ids_mem, num_event_records, event_records[i].id);
        if (id_idx == -1) {
            printf("Identifier not found\n");
            return;
        }

        latencies[seq_idx] = getLatency(event_records[i]);
    }

    // Store the processed data in the memory pool
    for (int i = 0; i < num_seq_nums; i++) {
        if (latencies[i] == -1.0f) continue;

        processed_data[i].seq_num = seq_nums_mem[i];
        processed_data[i].id = ids_mem[i];
        processed_data[i].value = event_records[i].value;
        processed_data[i].latency = latencies[i];
    }

    // Free the memory for the sequence numbers and identifiers
    free(seq_nums_mem);
    free(ids_mem);

    // Free the memory for the latency metrics
    free(latencies);
}

// Define the function to find the index of a sequence number in the array of sequence numbers
int findSeqNumIdx(uint64_t *seq_nums, int num_seq_nums, uint64_t seq_num) {
    for (int i = 0; i < num_seq_nums; i++) {
        if (seq_nums[i] == seq_num) return i;
    }

    return -1;
}

// Define the function to find the index of an identifier in the array of identifiers
int findIdx(uint16_t *ids, int num_event_records, uint16_t id) {
    for (int i = 0; i < num_event_records; i++) {
        if (ids[i] == id) return i;
    }

    return -1;
}

// Define the function to get the latency of an event record
float getLatency(EventRecord *record) {
    // Calculate the latency based on the current time and the timestamp in the record
    return (float)(time(NULL) - record->timestamp);
}
