// Hash table structure
struct hash_table {
    // Number of records in the hash table
    size_t num_records;
    // Size of the hash table (in bytes)
    size_t size;
    // Array of records
    struct record *records;
};

// Record structure
struct record {
    long offset;
    int key;
    char *value;
};

// Hash function for keys
static unsigned int hash(int key) {
    return key % PRIME_NUMBER;
}

// Dynamic resizing strategy (increases the size of the hash table by 2x when it's full)
void resize_hash_table(struct hash_table *ht) {
    struct record **old_records = ht->records;
    size_t old_size = ht->size;
    size_t new_size = old_size * 2;
    ht->size = new_size;
    ht->records = malloc(new_size * sizeof(struct record));
    memcpy(ht->records, old_records, old_size);
    free(old_records);
}

// Insert a new 'record' into the hash table
void insert_record(struct hash_table *ht, int key) {
    // Calculate the index of the bucket where the record should be stored
    size_t idx = hash(key) % ht->size;
    struct record *new_rec = malloc(sizeof(struct record));
    new_rec->offset = rand() % RANGE;
    new_rec->key = key;
    new_rec->value = malloc(64);
    for (int i = 0; i < 64; i++) {
        new_rec->value[i] = rand() % ('z' - 'a') + 'a';
    }
    // Check if the bucket is already occupied and handle collisions by chaining
    while (ht->records[idx].key != 0) {
        idx++;
        if (idx == ht->size) {
            resize_hash_table(ht);
            idx = hash(key) % ht->size;
        }
    }
    // Insert the new record into the bucket
    ht->records[idx] = *new_rec;
    ht->num_records++;
}

// Lookup a 'record' in the hash table by its key
struct record *lookup_record(struct hash_table *ht, int key) {
    // Calculate the index of the bucket where the record should be stored
    size_t idx = hash(key) % ht->size;
    struct record *rec = &ht->records[idx];
    while (rec != NULL && rec->key != key) {
        idx++;
        if (idx == ht->size) {
            idx = 0;
        }
        rec = &ht->records[idx];
    }
    return rec;
}

// Delete a 'record' from the hash table by its key
void delete_record(struct hash_table *ht, int key) {
    // Calculate the index of the bucket where the record should be stored
    size_t idx = hash(key) % ht->size;
    struct record *rec = &ht->records[idx];
    while (rec != NULL && rec->key != key) {
        idx++;
        if (idx == ht->size) {
            idx = 0;
        }
        rec = &ht->records[idx];
    }
    // Check if the record was found and delete it
    if (rec != NULL) {
        free(rec->value);
        *rec = ht->records[--ht->num_records];
        resize_hash_table(ht);
    }
}

// Randomly populate the hash table with unique 'int' keys and set the 'long' offset of each 'record' to a random value within a specified range
void populate_hash_table(struct hash_table *ht, int range) {
    for (int i = 0; i < ht->size; i++) {
        int key = rand() % range;
        while (lookup_record(ht, key) != NULL) {
            key++;
            if (key == range) {
                key = 0;
            }
        }
        insert_record(ht, key);
    }
}
```
This code implements a dynamic, scalable hash table that supports insertion, lookup, and deletion of 'record' structures with randomized key values and string values. The hash function used is based on the key modulo a prime number, which helps to distribute keys evenly across buckets. The resize_hash_table() function handles dynamic resizing of the hash table by doubling its size when it becomes full, which allows for efficient insertion and lookup operations while maintaining reasonable memory usage. The insert_record(), lookup_record(), and delete_record() functions implement the main functionality of the hash table, including handling collisions and resizing the table as needed. The populate_hash_table() function randomly populates the hash table with unique 'int' keys and sets the 'long' offset of each 'record' to a random value within a specified range after population."]

