    if (!ptr) {
        fprintf(stderr, "Error: failed to allocate memory\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void free_memory(struct record* records, int* keys, long* offsets, int num_records) {
    free(records);
    free(keys);
    free(offsets);
