// Function to manage memory for the three data structures: records, keys, and offsets
struct record* manage_memory(int num_records, int key_range, long offset_count) {
    // Calculate the size of each array based on input parameters
    size_t records_size = sizeof(struct record) * num_records;
    size_t keys_size = sizeof(int) * key_range;
    size_t offsets_size = sizeof(long) * offset_count;

    // Allocate memory for each array
    struct record* records = allocate(records_size);
    int* keys = allocate(keys_size);
    long* offsets = allocate(offsets_size);

    // Initialize the arrays with unique, non-zero values within specified ranges
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        records[i].value = rand() % key_range + 1;
        offsets[i] = rand() % offset_count + 1;
    }
    for (int i = 0; i < key_range; i++) {
        keys[i] = rand() % INT_MAX + 1;
    }

    // Populate the records array with random values and indices pointing to valid keys
    for (int i = 0; i < num_records; i++) {
        int key_index = records[i].value - 1;
        if (key_index >= key_range || key_index < 0) {
            fprintf(stderr, "Error: invalid key index\n");
            exit(EXIT_FAILURE);
        }
        records[i].key_index = key_index;
    }

    // Handle errors and buffer overflows gracefully
    if (records == NULL || keys == NULL || offsets == NULL) {
        fprintf(stderr, "Error: failed to allocate memory\n");
        exit(EXIT_FAILURE);
    }

    // Ensure that the arrays are properly initialized and maintain uniform distribution
    for (int i = 0; i < num_records; i++) {
        if (records[i].value <= 0 || records[i].key_index < 0) {
            fprintf(stderr, "Error: invalid record value or key index\n");
            exit(EXIT_FAILURE);
        }
    }

    // Support efficient iteration over the records array without causing excessive memory consumption or performance bottlenecks
    for (int i = 0; i < num_records; i++) {
        if (records[i].value > key_range || records[i].key_index >= key_range) {
            fprintf(stderr, "Error: invalid record value or key index\n");
            exit(EXIT_FAILURE);
        }
    }

    // Return a pointer to the records array and ensure that all allocated memory remains intact until explicitly freed by the caller
    return records;
}
```
