typedef struct {
    int value;
    double timestamp;
    float weight;
} record;

void *dynamicDataProcessor(void* args) {
    // Initialize variables
    int i, j, k, num_records = DEFAULT_MAX_RECORDS;
    long* offset_array = NULL;
    int* key_array = NULL;
    record* record_array = NULL;
    char** meta_data_tags = NULL;
    struct pollfd fds[1];
    int ret, data_available;

    // Allocate memory for arrays and initialize with default values
    offset_array = malloc(sizeof(long) * num_records);
    key_array = malloc(sizeof(int) * num_records);
    record_array = malloc(sizeof(record) * num_records);
    meta_data_tags = malloc(sizeof(char*) * META_DATA_NUM);

    // Set default values for metadata tags and initialize random seed
    for (i = 0; i < META_DATA_NUM; ++i) {
        char* tag = malloc(128);
        sprintf(tag, "meta_data_%d", i + 1);
        meta_data_tags[i] = tag;
    }
    srand(time(NULL));

    // Open input stream and set up poll() for data availability checking
    fds[0].fd = open(INPUT_STREAM, O_RDONLY);
    fds[0].events = POLLIN;
    ret = poll(fds, 1, -1);
    if (ret < 0) {
        perror("poll()");
        exit(EXIT_FAILURE);
    } else if (ret == 0) {
        fprintf(stderr, "Timeout waiting for input data\n");
        exit(EXIT_FAILURE);
    }

    // Read and process input data until EOF is reached
    while ((data_available = read(fds[0].fd, offset_array, sizeof(long) * num_records)) > 0) {
        // Allocate memory for record array and initialize its elements
        for (i = 0; i < num_records; ++i) {
            record_array[i].value = rand() % 100 + 1;
            record_array[i].timestamp = (double)time(NULL);
            record_array[i].weight = (float)(rand() % 10000) / 10000.0;
        }

        // Print metadata tags and record values to stdout
        for (i = 0; i < META_DATA_NUM; ++i) {
            fprintf(stdout, "%s\n", meta_data_tags[i]);
        }
        for (i = 0; i < num_records; ++i) {
            fprintf(stdout, "%d %f %lf %ld\n", record_array[i].value, record_array[i].weight, record_array[i].timestamp, offset_array[i]);
        }
    }

    // Free allocated memory and return
    free(offset_array);
    free(key_array);
    free(record_array);
    for (i = 0; i < META_DATA_NUM; ++i) {
        free(meta_data_tags[i]);
    }
    return NULL;
}
