// Struct to represent a point with x, y coordinates and a label
struct Point {
    double x;
    double y;
    char *label;
};

// Function to initialize the spatial index
struct Point **initializeSpatialIndex(int numPoints, int maxLabelLength) {
    // Allocate memory for the pointers to the point structures
    struct Point **index = (struct Point **)malloc(numPoints * sizeof(struct Point *));
    assert(index != NULL);

    // Initialize each pointer in the index to NULL
    for (int i = 0; i < numPoints; i++) {
        index[i] = NULL;
    }

    // Allocate memory for each point structure and initialize its coordinates and label
    for (int i = 0; i < numPoints; i++) {
        struct Point *point = (struct Point *)malloc(sizeof(struct Point));
        assert(point != NULL);

        point->x = (double)rand() / RAND_MAX;
        point->y = (double)rand() / RAND_MAX;
        point->label = (char *)malloc((maxLabelLength + 1) * sizeof(char));
        assert(point->label != NULL);

        for (int j = 0; j < maxLabelLength; j++) {
            point->label[j] = (char)('A' + (rand() % 26));
        }
        point->label[maxLabelLength] = '\0';

        index[i] = point;
    }

    // Randomly populate the spatial index with points, avoiding identical coordinates within a specified threshold
    int threshold = 0.1; // threshold for avoiding identical coordinates
    while (true) {
        struct Point *point1 = index[rand() % numPoints];
        struct Point *point2 = index[rand() % numPoints];

        if ((fabs(point1->x - point2->x) > threshold) && (fabs(point1->y - point2->y) > threshold)) {
            break;
        }
    }

    return index;
}

// Function to update the double value fields of all points in the spatial index with random values within a specified range
void updateDoubleValues(struct Point **index, int numPoints, double minValue, double maxValue) {
    for (int i = 0; i < numPoints; i++) {
