        index[i]->y = (double)(rand() % 1000) / 100.0;
    }
}

// Function to free the memory allocated for the spatial index
void freeSpatialIndex(struct Point **index, int numPoints) {
    // Free each point structure and its label
    for (int i = 0; i < numPoints; i++) {
        struct Point *point = index[i];
        free(point->label);
        free(point);
    }

    // Free the memory allocated for the pointers to the point structures
    free(index);
}

