    int numPoints = 100;
    int maxLabelLength = 32;
    struct Point **index = initializeSpatialIndex(numPoints, maxLabelLength);
    updateDoubleValues(index, numPoints, 0.0, 100.0);
    freeSpatialIndex(index, numPoints);
    return 0;
