#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <pthread.h>

// Log entry structure
typedef struct log_entry {
    time_t timestamp;
    char message[256];
    size_t identifier;
} log_entry_t;

// B-tree node structure
typedef struct btree_node {
    int key;
    log_entry_t *entries;
    struct btree_node *left, *right;
} btree_node_t;

// Logging framework instance
typedef struct logger {
    pthread_mutex_t mutex;
    int fd;
    int count;
    btree_node_t *root;
} logger_t;

// Initialize a new logging instance
logger_t* initialize_logger(char* filename) {
    // Open the log file for writing
    int fd = open(filename, O_CREAT | O_WRONLY | O_APPEND, 0644);
    if (fd == -1) {
        perror("Error opening log file");
        return NULL;
    }

    // Create a new logging instance
    logger_t *logger = malloc(sizeof(logger_t));
    if (!logger) {
        fprintf(stderr, "Failed to allocate memory for logging instance\n");
        close(fd);
        return NULL;
    }

    // Initialize the mutex and B-tree root node
    pthread_mutex_init(&logger->mutex, NULL);
    logger->root = malloc(sizeof(btree_node_t));
    if (!logger->root) {
        fprintf(stderr, "Failed to allocate memory for B-tree root\n");
        free(logger);
        close(fd);
        return NULL;
    }
    logger->root->key = 0;
    logger->root->left = NULL;
    logger->root->right = NULL;
    logger->count = 0;

    // Set the file descriptor and return the logging instance
    logger->fd = fd;
    return logger;
}

// Append a new log entry to the B-tree
int append_entry(logger_t *logger, time_t timestamp, char* message, size_t identifier) {
    // Acquire the mutex
    pthread_mutex_lock(&logger->mutex);

    // Create a new log entry and insert it into the B-tree
    log_entry_t *new_entry = malloc(sizeof(log_entry_t));
    if (!new_entry) {
        fprintf(stderr, "Failed to allocate memory for new log entry\n");
        pthread_mutex_unlock(&logger->mutex);
        return -1;
    }
    new_entry->timestamp = timestamp;
    strncpy(new_entry->message, message, 256);
    new_entry->identifier = identifier;
    insert_into_btree(logger, logger->root, new_entry);

    // Release the mutex and return success
    pthread_mutex_unlock(&logger->mutex);
    return 0;
}

// Insert a log entry into the B-tree
void insert_into_btree(logger_t *logger, btree_node_t *root, log_entry_t *new_entry) {
    // If the root node is null, create a new node and set it as the root
    if (!root) {
        root = malloc(sizeof(btree_node_t));
        if (!root) {
            fprintf(stderr, "Failed to allocate memory for B-tree node\n");
            return;
        }
        root->key = new_entry->timestamp;
        root->left = NULL;
        root->right = NULL;
    }

    // If the new entry's timestamp is less than the root node's key, insert on the left side
    if (new_entry->timestamp < root->key) {
        insert_into_btree(logger, root->left, new_entry);
    }

    // If the new entry's timestamp is greater than the root node's key, insert on the right side
    else if (new_entry->timestamp > root->key) {
        insert_into_btree(logger, root->right, new_entry);
    }

    // Otherwise, insert at the current level
    else {
        int index = 0;
        while (index < root->count && new_entry->timestamp > root->entries[index].timestamp) {
            index++;
        }
        if (index == root->count) {
            root->count++;
            root->entries = realloc(root->entries, sizeof(log_entry_t) * (root->count + 1));
            root->entries[index] = new_entry;
        } else {
            root->entries[index] = new_entry;
        }
    }
}

// Retrieve log entries within a specified time range
void retrieve_log_range(logger_t *logger, time_t start_time, time_t end_time) {
    // Acquire the mutex
    pthread_mutex_lock(&logger->mutex);

    // Find the first and last log entries within the specified range
    int first = 0;
    int last = logger->count - 1;
    while (first < logger->count && logger->root->entries[first].timestamp < start_time) {
        first++;
    }
    while (last >= 0 && logger->root->entries[last].timestamp > end_time) {
        last--;
    }

    // Print the log entries within the specified range
    for (int i = first; i <= last; i++) {
        printf("%s\n", logger->root->entries[i].message);
    }

    // Release the mutex and return success
    pthread_mutex_unlock(&logger->mutex);
}

// Retrieve all log entries
void retrieve_all_log(logger_t *logger) {
    // Acquire the mutex
    pthread_mutex_lock(&logger->mutex);

    // Print all log entries
    for (int i = 0; i < logger->count; i++) {
        printf("%s\n", logger->root->entries[i].message);
    }

    // Release the mutex and return success
    pthread_mutex_unlock(&logger->mutex);
}

// Delete all log entries
void delete_all_log(logger_t *logger) {
    // Acquire the mutex
    pthread_mutex_lock(&logger->mutex);

    // Free the memory used by the B-tree and set the root node to null
    free(logger->root->entries);
    logger->root->left = NULL;
    logger->root->right = NULL;
    logger->count = 0;

    // Release the mutex and return success
    pthread_mutex_unlock(&logger->mutex);
}
