void processAndTransformData(const std::vector<std::tuple<int, float, std::string>>& input) {
    // Initialize memory pool and allocate arrays for data entries and labels
    auto* memPool = new MemoryPool();
    auto* dataArray = (float*)memPool->allocate(sizeof(float) * input.size());
    auto* labelArray = (char**)memPool->allocate(sizeof(char*) * input.size());

    // Initialize timestamp and random number generator
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_real_distribution<> dis(0, 1);

    // Iterate through input data and perform transformations
    for (int i = 0; i < input.size(); ++i) {
        auto& [id, value, label] = input[i];
        dataArray[i] = value;
        labelArray[i] = strdup(label.c_str());

        // Generate random number within specified range and set as float value
        value = dis(gen);

        // Initialize timestamp in seconds since epoch
        auto now = std::chrono::duration_cast<std::chrono::seconds>(std::chrono::system_clock::now().time_since_epoch());
        dataArray[i] = (float)now.count();
    }

    // Calculate and print average of float values
    auto sum = 0.0f;
    for (int i = 0; i < input.size(); ++i) {
        sum += dataArray[i];
    }
    auto avg = sum / input.size();
    std::cout << "Average: " << avg << "\n";

    // Clean up allocated memory
    memPool->free(dataArray);
    memPool->free(labelArray);
    delete memPool;
}

// Memory pool implementation for efficient allocation and deallocation of resources
class MemoryPool {
public:
    void* allocate(size_t size) {
        // Allocate memory block from pre-existing memory pool or fall back to standard malloc if necessary
        auto* mem = new char[size];
        return mem;
    }

    void free(void* ptr) {
        // Free memory block using pre-existing memory pool or standard free if necessary
        delete[] (char*)ptr;
    }
};
