void initMemPool(struct mempool* pool, size_t capacity) {
    pool->ids = (int*)malloc(capacity * sizeof(int));
    pool->values = (float*)malloc(capacity * sizeof(float));
    pool->data = (data_t**)malloc(capacity * sizeof(data_t*));
}

// Function to add a new data object to the memory pool
void addDataObjectToPool(struct mempool* pool, int id, float value, char* identifier, bool flag) {
    // Check if there is space available in the pool
    if (pool->ids >= capacity) {
        return;
    }

    // Add new data object to the pool
    pool->ids[pool->size] = id;
    pool->values[pool->size] = value;
    pool->data[pool->size] = (data_t*)malloc(sizeof(data_t));
    pool->data[pool->size]->identifier = strdup(identifier);
