#define MAX_CONNECTIONS 1000
#define MIN_POOL_SIZE 5
#define POOL_GROWTH_FACTOR 2
#define POOL_SHRINK_FACTOR 0.75
#define RATE_LIMIT 1000
#define BURST_SUPPRESSION 10

struct connectionPool {
    int size;
    int count;
    int *connections;
};

struct connection {
    int id;
    int inUse;
    void *connectionPtr;
};

// Connection pool management functions
void initializeConnectionPool(struct connectionPool *pool) {
    pool->size = MIN_POOL_SIZE;
    pool->count = 0;
    pool->connections = (int *)malloc(pool->size * sizeof(int));
}

void expandConnectionPool(struct connectionPool *pool) {
    if (pool->count == MAX_CONNECTIONS) {
        return;
    }
    int newSize = pool->size * POOL_GROWTH_FACTOR;
    int *newConnections = (int *)malloc(newSize * sizeof(int));
    for (int i = 0; i < pool->count; i++) {
        newConnections[i] = pool->connections[i];
    }
    free(pool->connections);
    pool->connections = newConnections;
    pool->size = newSize;
}

void shrinkConnectionPool(struct connectionPool *pool) {
    if (pool->count == 0 || pool->size / POOL_SHRINK_FACTOR < MIN_POOL_SIZE) {
        return;
    }
    int newSize = pool->size / POOL_SHRINK_FACTOR;
    int *newConnections = (int *)malloc(newSize * sizeof(int));
    for (int i = 0; i < pool->count; i++) {
        newConnections[i] = pool->connections[i];
    }
    free(pool->connections);
    pool->connections = newConnections;
    pool->size = newSize;
}

void addConnectionToPool(struct connectionPool *pool, int id) {
    if (pool->count == MAX_CONNECTIONS) {
        expandConnectionPool(pool);
    }
    pool->connections[pool->count++] = id;
}

void removeConnectionFromPool(struct connectionPool *pool, int id) {
    for (int i = 0; i < pool->count; i++) {
        if (pool->connections[i] == id) {
            pool->count--;
            memmove(&pool->connections[i], &pool->connections[i + 1], sizeof(int) * (pool->count - i));
            break;
        }
    }
}

