    char* tempLogContent = (char*)malloc(preAllocSize);
    if (tempLogContent == NULL) {
        fprintf(stderr, "Failed to allocate memory for log content\n");
        return;
    }
    int* tempLineNumbers = (int*)malloc(sizeof(int) * preAllocSize);
    if (tempLineNumbers == NULL) {
        fprintf(stderr, "Failed to allocate memory for line numbers\n");
        free(tempLogContent);
        return;
    }
    struct LogEntry** tempLogEntries = (struct LogEntry**)malloc(sizeof(struct LogEntry*) * preAllocSize);
    if (tempLogEntries == NULL) {
        fprintf(stderr, "Failed to allocate memory for log entries\n");
        free(tempLogContent);
        free(tempLineNumbers);
        return;
    }
    int* tempFrequencyCounters = (int*)malloc(sizeof(int) * preAllocSize);
    if (tempFrequencyCounters == NULL) {
        fprintf(stderr, "Failed to allocate memory for frequency counters\n");
        free(tempLogContent);
        free(tempLineNumbers);
        free(tempLogEntries);
        return;
    }

    // Read log entries from standard input
    while ((readBytes = getline(&lineBuffer, &lineSize, stdin)) != -1) {
        // Add newline to the end of the line buffer if it doesn't already have one
        if (lineBuffer[readBytes - 1] != '\n') {
            lineBuffer[readBytes] = '\n';
            readBytes++;
        }

        // Tokenize the line into tokens using whitespace as delimiters
        char* token = strtok(lineBuffer, " ");
        while (token != NULL) {
            if (strcmp(token, "-") == 0) {
                // If the token is "-", add a newline to the log content and increment the line number
                tempLogContent[numLines] = '\n';
                tempLineNumbers[numLines]++;
            } else {
                // Otherwise, add the token to the log content and increment the line number
                strcpy(tempLogContent + numLines, token);
                tempLineNumbers[numLines]++;
            }
            token = strtok(NULL, " ");
        }
    }

    // Free the old memory buffers if they are no longer needed
    free(logContent);
    free(lineNumbers);
    free(logEntries);
    free(frequencyCounters);

    // Copy the new memory buffers to the output variables
    logContent = tempLogContent;
    lineNumbers = tempLineNumbers;
    logEntries = tempLogEntries;
    frequencyCounters = tempFrequencyCounters;

    // Count the number of unique lines in the log content
    int numUniqueLines = 0;
    for (int i = 0; i < numLines; i++) {
        if (frequencyCounters[i] == 1) {
            numUniqueLines++;
        }
    }

    // Allocate memory for the unique lines and their corresponding frequency counters
    char** uniqueLines = (char**)malloc(sizeof(char*) * numUniqueLines);
    int* uniqueFrequencyCounters = (int*)malloc(sizeof(int) * numUniqueLines);
    if (uniqueLines == NULL || uniqueFrequencyCounters == NULL) {
        fprintf(stderr, "Failed to allocate memory for unique lines and their frequency counters\n");
        free(logContent);
        free(lineNumbers);
        free(logEntries);
        free(frequencyCounters);
        return;
    }

    // Copy the unique lines and their corresponding frequency counters to the output variables
    int uniqueLineIndex = 0;
    for (int i = 0; i < numLines; i++) {
        if (frequencyCounters[i] == 1) {
            uniqueLines[uniqueLineIndex] = malloc(strlen(logContent + i) + 1);
            strcpy(uniqueLines[uniqueLineIndex], logContent + i);
            uniqueFrequencyCounters[uniqueLineIndex++] = frequencyCounters[i];
        }
    }

    // Print the summary of unique lines and their corresponding frequency counters to standard output
    printf("Summary of unique lines:\n");
