void parseAndAggregateMetrics(void) {
    // Declare variables for tracking network latency and retry counts
    int networkLatency = 0;
    int retryCount = 0;

    // Initialize a memory pool for dynamic allocation of metric data structures
    MetricData* metricData = malloc(sizeof(MetricData) * 10);
