        char* metric = strtok_r(configData, ",", &configData);
        if (!metric) {
            printf("Error: Could not parse metric from configuration data\n");
            free(metricData);
            return;
        }

        // Allocate a new metric data structure and populate it with the current metric's name, description, and value
        MetricData* currentMetric = malloc(sizeof(MetricData));
        if (!currentMetric) {
            printf("Error: Could not allocate memory for metric %s\n", metric);
            free(metricData);
            return;
