    }

    // Print keys
    printf("Keys:\n");
    for (int i = 0; i < numKeys; i++) {
        printf("%s\n", keysArray[i]);
    }
}

// Function to handle memory allocation failures
void cleanupResources(struct metricData* metrics, int numMetrics) {
    // Free memory for struct offsets
    free(metrics);

    // Free memory for struct keys
    free(keysArray);
}

int main() {
    // Set up input parameters
    char* filename = "data.txt";
    char* apiEndpoint = "https://example.com/api";

    // Read data from file and API endpoint
    readData(filename, apiEndpoint);

    // Compute metrics
    computeMetrics();

    // Manage memory for struct offsets
    manageOffsets();

    // Manage memory for struct keys
    manageKeys();

    // Handle memory allocation failures
    cleanupResources();

    return 0;
}
