        reading->humidity = humidity;
        reading->pressure = pressure;
        strcpy(reading->sensor_id, "SensorModule-");
        strcat(reading->sensor_id, i);

        // Update the average values and highest readings for each parameter
        avg_temperature += temperature;
        avg_humidity += humidity;
        avg_pressure += pressure;
        if (temperature > highest_temperature) {
            highest_temperature = temperature;
        }
        if (humidity > highest_humidity) {
            highest_humidity = humidity;
        }
        if (pressure > highest_pressure) {
            highest_pressure = pressure;
        }
    }

    // Compute the average values and highest readings for each parameter
