    if (eventType == OPEN) {
        // Allocate memory for the new connection and initialize its status to 1
        metadata->connections = realloc(metadata->connections, sizeof(struct dbConnection) * (metadata->numConnections + 1));
        metadata->connections[metadata->numConnections].status = 1;
        metadata->connections[metadata->numConnections].errorCode = 0;
        metadata->numConnections++;
    }

    // Handle closing a connection
    if (eventType == CLOSE) {
        // Set the status of the connection to inactive and reset its error code
        for (i = 0; i < metadata->numConnections; i++) {
            if (metadata->connections[i].status) {
                metadata->connections[i].status = 0;
                metadata->connections[i].errorCode = 0;
