int evaluatePacketContent(void* packet_buffer, size_t size_limit, void* config) {
    // Check if the packet buffer is null or the size limit is 0
    if (!packet_buffer || !size_limit) {
        return -1;
    }

    // Cast the configuration object to a specific type (e.g., struct configuration)
    struct configuration* config_ptr = (struct configuration*)config;

    // Extract the necessary information from the packet buffer
    uint8_t* data = (uint8_t*)packet_buffer;
    size_t data_size = *(size_t*)data;
    uint32_t protocol = *(uint32_t*)(data + sizeof(size_t));
    uint16_t source_port = *(uint16_t*)(data + 2*sizeof(size_t));
    uint16_t destination_port = *(uint16_t*)(data + 3*sizeof(size_t));

    // Validate the packet content based on the configuration object
    if (config_ptr->protocol != protocol) {
        return -2;
    }
    if (source_port < config_ptr->min_source_port || source_port > config_ptr->max_source_port) {
        return -3;
    }
    if (destination_port < config_ptr->min_destination_port || destination_port > config_ptr->max_destination_port) {
        return -4;
    }

    // Calculate the checksum of the packet content
    uint32_t checksum = 0;
    for (size_t i = 0; i < data_size; i += sizeof(uint32_t)) {
        checksum += *(uint32_t*)(data + i);
    }

    // Return the checksum if it is within the specified range
    return (checksum >= config_ptr->min_checksum && checksum <= config_ptr->max_checksum) ? 0 : -5;
}
