        logEntries[i].timestamp = time(NULL);
        strcpy(fileMetadatas[i].filename, inputs[i]);
        fileMetadatas[i].size = inputLen;
        fileMetadatas[i].modificationTime = 0;
    }

    // Clean up the memory allocated for arrays
    free(memBuf);
    free(statusArr);
    free(logEntries);
    free(fileMetadatas);
}

