        // Handle memory usage anomalies gracefully
        printf("Memory usage exceeds the limit\n");
    }
}

// Define the function to handle edge cases such as empty input, invalid characters, and files exceeding size limits
void handleEdgeCases() {
    // Check if any of the inputs are empty or contain invalid characters
    for (size_t i = 0; i < numInputs; ++i) {
        if (inputs[i][0] == '\0' || inputs[i][strlen(inputs[i]) - 1] != '\n') {
            // Handle empty input and invalid characters gracefully
            statusArr[i] = EINVAL;
            continue;
        }
    }

    // Check if any of the files exceed the size limit
    for (size_t i = 0; i < numInputs; ++i) {
        if (fileMetadatas[i].size > MAX_FILE_SIZE) {
            // Handle file size limits gracefully
            statusArr[i] = ENOSPC;
            continue;
        }
    }
}
