// Custom data structure to hold record information
typedef struct {
    int key;
    long offset;
    int value;
} Record;

// Hash table for fast key-based lookups
struct hash_table {
    int size;
    int mask;
    Record **buckets;
};

// Custom comparison function for keys
int compare(const void *key1, const void *key2) {
    return (*(int *)key1 - *(int *)key2);
}

// Initialize the hash table with a given size and mask
void init_hash_table(struct hash_table *ht, int size, int mask) {
    ht->size = size;
    ht->mask = mask;
    ht->buckets = (Record **)malloc((size + 1) * sizeof(Record));
}

// Insert a new record into the hash table
void insert_record(struct hash_table *ht, int key, long offset, int value) {
    Record *rec = malloc(sizeof(Record));
    rec->key = key;
    rec->offset = offset;
    rec->value = value;
    ht->buckets[hash(key) & ht->mask] = rec;
}

// Lookup a record in the hash table using its key
void *lookup_record(struct hash_table *ht, int key) {
    Record *rec = ht->buckets[hash(key) & ht->mask];
    while (rec && rec->key != key) {
        rec = rec->next;
    }
    return rec ? rec : NULL;
}

// Delete a record from the hash table using its key
void delete_record(struct hash_table *ht, int key) {
    Record *rec = ht->buckets[hash(key) & ht->mask];
    while (rec && rec->next && rec->next->key != key) {
        rec = rec->next;
    }
    if (rec && rec->next && rec->next->key == key) {
        rec->next = rec->next->next;
        free(rec->next);
    }
}

// Iterate over all records in the hash table and print them to standard output
void iterate_records(struct hash_table *ht, void (*print_func)(Record *)) {
    for (int i = 0; i < ht->size; i++) {
        Record *rec = ht->buckets[i];
        while (rec) {
            print_func(rec);
            rec = rec->next;
        }
    }
}

// Free the memory allocated by the hash table
void free_hash_table(struct hash_table *ht) {
    for (int i = 0; i < ht->size + 1; i++) {
        Record *rec = ht->buckets[i];
        while (rec) {
            Record *next = rec->next;
            free(rec);
            rec = next;
        }
    }
    free(ht->buckets);
}

// Generate a random integer within the specified range
int generate_random_key(int min, int max) {
    return (rand() % (max - min + 1)) + min;
}

// Initialize records with random integer values within the specified range
void init_records(struct hash_table *ht, int min, int max) {
    for (int i = 0; i < ht->size; i++) {
        Record *rec = malloc(sizeof(Record));
        rec->key = generate_random_key(min, max);
        while (lookup_record(ht, rec->key)) {
            rec->key = generate_random_key(min, max);
        }
        rec->offset = 0;
        rec->value = 0;
        ht->buckets[i] = rec;
    }
}

// Main function for testing the hash table
int main() {
