    struct hash_table *ht = malloc(sizeof(struct hash_table));
    init_hash_table(ht, 1024, 511);

    // Insert some records into the hash table
    insert_record(ht, 1, 0, 3);
    insert_record(ht, 2, 10, 7);
    insert_record(ht, 3, 20, 11);

