// Function to dynamically allocate memory for an event
EventNode* createEvent(uint64_t timestamp, char identifier, float temperature) {
    // Allocate memory for the event node
    EventNode *event = malloc(sizeof(EventNode));
    if (event == NULL) {
        return NULL;
    }

    // Initialize the event node fields
    event->timestamp = timestamp;
    event->identifier = identifier;
    event->temperature = temperature;
    event->next = NULL;

    return event;
}

// Function to free memory for an event
void destroyEvent(EventNode *event) {
