        printf("Memory allocation failed\n");
        exit(1);
    }
}

// A function to compute and output the average temperature for a specified time window
float getAverageTemperature(EventNode *head, uint64_t startTime, uint64_t endTime) {
    // Initialize the sum of temperatures and the number of events
    float sum = 0;
    int numEvents = 0;

    // Iterate through the linked list to find events within the time window
    EventNode *current = head;
    while (current != NULL) {
        // Check if the event timestamp is within the specified range
        if (current->timestamp >= startTime && current->timestamp <= endTime) {
            sum += current->temperature;
            numEvents++;
        }

        // Advance to the next node
        current = current->next;
    }

    // Return the average temperature, or 0 if no events were found
    return numEvents == 0 ? 0 : sum / (float)numEvents;
}

