// A function to create a copy of a linked list within a specified time window
EventNode* createWindow(EventNode *head, uint64_t startTime, uint64_t endTime) {
    // Create a new linked list to store the copied events
    EventNode *window = malloc(sizeof(EventNode));
    checkAllocation(window);
    window->next = NULL;

    // Iterate through the original linked list and copy events within the time window
    EventNode *current = head;
    while (current != NULL) {
        // Check if the event timestamp is within the specified range
        if (current->timestamp >= startTime && current->timestamp <= endTime) {
            // Allocate memory for a new node and copy the event data
            EventNode *node = createEvent(current->timestamp, current->identifier, current->temperature);
            checkAllocation(node);

            // Add the copied node to the new linked list
