// Function to allocate memory for an entry
entry* alloc_entry(const char* key, size_t length) {
    // Allocate memory for the entry structure
    entry* new_entry = malloc(sizeof(entry));
    if (new_entry == NULL) {
        return NULL;
    }

    // Allocate memory for the key and copy it
    size_t key_len = strlen(key);
    char* new_key = malloc(key_len + 1);
    if (new_key == NULL) {
        free(new_entry);
        return NULL;
    }
    memcpy(new_key, key, key_len + 1);
    new_entry->key = new_key;

    // Set the length and value fields
    new_entry->length = length;
    new_entry->value = 0.0f;

    return new_entry;
}

// Function to deallocate memory for an entry
void free_entry(entry* entry) {
    // Free the key and value fields
    free(entry->key);
    free(entry);
}

// Function to update the value field of an entry by its key
int update_value(const char* key, float new_value) {
    // Find the entry with the matching key
    int i = 0;
    while (i < num_entries && strcmp(key, entries[i]->key) != 0) {
        i++;
    }

    // If the entry was found, update its value field and return success
    if (i < num_entries) {
        entries[i]->value = new_value;
        return 1;
    } else {
        return 0;
    }
}

// Function to add a new entry to the dynamic array
int add_entry(const char* key, size_t length) {
    // Allocate memory for the new entry and copy its key
    entry* new_entry = alloc_entry(key, length);
    if (new_entry == NULL) {
        return 0;
    }

    // Add the new entry to the dynamic array
    entries = realloc(entries, sizeof(entry*) * (num_entries + 1));
    if (entries == NULL) {
        free_entry(new_entry);
        return 0;
    }
    entries[num_entries] = new_entry;
    num_entries++;

    return 1;
}

// Function to delete an entry from the dynamic array by its key
int remove_entry(const char* key) {
    // Find the index of the entry with the matching key
    int i = 0;
    while (i < num_entries && strcmp(key, entries[i]->key) != 0) {
        i++;
    }

    // If the entry was found, delete it and return success
    if (i < num_entries) {
        free_entry(entries[i]);
        memmove(&entries[i], &entries[i + 1], sizeof(entry*) * (num_entries - i - 1));
        entries = realloc(entries, sizeof(entry*) * (num_entries - 1));
        num_entries--;
        return 1;
    } else {
        return 0;
    }
}

// Function to retrieve the value of an entry by its key
