    // If the entry was found, return its value field
    if (i < num_entries) {
        return entries[i]->value;
    } else {
        return -1.0f;
    }
}

// Function to print all entries in the dynamic array
void print_all() {
    for (int i = 0; i < num_entries; i++) {
        printf("%s: %f\n", entries[i]->key, entries[i]->value);
    }
}
