// Define the structure for the data to be processed
typedef struct {
    int id;
    double value;
} DataPoint;

// Define the function prototype for processing and generating reports
void processAndGenerateReport(char* input, char* output) {
    // Initialize variables
    int numDataPoints = 0;
    DataPoint* data = NULL;
    FILE* fp = NULL;
    pthread_mutex_t lock;

    // Parse the input and count the number of data points
    char* token = strtok(input, ",");
    while (token != NULL) {
        numDataPoints++;
        token = strtok(NULL, ",");
    }

    // Allocate memory for the data array
    data = malloc(numDataPoints * sizeof(DataPoint));
    if (data == NULL) {
        fprintf(stderr, "Failed to allocate memory for data\n");
        return;
    }

    // Lock the mutex before accessing shared data structures
    pthread_mutex_lock(&lock);

    // Parse the input and fill the data array
    token = strtok(input, ",");
    int i = 0;
    while (token != NULL) {
        data[i].id = atoi(token);
        token = strtok(NULL, ",");
        if (token != NULL) {
            data[i].value = atof(token);
            token = strtok(NULL, ",");
        } else {
            break;
        }
        i++;
    }

    // Unlock the mutex after accessing shared data structures
    pthread_mutex_unlock(&lock);

    // Calculate the sum of the values in the array
    double sum = 0.0;
    for (int i = 0; i < numDataPoints; i++) {
        sum += data[i].value;
    }

    // Generate a report from the data
    fp = fopen(output, "w");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open output file\n");
        return;
    }
    fprintf(fp, "The sum of the values in the array is: %lf\n", sum);
    fclose(fp);

    // Free memory for the data array
    free(data);
}
