    // Key and value of the node
    char* key;
    float value;
    // Pointer to left and right child nodes
    struct Node* left, *right;
};

// Function to allocate memory for an array of entries
Entry** allocate_entries(int num_entries) {
    Entry** entries = (Entry**)malloc(num_entries * sizeof(Entry*));
    if (!entries) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    return entries;
}

// Function to initialize a hash table
struct HashTable* initialize_hash_table() {
    struct HashTable* table = (struct HashTable*)malloc(sizeof(struct HashTable));
    if (!table) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    // Allocate memory for the array of entries
    Entry** entries = allocate_entries(INITIAL_NUM_ENTRIES);
    table->num_entries = 0;
    table->entries = entries;
    return table;
}

// Function to initialize a balanced tree
struct BalancedTree* initialize_balanced_tree() {
    struct BalancedTree* tree = (struct BalancedTree*)malloc(sizeof(struct BalancedTree));
    if (!tree) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    // Allocate memory for the root node
    struct Node* root = (struct Node*)malloc(sizeof(struct Node));
    if (!root) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    tree->num_nodes = 0;
    tree->root = root;
    return tree;
}

// Function to add an entry to the hash table or balanced tree
void add_entry(struct HashTable* table, char* key, float value) {
    // Check if the key already exists in the table
    int i;
    for (i = 0; i < table->num_entries; i++) {
        if (!strcmp(table->entries[i]->key, key)) {
            break;
        }
    }
    // If the key does not exist, add a new entry
    if (i == table->num_entries) {
        Entry* new_entry = (Entry*)malloc(sizeof(Entry));
        new_entry->key = key;
        new_entry->length = strlen(key);
        new_entry->value = value;
        table->entries[table->num_entries++] = new_entry;
    } else {
        // If the key already exists, update the value
        table->entries[i]->value = value;
    }
}

// Function to add an entry to the balanced tree
void add_entry(struct BalancedTree* tree, char* key, float value) {
    // Check if the key already exists in the tree
    struct Node* current = tree->root;
    while (current != NULL) {
        int cmp = strcmp(key, current->key);
        if (cmp < 0) {
            current = current->left;
        } else if (cmp > 0) {
            current = current->right;
        } else {
            // If the key already exists, update the value
            current->value = value;
            return;
        }
    }
    // If the key does not exist, add a new node
    struct Node* new_node = (struct Node*)malloc(sizeof(struct Node));
    new_node->key = key;
    new_node->length = strlen(key);
    new_node->value = value;
    if (tree->num_nodes == 0) {
        tree->root = new_node;
    } else {
        // Insert the node into the tree
        struct Node* parent = NULL;
        struct Node* child = tree->root;
        while (child != NULL) {
            int cmp = strcmp(key, child->key);
            if (cmp < 0) {
                parent = child;
                child = child->left;
            } else if (cmp > 0) {
                parent = child;
                child = child->right;
            } else {
                // If the key already exists, update the value
                child->value = value;
                return;
            }
        }
        new_node->parent = parent;
        if (cmp < 0) {
            parent->left = new_node;
        } else {
            parent->right = new_node;
        }
    }
}

// Function to update the value of an entry in the hash table or balanced tree
void update_entry(struct HashTable* table, char* key, float value) {
    // Check if the key exists in the table
    int i;
    for (i = 0; i < table->num_entries; i++) {
        if (!strcmp(table->entries[i]->key, key)) {
            break;
        }
    }
    // If the key does not exist, add a new entry
    if (i == table->num_entries) {
        Entry* new_entry = (Entry*)malloc(sizeof(Entry));
        new_entry->key = key;
        new_entry->length = strlen(key);
        new_entry->value = value;
        table->entries[table->num_entries++] = new_entry;
    } else {
        // If the key already exists, update the value
        table->entries[i]->value = value;
    }
}

// Function to update the value of an entry in the balanced tree
void update_entry(struct BalancedTree* tree, char* key, float value) {
    // Check if the key exists in the tree
    struct Node* current = tree->root;
    while (current != NULL) {
        int cmp = strcmp(key, current->key);
        if (cmp < 0) {
            current = current->left;
        } else if (cmp > 0) {
            current = current->right;
        } else {
            // If the key already exists, update the value
            current->value = value;
            return;
        }
    }
}

// Function to delete an entry from the hash table or balanced tree
void delete_entry(struct HashTable* table, char* key) {
    // Check if the key exists in the table
    int i;
    for (i = 0; i < table->num_entries; i++) {
        if (!strcmp(table->entries[i]->key, key)) {
            break;
        }
    }
    // If the key does not exist, do nothing
    if (i == table->num_entries) {
        return;
    } else {
        // If the key exists, delete it
        free(table->entries[i]);
        for (int j = i; j < table->num_entries - 1; j++) {
            table->entries[j] = table->entries[j + 1];
        }
        table->num_entries--;
    }
}

// Function to delete an entry from the balanced tree
void delete_entry(struct BalancedTree* tree, char* key) {
    // Check if the key exists in the tree
    struct Node* current = tree->root;
    while (current != NULL) {
        int cmp = strcmp(key, current->key);
        if (cmp < 0) {
            current = current->left;
        } else if (cmp > 0) {
            current = current->right;
        } else {
            // If the key exists, delete it
            struct Node* parent = NULL;
            struct Node* child = current;
            while (child != NULL && child->left != NULL) {
                parent = child;
                child = child->left;
            }
            if (parent == NULL) {
                tree->root = child;
            } else {
                parent->left = child;
            }
            free(current);
            return;
        }
    }
}

// Function to search for an entry in the hash table or balanced tree
int search_entry(struct HashTable* table, char* key) {
    // Check if the key exists in the table
    int i;
    for (i = 0; i < table->num_entries; i++) {
        if (!strcmp(table->entries[i]->key, key)) {
            break;
        }
    }
    // If the key does not exist, return -1
    if (i == table->num_entries) {
        return -1;
    } else {
        // If the key exists, return its value
        return table->entries[i]->value;
    }
}

// Function to search for an entry in the balanced tree
int search_entry(struct BalancedTree* tree, char* key) {
    // Check if the key exists in the tree
    struct Node* current = tree->root;
    while (current != NULL) {
        int cmp = strcmp(key, current->key);
        if (cmp < 0) {
            current = current->left;
        } else if (cmp > 0) {
            current = current->right;
        } else {
            // If the key exists, return its value
            return current->value;
        }
    }
    // If the key does not exist, return -1
    return -1;
}
