    fprintf(output, "Average temperature: %.2f\n", averageTemperature);
    fprintf(output, "Sensor with highest temperature: %d\n", sensorWithHighestTemperature);
    fprintf(output, "Time range with lowest humidity: [%ld, %ld]\n", timeRangeLowestHumidity, timeRangeHighestHumidity);
    fprintf(output, "Number of disjoint pairs: %d\n", numDisjointPairs);
