// Macros for error handling and debugging
#define ERROR_HANDLING(error) printf("Error: %s\n", strerror(error)); exit(1);
#define DEBUG_PRINT(message) printf("%s\n", message);

// Enum for data categories
enum category {
    temperature, humidity, pressure, acceleration
};

// Struct for data points
struct data_point {
    double value;
    time_t timestamp;
    enum category category;
    char label[10];
};

// Function to process and aggregate data from multiple sources
void processAndAggregateData(const char* filepaths[], size_t num_sources) {
    // Initialize variables for memory management and synchronization
    struct data_point* measurements = NULL;
    size_t total_size = 0, current_size = 0;
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    int error = 0;

    // Allocate memory for all arrays at once to minimize fragmentation and overhead
    measurements = (struct data_point*)malloc(sizeof(struct data_point) * num_sources);
    if (!measurements) {
        ERROR_HANDLING(errno);
    }

    // Loop over all file paths and process each file concurrently using threads
    for (size_t i = 0; i < num_sources; i++) {
        struct data_point* measurement_ptr = &measurements[i];
        pthread_create(&mutex, NULL, (void* (*)(void*))processDataFile, (void*)filepaths[i]);
    }

    // Wait for all threads to finish and clean up resources
    for (size_t i = 0; i < num_sources; i++) {
        pthread_join(mutex, NULL);
        free(measurements);
    }

    // Calculate average, maximum, minimum values for each category
    for (int i = 0; i < total_size; i++) {
        struct data_point* current_measurement = &measurements[i];
        switch (current_measurement->category) {
            case temperature:
                DEBUG_PRINT("Average temperature: %lf", current_measurement->value);
                break;
            case humidity:
                DEBUG_PRINT("Average humidity: %lf", current_measurement->value);
                break;
            case pressure:
                DEBUG_PRINT("Average pressure: %lf", current_measurement->value);
                break;
            case acceleration:
                DEBUG_PRINT("Average acceleration: %lf", current_measurement->value);
                break;
        }
    }
}

// Function to process a single data file and update the measurement array
void* processDataFile(const char* filepath) {
    // Initialize variables for memory management and synchronization
    FILE* file = fopen(filepath, "r");
    struct data_point* current_measurement = NULL;
    size_t total_size = 0, current_size = 0;
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    int error = 0;

    // Read data from file and update the measurement array concurrently
    while (fscanf(file, "%lf%lu%c", &current_measurement->value, &current_measurement->timestamp, current_measurement->label) != EOF) {
        pthread_mutex_lock(&mutex);
        if (!total_size || total_size == current_size) {
            measurements = (struct data_point*)realloc(measurements, sizeof(struct data_point) * (current_size + 1));
            if (!measurements) {
                ERROR_HANDLING(errno);
            }
            total_size++;
        }
        current_measurement = &measurements[current_size++];
        pthread_mutex_unlock(&mutex);
    }

    // Clean up resources and return
    fclose(file);
    return NULL;
}
