// Struct for record data
typedef struct {
    int value;
    double timestamp;
} Record;

// Function header
void processAndFindMax(int limit, callbackFunc filter) {
    // Initialize variables
    long offset = 0;
    int count = 0;
    int filteredCount = 0;
    double maxValue = INT_MIN;

    // Read records from standard input until a specified limit is reached
    while (count < limit) {
        Record* record = malloc(sizeof(Record));
        if (record == NULL) {
            fprintf(stderr, "Failed to allocate memory for record\n");
            return;
        }
        // Generate random integer value and timestamp
        record->value = rand() % limit;
        record->timestamp = time(NULL);
        // Check if the filter condition is met
        if (filter(record)) {
            // Increment filtered count
            filteredCount++;
            // Update max value if necessary
            if (record->value > maxValue) {
                maxValue = record->value;
            }
        } else {
            // Free the record since it does not meet the filter condition
            free(record);
        }
        offset += sizeof(Record);
        count++;
    }

    // Print processing statistics
    printf("Processed %d records, filtered out %d, max value = %d\n",
           count, filteredCount, (int)maxValue);
}

// Callback function prototype
bool filter(Record* record);

