int init_config(const char* config_files[], int num_config_files) {
    // Declare variables for array of long offsets, array of int keys, and array of records
    long* offset_array = NULL;
    int* key_array = NULL;
    record_t* record_array = NULL;

    // Declare variables for section structures and their corresponding indices
    section_t* section_array = NULL;
    int num_sections = 0;

    // Loop through each configuration file and read in the settings
    for (int i = 0; i < num_config_files; i++) {
        // Open the JSON file and create a JSON object
        FILE* json_file = fopen(config_files[i], "r");
        json_t* json = json_loadf(json_file, 0, NULL);

        // Extract the root node of the JSON object and iterate through its children
        json_t* root = json_object_get(json, NULL);
        size_t num_children = json_object_size(root);
        for (int j = 0; j < num_children; j++) {
            // Get the child node and determine its type
            const char* child_name = json_object_iterkey(root, j);
            json_t* child_node = json_object_get(root, child_name);
            int child_type = json_typeof(child_node);

            // If the child node is an array of integers, allocate memory for it and populate it with values
            if (child_type == JSON_ARRAY) {
                size_t num_values = json_array_size(child_node);
                int* value_array = malloc(num_values * sizeof(int));
                for (int k = 0; k < num_values; k++) {
                    json_t* value_node = json_array_get(child_node, k);
                    assert(json_typeof(value_node) == JSON_INTEGER);
                    value_array[k] = (int)json_integer_value(value_node);
                }

                // If the child node is an array of strings, allocate memory for it and populate it with values
            } else if (child_type == JSON_ARRAY) {
                size_t num_values = json_array_size(child_node);
                char** value_array = malloc(num_values * sizeof(char*));
                for (int k = 0; k < num_values; k++) {
                    json_t* value_node = json_array_get(child_node, k);
                    assert(json_typeof(value_node) == JSON_STRING);
                    value_array[k] = strdup(json_string_value(value_node));
                }

                // If the child node is a section object, allocate memory for it and populate it with values
            } else if (child_type == JSON_OBJECT) {
                json_t* value_node = json_object_get(root, child_name);
                assert(json_typeof(value_node) == JSON_OBJECT);
                section_array[num_sections].index = num_sections;
                section_array[num_sections].name = strdup(child_name);
                num_sections++;
            }
        }
    }

    // Allocate memory for the arrays of long offsets, int keys, and records, and populate them with values
    offset_array = malloc(sizeof(long) * num_sections);
    key_array = malloc(sizeof(int) * num_sections);
    record_array = malloc(sizeof(record_t) * num_sections);
    for (int i = 0; i < num_sections; i++) {
        offset_array[i] = (long)section_array[i].index;
        key_array[i] = section_array[i].key;
        record_array[i].value = key_array[i];
        record_array[i].current_time = (double)time(NULL);
        record_array[i].rolling_average = (double)time(NULL);
    }

    // Free the memory for the JSON objects and close the files
    json_decref(json);
    fclose(json_file);

    // Return success or failure based on whether all allocations were successful
    if (offset_array != NULL && key_array != NULL && record_array != NULL) {
        return 0;
    } else {
        return 1;
    }
}
