    new_node->entry->timestamp = timestamp;
    new_node->entry->status = status;

    // Insert the new node at the beginning of the linked list
    new_node->next = *head;
    *head = new_node;
}

// Function to remove an entry from the linked list by ID
void remove_entry(node_t **head, int id) {
    // Traverse the linked list until we find the node with the given ID
