        current_node = current_node->next;
    }

    // If we found a matching node, update its entry data
    if (current_node != NULL) {
        current_node->entry->timestamp = timestamp;
        current_node->entry->status = status;
    }
}

// Function to retrieve an existing entry from the linked list by ID
