    }
}

// Function to clear the linked list by freeing all memory allocated for entries and nodes
void clear_entries(node_t **head) {
    // Traverse the linked list until we reach the end
    while (*head != NULL) {
        node_t *current_node = *head;
        *head = current_node->next;
