typedef struct {
    long offset;
    int key;
    char* key_ptr;
} record;

// Function to initialize array of records
void init_records(record** records, int num_records) {
    // Initialize array of records
    *records = (record*) malloc(num_records * sizeof(record));

    // Iterate over each record and initialize its offset, key, and key pointer
    for (int i = 0; i < num_records; i++) {
        (*records)[i].offset = 0;
        (*records)[i].key = 0;
        (*records)[i].key_ptr = NULL;
    }
}

// Function to deallocate array of records
void dealloc_records(record** records) {
    // Check if records are valid
    if (*records == NULL) {
        return;
    }

    // Deallocate memory for each record
    for (int i = 0; i < num_records; i++) {
        free((*records)[i].key_ptr);
    }

    // Deallocate memory for array of records
    free(*records);
}

// Function to process a batch of records in parallel using multiple threads
void process_batch(record** records, int num_records) {
    // Initialize array of thread data structures
    pthread_t* threads = (pthread_t*) malloc(num_records * sizeof(pthread_t));

    // Initialize mutex for protecting shared resources
    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);

    // Iterate over each record and create a thread to process it
