// Structure to represent a record in the data structure
typedef struct Record {
    int key;
    long offset;
} Record;

// Data structure to hold the records
typedef struct Records {
    // Array of pointers to records
    Record** records;
    // Number of records in the array
    size_t count;
    // Maximum number of records that can be held by the data structure
    size_t capacity;
} Records;

// Function to initialize the data structure from an external data source
Records* init_records(void* data, size_t size, size_t max_records) {
    // Allocate memory for the records array
    Record** records = (Record**)custom_malloc(sizeof(Record*) * max_records);
    if (!records) {
        fprintf(stderr, "Error: Failed to allocate memory for records array\n");
        return NULL;
    }

    // Initialize the records array with null pointers
    memset(records, 0, sizeof(Record*) * max_records);

    // Iterate over the data and add each record to the records array
    size_t i = 0;
    while (i < size) {
        Record* new_record = (Record*)custom_malloc(sizeof(Record));
        if (!new_record) {
            fprintf(stderr, "Error: Failed to allocate memory for record %lu\n", i);
            break;
        }

        // Read the key and offset from the data
        int* key = (int*)&data[i];
        long* offset = (long*)&data[i + sizeof(int)];

        new_record->key = *key;
        new_record->offset = *offset;

        // Add the record to the records array
        records[i] = new_record;

        i += 2 * sizeof(int);
    }

    // Create a new data structure to hold the records
    Records* new_records = (Records*)custom_malloc(sizeof(Records));
    if (!new_records) {
        fprintf(stderr, "Error: Failed to allocate memory for record array\n");
        return NULL;
    }

    // Initialize the records array and set the count and capacity
    new_records->records = records;
    new_records->count = i / (2 * sizeof(int));
    new_records->capacity = max_records;

    return new_records;
}

// Function to get the first element of the records array
Record* get_first_record(Records* records) {
    if (!records || !records->count) {
        fprintf(stderr, "Error: No records in the data structure\n");
        return NULL;
    }

    // Return the first element of the records array
    return records->records[0];
}

// Function to deallocate the memory used by the records data structure
void free_records(Records* records) {
    if (!records) {
        fprintf(stderr, "Error: No records in the data structure\n");
        return;
    }

    // Iterate over the records array and deallocate each record
    for (size_t i = 0; i < records->count; ++i) {
        custom_free(records->records[i]);
    }

    // Deallocate the records array
    custom_free(records->records);
}']

