    meas->sensor_type = init_sensor(rand() % 3); // rand() % 3 is used to get a random index within the range of SENSOR_TYPES
    meas->timestamp = time(NULL);

    return meas;
}

// Function to allocate and initialize memory for temperature, sensor identifiers, and measurement records
struct measurement** init_data() {
    struct measurement** data = (struct measurement**)malloc(3 * sizeof(struct measurement*));
