    // Allocate and initialize measurement records
    data[2] = (struct measurement*)malloc(sizeof(struct measurement));
    if (!data[2]) {
        free(data);
        printf("Error: Failed to allocate memory for measurement records.\n");
        return NULL;
    }
    data[2]->temperature = generate_temperature();
    data[2]->sensor_type = init_sensor(rand() % 3); // rand() % 3 is used to get a random index within the range of SENSOR_TYPES
    data[2]->timestamp = time(NULL);

    return data;
}

// Function to free memory allocated for temperature, sensor identifiers, and measurement records
void free_data(struct measurement** data) {
    if (data) {
        free(data[0]);
        free(data[1]);
        free(data[2]);
        free(data);
    }
}

// Main function to demonstrate usage of init_data() and free_data() functions
