    double timestamp;
} record_t;

typedef struct {
    long offset[];
    int keys[];
    record_t records[];
} data_t;

int processAndFindMax(data_t *data, int limit, bool (*filter)(const int)) {
    // Allocate memory for arrays containing 'long' offsets, 'int' keys, and 'record' structures
    long *offsets = malloc(limit * sizeof(long));
    int *keys = malloc(limit * sizeof(int));
    record_t *records = malloc(limit * sizeof(record_t));
    if (offsets == NULL || keys == NULL || records == NULL) {
        // Handle memory allocation failure gracefully
        return ENOMEM;
    }

    // Generate 'int' values within a specified range
    srand(time(NULL));
    for (int i = 0; i < limit; ++i) {
        offsets[i] = rand() % LIMIT;
        keys[i] = rand() % LIMIT;
        records[i].value = offsets[i];
        records[i].timestamp = time(NULL);
    }

    // Filter records based on a user-defined condition for the 'int' key
    int filtered_count = 0;
    for (int i = 0; i < limit; ++i) {
        if (!filter(keys[i])) {
            filtered_count++;
            continue;
        }
        records[filtered_count++] = records[i];
    }

    // Find the maximum value encountered
    int max_value = -1;
    for (int i = 0; i < filtered_count; ++i) {
        if (records[i].value > max_value) {
            max_value = records[i].value;
        }
    }

    // Clean up allocated memory
    free(offsets);
    free(keys);
    free(records);

    return max_value;
