    // Check if the list is full and needs to be resized
    if (logListSize >= MAX_LOG_ENTRIES) {
        // Resize the list by a factor of 2
        struct logEntry** newList = realloc(logList, sizeof(struct logEntry*) * (logListSize + logListSize / 2));
        if (!newList) {
            // Handle error
