#include <stdlib.h>
#include <string.h>

// Structure to hold a record with an int key and long offset value
typedef struct {
  int key;
  long offset;
} Record;

// Data structure to store the records
struct Records {
  // Array of pointers to Records
  Record **records;
  // Number of records in the data structure
  size_t count;
  // Total memory usage of the data structure in bytes
  size_t mem_usage;
  // Maximum number of records that can be stored in the data structure
  size_t max_count;
};

// Initializes a new Records data structure with a specified maximum capacity
struct Records* init_records(size_t max_count) {
  struct Records *records = malloc(sizeof(struct Records));
  records->records = calloc(max_count, sizeof(Record*));
  records->count = 0;
  records->mem_usage = 0;
  records->max_count = max_count;
  return records;
}

// Inserts a new record into the data structure
void insert_record(struct Records *records, int key, long offset) {
  // Check if there is enough space in the data structure to store the record
  if (records->count == records->max_count) {
    // Reallocate the array of pointers to Records with a larger size
    Record **new_records = realloc(records->records, 2 * records->max_count * sizeof(Record*));
    if (new_records == NULL) {
      // Handle out-of-memory error
      return;
    }
    records->records = new_records;
    records->max_count *= 2;
  }

  // Create a new Record and insert it into the data structure
  Record *new_record = malloc(sizeof(Record));
  new_record->key = key;
  new_record->offset = offset;
  records->records[records->count++] = new_record;
  records->mem_usage += sizeof(Record);
}

// Removes a record from the data structure based on its key
void remove_record(struct Records *records, int key) {
  // Find the index of the record with the specified key
  size_t i = 0;
  while (i < records->count && records->records[i]->key != key) {
    ++i;
  }

  if (i == records->count) {
    // Handle case where key does not exist in the data structure
    return;
  }

  // Remove the record from the data structure
  free(records->records[i]);
  memmove(&records->records[i], &records->records[i + 1], (records->count - i) * sizeof(Record*));
  records->count--;
  records->mem_usage -= sizeof(Record);
}

// Retrieves a record from the data structure based on its key
void retrieve_record(struct Records *records, int key) {
  // Find the index of the record with the specified key
  size_t i = 0;
  while (i < records->count && records->records[i]->key != key) {
    ++i;
  }

  if (i == records->count) {
    // Handle case where key does not exist in the data structure
    return NULL;
  }

  // Return a pointer to the record with the specified key
  return records->records[i];
}
