        // Initialize the float data
        for (j = 0; j < num_components; ++j) {
            data_set->float_data[j] = (float)(rand() % 100);
        }

        // Initialize the char data
        for (j = 0; j < num_components; ++j) {
            data_set->char_data[j] = (char)(rand() % 26 + 'a');
        }

        // Initialize the component data
        for (j = 0; j < num_components; ++j) {
            component_t *component = &(data_set->component_data[j]);
            component->id = rand() % 100;
            component->value = data_set->float_data[j];
        }

        // Initialize the processed data
        for (j = 0; j < num_components; ++j) {
            processed_data_t *processed_data = &(data_set->processed_data[j]);
            processed_data->value = data_set->float_data[j];
            processed_data->id = rand() % 100;
            processed_data->ref_count = 0;
        }
    }
}

// Define the function to handle potential memory allocation failures gracefully and release all allocated memory upon completion
void cleanup_data_sets(size_t num_data_sets) {
    // Free the memory for each data set
