    for (i = 0; i < num_data_sets; ++i) {
        free(data_set[i].float_data);
        free(data_set[i].char_data);
        free(data_set[i].component_data);
        free(data_set[i].processed_data);
    }

    // Free the memory for the data sets array
    free(data_sets);
}
