```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <assert.h>

// Define the data structure to represent a record in the store
typedef struct {
    int key;
    int value;
    char *str_value;
} Record;

// Global variables for managing the records and threads
static Record *records = NULL; // Array of records
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER; // Mutex to synchronize access to records
static int num_threads = 0; // Number of threads accessing the store

// Function to allocate memory for a record and initialize its fields
void init_record(Record *rec) {
    rec->key = rand() % 10000;
    rec->value = rand() % 10000;
    rec->str_value = malloc(256); // Dynamically allocate a buffer for the string value
    assert(rec->str_value != NULL);
}

// Function to free memory allocated for a record
void free_record(Record *rec) {
    if (rec->str_value != NULL) {
        free(rec->str_value);
    }
}

// Function to allocate memory for an array of records and initialize them
void init_records(int num_records, int str_len) {
    // Allocate memory for the array of records
    records = malloc(num_records * sizeof(Record));
    assert(records != NULL);

    // Initialize each record with a randomly generated key and value
    for (int i = 0; i < num_records; i++) {
        init_record(&records[i]);
    }
}

// Function to free memory allocated for an array of records
void free_records() {
    // Free the memory allocated for each record
    for (int i = 0; i < num_threads; i++) {
        free_record(&records[i]);
    }

    // Free the memory allocated for the array of records
    free(records);
}

// Function to add a new record to the store
void add_record(int key, int value, char *str_value) {
    pthread_mutex_lock(&lock);

    // Check if the key is already present in the store
    for (int i = 0; i < num_threads; i++) {
        if (records[i].key == key) {
            printf("Key already present in the store\n");
            pthread_mutex_unlock(&lock);
            return;
        }
    }

    // Allocate memory for a new record and initialize its fields
    Record *new_rec = malloc(sizeof(Record));
    assert(new_rec != NULL);
    init_record(new_rec);
    new_rec->key = key;
    new_rec->value = value;
    strcpy(new_rec->str_value, str_value);

    // Add the new record to the store
    records[num_threads++] = new_rec;

    pthread_mutex_unlock(&lock);
}

// Function to get a record from the store by its key
Record *get_record(int key) {
    pthread_mutex_lock(&lock);

    // Search for the record with the given key in the store
    for (int i = 0; i < num_threads; i++) {
        if (records[i].key == key) {
            Record *rec = &records[i];
            pthread_mutex_unlock(&lock);
            return rec;
        }
    }

    // If the record is not found, return NULL
    printf("Record with key %d not found in the store\n", key);
    pthread_mutex_unlock(&lock);
    return NULL;
}

// Function to delete a record from the store by its key
void delete_record(int key) {
    pthread_mutex_lock(&lock);

    // Search for the record with the given key in the store
    int index = -1;
    for (int i = 0; i < num_threads; i++) {
        if (records[i].key == key) {
            index = i;
            break;
        }
    }

    // If the record is found, delete it from the store
    if (index != -1) {
        free_record(&records[index]);
        records[index] = records[--num_threads];
    }

    pthread_mutex_unlock(&lock);
}

// Function to update a record in the store by its key
void update_record(int key, int value) {
    pthread_mutex_lock(&lock);

    // Search for the record with the given key in the store
    int index = -1;
    for (int i = 0; i < num_threads; i++) {
        if (records[i].key == key) {
            index = i;
            break;
        }
    }

    // If the record is found, update its value and return
    if (index != -1) {
        records[index].value = value;
        pthread_mutex_unlock(&lock);
        return;
    }

    // If the record is not found, add a new record with the given key and value
    Record *new_rec = malloc(sizeof(Record));
    assert(new_rec != NULL);
    init_record(new_rec);
    new_rec->key = key;
    new_rec->value = value;
    strcpy(new_rec->str_value, "");

    // Add the new record to the store
    records[num_threads++] = new_rec;

    pthread_mutex_unlock(&lock);
}

// Function to print all records in the store
void print_records() {
    printf("Records in the store:\n");

    // Iterate over each record and print its fields
    for (int i = 0; i < num_threads; i++) {
        Record *rec = &records[i];
        printf("Key: %d, Value: %d, String value: %s\n", rec->key, rec->value, rec->str_value);
    }
}

int main() {
    // Initialize the array of records and allocate memory for them
    init_records(1000, 256);

    // Add a new record to the store
    add_record(1, 2, "hello");

    // Get a record from the store by its key
    Record *rec = get_record(1);
    if (rec != NULL) {
        printf("Found record with key %d and value %d\n", rec->key, rec->value);
    } else {
        printf("Record not found in the store\n");
    }

    // Update a record in the store by its key
    update_record(1, 3);

    // Print all records in the store
    print_records();

    // Delete a record from the store by its key
    delete_record(1);

    // Print all records in the store again
    print_records();

    return 0;
}
```

This code creates an array of `Record` structures to store the data. The `add_record()` function adds a new record to the store, while the `get_record()` function searches for a record with a given key and returns it if found. The `update_record()` function updates a record in the store by its key, and the `delete_record()` function deletes a record from the store by its key. Finally, the `print_records()` function prints all records in the store.

In this example, we have implemented a basic CRUD (create, read, update, delete) application using an array of structures to store the data. We have also used a mutex lock to ensure thread-safety while accessing and modifying the shared data structure.']

