#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <pthread.h>
#include <semaphore.h>
#include <errno.h>
#include <stdbool.h>

// Function to handle file operations
void handleFileOperations(char* filePath, int operationType) {
    // Define a semaphore for thread synchronization
    sem_t *sem = sem_open("fileSemaphore", O_CREAT, 0644, 1);
    if (sem == SEM_FAILED) {
        perror("Error creating semaphore");
        exit(EXIT_FAILURE);
    }

    // Allocate memory for file metadata structures
    struct fileMetadata* fileMetadata = malloc(sizeof(struct fileMetadata));
    if (fileMetadata == NULL) {
        perror("Error allocating memory for file metadata");
        exit(EXIT_FAILURE);
    }

    // Initialize file metadata structures
    memset(fileMetadata, 0, sizeof(struct fileMetadata));
    fileMetadata->filePath = filePath;
    fileMetadata->operationType = operationType;

    // Lock the semaphore to synchronize threads
    if (sem_wait(sem) == -1) {
        perror("Error waiting on semaphore");
        exit(EXIT_FAILURE);
    }

    // Perform file operations based on operationType
    switch (operationType) {
        case READ:
            readFileOperation(fileMetadata);
            break;
        case WRITE:
            writeFileOperation(fileMetadata);
            break;
        default:
            printf("Invalid operation type\n");
            break;
    }

    // Unlock the semaphore
    if (sem_post(sem) == -1) {
        perror("Error posting on semaphore");
        exit(EXIT_FAILURE);
    }

    // Clean up memory allocated for file metadata
    free(fileMetadata);
}

// Function to perform read file operations
void readFileOperation(struct fileMetadata* fileMetadata) {
    // Open the file in read-only mode
    int fd = open(fileMetadata->filePath, O_RDONLY, 0644);
    if (fd == -1) {
        perror("Error opening file for reading");
        exit(EXIT_FAILURE);
    }

    // Read the contents of the file into a buffer
    char* buffer = malloc(sizeof(char) * BUFFER_SIZE);
    if (buffer == NULL) {
        perror("Error allocating memory for read buffer");
        exit(EXIT_FAILURE);
    }

    // Read the file contents into the buffer
    ssize_t bytesRead = read(fd, buffer, BUFFER_SIZE);
    if (bytesRead == -1) {
        perror("Error reading from file");
        exit(EXIT_FAILURE);
    }

    // Close the file descriptor
    close(fd);
}

// Function to perform write file operations
void writeFileOperation(struct fileMetadata* fileMetadata) {
    // Open the file in write-only mode
    int fd = open(fileMetadata->filePath, O_WRONLY, 0644);
    if (fd == -1) {
        perror("Error opening file for writing");
        exit(EXIT_FAILURE);
    }

    // Write the contents of the buffer to the file
    ssize_t bytesWritten = write(fd, fileMetadata->buffer, strlen(fileMetadata->buffer));
    if (bytesWritten == -1) {
        perror("Error writing to file");
        exit(EXIT_FAILURE);
    }

    // Close the file descriptor
    close(fd);
}

// Structure to hold file metadata
struct fileMetadata {
    char* filePath;
    int operationType;
    char* buffer;
};

#define BUFFER_SIZE 1024
```
This code defines a function `handleFileOperations` that takes two parameters: the file path and an operation type (read or write). The function creates a semaphore to synchronize threads, allocates memory for file metadata structures, initializes them, locks the semaphore, performs the file operations based on the operation type, unlocks the semaphore, frees the allocated memory, and exits.

The `readFileOperation` function opens the file in read-only mode, allocates a buffer to store the contents of the file, reads the file contents into the buffer, and closes the file descriptor. The `writeFileOperation` function opens the file in write-only mode, writes the contents of the buffer to the file, and closes the file descriptor.

The code also defines a structure called `fileMetadata` to hold file metadata, including the file path, operation type, and buffer for read and write operations. The `BUFFER_SIZE` macro is defined as 1024 to define the size of the buffer used for reading and writing files.

This code is highly modular, allowing for easy extension and modification of the functionality without affecting the overall system design.']

