int manageDatabaseConnections(char* queryString, int transactionId) {

// Initialize variables
struct dbMetadata* connectionMetadata = NULL;
bool isConnectionAvailable = false;
int connectionIndex = -1;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

// Validate input parameters
if (queryString == NULL || strlen(queryString) == 0) {
return -1; // Invalid query string
}

// Lock the mutex to synchronize access to the connection pool
pthread_mutex_lock(&lock);

// Check if a connection is available in the pool
for (int i = 0; i < MAX_CONNECTIONS; i++) {
if (!connectionPool[i].isUsed) {
connectionIndex = i;
isConnectionAvailable = true;
break;
}
}

// If no connection is available, allocate a new one
if (!isConnectionAvailable) {
// Check if the pool has reached its maximum capacity
if (connectionPoolCount >= MAX_CONNECTIONS) {
pthread_mutex_unlock(&lock);
return -2; // Pool exhausted
}

// Allocate a new connection and add it to the pool
connectionMetadata = malloc(sizeof(struct dbMetadata));
if (connectionMetadata == NULL) {
pthread_mutex_unlock(&lock);
return -3; // Memory allocation failed
}

connectionPool[connectionPoolCount].metadata = connectionMetadata;
connectionPool[connectionPoolCount].isUsed = true;
connectionPoolCount++;
}

// Update the connection metadata with the current query string and transaction ID
connectionPool[connectionIndex].metadata->queryString = malloc(strlen(queryString) + 1);
strcpy(connectionPool[connectionIndex].metadata->queryString, queryString);
connectionPool[connectionIndex].metadata->transactionId = transactionId;

// Unlock the mutex and signal the condition variable
pthread_mutex_unlock(&lock);
pthread_cond_signal(&cond);

// Return the connection index
return connectionIndex;
}']

