// Define struct item
struct item {
    double value;
    unsigned int index;
    char label[32];
};

// Define memory pool for struct items
struct mem_pool {
    size_t capacity; // number of struct items in the pool
    size_t size; // number of used struct items in the pool
    struct item* items; // pointer to array of struct items
};

// Function prototypes
void init_mem_pool(struct mem_pool* pool);
void deinit_mem_pool(struct mem_pool* pool);
void create_struct_items(struct mem_pool* pool, size_t num_items, double min_val, double max_val, unsigned int min_idx, unsigned int max_idx);
void destroy_struct_items(struct mem_pool* pool);
double calculate_average(const struct item* items, size_t start, size_t end);

// Main function
int main() {
    // Define memory pool for struct items
    struct mem_pool item_pool;
    init_mem_pool(&item_pool);

    // Set number of struct items to create and initialize their values
    size_t num_items = 1000000;
    double min_val = 0.0;
    double max_val = 100.0;
    unsigned int min_idx = 0;
    unsigned int max_idx = UINT32_MAX;
    create_struct_items(&item_pool, num_items, min_val, max_val, min_idx, max_idx);

    // Calculate and set average value for each struct item
    for (size_t i = 0; i < item_pool.size; ++i) {
        size_t start = i - 1;
        size_t end = i + 1;
        if (start < 0) {
            start = 0;
        }
        if (end >= item_pool.size) {
            end = item_pool.size - 1;
        }
        double average = calculate_average(item_pool.items, start, end);
        item_pool.items[i].value = average;
    }

    // Destroy struct items and memory pool
    destroy_struct_items(&item_pool);
    deinit_mem_pool(&item_pool);

    return 0;
}

// Initialize memory pool for struct items
void init_mem_pool(struct mem_pool* pool) {
    pool->capacity = 0;
    pool->size = 0;
    pool->items = NULL;
}

// Deinitialize memory pool for struct items
void deinit_mem_pool(struct mem_pool* pool) {
    if (pool->items != NULL) {
        free(pool->items);
        pool->items = NULL;
    }
    pool->capacity = 0;
    pool->size = 0;
}

// Create struct items and initialize their values
void create_struct_items(struct mem_pool* pool, size_t num_items, double min_val, double max_val, unsigned int min_idx, unsigned int max_idx) {
    // Check if memory pool is already initialized
    if (pool->items != NULL) {
        fprintf(stderr, "Error: Memory pool for struct items is already initialized\n");
        return;
    }

    // Allocate memory for struct items and initialize their values
    pool->capacity = num_items;
    pool->size = 0;
    pool->items = (struct item*)calloc(num_items, sizeof(struct item));
    if (pool->items == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for struct items\n");
        return;
    }
    for (size_t i = 0; i < num_items; ++i) {
        pool->items[i].value = min_val + (max_val - min_val) * ((double)rand() / RAND_MAX);
        pool->items[i].index = min_idx + (max_idx - min_idx) * ((double)rand() / RAND_MAX);
        snprintf(pool->items[i].label, 32, "Label %lu", pool->items[i].index);
    }
}

// Destroy struct items and memory pool
void destroy_struct_items(struct mem_pool* pool) {
    if (pool->items != NULL) {
        free(pool->items);
        pool->items = NULL;
    }
    pool->capacity = 0;
    pool->size = 0;
}

// Calculate and set average value for each struct item
double calculate_average(const struct item* items, size_t start, size_t end) {
    if (start < 0 || end >= pool->size) {
        return NAN;
    }
    double sum = 0.0;
    for (size_t i = start; i <= end; ++i) {
        sum += items[i].value;
    }
    return sum / (end - start + 1);
}
```
