#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

struct logEntry {
    char status;
    time_t timestamp;
};

typedef struct {
    int *content; // array of 'char' content
    int *lineNumbers; // array of 'int' line numbers
    struct logEntry *records; // array of `struct logEntry` records
    int *indices; // array of 'int' indices for managing disjoint pairs using a Union-Find data structure
} reportData;

// Function to process and generate report based on input from standard input
void processAndGenerateReport() {
    int i, j, k, l;
    int n = 0; // number of log entries
    char status; // status indicator for each log entry
    time_t timestamp; // timestamp for each log entry
    reportData data; // structure to store all the data

    // Initialize data structures
    data.content = (int *)malloc(10000 * sizeof(int));
    data.lineNumbers = (int *)malloc(10000 * sizeof(int));
    data.records = (struct logEntry *)malloc(10000 * sizeof(struct logEntry));
    data.indices = (int *)malloc(10000 * sizeof(int));
    if (!data.content || !data.lineNumbers || !data.records || !data.indices) {
        printf("Error: Failed to allocate memory for report data structures\n");
        return;
    }

    // Read input from standard input
    while (scanf("%c %ld", &status, &timestamp) != EOF) {
        data.content[n] = status;
        data.lineNumbers[n] = n + 1;
        data.records[n].status = status;
        data.records[n].timestamp = timestamp;
        n++;
    }

    // Determine disjoint pairs within the 'char' content array using a Union-Find data structure
    for (i = 0; i < n; i++) {
        for (j = i + 1; j < n; j++) {
            if (data.content[i] == data.content[j]) {
                union(data.indices, i, j);
            }
        }
    }

    // Allocate memory for and initialize an array of 'record' structures
    int numRecords = 0;
    for (i = 0; i < n; i++) {
        if (data.indices[i] != i) {
            continue;
        }
        data.records[numRecords].value = data.content[i];
        data.records[numRecords++].timestamp = timestamp;
    }

    // Handle edge cases such as empty input or invalid characters in the content array
    if (n == 0) {
        printf("Error: No input received\n");
        return;
    } else if (data.content[i] < 'a' || data.content[i] > 'z') {
        printf("Error: Invalid character in content array at index %d\n", i);
        return;
    }

    // Print report based on the processed data
    for (i = 0; i < numRecords; i++) {
        printf("%c %ld\n", data.records[i].value, data.records[i].timestamp);
    }

    // Clean up memory allocated for report data structures
    free(data.content);
    free(data.lineNumbers);
    free(data.records);
    free(data.indices);
}
