#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <assert.h>
#include <pthread.h>
#include <semaphore.h>

// Define the structure for an item
typedef struct {
    double value;
    unsigned int index;
    char label[10];
    char *description;
} Item;

// Define a global counter for the number of items created
static long total_items = 0;

// Declare a mutex for thread-safe access to the counter
static pthread_mutex_t counter_mutex = PTHREAD_MUTEX_INITIALIZER;

// Declare a semaphore for waiting on memory allocation
static semaphore_t memory_semaphore;

// Define a function to initialize and allocate memory for an array of items
int allocate_and_init_items(size_t num_items, double min_value, double max_value, const char **labels, size_t label_count) {
    // Validate input parameters
    if (num_items == 0 || min_value >= max_value || labels == NULL || label_count == 0) {
        return -1;
    }

    // Initialize the memory semaphore for waiting on memory allocation
    semaphore_init(&memory_semaphore, 0);

    // Declare variables to store the pointers to the arrays and their sizes
    Item **items = NULL;
    size_t items_size = 0;

    // Allocate memory for the array of items
    items = (Item **)malloc(sizeof(Item *) * num_items);
    if (items == NULL) {
        semaphore_destroy(&memory_semaphore);
        return -1;
    }
    items_size = sizeof(Item) * num_items;

    // Allocate memory for the array of labels
    char **labels_array = (char **)malloc(sizeof(char *) * label_count);
    if (labels_array == NULL) {
        free(items);
        semaphore_destroy(&memory_semaphore);
        return -1;
    }

    // Initialize the labels array with the given labels
    for (size_t i = 0; i < label_count; i++) {
        labels_array[i] = strdup(labels[i]);
    }

    // Fill the items array with random values, indices, and labels
    for (size_t i = 0; i < num_items; i++) {
        // Generate a random value within the specified range
        double value = min_value + ((double)rand() / RAND_MAX) * (max_value - min_value);

        // Create a new item and initialize its fields
        Item *item = (Item *)malloc(sizeof(Item));
        if (item == NULL) {
            free(items);
            free(labels_array);
            semaphore_destroy(&memory_semaphore);
            return -1;
        }
        item->value = value;
        item->index = i;
        strcpy(item->label, labels_array[i % label_count]);

        // Calculate the weighted average of its neighboring values (if they exist)
        double weighted_sum = 0.0;
        if (i > 0 && i < num_items - 1) {
            Item *prev_item = items[i - 1];
            Item *next_item = items[i + 1];
            double prev_weight = 0.5, next_weight = 0.5;
            weighted_sum += (prev_item->value * prev_weight) + (next_item->value * next_weight);
        } else if (i == 0 && i < num_items - 1) {
            Item *next_item = items[i + 1];
            double weight = 0.5;
            weighted_sum += (next_item->value * weight);
        } else if (i > 0 && i == num_items - 1) {
            Item *prev_item = items[i - 1];
            double weight = 0.5;
            weighted_sum += (prev_item->value * weight);
        }
        item->description = malloc(strlen(item->label) + 20);
        if (item->description == NULL) {
            free(items);
            free(labels_array);
            semaphore_destroy(&memory_semaphore);
            return -1;
        }
        sprintf(item->description, "%s%lu", item->label, i + 1);

        // Add the new item to the array of items and increment the total number of items created
        items[i] = item;
        pthread_mutex_lock(&counter_mutex);
        total_items++;
        pthread_mutex_unlock(&counter_mutex);
    }

    // Clean up the labels array and return the pointer to the items array
    for (size_t i = 0; i < label_count; i++) {
        free(labels_array[i]);
    }
    free(labels_array);
    semaphore_destroy(&memory_semaphore);
    return items;
}

// Define a function to retrieve the total number of items created
long get_total_items() {
    pthread_mutex_lock(&counter_mutex);
    long total = total_items;
    pthread_mutex_unlock(&counter_mutex);
    return total;
}
```
This code defines a function `allocate_and_init_items` that dynamically allocates memory for and initializes four arrays: one for `double` precision floating-point numbers, another for `unsigned long` identifiers, a third for `struct item` objects, and a fourth for strings representing the labels. The function takes in a number of items to allocate memory for, a minimum value, a maximum value, an array of labels, and a flag indicating whether to use the default label if no labels are provided.

The function first allocates memory for the arrays using `malloc`. If any allocation fails, it cleans up any allocated memory and returns -1.

Next, it fills the items array with random values, indices, and labels. It calculates the weighted average of its neighboring values (if they exist) and creates a string representing the label and index using `sprintf`. If any allocation for the description field fails, it cleans up any allocated memory and returns -1.

Finally, it increments the total number of items created and returns a pointer to the items array.

The function `get_total_items` returns the total number of items created by the `allocate_and_init_items` function. It locks the mutex using `pthread_mutex_lock`, gets the value of the total number of items, and then unlocks the mutex using `pthread_mutex_unlock`.

Note that this code uses a pthreads mutex to synchronize access to the total number of items created. This is necessary because multiple threads may be calling the `allocate_and_init_items` function simultaneously, and we want to ensure that the total number of items created is accurate across all threads.']

