    time_t start_time;
} Session;

// Function to dynamically manage and initialize structures
int initStructures(Person* persons, int numPersons, Activity* activities, int numActivities, Session* sessions, int numSessions) {
    // Check input parameters for validity
    if (persons == NULL || numPersons <= 0 || activities == NULL || numActivities <= 0 || sessions == NULL || numSessions <= 0) {
        return -1;
    }

    // Initialize memory for persons and assign unique IDs
    Person* tempPerson = persons;
    for (int i = 0; i < numPersons; i++) {
        tempPerson->id = i + 1;
        tempPerson++;
    }

    // Allocate memory for activities and link them to corresponding persons
    Activity* tempActivity = activities;
    for (int i = 0; i < numActivities; i++) {
        tempActivity->person = &persons[i];
        tempActivity++;
    }

    // Allocate memory for sessions and link them to corresponding persons
    Session* tempSession = sessions;
    for (int i = 0; i < numSessions; i++) {
        tempSession->person = &persons[i];
        tempSession++;
    }

    // Initialize start time for each session
    Session* tempSessionStartTime = sessions;
    for (int i = 0; i < numSessions; i++) {
        tempSessionStartTime->start_time = time(NULL);
        tempSessionStartTime++;
    }

    // Allocate memory for activities in each session and link them to corresponding persons
    Session* tempSessionActivities = sessions;
    for (int i = 0; i < numSessions; i++) {
        tempSessionActivities->activities = malloc(sizeof(Activity*) * numActivities);
        if (tempSessionActivities->activities == NULL) {
            return -1;
        }
        for (int j = 0; j < numActivities; j++) {
            tempSessionActivities->activities[j] = &activities[j];
        }
        tempSessionActivities++;
    }

    // Clean up temporary memory
    free(tempPerson);
    free(tempActivity);
    free(tempSession);
    free(tempSessionStartTime);

    return 0;
}

// Example usage:
int main() {
    int numPersons = 5;
    int numActivities = 10;
    int numSessions = 2;

    // Allocate memory for structures
    Person* persons = malloc(sizeof(Person) * numPersons);
    Activity* activities = malloc(sizeof(Activity) * numActivities);
    Session* sessions = malloc(sizeof(Session) * numSessions);

    // Initialize structures
    initStructures(persons, numPersons, activities, numActivities, sessions, numSessions);

    return 0;
}
