#define MAX_POOL_SIZE 1024

// Define the initial size of the thread pool
#define INITIAL_POOL_SIZE 8

// Define the maximum number of threads in the pool
#define MAX_THREADS 64

// Define the minimum number of threads in the pool
#define MIN_THREADS 1

// Define the time to wait for a thread to terminate before forcing its termination
#define TERMINATION_TIMEOUT 5000

// Define the interval at which to check the load and adjust the pool size
#define POOL_SIZE_CHECK_INTERVAL 1000

// Define the maximum number of buffers in the memory buffer pool
#define MAX_BUFFER_COUNT 1024

// Define the initial size of each buffer in the memory buffer pool
