// Define the minimum size of each network socket in the socket pool
#define MIN_SOCKET_SIZE 512

// Define the flag to indicate whether the pool is initialized
static bool poolInitialized = false;

// Define the mutex to protect the thread pool and memory buffer pool
static pthread_mutex_t poolMutex = PTHREAD_MUTEX_INITIALIZER;

// Define the condition variable to signal when a new thread is available in the thread pool
static pthread_cond_t newThreadAvailableCond = PTHREAD_COND_INITIALIZER;

// Define the array of threads in the thread pool
static pthread_t *threads = NULL;

// Define the current size of the thread pool
static int threadCount = 0;

// Define the maximum number of threads in the thread pool
static int maxThreads = MAX_THREADS;

// Define the minimum number of threads in the thread pool
static int minThreads = MIN_THREADS;

// Define the array of buffers in the memory buffer pool
static char **buffers = NULL;

// Define the current size of the memory buffer pool
static int bufferCount = 0;

// Define the maximum number of buffers in the memory buffer pool
