// Define the flag to indicate whether the memory buffer pool is initialized
static bool buffersInitialized = false;

// Define the flag to indicate whether the socket pool is initialized
static bool socketsInitialized = false;

// Define the function to initialize the thread pool and memory buffer pool
void manageDynamicResourcePool(int initialSize) {
  // Check if the pool is already initialized
  if (poolInitialized) {
    return;
  }

  // Initialize the thread pool with the specified size
  threads = malloc(initialSize * sizeof(pthread_t));
  threadCount = initialSize;
  maxThreads = MAX_THREADS;
  minThreads = MIN_THREADS;
  pthread_mutex_init(&poolMutex, NULL);
  pthread_cond_init(&newThreadAvailableCond, NULL);

  // Initialize the memory buffer pool with the specified size and initial buffer size
  buffers = malloc(initialSize * sizeof(char*));
  bufferCount = initialSize;
  maxBufferCount = MAX_BUFFER_COUNT;
  initialBufferSize = INITIAL_BUFFER_SIZE;
  minBufferSize = MIN_BUFFER_SIZE;

  // Initialize the socket pool with the specified size and initial socket size
  sockets = malloc(initialSize * sizeof(struct sockaddr_in));
  socketCount = initialSize;
  maxSocketCount = MAX_SOCKET_COUNT;
  initialSocketSize = INITIAL_SOCKET_SIZE;
  minSocketSize = MIN_SOCKET_SIZE;

  // Set the flag to indicate that the pool is initialized
  poolInitialized = true;
}

// Define the function to resize the thread pool and memory buffer pool
void resizeDynamicResourcePool(int newSize) {
  // Check if the pool is not initialized
  if (!poolInitialized) {
    return;
  }

  // Ensure that the new size is within the bounds of the maximum and minimum sizes
  if (newSize < minThreads || newSize > maxThreads) {
    return;
  }

  // Adjust the thread pool size to the specified size
  pthread_mutex_lock(&poolMutex);
  int diff = newSize - threadCount;
  if (diff > 0) {
    for (int i = 0; i < diff; i++) {
      pthread_create(&threads[threadCount + i], NULL, workerThread, NULL);
    }
  } else if (diff < 0) {
    for (int i = 0; i > diff; i--) {
      pthread_join(threads[threadCount - i], NULL);
    }
  }
  threadCount = newSize;
  pthread_cond_broadcast(&newThreadAvailableCond);
  pthread_mutex_unlock(&poolMutex);

  // Adjust the memory buffer pool size to the specified size and initial buffer size
  buffersInitialized = true;
  bufferCount = newSize;
  maxBufferCount = MAX_BUFFER_COUNT;
  initialBufferSize = INITIAL_BUFFER_SIZE;
  minBufferSize = MIN_BUFFER_SIZE;

  // Adjust the socket pool size to the specified size and initial socket size
  socketsInitialized = true;
  socketCount = newSize;
  maxSocketCount = MAX_SOCKET_COUNT;
  initialSocketSize = INITIAL_SOCKET_SIZE;
  minSocketSize = MIN_SOCKET_SIZE;
}

// Define the function to get a thread from the thread pool
pthread_t getThread() {
  // Check if the pool is not initialized
  if (!poolInitialized) {
    return NULL;
  }

  // Lock the mutex for protecting the thread pool
  pthread_mutex_lock(&poolMutex);

  // Wait until a new thread is available in the thread pool
  while (threadCount == 0) {
    pthread_cond_wait(&newThreadAvailableCond, &poolMutex);
  }

  // Get and return a new thread from the thread pool
  int index = threadCount - 1;
  threadCount--;
  pthread_mutex_unlock(&poolMutex);
  return threads[index];
}

// Define the function to create a new memory buffer in the memory buffer pool
char* createBuffer(int size) {
  // Check if the memory buffer pool is not initialized
  if (!buffersInitialized) {
    return NULL;
  }

  // Ensure that the specified size is within the bounds of the maximum and minimum sizes
  if (size < minBufferSize || size > maxBufferSize) {
    return NULL;
  }

  // Lock the mutex for protecting the memory buffer pool
  pthread_mutex_lock(&poolMutex);

  // Wait until a new buffer is available in the memory buffer pool
  while (bufferCount == 0) {
    pthread_cond_wait(&newThreadAvailableCond, &poolMutex);
  }

  // Get and return a new memory buffer from the memory buffer pool
  int index = bufferCount - 1;
  bufferCount--;
  pthread_mutex_unlock(&poolMutex);
  return buffers[index];
}

// Define the function to create a new network socket in the socket pool
struct sockaddr_in *createSocket(int size) {
  // Check if the socket pool is not initialized
  if (!socketsInitialized) {
    return NULL;
  }

  // Ensure that the specified size is within the bounds of the maximum and minimum sizes
  if (size < minSocketSize || size > maxSocketSize) {
    return NULL;
  }

  // Lock the mutex for protecting the socket pool
  pthread_mutex_lock(&poolMutex);

  // Wait until a new socket is available in the socket pool
  while (socketCount == 0) {
    pthread_cond_wait(&newThreadAvailableCond, &poolMutex);
  }

  // Get and return a new network socket from the socket pool
  int index = socketCount - 1;
  socketCount--;
  pthread_mutex_unlock(&poolMutex);
  return sockets[index];
}

// Define the function to destroy the thread pool and memory buffer pool
void destroyDynamicResourcePool() {
  // Check if the pool is not initialized
  if (!poolInitialized) {
    return;
  }

  // Lock the mutex for protecting the thread pool
  pthread_mutex_lock(&poolMutex);

  // Destroy all threads in the thread pool
  for (int i = 0; i < threadCount; i++) {
    pthread_cancel(threads[i]);
  }

  // Destroy the memory buffer pool
  buffersInitialized = false;

  // Destroy the socket pool
  socketsInitialized = false;

  // Unlock the mutex for protecting the thread pool
  pthread_mutex_unlock(&poolMutex);
}
