    if (!pool) {
        fprintf(stderr, "Failed to allocate memory pool\n");
        return;
    }
    pool->size = 0;
    pool->numBlocks = 1;
    pool->blocks = malloc(sizeof(struct memPoolBlock));
    if (!pool->blocks) {
        fprintf(stderr, "Failed to allocate memory for blocks\n");
        return;
    }
    pool->blocks[0].size = 16 * sizeof(struct logEntry);
    pool->blocks[0].numFree = 0;
    pool->blocks[0].freeList = NULL;

