    struct report *report = malloc(sizeof(struct report));
    if (!report) {
        fprintf(stderr, "Failed to allocate memory for report\n");
        return;
    }
    report->numEntries = 0;
    report->entries = NULL;

    // Process input strings and generate report
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    for (int i = 0; i < numInputs; i++) {
        char* inputString = inputStrings[i];
        int len = strlen(inputString);
        // Check if the input string is empty or contains invalid characters
        if (len == 0 || !isValidInputString(inputString)) {
            continue;
        }
        // Allocate memory for the log entry from the memory pool
        struct logEntry* entry = (struct logEntry*)pool->blocks[0].freeList;
        if (!entry) {
            pthread_mutex_lock(&mutex);
            if (pool->size == 0) {
                // If the pool is empty, allocate a new block of memory
                struct memPoolBlock* newBlock = malloc(sizeof(struct memPoolBlock));
                if (!newBlock) {
                    fprintf(stderr, "Failed to allocate memory for new block\n");
                    return;
                }
                newBlock->size = 16 * sizeof(struct logEntry);
                newBlock->numFree = 0;
                newBlock->freeList = NULL;
                pool->blocks[pool->numBlocks++] = newBlock;
            } else {
                // If the pool is not empty, allocate memory from the top block
                entry = (struct logEntry*)pool->blocks[pool->numBlocks - 1]->freeList;
                if (!entry) {
                    fprintf(stderr, "Failed to allocate memory for log entry\n");
                    return;
                }
            }
            pthread_mutex_unlock(&mutex);
        }
        // Initialize the log entry and add it to the report
        entry->status = 'i';
        entry->timestamp = time(NULL);
        entry->severity = SEVERITY_INFO;
        report->entries = realloc(report->entries, sizeof(struct logEntry) * (report->numEntries + 1));
        if (!report->entries) {
            fprintf(stderr, "Failed to allocate memory for report entries\n");
            return;
        }
        report->entries[report->numEntries++] = *entry;
    }

    // Free the memory pool and report
    pthread_mutex_lock(&mutex);
    free(pool->blocks);
    free(pool);
    pthread_mutex_unlock(&mutex);
    free(report->entries);
    free(report);
}
