};

// Define a linked list node to store log entries
typedef struct LogNode {
    struct LogEntry* entry;
    struct LogNode* next;
} LogNode;

// Function to process and generate report from input string
void processAndGenerateReport(const char* inputString) {
    // Create a linked list to store log entries
    LogNode* head = NULL;
    LogNode* current = NULL;

    // Iterate through each line in the input string
    for (const char* line = strtok(inputString, "\n"); line != NULL; line = strtok(NULL, "\n")) {
        // Tokenize the line into status, timestamp, severity, and UUID fields
        char* token = strtok(line, " ");
        char status = *token++;
        time_t timestamp = atol(token++);
        enum severityLevel severity = *token++;
        uuid_t uuid;
        uuid_parse(token, &uuid);

        // Allocate memory for the log entry struct and initialize it
        LogEntry* newEntry = malloc(sizeof(LogEntry));
        if (newEntry == NULL) {
            printf("Error: unable to allocate memory for log entry\n");
            return;
        }
        newEntry->status = status;
        newEntry->timestamp = timestamp;
        newEntry->severity = severity;
        memcpy(&newEntry->uuid, &uuid, sizeof(uuid_t));

        // Add the log entry to the linked list
        if (head == NULL) {
            head = current = malloc(sizeof(LogNode));
            if (current == NULL) {
                printf("Error: unable to allocate memory for log node\n");
                return;
            }
            current->entry = newEntry;
            current->next = NULL;
        } else {
            current->next = malloc(sizeof(LogNode));
            if (current->next == NULL) {
                printf("Error: unable to allocate memory for log node\n");
                return;
            }
            current = current->next;
            current->entry = newEntry;
            current->next = NULL;
        }
    }

    // Generate the report by traversing the linked list and printing each entry
    printf("Report:\n");
    for (current = head; current != NULL; current = current->next) {
        LogEntry* entry = current->entry;
        printf("%c %ld %s\n", entry->status, entry->timestamp, uuid_unparse(entry->uuid));
    }
}
