typedef struct task {
    int id;
    char* description;
    struct timeval start_time;
    pthread_t thread_id;
    long priority;
    char* status_message;
} task_t;

int allocate_tasks(size_t num_tasks, task_t** tasks) {
    if (num_tasks == 0) {
        return -1;
    }

    // Allocate memory for the task array and its elements.
    *tasks = malloc(sizeof(task_t) * num_tasks);
    if (*tasks == NULL) {
        return -1;
    }

    // Initialize each task with a unique ID, start time, priority, and status message.
    for (size_t i = 0; i < num_tasks; i++) {
        (*tasks)[i].id = i + 1;
        gettimeofday(&((*tasks)[i].start_time), NULL);
        (*tasks)[i].priority = 0;
        (*tasks)[i].status_message = "init";
    }

    return num_tasks;
}

void free_tasks(task_t** tasks) {
    if (*tasks != NULL) {
        for (size_t i = 0; i < *num_tasks; i++) {
            // Free the task's description string and status message.
            free((*tasks)[i].description);
            free((*tasks)[i].status_message);
        }

        // Free the task array itself.
        free(*tasks);
    }
}
