// Custom allocator for efficient memory management
void* my_alloc(size_t size) {
  void* ptr = malloc(size);
  if (ptr == NULL) {
    // Release as much memory as possible before exiting
    free();
    return NULL;
  }
  return ptr;
}

// Custom deallocator for efficient memory management
void my_dealloc(void* ptr) {
  free(ptr);
}

// Logging function to track memory allocations and deallocations
void log_memory(char* message, void* ptr) {
  printf("%s: %p\n", message, ptr);
}

// Function for dynamically allocating memory for a variable number of 'record' structures
int allocate_records(long min_offset, long max_offset, int prefix_len, char** unique_id_prefix) {
  // Calculate the total size required for all records
  size_t record_size = sizeof(struct record);
  size_t num_records = (max_offset - min_offset) + 1;
  size_t total_size = record_size * num_records;

  // Allocate memory for the records
  struct record* records = my_alloc(total_size);
  if (records == NULL) {
    log_memory("Memory allocation failed", records);
    return -1; // Memory allocation failure
  }
  log_memory("Allocated memory for records", records);

  // Initialize the records with unique identifiers and timestamps
  for (int i = 0; i < num_records; i++) {
    struct record* record = &records[i];
    long offset = min_offset + i;
    char* unique_id = my_alloc(prefix_len + 1); // 1 byte for null terminator
    if (unique_id == NULL) {
      log_memory("Memory allocation failed", unique_id);
      return -1; // Memory allocation failure
    }
    strcpy(unique_id, unique_id_prefix);
    strcat(unique_id, offset);
    record->offset = offset;
    record->key = i;
    record->timestamp = time(NULL) * 1000; // Convert to milliseconds since epoch
    record->unique_id = unique_id;
    log_memory("Initialized record", record);
  }

  return 0; // Successful allocation and initialization
}
```
