int allocate_records(size_t num_records, size_t min_description_length, struct record** records) {
    if (num_records == 0 || min_description_length == 0 || records == NULL) {
        return -EINVAL;
    }

    // Allocate memory for the array of records
    *records = malloc(sizeof(struct record) * num_records);
    if (*records == NULL) {
        return -ENOMEM;
    }

    struct record* curr_record = *records;
    size_t description_length;

    for (size_t i = 0; i < num_records; i++) {
        // Generate a random integer ID within the specified range
        curr_record->id = rand() % 1000 + 1;

        // Initialize the timestamp field with the current time in milliseconds since epoch
        curr_record->timestamp = (double)time(NULL) * 1000.0;

        // Determine the length of the description string to allocate
        if (strlen(description) < min_description_length) {
            description_length = min_description_length;
        } else {
            description_length = strlen(description);
        }

        // Allocate memory for the description string buffer
        curr_record->description = malloc(sizeof(char) * (description_length + 1));
        if (curr_record->description == NULL) {
            return -ENOMEM;
        }

        // Copy the predefined message into the buffer, ensuring to add a null terminator
        strncpy(curr_record->description, description, description_length);
        curr_record->description[description_length] = '\0';
    }

    return 0;
}

// Example usage:
