void initialize_arrays(int num_records, int key_range_start, int key_range_end, double timestamp_round_to, const char* metadata) {
  // Allocate memory for the arrays
  Record *records = malloc(num_records * sizeof(Record));
  Event *events = malloc(num_records * sizeof(Event));

  if (records == NULL || events == NULL) {
    printf("Error: Out of memory\n");
    return;
