    records[i].key = generate_random_key(key_range_start, key_range_end);
    records[i].timestamp = get_current_time() + fmod(rand(), timestamp_round_to);
    events[i].record = &records[i];
    if (metadata != NULL) {
      strncpy(events[i].metadata, metadata, 256);
    } else {
      strcpy(events[i].metadata, "No metadata provided");
    }
  }
}

int generate_random_key(int min, int max) {
  // Generate a random integer within the specified range
  return rand() % (max - min + 1) + min;
