    *records = (record **)malloc(sizeof(record *) * MAX_RECORD_SIZE);
    if (*records == NULL) {
        free(*offsets);
        free(*keys);
        return 3;
    }
    // Initialize the offset and key arrays
    for (int i = 0; i < MAX_OFFSET_SIZE; i++) {
        (*offsets)[i] = 0;
    }
    for (int i = 0; i < MAX_KEY_SIZE; i++) {
        (*keys)[i] = 0;
    }
    // Initialize the record array
    for (int i = 0; i < MAX_RECORD_SIZE; i++) {
        (*records)[i] = NULL;
    }
    return 0;
}

int insert_record(long *offsets, int *keys, record ***records, int key) {
    // Find the first free slot in the offset array
    int index = -1;
    for (int i = 0; i < MAX_OFFSET_SIZE && index == -1; i++) {
        if ((*offsets)[i] == 0) {
            index = i;
        }
    }
    // If no free slot found, return error code
    if (index == -1) {
        return 4;
    }
    // Allocate memory for the new record
    (*records)[index] = (record *)malloc(sizeof(record));
    if ((*records)[index] == NULL) {
        return 5;
    }
    // Initialize the new record
    (*records)[index]->value = rand() % (MAX_INT - MIN_INT + 1) + MIN_INT;
    (*records)[index]->timestamp = (double)time(NULL);
    sprintf((*records)[index]->buffer, "Random string");
    // Update the offset and key arrays
    (*offsets)[index] = sizeof(record);
    (*keys)[key] = index;
    return 0;
}

int delete_record(long *offsets, int *keys, record ***records, int key) {
    // Find the index of the record to be deleted
    int index = -1;
    for (int i = 0; i < MAX_RECORD_SIZE && index == -1; i++) {
        if ((*offsets)[i] != 0 && (*keys)[key] == i) {
            index = i;
        }
    }
    // If no record found, return error code
    if (index == -1) {
        return 6;
    }
    // Free the memory of the deleted record
    free((*records)[index]);
    (*records)[index] = NULL;
    // Update the offset and key arrays
    (*offsets)[index] = 0;
    (*keys)[key] = -1;
    return 0;
}

int main() {
    long *offsets = NULL;
    int *keys = NULL;
    record **records = NULL;
    init_arrays(&offsets, &keys, &records);
    for (int i = 0; i < 100; i++) {
        insert_record(offsets, keys, records, i);
    }
    // Print the contents of the arrays
    printf("Offsets: ");
    for (int i = 0; i < MAX_OFFSET_SIZE; i++) {
        if ((*offsets)[i] != 0) {
            printf("%ld ", (*offsets)[i]);
        }
    }
    printf("\n");
    printf("Keys: ");
    for (int i = 0; i < MAX_KEY_SIZE; i++) {
        if ((*keys)[i] != -1) {
            printf("%d ", (*keys)[i]);
        }
    }
    printf("\n");
    printf("Records: ");
    for (int i = 0; i < MAX_RECORD_SIZE; i++) {
        if ((*records)[i] != NULL) {
            printf("%d %lf %s\n", (*records)[i]->value, (*records)[i]->timestamp, (*records)[i]->buffer);
        }
    }
    return 0;
}
