    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    // Initialize the arrays and the lock
    init_arrays(&offset_array, &key_array, &record_array);
    if (!offset_array || !key_array || !record_array) {
        fprintf(stderr, "Error: failed to allocate memory for the arrays\n");
        return EXIT_FAILURE;
    }
    pthread_mutex_lock(&lock);

    // Initialize each record in the array
    for (int i = 0; i < MAX_RECORDS; i++) {
        record_t *record = (record_t *)malloc(sizeof(record_t));
        if (!record) {
            fprintf(stderr, "Error: failed to allocate memory for record %d\n", i);
