// Define a structure to represent a transaction
typedef struct {
    char *merchant_name;
    int amount;
    time_t timestamp;
    float fee;
} transaction_t;

// Define a hash table to store the transactions
static transaction_t *transactions = NULL;

// Function to add a new transaction
int add_transaction(const char *merchant_name, int amount) {
    // Allocate memory for the new transaction
    transaction_t *new_transaction = malloc(sizeof(transaction_t));
    if (new_transaction == NULL) {
        return -1; // Memory allocation failed
    }

    // Initialize the new transaction fields
    new_transaction->merchant_name = merchant_name;
    new_transaction->amount = amount;
    new_transaction->timestamp = time(NULL);

    // Compute the transaction fee as a percentage of the amount
    float fee = (float)amount * 0.05;
    new_transaction->fee = floor(fee * 100) / 100;

    // Add the new transaction to the hash table
    int result = ht_add(&transactions, new_transaction);
    if (result < 0) {
        free(new_transaction);
        return result;
    }

    return 0;
}

// Function to remove a transaction by ID
int remove_transaction(unsigned long id) {
    // Search for the transaction in the hash table
    transaction_t *transaction = ht_get(&transactions, id);
    if (transaction == NULL) {
        return -1; // Transaction not found
    }

    // Remove the transaction from the hash table
    int result = ht_remove(&transactions, transaction);
    if (result < 0) {
        return result;
    }

    free(transaction);
    return 0;
}

// Function to update a transaction by ID
int update_transaction(unsigned long id, const char *merchant_name, int amount) {
    // Search for the transaction in the hash table
    transaction_t *transaction = ht_get(&transactions, id);
    if (transaction == NULL) {
        return -1; // Transaction not found
    }

    // Update the transaction fields
    transaction->merchant_name = merchant_name;
    transaction->amount = amount;

    // Compute the new transaction fee as a percentage of the updated amount
    float fee = (float)amount * 0.05;
    transaction->fee = floor(fee * 100) / 100;

    return 0;
}

// Function to retrieve all transactions in the hash table
transaction_t **get_transactions() {
    // Allocate memory for an array of pointers to transaction structures
    transaction_t **transactions = malloc(sizeof(transaction_t *) * ht_size(&transactions));
    if (transactions == NULL) {
        return NULL; // Memory allocation failed
    }

    // Copy the transactions from the hash table into the array
    int i = 0;
    for (ht_iterator_t it = ht_begin(transactions); !ht_end(it); ++it) {
        transactions[i++] = *it;
    }

    return transactions;
}

// Function to free all memory allocated by the hash table
void free_transactions() {
    // Free the transactions in the hash table
    for (ht_iterator_t it = ht_begin(transactions); !ht_end(it); ++it) {
        free(*it);
    }

    // Free the memory allocated for the hash table itself
    free(transactions);
}
