            break;
        }
    }
    if (i >= num_sessions) {
        perror("Session not found");
        return;
    }
    for (j = i + 1; j < num_sessions; j++) {
        sessions[j - 1] = sessions[j];
    }
    num_sessions--;

    // Release the memory allocated for the session data structure
    free(sd->session_id);
    free(sd);
}

