struct record {
    int key;
    double value;
};

typedef struct {
    char *content;
    size_t length;
} string;

void generateReportWithRecords(string input) {
    // Initialize data structures
    string *strings = (string *)malloc(sizeof(string) * input.length);
    int *keys = (int *)malloc(sizeof(int) * input.length);
    struct record *records = (struct record *)malloc(sizeof(struct record) * input.length);

    // Parse input and populate data structures
    for (size_t i = 0; i < input.length; i++) {
        strings[i].content = (char *)malloc(input.length + 1);
        keys[i] = atoi(input.content);
        records[i].value = atof(input.content);
    }

    // Manage disjoint set of elements in content array for thread safety
    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);
    size_t numThreads = sysconf(_SC_NPROCESSORS_ONLN);
    pthread_barrier_t barrier;
    pthread_barrier_init(&barrier, NULL, numThreads);
    struct record *mergedRecords = (struct record *)malloc(sizeof(struct record) * input.length);

    // Process strings in parallel using multiple threads
    size_t threadIdx;
    pthread_create(&threadIdx, NULL, &processStrings, (void *)&strings[i]);
    while (pthread_barrier_wait(&barrier) == PTHREAD_BARRIER_SERIAL_THREAD);

    // Merge records and clean up resources
    for (size_t i = 0; i < input.length; i++) {
        mergedRecords[i].key = keys[i];
        mergedRecords[i].value = records[i].value + records[i].timestamp;
    }
    free(strings);
    free(keys);
    free(records);
}

void *processStrings(void *data) {
    // Cast data to string pointer and initialize local variables
    string *input = (string *)data;
    size_t threadIdx = ((size_t *)data)[1];
    struct record *localRecords = (struct record *)malloc(sizeof(struct record) * input.length);

    // Parse string and populate local records array
    for (size_t i = 0; i < input.length; i++) {
        char *token = strtok(input[i].content, ",");
        int key = atoi(token);
        token = strtok(NULL, ",");
        double value = atof(token);
        localRecords[i].key = key;
        localRecords[i].value = value;
    }

    // Synchronize access to shared resources and merge records
    pthread_mutex_lock(&mutex);
    for (size_t i = 0; i < input.length; i++) {
        mergedRecords[i].key = localRecords[i].key;
        mergedRecords[i].value = localRecords[i].value + records[i].timestamp;
    }
    pthread_mutex_unlock(&mutex);

    // Clean up local resources
    free(localRecords);
}
