        while (token != NULL) {
            if (!isdigit(token[0]) && !isalpha(token[0])) {
                // Handle invalid data gracefully by logging errors and continuing processing where possible
                printf("Error: invalid data in line %d\n", num_lines + 1);
                token = strtok(NULL, ",");
                continue;
            }
            if (isdigit(token[0])) {
                // If the token is a double precision floating-point number, add it to the double array
                double value = atof(token);
                if (double_array == NULL) {
                    double_array = malloc((num_lines + 1) * sizeof(double));
                } else {
                    double_array = realloc(double_array, (num_lines + 1) * sizeof(double));
                }
                if (double_array == NULL) {
                    printf("Error: unable to allocate memory for double array\n");
                    break;
                }
                double_array[num_lines] = value;
            } else if (isalpha(token[0])) {
                // If the token is a string, add it to the char array
                size_t len = strlen(token);
                if (string_array == NULL) {
                    string_array = malloc((num_lines + 1) * sizeof(char*));
                } else {
                    string_array = realloc(string_array, (num_lines + 1) * sizeof(char*));
                }
                if (string_array == NULL) {
                    printf("Error: unable to allocate memory for string array\n");
                    break;
                }
                string_array[num_lines] = malloc((len + 1) * sizeof(char));
                if (string_array[num_lines] == NULL) {
                    printf("Error: unable to allocate memory for string %d\n", num_lines);
                    break;
                }
                strncpy(string_array[num_lines], token, len);
            } else if (token[0] == '{' && token[strlen(token) - 1] == '}') {
                // If the token is a struct data point, parse it and add it to the struct data point array
                size_t num_fields = strlen(token) / 2;
                char* field_tokens[num_fields];
                int i = 0;
                while ((field_tokens[i] = strsep(&token, ":")) != NULL) {
                    if (!isdigit(field_tokens[i][0]) && !isalpha(field_tokens[i][0])) {
                        printf("Error: invalid data in line %d\n", num_lines + 1);
                        break;
                    }
                    i++;
                }
                if (i == num_fields) {
                    struct data_point point = { .value = atof(field_tokens[0]), .id = atoi(field_tokens[1]), .label = strdup(field_tokens[2]) };
                    if (data_point_array == NULL) {
                        data_point_array = malloc((num_lines + 1) * sizeof(struct data_point));
                    } else {
                        data_point_array = realloc(data_point_array, (num_lines + 1) * sizeof(struct data_point));
                    }
                    if (data_point_array == NULL) {
                        printf("Error: unable to allocate memory for struct data point array\n");
                        break;
                    }
                    data_point_array[num_lines] = point;
                }
            } else {
                // Handle invalid data gracefully by logging errors and continuing processing where possible
                printf("Error: invalid data in line %d\n", num_lines + 1);
            }
            token = strtok(NULL, ",");
        }
        num_lines++;
    }

    // Close the file
    fclose(file);

    // Free any allocated memory
    if (double_array != NULL) {
        free(double_array);
    }
    if (string_array != NULL) {
        for (int i = 0; i < num_lines; i++) {
            if (string_array[i] != NULL) {
                free(string_array[i]);
            }
        }
        free(string_array);
    }
    if (data_point_array != NULL) {
        for (int i = 0; i < num_lines; i++) {
            if (data_point_array[i].label != NULL) {
                free(data_point_array[i].label);
            }
        }
        free(data_point_array);
    }
}
```
