typedef struct record {
    int value;
} record_t;

int main(int argc, char **argv) {
    // Validate user input
    if (argc != 3) {
        printf("Usage: %s <offset_size> <key_size>\n", argv[0]);
        return 1;
    }
    int offset_size = atoi(argv[1]);
    int key_size = atoi(argv[2]);
    if (offset_size <= 0 || key_size <= 0) {
        printf("Error: invalid input size\n");
        return 1;
    }

    // Dynamically allocate memory for arrays and initialize them
    long *offsets = malloc(offset_size * sizeof(long));
    int *keys = malloc(key_size * sizeof(int));
    if (!offsets || !keys) {
        printf("Error: out of memory\n");
        return 1;
    }
    for (int i = 0; i < offset_size; i++) {
        offsets[i] = i;
    }
    for (int i = 0; i < key_size; i++) {
        keys[i] = i;
    }

    // Set values of each record's int field to a random value within a specified range
    srand(time(NULL));
    for (int i = 0; i < offset_size; i++) {
        offsets[i] = rand() % 1000;
    }
    for (int i = 0; i < key_size; i++) {
        keys[i] = rand() % 1000;
    }

    // Compute hash of offset and key arrays using cryptographic hash functions
    unsigned char sha256hash[SHA256_DIGEST_LENGTH];
    SHA256(offsets, sizeof(long) * offset_size, sha256hash);
    SHA256(keys, sizeof(int) * key_size, sha256hash);

    // Create an array of record structures and initialize them with the random values
    record_t *records = malloc(offset_size * sizeof(record_t));
    if (!records) {
        printf("Error: out of memory\n");
        return 1;
    }
    for (int i = 0; i < offset_size; i++) {
        records[i].value = rand() % 1000;
    }

    // Save the initialized records to a file
    FILE *file = fopen("records.bin", "wb");
    if (!file) {
        printf("Error: failed to open file\n");
        return 1;
    }
    fwrite(records, sizeof(record_t), offset_size, file);
    fclose(file);

    // Clean up resources and exit
    free(offsets);
    free(keys);
    free(records);
    return 0;
}
