// Struct definitions for sensor data and log entries
struct sensor_data {
    float value;
    enum sensor_type type;
    char* string;
};

struct log_entry {
    struct sensor_data* sensor_data;
    time_t timestamp;
    int status_flag;
};

// Function to manage memory allocation for arrays of different types
void allocate_memory(size_t num_elements, void** data_ptr, size_t elem_size) {
    // Check if the data pointer is NULL and if it needs to be reallocated
    if (*data_ptr == NULL || *data_ptr_num_elements < num_elements) {
        // Reallocate memory for the array
        void* new_data = realloc(*data_ptr, num_elements * elem_size);
        if (new_data == NULL) {
            fprintf(stderr, "Error: Failed to allocate memory\n");
            exit(1);
        }
        // Update the data pointer and number of elements
        *data_ptr = new_data;
        *data_ptr_num_elements = num_elements;
    }
}

// Function to parse a CSV file and populate the arrays with sensor data and log entries
void parse_csv(const char* filename, struct sensor_data** sensor_data, size_t* sensor_data_num_elements, struct log_entry** log_entries, size_t* log_entries_num_elements) {
    // Open the CSV file for reading
    FILE* csv_file = fopen(filename, "r");
    if (csv_file == NULL) {
        fprintf(stderr, "Error: Failed to open CSV file\n");
        exit(1);
    }

    // Read the header row of the CSV file
    char* header = fgets(NULL, 0, csv_file);

    // Initialize variables for the number of sensor data and log entries
    size_t num_sensor_data = 0;
    size_t num_log_entries = 0;

    // Loop through each line of the CSV file
    while (fgets(NULL, 0, csv_file) != NULL) {
        // Increment the number of log entries
        num_log_entries++;

        // Allocate memory for the new log entry
        allocate_memory(num_log_entries, log_entries, sizeof(struct log_entry));

        // Parse the line into a struct sensor_data and time_t
        struct sensor_data* sensor_data = malloc(sizeof(struct sensor_data));
        time_t timestamp;
        sscanf(header, "%f,%d,%s", &sensor_data->value, &sensor_data->type, sensor_data->string);
        timestamp = strtotime(header + 10); // Skip the first 10 characters which are ",,"

        // Store the parsed data in the log entry struct
        (*log_entries)[num_log_entries - 1].sensor_data = sensor_data;
        (*log_entries)[num_log_entries - 1].timestamp = timestamp;

        // Increment the number of sensor data if it is of interest
        if ((*sensor_data).type == SENSOR_TYPE_OF_INTEREST) {
            num_sensor_data++;
        }
    }

    // Close the CSV file
    fclose(csv_file);

    // Allocate memory for the arrays of sensor data and log entries
    allocate_memory(num_sensor_data, sensor_data, sizeof(struct sensor_data));
    allocate_memory(num_log_entries, log_entries, sizeof(struct log_entry));

    // Populate the arrays with the parsed data
    for (size_t i = 0; i < num_sensor_data; i++) {
        (*sensor_data)[i] = (*log_entries)[i].sensor_data;
    }
}

// Function to filter and store only those log entries with a timestamp within the specified range
void filter_and_store_log_entries(struct log_entry** log_entries, size_t* log_entries_num_elements, time_t start_time, time_t end_time) {
    // Initialize variables for the number of filtered log entries and sensor data
    size_t num_filtered_log_entries = 0;
    size_t num_filtered_sensor_data = 0;

    // Loop through each log entry and filter based on the timestamp
    for (size_t i = 0; i < *log_entries_num_elements; i++) {
        struct log_entry* log_entry = (*log_entries)[i];
        if (log_entry->timestamp >= start_time && log_entry->timestamp <= end_time) {
            // Increment the number of filtered log entries and sensor data
            num_filtered_log_entries++;
            if ((*log_entry).sensor_data->type == SENSOR_TYPE_OF_INTEREST) {
                num_filtered_sensor_data++;
            }
        }
    }

    // Allocate memory for the filtered arrays of log entries and sensor data
    allocate_memory(num_filtered_log_entries, log_entries, sizeof(struct log_entry));
    allocate_memory(num_filtered_sensor_data, sensor_data, sizeof(struct sensor_data));

    // Populate the filtered arrays with the parsed data
    for (size_t i = 0; i < num_filtered_log_entries; i++) {
        struct log_entry* log_entry = (*log_entries)[i];
        if ((*log_entry).sensor_data->type == SENSOR_TYPE_OF_INTEREST) {
            (*sensor_data)[num_filtered_sensor_data - 1] = (*log_entry).sensor_data;
            num_filtered_sensor_data--;
        }
    }
}

// Function to free all allocated memory upon completion
void cleanup(struct sensor_data** sensor_data, size_t* sensor_data_num_elements, struct log_entry** log_entries, size_t* log_entries_num_elements) {
    // Free the arrays of log entries and sensor data
    free(*log_entries);
    free(*sensor_data);
}
```
