// Function to dynamically manage memory for arrays and initialize them with random values
int initArrays(long** offsets, int** keys, Record*** records) {
    // Allocate memory for the offset array
    *offsets = (long*)malloc(sizeof(long) * 10);
    if (*offsets == NULL) {
        return -1; // Memory allocation failed
    }

    // Initialize the offset array with random values between 0 and 100
    for (int i = 0; i < 10; i++) {
        (*offsets)[i] = rand() % 100;
    }

    // Allocate memory for the key array
    *keys = (int*)malloc(sizeof(int) * 10);
    if (*keys == NULL) {
        return -2; // Memory allocation failed
    }

    // Initialize the key array with random values between 0 and 100
    for (int i = 0; i < 10; i++) {
        (*keys)[i] = rand() % 100;
    }

    // Allocate memory for the record structure array
    *records = (Record**)malloc(sizeof(Record*) * 10);
    if (*records == NULL) {
        return -3; // Memory allocation failed
