    // Initialize each record structure with random values and a randomly generated string buffer
    for (int i = 0; i < 10; i++) {
        (*records)[i] = malloc(sizeof(Record));
        if ((*records)[i] == NULL) {
            return -4; // Memory allocation failed
        }

        (*records)[i]->key = rand() % 100;
        (*records)[i]->timestamp = (double)time(NULL);
        snprintf((*records)[i]->buffer, sizeof((*records)[i]->buffer), "Random string");
    }

    return 0; // Success
}

// Function to add a record to the linked list
int addRecord(Node** head, Record* new_record) {
    Node* temp = *head;
    while (temp->next != NULL) {
        temp = temp->next;
    }

    // Allocate memory for the new node
    temp->next = malloc(sizeof(Node));
    if (temp->next == NULL) {
        return -1; // Memory allocation failed
    }

    // Initialize the new node with the given record
    temp->next->data = new_record;
    temp->next->next = NULL;

    return 0; // Success
}

// Function to delete a record from the linked list
int delRecord(Node** head, int key) {
    Node* current = *head;
    Node* previous = NULL;

    while (current != NULL && current->data->key != key) {
        previous = current;
        current = current->next;
    }

    if (current == NULL) {
        return -1; // Record not found
    }

    if (previous == NULL) {
        *head = (*head)->next;
    } else {
        previous->next = current->next;
    }

    free(current);

    return 0; // Success
}

// Function to search for a record in the linked list
int findRecord(Node* head, int key) {
    while (head != NULL && head->data->key != key) {
        head = head->next;
    }

    if (head == NULL) {
        return -1; // Record not found
    }

    return 0; // Success
}

// Function to update a record in the linked list
int updRecord(Node* head, int key, Record* new_record) {
    Node* current = head;

    while (current != NULL && current->data->key != key) {
        current = current->next;
    }

    if (current == NULL) {
        return -1; // Record not found
    }

    // Update the record with the new data
    current->data->key = new_record->key;
    current->data->timestamp = new_record->timestamp;
    strncpy(current->data->buffer, new_record->buffer, sizeof(new_record->buffer));

    return 0; // Success
}

// Function to free the memory allocated for the arrays and linked list
void freeArrays(long* offsets, int* keys, Record** records) {
    // Free the offset array
    free(offsets);

    // Free the key array
    free(keys);

    // Free each record structure in the record array
    for (int i = 0; i < 10; i++) {
        if (records[i] != NULL) {
            free(records[i]);
        }
    }
}

// Function to print the linked list
void printList(Node* head) {
    while (head != NULL) {
        printf("Record: %d, Timestamp: %lf, Buffer: %s\n", head->data->key, head->data->timestamp, head->data->buffer);
        head = head->next;
    }
}

int main() {
    long* offsets;
    int* keys;
    Record** records;

    // Initialize the arrays and linked list
    initArrays(&offsets, &keys, &records);
    Node* head = NULL;

    // Add some records to the linked list
    addRecord(&head, records[0]);
    addRecord(&head, records[1]);
    addRecord(&head, records[2]);
    addRecord(&head, records[3]);

    // Search for a record in the linked list
    findRecord(head, keys[0]);

    // Update a record in the linked list
    updRecord(head, keys[1], records[4]);

    // Delete a record from the linked list
    delRecord(&head, keys[2]);

    // Print the linked list
    printList(head);

    // Free the memory allocated for the arrays and linked list
    freeArrays(offsets, keys, records);

    return 0;
}']

