#define MAX_RECORDS 1000000
#define MIN_INT -1000000
#define MAX_INT 1000000

typedef struct {
    int int_value;
    double timestamp;
    char *str_value;
} record;

int generate_records(record **records, int num_records) {
    // allocate memory for the arrays of offsets and keys
    long *offset_array = (long *)malloc(num_records * sizeof(long));
    if (!offset_array) {
        return -1;  // allocation failed
    }
    int *key_array = (int *)malloc(num_records * sizeof(int));
    if (!key_array) {
        free(offset_array);
        return -2;  // allocation failed
    }

    // populate the arrays of offsets and keys
    for (int i = 0; i < num_records; i++) {
        offset_array[i] = i * sizeof(record);
        key_array[i] = rand() % (MAX_INT - MIN_INT + 1) + MIN_INT;
    }

    // allocate memory for the records and populate them
    record *records_ptr = (record *)malloc(num_records * sizeof(record));
    if (!records_ptr) {
        free(offset_array);
        free(key_array);
        return -3;  // allocation failed
    }

    for (int i = 0; i < num_records; i++) {
        records_ptr[i].int_value = key_array[i];
        records_ptr[i].timestamp = (double)time(NULL);
        asprintf(&records_ptr[i].str_value, "%d", key_array[i]);
    }

    // calculate and store statistical summaries
    int min_int = INT_MAX;
    int max_int = INT_MIN;
    double avg_timestamp = 0;
    int count = 0;

    for (int i = 0; i < num_records; i++) {
        if (records_ptr[i].int_value < min_int) {
            min_int = records_ptr[i].int_value;
        }
        if (records_ptr[i].int_value > max_int) {
            max_int = records_ptr[i].int_value;
        }
        avg_timestamp += records_ptr[i].timestamp;
        count++;
    }

    // free the memory allocated for the arrays of offsets and keys
    free(offset_array);
    free(key_array);

    // store the statistical summaries in the record structures
    for (int i = 0; i < num_records; i++) {
        records_ptr[i].min_int = min_int;
        records_ptr[i].max_int = max_int;
        records_ptr[i].avg_timestamp = avg_timestamp / count;
    }

    // return the pointer to the allocated memory
    *records = records_ptr;
    return num_records;
}
