        fprintf(stderr, "Maximum number of items reached: %d\n", MAX_ITEMS);
        return;
    }

    // allocate memory for new item
    (*item_arr)[*total_items] = (item){0};
    (*item_arr)[*total_items].id = *total_items + 1;
    (*item_arr)[*total_items].value = ((float)rand() / RAND_MAX) * 10.0f;
    sprintf((*item_arr)[*total_items].label, "A%c", 'a' + (*item_arr)[*total_items].id % 26);

    // increment total number of items added
    (*total_items)++;
}

