        return -2;
    }

    // Allocate memory for the record array
    size_t num_records = num_offsets * num_keys;
    record_t* records_array = malloc(sizeof(record_t) * num_records);
    if (!records_array) {
        free(offsets);
        free(keys);
        fprintf(stderr, "Failed to allocate memory for record array\n");
        return -2;
    }

    // Initialize the offset and key arrays
    size_t i;
    for (i = 0; i < num_offsets; i++) {
        offsets[i] = rand() % 10000;
    }
    for (i = 0; i < num_keys; i++) {
        keys[i] = rand() % 100;
