                    break;
                }

                // Update the last access time and transaction ID for this connection
                connections[transactionID].lastAccessTime = time(NULL);
                transactionIDs[transactionID]++;
            }
            case ROLLBACK: {
                int transactionID = getTransactionID(); // Implement a function to retrieve the transaction ID from the incoming request
                if (transactionID < 0) {
                    fprintf(stderr, "Error: Could not retrieve transaction ID from incoming request\n");
                    break;
                }

                // Roll back the transaction and update the connection metadata accordingly
                int status = rollbackTransaction(transactionID); // Implement a function to roll back the transaction on the database
                if (status < 0) {
                    fprintf(stderr, "Error: Could not roll back transaction %d\n", transactionID);
                    break;
                }

                // Update the last access time and transaction ID for this connection
                connections[transactionID].lastAccessTime = time(NULL);
                transactionIDs[transactionID]++;
            }
            case OPEN: {
