                if (status < 0) {
                    fprintf(stderr, "Error: Could not open new connection at index %d\n", connectionIndex);
                    break;
                }

                // Update the last access time and transaction ID for this connection
                connections[connectionIndex].lastAccessTime = time(NULL);
                transactionIDs[connectionIndex]++;
            }
            case CLOSE: {
                int connectionIndex = getConnectionIndex(); // Implement a function to retrieve the connection index from the incoming request
                if (connectionIndex < 0) {
                    fprintf(stderr, "Error: Could not retrieve connection index from incoming request\n");
                    break;
