// Define the data unit structure
typedef struct {
    int id;
    size_t offset_size;
    size_t* offsets;
} dataUnit;

// Define a function to manage dynamic memory allocation for a collection of data units
dataUnit* allocateDataUnits(int num_units, int min_offset_size, int max_offset_size) {
    // Check if the number of units is valid
    assert(num_units >= 0);

    // Allocate memory for the data unit array
    dataUnit* units = (dataUnit*)malloc(sizeof(dataUnit) * num_units);
    if (!units) {
        fprintf(stderr, "Error: Failed to allocate memory for data unit array\n");
        return NULL;
    }

    // Initialize each data unit
    for (int i = 0; i < num_units; i++) {
        units[i].id = i + 1;
        units[i].offset_size = min_offset_size + (rand() % (max_offset_size - min_offset_size));
        units[i].offsets = (size_t*)malloc(sizeof(size_t) * units[i].offset_size);
        if (!units[i].offsets) {
            fprintf(stderr, "Error: Failed to allocate memory for offsets of data unit %d\n", i + 1);
            free(units);
            return NULL;
        }
    }

    // Initialize the offsets for each data unit
    for (int i = 0; i < num_units; i++) {
        for (int j = 0; j < units[i].offset_size; j++) {
            units[i].offsets[j] = rand() % max_offset_size;
        }
    }

    return units;
}

// Define a function to deallocate memory for a collection of data units
void deallocateDataUnits(dataUnit* units) {
    // Check if the input is valid
    assert(units != NULL);

    // Deallocate memory for each data unit
    for (int i = 0; i < num_units; i++) {
        free(units[i].offsets);
    }

    // Deallocate memory for the data unit array
    free(units);
}
