#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <errno.h>
#include <pthread.h>
#include <time.h>

#define MAX_CONN 10000 // Maximum number of connections to manage
#define POOL_SIZE 1000 // Size of connection pool
#define MSG_BUF_SIZE 4096 // Size of message buffer in bytes
#define CONN_META_SIZE sizeof(struct connMetadata) // Size of connection metadata structure

typedef enum {
    CONN_INACTIVE = 1,
    CONN_ACTIVE = 2,
    CONN_CLOSING = 3,
} connStatus; // Connection status enumeration

typedef struct connMetadata {
    int sessionID; // Session ID for each connection
    time_t lastActivityTime; // Last activity time for each connection
    int errorCode; // Error code for each connection
} connMetadata;

typedef struct netConnection {
    int socketFd; // Socket file descriptor for each connection
    connStatus status; // Connection status indicator (active, inactive, or closing)
    time_t lastActivityTime; // Last activity time for each connection
    char* msgBuf; // Message buffer for incoming messages
} netConnection;

struct networkServerManager {
    pthread_mutex_t lock; // Mutex for protecting shared resources
    pthread_cond_t cond; // Condition variable for signaling between threads
    int numConns; // Number of active connections
    connMetadata* connMetaData; // Connection metadata array
    netConnection* conns; // Array of network connections
};

// Initialize the connection pool and allocate memory for it
void initConnectionPool(struct networkServerManager* server) {
    // Allocate memory for the connection pool
    server->conns = (netConnection*)malloc(POOL_SIZE * sizeof(netConnection));
    if (!server->conns) {
        printf("Error: Failed to allocate memory for connection pool\n");
        exit(1);
    }

    // Initialize each connection's status to a random connection state within the specified range
    for (int i = 0; i < POOL_SIZE; i++) {
        server->conns[i].status = CONN_INACTIVE;
        server->conns[i].lastActivityTime = 0;
        server->conns[i].socketFd = -1;
    }
}

// Allocate memory for the message buffer and initialize it to empty
void initMsgBuf(netConnection* conn) {
    // Allocate memory for the message buffer
    conn->msgBuf = (char*)malloc(MSG_BUF_SIZE * sizeof(char));
    if (!conn->msgBuf) {
        printf("Error: Failed to allocate memory for message buffer\n");
        exit(1);
    }

    // Initialize the message buffer to empty
    conn->msgBuf[0] = '\0';
}

// Create a new connection and add it to the pool
int createConnection(struct networkServerManager* server, struct sockaddr_in* clientAddr) {
    int socketFd; // Socket file descriptor for the new connection
    netConnection* conn; // Pointer to the new connection structure

    // Check if the connection pool is full
    if (server->numConns >= POOL_SIZE) {
        printf("Error: Connection pool is full\n");
        return -1;
    }

    // Create a new socket file descriptor
    socketFd = socket(AF_INET, SOCK_STREAM, 0);
    if (socketFd < 0) {
        printf("Error: Failed to create socket\n");
        return -1;
    }

    // Bind the new socket file descriptor to the specified port and address
    struct sockaddr_in serverAddr = {
        .sin_family = AF_INET,
        .sin_port = htons(SERVER_PORT),
        .sin_addr.s_addr = htonl(INADDR_ANY)
    };
    if (bind(socketFd, (struct sockaddr*)&serverAddr, sizeof(serverAddr)) < 0) {
        printf("Error: Failed to bind socket\n");
        return -1;
    }

    // Listen for incoming connections
    if (listen(socketFd, 3) < 0) {
        printf("Error: Failed to listen on socket\n");
        return -1;
    }

    // Accept an incoming connection
    conn = &server->conns[server->numConns];
    conn->socketFd = accept(socketFd, (struct sockaddr*)clientAddr, (socklen_t*)&clientAddr);
    if (conn->socketFd < 0) {
        printf("Error: Failed to accept connection\n");
        return -1;
    }

    // Initialize the new connection's status to active
    conn->status = CONN_ACTIVE;
    conn->lastActivityTime = time(NULL);

    // Increment the number of active connections
    server->numConns++;

    return 0;
}

// Close a connection and remove it from the pool
int closeConnection(struct networkServerManager* server, int socketFd) {
    int i = 0;
    netConnection* conn; // Pointer to the connection structure

    // Find the connection with the specified socket file descriptor in the connection pool
    while (i < POOL_SIZE && server->conns[i].socketFd != socketFd) {
        i++;
    }

    // Check if the connection was found in the pool
    if (i == POOL_SIZE) {
        printf("Error: Connection not found\n");
        return -1;
    }

    // Close the connection's socket file descriptor
    conn = &server->conns[i];
    if (close(conn->socketFd) < 0) {
        printf("Error: Failed to close socket\n");
        return -1;
    }

    // Set the connection's status to inactive
    conn->status = CONN_INACTIVE;

    // Decrement the number of active connections
    server->numConns--;

    return 0;
}

// Send data over a connection
int sendData(struct networkServerManager* server, int socketFd, char* data) {
    netConnection* conn; // Pointer to the connection structure
    ssize_t numBytes; // Number of bytes sent over the connection

    // Find the connection with the specified socket file descriptor in the connection pool
    for (int i = 0; i < POOL_SIZE; i++) {
        if (server->conns[i].socketFd == socketFd) {
            conn = &server->conns[i];
            break;
        }
    }

    // Check if the connection was found in the pool
    if (!conn) {
        printf("Error: Connection not found\n");
        return -1;
    }

    // Send the data over the connection
    numBytes = send(socketFd, data, strlen(data), 0);
    if (numBytes < 0) {
        printf("Error: Failed to send data over socket\n");
        return -1;
    }

    return 0;
}

// Receive data from a connection
int receiveData(struct networkServerManager* server, int socketFd, char* buffer) {
    netConnection* conn; // Pointer to the connection structure
    ssize_t numBytes; // Number of bytes received over the connection

    // Find the connection with the specified socket file descriptor in the connection pool
    for (int i = 0; i < POOL_SIZE; i++) {
        if (server->conns[i].socketFd == socketFd) {
            conn = &server->conns[i];
            break;
        }
    }

    // Check if the connection was found in the pool
    if (!conn) {
        printf("Error: Connection not found\n");
        return -1;
    }

    // Receive the data from the connection
    numBytes = recv(socketFd, buffer, MSG_SIZE, 0);
    if (numBytes < 0) {
        printf("Error: Failed to receive data over socket\n");
        return -1;
    }

    return 0;
}

// Close all connections and free memory allocated for the connection pool
void closeAllConnections(struct networkServerManager* server) {
    // Loop through each connection in the pool and close it
    for (int i = 0; i < POOL_SIZE; i++) {
        if (server->conns[i].socketFd != -1) {
            closeConnection(server, server->conns[i].socketFd);
        }
    }
}

// Free memory allocated for the connection pool and shut down the network server
void freeConnectionPool(struct networkServerManager* server) {
    // Close all connections in the pool
    closeAllConnections(server);

    // Free memory allocated for the connection pool
    if (server->conns) {
        free(server->conns);
    }

    // Shut down the network server
    shutdown(server->socketFd, SHUT_RDWR);
}

int main() {
    struct sockaddr_in clientAddr; // Address of the incoming connection
    int socketFd; // Socket file descriptor for the new connection
    char data[MSG_SIZE]; // Buffer for receiving and sending data

    // Create a new network server
    struct networkServerManager server = {
        .lock = PTHREAD_MUTEX_INITIALIZER,
        .cond = PTHREAD_COND_INITIALIZER,
        .numConns = 0,
        .socketFd = socket(AF_INET, SOCK_STREAM, 0)
    };

    // Check if the network server was created successfully
    if (server.socketFd == -1) {
        printf("Error: Failed to create network server\n");
        return -1;
    }

    // Set the socket options for the network server
    int option = 1;
    if (setsockopt(server.socketFd, SOL_SOCKET, SO_REUSEADDR, &option, sizeof(option)) < 0) {
        printf("Error: Failed to set socket options\n");
        return -1;
    }

    // Bind the network server to a specific IP address and port number
    struct sockaddr_in servAddr = {
        .sin_family = AF_INET,
        .sin_port = htons(PORT),
        .sin_addr.s_addr = INADDR_ANY
    };
    if (bind(server.socketFd, (struct sockaddr*)&servAddr, sizeof(servAddr)) < 0) {
        printf("Error: Failed to bind network server\n");
        return -1;
    }

    // Listen for incoming connections on the network server
    if (listen(server.socketFd, BACKLOG) < 0) {
        printf("Error: Failed to listen for incoming connections\n");
        return -1;
    }

    // Loop forever waiting for and handling incoming connections
    while (true) {
        // Accept an incoming connection on the network server
        socketFd = accept(server.socketFd, NULL, NULL);
        if (socketFd == -1) {
            printf("Error: Failed to accept incoming connection\n");
            return -1;
        }

        // Handle the incoming connection by sending and receiving data over it
        while (true) {
            // Receive data from the client
            receiveData(&server, socketFd, data);

            // Process the received data
            printf("Received: %s\n", data);

            // Send a response back to the client
            char* response = "Hello!";
            sendData(&server, socketFd, response);
        }
    }

    // Close the network server and free memory allocated for the connection pool
    closeConnectionPool(&server);

    return 0;
}
