#include <netinet/in.h>
#include <arpa/inet.h>
#include <netdb.h>

#define PORT 8080
#define BACKLOG 10
#define MSG_SIZE 256

int main() {
    struct sockaddr_in servAddr; // Address of the server to connect to
    int socketFd; // Socket file descriptor for the connection
    char data[MSG_SIZE]; // Buffer for sending and receiving data

