        printf("Error: unable to allocate memory for connection pool\n");
        return NULL;
    }

    // Initialize the pool with the specified maximum number of connections
    pool->size = maxConn;

    // Allocate arrays for last access times, transaction IDs, and metadata records
    pool->lastAccessTimes = malloc(maxConn * sizeof(long));
    pool->transactionIDs = malloc(maxConn * sizeof(int));
    pool->meta = malloc(maxConn * sizeof(struct dbMetadata));
