#include <stdlib.h>
#include <time.h>
#include <string.h>

// Define structs for each data structure
struct sensor_data {
    int *id;
    char *buffer;
    time_t *timestamp;
};

struct event_log {
    struct sensor_data *sensor_data;
    int unique_id;
    struct event_log *next;
};

// Define constants for memory allocation and initialization
#define MAX_BUFFER_SIZE 256
#define MIN_ID 100
#define MAX_ID 999
#define TIMEOUT_INTERVAL 30 // in seconds

// Define function to generate random number within specified range
int generate_random(int min, int max) {
    return min + (rand() % (max - min + 1));
}

// Define function to generate random string of characters and digits
char *generate_string(size_t size) {
    char *str = malloc(sizeof(char) * size);
    if (!str) {
        return NULL;
    }
    for (int i = 0; i < size; i++) {
        str[i] = (rand() % 26) + 'a'; // lowercase letters
        if (i % 2 == 1) {
            str[i] += 32; // uppercase letters
        }
        if (i % 4 == 0) {
            str[i] = rand() % 10 + '0'; // digits
        }
    }
    return str;
}

// Define function to initialize data structures
struct event_log *initialize_data_structures(int num_sensors, int num_events) {
    struct event_log *first = NULL;
    for (int i = 0; i < num_sensors; i++) {
        // Allocate memory for sensor data structure
        struct sensor_data *sensor_data = malloc(sizeof(struct sensor_data));
        if (!sensor_data) {
            return NULL;
        }
        // Initialize id to a random value within the specified range
        sensor_data->id = malloc(sizeof(int));
        *(sensor_data->id) = generate_random(MIN_ID, MAX_ID);
        // Generate a unique string for each sensor and allocate memory for it
        size_t buffer_size = (rand() % (MAX_BUFFER_SIZE - MIN_BUFFER_SIZE)) + MIN_BUFFER_SIZE;
        char *buffer = generate_string(buffer_size);
        if (!buffer) {
            return NULL;
        }
        sensor_data->buffer = buffer;
        // Initialize timestamp to the current system time
        sensor_data->timestamp = malloc(sizeof(time_t));
        *(sensor_data->timestamp) = time(NULL);
        // Allocate memory for event log structure and initialize it
        struct event_log *event_log = malloc(sizeof(struct event_log));
        if (!event_log) {
            return NULL;
        }
        event_log->sensor_data = sensor_data;
        event_log->unique_id = generate_random(MIN_ID, MAX_ID);
        // Add event log to the linked list
        event_log->next = first;
        first = event_log;
    }
    return first;
}

// Define function to insert events into linked list and BST
void insert_events(struct event_log *first, struct event_log *event) {
    // Insert event into linked list
    if (first == NULL) {
        first = event;
    } else {
        struct event_log *current = first;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = event;
    }
    // Insert event into BST
    struct event_log *bst_root = bst_insert(first, event);
}

// Define function to traverse linked list and BST
void traverse_data_structures(struct event_log *first) {
    // Traverse linked list
    struct event_log *current = first;
    while (current != NULL) {
        printf("Sensor ID: %d\n", *(current->sensor_data->id));
        printf("Buffer: %s\n", current->sensor_data->buffer);
        printf("Timestamp: %s\n", ctime(current->sensor_data->timestamp));
        printf("Event ID: %d\n", current->unique_id);
        current = current->next;
    }
    // Traverse BST
    struct event_log *bst_root = first;
    while (bst_root != NULL) {
        printf("Sensor ID: %d\n", bst_root->sensor_data->id);
        printf("Buffer: %s\n", bst_root->sensor_data->buffer);
        printf("Timestamp: %s\n", ctime(bst_root->sensor_data->timestamp));
        printf("Event ID: %d\n", bst_root->unique_id);
        bst_root = bst_root->next;
