// Function to dynamically allocate memory for a variable-sized list of custom Items
void* allocateItems(int numItems, int numItemTypes) {
    // Calculate the total size of the items array and the item metadata array
    int itemsSize = sizeof(Item) * numItems;
    int metaDataSize = numItemTypes * sizeof(void*);
    int totalSize = itemsSize + metaDataSize;

    // Ensure that the total memory usage is within bounds
    if (totalSize > MAX_MEMORY_SIZE) {
        return NULL;
    }

    // Allocate memory for the items array and the item metadata array
    void* mem = malloc(totalSize);
    assert(mem != NULL);

    // Initialize the items array
    Item* items = (Item*) mem;
    for (int i = 0; i < numItems; i++) {
        items[i].value = 0.0;
        items[i].name = NULL;
        items[i].metadata = NULL;
    }

    // Initialize the item metadata array
    void** metaData = (void**) (mem + itemsSize);
    for (int i = 0; i < numItemTypes; i++) {
        metaData[i] = NULL;
    }

    return mem;
}

// Function to safely free the allocated memory when no longer needed
void freeItems(void* mem) {
    if (mem != NULL) {
        free(mem);
    }
}
