    record_t record;
};

// Define a mutex for protecting concurrent access to the data structures
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Define a function to initialize the data structures
void init_data_structures(int num_records, int value_range_min, int value_range_max) {
    // Allocate memory for the offsets and keys arrays
    offsets = (long *)malloc(num_records * sizeof(long));
    keys = (int *)malloc(num_records * sizeof(int));

    // Initialize the offsets array with random values within the specified range
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        offsets[i] = rand() % (value_range_max - value_range_min + 1) + value_range_min;
    }

    // Initialize the keys array with random values within the specified range
    for (int i = 0; i < num_records; i++) {
        keys[i] = rand() % (value_range_max - value_range_min + 1) + value_range_min;
    }

    // Allocate memory for the records array and initialize it with random values within the specified range
    records = (record_t *)malloc(num_records * sizeof(record_t));
    for (int i = 0; i < num_records; i++) {
        records[i].value = rand() % (value_range_max - value_range_min + 1) + value_range_min;
    }
}

// Define a function to add a record to the linked list of records for efficient insertion and deletion
void add_record(record_t record) {
    struct record_list *new_record = malloc(sizeof(struct record_list));
    new_record->next = NULL;
    new_record->record = record;

    // Lock the mutex to prevent concurrent access to the linked list
    pthread_mutex_lock(&lock);

    // If the linked list is empty, set the head pointer to point to the new record
    if (records == NULL) {
        records = new_record;
    } else {
        struct record_list *current = records;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_record;
    }

    // Unlock the mutex to allow other threads to access the linked list
    pthread_mutex_unlock(&lock);
}

// Define a function to remove a record from the linked list of records for efficient insertion and deletion
void remove_record(int key) {
    // Lock the mutex to prevent concurrent access to the linked list
    pthread_mutex_lock(&lock);

    // If the linked list is empty, do nothing
    if (records == NULL) {
        return;
    }

    // Find the record with the specified key in the linked list
    struct record_list *current = records;
    while (current != NULL && current->record.key != key) {
        current = current->next;
    }

    // If the record is found, remove it from the linked list and free its memory
    if (current != NULL) {
        struct record_list *previous = records;
        while (previous->next != current) {
            previous = previous->next;
        }
        previous->next = current->next;
        free(current);
    }

    // Unlock the mutex to allow other threads to access the linked list
    pthread_mutex_unlock(&lock);
}

// Define a function to get a record from the linked list of records for efficient insertion and deletion
record_t *get_record(int key) {
    // Lock the mutex to prevent concurrent access to the linked list
    pthread_mutex_lock(&lock);

    // If the linked list is empty, return NULL
    if (records == NULL) {
        return NULL;
    }

    // Find the record with the specified key in the linked list
    struct record_list *current = records;
    while (current != NULL && current->record.key != key) {
        current = current->next;
    }

    // If the record is found, return it
    if (current != NULL) {
        pthread_mutex_unlock(&lock);
        return &(current->record);
    }

    // Unlock the mutex to allow other threads to access the linked list
    pthread_mutex_unlock(&lock);

    // Return NULL if the record is not found
    return NULL;
}

// Define a function to free all memory allocated for the data structures
void free_data_structures() {
    // Free the memory allocated for the offsets, keys, and records arrays
    free(offsets);
    free(keys);
    free(records);

    // Reset the pointers to NULL
    offsets = NULL;
    keys = NULL;
    records = NULL;
}
