        events->events[i]->time_stamp = ts;
        events->events[i]->source_ip = src_ip;
        events->events[i]->destination_port = dst_port;
        events->sizes.sizes[i] = pkt_size;

        // Categorize event based on packet size into different event codes
        if (pkt_size < 1024) {
            events->codes.codes[i] = 0;
        } else if (pkt_size >= 1024 && pkt_size < 5120) {
            events->codes.codes[i] = 1;
        } else if (pkt_size >= 5120 && pkt_size < 16384) {
            events->codes.codes[i] = 2;
        } else if (pkt_size >= 16384 && pkt_size < 65536) {
            events->codes.codes[i] = 3;
        } else {
            events->codes.codes[i] = 4;
        }
    }
