    assert(data_points != NULL);

    // Initialize the offset array with random values
    for (int i = 0; i < num_datasets; i++) {
        offset_array[i] = rand() % (max_records - min_key + 1) + min_key;
    }

    // Initialize the key and measurement arrays with random values
    for (int i = 0; i < num_datasets; i++) {
        int offset = offset_array[i];
        for (int j = 0; j < max_records; j++) {
            data_points[offset + j].key = rand() % (max_key - min_key + 1) + min_key;
            data_points[offset + j].measurement = rand() % (max_measurement - min_measurement + 1) + min_measurement;
        }
