    for (size_t i = 0; i < MAX_LOGS; i++) {
        struct log_entry* entry = logs + i;
        entry->timestamp = get_current_time();
        entry->event_type = generate_random_event_type();
        entry->message = malloc(MAX_MESSAGE_LENGTH);
    }
}

