}

// Main logging function that manages the array of log entries
void log(struct log_entry* entry) {
    // Check if the memory for the log array has been allocated
    if (logs == NULL) {
        init_logging();
    }

    // Update the current log entry with data from the sensor API
    update_log_entry(entry);

    // Add the updated log entry to the end of the log array
    logs[num_logs++] = *entry;

    // Check for network errors and handle them appropriately
    if (check_network_errors()) {
        log_error("Network error occurred during logging");
        return;
    }

    // Check for API timeouts and handle them appropriately
    if (check_api_timeouts()) {
        log_error("API timeout occurred during logging");
        return;
    }

    // Write the log entry to a file
    write_log_entry(logs[num_logs - 1]);
}

// Function to write a single log entry to a file
void write_log_entry(struct log_entry* entry) {
    FILE* f = fopen("log.txt", "a");
    if (f == NULL) {
        log_error("Failed to open log file for writing");
        return;
    }

    // Write the log entry to the file
    fprintf(f, "%ld %d %s\n", entry->timestamp, entry->event_type, entry->message);

    // Close the file stream
    fclose(f);
}

// Function to generate a random event type within a specified range
int generate_random_event_type() {
    return rand() % MAX_EVENT_TYPE + MIN_EVENT_TYPE;
}

// Function to retrieve the current time as a timestamp
double get_current_time() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    return (double)ts.tv_sec + (double)ts.tv_nsec / 1e9;
}

// Function to retrieve the current temperature reading from a hypothetical sensor API
