// Struct to store items in the collection
struct item {
  int id;
  double value;
  char label[10];
};

// Collection object that manages the items
struct collection {
  struct item *items; // Array of pointers to items
  size_t capacity;   // Maximum number of items in the collection
  size_t count;      // Current number of items in the collection
};

// Function to create a new collection with initial capacity set to 0
struct collection *create_collection() {
  struct collection *col = malloc(sizeof(struct collection));
  if (!col) return NULL;
  col->items = malloc(0);
  if (!col->items) {
    free(col);
    return NULL;
  }
  col->capacity = 0;
  col->count = 0;
  return col;
}

// Function to add a new item to the collection
int add_item(struct collection *col, struct item *item) {
  // Check if the collection is full
  if (col->capacity == col->count) {
    // Increase the capacity by half if it's not already at its maximum
    size_t new_capacity = col->capacity < 10 ? col->capacity * 2 : col->capacity + 1;
    struct item *new_items = realloc(col->items, sizeof(struct item) * new_capacity);
    if (!new_items) return -1;
    col->items = new_items;
    col->capacity = new_capacity;
  }

  // Add the new item to the collection
  col->items[col->count++] = *item;
  return 0;
}

// Function to retrieve an item from the collection by its id
struct item *get_item(struct collection *col, int id) {
  for (size_t i = 0; i < col->count; ++i) {
    if (col->items[i].id == id) return &col->items[i];
  }
  return NULL;
}

// Function to remove an item from the collection by its id
int remove_item(struct collection *col, int id) {
  // Check if the collection is empty
  if (col->count == 0) return -1;

  // Find the index of the item to be removed
  size_t i = 0;
  while (i < col->count && col->items[i].id != id) ++i;
  if (i == col->count) return -2;

  // Shift all items after the target index down by one
  for (size_t j = i; j < col->count - 1; ++j) {
    col->items[j] = col->items[j + 1];
  }

  // Decrement the count and resize the collection if necessary
  --col->count;
  if (col->capacity > 5 && col->count * 4 < col->capacity) {
    struct item *new_items = realloc(col->items, sizeof(struct item) * col->count);
    if (!new_items) return -3;
    col->items = new_items;
    col->capacity = col->count;
  }
  return 0;
}

// Function to log the total number of items processed, last id used, and average value of added items
void log(struct collection *col) {
  FILE *file; // Replace with a logger mechanism based on user preference
  file = fopen("log.txt", "a+");
  if (!file) return;

  // Write the total number of items processed to the log
  char num_items[10];
  sprintf(num_items, "%zu", col->count);
  fwrite(num_items, strlen(num_items), 1, file);

  // Write the last id used to the log
  char last_id[10];
  sprintf(last_id, "%d", col->items[col->count - 1].id);
  fwrite(last_id, strlen(last_id), 1, file);

  // Calculate and write the average value of added items to the log
  double sum = 0;
  for (size_t i = 0; i < col->count; ++i) {
    sum += col->items[i].value;
  }
  char avg_value[10];
  sprintf(avg_value, "%.2f", sum / col->count);
  fwrite(avg_value, strlen(avg_value), 1, file);

  // Close the log file
  fclose(file);
}

// Cleanup function to free memory allocated by the collection
void destroy_collection(struct collection *col) {
  if (!col) return;
  free(col->items);
  free(col);
}
