#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <math.h>

// Define struct for storing data
typedef struct {
  int id;
  double value;
  char label[10];
} item;

// Define collections of different types
item* float_items = NULL;
item* char_items = NULL;
item* struct_items = NULL;

// Define variables to track stats
int total_items = 0;
int last_id = -1;
double avg_value = 0.0;

// Define synchronization mechanism
pthread_mutex_t mutex;

// Define function to add new item
void add_item(item* collection, void* data) {
  // Lock the mutex before modifying shared variables
  pthread_mutex_lock(&mutex);

  // Create new item and copy data into it
  item* new_item = (item*)malloc(sizeof(item));
  memcpy(new_item, data, sizeof(item));

  // Add new item to collection
  if (collection == NULL) {
    collection = (item**)malloc(sizeof(item*));
  } else {
    collection = (item**)realloc(collection, (total_items + 1) * sizeof(item*));
  }

  // Update statistics
  total_items++;
  if (new_item->id > last_id) {
    last_id = new_item->id;
  }
  avg_value += new_item->value;

  // Add new item to collection and unlock mutex
  collection[total_items - 1] = new_item;
  pthread_mutex_unlock(&mutex);
}

// Define function to retrieve statistics
void get_stats(int* total, int* last_id, double* avg) {
  // Lock the mutex before modifying shared variables
  pthread_mutex_lock(&mutex);

  // Update pointers with current values
  *total = total_items;
  *last_id = last_id;
  *avg = avg_value / total_items;

  // Unlock mutex and return
  pthread_mutex_unlock(&mutex);
}

// Define function to handle unexpected failures
void handle_error(char* error) {
  fprintf(stderr, "Error: %s\n", error);
  pthread_exit(1);
}

int main() {
  // Initialize mutex and collections
  pthread_mutex_init(&mutex, NULL);
  float_items = (item**)malloc(sizeof(item*));
  char_items = (item**)malloc(sizeof(item*));
  struct_items = (item**)malloc(sizeof(item*));

  // Start thread pool and add items concurrently
  int num_threads = 4;
  pthread_t threads[num_threads];
  for (int i = 0; i < num_threads; i++) {
    if (pthread_create(&threads[i], NULL, (void* (*)(void*))add_item, (void*)float_items) != 0) {
      handle_error("Failed to create thread");
    }
    if (pthread_create(&threads[i], NULL, (void* (*)(void*))add_item, (void*)char_items) != 0) {
      handle_error("Failed to create thread");
    }
    if (pthread_create(&threads[i], NULL, (void* (*)(void*))add_item, (void*)struct_items) != 0) {
      handle_error("Failed to create thread");
    }
  }

  // Wait for threads to finish
  for (int i = 0; i < num_threads; i++) {
    if (pthread_join(threads[i], NULL) != 0) {
      handle_error("Failed to join thread");
    }
  }

  // Print statistics and free resources
  int total, last_id;
  double avg;
  get_stats(&total, &last_id, &avg);
  printf("Total items: %d\n", total);
  printf("Last ID used: %d\n", last_id);
  printf("Average value: %.2f\n", avg);

  // Free resources and exit
  pthread_mutex_destroy(&mutex);
  free(float_items);
  free(char_items);
  free(struct_items);
  return 0;
}
```
