import java.io.ObjectInputStream;
import java.util.HashMap;

public class ObjectProcessor {
    private static HashMap<byte[], Object> cache = new HashMap<>();

    public static Object deserialize(byte[] serialized) {
        // Check if the byte array is already in the cache
        if (cache.containsKey(serialized)) {
            return cache.get(serialized);
        } else {
            try {
                // Deserialize the byte array using ObjectInputStream
                ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(serialized));
                Object object = ois.readObject();
                // Add the deserialized object to the cache
                cache.put(serialized, object);
                return object;
            } catch (Exception e) {
                // Log a warning message and return null if deserialization fails
                System.out.println("Warning: Failed to deserialize byte array");
                return null;
            }
        }
    }
}
