// C function to dynamically manage a many-to-many relationship between offset values (stored as long) and keys (stored as int)
void manageRecords(int op, void *data) {
    // Define structure for each record containing an offset pointer, a list of associated keys, and an int value
    struct Record {
        long offset;
        int *keys;
        int value;
    };

    // Define a hash map to store the records
    HashMap<long, std::vector<int>> recordMap;

    switch (op) {
        case ADD_RECORD: {
            struct Record *newRecord = (struct Record *)data;
            recordMap[newRecord->offset].push_back(newRecord->value);
            for (int i = 0; i < newRecord->keys->size(); i++) {
                recordMap[newRecord->keys[i]].push_back(newRecord->value);
            }
            break;
        }
        case UPDATE_VALUE: {
            struct Record *record = (struct Record *)data;
            record->value = rand() % 100; // Update the int value of each record to a random value within a specified range
            break;
        }
        case FIND_BY_OFFSET: {
            long offset = *((long *)data);
            if (recordMap.count(offset)) {
                std::vector<int> keys = recordMap[offset];
                for (int i = 0; i < keys.size(); i++) {
                    // Print each record in a human-readable format for debugging purposes
                    printf("Offset: %ld, Key: %d, Value: %d\n", offset, keys[i], recordMap[keys[i]][0]);
                }
            } else {
                printf("No records found for offset %ld\n", offset);
            }
            break;
        }
        case FIND_BY_KEY: {
            int key = *((int *)data);
            if (recordMap.count(key)) {
                std::vector<long> offsets = recordMap[key];
                for (int i = 0; i < offsets.size(); i++) {
                    // Print each record in a human-readable format for debugging purposes
                    printf("Offset: %ld, Key: %d, Value: %d\n", offsets[i], key, recordMap[offsets[i]][0]);
                }
            } else {
                printf("No records found for key %d\n", key);
            }
            break;
        }
        default:
            // Handle invalid operations and ensure robustness against potential memory allocation failures
            break;
    }
}

// Function to print all records in a human-readable format for debugging purposes
void printRecords() {
    for (auto it = recordMap.begin(); it != recordMap.end(); ++it) {
        printf("Offset: %ld, Keys: ", it->first);
        for (int i = 0; i < it->second.size(); i++) {
            printf("%d, ", it->second[i]);
        }
        printf(", Value: %d\n", recordMap[it->first][0]);
    }
}']

