        return -1;
    }

    // Allocate memory for the new record
    void* recordPtr = malloc(sizeof(Record));
    if (!recordPtr) {
        fprintf(stderr, "Failed to allocate memory for new record\n");
        return -1;
    }

    // Set the index of the new record to the key provided
    Record* newRecord = (Record*)recordPtr;
    newRecord->index = key;

    // Update the records array with the new record
