    for (int i = 0; i < recordCount; i++) {
        if (recordsArray[i].index >= 0) {
            insertIndex++;
        } else {
            break;
        }
    }
    recordsArray[insertIndex] = *newRecord;

    // Return the index of the new record in the records array
    return insertIndex;
}

