#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <stdint.h>
#include <assert.h>

// Define a record structure to store offset and key associations
typedef struct {
  long *offset;
  int *keys;
  int num_keys;
} record;

// Define a custom hash table data structure for managing many-to-many relationships between offsets and keys
typedef struct {
  record **records;
  size_t capacity;
  size_t size;
} hash_table;

// Initialize the hash table with an initial capacity of 1024 records
void init_hash_table(hash_table *ht) {
  ht->capacity = 1024;
  ht->size = 0;
  ht->records = (record **)malloc(sizeof(record *) * ht->capacity);
}

// Resize the hash table to accommodate more records if necessary
void resize_hash_table(hash_table *ht) {
  size_t new_capacity = ht->capacity * 2;
  record **new_records = (record **)malloc(sizeof(record *) * new_capacity);
  memcpy(new_records, ht->records, sizeof(record *) * ht->size);
  free(ht->records);
  ht->records = new_records;
  ht->capacity = new_capacity;
}

// Add a new record to the hash table
void add_record(hash_table *ht, long offset, int key) {
  if (ht->size == ht->capacity) {
    resize_hash_table(ht);
  }
  record *new_record = (record *)malloc(sizeof(record));
  new_record->offset = offset;
  new_record->keys = (int *)malloc(sizeof(int) * ht->num_keys);
  new_record->num_keys = ht->num_keys;
  memset(new_record->keys, -1, sizeof(int) * ht->num_keys);
  ht->records[ht->size] = new_record;
  ht->size++;
}

// Update an existing record in the hash table
void update_record(hash_table *ht, long offset, int key) {
  bool found = false;
  for (int i = 0; i < ht->size; i++) {
    if (ht->records[i]->offset == offset) {
      found = true;
      break;
    }
  }
  if (!found) {
    add_record(ht, offset, key);
  } else {
    for (int i = 0; i < ht->num_keys; i++) {
      if (ht->records[i]->offset == offset && ht->records[i]->keys[i] == -1) {
        ht->records[i]->keys[i] = key;
        break;
      }
    }
  }
}

// Retrieve a record from the hash table based on its offset value
record *get_record(hash_table *ht, long offset) {
  for (int i = 0; i < ht->size; i++) {
    if (ht->records[i]->offset == offset) {
      return ht->records[i];
    }
  }
  return NULL;
}

// Retrieve all records from the hash table that have a specific key value
record **get_records(hash_table *ht, int key) {
  record **result = (record **)malloc(sizeof(record *) * ht->size);
  int num_results = 0;
  for (int i = 0; i < ht->size; i++) {
    for (int j = 0; j < ht->num_keys; j++) {
      if (ht->records[i]->keys[j] == key) {
        result[num_results++] = ht->records[i];
      }
    }
  }
  return result;
}

// Print all records in the hash table in a human-readable format for debugging purposes
void print_records(hash_table *ht) {
  printf("Size: %zu\n", ht->size);
  for (int i = 0; i < ht->size; i++) {
    printf("%p: Offset = %ld, Keys = ", ht->records[i], ht->records[i]->offset);
    for (int j = 0; j < ht->num_keys; j++) {
      if (ht->records[i]->keys[j] != -1) {
        printf("%d, ", ht->records[i]->keys[j]);
      }
    }
    printf("\n");
  }
}

// Set the value of a record's int field to a random value within a specified range
void set_random_value(hash_table *ht, long offset, int min, int max) {
  record *rec = get_record(ht, offset);
  if (rec != NULL) {
    rec->int_field = rand() % (max - min + 1) + min;
  }
}

// Periodically check and clean up unused resources
void cleanup(hash_table *ht) {
  for (int i = 0; i < ht->size; i++) {
    if (ht->records[i]->num_keys == 0) {
      free(ht->records[i]);
      ht->records[i] = NULL;
    }
  }
}

int main() {
  hash_table *ht = malloc(sizeof(hash_table));
  init_hash_table(ht);

  // Test adding and updating records
  add_record(ht, 100, 10);
  update_record(ht, 200, 15);
  update_record(ht, 300, 20);
  print_records(ht);

  // Test retrieving records based on offset and key value
  record *rec = get_record(ht, 200);
  if (rec != NULL) {
    printf("Record with offset 200 has keys: ");
    for (int i = 0; i < ht->num_keys; i++) {
      if (rec->keys[i] != -1) {
        printf("%d, ", rec->keys[i]);
      }
    }
    printf("\n");
  }

  // Test retrieving all records with a specific key value
  record **results = get_records(ht, 20);
  if (results != NULL) {
    for (int i = 0; i < ht->size; i++) {
      printf("%p: Offset = %ld, Keys = ", results[i], results[i]->offset);
      for (int j = 0; j < ht->num_keys; j++) {
        if (results[i]->keys[j] != -1) {
          printf("%d, ", results[i]->keys[j]);
        }
      }
      printf("\n");
    }
  }

  // Test setting a random value for a record's int field
  set_random_value(ht, 400, 10, 20);
  rec = get_record(ht, 400);
  if (rec != NULL) {
    printf("Record with offset 400 has int field value %d\n", rec->int_field);
  }

  // Test cleaning up unused resources
  cleanup(ht);
}
