void log_sensor_data(int num_sensors, int num_log_entries, struct log_entry* log_buffer) {
    // Dynamically allocate memory for the log buffer
    log_buffer = (struct log_entry*)malloc(sizeof(struct log_entry) * num_log_entries);

    // Initialize the log buffer with empty slots
    for (int i = 0; i < num_log_entries; i++) {
