        // Update the log buffer with the new data
        log_buffer[curr_log_entry].timestamp = sensor_data.temperature;
        log_buffer[curr_log_entry].event_type = sensor_data.event_type;
        log_buffer[curr_log_entry].message = malloc(strlen(sensor_data.message) + 1);
        strcpy(log_buffer[curr_log_entry].message, sensor_data.message);

        // Increment the current log entry index and wrap around if necessary
        curr_log_entry++;
        if (curr_log_entry >= num_log_entries) {
            curr_log_entry = 0;
        }
    }

    // Write the log buffer to persistent storage in a thread-safe manner
