void initNetworkRequestPool(size_t capacity) {
    struct networkRequestPool *pool = (struct networkRequestPool *)malloc(sizeof(struct networkRequestPool));
    pool->capacity = capacity;
    pool->count = 0;
    pool->requests = (struct networkRequest *)malloc(sizeof(struct networkRequest) * pool->capacity);
}

// Function to dynamically allocate a new request structure and add it to the pool
void allocateNetworkRequest(char *urlPath, int requestID, struct reqMetadata metadata) {
    // Acquire the mutex to protect the pool
    pthread_mutex_lock(&requestPoolMutex);

    // Check if there is still capacity in the pool
    if (pool->count < pool->capacity) {
        // Allocate a new request structure and add it to the pool
        struct networkRequest *newReq = (struct networkRequest *)malloc(sizeof(struct networkRequest));
        newReq->urlPath = urlPath;
        newReq->requestID = requestID;
        newReq->metadata = metadata;
        pool->requests[pool->count++] = newReq;
    } else {
        // There is no more capacity in the pool, so we need to reallocate it
        size_t newCapacity = pool->capacity * 2;
        struct networkRequest *newPool = (struct networkRequest *)realloc(pool->requests, sizeof(struct networkRequest) * newCapacity);
        if (newPool == NULL) {
            // Reallocation failed, so we need to abort the operation
            pthread_mutex_unlock(&requestPoolMutex);
            return;
        }
        pool->capacity = newCapacity;
        pool->requests = newPool;

        // Allocate a new request structure and add it to the pool
        struct networkRequest *newReq = (struct networkRequest *)malloc(sizeof(struct networkRequest));
        newReq->urlPath = urlPath;
        newReq->requestID = requestID;
        newReq->metadata = metadata;
        pool->requests[pool->count++] = newReq;
    }

    // Release the mutex
    pthread_mutex_unlock(&requestPoolMutex);
}

// Function to deallocate a request structure from the pool and update its metadata
void deallocateNetworkRequest(int requestID) {
    // Acquire the mutex to protect the pool
    pthread_mutex_lock(&requestPoolMutex);

    // Find the request with the given ID in the pool
    size_t i;
    for (i = 0; i < pool->count; i++) {
        if (pool->requests[i]->requestID == requestID) {
            break;
        }
    }

    // If we found the request, deallocate its memory and remove it from the pool
    if (i < pool->count) {
        free(pool->requests[i]);
        pool->count--;
        memmove(&pool->requests[i], &pool->requests[i + 1], sizeof(struct networkRequest) * (pool->count - i));
    } else {
        // We didn't find the request, so we need to abort the operation
        pthread_mutex_unlock(&requestPoolMutex);
        return;
    }

    // Release the mutex
    pthread_mutex_unlock(&requestPoolMutex);
}

// Function to send a network request and update its metadata
void sendNetworkRequest(char *urlPath, int requestID, struct reqMetadata metadata) {
    // Acquire the mutex to protect the pool
    pthread_mutex_lock(&requestPoolMutex);

    // Find the request with the given ID in the pool
    size_t i;
    for (i = 0; i < pool->count; i++) {
        if (pool->requests[i]->requestID == requestID) {
            break;
        }
    }

    // If we found the request, update its metadata and send it
    if (i < pool->count) {
        struct networkRequest *req = pool->requests[i];
        req->metadata = metadata;
        // Send the request over the network...
    } else {
        // We didn't find the request, so we need to allocate a new one and send it
        allocateNetworkRequest(urlPath, requestID, metadata);
    }

    // Release the mutex
    pthread_mutex_unlock(&requestPoolMutex);
}

// Function to handle a network response and update its metadata
void handleNetworkResponse(char *urlPath, int requestID, struct reqMetadata metadata) {
    // Acquire the mutex to protect the pool
    pthread_mutex_lock(&requestPoolMutex);

    // Find the request with the given ID in the pool
    size_t i;
    for (i = 0; i < pool->count; i++) {
        if (pool->requests[i]->requestID == requestID) {
            break;
        }
    }

    // If we found the request, update its metadata and deallocate it from the pool
    if (i < pool->count) {
        struct networkRequest *req = pool->requests[i];
        req->metadata = metadata;
        deallocateNetworkRequest(requestID);
    } else {
        // We didn't find the request, so we need to abort the operation
        pthread_mutex_unlock(&requestPoolMutex);
        return;
    }

    // Release the mutex
    pthread_mutex_unlock(&requestPoolMutex);
}
