void handleFileOperations(const char* path, enum fileOperation operation, int version) {
    // Validate inputs and ensure they correspond to supported operations
    if (path == NULL || operation < READ || operation > TRUNCATE) return;

    // Get file metadata from cache or allocate new metadata
    fileMetadata* metadata = getMetadata(path);
    if (metadata == NULL) {
        metadata = malloc(sizeof(fileMetadata));
        strcpy(metadata->path, path);
        metadata->size = 0;
        metadata->version = -1;
