    // Get file descriptor from cache or open new file descriptor
    fileBuffer* buffer = getBuffer(params.blockSize * params.concurrency);
    if (buffer == NULL) return;

    // Set file descriptor in file buffer and set file version number
    int fd = -1;
    switch (operation) {
        case READ:
            fd = open(path, O_RDONLY);
            break;
        case WRITE:
            fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, S_IRUSR | S_IWUSR);
            break;
    }
    setFileDescriptor(buffer, fd);
    setVersionNumber(metadata, version);

    // Read or write file data in file buffer
    if (fd > 0) {
        switch (operation) {
            case READ:
                read(fd, buffer->data, params.blockSize * params.concurrency);
                break;
            case WRITE:
                write(fd, buffer->data, params.blockSize * params.concurrency);
                break;
        }
    }

    // Update file metadata cache with new version number
    updateMetadataCache(metadata);
}

// Handle file operations concurrently using pthread library
void handleFileOperationsConcurrently(const char* path, enum fileOperation operation, int version) {
    // Validate inputs and ensure they correspond to supported operations
    if (path == NULL || operation < READ || operation > TRUNCATE) return;

    // Get file metadata from cache or allocate new metadata
    fileMetadata* metadata = getMetadata(path);
    if (metadata == NULL) {
        metadata = malloc(sizeof(fileMetadata));
        strcpy(metadata->path, path);
        metadata->size = 0;
        metadata->version = -1;
    }

    // Allocate memory for file buffers and set file version number
    fileBuffer* buffer = getBuffer(params.blockSize * params.concurrency);
    if (buffer == NULL) return;
    setVersionNumber(metadata, version);

    // Create pthread attributes and detach from parent thread
    pthread_attr_t attr;
    pthread_attr_init(&attr);
    pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_DETACHED);

    // Create and start threads for read or write operations
    switch (operation) {
        case READ:
            for (int i = 0; i < params.concurrency; i++) {
                pthread_t thread;
                pthread_create(&thread, &attr, handleFileOperations, path);
            }
            break;
        case WRITE:
            for (int i = 0; i < params.concurrency; i++) {
                pthread_t thread;
                pthread_create(&thread, &attr, handleFileOperations, path);
            }
            break;
    }
}

// Free memory allocated for file buffers and metadata cache
void freeMemory() {
    deallocateBuffer(bufferPool.buffers);
    deallocateMetadata(metadataCache.cache);
