        return INT_MIN;
    }
    int max = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    return max;
}

// Calculate the average timestamp difference between consecutive records within a batch
double averageTimestampDiff(long *offsets, int size) {
