// Define the data structure to store tasks
typedef struct {
    char* description; // Descriptive string of the task
    int priority; // Priority level of the task (integer)
    double start_time; // Start time of the task (seconds since epoch)
} Task;

// Define a list to store tasks
typedef struct {
    Task* tasks; // Array of tasks
    size_t capacity; // Capacity of the list
    size_t size; // Number of tasks in the list
} TaskList;

// Function to add a new task to the list
void addTask(TaskList* list, char* description, int priority, double start_time) {
    if (list->size == list->capacity) { // If the list is full, resize it
        list->tasks = realloc(list->tasks, 2 * list->capacity * sizeof(Task));
        list->capacity *= 2;
    }
    Task* new_task = malloc(sizeof(Task));
    new_task->description = strdup(description);
    new_task->priority = priority;
    new_task->start_time = start_time;
    list->tasks[list->size++] = *new_task;
}

// Function to remove a task from the list by its index
void removeTask(TaskList* list, size_t index) {
    if (index >= list->size || index < 0) { // If the index is invalid, return
        return;
    }
    for (size_t i = index + 1; i < list->size; i++) { // Shift elements to fill the gap
        list->tasks[i - 1] = list->tasks[i];
    }
    free(list->tasks[--list->size]); // Free the removed task
}

// Function to update the priority of a task by its index
void updatePriority(TaskList* list, size_t index, int new_priority) {
    if (index >= list->size || index < 0) { // If the index is invalid, return
        return;
    }
    list->tasks[index].priority = new_priority; // Update the priority of the task
}

// Function to sort the list of tasks based on either priority or start time
void sortTasks(TaskList* list, int order) {
    if (order == 0) { // Sort by priority
        qsort(list->tasks, list->size, sizeof(Task), comparePriority);
    } else { // Sort by start time
        qsort(list->tasks, list->size, sizeof(Task), compareStartTime);
    }
}

// Function to compare tasks based on priority
int comparePriority(const void* a, const void* b) {
    Task* task_a = (Task*)a;
    Task* task_b = (Task*)b;
    if (task_a->priority > task_b->priority) { // Priority is greater
        return 1;
    } else if (task_a->priority < task_b->priority) { // Priority is lesser
        return -1;
    } else { // Priorities are equal, compare start times
        return compareStartTime(a, b);
    }
}

// Function to compare tasks based on start time
int compareStartTime(const void* a, const void* b) {
    Task* task_a = (Task*)a;
    Task* task_b = (Task*)b;
    if (task_a->start_time > task_b->start_time) { // Start time is greater
        return 1;
    } else if (task_a->start_time < task_b->start_time) { // Start time is lesser
        return -1;
    } else { // Start times are equal, compare priorities
        return comparePriority(a, b);
    }
}']

