#include <stdlib.h>
#include <pthread.h>

struct log_entry {
    long offset;
    int key;
    struct record {
        int value1;
        double timestamp;
    } record;
};

typedef struct log_entry log_entry_t;

struct log_list {
    pthread_mutex_t mutex;
    log_entry_t *head;
    log_entry_t *tail;
    int max_entries;
    int entry_count;
};

typedef struct log_list log_list_t;

void log_add(log_list_t *list, long offset, int key, struct record {
        int value1;
        double timestamp;
} record) {
    pthread_mutex_lock(&list->mutex);

    // Check if the maximum number of entries has been reached
    if (list->entry_count == list->max_entries) {
        // Remove the oldest entry
        log_entry_t *oldest = list->head;
        list->head = list->head->next;
        free(oldest);

        // Decrement the total number of entries
        list->entry_count--;
    }

    // Create a new entry and add it to the end of the list
    log_entry_t *new_entry = malloc(sizeof(log_entry_t));
    if (!new_entry) {
        pthread_mutex_unlock(&list->mutex);
        return NULL; // Error: memory allocation failed
    }

    new_entry->offset = offset;
    new_entry->key = key;
    new_entry->record.value1 = record.value1;
    new_entry->record.timestamp = record.timestamp;

    list->tail->next = new_entry;
    list->tail = new_entry;

    // Increment the total number of entries
    list->entry_count++;

    pthread_mutex_unlock(&list->mutex);
}

void log_remove(log_list_t *list, int key) {
    pthread_mutex_lock(&list->mutex);

    // Find the entry with the given key
    log_entry_t *curr = list->head;
    while (curr != NULL && curr->key != key) {
        curr = curr->next;
    }

    if (curr == NULL) {
        pthread_mutex_unlock(&list->mutex);
        return; // Error: entry not found
    }

    // Remove the entry from the list
    log_entry_t *prev = curr->prev;
    log_entry_t *next = curr->next;
    if (prev == NULL) {
        list->head = next;
    } else {
        prev->next = next;
    }
    if (next != NULL) {
        next->prev = prev;
    } else {
        list->tail = prev;
    }

    // Decrement the total number of entries
    list->entry_count--;

    pthread_mutex_unlock(&list->mutex);
}

void log_get(log_list_t *list, int key, struct record {
        int value1;
        double timestamp;
} *record) {
    pthread_mutex_lock(&list->mutex);

    // Find the entry with the given key
    log_entry_t *curr = list->head;
    while (curr != NULL && curr->key != key) {
        curr = curr->next;
    }

    if (curr == NULL) {
        pthread_mutex_unlock(&list->mutex);
        return; // Error: entry not found
    }

    // Copy the record data into the given buffer
    *record = curr->record;

    pthread_mutex_unlock(&list->mutex);
}

void log_clear(log_list_t *list) {
    pthread_mutex_lock(&list->mutex);

    // Remove all entries from the list
    log_entry_t *curr = list->head;
    while (curr != NULL) {
        log_entry_t *next = curr->next;
        free(curr);
        curr = next;
    }

    list->head = NULL;
    list->tail = NULL;
    list->entry_count = 0;

    pthread_mutex_unlock(&list->mutex);
}
