// Data structure to represent a task
struct Task {
    char *description;
    int priority;
    double start_time;
};

// Data structure to store the list of tasks
struct TaskList {
    struct Task **tasks;
    size_t size;
    size_t capacity;
};

// Initializes a task list with a given initial capacity
void init_task_list(struct TaskList *list, size_t capacity) {
    list->tasks = malloc(capacity * sizeof(struct Task *));
    if (!list->tasks) {
        perror("Failed to allocate memory for task list");
        exit(EXIT_FAILURE);
    }
    list->size = 0;
    list->capacity = capacity;
}

// Adds a new task to the task list
void add_task(struct TaskList *list, const char *description, int priority) {
    // Grow the task list if necessary
    if (list->size == list->capacity) {
        struct Task **new_tasks = realloc(list->tasks, 2 * list->capacity * sizeof(struct Task *));
        if (!new_tasks) {
            perror("Failed to grow task list");
            exit(EXIT_FAILURE);
        }
        list->tasks = new_tasks;
        list->capacity *= 2;
    }

    // Create a new task and add it to the list
    struct Task *task = malloc(sizeof(struct Task));
    if (!task) {
        perror("Failed to allocate memory for new task");
        exit(EXIT_FAILURE);
    }
    task->description = strdup(description);
    task->priority = priority;
    task->start_time = clock(); // start time in seconds since the epoch
    list->tasks[list->size++] = task;
}

// Removes a task from the task list by its index
void remove_task(struct TaskList *list, size_t index) {
    if (index >= list->size) {
        fprintf(stderr, "Invalid index for removing task\n");
        exit(EXIT_FAILURE);
    }

    // Free the memory allocated for the removed task
    free(list->tasks[index]->description);
    free(list->tasks[index]);

    // Shift all tasks that follow the removed task to the left by one index
    memmove(&list->tasks[index], &list->tasks[index + 1], (list->size - index - 1) * sizeof(struct Task *));
    list->size--;
}

// Updates the priority of a task in the task list by its index
void update_task_priority(struct TaskList *list, size_t index, int new_priority) {
    if (index >= list->size) {
        fprintf(stderr, "Invalid index for updating task priority\n");
        exit(EXIT_FAILURE);
    }
    list->tasks[index]->priority = new_priority;
}

// Sorts the task list based on either priority or start time
void sort_task_list(struct TaskList *list, int priority) {
    // Use a stable sorting algorithm to ensure that equal priorities/start times are preserved
    qsort(list->tasks, list->size, sizeof(struct Task *), priority ? compare_priority : compare_start_time);
}

// Compare function for sorting tasks based on their priorities
int compare_priority(const void *a, const void *b) {
    struct Task **task1 = (struct Task **)a;
    struct Task **task2 = (struct Task **)b;
    return (*task1)->priority - (*task2)->priority;
}

// Compare function for sorting tasks based on their start times
int compare_start_time(const void *a, const void *b) {
    struct Task **task1 = (struct Task **)a;
    struct Task **task2 = (struct Task **)b;
    return (*task1)->start_time - (*task2)->start_time;
}

// Prints the tasks in the task list
void print_tasks(struct TaskList *list) {
    for (size_t i = 0; i < list->size; i++) {
        struct Task *task = list->tasks[i];
        printf("Task %zu: %s (priority: %d, start time: %.2f)\n", i, task->description, task->priority, task->start_time / CLOCKS_PER_SEC);
    }
}
```
