// Define the record structure
typedef struct {
  int key;
  double timestamp;
} Record;

// Function to process and aggregate records from standard input and a file
int processAndAggregateRecords(const char* configFilePath, int maxNumRecords) {
  // Declare variables for dynamic memory allocation
  long *offsetArray = NULL;
  Record *recordArray = NULL;

  // Load the configuration file and allocate memory for the arrays
  FILE *configFile = fopen(configFilePath, "r");
  if (configFile == NULL) {
    printf("Error: unable to open configuration file\n");
    return -1;
  }
  offsetArray = malloc(maxNumRecords * sizeof(long));
  recordArray = malloc(maxNumRecords * sizeof(Record));
  if (offsetArray == NULL || recordArray == NULL) {
    printf("Error: unable to allocate memory for arrays\n");
    fclose(configFile);
    return -1;
  }

  // Read records from the configuration file and fill in the arrays
  int numRecords = 0;
  while (fscanf(configFile, "%d %ld", &recordArray[numRecords].key, &offsetArray[numRecords]) == 2) {
    recordArray[numRecords].timestamp = time(NULL);
    numRecords++;
    if (numRecords >= maxNumRecords) {
      break;
    }
  }
  fclose(configFile);

  // Process records from standard input and add them to the arrays
  while (true) {
    int key = getIntFromUser("Enter a record key: ");
    if (key == -1) {
      break;
    }
    long offset = getLongFromUser("Enter an offset value: ");
    Record newRecord;
    newRecord.key = key;
    newRecord.timestamp = time(NULL);
    if (offsetArray[numRecords] != -1) {
      offsetArray[numRecords] += offset;
    } else {
      offsetArray[numRecords] = offset;
    }
    recordArray[numRecords] = newRecord;
    numRecords++;
    if (numRecords >= maxNumRecords) {
      break;
    }
  }

  // Clean up memory and return
  free(offsetArray);
  free(recordArray);
  return 0;
}
```
