// Function to process and store sensor data
int processAndStoreSensorData(float *data, int numRecords) {
    // Initialize variables for tracking total number of records processed and data size
    int totalNumRecords = 0;
    int totalDataSize = 0;

    // Initialize arrays for storing data values and labels
    float *dataValues = NULL;
    char *labels = NULL;

    // Create a sensorRecord structure to hold data values and labels
    sensorRecord *sensorRecords = NULL;

    // Initialize an error code variable
    int errCode = 0;

    // Check if the input number of records is valid
    if (numRecords <= 0) {
        fprintf(stderr, "Invalid number of records: %d\n", numRecords);
        return -1;
    }

    // Allocate memory for data values and labels arrays
    errCode = posix_memalign((void **)&dataValues, 4096, sizeof(float) * numRecords);
    if (errCode != 0) {
        fprintf(stderr, "Memory allocation failed: %s\n", strerror(errCode));
        return -1;
    }
    errCode = posix_memalign((void **)&labels, 4096, sizeof(char) * numRecords);
    if (errCode != 0) {
        fprintf(stderr, "Memory allocation failed: %s\n", strerror(errCode));
        free(dataValues);
        return -1;
    }

    // Allocate memory for the sensorRecord structure
    errCode = posix_memalign((void **)&sensorRecords, 4096, sizeof(sensorRecord) * numRecords);
    if (errCode != 0) {
        fprintf(stderr, "Memory allocation failed: %s\n", strerror(errCode));
        free(dataValues);
        free(labels);
        return -1;
    }

    // Loop through the input data and process each record
    for (int i = 0; i < numRecords; i++) {
        // Process the current record
        float value = data[i];
        char label = getLabel(value);

        // Store the processed record in the appropriate arrays
        dataValues[totalNumRecords] = value;
        labels[totalNumRecords] = label;
        sensorRecords[totalNumRecords].value = value;
        sensorRecords[totalNumRecords].label = label;

        // Increment the total number of records and data size
        totalNumRecords++;
        totalDataSize += sizeof(float) + sizeof(char);

        // Check if the batch size has been exceeded
        if (totalNumRecords >= 5000) {
            // Save excess data to a temporary file for later processing
            FILE *tempFile = fopen("excess_data.txt", "w");
            if (tempFile == NULL) {
                fprintf(stderr, "Error creating temp file: %s\n", strerror(errno));
                free(dataValues);
                free(labels);
                free(sensorRecords);
                return -1;
            }
            for (int j = 5000; j < totalNumRecords; j++) {
                fprintf(tempFile, "%f %c\n", dataValues[j], labels[j]);
            }
            fclose(tempFile);

            // Reset the batch size counter and release excess memory
            totalNumRecords = 5000;
            free(dataValues + 5000);
            free(labels + 5000);
        }
    }

    // Print the highest float value found among the provided inputs
    printf("Highest float value: %f\n", getMaxValue(dataValues, totalNumRecords));

    // Release memory allocated for data values and labels arrays
    free(dataValues);
    free(labels);

    // Release memory allocated for the sensorRecord structure
    free(sensorRecords);

    return 0;
}

// Function to get a label for a given float value
char getLabel(float value) {
    if (value < 0) {
        return 'T'; // Temperature
    } else {
        return 'H'; // Humidity
    }
}

// Function to get the maximum value from an array of floats
float getMaxValue(float *arr, int numRecords) {
    float maxValue = arr[0];
    for (int i = 1; i < numRecords; i++) {
        if (arr[i] > maxValue) {
            maxValue = arr[i];
        }
    }
    return maxValue;
}
