    assert(logFile != NULL);
    for (int i = 0; i < num_events; i++) {
        char buffer[1024];
        snprintf(buffer, sizeof(buffer), "%d %s %.3f %f\n", events[i].key, events[i].label, events[i].timestamp, events[i].metric);
        fputs(buffer, logFile);
    }
    fclose(logFile);

    // Export the final list of records to a CSV file named "metrics.csv"
    FILE* csvFile = fopen("metrics.csv", "w");
    assert(csvFile != NULL);
    for (int i = 0; i < num_events; i++) {
        char buffer[1024];
        snprintf(buffer, sizeof(buffer), "%d,%s,%f\n", events[i].key, events[i].label, events[i].metric);
        fputs(buffer, csvFile);
    }
    fclose(csvFile);

    // Free allocated memory for the event records
    free(events);
}

// Define a function to generate a random label based on predefined word lists
