    long* offsets = (long*)malloc(config.batch_size * sizeof(long));
    int* keys = (int*)malloc(config.batch_size * config.key_size * sizeof(int));
    Record* records = (Record*)malloc(config.batch_size * sizeof(Record));

    // Set up the thread pool
    pthread_t threads[config.num_threads];
    for (int i = 0; i < config.num_threads; ++i) {
        pthread_create(&threads[i], NULL, processBatch, &config);
    }

    // Join the threads and print the results
    for (int i = 0; i < config.num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }
    printf("Processed %d records with maximum value %d\n", config.num_records, maxValue);
    free(offsets);
    free(keys);
    free(records);
}

void* processBatch(void* args) {
    // Get the configuration and record arrays
    Config* config = (Config*)args;
    long* offsets = (long*)malloc(config->batch_size * sizeof(long));
    int* keys = (int*)malloc(config->batch_size * config->key_size * sizeof(int));
    Record* records = (Record*)malloc(config->batch_size * sizeof(Record));

    // Initialize the offsets and keys
    for (int i = 0; i < config->batch_size; ++i) {
        offsets[i] = (long)(rand() % (config->range_max - config->range_min)) + config->range_min;
        for (int j = 0; j < config->key_size; ++j) {
            keys[i * config->key_size + j] = (int)(rand() % (config->range_max - config->range_min)) + config->range_min;
        }
    }

    // Initialize the records with random values and timestamps
    for (int i = 0; i < config->batch_size; ++i) {
        records[i].value = (int)(rand() % (config->range_max - config->range_min)) + config->range_min;
        records[i].timestamp = (double)time(NULL);
    }

    // Apply the filtering mechanism if necessary
    if (config->filter_callback != NULL) {
        filterRecords(records, config->batch_size, config->filter_callback);
    }

    // Print the results if necessary
    if (config->print_results) {
        for (int i = 0; i < config->batch_size; ++i) {
            printf("Record %d: value=%d, timestamp=%.3f\n", i, records[i].value, records[i].timestamp);
        }
    }

    // Free the offsets and keys
    free(offsets);
    free(keys);
    free(records);
}

void filterRecords(Record* records, int num_records, void (*filter_callback)(int)) {
    // Apply the filtering mechanism to the records
    for (int i = 0; i < num_records; ++i) {
        if (!filter_callback(records[i].value)) {
            // If the filter returns false, remove the record from the array
            for (int j = i; j < num_records - 1; ++j) {
                records[j] = records[j + 1];
            }
            --num_records;
        }
    }
}
```

This code uses the `pthread` library to create a thread pool and process the data in parallel. The `processAndAggregateRecords` function takes in the configuration parameters, including the range of values and the number of threads to use, as well as a boolean flag indicating whether or not to print the results.

The `processBatch` function is responsible for processing each batch of records independently. It first initializes the offsets and keys arrays using random numbers within the specified range, then initializes the records with random values and timestamps. If a filtering callback was provided, it applies the filter to the records before continuing. Finally, it prints the results if necessary.

The `filterRecords` function takes in an array of records, the number of records, and a pointer to a filtering callback function. It then applies the filtering mechanism to each record independently, removing any records that do not pass the filter test.']

