// Custom data structure for efficiently determining disjoint pairs of elements in a double array
typedef struct {
    int *indices; // Indices of the disjoint pairs in the original array
    size_t numPairs; // Number of disjoint pairs found
} DisjointPairArray;

// Custom function for determining disjoint pairs of elements in a double array
void findDisjointPairs(const double *metrics, const size_t numMetrics, DisjointPairArray *result) {
    // Initialize the result struct with an empty list of indices
    result->numPairs = 0;
    result->indices = NULL;

    // Create a temporary array for storing the indices of the disjoint pairs
    int *tmpIndices = (int *)malloc(numMetrics * sizeof(int));
    if (!tmpIndices) {
        // Handle memory allocation failure
        printf("Error: unable to allocate memory for temporary indices\n");
        return;
    }

    // Iterate over the metric values and find disjoint pairs
    size_t i = 0, j = 1;
    while (i < numMetrics && j < numMetrics) {
        if (metrics[i] != metrics[j]) {
            // Add the current index to the list of indices for the current disjoint pair
            tmpIndices[result->numPairs++] = i;
            // Increment both pointers to the next element in the array
            ++i, ++j;
        } else {
            // Skip over duplicate elements and increment the second pointer only
            ++j;
        }
    }

    // Copy the temporary indices list into the result struct
    result->indices = (int *)malloc(result->numPairs * sizeof(int));
    if (!result->indices) {
        // Handle memory allocation failure
        printf("Error: unable to allocate memory for final indices\n");
        free(tmpIndices);
        return;
    }
    memcpy(result->indices, tmpIndices, result->numPairs * sizeof(int));

    // Clean up temporary resources
    free(tmpIndices);
}

// Custom function for calculating the average, minimum, and maximum values in a double array
void calculateStats(const double *metrics, const size_t numMetrics, double *result) {
