void processSensorData(struct SensorReading* readings, int numReadings) {
    // Allocate memory for the readings
    struct SensorReading* buffer = (struct SensorReading*)malloc(numReadings * sizeof(struct SensorReading));
    if (!buffer) {
        // Handle error
    }

    // Loop through each reading and classify it as high-quality or low-quality
    for (int i = 0; i < numReadings; i++) {
        struct SensorReading* reading = &readings[i];
        if (reading->temperature > HIGH_QUALITY_TEMPERATURE && reading->humidity > HIGH_QUALITY_HUMIDITY) {
            buffer[numHighQualityReadings++] = *reading;
        } else {
            buffer[numLowQualityReadings++] = *reading;
        }
    }

    // Free the memory allocated for the readings
    free(buffer);
}
