    struct memory_node* next;
} MemoryNode;

typedef struct key_track {
    int uses; // number of times the key has been used
    pthread_mutex_t mutex; // lock for concurrent access
} KeyTrack;

// Function prototypes
void* processAndFindMax(void* args);
int allocateMemory(size_t size, void** data);
void deallocateMemory(void* data, size_t size);
int getRandomInt();
double getCurrentTimestamp();
pthread_mutex_t* createMutex();
KeyTrack* createKeyTrack(int key);

// Function implementations

/**
 * Processes the given inputs and finds the largest integer.
 */
void* processAndFindMax(void* args) {
    // Parse arguments
    int num_keys = (int)args;
    assert(num_keys > 0 && num_keys <= MAX_NUM_KEYS);

    // Initialize data structures
    MemoryNode* memory = NULL; // list of allocated memory nodes
    KeyTrack** keys = malloc(sizeof(KeyTrack*) * num_keys); // array of key tracks
    for (int i = 0; i < num_keys; ++i) {
        keys[i] = createKeyTrack(i);
    }
    Record* records = calloc(NUM_RECORDS, sizeof(Record));

    // Populate records with random integer values and timestamps
    for (int i = 0; i < NUM_RECORDS; ++i) {
        records[i].value = getRandomInt();
        records[i].timestamp = getCurrentTimestamp();
    }

    // Sort records by value in ascending order
    qsort(records, NUM_RECORDS, sizeof(Record), compareRecordsByValue);

    // Find the largest integer and print it
    int max_value = 0;
    for (int i = 0; i < NUM_RECORDS; ++i) {
        if (records[i].value > max_value) {
            max_value = records[i].value;
        }
    }
    printf("Largest integer: %d\n", max_value);

    // Clean up allocated memory and return success code
    deallocateMemory(records, sizeof(Record) * NUM_RECORDS);
    for (int i = 0; i < num_keys; ++i) {
        destroyKeyTrack(keys[i]);
    }
    free(keys);
    return NULL;
}

/**
 * Compares two records by their values in ascending order.
 */
int compareRecordsByValue(const void* a, const void* b) {
    const Record* ra = (const Record*)a;
    const Record* rb = (const Record*)b;
    return ra->value - rb->value;
}

/**
 * Allocates memory for the given size and returns a pointer to it.
 */
int allocateMemory(size_t size, void** data) {
    // Check for invalid input
    if (size == 0 || data == NULL) {
        return -1;
    }

    // Allocate memory
    MemoryNode* node = malloc(sizeof(MemoryNode));
    if (node == NULL) {
        return -2;
    }

    // Initialize memory node
    node->data = malloc(size);
    if (node->data == NULL) {
        free(node);
        return -3;
    }
    node->size = size;
    node->next = NULL;

    // Add memory node to the end of the list
    MemoryNode* current = memory;
    while (current != NULL && current->next != NULL) {
        current = current->next;
    }
    if (current == NULL) {
        memory = node;
    } else {
        current->next = node;
    }

    // Return a pointer to the allocated memory
    *data = node->data;
    return 0;
}

/**
 * Deallocates memory for the given data and size.
 */
void deallocateMemory(void* data, size_t size) {
    // Check for invalid input
    if (data == NULL || size == 0) {
        return;
    }

    // Find the memory node containing the given data
    MemoryNode* current = memory;
    while (current != NULL && current->data != data) {
        current = current->next;
    }
    if (current == NULL) {
        return;
    }

    // Deallocate the memory node and remove it from the list
    void* next_node = current->next;
    free(current->data);
    free(current);
    if (memory == current) {
        memory = next_node;
    } else {
        MemoryNode* previous = NULL;
        while (previous != NULL && previous->next != current) {
            previous = previous->next;
        }
        assert(previous != NULL);
        previous->next = next_node;
    }
}

/**
 * Generates a random integer within the specified range.
 */
int getRandomInt() {
    return rand() % (MAX_RAND_INT - MIN_RAND_INT + 1) + MIN_RAND_INT;
}

/**
 * Returns the current timestamp in milliseconds since the epoch.
 */
double getCurrentTimestamp() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    return (double)ts.tv_sec * 1000 + (double)ts.tv_nsec / 1e6;
}

/**
 * Creates a new mutex for concurrent access to the key track.
 */
pthread_mutex_t* createMutex(int key) {
    // Check for invalid input
    if (key < 0 || key > INT_MAX) {
        return NULL;
    }

    // Create a new mutex and add it to the hash table
    pthread_mutex_t* mutex = malloc(sizeof(pthread_mutex_t));
    if (mutex == NULL) {
        return NULL;
    }
    int ret = pthread_mutex_init(mutex, NULL);
    if (ret != 0) {
        free(mutex);
        return NULL;
    }
    hashTable[key] = mutex;

    // Return the newly created mutex
    return mutex;
}

/**
 * Destroys a previously created mutex.
 */
void destroyMutex(pthread_mutex_t* mutex) {
    // Check for invalid input
    if (mutex == NULL) {
        return;
    }

    // Destroy the mutex and remove it from the hash table
    int ret = pthread_mutex_destroy(mutex);
    if (ret != 0) {
        return;
    }
    hashTable[key] = NULL;
}
