#include <stdlib.h>
#include <stdio.h>
#include <time.h>
#include <pthread.h>

struct record {
    int key;
    long offset;
    struct record *next;
    int value;
    double timestamp;
};

typedef struct {
    struct record *head;
    pthread_mutex_t mutex;
} list;

void init(list *l) {
    l->head = NULL;
    pthread_mutex_init(&l->mutex, NULL);
}

int insert(list *l, int key, long offset, int value) {
    struct record *new_record = malloc(sizeof(struct record));
    if (new_record == NULL) {
        return -1; // Memory allocation failed.
    }

    new_record->key = key;
    new_record->offset = offset;
    new_record->value = value;
    new_record->timestamp = time(NULL);
    pthread_mutex_lock(&l->mutex);
    struct record *current = l->head;
    if (current == NULL) {
        current = new_record;
    } else {
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_record;
    }
    pthread_mutex_unlock(&l->mutex);
    return 0;
}

int remove(list *l, int key) {
    pthread_mutex_lock(&l->mutex);
    struct record *current = l->head;
    struct record *previous = NULL;
    while (current != NULL && current->key != key) {
        previous = current;
        current = current->next;
    }
    if (current == NULL) {
        pthread_mutex_unlock(&l->mutex);
        return -1; // Key not found.
    }
    if (previous != NULL) {
        previous->next = current->next;
    } else {
        l->head = current->next;
    }
    free(current);
    pthread_mutex_unlock(&l->mutex);
    return 0;
}

int retrieve(list *l, int key) {
    struct record *record = NULL;
    pthread_mutex_lock(&l->mutex);
    struct record *current = l->head;
    while (current != NULL && current->key != key) {
        current = current->next;
    }
    if (current == NULL) {
        pthread_mutex_unlock(&l->mutex);
        return -1; // Key not found.
    }
    record = current;
    pthread_mutex_unlock(&l->mutex);
    return 0;
}
```
