int event_log_init(struct event_log* log) {
    // Initialize the event log structure
    log->events = NULL;
    log->num_events = 0;
    log->max_events = INITIAL_EVENT_CAPACITY;

    // Allocate memory for the initial events array
    log->events = malloc(log->max_events * sizeof(struct event));
    if (log->events == NULL) {
        fprintf(stderr, "Failed to allocate memory for events\n");
        return -1;
    }

    // Initialize the current time in milliseconds since the epoch
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    log->current_timestamp = (int64_t)ts.tv_sec * 1000 + (int64_t)ts.tv_nsec / 1000000;

    return 0;
}

void event_log_add(struct event_log* log, struct event* ev) {
    // Check if the event log is full and needs to be resized
    if (log->num_events == log->max_events) {
        // Resize the events array by a factor of 2
        log->max_events *= 2;
        struct event* new_events = realloc(log->events, log->max_events * sizeof(struct event));
        if (new_events == NULL) {
            fprintf(stderr, "Failed to resize events array\n");
            return;
        }
        log->events = new_events;
    }

    // Copy the event into the next available slot in the events array
    struct event* dest = &log->events[log->num_events];
    memcpy(dest, ev, sizeof(struct event));
    dest->id = generate_unique_identifier();
    log->num_events++;
}

void event_log_free(struct event_log* log) {
    // Free the events array and set the structure to an empty state
    free(log->events);
    log->events = NULL;
    log->num_events = 0;
    log->max_events = INITIAL_EVENT_CAPACITY;
