int parseAndAggregateMetrics(FILE* fp) {
    int error = 0; // Error code
    long total_duration = 0; // Total duration between consecutive log entries
    int frequent_status_code = -1; // Most frequent status code
    int longest_payload = -1; // Longest payload in terms of character count
    int shortest_payload = INT_MAX; // Shortest payload in terms of character count
    int num_log_entries = 0; // Number of log entries processed
