        int payload_length = strlen(log->payload);
        if (payload_length > longest_payload) {
            longest_payload = payload_length;
        }
        if (payload_length < shortest_payload) {
            shortest_payload = payload_length;
        }

        // Increment number of log entries processed
        num_log_entries++;
    }

