    printf("Total duration: %ld\n", total_duration);
    printf("Frequent status code: %d\n", frequent_status_code);
    printf("Longest payload: %d\n", longest_payload);
    printf("Shortest payload: %d\n", shortest_payload);

    // Clean up allocated resources
    free(log);

    return error;
}

// Function to read a log entry from the file and parse it as a struct
log_entry* readLogEntry(FILE* fp) {
    char line[1024]; // Line of text from the file
    long timestamp; // Time stamp of the log entry
    int status_code; // Status code of the log entry
    char payload[1024]; // Payload of the log entry (string of alphanumeric characters)

    // Read a line from the file and parse it as a struct
    if (fgets(line, 1024, fp) == NULL) {
        return NULL;
    }
    sscanf(line, "%ld %d %s", &timestamp, &status_code, payload);

