// Define the node structure for the linked list
typedef struct Node {
    char* string;
    int priority;
    struct time_info time_info;
    struct Node* next;
} Node;

// Define the function to manage the linked list of nodes
int manage_list(char* prefix, int min_priority, int max_priority) {
    // Initialize the linked list head and tail pointers
    Node* head = NULL;
    Node* tail = NULL;

    // Loop through the input data and create a new node for each string
    while (prefix != NULL) {
        // Allocate memory for the new node
        Node* new_node = malloc(sizeof(Node));
        if (new_node == NULL) {
            printf("Error: Memory allocation failed\n");
            return -1;
        }

        // Set the string, priority level, and time information in the new node
        new_node->string = prefix;
        new_node->priority = rand() % (max_priority - min_priority + 1) + min_priority;
        new_node->time_info.seconds = time(NULL);
        new_node->time_info.microseconds = 0;

        // Hash the string to generate a unique identifier
        unsigned long hash = hash_string(prefix, strlen(prefix));

        // Update the current time in the new node's time information
        update_time(&new_node->time_info);

        // Insert the new node at the tail of the linked list
        if (head == NULL) {
            head = new_node;
            tail = new_node;
        } else {
            tail->next = new_node;
            tail = new_node;
        }

        // Move on to the next string in the input data
        prefix = strtok(NULL, ",");
    }

    // Free memory for the linked list nodes
    Node* current = head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    return 0;
}

// Hash a string to generate a unique identifier
unsigned long hash_string(char* str, int len) {
    unsigned long hash = 5381;
    for (int i = 0; i < len; i++) {
        hash = ((hash << 5) + hash) ^ str[i];
    }
    return hash;
}

// Update the time information in a node
void update_time(struct time_info* time_info) {
    struct timespec current_time;
    clock_gettime(CLOCK_REALTIME, &current_time);
    time_info->seconds = current_time.tv_sec;
    time_info->microseconds = current_time.tv_nsec / 1000;
}
