    NFAPI_CRC_INDICATION_PDU_T* crcIndications = malloc(length * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!crcIndications) {
        free(offsets);
        free(keys);
        fprintf(stderr, "Failed to allocate memory for CRC indications\n");
        return -1;
    }

    // Initialize the timestamp for each record
    for (unsigned int i = 0; i < length; ++i) {
        crcIndications[i].timestamp = time(NULL);
    }

    // Set the value of each record's 'int' field to a random value within the specified range
    unsigned int minValue = 10;
    unsigned int maxValue = 1000;
    for (unsigned int i = 0; i < length; ++i) {
        crcIndications[i].value = rand_r(&seed) % (maxValue - minValue + 1) + minValue;
    }

    // Set the CRCFLAG in each record's CRC_INDICATION_REL8_TAG to a randomly set value
    for (unsigned int i = 0; i < length; ++i) {
        crcIndications[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand_r(&seed) % 2 == 0 ? 1 : 0;
    }

    // Set the RX_UE_INFORMATION_TAG and RNTI for each record
    for (unsigned int i = 0; i < length; ++i) {
        crcIndications[i].RX_UE_INFORMATION_TAG.RNTI = rand() % INT_MAX;
        crcIndications[i].RX_UE_INFORMATION_TAG.RX_INDICATION = i;
    }

    // Set the offset for each record
    for (unsigned int i = 0; i < length; ++i) {
        offsets[i] = rand() % INT_MAX;
    }

    // Set the key for each record
    for (unsigned int i = 0; i < length; ++i) {
        keys[i] = rand() % INT_MAX;
    }

    // Cleanup
    free(offsets);
    free(keys);
    return 0;
}
