#include <pthread.h>
#include <errno.h>
#include <stdlib.h>

// Custom data structure for storing timestamp, UID, and data point
struct DATA_RECORD {
    uint64_t uid;
    double data;
    time_t timestamp;
};

void *streamProcessor(void *args) {
    struct streamProcessorArgs *arg = (struct streamProcessorArgs *)args;
    int sockfd = arg->sockfd;
    size_t bufSize = arg->bufSize;
    void (*processData)(char *, size_t);

    // Allocate memory for timestamp, UID, and data points arrays
    float *timestamps = (float *)malloc(bufSize * sizeof(float));
    uint64_t *uids = (uint64_t *)malloc(bufSize * sizeof(uint64_t));
    double *dataPoints = (double *)malloc(bufSize * sizeof(double));

    // Create and populate list of DATA_RECORD structures
    struct DATA_RECORD *records = (struct DATA_RECORD *)malloc(bufSize * sizeof(struct DATA_RECORD));
    for (int i = 0; i < bufSize; i++) {
        records[i].uid = uids[i];
        records[i].data = dataPoints[i];
        records[i].timestamp = timestamps[i];
    }

    // Set thread pool size dynamically based on system load and resources
    int threadPoolSize = 0;
    pthread_mutex_lock(&arg->poolMutex);
    if (arg->threadPoolSize < arg->maxThreads) {
        threadPoolSize++;
        arg->threadPoolSize++;
    }
    pthread_mutex_unlock(&arg->poolMutex);

    // Create and start threads to process data records
    pthread_t *threads = (pthread_t *)malloc(threadPoolSize * sizeof(pthread_t));
    for (int i = 0; i < threadPoolSize; i++) {
        pthread_create(&threads[i], NULL, processData, &records[i]);
    }

    // Join threads and free resources
    for (int i = 0; i < threadPoolSize; i++) {
        pthread_join(threads[i], NULL);
        pthread_detach(threads[i]);
        free(records[i].data);
        free(records[i].uid);
        free(records[i].timestamp);
    }
    free(records);
    free(timestamps);
    free(uids);
    free(dataPoints);
    free(threads);

    return NULL;
}

int main() {
    struct streamProcessorArgs arg;
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    arg.sockfd = sockfd;
    arg.bufSize = 1024;
    arg.threadPoolSize = 0;
    arg.maxThreads = 8;
    pthread_mutex_init(&arg.poolMutex, NULL);

    // Start thread pool for data processing
    pthread_t thread = pthread_create(NULL, NULL, streamProcessor, &arg);

    // Process data records and free resources
    struct DATA_RECORD *records;
    size_t bufSize = arg.bufSize;
    while ((records = (struct DATA_RECORD *)malloc(bufSize * sizeof(struct DATA_RECORD)))) {
        for (int i = 0; i < bufSize; i++) {
            records[i].uid = uids[i];
            records[i].data = dataPoints[i];
            records[i].timestamp = timestamps[i];
        }
        processData(records, bufSize);
    }

    return 0;
}
