// Define a function to handle file system operations
void handleFileSystemOperations(operation_t* operation, config_file* configuration) {
    // Initialize the file descriptor and directory pointer variables
    int fd = -1;
    DIR* dirp = NULL;

    // Allocate memory for the file metadata structure
    file_metadata_t* file_metadata = (file_metadata_t*) malloc(sizeof(file_metadata_t));

    // Allocate memory for the directory metadata structure
    dir_metadata_t* dir_metadata = (dir_metadata_t*) malloc(sizeof(dir_metadata_t));

    // Allocate memory for the access plan union
    access_plan_union_t* access_plan = (access_plan_union_t*) malloc(sizeof(access_plan_union_t));

    // Check if the operation is valid and correspond to a supported configuration
    if (!isOperationValid(operation->op, configuration)) {
        return;
    }

    // Open the file or directory and obtain its metadata
    switch (operation->op) {
        case "create":
            fd = open(operation->path, O_RDWR | O_CREAT, FILE_PERMS);
            break;
        case "delete":
            remove(operation->path);
            break;
        case "rename":
            rename(operation->path, operation->config);
            break;
        case "traverse":
            dirp = opendir(operation->path);
            break;
    }

    // Check if the file or directory was opened successfully
    if (fd == -1 || dirp == NULL) {
        // Handle error and return
        return;
    }

    // Fetch the metadata for the file or directory
    switch (operation->op) {
        case "create":
            file_metadata->name = operation->path;
            file_metadata->size = 0;
            file_metadata->modified = time(NULL);
            file_metadata->owner = getuid();
            file_metadata->group = getgid();
            file_metadata->permissions = FILE_PERMS;
