        case "create":
            access_plan->name = operation->path;
            access_plan->size = 0;
            access_plan->modified = time(NULL);
            access_plan->owner = getuid();
            access_plan->group = getgid();
            access_plan->permissions = FILE_PERMS;
            access_plan->fd = fd;
