    }

    // Check if the file or directory exists and is accessible
    if (!fileExists(operation->path) || !directoryExists(operation->path)) {
        return;
    }

    // Perform the desired operation on the file or directory
    switch (operation->op) {
        case "create":
            createFile(access_plan);
            break;
        case "delete":
            deleteFile(access_plan);
            break;
        case "rename":
            renameFile(access_plan);
            break;
        case "traverse":
            traverseDirectory(access_plan);
            break;
    }
}

// Define a function to check if an operation is valid and correspond to a supported configuration
bool isOperationValid(char* op, config_file* configuration) {
    // Check if the operation is supported
    if (!isSupportedOperation(op)) {
        return false;
    }

    // Check if the configuration corresponds to a supported setting
    if (!isConfigurationValid(configuration)) {
        return false;
    }

    return true;
}

// Define a function to check if an operation is valid and correspond to a supported configuration
bool isSupportedOperation(char* op) {
    // Check if the operation is valid
    if (!isValidOperation(op)) {
        return false;
    }

    // Check if the operation corresponds to a supported setting
    if (!isSupportedSetting(op)) {
        return false;
    }

    return true;
}

// Define a function to check if an operation is valid and correspond to a supported configuration
bool isValidOperation(char* op) {
    // Check if the operation is one of the following: "create", "delete", "rename", or "traverse"
    if (strcmp(op, "create") != 0 && strcmp(op, "delete") != 0 && strcmp(op, "rename") != 0 && strcmp(op, "traverse") != 0) {
        return false;
    }

    return true;
}

// Define a function to check if an operation is valid and correspond to a supported configuration
bool isSupportedSetting(char* op) {
    // Check if the operation corresponds to one of the following: "create", "delete", or "rename"
    if (strcmp(op, "create") == 0 || strcmp(op, "delete") == 0 || strcmp(op, "rename") == 0) {
        return true;
    }

    return false;
}

// Define a function to check if a file exists and is accessible
bool fileExists(char* path) {
    // Check if the file exists and is readable
    if (access(path, R_OK)) {
        return false;
    }

    return true;
}

// Define a function to check if a directory exists and is accessible
bool directoryExists(char* path) {
    // Check if the directory exists and is readable
    if (access(path, R_OK | X_OK)) {
        return false;
    }

    return true;
}

// Define a function to create a file with the given access plan
void createFile(access_plan* plan) {
    // Open the file for writing and truncating
    FILE* file = fopen(plan->name, "w");

    // Check if the file was successfully opened
    if (!file) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    // Close the file
    fclose(file);
}

// Define a function to delete a file with the given access plan
void deleteFile(access_plan* plan) {
    // Remove the file
    if (remove(plan->name)) {
        perror("remove");
        exit(EXIT_FAILURE);
    }
}

// Define a function to rename a file with the given access plan
void renameFile(access_plan* plan) {
    // Rename the file
    if (rename(plan->name, plan->config)) {
        perror("rename");
        exit(EXIT_FAILURE);
    }
}

// Define a function to traverse a directory with the given access plan
void traverseDirectory(access_plan* plan) {
    // Open the directory stream
    DIR* dir = opendir(plan->name);

    // Check if the directory was successfully opened
    if (!dir) {
        perror("opendir");
        exit(EXIT_FAILURE);
    }

    // Loop over each entry in the directory
    while (struct dirent* entry = readdir(dir)) {
        // Check if the entry is a file or directory
        if (entry->d_type == DT_REG || entry->d_type == DT_DIR) {
            // Skip over "." and ".." entries
            if (!strcmp(entry->d_name, ".") || !strcmp(entry->d_name, "..")) {
                continue;
            }

            // Create a new access plan for the file or directory
            access_plan* sub_plan = createAccessPlan(plan->name, entry->d_name);

            // Perform the desired operation on the file or directory
            switch (sub_plan->op) {
                case "create":
                    createFile(sub_plan);
                    break;
                case "delete":
                    deleteFile(sub_plan);
                    break;
                case "rename":
                    renameFile(sub_plan);
                    break;
                case "traverse":
                    traverseDirectory(sub_plan);
                    break;
            }
        }
    }

    // Close the directory stream
    closedir(dir);
}']

