    struct OffsetList* head = (struct OffsetList*)malloc(sizeof(struct OffsetList));
    head->size = size;
    head->head = NULL;
    return head;
}

// Function to add a new offset record to the linked list
void addOffsetRecord(struct OffsetList* head, int value, double timestamp) {
    struct OffsetRecord* record = (struct OffsetRecord*)malloc(sizeof(struct OffsetRecord));
    record->value = value;
    record->timestamp = timestamp;
    if (head->head == NULL) {
        head->head = record;
    } else {
        head->tail->next = record;
    }
    head->tail = record;
}

// Function to free the memory allocated for an offset list
void freeOffsetList(struct OffsetList* head) {
    struct OffsetRecord* curr = head->head;
    while (curr != NULL) {
        struct OffsetRecord* next = curr->next;
        free(curr);
        curr = next;
    }
    free(head);
}

