struct HashTable* initHashTable(int size) {
    struct HashTable* table = (struct HashTable*)malloc(sizeof(struct HashTable));
    table->size = size;
    table->bins = (struct Bin**)malloc(size * sizeof(struct Bin*));
    for (int i = 0; i < size; i++) {
        table->bins[i] = NULL;
    }
    return table;
}

// Function to free the memory allocated for a hash table
void freeHashTable(struct HashTable* table) {
    struct Bin* curr = table->head;
    while (curr != NULL) {
        struct Bin* next = curr->next;
        free(curr);
        curr = next;
    }
    free(table->bins);
    free(table);
}

// Function to add a new record to the hash table and increment its frequency count
void addRecordToHashTable(struct HashTable* table, struct OffsetRecord* record) {
    int key = record->value;
    struct Bin** binPtr = &(table->bins[key % table->size]);
    if (*binPtr == NULL) {
        *binPtr = (struct Bin*)malloc(sizeof(struct Bin));
        (*binPtr)->key = key;
        (*binPtr)->freqCount = 1;
        (*binPtr)->next = NULL;
    } else {
        struct Bin* curr = *binPtr;
        while (curr->next != NULL) {
            curr = curr->next;
        }
        curr->next = (struct Bin*)malloc(sizeof(struct Bin));
        (*binPtr)->freqCount++;
    }
}

// Function to find the largest integer value encountered in the stream and the most frequently occurring key along with its frequency count
void processAndFindMax(struct OffsetList* offsets, int* keys, struct HashTable* table) {
    // Initialize variables to keep track of the largest integer value and the most frequently occurring key
    int maxValue = -1;
    int maxFreqCount = 0;
    int mostFrequentKey = -1;
    for (int i = 0; i < offsets->size; i++) {
        struct OffsetRecord* record = offsets->head;
        while (record != NULL) {
            addRecordToHashTable(table, record);
            if (record->value > maxValue) {
                maxValue = record->value;
            }
            record = record->next;
        }
    }
    // Iterate through the hash table to find the most frequently occurring key and its frequency count
    struct Bin* curr = table->head;
    while (curr != NULL) {
        if (curr->freqCount > maxFreqCount) {
            mostFrequentKey = curr->key;
            maxFreqCount = curr->freqCount;
        }
        curr = curr->next;
    }
    // Print the results
    printf("The largest integer value encountered in the stream is %d\n", maxValue);
    printf("The most frequently occurring key is %d with a frequency count of %d\n", mostFrequentKey, maxFreqCount);
}

int main() {
    // Initialize the linked list of offset structures and the hash table
    struct OffsetList* offsets = initOffsetList(1000);
    int* keys = initKeyArray(1000);
    struct HashTable* table = initHashTable(1000);

    // Generate random integer values and timestamps for each record in the linked list of offset structures
    srand(time(NULL));
    for (int i = 0; i < offsets->size; i++) {
        addOffsetRecord(offsets, rand() % 100 + 1, time(NULL) * 1000);
    }

    // Process and find the largest integer value encountered in the stream and the most frequently occurring key along with its frequency count
    processAndFindMax(offsets, keys, table);

    // Free the memory allocated for the linked list of offset structures, the hash table, and the key array
    freeOffsetList(offsets);
    freeHashTable(table);
    freeKeyArray(keys);
    return 0;
}
