#include <stdlib.h>
#include <pthread.h>

struct record {
    long* offset;
    int* key;
    int ref_count;
};

struct data_structures {
    struct record** records;
    size_t num_records;
    pthread_mutex_t lock;
};

void init_data_structures(struct data_structures* ds, size_t num_records) {
    ds->num_records = num_records;
    ds->records = (struct record**)malloc(sizeof(struct record*) * num_records);
    for (size_t i = 0; i < num_records; ++i) {
        struct record* r = (struct record*)malloc(sizeof(struct record));
        r->offset = (long*)malloc(sizeof(long));
        r->key = (int*)malloc(sizeof(int));
        r->ref_count = 0;
        ds->records[i] = r;
    }
}

void free_data_structures(struct data_structures* ds) {
    for (size_t i = 0; i < ds->num_records; ++i) {
        struct record* r = ds->records[i];
        free(r->offset);
        free(r->key);
        free(r);
    }
    free(ds->records);
}

void acquire_lock(struct data_structures* ds) {
    pthread_mutex_lock(&ds->lock);
}

void release_lock(struct data_structures* ds) {
    pthread_mutex_unlock(&ds->lock);
}

int insert_record(struct data_structures* ds, long offset, int key) {
    acquire_lock(ds);
    struct record* r = (struct record*)malloc(sizeof(struct record));
    r->offset = (long*)malloc(sizeof(long));
    *r->offset = offset;
    r->key = (int*)malloc(sizeof(int));
    *r->key = key;
    r->ref_count = 1;
    ds->records[ds->num_records++] = r;
    release_lock(ds);
}

int delete_record(struct data_structures* ds, long offset) {
    acquire_lock(ds);
    int i;
    for (i = 0; i < ds->num_records; ++i) {
        if (*ds->records[i]->offset == offset) {
            struct record* r = ds->records[i];
            free(r->offset);
            free(r->key);
            free(r);
            ds->num_records--;
            break;
        }
    }
    release_lock(ds);
    return i == ds->num_records ? -1 : 0;
}

int update_record(struct data_structures* ds, long offset, int key) {
    acquire_lock(ds);
    struct record* r = NULL;
    for (size_t i = 0; i < ds->num_records; ++i) {
        if (*ds->records[i]->offset == offset) {
            r = ds->records[i];
            break;
        }
    }
    if (r != NULL) {
        *r->key = key;
        release_lock(ds);
        return 0;
    } else {
        release_lock(ds);
        return -1;
    }
}

int get_record(struct data_structures* ds, long offset) {
    acquire_lock(ds);
    struct record* r = NULL;
    for (size_t i = 0; i < ds->num_records; ++i) {
        if (*ds->records[i]->offset == offset) {
            r = ds->records[i];
            break;
        }
    }
    if (r != NULL) {
        *r->ref_count += 1;
        release_lock(ds);
        return 0;
    } else {
        release_lock(ds);
        return -1;
    }
}

int free_record(struct data_structures* ds, long offset) {
    acquire_lock(ds);
    struct record* r = NULL;
    for (size_t i = 0; i < ds->num_records; ++i) {
        if (*ds->records[i]->offset == offset) {
            r = ds->records[i];
            break;
        }
    }
    if (r != NULL && r->ref_count > 0) {
        *r->ref_count -= 1;
        release_lock(ds);
        return 0;
    } else {
        release_lock(ds);
        return -1;
    }
}
```
