['```c
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// A node in the doubly linked list
typedef struct Node {
    int value;
    int ref_count;
    struct Node *prev, *next;
} Node;

// The head and tail of the linked list
static Node *head = NULL, *tail = NULL;

// Function to create a new node with the given value
Node* create_node(int val) {
    // Allocate memory for the node
    Node *new_node = (Node*) malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Error: Failed to allocate memory for new node\n");
        return NULL;
    }

    // Initialize the node fields
    new_node->value = val;
    new_node->ref_count = 1;
    new_node->prev = NULL;
    new_node->next = NULL;

    return new_node;
}

// Function to insert a node at the head of the list
void insert_head(Node *new_node) {
    // Update the reference count for the new node
    new_node->ref_count++;

    // If the list is empty, set the new node as both the head and tail
    if (!head && !tail) {
        head = new_node;
        tail = new_node;
    } else {
        // Otherwise, insert the new node before the current head
        new_node->next = head;
        head->prev = new_node;
        head = new_node;
    }
}

// Function to insert a node at the tail of the list
void insert_tail(Node *new_node) {
    // Update the reference count for the new node
    new_node->ref_count++;

    // If the list is empty, set the new node as both the head and tail
    if (!head && !tail) {
        head = new_node;
        tail = new_node;
    } else {
        // Otherwise, insert the new node after the current tail
        new_node->prev = tail;
        tail->next = new_node;
        tail = new_node;
    }
}

// Function to delete a node from the list
void delete(Node *del_node) {
    // Update the reference count for the deleted node
    del_node->ref_count--;

    // If the node is the head, update the new head and tail accordingly
    if (del_node == head) {
        if (head == tail) {
            // If there's only one node in the list, reset the head and tail
            head = NULL;
            tail = NULL;
        } else {
            // Otherwise, update the new head and tail
            head = del_node->next;
            head->prev = NULL;
        }
    }

    // If the node is the tail, update the new tail accordingly
    if (del_node == tail) {
        tail = del_node->prev;
        tail->next = NULL;
    }

    // If the node has no more references, free it
    if (del_node->ref_count == 0) {
        free(del_node);
    }
}

// Function to traverse the list and print node values
void traverse(void (*print_fn)(int)) {
    Node *curr = head;
    while (curr != NULL) {
        // Call the print function with the current node's value
        print_fn(curr->value);

        // Move to the next node
        curr = curr->next;
    }
}

// Function to safely free all nodes, decrementing reference counts as needed
void safe_free() {
    Node *curr = head;
    while (curr != NULL) {
        // If the node has no more references, free it and update the list accordingly
        if (curr->ref_count == 0) {
            free(curr);
            curr = curr->next;
        } else {
            break;
        }
    }
}
```
This implementation uses a doubly linked list to store `Node` structures, where each node contains a pointer to another node, an integer value, and a reference count for shared ownership. The reference counts are used to track the number of nodes that refer to each other in the list, allowing efficient insertion and deletion of nodes at both the head and tail without excessive overhead.

The `create_node` function creates a new node with the given value and returns a pointer to it. It also updates the reference count for the new node, which is initially set to 1.

The `insert_head` and `insert_tail` functions insert a new node at the head or tail of the list, respectively. They update the reference counts for the new node and the existing nodes in the list, ensuring that the list remains consistent.

The `delete` function deletes a node from the list by updating the reference count for the deleted node, and freeing it if necessary. If the deleted node was the head or tail of the list, it updates the new head and tail accordingly.

The `traverse` function traverses the list and calls the provided print function with each node's value, allowing the user to print the values stored in the nodes.

Finally, the `safe_free` function safely frees all nodes in the list by decrementing their reference counts and freeing them if necessary. It stops when it reaches a node with no more references, indicating that all nodes have been freed.']

["Here is an example implementation of the modular C library that provides functionality to manage a collection of records, each containing a unique integer key and a corresponding long offset value:
```
// Define a struct for storing records in the library
typedef struct Record {
  int key;
  long offset;
} Record;

// Define a linked list-based structure to maintain the records
typedef struct RecordListNode {
  Record *record;
  struct RecordListNode *next;
} RecordListNode;

// Define a function to add a new record to the collection
int record_add(Record *record) {
  // Create a new node for the record and insert it into the list
  RecordListNode *node = malloc(sizeof(RecordListNode));
  node->record = record;
  node->next = NULL;

  if (head == NULL) {
    head = node;
    return 0;
  } else {
    RecordListNode *curr = head;
    while (curr->next != NULL) {
      curr = curr->next;
    }
    curr->next = node;
    return 1;
  }
}

// Define a function to update an existing record in the collection
int record_update(int key, long offset) {
  // Search for the record with the given key and update its value if found
  RecordListNode *curr = head;
  while (curr != NULL) {
    if (curr->record->key == key) {
      curr->record->offset = offset;
      return 0;
    }
    curr = curr->next;
  }

  // If the record is not found, add a new one with the given key and value
  Record *new_record = malloc(sizeof(Record));
  new_record->key = key;
  new_record->offset = offset;
  return record_add(new_record);
}

// Define a function to retrieve a record from the collection by its key
Record *record_get(int key) {
  // Search for the record with the given key and return it if found
  RecordListNode *curr = head;
  while (curr != NULL) {
    if (curr->record->key == key) {
      return curr->record;
    }
    curr = curr->next;
  }
  return NULL;
}

// Define a function to remove a record from the collection by its key
int record_remove(int key) {
  // Search for the record with the given key and remove it if found
  RecordListNode *curr = head;
  while (curr != NULL) {
    if (curr->record->key == key) {
      RecordListNode *prev = curr;
      curr = curr->next;
      free(prev);
      return 0;
    }
    curr = curr->next;
  }
  return 1;
}
