    return current;
}

// Deletes a person object from the hash table.
void delete_person(HashTable* table, int id) {
    int index = id % table->size;
    Person* current = table->people[index];
    while (current != NULL && current->id != id) {
        current = current->next;
    }
    if (current != NULL) {
        dec_node_ref(current);
        if (current == table->people[index]) {
            table->people[index] = current->next;
        } else {
            current->prev->next = current->next;
        }
    }
}

// Inserts an activity record into the linked list.
void insert_activity(Node* node, Activity* activity) {
    // Insert the activity record at the head of the list.
    activity->next = node;
    activity->prev = NULL;
    if (node != NULL) {
        node->prev = activity;
    }
}

// Retrieves an activity record from the linked list.
Activity* get_activity(Node* node, long timestamp) {
    Activity* current = node;
    while (current != NULL && current->timestamp < timestamp) {
        current = current->next;
    }
    return current;
}

// Deletes an activity record from the linked list.
void delete_activity(Node* node, Activity* activity) {
    if (node == activity) {
        node = node->next;
    } else {
        activity->prev->next = activity->next;
    }
}

// Traverses the linked list and prints the values of each node.
void traverse_list(Node* node) {
    while (node != NULL) {
        printf("%d ", node->value);
        node = node->next;
    }
}

// Safely frees all nodes in the linked list, decrementing the reference count for each node.
void free_list(Node* node) {
    while (node != NULL) {
        dec_node_ref(node);
        Node* next = node->next;
        free(node);
        node = next;
    }
}

int main() {
    // Create a hash table with 10 slots.
    HashTable* table = create_hash_table(10);

    // Insert a person object into the hash table.
    Person* person = create_person(1, "John", 30);
    insert_person(table, person);

    // Retrieve the person object from the hash table.
