    printf("Retrieved person: %d %s %d\n", retrieved_person->id, retrieved_person->name, retrieved_person->age);

    // Insert an activity record into the linked list.
    Activity* activity = create_activity(100, "running");
    insert_activity(retrieved_person, activity);

