    // Delete an activity record from the linked list.
    delete_activity(retrieved_person->next, retrieved_activity);

    // Traverse the linked list and print the values of each node.
    traverse_list(table->people[0]);

    // Safely frees all nodes in the linked list, decrementing the reference count for each node.
    free_list(table->people[0]);

    return 0;
}
