struct record {
    long offset;
    int key;
    char* metadata;
    void* data_ptr;
    size_t data_size;
};

struct index {
    struct record* records;
    size_t num_records;
    pthread_mutex_t mutex;
};

int allocate_index(size_t num_records) {
    // Allocate memory for the index and initialize its metadata
    struct index* idx = malloc(sizeof(struct index));
    if (!idx) {
        LOG("Failed to allocate memory for index\n");
        return -1;
    }
    idx->records = calloc(num_records, sizeof(struct record));
    if (!idx->records) {
        free(idx);
        LOG("Failed to allocate memory for records\n");
        return -1;
    }
    idx->num_records = num_records;
    pthread_mutex_init(&idx->mutex, NULL);
    return 0;
}

void deallocate_index(struct index* idx) {
    // Free memory allocated for the index
    if (idx->records) {
        free(idx->records);
    }
    pthread_mutex_destroy(&idx->mutex);
    free(idx);
}

int add_record(struct index* idx, long offset, int key, char* metadata, void* data_ptr, size_t data_size) {
    // Acquire mutex to prevent concurrent access
    pthread_mutex_lock(&idx->mutex);
    // Check if there is space for the new record
    if (idx->num_records >= idx->records_size) {
        size_t new_size = idx->records_size * 2;
        struct record* new_records = realloc(idx->records, new_size);
        if (!new_records) {
            pthread_mutex_unlock(&idx->mutex);
            LOG("Failed to allocate more memory for records\n");
            return -1;
        }
        idx->records = new_records;
        idx->records_size = new_size;
    }
    // Initialize the new record with the given data
    idx->records[idx->num_records].offset = offset;
    idx->records[idx->num_records].key = key;
    idx->records[idx->num_records].metadata = metadata;
    idx->records[idx->num_records].data_ptr = data_ptr;
    idx->records[idx->num_records].data_size = data_size;
    // Increment the number of records and release mutex
    idx->num_records++;
    pthread_mutex_unlock(&idx->mutex);
    return 0;
}

int get_record(struct index* idx, long offset, int key, char** metadata, void** data_ptr, size_t* data_size) {
    // Acquire mutex to prevent concurrent access
    pthread_mutex_lock(&idx->mutex);
    // Find the record with the given offset and key
    struct record* rec = NULL;
    for (int i = 0; i < idx->num_records; i++) {
        if (idx->records[i].offset == offset && idx->records[i].key == key) {
            rec = &idx->records[i];
            break;
        }
    }
    // If the record was not found, return an error
    if (!rec) {
        pthread_mutex_unlock(&idx->mutex);
        LOG("Record with offset %ld and key %d not found\n", offset, key);
        return -1;
    }
    // Copy the metadata and data pointers to the output parameters
    *metadata = rec->metadata;
    *data_ptr = rec->data_ptr;
    *data_size = rec->data_size;
    // Release mutex
    pthread_mutex_unlock(&idx->mutex);
    return 0;
}
