    FileMetadata* metadata;
    pthread_mutex_t mutex; // for synchronization
} FileHandle;

// Function to initialize file handles pool
void initFileHandlesPool(int numFiles, int numThreads) {
    // Allocate memory for the file handles pool
    FileHandle* handles = (FileHandle*)malloc(numFiles * sizeof(FileHandle));
    if (!handles) {
        perror("Failed to allocate memory for file handles pool");
        exit(1);
    }

    // Initialize each handle with a random access status, last modified time, and error code
