        FileHandle* handle = &handles[i];
        handle->metadata = (FileMetadata*)malloc(sizeof(FileMetadata));
        if (!handle->metadata) {
            perror("Failed to allocate memory for file metadata");
            exit(1);
        }
        handle->metadata->version = rand() % 10;
        handle->metadata->lastModified = time(NULL);
        handle->metadata->errorCode = 0;
    }

    // Initialize the mutex for each handle
    for (int i = 0; i < numFiles; i++) {
        FileHandle* handle = &handles[i];
        pthread_mutex_init(&handle->mutex, NULL);
    }

    // Set the handles pool size and return it
    FILE_HANDLES_POOL_SIZE = numFiles;
    return handles;
}

// Function to allocate a file handle for a given file path
FileHandle* allocateFileHandle(char* filePath) {
    // Find an available handle in the pool
    int i;
    for (i = 0; i < FILE_HANDLES_POOL_SIZE; i++) {
        FileHandle* handle = &FILE_HANDLES_POOL[i];
        if (!pthread_mutex_lock(&handle->mutex)) {
            break;
        }
    }

    // If no available handles were found, allocate a new one
    if (i == FILE_HANDLES_POOL_SIZE) {
        FileHandle* handle = (FileHandle*)malloc(sizeof(FileHandle));
        handle->metadata = (FileMetadata*)malloc(sizeof(FileMetadata));
        if (!handle || !handle->metadata) {
            perror("Failed to allocate memory for file handle");
            exit(1);
        }
        pthread_mutex_init(&handle->mutex, NULL);
    }

    // Initialize the handle with the given file path and return it
    FileHandle* newHandle = &FILE_HANDLES_POOL[i];
    strcpy(newHandle->metadata->filePath, filePath);
    newHandle->metadata->version = 0;
    newHandle->metadata->lastModified = time(NULL);
    newHandle->metadata->errorCode = 0;
    return newHandle;
}

// Function to free a file handle and its associated memory
void freeFileHandle(FileHandle* handle) {
    // Free the handle's metadata and mutex
    if (handle->metadata) {
        free(handle->metadata);
    }
    pthread_mutex_destroy(&handle->mutex);

    // Free the handle itself
    free(handle);
}

// Function to read a file with a given file handle
void readFile(FileHandle* handle) {
    // Lock the mutex for the given handle
    if (pthread_mutex_lock(&handle->mutex)) {
        perror("Failed to lock mutex");
        return;
    }

    // Read the file content from disk
    char* content = readFileContent(handle->metadata->filePath);
    if (!content) {
        handle->metadata->errorCode = 1;
        pthread_mutex_unlock(&handle->mutex);
        return;
    }

    // Update the file metadata with the new content and version number
    handle->metadata->content = content;
    handle->metadata->version++;
    handle->metadata->lastModified = time(NULL);

    // Unlock the mutex for the given handle
    pthread_mutex_unlock(&handle->mutex);
}

// Function to write a file with a given file handle
void writeFile(FileHandle* handle) {
    // Lock the mutex for the given handle
    if (pthread_mutex_lock(&handle->mutex)) {
        perror("Failed to lock mutex");
        return;
    }

    // Write the file content to disk
    int status = writeFileContent(handle->metadata->filePath, handle->metadata->content);
    if (status == -1) {
        handle->metadata->errorCode = 2;
        pthread_mutex_unlock(&handle->mutex);
        return;
    }

    // Update the file metadata with the new version number and last modified time
    handle->metadata->version++;
    handle->metadata->lastModified = time(NULL);

    // Unlock the mutex for the given handle
    pthread_mutex_unlock(&handle->mutex);
}

// Function to append data to a file with a given file handle
void appendToFile(FileHandle* handle, char* content) {
    // Lock the mutex for the given handle
    if (pthread_mutex_lock(&handle->mutex)) {
        perror("Failed to lock mutex");
        return;
    }

    // Append the data to the file content
    char* newContent = (char*)realloc(handle->metadata->content, strlen(content) + strlen(handle->metadata->content));
    if (!newContent) {
        handle->metadata->errorCode = 3;
        pthread_mutex_unlock(&handle->mutex);
        return;
    }
    handle->metadata->content = newContent;
    strcat(handle->metadata->content, content);

    // Update the file metadata with the new version number and last modified time
    handle->metadata->version++;
    handle->metadata->lastModified = time(NULL);

    // Unlock the mutex for the given handle
    pthread_mutex_unlock(&handle->mutex);
}

// Function to delete a file with a given file path
void deleteFile(char* filePath) {
    // Lock the mutex for the given file path
    if (pthread_mutex_lock(&FILE_PATH_MUTEXES[filePath])) {
        perror("Failed to lock mutex");
        return;
    }

    // Delete the file from disk
    int status = remove(filePath);
    if (status == -1) {
        FILE_HANDLES[filePath].errorCode = 4;
        pthread_mutex_unlock(&FILE_PATH_MUTEXES[filePath]);
        return;
    }

    // Delete the file handle and its associated memory
    freeFileHandle(&FILE_HANDLES[filePath]);

    // Unlock the mutex for the given file path
    pthread_mutex_unlock(&FILE_PATH_MUTEXES[filePath]);
}

// Function to check if a file exists with a given file path
bool fileExists(char* filePath) {
    // Lock the mutex for the given file path
    if (pthread_mutex_lock(&FILE_PATH_MUTEXES[filePath])) {
        perror("Failed to lock mutex");
        return false;
    }

    // Check if the file exists on disk
    int status = access(filePath, F_OK);
    if (status == -1) {
        FILE_HANDLES[filePath].errorCode = 5;
        pthread_mutex_unlock(&FILE_PATH_MUTEXES[filePath]);
        return false;
    }

    // Unlock the mutex for the given file path
    pthread_mutex_unlock(&FILE_PATH_MUTEXES[filePath]);
    return true;
}
```

This is a very simple example of how you could use threads to perform I/O operations on files in parallel. This code uses a pool of worker threads to handle the I/O requests, and it keeps track of which file paths are currently being processed by each thread using a mutex for each file path. This ensures that only one thread can access a given file at any given time, which helps prevent race conditions and other types of data corruption that could occur if multiple threads were trying to access the same file simultaneously.

This is just a basic example of how you might use threads for I/O operations on files in parallel. Depending on your specific requirements, you may need to add additional synchronization or error handling mechanisms to ensure that your code works correctly in all scenarios.']

