// Define a struct to store log entry information
struct logEntry {
    char status;   // Status indicator (e.g., 'I', 'W', or 'E')
    time_t timestamp;  // Timestamp of the entry
    double metricValue; // Metric value associated with the entry
};

// Define a function to process and generate report from input strings
void processAndGenerateReport(char** inputStrings, int numInputStrings) {
    // Allocate memory for the log entries
    struct logEntry* logEntries = (struct logEntry*)malloc(numInputStrings * sizeof(struct logEntry));
    if (!logEntries) {
        perror("Error allocating memory for log entries");
        return;
    }

    // Allocate memory for the char content arrays
    char** contentArrays = (char**)malloc(numInputStrings * sizeof(char*));
    if (!contentArrays) {
        perror("Error allocating memory for content arrays");
        free(logEntries);
        return;
    }

    // Allocate memory for the int line numbers
    int* lineNumbers = (int*)malloc(numInputStrings * sizeof(int));
    if (!lineNumbers) {
        perror("Error allocating memory for line numbers");
        free(logEntries);
        free(contentArrays);
        return;
    }

    // Initialize the log entries and content arrays
    for (int i = 0; i < numInputStrings; ++i) {
        logEntries[i].status = '\0';
        logEntries[i].timestamp = 0;
        logEntries[i].metricValue = 0.0;
        contentArrays[i] = (char*)malloc(strlen(inputStrings[i]) + 1);
        if (!contentArrays[i]) {
            perror("Error allocating memory for content array");
            free(logEntries);
            free(contentArrays);
            free(lineNumbers);
            return;
        }
        strcpy(contentArrays[i], inputStrings[i]);
        lineNumbers[i] = 0;
    }

    // Process the log entries and generate the report
    for (int i = 0; i < numInputStrings; ++i) {
        char* content = contentArrays[i];
        int lineNumber = lineNumbers[i];
        struct logEntry* entry = &logEntries[i];
        // Process the log entry and update the status, timestamp, and metric value
        if (strncmp(content, "INFO", 4) == 0) {
            entry->status = 'I';
            entry->timestamp = time(NULL);
            entry->metricValue = 1.0;
        } else if (strncmp(content, "WARN", 4) == 0) {
            entry->status = 'W';
            entry->timestamp = time(NULL);
            entry->metricValue = 2.0;
        } else if (strncmp(content, "ERROR", 5) == 0) {
            entry->status = 'E';
            entry->timestamp = time(NULL);
            entry->metricValue = 3.0;
        }
    }

    // Generate the report based on the processed log entries
    printf("Report:\n");
    for (int i = 0; i < numInputStrings; ++i) {
        struct logEntry* entry = &logEntries[i];
        if (entry->status != '\0') {
            printf("%d: %s\n", lineNumbers[i], contentArrays[i]);
        }
    }

    // Deallocate memory for the log entries, content arrays, and line numbers
    free(logEntries);
    free(contentArrays);
    free(lineNumbers);
}
