    for (int i = 0; i < PACKET_SIZES; i++) {
        mem->packet_sizes[i] = rand() % PACKET_SIZES;
    }

    return mem;
}

void deallocate_memory(memory_management* mem) {
    // Deallocate the memory allocated for the network records and event codes
    free(mem);
}
