// Function to initialize the memory for the dynamic components
void init_memory() {
    // Allocate memory for the records linked list
    records = (struct record *)malloc(sizeof(struct record) * 10);
    if (!records) {
        printf("Error: Failed to allocate memory for records\n");
        return;
    }

    // Initialize the records in the linked list
    for (int i = 0; i < 10; i++) {
        records[i].value = rand() % 100;
        records[i].timestamp = time(NULL);
    }

    // Allocate memory for the keys array
    keys = (int *)malloc(sizeof(int) * 10);
    if (!keys) {
        printf("Error: Failed to allocate memory for keys\n");
        return;
    }

    // Initialize the keys in the array
    for (int i = 0; i < 10; i++) {
        keys[i] = rand() % 100;
    }

    // Allocate memory for the counters linked list
    counters = (struct counter **)malloc(sizeof(struct counter *) * 10);
    if (!counters) {
        printf("Error: Failed to allocate memory for counters\n");
        return;
    }

    // Initialize the counters in the linked list
    for (int i = 0; i < 10; i++) {
        counters[i] = (struct counter *)malloc(sizeof(struct counter));
        if (!counters[i]) {
            printf("Error: Failed to allocate memory for counters\n");
            return;
        }
    }
}

// Function to process and analyze the data stream
int processAndAnalyzeDataStream() {
    // Initialize the memory for the dynamic components
    init_memory();

    // Declare variables for tracking the largest integer and the most frequently occurring key
    int largest_integer = INT_MIN;
    int most_frequent_key = -1;
    int count = 0;

    // Loop through each record in the linked list
    struct record *current_record = records;
    while (current_record) {
        // Increment the frequency counter for the current key
        counters[current_record->value]->count++;

        // Update the largest integer if necessary
        if (largest_integer < current_record->value) {
            largest_integer = current_record->value;
        }

        // Update the most frequently occurring key if necessary
        if (counters[current_record->value]->count > count) {
            most_frequent_key = current_record->value;
            count = counters[current_record->value]->count;
        }

        // Move to the next record in the linked list
        current_record = current_record->next;
    }

    // Print the results
    printf("Largest integer: %d\n", largest_integer);
    printf("Most frequently occurring key: %d (%d times)\n", most_frequent_key, count);

    // Clean up the memory for the dynamic components
    free(records);
    records = NULL;

    for (int i = 0; i < 10; i++) {
        free(counters[i]);
        counters[i] = NULL;
    }
    free(counters);
    counters = NULL;

    return 0;
}
