// Define an array of dbConnection structures for the connection pool
struct dbConnection *connections = NULL;

// Define a semaphore to manage concurrent access to the connection pool
sem_t *connectionSemaphore = NULL;

// Define a mutex to protect shared data structures during configuration updates
