// Function to allocate memory for the connection pool
void allocateConnections(int numConnections) {
  // Allocate an array of struct dbConnection
  connections = (struct dbConnection *)malloc(numConnections * sizeof(struct dbConnection));
  if (!connections) {
    printf("Error: Failed to allocate memory for connection pool\n");
    exit(1);
  }

  // Initialize each connection's status to a random connection state within the specified range
  srand(time(NULL));
  for (int i = 0; i < numConnections; i++) {
    connections[i].status = rand() % 2;
    connections[i].lastAccessTime = 0;
    connections[i].errorCode = 0;
  }

  // Create a semaphore to manage concurrent access to the connection pool
  if (sem_init(&connectionSemaphore, 1, numConnections) == -1) {
    printf("Error: Failed to initialize connection semaphore\n");
    exit(1);
  }
}

// Function to free memory for the connection pool
void deallocateConnections() {
  // Free the array of struct dbConnection
  if (connections) {
    free(connections);
  }

  // Destroy the semaphore
  if (connectionSemaphore) {
    sem_destroy(&connectionSemaphore);
  }
}

