  connections[connectionIndex].referenceCount++;

  // Perform any necessary error handling if the connection is in an error state
  if (connections[connectionIndex].status == DB_CONNECTION_ERROR) {
    return -1;
  }

  // Update the connection's last access time and status
  connections[connectionIndex].lastAccessTime = time(NULL);
  connections[connectionIndex].status = DB_CONNECTION_BUSY;

  // Execute the query using the connection
  int result = executeQueryOnConnection(queryString, transactionID, &connections[connectionIndex]);

  // Check if an error occurred during execution
  if (result == -1) {
    return -1;
  }

  // Update the connection's status and error code
  connections[connectionIndex].status = DB_CONNECTION_IDLE;
  connections[connectionIndex].errorCode = result;

  // Decrement the connection's reference count and release it back to the pool
  connections[connectionIndex].referenceCount--;
  sem_post(&connectionSemaphore);

  return result;
}

