DBConnection* initializeDatabaseConnection(const DBConnectionParams& params, int maxRetries = 5, int retryDelayMS = 1000) {
    std::cout << "Establishing connection to database..." << std::endl;

    // Initialize the connection object and set default values
    DBConnection* connection = new DBConnection();
    connection->handle = nullptr;
    connection->connected = false;
    connection->retryCount = 0;
    connection->maxRetries = maxRetries;
    connection->retryDelay = std::chrono::milliseconds(retryDelayMS);

    // Check if the connection parameters are valid
    if (params.host == "" || params.port <= 0 || params.username == "" || params.password == "") {
        delete connection;
        return nullptr;
    }

    // Try connecting to the database using exponential backoff
    while (connection->retryCount < connection->maxRetries) {
        try {
            // Establish a new connection to the database
            connection->handle = connectToDatabase(params.host, params.port, params.username, params.password, params.database_name);
            if (connection->handle != nullptr) {
                connection->connected = true;
                std::cout << "Connection established successfully!" << std::endl;
                break;
            }
        } catch (const std::exception& e) {
            // Log the error and retry
            std::cerr << "Failed to establish connection: " << e.what() << std::endl;
            ++connection->retryCount;
            if (connection->retryCount < connection->maxRetries) {
                std::this_thread::sleep_for(connection->retryDelay);
            }
        }
    }

    // Return the connection object or nullptr if all retries failed
    return (connection->connected ? connection : nullptr);
}

