array_container* manage_arrays(size_t num_entries, unsigned seed, int min_val, int max_val) {
    // Allocate memory for the three arrays
    long* offsets = (long*)malloc(num_entries * sizeof(long));
    int* keys = (int*)malloc(num_entries * sizeof(int));
    record** records = (record**)malloc(num_entries * sizeof(record*));

    // Check for memory allocation failures
    if (offsets == NULL || keys == NULL || records == NULL) {
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    // Initialize the random number generator with the given seed
    srand(seed);

    // Initialize the offsets array
    for (size_t i = 0; i < num_entries; i++) {
        offsets[i] = i;
    }

    // Initialize the keys array by applying bitwise AND with 0xFFFF to each offset
    for (size_t i = 0; i < num_entries; i++) {
        keys[i] = offsets[i] & 0xFFFF;
    }

    // Allocate memory for the records array
    record* tmp = (record*)malloc(num_entries * sizeof(record));

    // Check for memory allocation failures
    if (tmp == NULL) {
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    // Initialize the records array by allocating a string for each key and filling in the random values
    for (size_t i = 0; i < num_entries; i++) {
        record* rec = &tmp[i];
        char* key_id = (char*)malloc(strlen(rec->key_id) + 1);
        if (key_id == NULL) {
            free(offsets);
            free(keys);
            free(records);
            return NULL;
        }
        strcpy(key_id, rec->key_id);
        rec->key_id = key_id;
        int* random_values = (int*)malloc(10 * sizeof(int));
        if (random_values == NULL) {
            free(offsets);
            free(keys);
            free(records);
            return NULL;
        }
        for (size_t j = 0; j < 10; j++) {
            random_values[j] = rand() % (max_val - min_val + 1) + min_val;
        }
        rec->random_values = random_values;
    }

    // Initialize the array container structure with pointers to the three arrays and metadata
    array_container* container = (array_container*)malloc(sizeof(array_container));
    if (container == NULL) {
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }
    container->offsets = offsets;
    container->keys = keys;
    container->records = records;
    container->num_entries = num_entries;

    // Return a pointer to the array container structure
    return container;
}
