// Function to allocate memory for an array of records with dynamic memory allocation
struct record* allocate_records(int num_records, const char* filepath) {
    struct record* records = NULL;
    int i;

    // Allocate memory for the array of records
    records = (struct record*) malloc(num_records * sizeof(struct record));
    if (records == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for records\n");
        return NULL;
    }

    // Initialize the array of records
    for (i = 0; i < num_records; i++) {
        records[i].offset = generate_seed();
        records[i].hash = hash(records[i].offset);
        records[i].data = (char*) malloc(1024 * sizeof(char));
        if (records[i].data == NULL) {
            fprintf(stderr, "Error: Failed to allocate memory for record data\n");
            return NULL;
