    pthread_mutex_lock(&cache->mutex);
    for (struct node *node = cache->head; node != NULL; node = node->next) {
        if (node->record->key == key) {
            record = node->record;
            break;
        }
    }
    pthread_mutex_unlock(&cache->mutex);
    return record;
}

