} record_t;

// Function to initialize a dynamic array of records with random integers and ASCII characters
record_t** init_records(int seed, int offset_limit, size_t count) {
    // Check for valid input parameters
    if (seed < 0 || offset_limit <= 0 || count == 0) {
        return NULL;
    }

    // Initialize the random number generator
    srand(seed);

    // Allocate memory for the array of records and initialize each record
    record_t** records = (record_t**)calloc(count, sizeof(record_t*));
    if (!records) {
        return NULL;
    }
    for (size_t i = 0; i < count; i++) {
        records[i] = (record_t*)malloc(sizeof(record_t));
        if (!records[i]) {
            free(records);
            return NULL;
        }
        records[i]->integer_value = rand() % offset_limit + 1;
        memset(records[i]->char_buffer, 0, sizeof(records[i]->char_buffer));
        size_t dynamic_size = (rand() % 50) + 1;
        records[i]->dynamic_buffer = (char*)malloc(dynamic_size);
        if (!records[i]->dynamic_buffer) {
            free(records[i]);
            free(records);
            return NULL;
        }
        for (size_t j = 0; j < dynamic_size; j++) {
            records[i]->dynamic_buffer[j] = rand() % 256;
        }
        records[i]->timestamp = time(NULL);
        records[i]->refcount = 1;
    }

