  // Acquire lock for thread safety
  pthread_mutex_lock(&dataset->lock);

  // Check if there is enough space in the dataset for a new record
  if (dataset->num_records >= dataset->offset_range + 1) {
    pthread_mutex_unlock(&dataset->lock);
    return -1;
  }

  // Add a new record to the dataset and update its values
  Record *record = &dataset->records[dataset->num_records++];
  record->value = value;
