struct node {
    float score;
    struct node* next;
};

// Define the configuration structure for the function
struct config {
    // Size of the arrays
    size_t offset_size, key_size, record_size, weight_size;

    // Range for random numbers used in records
    int record_range_start, record_range_end;

    // Size of the labels array and each label
    size_t labels_size;
    char* labels[];
};

// Define the function to initialize the data structures
int initialize_data_structures(struct config* config) {
    // Check if the configuration is valid
    if (config == NULL || config->offset_size <= 0 || config->key_size <= 0 ||
        config->record_size <= 0 || config->weight_size <= 0 ||
        config->record_range_start > config->record_range_end) {
        fprintf(stderr, "Invalid configuration\n");
        return -1;
    }

    // Dynamically allocate memory for the arrays and initialize them
    struct node** nodes = (struct node**)malloc(config->offset_size * sizeof(struct node*));
    int* offsets = (int*)malloc(config->offset_size * sizeof(int));
    int* keys = (int*)malloc(config->key_size * sizeof(int));
    struct record* records = (struct record*)malloc(config->record_size * sizeof(struct record));
    float* weights = (float*)malloc(config->weight_size * sizeof(float));
    for (size_t i = 0; i < config->offset_size; i++) {
        offsets[i] = rand() % (config->record_range_end - config->record_range_start + 1) + config->record_range_start;
        keys[i] = rand() % config->labels_size;
        records[i].value = rand() % config->record_range_end;
        records[i].timestamp = (double)time(NULL) * 1000.0; // milliseconds since the epoch
        weights[i] = ((float)rand() / RAND_MAX) * (config->weight_max - config->weight_min) + config->weight_min;
    }

    // Initialize each node with a random integer within the specified range and a pointer to another node
    for (size_t i = 0; i < config->offset_size; i++) {
        nodes[i] = (struct node*)malloc(sizeof(struct node));
        nodes[i]->score = weights[i];
        nodes[i]->next = NULL;
    }

    // Free the memory allocated for the arrays and return a pointer to the dynamically allocated array of node pointers
    free(offsets);
    free(keys);
    free(records);
    free(weights);
    return (int*)nodes;
}
