        free(offsets);
        free(keys);
        return NULL;
    }

    // Initialize the record structures with random values within the specified range
    init_records(records, num_records);

    // Create an EVP_CIPHER structure to represent the selected cipher
    EVP_CIPHER* cipher = EVP_CIPHER_new();
    if (!cipher) {
        fprintf(stderr, "Failed to create EVP_CIPHER structure\n");
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    // Set the cipher mode and number of iterations for encryption/decryption
    EVP_CIPHER_set_cipher_mode(cipher, mode);
    EVP_CIPHER_set_num_iterations(cipher, num_iterations);

    return cipher;
}

// Define a function to manage the memory deallocation and validation of the data after encryption/decryption
void free_memory(EVP_CIPHER* cipher) {
    // Free the EVP_CIPHER structure
    EVP_CIPHER_free(cipher);

    // Get the offsets, keys, and records arrays from the EVP_CIPHER structure
    long* offsets = EVP_CIPHER_get_offsets(cipher);
