} record;

typedef struct {
    long offset;
    int key;
    double timestamp;
} offset_t;

// Function to generate random integers within a specified range
int get_random_int(int min, int max) {
    return min + (rand() % (max - min));
}

// Function to convert milliseconds since epoch to human-readable time
char* format_timestamp(double timestamp) {
    struct tm *tm = gmtime(&timestamp);
    char buffer[20];
    strftime(buffer, 19, "%Y-%m-%d %H:%M:%S", tm);
    return strdup(buffer);
}

// Function to process records in parallel using multiple threads
void *process_records(void *args) {
    // Declare variables for thread-safe data structures
    offset_t **offsets = args;
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Loop over records and perform operations
    for (int i = 0; i < offsets->size; i++) {
        offset_t *offset = &offsets[i];
        int key = get_random_int(min, max);
        double timestamp = (double)time(NULL);

        // Lock mutex to update shared data structures
        pthread_mutex_lock(&mutex);
        offset->key = key;
        offset->timestamp = timestamp;
        pthread_mutex_unlock(&mutex);
    }

    return NULL;
}

// Function to find maximum value in an array of offsets
int find_max(offset_t *offsets, int size) {
    // Initialize variables for maximum value and timestamp
    int max = INT_MIN;
    double max_timestamp = -1.0;

    // Loop over offsets and update maximum value and timestamp if necessary
    for (int i = 0; i < size; i++) {
        offset_t *offset = &offsets[i];
        int key = offset->key;
        double timestamp = offset->timestamp;

        // Check if current key is greater than maximum value
        if (key > max) {
            max = key;
            max_timestamp = timestamp;
        }
    }

    return max;
}

