        while ((offsets[i] = malloc(sizeof(offset_t))) && (keys[i] = get_random_int(min, max)) && (timestamps[i] = (double)time(NULL))) {
            // Create records with key and timestamp values
            record *record = &records[i];
            record->value = keys[i];
            record->timestamp = timestamps[i];
        }
    } else if (input_source == "file") {
        // Read offsets, keys, and timestamps from file specified by command-line arguments
        FILE *file = fopen(input_file, "r");
        while ((offsets[i] = malloc(sizeof(offset_t))) && (keys[i] = get_random_int(min, max)) && (timestamps[i] = (double)time(NULL))) {
