void processAndFindMax(int min, int max) {
    // Allocate memory for arrays
    long *offset_values = (long *)malloc(sizeof(long) * 100);
    int *keys = (int *)malloc(sizeof(int) * 100);
    Record *records = (Record *)malloc(sizeof(Record) * 100);

    // Initialize rolling average and window of last 100 records
    double rolling_average = 0;
    int window[100];

    // Read integers from standard input
    while (true) {
        // Read integer value
        int key = 0;
        scanf("%d", &key);

        // Check if integer is within specified range
        if (key < min || key > max) {
            continue;
        }

        // Initialize record structure with current time in milliseconds since epoch
        Record record = {key, ((double)time(NULL)) * 1000};

        // Add record to the end of the window
        int last_index = (window[99] - window[0]) % 100;
        if (last_index == 0) {
            // Circular buffer is full, overwrite oldest record
            free(records[window[0]]);
            records[window[0]] = record;
        } else {
            // Add new record to the end of the window
            records[last_index] = record;
        }

        // Update rolling average
        rolling_average = (rolling_average * 99 + key) / 100;
    }

    // Find largest integer in the last 100 records
    int max_key = -1;
    for (int i = 0; i < 100; i++) {
        if (records[i].key > max_key) {
            max_key = records[i].key;
        }
    }

    // Print results
    printf("Largest integer found: %d\n", max_key);
    printf("Current rolling average: %f\n", rolling_average);

    // Free memory for arrays
    free(offset_values);
    free(keys);
    free(records);
}
