void parseAndAggregateData(char* filename) {
    // Initialize variables for tracking progress and errors
    int num_entries = 0, num_skipped = 0, error_code = 0;
    time_t max_timestamp = 0;
    float max_sensor_reading = -FLT_MAX;

    // Open the CSV file in read mode and check for errors
    FILE* csv_file = fopen(filename, "r");
    if (csv_file == NULL) {
        printf("Error: Could not open CSV file\n");
        return;
    }

    // Skip header lines if present and read data from the file
    char line[1024];
    while (fgets(line, 1024, csv_file) != NULL) {
        // Check for malformed CSV lines
        if (strlen(line) == 0 || line[0] == '#') continue;

        // Parse the timestamp and sensor reading from the current line
        time_t timestamp = strtol(line, &line, 10);
        float sensor_reading = strtof(line, NULL);

        // Check for empty or malformed data lines and skip them
        if (timestamp == 0 || sensor_reading < 0) {
            num_skipped++;
            continue;
        }

        // Update the maximum timestamp and sensor reading encountered so far
        if (timestamp > max_timestamp) max_timestamp = timestamp;
        if (sensor_reading > max_sensor_reading) max_sensor_reading = sensor_reading;

        // Store the current data entry in the vector of data entries
        data_entry* new_entry = new data_entry();
        new_entry->timestamp = timestamp;
        new_entry->sensorReading = sensor_reading;
        data_entries.push_back(new_entry);

        // Compute the moving average of the sensor readings over the last 10 entries
        if (data_entries.size() > window_size) {
            float sum = 0;
            for (int i = data_entries.size() - window_size; i < data_entries.size(); i++) {
                sum += data_entries[i]->sensorReading;
            }
            new_entry->movingAverage = sum / window_size;
        }

        // Increment the number of entries processed and check for memory allocation errors
        num_entries++;
        if (data_entries.capacity() == data_entries.size()) {
            error_code = 1;
            break;
        }
    }

    // Close the CSV file and print the maximum sensor reading encountered during processing
    fclose(csv_file);
    printf("Maximum sensor reading: %f\n", max_sensor_reading);

    // Clean up any allocated resources before exiting, including memory leaks
    for (int i = 0; i < data_entries.size(); i++) {
        delete data_entries[i];
    }
    data_entries.clear();

    // Return an appropriate error code if necessary
    if (error_code == 1) return -1;
}
