// Define a function to allocate memory for the struct objects and populate the string array
void initializeStructs(int numStructs, int maxSize) {
    // Allocate memory for the struct objects
    structs = (struct_t *)malloc(numStructs * sizeof(struct_t));
    if (!structs) {
        fprintf(stderr, "Error: Failed to allocate memory for structs\n");
        return;
    }

    // Initialize the struct objects and populate the string array
    for (int i = 0; i < numStructs; i++) {
        structs[i].value = 0.0;
        structs[i].label[0] = '\0';
        structs[i].id = i;
        structs[i].size = maxSize;
        structs[i].state = AVAILABLE;
    }
}

// Define a function to add new struct objects and manage memory allocation
int addStruct(double value, char *label) {
    // Check if there is enough memory available for the new struct object
    size_t totalSize = sizeof(struct_t) + strlen(label);
    if (totalSize > maxSize) {
        fprintf(stderr, "Error: Not enough memory to add new struct\n");
        return -1;
    }

    // Find an available struct object and update its values
    for (int i = 0; i < numStructs; i++) {
        if (structs[i].state == AVAILABLE) {
            structs[i].value = value;
            strcpy(structs[i].label, label);
            structs[i].id++;
            structs[i].size += totalSize;
            structs[i].state = UNAVAILABLE;
            return i;
        }
    }

    // If no available struct objects are found, allocate new memory and add a new object
    struct_t *newStruct = (struct_t *)realloc(structs, (numStructs + 1) * sizeof(struct_t));
    if (!newStruct) {
        fprintf(stderr, "Error: Failed to allocate memory for new struct\n");
        return -1;
    }
    structs = newStruct;

    // Initialize the new struct object and populate the string array
    structs[numStructs].value = value;
    strcpy(structs[numStructs].label, label);
    structs[numStructs].id = numStructs;
    structs[numStructs].size = totalSize;
    structs[numStructs].state = UNAVAILABLE;

    return numStructs++;
}

