        fprintf(stderr, "Error: Invalid ID provided\n");
        return;
    }

    // Find the struct object with the specified ID and update its state
    for (int i = 0; i < numStructs; i++) {
        if (structs[i].id == id) {
            structs[i].state = AVAILABLE;
            break;
        }
    }
}

