        // Increment number of lines parsed
        num_lines++;
    }

    // Check for read failure or end of file
    if (bytes_read == -1) {
        fprintf(stderr, "Error: Failed to read from input file\n");
        exit(EXIT_FAILURE);
    }

    // Calculate average value of float field across all struct objects
    double average = 0;
    for (int i = 0; i < num_lines; i++) {
        average += custom_structs[i].float_field;
    }
    average /= num_lines;

    // Return the average value and memory usage statistics
    printf("Average value of float field: %f\n", average);
    printf("Total number of lines parsed: %d\n", num_lines);
    printf("Memory used for double precision floating-point numbers: %zu bytes\n", *double_mem);
    printf("Memory used for variable-length char strings: %zu bytes\n", *char_str_mem);
    printf("Memory used for custom struct objects: %zu bytes\n", *custom_struct_mem);

    // Free memory allocated for the collections
    free(doubles);
    free(char_strings);
    free(custom_structs);
}

int main(int argc, char* argv[]) {
