    while (!feof(input_file)) {
        char buffer[BUFSIZ];
        fread(buffer, BUFSIZ, 1, input_file);
        file_size += BUFSIZ;
    }

    // Close the input file and allocate memory for the collections
    fclose(input_file);
    size_t num_lines = (file_size / sizeof(double)) + 1;
    parse_file(num_lines);

    return 0;
}
