    // Count the frequency of each element in the array
    int counts[MAX_SIZE] = {0};
    for (int i = 0; i < n; i++) {
        counts[arr[i]]++;
    }
    // Find the maximum count and its corresponding index
    int maxCount = 0, maxIndex = -1;
    for (int i = 0; i < MAX_SIZE; i++) {
        if (counts[i] > maxCount) {
            maxCount = counts[i];
            maxIndex = i;
        }
    }
