// C function to manage a dynamic storage system for records with unique integer keys, long offset values, and timestamps
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <errno.h>

// Record structure to store key-value pairs and timestamps
typedef struct {
    int key;      // unique integer key
    long offset;  // long value
    time_t timestamp;  // timestamp in milliseconds since the epoch
} record_t;

// Linked list node structure to store pointers to records
typedef struct node {
    record_t *record;
    struct node *next;
} node_t;

// Global variable to track the total number of records currently stored
int num_records = 0;

// Function to initialize a random integer key within a specified range
int generate_key(int min, int max) {
    int rand_key;
    do {
        // Generate a random integer within the specified range
        rand_key = min + (rand() % (max - min));
    } while (rand_key == 0);
    return rand_key;
}

// Function to initialize a record with a unique key, long offset value, and timestamp
record_t *init_record(int min, int max) {
    // Allocate memory for the record
    record_t *record = (record_t *)malloc(sizeof(record_t));
    if (!record) {
        fprintf(stderr, "Failed to allocate memory for record: %s\n", strerror(errno));
        return NULL;
    }

    // Initialize the key with a random integer within the specified range
    int rand_key = generate_key(min, max);
    while (lookup_record(rand_key)) {
        // Generate a new random key if the generated key already exists in the system
        rand_key = generate_key(min, max);
    }
    record->key = rand_key;

    // Initialize the offset value with a random long integer within the specified range
    record->offset = ((long)rand() % (max - min)) + min;

    // Initialize the timestamp with the current time in milliseconds since the epoch
    time_t timestamp = time(NULL);
    record->timestamp = timestamp;

    return record;
}

// Function to insert a new record into the linked list
node_t *insert_record(record_t *record) {
    // Allocate memory for the new node
    node_t *new_node = (node_t *)malloc(sizeof(node_t));
    if (!new_node) {
        fprintf(stderr, "Failed to allocate memory for new node: %s\n", strerror(errno));
        return NULL;
    }

    // Initialize the new node with the given record
    new_node->record = record;
    new_node->next = NULL;

    // Add the new node to the end of the linked list
    if (head == NULL) {
        head = new_node;
        tail = new_node;
    } else {
        tail->next = new_node;
        tail = new_node;
    }
    num_records++;

    return new_node;
}

// Function to delete a record from the linked list based on its key
void delete_record(int key) {
    // Find the node with the given key and remove it from the linked list
    node_t *prev = NULL, *curr = head;
    while (curr != NULL && curr->record->key != key) {
        prev = curr;
        curr = curr->next;
    }
    if (curr == NULL) {
        fprintf(stderr, "Record with key %d does not exist in the system\n", key);
        return;
    }
    if (prev == NULL) {
        head = curr->next;
    } else {
        prev->next = curr->next;
    }
    free(curr);
    num_records--;
}

// Function to retrieve a record from the linked list based on its key
record_t *lookup_record(int key) {
    // Find the node with the given key and return the corresponding record
    node_t *curr = head;
    while (curr != NULL && curr->record->key != key) {
        curr = curr->next;
    }
    if (curr == NULL) {
        fprintf(stderr, "Record with key %d does not exist in the system\n", key);
        return NULL;
    }
    return curr->record;
}

// Function to update a record's offset value based on its key
void update_offset(int key, long offset) {
    // Find the node with the given key and update its offset value
    node_t *curr = head;
    while (curr != NULL && curr->record->key != key) {
        curr = curr->next;
    }
    if (curr == NULL) {
        fprintf(stderr, "Record with key %d does not exist in the system\n", key);
        return;
    }
    curr->record->offset = offset;
}

// Function to update a record's timestamp based on its key
void update_timestamp(int key) {
    // Find the node with the given key and update its timestamp value
    node_t *curr = head;
    while (curr != NULL && curr->record->key != key) {
        curr = curr->next;
    }
    if (curr == NULL) {
        fprintf(stderr, "Record with key %d does not exist in the system\n", key);
        return;
    }
    time_t timestamp = time(NULL);
    curr->record->timestamp = timestamp;
}

// Function to print all records stored in the linked list
void print_records() {
    node_t *curr = head;
    while (curr != NULL) {
        printf("Record with key %d and offset %ld\n", curr->record->key, curr->record->offset);
        curr = curr->next;
    }
}

// Function to free all memory allocated for the linked list
void cleanup() {
    node_t *curr = head;
    while (curr != NULL) {
        node_t *temp = curr;
        curr = curr->next;
        free(temp);
    }
}

int main() {
    // Initialize the linked list with a single record
    head = tail = insert_record(init_record());

    // Insert multiple records into the linked list
    for (int i = 0; i < 5; i++) {
        insert_record(init_record());
    }

    // Delete a record from the linked list based on its key
    delete_record(1);

    // Update a record's offset value based on its key
    update_offset(2, 10);

    // Update a record's timestamp based on its key
    update_timestamp(3);

    // Print all records stored in the linked list
    print_records();

    // Free all memory allocated for the linked list
    cleanup();

    return 0;
}']

