// Function to process events in batches
void processAndFindMax(Event** events, int num_events) {
    if (num_events <= 0) return;

    // Calculate the maximum priority among all events
    float max_priority = -1;
    for (int i = 0; i < num_events; ++i) {
        if (events[i]->priority > max_priority) {
            max_priority = events[i]->priority;
        }
    }

    // Print the maximum priority to stdout
    printf("Max priority: %.2f\n", max_priority);
}

