    if (fp == NULL) return;

    Event** events = my_malloc(sizeof(Event*) * batch_size);
    for (int i = 0; i < batch_size; ++i) {
        events[i] = my_malloc(sizeof(Event));
    }

    int num_events = fread(events, sizeof(Event), batch_size, fp);
    if (num_events > 0) {
        processAndFindMax(events, num_events);

        // Write the events to the log file
        if (logging_enabled) {
            FILE* log_file = fopen(log_file_path, "a");
            for (int i = 0; i < num_events; ++i) {
                Event* event = events[i];
                char* description = event->description;
                if (description == NULL || strlen(description) == 0) {
                    fprintf(log_file, "Event: %d %.2f %f\n", event->key, event->timestamp, event->priority);
                } else {
                    fprintf(log_file, "Event: %d %.2f %f %s\n", event->key, event->timestamp, event->priority, description);
                }
            }
            fclose(log_file);
        }
    }

    // Free the events
    for (int i = 0; i < batch_size; ++i) {
        my_free(events[i]);
    }
    my_free(events);
}

// Function to read input from standard input
