int processAndFindMax(size_t n) {
    // Allocate memory for the offset array
    long* offsets = malloc(n * sizeof(long));
    if (!offsets) {
        return -1;
    }

    // Allocate memory for the key array
    int* keys = malloc(n * sizeof(int));
    if (!keys) {
        free(offsets);
        return -2;
    }

    // Allocate memory for the record array
    Record* records = malloc(n * sizeof(Record));
    if (!records) {
        free(offsets);
        free(keys);
        return -3;
    }

    // Initialize the summary information
    Summary* summaries = malloc(sizeof(Summary));
    if (!summaries) {
        free(offsets);
        free(keys);
        free(records);
        return -4;
    }

    // Initialize the offset array
    for (size_t i = 0; i < n; ++i) {
        offsets[i] = i * sizeof(Record);
    }

    // Initialize the key and timestamp arrays
    srand(time(NULL));
    for (size_t i = 0; i < n; ++i) {
        keys[i] = rand() % 100;
        records[i].timestamp = time(NULL);
    }

    // Find the maximum key
    int max_key = INT_MIN;
    for (size_t i = 0; i < n; ++i) {
        if (keys[i] > max_key) {
            max_key = keys[i];
        }
    }

    // Free the allocated memory
    free(offsets);
    free(keys);
    free(records);
    free(summaries);

    return max_key;
}
