#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <pthread.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <dirent.h>
#include <errno.h>
#include <limits.h>
#include <fcntl.h>

#define MAX_FILENAME 256
#define MAX_METADATA 1024
#define MIN_FREE_SPACE 1024*1024 // 1 MB

// Global variables
int cache_size = 100; // Initially allocate 100 entries in the cache
int quota = 100000; // 100KB per user by default

// Structures for file metadata
struct file_metadata {
    char filename[MAX_FILENAME];
    int size;
    time_t last_modified;
    uid_t owner;
    gid_t group;
    mode_t permissions;
};

// Cache for recently accessed files
struct file_cache {
    struct file_metadata metadata[MAX_METADATA];
    int cache_size; // Current size of the cache
};

// Function to handle file system operations
void handleFileSystemOperations(char *operation, char *filename) {
    // Initialize variables for the current operation
    struct stat buf;
    struct file_cache cache;
    int file_descriptor = -1;
    int retval = 0;
    time_t timestamp;

    // Obtain metadata about the file being operated on
    if (stat(filename, &buf) < 0) {
        fprintf(stderr, "Error: Failed to obtain metadata for %s\n", filename);
        return;
    }

    // Initialize cache and metadata structures
    cache.cache_size = 0;
    struct file_metadata *metadata = &cache.metadata[0];
    memset(metadata, 0, sizeof(struct file_metadata));

    // Determine the current user's quota in bytes
    uid_t user_id = getuid();
    gid_t group_id = getgid();
    int quota_size = quota * 1024; // Convert from KB to bytes

    // Check if the file being operated on is in the cache
    for (int i = 0; i < cache.cache_size; i++) {
        if (!strcmp(filename, cache.metadata[i].filename)) {
            metadata = &cache.metadata[i];
            break;
        }
    }

    // Perform the desired operation on the file
    if (!strcmp("create", operation)) {
        // Create a new file with the specified name and permissions
        file_descriptor = open(filename, O_CREAT | O_WRONLY, buf.st_mode);
        if (file_descriptor < 0) {
            fprintf(stderr, "Error: Failed to create %s\n", filename);
            return;
        }
    } else if (!strcmp("delete", operation)) {
        // Delete the specified file and remove it from the cache
        retval = unlink(filename);
        if (retval < 0) {
            fprintf(stderr, "Error: Failed to delete %s\n", filename);
            return;
        }
        for (int i = 0; i < cache.cache_size; i++) {
            if (!strcmp(filename, cache.metadata[i].filename)) {
                cache.cache_size--;
                break;
            }
        }
    } else if (!strcmp("modify", operation)) {
        // Modify the specified file and update its metadata in the cache
        retval = open(filename, O_WRONLY, buf.st_mode);
        if (retval < 0) {
            fprintf(stderr, "Error: Failed to modify %s\n", filename);
            return;
        }
        file_descriptor = retval;
    } else if (!strcmp("rename", operation)) {
        // Rename the specified file and update its metadata in the cache
        char *new_filename = (char *)malloc(MAX_FILENAME * sizeof(char));
        strcpy(new_filename, filename);
        retval = rename(filename, new_filename);
        if (retval < 0) {
            fprintf(stderr, "Error: Failed to rename %s\n", filename);
            return;
        }
        for (int i = 0; i < cache.cache_size; i++) {
            if (!strcmp(filename, cache.metadata[i].filename)) {
                strcpy(cache.metadata[i].filename, new_filename);
                break;
            }
        }
    } else if (!strcmp("traverse", operation)) {
        // Traverse the specified directory and update metadata for its contents in the cache
        DIR *dirp = opendir(filename);
        if (dirp == NULL) {
            fprintf(stderr, "Error: Failed to traverse %s\n", filename);
            return;
        }
        struct dirent *dp;
        while ((dp = readdir(dirp)) != NULL) {
            char file_path[MAX_FILENAME];
            strcpy(file_path, filename);
            strcat(file_path, "/");
            strcat(file_path, dp->d_name);
            struct stat buf;
            if (stat(file_path, &buf) < 0) {
                fprintf(stderr, "Error: Failed to obtain metadata for %s\n", file_path);
                continue;
            }
            // Update the metadata in the cache
            struct file_metadata *metadata = &cache.metadata[cache.cache_size];
            memset(metadata, 0, sizeof(struct file_metadata));
            strcpy(metadata->filename, dp->d_name);
            metadata->size = buf.st_size;
            metadata->last_modified = buf.st_mtime;
            metadata->owner = buf.st_uid;
            metadata->group_id = buf.st_gid;
            cache.cache_size++;
        }
    } else {
        fprintf(stderr, "Error: Unknown operation %s\n", operation);
        return;
    }

    // Update the file's metadata in the cache if it was modified or created
    if (file_descriptor > 0) {
        struct stat buf;
        fstat(file_descriptor, &buf);
        struct file_metadata *metadata = &cache.metadata[cache.cache_size];
        memset(metadata, 0, sizeof(struct file_metadata));
        strcpy(metadata->filename, filename);
        metadata->size = buf.st_size;
        metadata->last_modified = buf.st_mtime;
        metadata->owner = buf.st_uid;
        metadata->group_id = buf.st_gid;
        cache.cache_size++;
    }

    // Check if the user's quota has been exceeded
    for (int i = 0; i < cache.cache_size; i++) {
        if (user_id == cache.metadata[i].owner && group_id == cache.metadata[i].group_id) {
            quota_size -= cache.metadata[i].size;
        }
    }
    if (quota_size < 0) {
        fprintf(stderr, "Error: User's quota has been exceeded\n");
        return;
    }

    // Update the file's metadata in the cache and log the operation to a file
    for (int i = 0; i < cache.cache_size; i++) {
        if (!strcmp(filename, cache.metadata[i].filename)) {
            metadata = &cache.metadata[i];
            break;
        }
    }
    char log_entry[1024];
    strftime(log_entry, 1024, "%F %T", gmtime(&metadata->last_modified));
    fprintf(stderr, "Error: User's quota has been exceeded\n");
    return;
}
