  int errorCode;   // Error code from connection attempts
} dbMetadata;

// Define the structure for a record in the database
typedef struct record {
  int key;        // Random integer value
  double timestamp;  // Time stamp in milliseconds since epoch
} record;

// Define the structure for the connection pool
typedef struct connectionPool {
  int maxSize;       // Maximum size of the connection pool
  int idleTimeout;   // Idle timeout in seconds
  int retryLimit;    // Retry limit for failed connections
  pthread_mutex_t mutex;  // Mutex for synchronizing access to the pool
  pthread_cond_t cond;  // Condition variable for signaling idle connections
  record *records;   // Array of records in the pool
} connectionPool;

// Function for initializing a new connection pool
connectionPool *initializeConnectionPool(int maxSize, int idleTimeout, int retryLimit) {
  connectionPool *pool = (connectionPool *)malloc(sizeof(connectionPool));
  if (pool == NULL) {
    printf("Error: Failed to allocate memory for the connection pool\n");
    return NULL;
  }

  // Initialize the mutex and condition variable
  pthread_mutex_init(&pool->mutex, NULL);
  pthread_cond_init(&pool->cond, NULL);

  // Set the maximum size of the pool
  pool->maxSize = maxSize;

  // Set the idle timeout in seconds
  pool->idleTimeout = idleTimeout;

  // Set the retry limit for failed connections
  pool->retryLimit = retryLimit;

  // Allocate memory for the records array
  pool->records = (record *)malloc(sizeof(record) * maxSize);
  if (pool->records == NULL) {
    printf("Error: Failed to allocate memory for the record array\n");
    return NULL;
  }

  // Initialize all records in the pool as idle
  for (int i = 0; i < maxSize; i++) {
    pool->records[i].key = -1;
    pool->records[i].timestamp = 0;
  }

  return pool;
}

// Function for allocating a new connection in the pool
int allocateConnection(connectionPool *pool) {
  // Check if the pool is full
  if (pool->size == pool->maxSize) {
    printf("Error: Connection pool is full\n");
    return -1;
  }

  // Allocate a new record in the pool
  int index = pool->nextIndex++;
  pool->records[index].key = generateRandomInt(pool);
  pool->records[index].timestamp = time(NULL) * 1000;

  // Increment the size of the pool
  pool->size++;

  return index;
}

// Function for releasing a connection in the pool
int releaseConnection(connectionPool *pool, int index) {
  // Check if the index is valid
  if (index < 0 || index >= pool->maxSize) {
    printf("Error: Invalid index\n");
    return -1;
  }

  // Set the record as idle
  pool->records[index].key = -1;
  pool->records[index].timestamp = time(NULL) * 1000;

  // Decrement the size of the pool
  pool->size--;

  return 0;
}

// Function for validating a connection in the pool
int validateConnection(connectionPool *pool, int index) {
  // Check if the index is valid
  if (index < 0 || index >= pool->maxSize) {
    printf("Error: Invalid index\n");
    return -1;
  }

  // If the record is not idle, return an error
  if (pool->records[index].key != -1) {
    printf("Error: Connection is not idle\n");
    return -1;
  }

  // Check if the connection has timed out
  time_t currentTime = time(NULL);
