int networkManager(network_queue_t* queue, char* url, int method, double timeout) {
    // Check if the queue is empty
    if (STAILQ_EMPTY(&queue->requests)) {
        // If the queue is empty, allocate memory for a new request
        request_t* new_request = malloc(sizeof(request_t));
        if (!new_request) {
            return -1;
        }

        // Initialize the new request with the given URL, method, and timeout
        new_request->url = url;
        new_request->method = method;
        new_request->timeout = timeout;

        // Add the new request to the queue
        STAILQ_INSERT_TAIL(&queue->requests, &new_request->next);

        // Update the queue size and last check timestamp
        queue->size++;
        gettimeofday(&queue->last_check, NULL);
    } else {
        // If the queue is not empty, allocate memory for a new request and add it to the queue
        request_t* new_request = malloc(sizeof(request_t));
