// Define a structure to represent a log entry
typedef struct {
    char* text; // Text content of the log entry
    int id; // Numeric identifier for the log entry
    time_t timestamp; // Timestamp for the log entry
    bool status; // Status indicator for the log entry
} LogEntry;

// Define a structure to represent a memory segment
typedef struct {
    void* buffer; // Pointer to the start of the buffer
    size_t size; // Size of the buffer in bytes
} MemorySegment;

// Define a linked list node to store log entries
typedef struct LogEntryNode {
    LogEntry entry;
    struct LogEntryNode* next;
} LogEntryNode;

// Define a linked list to store log entries
LogEntryNode* logEntries = NULL;

// Define a memory pool for allocating log entry nodes
MemorySegment logEntryNodesPool = {NULL, 0};

// Define a mutex to protect the log entries and memory pool
pthread_mutex_t logMutex = PTHREAD_MUTEX_INITIALIZER;

// Function to allocate memory for a new log entry node
void* allocLogEntryNode(size_t size) {
    // Check if there is enough space in the pool
    if (logEntryNodesPool.size - sizeof(MemorySegment) >= size) {
        // Allocate memory from the pool
        void* mem = logEntryNodesPool.buffer;
        logEntryNodesPool.buffer += size;
        logEntryNodesPool.size -= size;
        return mem;
    } else {
        // Allocate memory from the heap if necessary
        return malloc(size);
    }
}

// Function to free memory for a log entry node
void freeLogEntryNode(void* mem) {
    // Check if the memory is in the pool
    if (mem >= logEntryNodesPool.buffer &&
            mem < logEntryNodesPool.buffer + logEntryNodesPool.size) {
        // Free memory from the pool
        logEntryNodesPool.size += sizeof(MemorySegment);
    } else {
        // Free memory from the heap if necessary
        free(mem);
    }
}

// Function to add a new log entry
void addLogEntry(LogEntry* entry) {
    LogEntryNode* node = (LogEntryNode*)allocLogEntryNode(sizeof(LogEntry));
    memcpy(&node->entry, entry, sizeof(LogEntry));
    node->next = NULL;

    // Lock the mutex to protect the log entries and memory pool
    pthread_mutex_lock(&logMutex);

    // Add the new node to the linked list of log entries
    if (logEntries == NULL) {
        logEntries = node;
    } else {
        LogEntryNode* current = logEntries;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = node;
    }

    // Unlock the mutex
    pthread_mutex_unlock(&logMutex);
}

// Function to remove a log entry
void removeLogEntry(int id) {
    // Lock the mutex to protect the log entries and memory pool
    pthread_mutex_lock(&logMutex);

    // Find the node with the matching ID
    LogEntryNode* current = logEntries;
    while (current != NULL && current->entry.id != id) {
        current = current->next;
    }

    // Remove the node from the linked list of log entries
    if (current != NULL) {
        if (current == logEntries) {
            logEntries = current->next;
        } else {
            LogEntryNode* previous = logEntries;
            while (previous->next != current) {
                previous = previous->next;
            }
            previous->next = current->next;
        }

        // Free the memory used by the node
        freeLogEntryNode(&current->entry);
    }

    // Unlock the mutex
    pthread_mutex_unlock(&logMutex);
}

// Function to update a log entry
void updateLogEntry(int id, LogEntry* entry) {
    // Lock the mutex to protect the log entries and memory pool
    pthread_mutex_lock(&logMutex);

    // Find the node with the matching ID
    LogEntryNode* current = logEntries;
    while (current != NULL && current->entry.id != id) {
        current = current->next;
    }

    // Update the entry if found
    if (current != NULL) {
        memcpy(&current->entry, entry, sizeof(LogEntry));
    }

    // Unlock the mutex
    pthread_mutex_unlock(&logMutex);
}

// Function to retrieve a log entry
LogEntry* getLogEntry(int id) {
    LogEntry* entry = NULL;

    // Lock the mutex to protect the log entries and memory pool
    pthread_mutex_lock(&logMutex);

    // Find the node with the matching ID
    LogEntryNode* current = logEntries;
    while (current != NULL && current->entry.id != id) {
        current = current->next;
    }

    // Copy the entry if found
    if (current != NULL) {
        entry = (LogEntry*)allocLogEntryNode(sizeof(LogEntry));
        memcpy(entry, &current->entry, sizeof(LogEntry));
    }

    // Unlock the mutex
    pthread_mutex_unlock(&logMutex);

    return entry;
}

// Function to retrieve all log entries
void getAllLogEntries(LogEntry** entries, int* count) {
    *entries = NULL;
    *count = 0;

    // Lock the mutex to protect the log entries and memory pool
    pthread_mutex_lock(&logMutex);

    // Copy all log entries
    LogEntryNode* current = logEntries;
    while (current != NULL) {
        *entries = (LogEntry*)allocLogEntryNode(sizeof(LogEntry));
        memcpy(*entries, &current->entry, sizeof(LogEntry));
        (*count)++;
        current = current->next;
    }

    // Unlock the mutex
    pthread_mutex_unlock(&logMutex);
}

// Function to clear all log entries
void clearLogEntries() {
    // Lock the mutex to protect the log entries and memory pool
    pthread_mutex_lock(&logMutex);

    // Free all log entry nodes
    LogEntryNode* current = logEntries;
    while (current != NULL) {
        LogEntryNode* next = current->next;
        freeLogEntryNode(&current->entry);
        current = next;
    }

    // Clear the linked list
    logEntries = NULL;

    // Unlock the mutex
    pthread_mutex_unlock(&logMutex);
}
