    off_t filesize;
    time_t lastAccessed;
    uint32_t checksum;
};

struct dataChunk {
    int recordID;
    double value;
    struct fileInfo fileInfo;
};

// Global variables for data chunk management
static size_t numDataChunks = 0;
static size_t maxDataChunks = 1000;
static struct dataChunk* dataChunks = NULL;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to read data chunks from a file
int readDataChunks(const char* filename, size_t numRecords) {
    // Open the file for reading
    int fd = open(filename, O_RDONLY);
    if (fd == -1) {
        printf("Error opening file: %s\n", strerror(errno));
        return -1;
    }

    // Allocate memory for the data chunks
    numDataChunks = 0;
    size_t chunkSize = sizeof(struct dataChunk) * numRecords;
    if (chunkSize > maxDataChunks * sizeof(struct dataChunk)) {
        printf("Error: cannot allocate %zu bytes of memory\n", chunkSize);
        close(fd);
        return -1;
    }

    // Read the file and populate the data chunks
    while (numDataChunks < numRecords) {
        struct dataChunk* chunk = &dataChunks[numDataChunks];
        int readBytes = read(fd, chunk, sizeof(struct dataChunk));
        if (readBytes == -1) {
            printf("Error reading file: %s\n", strerror(errno));
            close(fd);
            return -1;
        } else if (readBytes != sizeof(struct dataChunk)) {
            break;
        }
        numDataChunks++;
    }

    // Close the file and return the number of records read
    close(fd);
    return numDataChunks;
}

// Function to update a record value in a data chunk
int updateRecordValue(size_t index, double newValue) {
    if (index >= numDataChunks) {
        printf("Error: invalid data chunk index %zu\n", index);
        return -1;
    }

    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Update the record value and release the lock
    dataChunks[index].value = newValue;
    pthread_mutex_unlock(&mutex);
    return 0;
}

// Function to merge two datasets by concatenating their records
int mergeDatasets(struct dataChunk* dataset1, struct dataChunk* dataset2) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Calculate the total number of records in both datasets
    size_t numRecords = 0;
    for (size_t i = 0; i < maxDataChunks; i++) {
        if (dataset1[i].recordID != -1) {
            numRecords++;
        }
        if (dataset2[i].recordID != -1) {
            numRecords++;
        }
    }

    // Allocate memory for the merged dataset
    size_t chunkSize = sizeof(struct dataChunk) * numRecords;
    struct dataChunk* mergedDataset = malloc(chunkSize);
    if (mergedDataset == NULL) {
        printf("Error: cannot allocate %zu bytes of memory\n", chunkSize);
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    // Concatenate the records from both datasets
    size_t mergedIndex = 0;
    for (size_t i = 0; i < maxDataChunks; i++) {
        if (dataset1[i].recordID != -1) {
            memcpy(&mergedDataset[mergedIndex], &dataset1[i], sizeof(struct dataChunk));
            mergedIndex++;
        }
        if (dataset2[i].recordID != -1) {
            memcpy(&mergedDataset[mergedIndex], &dataset2[i], sizeof(struct dataChunk));
            mergedIndex++;
        }
    }

    // Release the lock and return the merged dataset
    pthread_mutex_unlock(&mutex);
    return mergedDataset;
}

// Function to handle file lifecycle events, such as opening and closing files
int handleFileLifecycleEvent(const char* filename, int eventType) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Open or close the file based on the event type
    if (eventType == 0) { // Opening a file
        int fd = open(filename, O_RDONLY);
        if (fd == -1) {
            printf("Error opening file: %s\n", strerror(errno));
            pthread_mutex_unlock(&mutex);
            return -1;
        }
    } else if (eventType == 1) { // Closing a file
        int fd = open(filename, O_RDONLY);
        if (fd == -1) {
            printf("Error closing file: %s\n", strerror(errno));
            pthread_mutex_unlock(&mutex);
            return -1;
        }
    }

    // Release the lock and return success
    pthread_mutex_unlock(&mutex);
    return 0;
}

// Function to handle errors, such as memory allocation failures
int handleError(const char* message) {
    printf("Error: %s\n", message);
    return -1;
}

// Main function for the program
int main() {
    // Allocate memory for the data chunks
    size_t chunkSize = sizeof(struct dataChunk) * maxDataChunks;
    struct dataChunk* dataset1 = malloc(chunkSize);
    struct dataChunk* dataset2 = malloc(chunkSize);
    if (dataset1 == NULL || dataset2 == NULL) {
        handleError("cannot allocate memory for the datasets");
        return -1;
    }

    // Read the files and populate the data chunks
    readDataset(filename1, dataset1);
    readDataset(filename2, dataset2);

    // Merge the two datasets by concatenating their records
    struct dataChunk* mergedDataset = mergeDatasets(dataset1, dataset2);
    if (mergedDataset == NULL) {
        handleError("cannot merge the datasets");
        return -1;
    }

    // Update a record value in the merged dataset
    updateRecordValue(0, 42.0);

    // Free the memory allocated for the data chunks
    free(dataset1);
    free(dataset2);
    free(mergedDataset);

    return 0;
}
