```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/mman.h>
#include <unistd.h>

// Define the struct for the records
struct Record {
    int key;
    long offset;
    time_t timestamp;
    int* values;
};

// Define a buffer for the dynamic dataset
static struct Record* buffer = NULL;

// Define the current size of the dataset
static size_t dataset_size = 0;

// Define the maximum size of the dataset
#define MAX_DATASET_SIZE 1024 * 1024 * 1024 // 1 GB

// Define the number of records to allocate at a time
#define ALLOCATION_SIZE 128

// Function to allocate memory for the dataset
static void allocate_memory(size_t size) {
    if (buffer != NULL) {
        free(buffer);
    }
    buffer = (struct Record*)malloc(size * sizeof(struct Record));
    if (buffer == NULL) {
        fprintf(stderr, "Failed to allocate memory for the dataset\n");
        exit(1);
    }
}

// Function to initialize a record
static void init_record(struct Record* record, int key, long offset, time_t timestamp) {
    record->key = key;
    record->offset = offset;
    record->timestamp = timestamp;
    record->values = NULL;
}

// Function to generate a non-predictable integer key within the specified range
static int generate_key(int min, int max) {
    return (rand() % (max - min)) + min;
}

// Function to generate a non-predictable long offset within the specified range
static long generate_offset(long min, long max) {
    return (rand() % (max - min)) + min;
}

// Function to generate a timestamp using the current system time
static time_t generate_timestamp() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    return ts.tv_sec * 1000 + ts.tv_nsec / 1000000;
}

// Function to insert a new record into the dataset
static void insert_record(struct Record* record) {
    // Check if the dataset needs to be resized
    if (dataset_size == MAX_DATASET_SIZE) {
        allocate_memory(MAX_DATASET_SIZE + ALLOCATION_SIZE);
    }
    buffer[dataset_size++] = *record;
}

// Function to retrieve a record from the dataset
static struct Record* get_record(int key) {
    for (int i = 0; i < dataset_size; i++) {
        if (buffer[i].key == key) {
            return &buffer[i];
        }
    }
    return NULL;
}

// Function to delete a record from the dataset
static void delete_record(int key) {
    for (int i = 0; i < dataset_size; i++) {
        if (buffer[i].key == key) {
            buffer[i] = buffer[dataset_size - 1];
            dataset_size--;
            return;
        }
    }
}

// Function to update a record in the dataset
static void update_record(int key, struct Record* new_record) {
    for (int i = 0; i < dataset_size; i++) {
        if (buffer[i].key == key) {
            buffer[i] = *new_record;
            return;
        }
    }
}

// Function to resize the integer array in a record
static void resize_array(struct Record* record, size_t new_size) {
    if (record->values == NULL) {
        record->values = (int*)malloc(new_size * sizeof(int));
        return;
    }
    int* new_values = (int*)realloc(record->values, new_size * sizeof(int));
    if (new_values == NULL) {
        fprintf(stderr, "Failed to resize the integer array\n");
        exit(1);
    }
    record->values = new_values;
}

// Function to add a value to an existing record in the dataset
static void add_value(int key, int value) {
    struct Record* record = get_record(key);
    if (record == NULL) {
        return;
    }
    resize_array(record, record->values.size + 1);
    record->values[record->values.size - 1] = value;
}

// Function to delete a value from an existing record in the dataset
static void delete_value(int key, int index) {
    struct Record* record = get_record(key);
    if (record == NULL) {
        return;
    }
    for (size_t i = 0; i < record->values.size - 1; i++) {
        record->values[i] = record->values[i + 1];
    }
    resize_array(record, record->values.size - 1);
}

// Function to update a value in an existing record in the dataset
static void update_value(int key, int index, int value) {
    struct Record* record = get_record(key);
    if (record == NULL) {
        return;
    }
    record->values[index] = value;
}
