Record* sort_records(long offset[], int keys[], size_t num_keys) {
    // Allocate memory for the sorted records
    Record* sorted_records = (Record*)malloc(num_keys * sizeof(Record));
    if (!sorted_records) {
        fprintf(stderr, "Error: Failed to allocate memory for sorted records\n");
        exit(EXIT_FAILURE);
    }

    // Initialize the sorted records with the initial keys and offsets
    for (size_t i = 0; i < num_keys; i++) {
        sorted_records[i].key = keys[i];
        sorted_records[i].offset = offset[i];
    }

    // Sort the records based on their keys in ascending order
    qsort(sorted_records, num_keys, sizeof(Record), compare_records);

    // Ensure that no two consecutive records have the same key value
    for (size_t i = 1; i < num_keys; i++) {
        if (sorted_records[i].key == sorted_records[i - 1].key) {
            int temp_key = sorted_records[i].key + 1;
            while (temp_key == sorted_records[i].key || temp_key == sorted_records[i - 1].key) {
                temp_key++;
            }
            sorted_records[i].key = temp_key;
        }
    }

    // Release memory for the initial arrays of keys and offsets
    free(keys);
    free(offset);

    return sorted_records;
}

int compare_records(const void* a, const void* b) {
    Record* record1 = (Record*)a;
    Record* record2 = (Record*)b;
    return record1->key - record2->key;
}
