int main() {
    // Create a vector to store the incoming data records
    std::vector<record_t> records;

    // Create a mutex to protect the aggregated data structure from concurrent access
    pthread_mutex_t aggregated_data_lock = PTHREAD_MUTEX_INITIALIZER;

    // Create a thread for each source of incoming data
    int num_threads = 2;
    pthread_t threads[num_threads];

    // Create an aggregated data structure to store the total sum and maximum number of records
    aggregated_data_t* aggregated_data = new aggregated_data_t();
    aggregated_data->total_records = 0;
    aggregated_data->max_records = 0;
    aggregated_data->sum = 0.0f;

    // Create a condition variable to signal when the aggregation is complete
    pthread_cond_t aggregation_complete = PTHREAD_COND_INITIALIZER;

    for (int i = 0; i < num_threads; i++) {
        // Create a thread worker function that reads from the data source and updates the aggregated data structure
        pthread_create(&threads[i], NULL, processAndAggregateDataStream, &records);
    }

    // Wait for all threads to complete
    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }

    // Print the total number of records processed and the maximum number of records held in memory at any given time
    printf("Total number of records: %ld\n", aggregated_data->total_records);
    printf("Maximum number of records: %ld\n", aggregated_data->max_records);

    // Print the aggregate sum of all 'float' values found in the records processed
    printf("Aggregate sum: %.2f\n", aggregated_data->sum);

    // Clean up resources
    delete aggregated_data;

    return 0;
}

void* processAndAggregateDataStream(void* arg) {
