        readRecord(record);

        // Add the record to the vector of records
        pthread_mutex_lock(&aggregated_data_lock);
        records->push_back(record);
        if (records->size() > aggregated_data->max_records) {
            aggregated_data->max_records = records->size();
        }
        pthread_mutex_unlock(&aggregated_data_lock);

        // Update the aggregated data structure with the new record
        pthread_mutex_lock(&aggregated_data_lock);
        aggregated_data->total_records++;
        aggregated_data->sum += record.value;
        pthread_cond_broadcast(&aggregation_complete);
        pthread_mutex_unlock(&aggregated_data_lock);
    }

    return NULL;
}
