#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>

// Structure to represent file metadata
typedef struct {
    char* filename;
    size_t filesize;
} file_metadata_t;

// Thread-safe hash table for storing file metadata
typedef struct {
    pthread_mutex_t mutex;
    file_metadata_t* buckets[1024];
} file_table_t;

// Function to allocate memory for file metadata structures
file_metadata_t* alloc_file_metadata(char* filename, size_t filesize) {
    file_metadata_t* metadata = (file_metadata_t*) malloc(sizeof(file_metadata_t));
    metadata->filename = strdup(filename);
    metadata->filesize = filesize;
    return metadata;
}

// Function to deallocate memory for file metadata structures
void free_file_metadata(file_metadata_t* metadata) {
    if (metadata == NULL) {
        return;
    }
    free(metadata->filename);
    free(metadata);
}

// Function to insert a new entry into the file table
int insert_file_table(file_table_t* table, char* filename, size_t filesize) {
    if (table == NULL || filename == NULL) {
        return -1;
    }

    // Lock the mutex to ensure thread-safety
    pthread_mutex_lock(&(table->mutex));

    // Find an empty bucket in the table
    size_t i = 0;
    while (i < 1024 && table->buckets[i] != NULL) {
        i++;
    }

    // If no empty buckets found, return -1
    if (i == 1024) {
        pthread_mutex_unlock(&(table->mutex));
        return -1;
    }

    // Allocate memory for the new entry and copy the filename and filesize
    file_metadata_t* metadata = alloc_file_metadata(filename, filesize);
    table->buckets[i] = metadata;

    pthread_mutex_unlock(&(table->mutex));

    return 0;
}

// Function to retrieve an entry from the file table
int lookup_file_table(file_table_t* table, char* filename) {
    if (table == NULL || filename == NULL) {
        return -1;
    }

    // Lock the mutex to ensure thread-safety
    pthread_mutex_lock(&(table->mutex));

    // Find the bucket with the matching filename and return the filesize if found
    size_t i = 0;
    while (i < 1024 && table->buckets[i] != NULL) {
        if (strcmp(table->buckets[i]->filename, filename) == 0) {
            pthread_mutex_unlock(&(table->mutex));
            return table->buckets[i]->filesize;
        }
        i++;
    }

    // If no matching bucket found, return -1
    pthread_mutex_unlock(&(table->mutex));
    return -1;
}

// Function to remove an entry from the file table
int delete_file_table(file_table_t* table, char* filename) {
    if (table == NULL || filename == NULL) {
        return -1;
    }

    // Lock the mutex to ensure thread-safety
    pthread_mutex_lock(&(table->mutex));

    // Find the bucket with the matching filename and delete it if found
    size_t i = 0;
    while (i < 1024 && table->buckets[i] != NULL) {
        if (strcmp(table->buckets[i]->filename, filename) == 0) {
            free_file_metadata(table->buckets[i]);
            table->buckets[i] = NULL;
            break;
        }
        i++;
    }

    // If no matching bucket found, return -1
    pthread_mutex_unlock(&(table->mutex));
    return (i == 1024) ? -1 : 0;
}
