    int num_threads = 0;
    for (int i = 0; i < MAX_THREADS; i++) {
        if (node->files[i].path != NULL) {
            num_threads++;
        }
    }

    if (num_threads == MAX_THREADS) {
        printf("Node not available\n");
        return;
    }

    int file_index = 0;
    for (int i = 0; i < MAX_FILES; i++) {
        if (node->files[i].path == NULL) {
            file_index = i;
            break;
        }
    }

    node->files[file_index] = *file;
    unlock_file(file->fd);
}

