// Structure to store metadata for each web application connection
struct webAppMetadata {
    int transaction_id;
    char* query_string;
    struct timeval last_access;
    int error_code;
};

// Structure to store a pool of connections
struct connectionPool {
    size_t num_connections;
    struct webAppMetadata* metadata;
    struct connectionPool* next;
};

// Function to allocate a new connection pool
struct connectionPool* allocateConnectionPool(size_t num_connections) {
    // Allocate memory for the pool structure
    struct connectionPool* pool = malloc(sizeof(struct connectionPool));
    if (!pool) {
        printf("Error: Failed to allocate memory for connection pool\n");
        return NULL;
    }

    // Initialize the pool structure
    pool->num_connections = num_connections;
    pool->metadata = malloc(sizeof(struct webAppMetadata) * num_connections);
    if (!pool->metadata) {
        printf("Error: Failed to allocate memory for connection metadata\n");
        free(pool);
        return NULL;
    }

    // Initialize the connection metadata
    for (size_t i = 0; i < num_connections; i++) {
        pool->metadata[i].transaction_id = -1;
        pool->metadata[i].query_string = NULL;
        gettimeofday(&(pool->metadata[i].last_access), NULL);
        pool->metadata[i].error_code = 0;
    }

    return pool;
}

// Function to free a connection pool
void freeConnectionPool(struct connectionPool* pool) {
    if (!pool) {
        printf("Error: Cannot free NULL connection pool\n");
        return;
    }

    // Free the metadata array
    free(pool->metadata);

    // Free the pool structure
    free(pool);
}

// Function to allocate a new connection from a pool
struct webAppMetadata* allocateConnectionFromPool(struct connectionPool* pool) {
    if (!pool) {
        printf("Error: Cannot allocate connection from NULL pool\n");
        return NULL;
    }

    // Find the first available connection in the pool
    for (size_t i = 0; i < pool->num_connections; i++) {
        if (pool->metadata[i].transaction_id == -1) {
            return &(pool->metadata[i]);
        }
    }

    // If no available connection is found, create a new one
    struct webAppMetadata* metadata = malloc(sizeof(struct webAppMetadata));
    if (!metadata) {
        printf("Error: Failed to allocate memory for new connection\n");
        return NULL;
    }

    metadata->transaction_id = -1;
    metadata->query_string = NULL;
    gettimeofday(&(metadata->last_access), NULL);
    metadata->error_code = 0;

    return metadata;
}

// Function to free a connection from a pool
void freeConnectionFromPool(struct webAppMetadata* metadata) {
    if (!metadata) {
        printf("Error: Cannot free NULL connection\n");
        return;
    }

    // Free the query string and reset the metadata fields
    free(metadata->query_string);
    metadata->transaction_id = -1;
    metadata->query_string = NULL;
    gettimeofday(&(metadata->last_access), NULL);
    metadata->error_code = 0;
}

// Function to manage web application connections in a highly concurrent multi-threaded environment
void manageWebAppConnections(struct connectionPool* pool, struct configFile* config) {
    // Check if the configuration file is valid
    if (!config || !config->query_string || !config->transaction_size || !config->num_connections) {
        printf("Error: Invalid configuration file\n");
        return;
    }

    // Allocate a new connection pool if the current one is full
    if (pool == NULL) {
        pool = allocateConnectionPool(config->num_connections);
        if (!pool) {
            printf("Error: Failed to allocate memory for connection pool\n");
            return;
        }
    } else if (pool->num_connections < config->num_connections) {
        struct connectionPool* new_pool = realloc(pool, sizeof(struct connectionPool) * config->num_connections);
        if (!new_pool) {
            printf("Error: Failed to reallocate memory for connection pool\n");
            return;
        }

        // Initialize the new connections
        for (size_t i = 0; i < config->num_connections - pool->num_connections; i++) {
            struct webAppMetadata* metadata = allocateConnectionFromPool(pool);
            if (!metadata) {
                printf("Error: Failed to allocate memory for new connection\n");
                return;
            }

            new_pool->metadata[i].transaction_id = -1;
            new_pool->metadata[i].query_string = NULL;
            gettimeofday(&(new_pool->metadata[i].last_access), NULL);
            new_pool->metadata[i].error_code = 0;
        }

        pool = new_pool;
    }

    // Execute the query and commit the transaction
    for (size_t i = 0; i < config->num_connections; i++) {
        struct webAppMetadata* metadata = &(pool->metadata[i]);
        if (metadata->transaction_id != -1) {
            // Execute the query and commit the transaction
            int ret = executeQueryAndCommitTransaction(config, metadata);
            if (ret != 0) {
                printf("Error: Failed to execute query and commit transaction\n");
                return;
            }
        } else {
            // Open a new connection and start a new transaction
            ret = openNewConnectionAndStartTransaction(config, metadata);
            if (ret != 0) {
                printf("Error: Failed to open new connection and start transaction\n");
                return;
            }
        }
    }
}

// Function to execute a query and commit a transaction
int executeQueryAndCommitTransaction(struct configFile* config, struct webAppMetadata* metadata) {
    // Check if the configuration file is valid
    if (!config || !config->query_string || !config->transaction_size || !metadata) {
        printf("Error: Invalid configuration file or metadata\n");
        return -1;
    }

    // Execute the query and commit the transaction
    int ret = executeQuery(config, metadata);
    if (ret != 0) {
        printf("Error: Failed to execute query\n");
        return -1;
    }

    ret = commitTransaction(metadata);
    if (ret != 0) {
        printf("Error: Failed to commit transaction\n");
        return -1;
    }

    // Update the last access time and reset the error code
    gettimeofday(&(metadata->last_access), NULL);
    metadata->error_code = 0;

    return 0;
}

// Function to open a new connection and start a new transaction
int openNewConnectionAndStartTransaction(struct configFile* config, struct webAppMetadata* metadata) {
    // Check if the configuration file is valid
    if (!config || !config->query_string || !config->transaction_size || !metadata) {
        printf("Error: Invalid configuration file or metadata\n");
        return -1;
    }

    // Open a new connection and start a new transaction
    int ret = openNewConnection(config, metadata);
    if (ret != 0) {
        printf("Error: Failed to open new connection\n");
        return -1;
    }

    ret = startTransaction(metadata);
    if (ret != 0) {
        printf("Error: Failed to start transaction\n");
        return -1;
    }

    // Update the last access time and reset the error code
    gettimeofday(&(metadata->last_access), NULL);
    metadata->error_code = 0;

    return 0;
}

// Function to execute a query
int executeQuery(struct configFile* config, struct webAppMetadata* metadata) {
    // Check if the configuration file is valid
    if (!config || !config->query_string || !metadata) {
        printf("Error: Invalid configuration file or metadata\n");
        return -1;
    }

    // Execute the query and check for errors
    int ret = executeQuery_(config, metadata);
    if (ret != 0) {
        printf("Error: Failed to execute query\n");
        return -1;
    }

    return 0;
}

// Function to commit a transaction
int commitTransaction(struct webAppMetadata* metadata) {
    // Check if the metadata is valid
    if (!metadata) {
        printf("Error: Invalid metadata\n");
        return -1;
    }

    // Commit the transaction and check for errors
    int ret = commitTransaction_(metadata);
    if (ret != 0) {
        printf("Error: Failed to commit transaction\n");
        return -1;
    }

    return 0;
}

// Function to open a new connection
int openNewConnection(struct configFile* config, struct webAppMetadata* metadata) {
    // Check if the configuration file is valid
    if (!config || !config->query_string || !metadata) {
        printf("Error: Invalid configuration file or metadata\n");
        return -1;
    }

    // Open a new connection and check for errors
    int ret = openNewConnection_(config, metadata);
    if (ret != 0) {
        printf("Error: Failed to open new connection\n");
        return -1;
    }

    return 0;
}

// Function to start a transaction
int startTransaction(struct webAppMetadata* metadata) {
    // Check if the metadata is valid
    if (!metadata) {
        printf("Error: Invalid metadata\n");
        return -1;
    }

    // Start the transaction and check for errors
    int ret = startTransaction_(metadata);
    if (ret != 0) {
        printf("Error: Failed to start transaction\n");
        return -1;
