// Structure to represent a record with a pointer to a buffer and an integer value
typedef struct {
    char *buffer;
    int value;
} Record;

// Function to initialize the memory for the arrays of file offsets, identifiers, and records
Record* initialize_memory(int offset_count, int identifier_count, int record_count) {
    // Allocate memory for the arrays of file offsets, identifiers, and records
    long *offsets = malloc(offset_count * sizeof(long));
    if (offsets == NULL) {
        printf("Error: Failed to allocate memory for the array of file offsets.\n");
        return NULL;
    }

    int *identifiers = malloc(identifier_count * sizeof(int));
    if (identifiers == NULL) {
        printf("Error: Failed to allocate memory for the array of identifiers.\n");
        free(offsets);
        return NULL;
    }

    Record *records = malloc(record_count * sizeof(Record));
    if (records == NULL) {
        printf("Error: Failed to allocate memory for the array of records.\n");
        free(offsets);
        free(identifiers);
        return NULL;
    }

    // Initialize the arrays of file offsets, identifiers, and records
    for (int i = 0; i < offset_count; ++i) {
        offsets[i] = i;
    }

    for (int i = 0; i < identifier_count; ++i) {
        identifiers[i] = i + 1;
    }

    for (int i = 0; i < record_count; ++i) {
        records[i].buffer = malloc(16 * sizeof(char));
        if (records[i].buffer == NULL) {
            printf("Error: Failed to allocate memory for the buffer of record %d.\n", i);
            free(offsets);
            free(identifiers);
            return NULL;
        }
        records[i].value = rand() % 1000 + 1;
    }

    // Copy the unique identifiers into the buffers of each record
    for (int i = 0; i < record_count; ++i) {
        memcpy(records[i].buffer, &identifiers[i], sizeof(int));
    }

    return records;
}

// Function to release the memory allocated by initialize_memory
void free_memory(Record *records) {
    // Release the memory allocated for the arrays of file offsets, identifiers, and records
    long *offsets = (long *)records;
    int *identifiers = (int *)(offsets + offset_count);
    Record *records = (Record *)(identifiers + identifier_count);

    for (int i = 0; i < record_count; ++i) {
        free(records[i].buffer);
    }

    free(offsets);
    free(identifiers);
    free(records);
}
