};

// Function to add a new record to the collection
void addRecord(struct Collection* coll, int key) {
    // Check if the key is already present in the collection
    for (size_t i = 0; i < coll->size; ++i) {
        if (coll->records[i].key == key) {
            // If a duplicate key is detected, retry generating a new key until a unique one is found
            while (true) {
                int newKey = generateNewKey();
                bool foundDuplicate = false;
                for (size_t j = 0; j < coll->size; ++j) {
                    if (coll->records[j].key == newKey) {
                        foundDuplicate = true;
                        break;
                    }
                }
                if (!foundDuplicate) {
                    key = newKey;
                    break;
                }
            }
        }
    }

    // Grow the collection if necessary
    if (coll->size == coll->capacity) {
        coll->capacity *= 2;
        struct Record* newRecords = realloc(coll->records, coll->capacity * sizeof(struct Record));
        assert(newRecords != NULL);
        coll->records = newRecords;
    }

    // Add the new record to the collection
    coll->records[coll->size++] = (struct Record) {key, NULL};
}

// Function to retrieve a record from the collection by key
struct Record* getRecord(struct Collection* coll, int key) {
    for (size_t i = 0; i < coll->size; ++i) {
        if (coll->records[i].key == key) {
            return &coll->records[i];
        }
    }
    return NULL;
}

// Function to update a record in the collection by key
void updateRecord(struct Collection* coll, int key, void* value) {
    struct Record* record = getRecord(coll, key);
    if (record != NULL) {
        record->value = value;
    } else {
        addRecord(coll, key);
    }
}

// Function to iterate over the collection in a consistent order based on keys
void iterateOverRecords(struct Collection* coll, void (*callback)(struct Record*)) {
    for (size_t i = 0; i < coll->size; ++i) {
        callback(&coll->records[i]);
    }
}

// Function to free the memory allocated for the collection and its records
void destroyCollection(struct Collection* coll) {
    free(coll->records);
    free(coll);
}
