#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <assert.h>
#include <stdbool.h>
#include <pthread.h>
#include <unistd.h>
#include <sys/time.h>

// Define the record structure
typedef struct {
  int key;
} Record;

// Define the collection structure
typedef struct {
  // Array of records
  Record* records;
  // Size of the array
  size_t capacity;
  // Current number of records in the collection
  size_t count;
  // Maximum capacity of the collection
  size_t max_capacity;
} Collection;

// Define the hash function for hashing the keys
unsigned long hash(int key) {
  unsigned long hash = 0;
  hash ^= (hash << 7) ^ (key << 14) ^ (key >> 5);
  return hash % max_capacity;
}

// Initialize a collection with the specified maximum capacity
void initialize(Collection* collection, size_t max_capacity) {
  assert(collection != NULL);
  // Allocate memory for the array of records
  collection->records = (Record*)malloc(sizeof(Record) * max_capacity);
  // Set the capacity and count to 0
  collection->capacity = max_capacity;
  collection->count = 0;
  collection->max_capacity = max_capacity;
}

// Add a new record to the collection
void add(Collection* collection, int key) {
  // Check if the collection is at capacity
  if (collection->count == collection->capacity) {
    // Increase the capacity by 50%
    collection->capacity *= 1.5;
    // Reallocate memory for the array of records
    collection->records = (Record*)realloc(collection->records, sizeof(Record) * collection->capacity);
  }
  // Generate a new key if a duplicate is detected during initialization
  while (find(collection, key) != NULL) {
    key++;
  }
  // Insert the record into the array of records
  collection->records[collection->count].key = key;
  collection->count++;
}

// Find a record in the collection by its key
Record* find(Collection* collection, int key) {
  // Calculate the index of the record based on the hash function
  size_t index = hash(key);
  while (index < collection->capacity && collection->records[index].key != key) {
    index++;
  }
  if (index == collection->capacity) {
    return NULL;
  }
  return &collection->records[index];
}

// Update a record in the collection by its key
void update(Collection* collection, int key, int new_key) {
  // Find the record to be updated
  Record* record = find(collection, key);
  if (record == NULL) {
    return;
  }
  // Remove the old record from the array of records
  memmove(&collection->records[index], &collection->records[index + 1], sizeof(Record) * (collection->count - index - 1));
  collection->count--;
  // Insert the updated record into the array of records
  record->key = new_key;
}

// Iterate over all records in the collection
void iterate(Collection* collection, void (*visit)(Record*)) {
  for (size_t i = 0; i < collection->count; i++) {
    visit(&collection->records[i]);
  }
}

// Destroy a collection and release its memory
void destroy(Collection* collection) {
  assert(collection != NULL);
  free(collection->records);
}

// Test the implementation with various scenarios
int main() {
  // Initialize a collection with a maximum capacity of 10,000 records
  Collection* collection = (Collection*)malloc(sizeof(Collection));
  initialize(collection, 10000);

  // Add a new record to the collection with a key of 5
  add(collection, 5);

  // Find the record with the key of 5
  Record* record = find(collection, 5);
  assert(record != NULL && record->key == 5);

  // Update the record with a new key of 10
  update(collection, 5, 10);

  // Find the updated record with the key of 10
  Record* updated_record = find(collection, 10);
  assert(updated_record != NULL && updated_record->key == 10);

  // Iterate over all records in the collection and print their keys
  iterate(collection, [](Record* record) {
    printf("%d\n", record->key);
  });

  // Destroy the collection and release its memory
  destroy(collection);

  return 0;
}
```
This implementation uses a hash-based structure to store the records in the collection. The hash function is used to calculate the index of each record in the array of records, which allows for fast lookups and updates. The collection can grow dynamically as needed by increasing its capacity by 50%.

The `add` function first checks if the collection is at capacity and if so, increases the capacity by 50% and reallocates memory for the array of records. It then generates a new key if a duplicate is detected during initialization and inserts the record into the array of records. The `find` function calculates the index of the record based on the hash function and iterates over the array until it finds the desired record or reaches the end of the array.

The `update` function first finds the record to be updated and then removes it from the array of records. It then inserts the updated record into the array of records. The `iterate` function visits each record in the collection and prints its key. The `destroy` function releases the memory allocated for the collection.

In the test scenario, a new record is added to the collection with a key of 5, which is then found using the `find` function. The record is then updated with a new key of 10, which is then found using the `update` function. Finally, the `iterate` function visits each record in the collection and prints its key.']

