```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define a struct to represent a transaction
typedef struct {
    int transaction_id;
    double amount;
    time_t timestamp;
} transaction_t;

// Function to dynamically allocate memory for an array of transactions
transaction_t* alloc_transactions(int num_transactions, int min_amount, int max_amount) {
    // Allocate memory for the array of transactions
    transaction_t* transactions = (transaction_t*)malloc(num_transactions * sizeof(transaction_t));
    if (!transactions) {
        perror("Failed to allocate memory for transactions");
        exit(EXIT_FAILURE);
    }

    // Initialize the array of transactions
    for (int i = 0; i < num_transactions; i++) {
        transaction_t* transaction = &transactions[i];
        transaction->transaction_id = i + 1;
        transaction->amount = (double)rand() / RAND_MAX * (max_amount - min_amount) + min_amount;
        transaction->timestamp = time(NULL);
    }

    // Filter transactions based on the minimum and maximum amount thresholds
    int filtered_num_transactions = 0;
    for (int i = 0; i < num_transactions; i++) {
        transaction_t* transaction = &transactions[i];
        if (transaction->amount >= min_amount && transaction->amount <= max_amount) {
            filtered_num_transactions++;
        }
    }

    // Reallocate memory for the filtered transactions
    transaction_t* filtered_transactions = (transaction_t*)realloc(transactions, filtered_num_transactions * sizeof(transaction_t));
    if (!filtered_transactions) {
        perror("Failed to reallocate memory for filtered transactions");
        exit(EXIT_FAILURE);
    }

    // Print the details of each transaction
    printf("Filtered transactions:\n");
    for (int i = 0; i < filtered_num_transactions; i++) {
        transaction_t* transaction = &filtered_transactions[i];
        printf("%d: %f, %ld\n", transaction->transaction_id, transaction->amount, transaction->timestamp);
    }

    // Free the memory allocated for the original transactions
    free(transactions);

    return filtered_transactions;
