// Function to evict least recently used records from the cache
void evict_lru() {
    size_t eviction_threshold = 1024; // Set the threshold for eviction
    if (cache_count >= eviction_threshold) { // If the count of records in the cache exceeds the threshold, start eviction
        while (true) { // Infinite loop to evict least recently used records from the cache
            size_t oldest_record = 0; // Initialize the index of the oldest record in the cache
