using namespace std;

struct LogEntry {
  int status;
  long timestamp;
  string eventType;
};

struct DatabaseEntry {
  int count;
  long totalDuration;
  vector<LogEntry> entries;
};

class LogProcessor {
 public:
  LogProcessor(size_t maxMemoryUsage, size_t maxThreads) :
      _maxMemoryUsage(maxMemoryUsage),
      _maxThreads(maxThreads),
      _logEntries(),
      _databaseEntries(),
      _mutex(),
      _cv(),
      _threadCount(0),
      _isRunning(true),
      _memoryUsage(0) {}

  ~LogProcessor() {
    stop();
  }

  void processAndIntegrateLogs(const LogEntry& logEntry) {
    // Check if the memory usage is within limits
    checkMemoryUsage();

    // Insert the log entry into the database
    insertIntoDatabase(logEntry);

    // Update the memory usage
    updateMemoryUsage();
  }

  void stop() {
    _isRunning = false;
    _cv.notify_all();
    for (auto& thread : _threads) {
      thread->join();
    }
    _threads.clear();
  }

 private:
  // Maximum memory usage in bytes
  size_t _maxMemoryUsage;

  // Maximum number of threads to use for processing logs
  size_t _maxThreads;

  // Vector of log entries to be processed
  vector<LogEntry> _logEntries;

  // Map of database entries, where the key is the event type and the value is the count and total duration
  unordered_map<string, DatabaseEntry> _databaseEntries;

  // Mutex for protecting access to shared data structures
  mutex _mutex;

  // Condition variable for signalling when new log entries are available
  condition_variable _cv;

  // Number of threads currently processing logs
  size_t _threadCount;

  // Flag indicating whether the processor is running or not
  bool _isRunning;

  // Current memory usage in bytes
  size_t _memoryUsage;

  void checkMemoryUsage() {
    if (_memoryUsage > _maxMemoryUsage) {
      _cv.wait(lock);
    }
  }

  void insertIntoDatabase(const LogEntry& logEntry) {
    // Lock the mutex to prevent race conditions
    lock_guard<mutex> lock(_mutex);

    // Update the database entry for this event type
    auto it = _databaseEntries.find(logEntry.eventType);
    if (it != _databaseEntries.end()) {
      it->second.count++;
      it->second.totalDuration += logEntry.duration;
    } else {
      DatabaseEntry entry{1, logEntry.duration, vector<LogEntry>{logEntry}};
      _databaseEntries[logEntry.eventType] = entry;
    }
  }

  void updateMemoryUsage() {
    // Lock the mutex to prevent race conditions
    lock_guard<mutex> lock(_mutex);

    // Update the memory usage
    _memoryUsage += sizeof(LogEntry) + logEntry.eventType.size();

    // Purge old entries if necessary
    while (_memoryUsage > _maxMemoryUsage * 0.75) {
      auto it = _databaseEntries.begin();
      if (it != _databaseEntries.end()) {
        size_t totalSize = sizeof(LogEntry) + it->first.size();
        for (auto& entry : it->second.entries) {
          totalSize += sizeof(LogEntry);
        }
        _memoryUsage -= totalSize;
        _databaseEntries.erase(it);
      }
    }
  }

  void processLogs() {
    // Lock the mutex to prevent race conditions
    lock_guard<mutex> lock(_mutex);

    // Loop until all log entries have been processed
    while (_logEntries.size()) {
      auto it = _logEntries.begin();
      if (it != _logEntries.end()) {
        processAndIntegrateLogs(*it);
        _logEntries.erase(it);
      }
    }
  }

  void run() {
    while (_isRunning) {
      // Check if there are any log entries to process
      checkMemoryUsage();

      // Process the logs if necessary
      if (_logEntries.size()) {
        processLogs();
      }

      // Sleep for a short time before checking again
      this_thread::sleep_for(chrono::milliseconds(10));
    }
  }
};

int main() {
  LogProcessor processor(1024 * 1024, 8);
  processor.start();

  // Example log entries
  vector<LogEntry> logEntries = {
      {"Event A", 1500000000, 100},
      {"Event B", 1600000000, 200},
      {"Event C", 1700000000, 300},
      {"Event A", 1800000000, 400},
      {"Event B", 1900000000, 500},
      {"Event C", 2000000000, 600},
      {"Event A", 2100000000, 700},
      {"Event B", 2200000000, 800},
      {"Event C", 2300000000, 900}
  };

  // Add the log entries to the processor
  for (auto& entry : logEntries) {
    processor.processAndIntegrateLogs(entry);
  }

  // Stop the processor
  processor.stop();

  return 0;
}
