#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Structure to represent a data entry
typedef struct {
    double value;
    char* string;
    int integer;
} data_entry;

// Function to allocate and initialize memory for a collection of data entries
data_entry* alloc_and_init_entries(int num_entries) {
    // Allocate memory for the array of data entries
    data_entry* entries = (data_entry*) malloc(num_entries * sizeof(data_entry));
    if (!entries) {
        fprintf(stderr, "Failed to allocate memory for %d entries\n", num_entries);
        return NULL;
    }

    // Initialize each entry in the array
    for (int i = 0; i < num_entries; ++i) {
        entries[i].value = 0.0;
        entries[i].string = NULL;
        entries[i].integer = 0;
    }

    return entries;
}

// Function to populate a collection of data entries with user input
void populate_entries(data_entry* entries, int num_entries) {
    // Read in the next batch of user input
    for (int i = 0; i < num_entries; ++i) {
        char buffer[1024];
        if (!fgets(buffer, sizeof(buffer), stdin)) {
            break;
        }

        // Parse the input and assign to the corresponding data entry field
        double value = atof(buffer);
        entries[i].value = value;
    }
}

// Function to serialize a collection of data entries to a file
void serialize_entries(data_entry* entries, int num_entries, FILE* file) {
    // Write the number of entries to the file
    fwrite(&num_entries, sizeof(int), 1, file);

    // For each entry in the collection, write its value and string fields to the file
    for (int i = 0; i < num_entries; ++i) {
        double value = entries[i].value;
        fwrite(&value, sizeof(double), 1, file);

        char* string = entries[i].string;
        int length = strlen(string);
        fwrite(&length, sizeof(int), 1, file);
        fwrite(string, sizeof(char), length, file);
    }
}

// Function to deserialize a collection of data entries from a file
void deserialize_entries(data_entry* entries, int num_entries, FILE* file) {
    // Read the number of entries from the file
    fread(&num_entries, sizeof(int), 1, file);

    // For each entry in the collection, read its value and string fields from the file
    for (int i = 0; i < num_entries; ++i) {
        double value;
        int length;
        fread(&value, sizeof(double), 1, file);
        fread(&length, sizeof(int), 1, file);
        char* string = (char*) malloc(length * sizeof(char));
        if (!string) {
            fprintf(stderr, "Failed to allocate memory for %d bytes\n", length);
            return;
        }
        fread(string, sizeof(char), length, file);
        entries[i].value = value;
        entries[i].string = string;
    }
}

// Function to free the memory allocated for a collection of data entries
void free_entries(data_entry* entries, int num_entries) {
    // Free each entry in the array
    for (int i = 0; i < num_entries; ++i) {
        free(entries[i].string);
    }

    // Finally, free the memory allocated for the array itself
    free(entries);
}
