  return current_memory_usage;
}

// Function to dynamically allocate and initialize arrays of 'long' offset values, 'int' keys, and 'record' structures
void* allocate_and_initialize_records(size_t num_records) {
  // Validate the number of records is positive
  if (num_records <= 0) {
    return NULL;
  }

  // Calculate the size of each 'record' structure in bytes
  size_t record_size = sizeof(struct record);

  // Calculate the total memory usage in bytes
  current_memory_usage += num_records * record_size;

  // Ensure the total memory usage does not exceed the maximum limit
  if (current_memory_usage > max_memory_limit) {
    printf("Maximum memory usage exceeded. Current usage: %zu, Maximum limit: %zu\n", current_memory_usage, max_memory_limit);
    return NULL;
  }

  // Allocate memory for the 'record' structures
  void* records = malloc(num_records * record_size);
  if (records == NULL) {
    printf("Failed to allocate memory for %zu records\n", num_records);
    return NULL;
  }

  // Initialize the 'record' structures
  for (int i = 0; i < num_records; ++i) {
    struct record* curr_record = (struct record*)records + i * record_size;
    curr_record->value = i;
  }

  return records;
}

// Function to release memory allocated by allocate_and_initialize_records()
void free_records(void* records) {
  // Check if the input pointer is NULL or not
  if (records == NULL) {
    printf("Invalid input pointer\n");
    return;
  }

  // Calculate the size of each 'record' structure in bytes
  size_t record_size = sizeof(struct record);

  // Release memory for the 'record' structures
  free(records);

  // Update the current memory usage
  current_memory_usage -= num_records * record_size;
}
