void processAndAggregateDataEntries(char **json_inputs, size_t num_inputs) {
    // Check for empty input
    if (num_inputs == 0) {
        fprintf(stderr, "Empty input provided\n");
        return;
    }

    // Allocate memory for three arrays: one for doubles, another for strings, and a third for data entries
    double *double_array = malloc(num_inputs * sizeof(double));
    char **string_array = malloc(num_inputs * sizeof(char*));
    struct data_entry *data_entries = malloc(num_inputs * sizeof(struct data_entry));

    // Check for memory allocation failures and handle them gracefully
    if (double_array == NULL || string_array == NULL || data_entries == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        free(double_array);
        free(string_array);
        free(data_entries);
        return;
    }

    // Initialize the arrays
    for (size_t i = 0; i < num_inputs; i++) {
        double_array[i] = NAN;
        string_array[i] = NULL;
        data_entries[i].double_value = NAN;
        data_entries[i].string_value = NULL;
        data_entries[i].int_value = -1;
    }

    // Iterate over the JSON inputs and extract the relevant information
    for (size_t i = 0; i < num_inputs; i++) {
        char *json_input = json_inputs[i];

        // Check if the input is malformed
        if (json_input == NULL || strlen(json_input) == 0) {
            fprintf(stderr, "Malformed JSON input provided\n");
            continue;
        }

        // Parse the JSON input and extract the relevant information
        json_t *root = json_loads(json_input, 0, NULL);
        if (root == NULL) {
