        if (double_value == NULL) {
            fprintf(stderr, "Failed to extract double value\n");
            continue;
        }
        double_array[i] = json_number_value(double_value);

        // Extract the string value from the JSON input
        json_t *string_value = json_object_get(root, "string_value");
        if (string_value == NULL) {
            fprintf(stderr, "Failed to extract string value\n");
            continue;
        }
        string_array[i] = strdup(json_string_value(string_value));

        // Extract the integer value from the JSON input
        json_t *int_value = json_object_get(root, "int_value");
        if (int_value == NULL) {
            fprintf(stderr, "Failed to extract integer value\n");
            continue;
        }
        data_entries[i].int_value = json_integer_value(int_value);

        // Free the JSON object and its children
        json_decref(root);
    }

    // Create a disjoint sets data structure to efficiently determine disjoint sets of numeric fields with identical values
    disjoint_sets *disjoint_sets = create_disjoint_sets();
    for (size_t i = 0; i < num_inputs; i++) {
        for (size_t j = i + 1; j < num_inputs; j++) {
            if (double_array[i] == double_array[j]) {
                union(disjoint_sets, i, j);
            }
        }
    }

    // Free the disjoint sets data structure
    free_disjoint_sets(disjoint_sets);
}

// Function to create a disjoint sets data structure
disjoint_sets *create_disjoint_sets() {
    disjoint_sets *sets = malloc(sizeof(disjoint_sets));
    if (sets == NULL) {
        fprintf(stderr, "Failed to allocate memory for disjoint sets\n");
        return NULL;
    }
    sets->data = malloc(num_inputs * sizeof(int));
    if (sets->data == NULL) {
        fprintf(stderr, "Failed to allocate memory for disjoint sets data\n");
        free(sets);
        return NULL;
    }
    sets->size = num_inputs;
    for (size_t i = 0; i < num_inputs; i++) {
        sets->data[i] = i;
    }
    return sets;
}

// Function to free a disjoint sets data structure
void free_disjoint_sets(disjoint_sets *sets) {
    free(sets->data);
    free(sets);
}

// Function to union two elements in the disjoint sets data structure
void union(disjoint_sets *sets, int a, int b) {
    if (a == b) return;
    int *data = sets->data;
    size_t size = sets->size;
    for (size_t i = 0; i < size; i++) {
        if (data[i] == a || data[i] == b) {
            data[i] = min(a, b);
        }
    }
}

// Function to find the minimum element in the disjoint sets data structure
int find_min(disjoint_sets *sets, int i) {
    int *data = sets->data;
    size_t size = sets->size;
    while (i != data[i]) {
        i = data[i];
    }
    return i;
}

// Function to determine if two elements are in the same disjoint set
bool is_in_same_set(disjoint_sets *sets, int a, int b) {
    return find_min(sets, a) == find_min(sets, b);
}
