record* allocateAndProcessRecords(size_t num_records) {
    // Initialize memory pool for offset_t, int, and record structures
    offset_t* offsets = (offset_t*)malloc(num_records * sizeof(offset_t));
    int* keys = (int*)malloc(num_records * sizeof(int));
    record* records = (record*)malloc(num_records * sizeof(record));

    // Seed random number generator for consistent but variable results
    srand(time(NULL));

    // Generate random offsets and keys within specified range
    for (size_t i = 0; i < num_records; i++) {
        offsets[i] = rand() % MEMORY_POOL_SIZE;
        keys[i] = rand() % MAX_RANDOM_INT - MIN_RANDOM_INT;
    }

    // Initialize record structures with offsets and keys
    for (size_t i = 0; i < num_records; i++) {
        records[i].offset = offsets[i];
        records[i].key = keys[i];
        records[i].random_int = rand() % MAX_RANDOM_INT - MIN_RANDOM_INT;
    }

    // Free memory pool for offset_t, int, and record structures
    free(offsets);
    free(keys);

    return records;
}

// Thread-safe function to handle compliance validation checks with API service
record* validateRecords(record* records, size_t num_records) {
    // Handle temporary unavailability or timeouts of the API service
    bool api_available = true;
    int retry_count = 0;
    while (api_available && retry_count < MAX_RETRY_COUNT) {
        if (!validateAPI()) {
            sleep(pow(2, retry_count)); // Exponential backoff
            retry_count++;
        } else {
            api_available = false;
        }
    }

    // Retry validation until API service is available or maximum retries reached
    if (!api_available) {
        handleError("Maximum retries exceeded");
        return NULL;
    }

    // Validate records with API service
    for (size_t i = 0; i < num_records; i++) {
        if (!validateRecord(records[i])) {
            handleError("Invalid record detected");
            return NULL;
        }
    }

    // Free memory pool for offset_t, int, and record structures
    free(offsets);
    free(keys);

    return records;
}

// Function to handle error conditions and provide clear error messages
