      return INPUT_DATA_INVALID_ERROR;
    }

    // Add the sensor value, timestamp, and status flag to the arrays
    sensorValues[windowSize - 1] = sensorValue;
    timestamps[windowSize - 1] = timestamp;
    metricRecords[windowSize - 1].sensorValue = sensorValue;
    metricRecords[windowSize - 1].timestamp = timestamp;
    metricRecords[windowSize - 1].statusFlag = 'G'; // Initialize status flag to good

    // Calculate the moving average and detect anomalies
    for (int i = 0; i < windowSize; i++) {
      movingAverage += sensorValues[i];
    }
    movingAverage /= windowSize;
    float stdDev = sqrt(((movingAverage * (windowSize - 1)) - ((sensorValues[windowSize - 1] - movingAverage) * (windowSize - 1))) / (windowSize - 2));
    if (fabs(sensorValues[windowSize - 1] - movingAverage) > stdDev * 3) {
      // Handle anomaly by logging an error message and continuing to process the remaining input
      printf("Error: Anomaly detected. Exiting.\n");
      return ANOMALY_DETECTED_ERROR;
    }

    // Shift the arrays down by one to make room for new data
    memmove(sensorValues, sensorValues + 1, (windowSize - 1) * sizeof(float));
    memmove(timestamps, timestamps + 1, (windowSize - 1) * sizeof(uint64_t));
    memmove(metricRecords, metricRecords + 1, (windowSize - 1) * sizeof(MetricRecord));

    // Handle potential connection timeouts or failures gracefully by retrying the read operation
    while (!feof(inputStream)) {
      if (fgets(inputStream, bufferSize, stdin) == NULL) {
        printf("Error: Connection timeout. Retrying.\n");
      } else {
        break;
      }
    }
  }

  // Print the latest aggregated metric and any detected anomalies
  printf("Aggregated metric: %.2f\n", movingAverage);
  if (numAnomaliesDetected > 0) {
    printf("Number of anomalies detected: %d\n", numAnomaliesDetected);
  }

  // Clean up any allocated resources before exiting
  free(sensorValues);
  free(timestamps);
  free(metricRecords);

  return 0;
}
