    // Initialize thread-safe data structures and synchronization mechanisms
    pthread_mutex_t lock;
    struct metric_record *records = (struct metric_record *)malloc(sizeof(struct metric_record) * MAX_THREADS);
    int num_threads = 0;
    int num_records = 0;
    int window_size = MIN_WINDOW_SIZE;
    struct timespec start, end;
    clock_gettime(CLOCK_REALTIME, &start);

    // Loop indefinitely until termination condition is met
    while (1) {
        // Read a line of data from standard input
        char *line = readline();

        // Parse the data into a struct metric_record object
        struct metric_record record;
        sscanf(line, "%f %lu %d", &record.sensor_value, &record.timestamp, &record.quality_flag);

        // Validate the data and handle edge cases
        if (record.timestamp < start.tv_sec) {
            continue;
        } else if (record.timestamp > end.tv_sec) {
            end = record.timestamp;
        }

        // Update the moving average window size based on volatility threshold and data processing rate
        float volatility = calculate_volatility(records, num_records);
        if (volatility > VOLATILITY_THRESHOLD) {
            window_size += 100;
        } else if (window_size > MIN_WINDOW_SIZE) {
            window_size -= 100;
        }

        // Add the record to the data structures
        records[num_records++] = record;

        // Start a new thread for processing metrics if necessary
        if (num_threads < MAX_THREADS) {
            pthread_t thread;
            struct thread_data *data = (struct thread_data *)malloc(sizeof(struct thread_data));
            data->lock = &lock;
            data->records = records;
            data->num_records = num_records;
            pthread_create(&thread, NULL, process_metrics, data);
            num_threads++;
        }
    }

    // Clean up and return successfully
    free(records);
    clock_gettime(CLOCK_REALTIME, &end);
    printf("Total time: %ld seconds\n", end.tv_sec - start.tv_sec);
    return 0;
}

// Function for handling signals and cleaning up data structures
void signal_handler(int sig) {
    // Clean up any remaining data structures
    free(records);

    // Terminate the program
    exit(EXIT_SUCCESS);
}

// Function for processing metrics in parallel using threads
void* process_metrics(void *data) {
    struct thread_data *thread_data = (struct thread_data *)data;
    pthread_mutex_t *lock = thread_data->lock;
    struct metric_record *records = thread_data->records;
    int num_records = thread_data->num_records;

    // Lock the mutex and process the records
    pthread_mutex_lock(lock);
    for (int i = 0; i < num_records; i++) {
        struct metric_record record = records[i];
        float moving_average = calculate_moving_average(records, i, window_size);
        if (record.sensor_value > moving_average) {
