            printf("Anomaly detected at timestamp %lu: sensor value %f > moving average %f\n", record.timestamp, record.sensor_value, moving_average);
        } else {
            // Continue processing normally
            continue;
        }
    }

    // Unlock the mutex and return successfully
    pthread_mutex_unlock(lock);
    return NULL;
}
