// Define a linked list structure to store the items
typedef struct node {
    Item data;
    struct node* next;
} Node;

// Define the function to initialize and manage the list of items
void init_list(int num_items, int *identifier, char **tag) {
    // Allocate memory for the linked list
    Node *head = malloc(sizeof(Node));
    head->next = NULL;

    // Initialize the current time as the timestamp for each item
    time_t curr_time = time(NULL);

    // Iterate over the number of items specified at runtime
    for (int i = 0; i < num_items; i++) {
        Node *new_node = malloc(sizeof(Node));
        new_node->data.timestamp = curr_time++;
        new_node->data.identifier = identifier[i];
        new_node->data.tag = strdup(tag[i]);
        new_node->next = head;
        head = new_node;
    }

    // Release the memory for the original head node
    free(head);
}

// Define a function to add an item to the list
void add_item(Item item) {
    // Allocate memory for the new node
    Node *new_node = malloc(sizeof(Node));
    new_node->data.timestamp = time(NULL);
    new_node->data.identifier = item.identifier;
    new_node->data.tag = strdup(item.tag);

