    // Iterate over the linked list to find the last node
    Node *curr_node = head;
    while (curr_node->next != NULL) {
        curr_node = curr_node->next;
    }

    // Add the new node to the end of the linked list
    curr_node->next = new_node;

    // Unlock the list and return
    pthread_mutex_unlock(&list_mutex);
}

// Define a function to remove an item from the list
void remove_item(Item item) {
    // Lock the list to prevent concurrent access
    pthread_mutex_lock(&list_mutex);

    // Iterate over the linked list to find the node containing the specified item
    Node *curr_node = head;
    while (curr_node != NULL && curr_node->data.identifier != item.identifier) {
        curr_node = curr_node->next;
    }

    // Check if the node was found
    if (curr_node == NULL) {
        pthread_mutex_unlock(&list_mutex);
        return;
    }

    // Remove the node from the linked list
    Node *prev_node = head;
    while (curr_node->next != NULL && curr_node->next->data.identifier != item.identifier) {
        prev_node = curr_node;
        curr_node = curr_node->next;
    }
    if (curr_node->next == NULL) {
        pthread_mutex_unlock(&list_mutex);
        return;
    }
    prev_node->next = curr_node->next;

    // Release the memory for the removed node
    free(curr_node);

    // Unlock the list and return
    pthread_mutex_unlock(&list_mutex);
}

// Define a function to serialize the list for persistence
void serialize_list() {
    // Lock the list to prevent concurrent access
    pthread_mutex_lock(&list_mutex);

    // Iterate over the linked list and append each item's data to a string buffer
    char *buf = malloc(sizeof(char) * 1024);
    Node *curr_node = head;
    while (curr_node != NULL) {
        buf += sprintf(buf, "%ld %d %s\n", curr_node->data.timestamp, curr_node->data.identifier, curr_node->data.tag);
        curr_node = curr_node->next;
    }

    // Unlock the list and return
    pthread_mutex_unlock(&list_mutex);
}

// Define a function to deserialize the list from persistence
void deserialize_list(char *buf) {
    // Lock the list to prevent concurrent access
    pthread_mutex_lock(&list_mutex);

    // Iterate over the string buffer and add each item's data to the linked list
    char *curr_pos = buf;
    while (curr_pos != NULL) {
        time_t timestamp;
        int identifier;
        char tag[1024];
        curr_pos += sscanf(curr_pos, "%ld %d %s\n", &timestamp, &identifier, tag);
        add_item((Item){.timestamp = timestamp, .identifier = identifier, .tag = strdup(tag)});
    }

    // Unlock the list and return
    pthread_mutex_unlock(&list_mutex);
}
