struct record {
    int value;
    double timestamp;
};

struct cache {
    struct record* records;
    size_t capacity;
    size_t count;
};

void allocateAndProcessRecords(struct cache* cache, int min_value, int max_value) {
    size_t num_records = 1000; // default number of records to process
    size_t record_size = sizeof(struct record);

    cache->capacity = num_records * record_size;
    cache->count = 0;
    cache->records = (struct record*)malloc(cache->capacity);

    if (!cache->records) {
        fprintf(stderr, "Error: failed to allocate memory for records\n");
        return;
    }

    // initialize random numbers and timestamps
    srand(time(NULL));
    for (size_t i = 0; i < num_records; ++i) {
        cache->records[i].value = rand() % (max_value - min_value + 1) + min_value;
        cache->records[i].timestamp = time(NULL);
    }

    // filter records based on timestamp interval
    struct record* current = NULL;
    for (size_t i = 0; i < num_records; ++i) {
        if (cache->records[i].timestamp >= time(NULL) - INTERVAL) {
            if (!current) {
                current = &cache->records[i];
            } else {
                cache->records[i] = *current;
                current = &cache->records[i];
            }
        }
    }

    // evict least recently used record when cache exceeds limit
    if (cache->count >= cache->capacity) {
        size_t oldest_index = 0;
        double oldest_timestamp = time(NULL);

        for (size_t i = 0; i < num_records; ++i) {
            if (cache->records[i].timestamp < oldest_timestamp) {
                oldest_index = i;
                oldest_timestamp = cache->records[i].timestamp;
            }
        }

        free(cache->records[oldest_index]);
        memmove(&cache->records[oldest_index], &cache->records[oldest_index + 1], (num_records - oldest_index - 1) * record_size);
        cache->count--;
    }
}
