// Function to dynamically allocate memory for an array of 'transaction' structures
struct transaction** allocate_transactions(int num_transactions, float amount_range_start, float amount_range_end) {
    // Check if input parameters are valid
    if (num_transactions <= 0 || amount_range_start >= amount_range_end) {
        return NULL;
    }

    struct transaction** transactions = malloc(sizeof(struct transaction*) * num_transactions);
    if (!transactions) {
        // Set error code and log failure
        return NULL;
    }

    for (int i = 0; i < num_transactions; i++) {
        struct transaction* current_transaction = malloc(sizeof(struct transaction));
        if (!current_transaction) {
            // Free previously allocated memory and set error code
            free_transactions(transactions, i);
            return NULL;
        }

        // Generate random amount within specified range
        float amount = amount_range_start + (float)(rand() % (amount_range_end - amount_range_start));
        current_transaction->amount = amount;

        // Get current timestamp
        time_t now = time(NULL);
        struct tm* local_time = localtime(&now);
        uint64_t timestamp = (uint64_t)mktime(local_time);
        current_transaction->timestamp = timestamp;

        // Generate random description
        const char* description = generate_description();
        current_transaction->description = description;

        transactions[i] = current_transaction;
    }

    return transactions;
}

// Function to dynamically allocate memory for an array of 'ledger' structures
struct ledger** allocate_ledgers(int num_ledgers) {
    // Check if input parameter is valid
    if (num_ledgers <= 0) {
        return NULL;
    }

    struct ledger** ledgers = malloc(sizeof(struct ledger*) * num_ledgers);
    if (!ledgers) {
        // Set error code and log failure
        return NULL;
    }

    for (int i = 0; i < num_ledgers; i++) {
        struct ledger* current_ledger = malloc(sizeof(struct ledger));
        if (!current_ledger) {
            // Free previously allocated memory and set error code
            free_ledgers(ledgers, i);
            return NULL;
        }

        current_ledger->balance = 0.0;
        current_ledger->transactions = malloc(sizeof(struct transaction*) * num_transactions);
        if (!current_ledger->transactions) {
            // Free previously allocated memory and set error code
            free_ledgers(ledgers, i);
            return NULL;
        }

        ledgers[i] = current_ledger;
    }

    return ledgers;
}

// Function to efficiently manage the linked list of transactions in a ledger
void add_transaction(struct ledger* ledger, struct transaction* transaction) {
    // Check if input parameters are valid
    if (!ledger || !transaction) {
        return;
    }

    // Update balance and allocate memory for new transaction pointer
    ledger->balance += transaction->amount;
    ledger->transactions = realloc(ledger->transactions, sizeof(struct transaction*) * (ledger->num_transactions + 1));
    if (!ledger->transactions) {
        // Set error code and log failure
        return;
    }

    // Add new transaction pointer to linked list
    ledger->transactions[ledger->num_transactions++] = transaction;
}

// Function to efficiently traverse the linked list of transactions in a ledger
void traverse_transactions(struct ledger* ledger, void (*callback)(struct transaction*)) {
    // Check if input parameters are valid
    if (!ledger || !callback) {
        return;
    }

    for (int i = 0; i < ledger->num_transactions; i++) {
        callback(ledger->transactions[i]);
    }
}

// Function to deallocate memory for an array of 'transaction' structures
void free_transactions(struct transaction** transactions, int num_transactions) {
    // Check if input parameters are valid
    if (!transactions || num_transactions <= 0) {
        return;
    }

    for (int i = 0; i < num_transactions; i++) {
        free(transactions[i]);
    }
    free(transactions);
}

// Function to deallocate memory for an array of 'ledger' structures
void free_ledgers(struct ledger** ledgers, int num_ledgers) {
    // Check if input parameters are valid
    if (!ledgers || num_ledgers <= 0) {
        return;
    }

    for (int i = 0; i < num_ledgers; i++) {
        free(ledgers[i]->transactions);
        free(ledgers[i]);
    }
    free(ledgers);
}

// Function to generate a random description
const char* generate_description() {
    // Generate random number between 0 and 1024 (inclusive)
    int random_index = rand() % 1025;

    // Initialize description array with NULL characters
    char description[16] = "";

    // Fill description array with random characters
    for (int i = 0; i < sizeof(description); i++) {
        if (random_index >= 97 && random_index <= 122) {
            description[i] = 'a' + random_index - 97;
        } else if (random_index >= 65 && random_index <= 90) {
            description[i] = 'A' + random_index - 65;
        } else if (random_index >= 48 && random_index <= 57) {
            description[i] = '0' + random_index - 48;
        } else {
            description[i] = '_';
        }
    }

    // Return description as a const char*
    return description;
}
