            perror("Error parsing CSV line");
            continue;
        }

        // Add reading to the sliding window
        readings[count].timestamp = timestamp;
        readings[count].sensorReading = sensorReading;
        count++;

        // Update moving average if window is full
        if (count == windowSize) {
            total += readings[0].sensorReading;
            float average = total / windowSize;
            printf("Moving average: %f\n", average);
            total -= readings[0].sensorReading;
            count--;
        }
    }

    // Handle edge cases
    if (count == 0) {
        perror("No sensor readings found in file");
    } else if (count == 1) {
        printf("Maximum sensor reading: %f\n", readings[0].sensorReading);
    } else {
        // Update moving average for last window
        total += readings[0].sensorReading;
        float average = total / count;
        printf("Moving average: %f\n", average);
        printf("Maximum sensor reading: %f\n", readings[count - 1].sensorReading);
    }

    // Free memory and close file
    free(readings);
    fclose(fp);
}
