void processAndAggregateMetrics(char *dataSource, char *dataType, void *data, size_t dataSize) {
    // Initialize structures for holding metric records
    struct metricRecord *metricRecords = NULL;
    int numRecords = 0;
    int maxNumRecords = 1000;

    // Check if data source is valid and data type is supported
    assert(dataSource != NULL && strcmp(dataType, "float") == 0);

    // Parse incoming data to populate metric records
    while (dataSize > 0) {
        // Allocate memory for new record
        if (numRecords >= maxNumRecords) {
            // Reallocate memory for more records
            maxNumRecords *= 2;
            metricRecords = realloc(metricRecords, maxNumRecords * sizeof(struct metricRecord));
        }

        // Populate new record with incoming data
        struct metricRecord *newRecord = &metricRecords[numRecords++];
        memcpy(&newRecord->sensorValue, data, sizeof(float));
        memcpy(&newRecord->timestamp, data + sizeof(float), sizeof(uint64_t));
        newRecord->status = 0;

        // Advance data pointer by record size
        data += sizeof(struct metricRecord);
        dataSize -= sizeof(struct metricRecord);
    }

    // Aggregate metrics based on moving average and detect anomalies
    float aggregatedValue = 0.0f;
    int numValidRecords = 0;
    for (int i = 0; i < numRecords; ++i) {
        if (metricRecords[i].status == 0) {
            aggregatedValue += metricRecords[i].sensorValue;
            ++numValidRecords;
        }
    }
    aggregatedValue /= numValidRecords;
    float anomalyThreshold = aggregatedValue * 0.5f;

    // Print latest aggregated value and detected anomalies
