    for (int i = 0; i < numRecords; ++i) {
        if (metricRecords[i].status == 0 && fabs(metricRecords[i].sensorValue - aggregatedValue) > anomalyThreshold) {
            printf("Anomaly Detected: sensor value = %f, timestamp = %lu\n", metricRecords[i].sensorValue, metricRecords[i].timestamp);
        }
    }

    // Clean up allocated memory
    free(metricRecords);
}

// Function to handle errors and clean up resources
