// Define a function to generate random integers within a specified range
int generateRandomInt(int min, int max) {
    return min + (rand() % (max - min + 1));
}

// Define a function to get the current time in milliseconds since the epoch
double getCurrentTimeInMs() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    return (double)ts.tv_sec * 1000 + (double)ts.tv_nsec / 1000000;
}

// Define a function to process the input data and find the largest integer
void processAndFindMax(InputData* input, int size) {
    // Initialize variables for tracking the largest integer and its corresponding timestamp
    int maxKey = -1;
    double maxTimestamp = 0.0;

    // Iterate over the input data and find the largest integer
    for (int i = 0; i < size; i++) {
        if (input[i].key > maxKey) {
            maxKey = input[i].key;
            maxTimestamp = input[i].timestamp;
        } else if (input[i].key == maxKey && input[i].timestamp > maxTimestamp) {
            maxTimestamp = input[i].timestamp;
        }
    }

    // Print the largest integer and its corresponding timestamp
    printf("The largest integer found is %d with timestamp %f\n", maxKey, maxTimestamp);
}

// Define a function to handle memory allocation failures gracefully
