    void* allocateInputData() {
        InputData* input = (InputData*) malloc(sizeof(InputData));
        if (!input) {
            handleMemoryAllocationFailure("Failed to allocate input data");
        } else {
            numAllocationsSucceeded++;
        }
        return input;
    }

    // Define a function to free memory for the input data structure
    void freeInputData(void* input) {
        free(input);
        numAllocationsFailed--;
    }

    // Define a function to handle memory allocation failures gracefully
    void handleMemoryAllocationFailure(const char* message, int numThreads) {
        perror(message);
        exit(EXIT_FAILURE);
    }

    // Read input data from standard input and process it concurrently using multiple threads
