        // Acquire the lock to synchronize access to the input data structure
        pthread_mutex_lock(&mutex);

        // Read a new record from standard input
        int key = generateRandomInt(0, 10000);
        double timestamp = getCurrentTimeInMs();
        InputData* input = (InputData*) malloc(sizeof(InputData));
        if (!input) {
            handleMemoryAllocationFailure("Failed to allocate input data", numThreads);
        } else {
            input->key = key;
            input->timestamp = timestamp;
            numRecordsProcessed++;
            numAllocationsSucceeded++;
        }

        // Release the lock to allow other threads to access the input data structure
        pthread_mutex_unlock(&mutex);

        // Process the input data concurrently using multiple threads
        processAndFindMax(input, 1);
    }

    // Print performance metrics under various load conditions
    printf("Total records processed: %d\n", numRecordsProcessed);
    printf("Memory allocation succeeded: %d times\n", numAllocationsSucceeded);
    printf("Memory allocation failed: %d times\n", numAllocationsFailed);
    totalTime = endTime - startTime;
    avgThroughput = (double)numRecordsProcessed / totalTime * 1000;
    maxThroughput = (double)numRecordsProcessed / totalTime * 1000;
    minThroughput = (double)numRecordsProcessed / totalTime * 1000;
    printf("Average throughput: %f records/second\n", avgThroughput);
    printf("Maximum throughput: %f records/second\n", maxThroughput);
