// Define a struct to represent log entries
struct logEntry {
    char status;
    time_t timestamp;
};

// Global variables for memory management
char* content;
int* lineNumbers;
struct logEntry* entries;
size_t numEntries = 0;
size_t capacity = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Process and execute JavaScript code
void processAndExecuteJavaScript(char* input) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Check if there is enough memory for the new input
    size_t newSize = numEntries + strlen(input) + 1;
    if (newSize > capacity) {
        // Reallocate memory to ensure sufficient space
        char* tmpContent = realloc(content, newSize);
        int* tmpLineNumbers = realloc(lineNumbers, newSize);
        struct logEntry* tmpEntries = realloc(entries, newSize);

        if (!tmpContent || !tmpLineNumbers || !tmpEntries) {
            // Handle memory allocation failure gracefully
            printf("Memory allocation failed!\n");
            pthread_mutex_unlock(&mutex);
            return;
        } else {
            content = tmpContent;
            lineNumbers = tmpLineNumbers;
            entries = tmpEntries;
            capacity = newSize;
        }
    }

    // Parse the input and populate the arrays
    char* curr = input;
    while (*curr) {
        if (numEntries >= capacity) {
            printf("Warning: Input too large!\n");
            break;
        }

        // Check for valid characters in the content array
        if (!isalpha(*curr)) {
            curr++;
            continue;
        }

        // Add a new entry to the arrays
        entries[numEntries].status = *curr;
        entries[numEntries].timestamp = time(NULL);
        lineNumbers[numEntries] = curr - content + 1;
        numEntries++;

        curr++;
    }

    // Unlock the mutex to allow other threads to access the data
    pthread_mutex_unlock(&mutex);
}

// Determine disjoint pairs of elements in the content array
void determineDisjointPairs(char* input) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Initialize a Union-Find data structure for the content array
    struct uf {
        char status;
        int rank;
        int parent;
    };

    size_t numStatuses = sizeof(input) / sizeof(input[0]);
    struct uf* statuses = calloc(numStatuses, sizeof(struct uf));

    // Iterate over the content array and union-find each status
    for (int i = 0; i < numEntries; i++) {
        char currStatus = entries[i].status;

        if (statuses[currStatus].rank == -1) {
            // Initialize a new node in the Union-Find data structure
            statuses[currStatus].status = currStatus;
            statuses[currStatus].parent = i;
            statuses[currStatus].rank = 0;
        } else {
            // Find the representative of the current status's set
            int repIdx = find(statuses, currStatus);

            if (repIdx != i) {
                // Union the two sets
                union(statuses, repIdx, i);
            }
        }
    }

    // Print a summary report of the unique status indicators found
    for (int i = 0; i < numStatuses; i++) {
        if (statuses[i].rank >= 0) {
            printf("Status %c: %d\n", statuses[i].status, statuses[i].rank);
        }
    }

    // Clean up the Union-Find data structure
    free(statuses);

    // Unlock the mutex to allow other threads to access the data
    pthread_mutex_unlock(&mutex);
}
