// Function to parse an RSA private or public key from a configuration file
int RSA_parse_private_key(RSA *rsa, CONF *config, const char *section, const char *name) {
  return RSA_parse_public_key(rsa, config, section, name);
}

int RSA_parse_public_key(RSA *rsa, CONF *config, const char *section, const char *name) {
  BIO *bio;
  X509 *x509;
  if (!(bio = BIO_new_file(name, "r"))) {
    return -1;
  }
  if (!(x509 = PEM_read_bio_X509(bio, NULL, NULL, NULL))) {
    BIO_free(bio);
    return -1;
  }
  RSA *rsa_tmp = X509_get_pubkey(x509);
  if (!RSA_copy(rsa, rsa_tmp)) {
    X509_free(x509);
    BIO_free(bio);
    return -1;
  }
  X509_free(x509);
  BIO_free(bio);
  return 0;
}
```
The `RSA_parse_private_key` function is used to parse an RSA private key from a configuration file, while the `RSA_parse_public_key` function is used to parse an RSA public key. Both of these functions use the `PEM_read_bio_X509` function to read the contents of the specified file and then use the `RSA_get_pubkey` function to extract the RSA private or public key from the X.509 certificate.

The `RSA_copy` function is used to copy an RSA key pair from one RSA structure to another. This function is necessary because the `PEM_read_bio_X509` function returns a pointer to a new RSA structure that needs to be copied to the original RSA structure.

Next, we define a few helper functions that are used later in the code:
