// Function to convert an RSA key pair into a PEM string
int RSA_to_pem(RSA *rsa, unsigned char **pem) {
  BIO *bio;
  if (!(bio = BIO_new(BIO_s_mem()))) {
    return -1;
  }
  if (!PEM_write_bio_RSAPrivateKey(bio, rsa)) {
    BIO_free(bio);
    return -1;
  }
  *pem = (unsigned char *)malloc(sizeof(char) * BIO_get_mem_data(bio));
  if (!*pem) {
    BIO_free(bio);
    return -1;
  }
  memcpy(*pem, bio->ptr, BIO_get_mem_data(bio));
  BIO_free(bio);
  return 0;
}

// Function to convert a PEM string into an RSA key pair
int RSA_from_pem(RSA *rsa, unsigned char **pem) {
  BIO *bio;
  if (!(bio = BIO_new(BIO_s_mem()))) {
    return -1;
  }
  BIO_write(bio, *pem, strlen((char *)*pem));
  RSA *rsa_tmp = PEM_read_bio_RSAPrivateKey(bio, NULL, NULL, NULL);
  if (!RSA_copy(rsa, rsa_tmp)) {
    BIO_free(bio);
    return -1;
  }
  X509_free(x509);
  BIO_free(bio);
  return 0;
}
