#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
#include <mutex>
#include <thread>
#include <condition_variable>

class MonitoringConfiguration {
public:
    // Constructor to initialize the monitoring configuration
    MonitoringConfiguration() : config_(nullptr) {}

    // Destructor to clean up resources
    ~MonitoringConfiguration() {
        if (config_) delete config_;
    }

    // Method to update the monitoring configuration at runtime
    void updateConfig(const std::string& new_config) {
        // Acquire the lock on the mutex
        std::lock_guard<std::mutex> lock(mutex_);

        // Update the monitoring configuration
        config_ = new_config;

        // Signal the condition variable to wake up any waiting threads
        cv_.notify_all();
    }

    // Method to apply changes immediately across all active monitoring agents
    void applyChanges() {
        // Acquire the lock on the mutex
        std::lock_guard<std::mutex> lock(mutex_);

        // Iterate over all active monitoring agents and update their configurations
        for (auto& agent : active_agents_) {
            agent->updateConfig(config_);
        }
    }

private:
    // Mutex to protect the configuration from concurrent access
    std::mutex mutex_;

    // Condition variable to signal changes in the configuration
    std::condition_variable cv_;

    // Vector of active monitoring agents
    std::vector<MonitoringAgent*> active_agents_;

    // Pointer to the current monitoring configuration
    std::string config_;
};

class MonitoringAgent {
public:
    // Constructor to initialize the monitoring agent
    MonitoringAgent(MonitoringConfiguration& config) : config_(config) {}

    // Destructor to clean up resources
    ~MonitoringAgent() = default;

    // Method to update the monitoring configuration at runtime
    void updateConfig(const std::string& new_config) {
        // Acquire the lock on the mutex
        std::lock_guard<std::mutex> lock(mutex_);

        // Update the monitoring agent's configuration
        config_.updateConfig(new_config);
    }

    // Method to apply changes immediately across all active monitoring agents
    void applyChanges() {
        // Acquire the lock on the mutex
        std::lock_guard<std::mutex> lock(mutex_);

        // Update the monitoring agent's configuration
        config_.applyChanges();
    }

private:
    // Mutex to protect the configuration from concurrent access
    std::mutex mutex_;

    // Pointer to the monitoring agent's current configuration
    MonitoringConfiguration& config_;
};
