void printResult(Results results);
void cleanupResources(ResourceTracking *resourceTracking);

// Main function to read file paths from standard input and process each path
int main() {
    // Initialize resource tracking structures
    ResourceTracking resourceTracking = {
        .mutex = PTHREAD_MUTEX_INITIALIZER,
        .memoryUsage = 0,
        .cpuUsage = 0
    };

    // Read file paths from standard input
