    for (int i = 0; i < numFiles; i++) {
        void *data = NULL;
        pthread_join(threads[i], &data);
        parseFileLineByLine((FILE *)data, &results);
        calculateAverage(&results);
    }

    // Print results and cleanup resources
    printResult(results);
    cleanupResources(&resourceTracking);

    return 0;
}

// Process each file path to perform the necessary tasks
void processFileList(char **filePaths, int numFiles) {
    for (int i = 0; i < numFiles; i++) {
        char *filePath = filePaths[i];
        // Validate file path and resolve relative paths based on base directory
        if (!validateFilePath(filePath)) {
            continue;
        }
        // Load file contents into a memory pool for efficient reuse
        FILE *filePtr = fopen(filePath, "r");
        if (filePtr == NULL) {
            perror("fopen");
            continue;
        }
        void *data = loadFileContent(&filePtr);
        parseFileLineByLine((FILE *)data, &results);
        calculateAverage(&results);
        fclose(filePtr);
    }
}

// Validate file path and resolve relative paths based on base directory
int validateFilePath(const char *filePath) {
    if (strlen(filePath) > MAX_FILE_PATH_LENGTH) {
        return 0;
    }
    if (!isAbsolutePath(filePath)) {
        filePath = resolveRelativePath(filePath);
    }
    return 1;
}

// Load file contents into a memory pool for efficient reuse
void* loadFileContent(void *args) {
    FILE *filePtr = NULL;
    char **filePaths = (char **)args;
    int fd = open(filePaths[i], O_RDONLY);
    if (fd == -1) {
        perror("open");
        return NULL;
    }
    filePtr = fdopen(fd, "r");
    if (filePtr == NULL) {
        perror("fdopen");
        close(fd);
        return NULL;
    }
    return filePtr;
}

// Parse the file content line by line and extract integer values
void parseFileLineByLine(FILE *filePtr, void (*callback)(char *line)) {
    char buffer[BUFFER_SIZE];
    while (readLineFromFile(filePtr, &buffer) != -1) {
        // Parse each line and extract integer values
        for (int i = 0; i < strlen(buffer); i++) {
            if (isdigit(buffer[i])) {
                int value = atoi(&buffer[i]);
                // Store integer values in a thread-safe, growable data structure
                callback(&value);
            }
        }
    }
}

// Calculate the average of all extracted integer values and store it along with the total count of integers processed
long calculateTotalCount(void *data) {
    int *values = (int *)data;
    long totalCount = 0;
    for (int i = 0; i < strlen(values); i++) {
        totalCount += values[i];
    }
    return totalCount;
}

// Calculate the average of all extracted integer values and store it along with the total count of integers processed
void calculateAverage(Results *results) {
    results->average = (double)calculateTotalCount(&results->values) / results->totalCount;
}

// Read a line from a file and return the contents in a buffer
int readLineFromFile(FILE *filePtr, char **buffer) {
    if (fgets(*buffer, BUFFER_SIZE, filePtr) == NULL) {
        perror("fgets");
        return -1;
    }
    return 0;
}

// Print the calculated average and total count of integers
void printResult(Results results) {
    printf("Average: %lf\nTotal Count: %ld\n", results.average, results.totalCount);
}

// Cleanup resources and free memory
void cleanupResources(void *args) {
    void **resources = (void **)args;
    for (int i = 0; i < strlen(resources); i++) {
        if (resources[i] != NULL) {
            free(resources[i]);
        }
    }
}
