typedef struct {
    char status;
    time_t timestamp;
} logEntry;

int processAndGenerateReport(const char *inputFile, const char *outputFile) {
    // Open the input file for reading
    int inFd = open(inputFile, O_RDONLY);
    if (inFd == -1) {
        perror("Failed to open input file");
        return EXIT_FAILURE;
    }

    // Open the output file for writing
    int outFd = open(outputFile, O_CREAT | O_TRUNC | O_WRONLY, S_IRUSR | S_IWUSR);
    if (outFd == -1) {
        perror("Failed to create output file");
        return EXIT_FAILURE;
    }

    // Allocate memory for the three arrays
    int contentSize = 1024 * 1024; // Start with a large capacity and resize as needed
    char *content = malloc(contentSize);
    if (content == NULL) {
        perror("Failed to allocate memory for content array");
        close(inFd);
        close(outFd);
        return EXIT_FAILURE;
    }
    int lineNumbersSize = 1024; // Start with a large capacity and resize as needed
    int *lineNumbers = malloc(lineNumbersSize * sizeof(int));
    if (lineNumbers == NULL) {
        perror("Failed to allocate memory for line numbers array");
        free(content);
        close(inFd);
        close(outFd);
        return EXIT_FAILURE;
    }
    logEntry *entries = malloc(1024 * sizeof(logEntry)); // Start with a large capacity and resize as needed
    if (entries == NULL) {
        perror("Failed to allocate memory for entries array");
        free(content);
        free(lineNumbers);
        close(inFd);
        close(outFd);
        return EXIT_FAILURE;
    }

    // Read from the input file and process each line
    char *line = NULL;
    size_t lineLength = 0;
    ssize_t readBytes;
    int entryCount = 0;
    while ((readBytes = getline(&line, &lineLength, inFd)) != -1) {
        // Parse the line and extract the status indicator and timestamp
        char *status = strchr(line, '[');
        if (status == NULL) {
            continue; // Ignore lines without a status indicator
        }
        time_t timestamp = atol(status + 1);

        // Add the entry to the entries array and update the line numbers array
        logEntry entry = { *status, timestamp };
        entries[entryCount] = entry;
        lineNumbers[entryCount]++;
        entryCount++;

        // Check for memory reallocation requirements
        if (entryCount >= lineNumbersSize) {
            int newLineNumbersSize = lineNumbersSize * 2;
            int *newLineNumbers = realloc(lineNumbers, newLineNumbersSize * sizeof(int));
            if (newLineNumbers == NULL) {
                perror("Failed to reallocate memory for line numbers array");
                free(content);
                free(lineNumbers);
                close(inFd);
                close(outFd);
                return EXIT_FAILURE;
            }
            lineNumbers = newLineNumbers;
            lineNumbersSize = newLineNumbersSize;
        }
    }
    free(line);

    // Close the input and output files
    close(inFd);
    close(outFd);

    // Print the summary report
    printf("Summary Report\n");
    for (int i = 0; i < entryCount; i++) {
        logEntry entry = entries[i];
        int count = lineNumbers[i];
        char *status = (entry.status == 'I') ? "Information" : "Warning";
        printf("%s: %d\n", status, count);
    }

    // Clean up memory
    free(content);
    free(lineNumbers);
    free(entries);

    return EXIT_SUCCESS;
}
