    size_t peakMemoryUsage;
};

// Function to process and generate report for multiple input channels
void processAndGenerateReport(int numChannels, struct channel* channels) {
    // Allocate memory for arrays used in the function
    char* content = (char*)malloc(5 * numChannels);
    int* lineNumbers = (int*)malloc(numChannels * sizeof(int));
    struct logEntry* logEntries = (struct logEntry*)malloc(10 * numChannels * sizeof(struct logEntry));
    struct logMetadata metadata;

    // Initialize variables used in the function
    int currentChannel = 0;
    int totalLines = 0;
    double averageTime = 0;
    size_t peakMemory = 0;

    // Loop through each input channel and process its data
    for (int i = 0; i < numChannels; ++i) {
        struct channel* channel = &channels[currentChannel];

        // Allocate memory for the current channel's content array
        char* contentArray = (char*)malloc(channel->bufferSize * sizeof(char));
        if (!contentArray) {
            fprintf(stderr, "Error: unable to allocate memory for content array\n");
            return;
        }

        // Allocate memory for the current channel's line numbers array
        int* lineNumbersArray = (int*)malloc(channel->bufferSize * sizeof(int));
        if (!lineNumbersArray) {
            fprintf(stderr, "Error: unable to allocate memory for line numbers array\n");
            return;
        }

        // Initialize the current channel's content and line numbers arrays
        memset(contentArray, 0, channel->bufferSize * sizeof(char));
        memset(lineNumbersArray, 0, channel->bufferSize * sizeof(int));

        // Loop through each line in the current channel's buffer
        for (int j = 0; j < channel->bufferSize; ++j) {
            struct logEntry entry;
            int ret = sscanf(channel->buffer[j], "%c %lu", &entry.status, &entry.timestamp);
            if (ret != 2) {
                fprintf(stderr, "Error: unable to parse line %d from channel %d\n", j + 1, i + 1);
                continue;
            }

            // Add the entry to the log entries array and update the metadata
            logEntries[currentChannel * 10 + totalLines] = entry;
            ++totalLines;
            averageTime += (double)entry.timestamp;
            peakMemory = MAX(peakMemory, channel->bufferSize);
        }

        // Free the current channel's content and line numbers arrays
        free(contentArray);
        free(lineNumbersArray);

        // Increment the current channel index
        ++currentChannel;
    }

    // Calculate the average processing time and peak memory usage
    metadata.averageProcessingTime = averageTime / totalLines;
    metadata.peakMemoryUsage = peakMemory;

    // Print the log entries and metadata
    for (int i = 0; i < currentChannel * 10; ++i) {
        struct logEntry entry = logEntries[i];
        printf("%c %lu\n", entry.status, entry.timestamp);
    }
    printf("Total lines: %d\n", totalLines);
    printf("Average processing time: %.2f seconds\n", metadata.averageProcessingTime);
    printf("Peak memory usage: %.2f MB\n", metadata.peakMemoryUsage / 1048576.0);

    // Free the arrays allocated in the function
    free(content);
    free(lineNumbers);
    free(logEntries);
}
