        record[i]->timestamp = time(NULL) * 1000; // milliseconds since the epoch
        sprintf(record[i]->description, "Record %d: %d", i + 1, record[i]->value);
    }

    // Keep track of the total number of records processed
    long total_records = max_records;

    // Reallocate memory for the record structures when necessary to avoid fragmentation
    while (total_records > 0) {
        if (total_records < max_records / 2) {
            break;
        }
        for (int i = 0; i < total_records; i++) {
            record[i] = realloc(record[i], sizeof(record_t));
            if (!record[i]) {
                fprintf(stderr, "Failed to reallocate memory for record %d\n", i);
                return;
            }
        }
        total_records /= 2;
    }
}

int main() {
    // Define the maximum number of records to process
    long max_records = 10000000;

    // Allocate memory for the offset, key, and record arrays
    int *offset = malloc(max_records * sizeof(int));
    if (!offset) {
        fprintf(stderr, "Failed to allocate memory for offset array\n");
        return 1;
    }
    int *key = malloc(max_records * sizeof(int));
    if (!key) {
        fprintf(stderr, "Failed to allocate memory for key array\n");
        free(offset);
        return 1;
    }
    record_t **record = malloc(max_records * sizeof(record_t*));
    if (!record) {
        fprintf(stderr, "Failed to allocate memory for record structures\n");
        free(offset);
        free(key);
        return 1;
    }

    // Populate the arrays and manage memory
    populate_arrays(offset, key, record, max_records);

    // Free the allocated memory
    for (int i = 0; i < max_records; i++) {
        free(record[i]);
    }
    free(offset);
    free(key);
    free(record);

    return 0;
}
