// Structure to hold file metadata
typedef struct FileMetadata {
    char *name;
    int size;
    time_t lastModified;
    uid_t ownerId;
    gid_t groupId;
    mode_t permissions;
} FileMetadata;

// Global variable to hold the file metadata structure
FileMetadata *fileMetadata = NULL;

// Mutex to protect access to the file metadata structure
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to create a new file
int createFile(char *name, int size) {
    // Lock the mutex to prevent concurrent modifications to the file metadata structure
    pthread_mutex_lock(&mutex);

    // Check if a file with the same name already exists
    if (fileMetadata != NULL && strcmp(fileMetadata->name, name) == 0) {
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    // Allocate memory for the new file metadata structure
    FileMetadata *newFile = (FileMetadata *)malloc(sizeof(FileMetadata));
    if (newFile == NULL) {
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    // Initialize the fields of the new file metadata structure
    newFile->name = strdup(name);
    newFile->size = size;
    newFile->lastModified = time(NULL);
    newFile->ownerId = getuid();
    newFile->groupId = getgid();
    newFile->permissions = 0644;

    // Add the new file metadata structure to the linked list of files
    if (fileMetadata == NULL) {
        fileMetadata = newFile;
    } else {
        FileMetadata *current = fileMetadata;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newFile;
    }

    // Unlock the mutex and return success
    pthread_mutex_unlock(&mutex);
    return 0;
}

// Function to delete an existing file
int deleteFile(char *name) {
    // Lock the mutex to prevent concurrent modifications to the file metadata structure
    pthread_mutex_lock(&mutex);

    // Check if a file with the given name exists
    FileMetadata *current = fileMetadata;
    while (current != NULL) {
        if (strcmp(current->name, name) == 0) {
            break;
        }
        current = current->next;
    }

    // If a file with the given name does not exist, return error
    if (current == NULL) {
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    // Remove the file metadata structure from the linked list of files
    if (current == fileMetadata) {
        fileMetadata = current->next;
    } else {
        FileMetadata *previous = fileMetadata;
        while (previous->next != current) {
            previous = previous->next;
        }
        previous->next = current->next;
    }

    // Free the memory allocated for the file metadata structure
    free(current->name);
    free(current);

    // Unlock the mutex and return success
    pthread_mutex_unlock(&mutex);
    return 0;
}

// Function to modify an existing file
int modifyFile(char *name, int size) {
    // Lock the mutex to prevent concurrent modifications to the file metadata structure
    pthread_mutex_lock(&mutex);

    // Check if a file with the given name exists
    FileMetadata *current = fileMetadata;
    while (current != NULL) {
        if (strcmp(current->name, name) == 0) {
            break;
        }
        current = current->next;
    }

    // If a file with the given name does not exist, return error
    if (current == NULL) {
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    // Update the size field of the file metadata structure
    current->size = size;

    // Unlock the mutex and return success
    pthread_mutex_unlock(&mutex);
    return 0;
}

// Function to traverse a directory
int traverseDirectory(char *path) {
    // Lock the mutex to prevent concurrent modifications to the file metadata structure
    pthread_mutex_lock(&mutex);

    // Check if a file with the given name exists
    FileMetadata *current = fileMetadata;
    while (current != NULL) {
        if (strcmp(current->name, path) == 0) {
            break;
        }
        current = current->next;
    }

    // If a file with the given name does not exist, return error
    if (current == NULL) {
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    // Traverse the directory and add all files to the linked list of files
    DIR *dir = opendir(path);
    if (dir == NULL) {
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        char fullPath[256];
        snprintf(fullPath, sizeof(fullPath), "%s/%s", path, entry->d_name);

        // If a file with the given name exists, add it to the linked list of files
        if (fileExists(fullPath)) {
            FileMetadata *newFile = (FileMetadata *)malloc(sizeof(FileMetadata));
            if (newFile == NULL) {
                pthread_mutex_unlock(&mutex);
                return -1;
            }

            newFile->name = strdup(fullPath);
            newFile->size = getFileSize(fullPath);
            newFile->lastModified = time(NULL);
            newFile->ownerId = getuid();
            newFile->groupId = getgid();
            newFile->permissions = 0644;

            if (fileMetadata == NULL) {
                fileMetadata = newFile;
            } else {
                FileMetadata *current = fileMetadata;
                while (current->next != NULL) {
                    current = current->next;
                }
                current->next = newFile;
            }
        }
    }

    // Unlock the mutex and return success
    pthread_mutex_unlock(&mutex);
    return 0;
}

// Function to get the size of a file
int getFileSize(char *path) {
    struct stat st;
    if (stat(path, &st) == -1) {
        return -1;
    }
    return st.st_size;
}

// Function to check if a file exists
int fileExists(char *path) {
    struct stat buffer;
    return (stat(path, &buffer) == 0);
}

// Main function
int main() {
    // Initialize the linked list of files
    fileMetadata = NULL;

    // Create a directory and add some files to it
    char *directoryPath = "/tmp/mydir";
    mkdir(directoryPath, 0755);
    createFile("/tmp/mydir/file1.txt");
    createFile("/tmp/mydir/file2.txt");
    modifyFile("/tmp/mydir/file1.txt", 1000);

    // Traverse the directory and print all files
    traverseDirectory(directoryPath);

    return 0;
}
```
