        printf("Error setting TCP_NODELAY option. Exiting.\n");
        return -1;
    }

    // Set up reuse address and port options for faster bind
    int yes = 1;
    if (setsockopt(sockfd, SOL_SOCKET, SO_REUSEADDR, &yes, sizeof(int)) == -1) {
        printf("Error setting SO_REUSEADDR option. Exiting.\n");
        return -1;
