        printf("Error listening on socket. Exiting.\n");
        return -1;
    }

    // Set up data structures for handling multiple requests
    pthread_t *threads = malloc(service_data->config->num_threads * sizeof(pthread_t));
    assert(threads != NULL);

    service_data->netstate->sockfd = sockfd;
    memcpy(&service_data->netstate->address, server_address, sizeof(*server_address));

    return 0;
}

// Function to handle network disruptions and unexpected interruptions
int handleDisruption(service_data_t *service_data) {
    // Check for socket errors and reinitialize if necessary
    int sockfd = service_data->netstate->sockfd;
    int error = getsockopt(sockfd, SOL_SOCKET, SO_ERROR);
    if (error != 0) {
        printf("Error detected on socket. Reinitializing...\n");

        // Close existing socket and recreate a new one
        close(sockfd);
        sockfd = createSocket(service_data->config->server_port, 1);
        if (sockfd == -1) {
            printf("Error creating socket. Exiting.\n");
            return -1;
        }

        // Set up reuse address and port options for faster bind
