            return -1;
        }

        if (setsockopt(sockfd, SOL_SOCKET, SO_REUSEPORT, &yes, sizeof(int)) == -1) {
            printf("Error setting SO_REUSEPORT option. Exiting.\n");
            return -1;
        }

        // Bind new socket to server address
        if (bind(sockfd, (struct sockaddr*)&service_data->netstate->address, sizeof(struct sockaddr_in)) == -1) {
            printf("Error binding socket. Exiting.\n");
            return -1;
        }
    }

    // Check for errors in thread creation and join existing threads if necessary
    pthread_t *threads = service_data->netstate->threads;
    int error = getsockopt(sockfd, SOL_SOCKET, SO_ERROR);
    if (error != 0) {
        printf("Error detected in thread creation. Joining existing threads...\n");

