#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>
#include <sys/time.h>

#define MAX_CONCURRENCY 200
#define MIN_CONCURRENCY 1
#define VERBOSE 3
#define DEFAULT_MODULE "my_module"
#define DEFAULT_LOGFILE "logfile.txt"

typedef struct {
    int id;
    double timestamp;
    int value;
} record;

typedef struct {
    char* name;
    void* (*init_fn)();
    void (*exec_fn)(void*);
    void (*deinit_fn)(void*);
} test_info;

typedef struct {
    int id;
    record* data;
    size_t capacity;
    size_t count;
    bool valid;
} stream_info;

void* manageTestAndDataExecution(test_info* tests, size_t num_tests, stream_info* streams, size_t num_streams) {
    // Dynamic memory allocation for test and data execution.
    void** modules = malloc(num_tests * sizeof(void*));
    if (modules == NULL) {
        fprintf(stderr, "Error: Out of memory!\n");
        return NULL;
    }

    size_t num_concurrency = MIN_CONCURRENCY;
    pthread_mutex_t mutex;
    pthread_cond_t cv;
    bool exit = false;
    bool running = true;
    stream_info* free_streams = NULL;
    size_t num_free_streams = 0;
    size_t num_used_streams = 0;

    // Initialize mutex and condition variable.
    pthread_mutex_init(&mutex, NULL);
    pthread_cond_init(&cv, NULL);

    while (running) {
        if (exit) break;

        // Load module using dynamic linking.
        void* module = dlopen(DEFAULT_MODULE, RTLD_LAZY);
        if (module == NULL) {
            fprintf(stderr, "Error: Failed to load module!\n");
            running = false;
            break;
        }

        // Run tests in parallel.
        for (size_t i = 0; i < num_tests && running; ++i) {
            if (num_concurrency >= MAX_CONCURRENCY) {
                pthread_cond_wait(&cv, &mutex);
            }

            // Initialize test.
            void* test = tests[i].init_fn();
            if (test == NULL) {
                fprintf(stderr, "Error: Failed to initialize test!\n");
                running = false;
                break;
            }

            // Reset mocking library after each test.
            void* mocking_library = dlsym(module, DEFAULT_MODULE);
            if (mocking_library == NULL) {
                fprintf(stderr, "Error: Failed to find mocking library!\n");
                running = false;
                break;
            }
            tests[i].deinit_fn(mocking_library);

            // Execute test.
            tests[i].exec_fn(test);
        }

        // Free resources.
        for (size_t i = 0; i < num_concurrency && running; ++i) {
            void* module = modules[i];
            if (module != NULL) {
                dlclose(module);
                modules[i] = NULL;
            }
        }
        free(modules);
    }

    // Free resources.
    pthread_mutex_destroy(&mutex);
    pthread_cond_destroy(&cv);

    return NULL;
}

void* data_processing_loop(stream_info* stream) {
    while (1) {
        // Check for available data in the buffer.
        if (stream->count < 200) {
            usleep(1000);
            continue;
        }

        // Process data.
        record* data = stream->data;
        size_t count = stream->count;
        for (size_t i = 0; i < count; ++i) {
            printf("Stream %d: Record %d, value=%d, timestamp=%.3f\n", stream->id, i, data[i].value, data[i].timestamp);
        }

        // Free memory and reset buffer.
        free(stream->data);
        stream->data = NULL;
        stream->capacity = 0;
        stream->count = 0;
        stream->valid = false;
    }
}
